// Generated by scripts/build-specs.ts from specs/*.yaml. Do not edit; edit the YAML and run `pnpm specs`.

export const specSources: Record<string, { yaml: string; data: unknown }> = {
  "activation-rate": { yaml: "id: activation-rate\nname: Activation rate\naliases:\n  - Aha moment rate\n  - User activation rate\n  - Signup-to-activation rate\nfamily: activation\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of people who signed up in a week who reached the product's activation milestone within 7 days of signing up.\n  formula: Signups who reached the activation milestone within 7 days ÷ signups, by signup week\n\nevents:\n  - name: signed_up\n    description: An account created, sent by the server when the account exists, not when the form is submitted.\n    also_called: [sign_up, Signed Up, user_signed_up, account_created]\n    properties:\n      - name: method\n        description: How the account was created, such as email, google, sso or invite.\n      - name: plan\n        description: The plan chosen at signup, if any.\n  - name: activated\n    description: The product's key action, the one that best predicts a user is still active weeks later, such as a first report shared or a first project with data.\n    also_called: [Activated, user_activated, aha_moment]\n    properties:\n      - name: milestone\n        description: Which milestone fired, when a product tracks more than one.\n\nnumerator:\n  label: Signups who activated within 7 days\n  aggregate: unique_users\n  event: activated\ndenominator:\n  label: People who signed up\n  aggregate: unique_users\n  event: signed_up\n\nqueries:\n  hogql: |-\n    -- Activation rate: of people whose first signup fell in each week, the share who reached the activation milestone within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(c.converted_people, 0) AS numerator,\n      coalesce(c.people, 0) AS denominator,\n      if(denominator = 0, NULL, numerator / denominator) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(2, 28))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, countIf(converted) AS converted_people, count() AS people\n      FROM (\n        SELECT\n          toMonday(s.start_at) AS week,\n          s.person_id AS person_id,\n          countIf(x.ts >= s.start_at AND x.ts < s.start_at + toIntervalDay(7)) > 0 AS converted\n        FROM (\n          SELECT person_id, min(toTimeZone(timestamp, 'UTC')) AS start_at\n          FROM events\n          WHERE event = 'signed_up'\n            AND person_id IS NOT NULL\n          GROUP BY person_id\n        ) AS s\n        LEFT JOIN (\n          SELECT person_id, toTimeZone(timestamp, 'UTC') AS ts\n          FROM events\n          WHERE event = 'activated'\n            AND timestamp >= now() - toIntervalWeek(29)\n        ) AS x ON x.person_id = s.person_id\n        WHERE toMonday(s.start_at) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(27) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(2)\n        GROUP BY week, person_id\n      )\n      GROUP BY week\n    ) AS c ON c.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Activation rate: of people whose first signup fell in each week, the share who reached the activation milestone within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '27 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '2 weeks',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    starts AS (\n      SELECT user_id, min(occurred_at AT TIME ZONE 'UTC') AS start_at\n      FROM events\n      WHERE event_name = 'signed_up'\n        AND user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    cohort AS (\n      SELECT\n        date_trunc('week', s.start_at)::date AS week,\n        s.user_id,\n        count(x.occurred_at) > 0 AS converted\n      FROM starts AS s\n      LEFT JOIN events AS x\n        ON x.user_id = s.user_id\n       AND x.event_name = 'activated'\n       AND x.occurred_at AT TIME ZONE 'UTC' >= s.start_at\n       AND x.occurred_at AT TIME ZONE 'UTC' < s.start_at + interval '7 days'\n      WHERE s.start_at >= date_trunc('week', now() AT TIME ZONE 'UTC') - interval '27 weeks'\n        AND s.start_at < date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week'\n      GROUP BY 1, 2\n    )\n    SELECT\n      w.week,\n      count(c.user_id) FILTER (WHERE c.converted) AS numerator,\n      count(c.user_id) AS denominator,\n      (count(c.user_id) FILTER (WHERE c.converted))::numeric / nullif(count(c.user_id), 0) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Activation rate: of people whose first signup fell in each week, the share who reached the activation milestone within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 27 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 2 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    starts AS (\n      SELECT user_id, MIN(occurred_at) AS start_at\n      FROM events\n      WHERE event_name = 'signed_up'\n        AND user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    cohort AS (\n      SELECT\n        DATE_TRUNC(DATE(s.start_at), ISOWEEK) AS week,\n        s.user_id,\n        COUNT(x.occurred_at) > 0 AS converted\n      FROM starts AS s\n      LEFT JOIN events AS x\n        ON x.user_id = s.user_id\n       AND x.event_name = 'activated'\n       AND x.occurred_at >= s.start_at\n       AND x.occurred_at < TIMESTAMP_ADD(s.start_at, INTERVAL 7 DAY)\n      WHERE s.start_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 27 WEEK))\n        AND s.start_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK))\n      GROUP BY week, s.user_id\n    )\n    SELECT\n      w.week,\n      COUNTIF(c.converted) AS numerator,\n      COUNT(c.user_id) AS denominator,\n      SAFE_DIVIDE(COUNTIF(c.converted), COUNT(c.user_id)) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Activation rate: of people whose first signup fell in each week, the share who reached the activation milestone within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 - ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    starts AS (\n      SELECT user_id, MIN(occurred_at) AS start_at\n      FROM events\n      WHERE event_name = 'signed_up'\n        AND user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    cohort AS (\n      SELECT\n        DATEADD(day, 1 - DAYOFWEEKISO(s.start_at), s.start_at::date) AS week,\n        s.user_id,\n        COUNT(x.occurred_at) > 0 AS converted\n      FROM starts AS s\n      LEFT JOIN events AS x\n        ON x.user_id = s.user_id\n       AND x.event_name = 'activated'\n       AND x.occurred_at >= s.start_at\n       AND x.occurred_at < DATEADD(day, 7, s.start_at)\n      WHERE s.start_at >= DATEADD(week, -27, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND s.start_at < DATEADD(week, -1, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n      GROUP BY 1, 2\n    )\n    SELECT\n      w.week,\n      COUNT_IF(c.converted) AS numerator,\n      COUNT(c.user_id) AS denominator,\n      COUNT_IF(c.converted)::float / NULLIF(COUNT(c.user_id), 0) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: signups in the cohort\n  typical: 0.34\n\nexample:\n  business: saas\n  level: 0.34\n  volume: 2200\n  trend: 0.06\n\ndrivers:\n  - id: tracking\n    label: Activation event\n    dropped:\n      check: Did the activated event stop firing on one platform, or did its milestone change in a release?\n      yes: Activation falls overnight on one platform or app version while usage of the underlying feature holds.\n    spiked:\n      check: Was the milestone made easier, or is the event now firing on a step everyone passes?\n      yes: Activation jumps overnight with no change in week-4 retention for the same cohorts.\n  - id: calendar\n    label: Holidays\n    feed: holidays\n    dropped:\n      check: Did the cohort's first 7 days include a holiday, when people sign up and then go away?\n      yes: The same cohort weeks last year show the same dip.\n    spiked:\n      check: Is this the first cohort back after a holiday, full of people with a job to get done?\n      yes: The same cohort weeks last year show the same rise.\n  - id: signup-quality\n    label: Who signed up\n    metric: signups\n    breakdown: utm_source\n    dropped:\n      check: Did the cohort include a wave of low-intent, bot or campaign signups?\n      yes: Signups from one source rose that week and activate at a fraction of the usual rate.\n    spiked:\n      check: Did a low-intent source stop, leaving a smaller cohort of committed signups?\n      yes: Signups from one source fell that week while activation from the other sources held.\n  - id: product-errors\n    label: Errors and outages\n    metric: error-rate\n    feed: cloudflare\n    dropped:\n      check: Did errors, an outage or a slow integration hit the setup path during the cohort's first week?\n      yes: Error rate or failed setup steps rose on the days the cohort was trying to get started.\n    spiked:\n      check: Did a fix to a broken setup step ship just before the cohort arrived?\n      yes: The step that failed before now completes, and activation recovers from the release date.\n  - id: onboarding\n    label: Onboarding\n    metric: onboarding-completion-rate\n    dropped:\n      check: Did fewer people finish onboarding, after a step was added or broke?\n      yes: Onboarding completion fell for the same cohorts by about as much.\n    spiked:\n      check: Did a shorter onboarding, a template or a guided setup ship?\n      yes: Onboarding completion rose for the same cohorts, and more of them reached the milestone.\n  - id: plan-split\n    label: Plan and signup method\n    breakdown: plan\n    dropped:\n      check: Is the drop in one plan, signup method or company size?\n      yes: One segment's activation fell while the others held.\n    spiked:\n      check: Is the rise in one plan, signup method or company size?\n      yes: One segment's activation rose, often the one a recent change was aimed at.\n\ndiagnose_order: [tracking, calendar, signup-quality, product-errors, onboarding, plan-split]\n\nrelated: [onboarding-completion-rate, time-to-value, signups, week-1-retention, trial-conversion-rate]\n\nprose:\n  why_it_matters: >-\n    Activation is where most signups are lost: at Copperline two in three never reach the\n    milestone. It is also the earliest number that predicts revenue, because the milestone is\n    chosen as the action that best separates people who stay from people who leave. A fixed 7-day window makes cohorts comparable and lets each week be judged two\n    weeks later, not months. With 2,200 signups in a cohort, a move of under 3 points is still chance.\n  pitfalls:\n    - The milestone defines the metric. Pick the action that best separates users still active a month later from those who left, then don't change it without restarting the series.\n    - Only cohorts whose 7 days have closed are reported, so the latest point is the signups of two weeks ago. Counting the current week makes activation look like it collapsed.\n    - Activations this week ÷ signups this week mixes cohorts and can swing wildly after a big signup week. This spec follows each signup cohort instead.\n    - In team products an invited teammate who never sets anything up is not a failed activation of the account. Track activation per account as well as per person.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"activation-rate","name":"Activation rate","aliases":["Aha moment rate","User activation rate","Signup-to-activation rate"],"family":"activation","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of people who signed up in a week who reached the product's activation milestone within 7 days of signing up.","formula":"Signups who reached the activation milestone within 7 days ÷ signups, by signup week"},"events":[{"name":"signed_up","description":"An account created, sent by the server when the account exists, not when the form is submitted.","also_called":["sign_up","Signed Up","user_signed_up","account_created"],"properties":[{"name":"method","description":"How the account was created, such as email, google, sso or invite."},{"name":"plan","description":"The plan chosen at signup, if any."}]},{"name":"activated","description":"The product's key action, the one that best predicts a user is still active weeks later, such as a first report shared or a first project with data.","also_called":["Activated","user_activated","aha_moment"],"properties":[{"name":"milestone","description":"Which milestone fired, when a product tracks more than one."}]}],"numerator":{"label":"Signups who activated within 7 days","aggregate":"unique_users","event":"activated"},"denominator":{"label":"People who signed up","aggregate":"unique_users","event":"signed_up"},"queries":{"hogql":"-- Activation rate: of people whose first signup fell in each week, the share who reached the activation milestone within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(c.converted_people, 0) AS numerator,\n  coalesce(c.people, 0) AS denominator,\n  if(denominator = 0, NULL, numerator / denominator) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(2, 28))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, countIf(converted) AS converted_people, count() AS people\n  FROM (\n    SELECT\n      toMonday(s.start_at) AS week,\n      s.person_id AS person_id,\n      countIf(x.ts >= s.start_at AND x.ts < s.start_at + toIntervalDay(7)) > 0 AS converted\n    FROM (\n      SELECT person_id, min(toTimeZone(timestamp, 'UTC')) AS start_at\n      FROM events\n      WHERE event = 'signed_up'\n        AND person_id IS NOT NULL\n      GROUP BY person_id\n    ) AS s\n    LEFT JOIN (\n      SELECT person_id, toTimeZone(timestamp, 'UTC') AS ts\n      FROM events\n      WHERE event = 'activated'\n        AND timestamp >= now() - toIntervalWeek(29)\n    ) AS x ON x.person_id = s.person_id\n    WHERE toMonday(s.start_at) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(27) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(2)\n    GROUP BY week, person_id\n  )\n  GROUP BY week\n) AS c ON c.week = w.week\nORDER BY week","postgres":"-- Activation rate: of people whose first signup fell in each week, the share who reached the activation milestone within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '27 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '2 weeks',\n    interval '1 week'\n  ) AS g(week)\n),\nstarts AS (\n  SELECT user_id, min(occurred_at AT TIME ZONE 'UTC') AS start_at\n  FROM events\n  WHERE event_name = 'signed_up'\n    AND user_id IS NOT NULL\n  GROUP BY user_id\n),\ncohort AS (\n  SELECT\n    date_trunc('week', s.start_at)::date AS week,\n    s.user_id,\n    count(x.occurred_at) > 0 AS converted\n  FROM starts AS s\n  LEFT JOIN events AS x\n    ON x.user_id = s.user_id\n   AND x.event_name = 'activated'\n   AND x.occurred_at AT TIME ZONE 'UTC' >= s.start_at\n   AND x.occurred_at AT TIME ZONE 'UTC' < s.start_at + interval '7 days'\n  WHERE s.start_at >= date_trunc('week', now() AT TIME ZONE 'UTC') - interval '27 weeks'\n    AND s.start_at < date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week'\n  GROUP BY 1, 2\n)\nSELECT\n  w.week,\n  count(c.user_id) FILTER (WHERE c.converted) AS numerator,\n  count(c.user_id) AS denominator,\n  (count(c.user_id) FILTER (WHERE c.converted))::numeric / nullif(count(c.user_id), 0) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;","bigquery":"-- Activation rate: of people whose first signup fell in each week, the share who reached the activation milestone within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 27 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 2 WEEK), INTERVAL 1 WEEK)) AS week\n),\nstarts AS (\n  SELECT user_id, MIN(occurred_at) AS start_at\n  FROM events\n  WHERE event_name = 'signed_up'\n    AND user_id IS NOT NULL\n  GROUP BY user_id\n),\ncohort AS (\n  SELECT\n    DATE_TRUNC(DATE(s.start_at), ISOWEEK) AS week,\n    s.user_id,\n    COUNT(x.occurred_at) > 0 AS converted\n  FROM starts AS s\n  LEFT JOIN events AS x\n    ON x.user_id = s.user_id\n   AND x.event_name = 'activated'\n   AND x.occurred_at >= s.start_at\n   AND x.occurred_at < TIMESTAMP_ADD(s.start_at, INTERVAL 7 DAY)\n  WHERE s.start_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 27 WEEK))\n    AND s.start_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK))\n  GROUP BY week, s.user_id\n)\nSELECT\n  w.week,\n  COUNTIF(c.converted) AS numerator,\n  COUNT(c.user_id) AS denominator,\n  SAFE_DIVIDE(COUNTIF(c.converted), COUNT(c.user_id)) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;","snowflake":"-- Activation rate: of people whose first signup fell in each week, the share who reached the activation milestone within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 - ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nstarts AS (\n  SELECT user_id, MIN(occurred_at) AS start_at\n  FROM events\n  WHERE event_name = 'signed_up'\n    AND user_id IS NOT NULL\n  GROUP BY user_id\n),\ncohort AS (\n  SELECT\n    DATEADD(day, 1 - DAYOFWEEKISO(s.start_at), s.start_at::date) AS week,\n    s.user_id,\n    COUNT(x.occurred_at) > 0 AS converted\n  FROM starts AS s\n  LEFT JOIN events AS x\n    ON x.user_id = s.user_id\n   AND x.event_name = 'activated'\n   AND x.occurred_at >= s.start_at\n   AND x.occurred_at < DATEADD(day, 7, s.start_at)\n  WHERE s.start_at >= DATEADD(week, -27, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND s.start_at < DATEADD(week, -1, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n  GROUP BY 1, 2\n)\nSELECT\n  w.week,\n  COUNT_IF(c.converted) AS numerator,\n  COUNT(c.user_id) AS denominator,\n  COUNT_IF(c.converted)::float / NULLIF(COUNT(c.user_id), 0) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"signups in the cohort","typical":0.34},"example":{"business":"saas","level":0.34,"volume":2200,"trend":0.06},"drivers":[{"id":"tracking","label":"Activation event","dropped":{"check":"Did the activated event stop firing on one platform, or did its milestone change in a release?","yes":"Activation falls overnight on one platform or app version while usage of the underlying feature holds."},"spiked":{"check":"Was the milestone made easier, or is the event now firing on a step everyone passes?","yes":"Activation jumps overnight with no change in week-4 retention for the same cohorts."}},{"id":"calendar","label":"Holidays","feed":"holidays","dropped":{"check":"Did the cohort's first 7 days include a holiday, when people sign up and then go away?","yes":"The same cohort weeks last year show the same dip."},"spiked":{"check":"Is this the first cohort back after a holiday, full of people with a job to get done?","yes":"The same cohort weeks last year show the same rise."}},{"id":"signup-quality","label":"Who signed up","metric":"signups","breakdown":"utm_source","dropped":{"check":"Did the cohort include a wave of low-intent, bot or campaign signups?","yes":"Signups from one source rose that week and activate at a fraction of the usual rate."},"spiked":{"check":"Did a low-intent source stop, leaving a smaller cohort of committed signups?","yes":"Signups from one source fell that week while activation from the other sources held."}},{"id":"product-errors","label":"Errors and outages","metric":"error-rate","feed":"cloudflare","dropped":{"check":"Did errors, an outage or a slow integration hit the setup path during the cohort's first week?","yes":"Error rate or failed setup steps rose on the days the cohort was trying to get started."},"spiked":{"check":"Did a fix to a broken setup step ship just before the cohort arrived?","yes":"The step that failed before now completes, and activation recovers from the release date."}},{"id":"onboarding","label":"Onboarding","metric":"onboarding-completion-rate","dropped":{"check":"Did fewer people finish onboarding, after a step was added or broke?","yes":"Onboarding completion fell for the same cohorts by about as much."},"spiked":{"check":"Did a shorter onboarding, a template or a guided setup ship?","yes":"Onboarding completion rose for the same cohorts, and more of them reached the milestone."}},{"id":"plan-split","label":"Plan and signup method","breakdown":"plan","dropped":{"check":"Is the drop in one plan, signup method or company size?","yes":"One segment's activation fell while the others held."},"spiked":{"check":"Is the rise in one plan, signup method or company size?","yes":"One segment's activation rose, often the one a recent change was aimed at."}}],"diagnose_order":["tracking","calendar","signup-quality","product-errors","onboarding","plan-split"],"related":["onboarding-completion-rate","time-to-value","signups","week-1-retention","trial-conversion-rate"],"prose":{"why_it_matters":"Activation is where most signups are lost: at Copperline two in three never reach the milestone. It is also the earliest number that predicts revenue, because the milestone is chosen as the action that best separates people who stay from people who leave. A fixed 7-day window makes cohorts comparable and lets each week be judged two weeks later, not months. With 2,200 signups in a cohort, a move of under 3 points is still chance.","pitfalls":["The milestone defines the metric. Pick the action that best separates users still active a month later from those who left, then don't change it without restarting the series.","Only cohorts whose 7 days have closed are reported, so the latest point is the signups of two weeks ago. Counting the current week makes activation look like it collapsed.","Activations this week ÷ signups this week mixes cohorts and can swing wildly after a big signup week. This spec follows each signup cohort instead.","In team products an invited teammate who never sets anything up is not a failed activation of the account. Track activation per account as well as per person."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "active-customers": { yaml: "id: active-customers\nname: Active customers\naliases:\n  - Active buyers\n  - 12-month active customers\n  - Active customer base\nfamily: customers\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: Customers who placed at least one order in the 52 weeks ending this week.\n  formula: Distinct customers with an order in the trailing 52 weeks, at each week's end\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: customer_id\n        description: The store's customer id, shared by guest and logged-in orders with the same email.\n      - name: is_first_order\n        description: True when the store has no earlier order from this customer, from its own customer records.\n\nnumerator:\n  label: Customers with an order in 52 weeks\n  aggregate: unique_users\n  event: order_completed\n\nqueries:\n  hogql: |-\n    -- Active customers: distinct customers with an order in the 52 weeks ending each week (Monday 00:00 UTC), for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its person_id when that is missing.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT w.week AS week, coalesce(a.customers, 0) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT s.week AS week, uniqExact(o.customer_id) AS customers\n      FROM (\n        SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n      ) AS s\n      CROSS JOIN (\n        SELECT DISTINCT\n          coalesce(properties.customer_id, toString(person_id)) AS customer_id,\n          toMonday(toTimeZone(timestamp, 'UTC')) AS order_week\n        FROM events\n        WHERE event = 'order_completed'\n          AND timestamp >= now() - toIntervalWeek(78)\n          AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(77) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n      ) AS o\n      WHERE o.order_week BETWEEN s.week - toIntervalWeek(51) AND s.week\n      GROUP BY week\n    ) AS a ON a.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Active customers: distinct customers with an order in the 52 weeks ending each week (Monday 00:00 UTC), for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its user_id when that is missing.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    orders AS (\n      SELECT DISTINCT\n        coalesce(properties->>'customer_id', user_id) AS customer_id,\n        date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week\n      FROM events\n      WHERE event_name = 'order_completed'\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '77 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n    )\n    SELECT w.week, count(DISTINCT o.customer_id) AS value\n    FROM weeks AS w\n    LEFT JOIN orders AS o ON o.week BETWEEN w.week - 357 AND w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Active customers: distinct customers with an order in the 52 weeks ending each week (Monday 00:00 UTC), for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its user_id when that is missing.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    orders AS (\n      SELECT DISTINCT\n        COALESCE(JSON_VALUE(properties, '$.customer_id'), user_id) AS customer_id,\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week\n      FROM events\n      WHERE event_name = 'order_completed'\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 77 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    )\n    SELECT w.week, COUNT(DISTINCT o.customer_id) AS value\n    FROM weeks AS w\n    LEFT JOIN orders AS o ON o.week BETWEEN DATE_SUB(w.week, INTERVAL 51 WEEK) AND w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Active customers: distinct customers with an order in the 52 weeks ending each week (Monday 00:00 UTC), for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its user_id when that is missing.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    orders AS (\n      SELECT DISTINCT\n        COALESCE(properties:\"customer_id\"::string, user_id) AS customer_id,\n        DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week\n      FROM events\n      WHERE event_name = 'order_completed'\n        AND occurred_at >= DATEADD(week, -77, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n    )\n    SELECT w.week, COUNT(DISTINCT o.customer_id) AS value\n    FROM weeks AS w\n    LEFT JOIN orders AS o ON o.week BETWEEN DATEADD(week, -51, w.week) AND w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n\nnoise:\n  type: process\n  min_denominator: 100\n  volume_unit: active customers\n  typical: 470000\n\nexample:\n  business: store\n  level: 470000\n  volume: 470000\n  trend: 0.18\n\ndrivers:\n  - id: identity\n    label: Customer records\n    dropped:\n      check: Did a merge or deduplication of customer records collapse several ids into one?\n      yes: The count falls on one day with no change in orders.\n    spiked:\n      check: Did customer matching break, or an import add customers who never ordered here?\n      yes: The count jumps on one day while orders hold, and many of the new customers have a single old order.\n  - id: roll-off\n    label: Customers leaving the window\n    dropped:\n      check: Is a large week from a year ago, such as last Black Friday, leaving the 52-week window?\n      yes: The week 52 weeks back brought far more first-time buyers than usual, and few of them returned.\n    spiked:\n      check: Is an unusually small week from a year ago leaving the window?\n      yes: The week 52 weeks back was quiet, so fewer customers lapsed this week than joined.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Is this the quiet stretch after the holidays, when few new buyers arrive to replace those leaving?\n      yes: The same weeks last year show the same flat or falling count.\n    spiked:\n      check: Is this a sale or holiday week adding many first-time buyers at once?\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: new-customers\n    label: New customers\n    metric: new-customers\n    dropped:\n      check: Did fewer first-time buyers arrive to replace the customers rolling off?\n      yes: New customers have run below the count leaving the window for several weeks.\n    spiked:\n      check: Did a campaign or launch bring a wave of first-time buyers?\n      yes: New customers this week are well above their usual range.\n  - id: win-back\n    label: Lapsed customers returning\n    metric: returning-customers\n    dropped:\n      check: Did win-back emails or offers to lapsed customers stop?\n      yes: Orders from customers whose previous order was over a year ago fall to near zero.\n    spiked:\n      check: Did a win-back campaign bring lapsed customers back?\n      yes: Many of this week's returning customers had last ordered more than 52 weeks ago.\n\ndiagnose_order: [identity, roll-off, calendar, new-customers, win-back]\n\nrelated: [new-customers, returning-customers, repeat-purchase-rate, purchase-frequency, customer-lifetime-value]\n\nprose:\n  why_it_matters: >-\n    Active customers is the size of the living customer base: everyone who bought in the past year\n    and can be sold to again. It is a stock that moves by inflows (new and won-back customers) minus\n    outflows (customers whose last order just turned a year old), so it barely moves week to week and\n    any lasting move matters. Northwind's base of about 470,000 grows only while each week's new and\n    returning buyers outnumber the ones rolling off.\n  pitfalls:\n    - Most of the weekly change is roll-off, the customers who bought exactly 52 weeks ago and not since. A big sale a year ago means a big drop now, and it is known in advance.\n    - Twelve months is the usual window for a store; for a product bought every week, 90 days is fairer. Pick one window and never mix them.\n    - Duplicate customer records inflate the base. Count the store's customer id, not browsers or emails typed differently.\n    - Counting everyone who ever bought includes people who will never buy again and can only grow. An active base must be able to shrink.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"active-customers","name":"Active customers","aliases":["Active buyers","12-month active customers","Active customer base"],"family":"customers","kind":"count","polarity":"up-is-good","definition":{"one_line":"Customers who placed at least one order in the 52 weeks ending this week.","formula":"Distinct customers with an order in the trailing 52 weeks, at each week's end"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"customer_id","description":"The store's customer id, shared by guest and logged-in orders with the same email."},{"name":"is_first_order","description":"True when the store has no earlier order from this customer, from its own customer records."}]}],"numerator":{"label":"Customers with an order in 52 weeks","aggregate":"unique_users","event":"order_completed"},"queries":{"hogql":"-- Active customers: distinct customers with an order in the 52 weeks ending each week (Monday 00:00 UTC), for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its person_id when that is missing.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT w.week AS week, coalesce(a.customers, 0) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT s.week AS week, uniqExact(o.customer_id) AS customers\n  FROM (\n    SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n  ) AS s\n  CROSS JOIN (\n    SELECT DISTINCT\n      coalesce(properties.customer_id, toString(person_id)) AS customer_id,\n      toMonday(toTimeZone(timestamp, 'UTC')) AS order_week\n    FROM events\n    WHERE event = 'order_completed'\n      AND timestamp >= now() - toIntervalWeek(78)\n      AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(77) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n  ) AS o\n  WHERE o.order_week BETWEEN s.week - toIntervalWeek(51) AND s.week\n  GROUP BY week\n) AS a ON a.week = w.week\nORDER BY week","postgres":"-- Active customers: distinct customers with an order in the 52 weeks ending each week (Monday 00:00 UTC), for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its user_id when that is missing.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\norders AS (\n  SELECT DISTINCT\n    coalesce(properties->>'customer_id', user_id) AS customer_id,\n    date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week\n  FROM events\n  WHERE event_name = 'order_completed'\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '77 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n)\nSELECT w.week, count(DISTINCT o.customer_id) AS value\nFROM weeks AS w\nLEFT JOIN orders AS o ON o.week BETWEEN w.week - 357 AND w.week\nGROUP BY w.week\nORDER BY w.week;","bigquery":"-- Active customers: distinct customers with an order in the 52 weeks ending each week (Monday 00:00 UTC), for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its user_id when that is missing.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\norders AS (\n  SELECT DISTINCT\n    COALESCE(JSON_VALUE(properties, '$.customer_id'), user_id) AS customer_id,\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week\n  FROM events\n  WHERE event_name = 'order_completed'\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 77 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n)\nSELECT w.week, COUNT(DISTINCT o.customer_id) AS value\nFROM weeks AS w\nLEFT JOIN orders AS o ON o.week BETWEEN DATE_SUB(w.week, INTERVAL 51 WEEK) AND w.week\nGROUP BY w.week\nORDER BY w.week;","snowflake":"-- Active customers: distinct customers with an order in the 52 weeks ending each week (Monday 00:00 UTC), for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its user_id when that is missing.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\norders AS (\n  SELECT DISTINCT\n    COALESCE(properties:\"customer_id\"::string, user_id) AS customer_id,\n    DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week\n  FROM events\n  WHERE event_name = 'order_completed'\n    AND occurred_at >= DATEADD(week, -77, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n)\nSELECT w.week, COUNT(DISTINCT o.customer_id) AS value\nFROM weeks AS w\nLEFT JOIN orders AS o ON o.week BETWEEN DATEADD(week, -51, w.week) AND w.week\nGROUP BY w.week\nORDER BY w.week;"},"noise":{"type":"process","min_denominator":100,"volume_unit":"active customers","typical":470000},"example":{"business":"store","level":470000,"volume":470000,"trend":0.18},"drivers":[{"id":"identity","label":"Customer records","dropped":{"check":"Did a merge or deduplication of customer records collapse several ids into one?","yes":"The count falls on one day with no change in orders."},"spiked":{"check":"Did customer matching break, or an import add customers who never ordered here?","yes":"The count jumps on one day while orders hold, and many of the new customers have a single old order."}},{"id":"roll-off","label":"Customers leaving the window","dropped":{"check":"Is a large week from a year ago, such as last Black Friday, leaving the 52-week window?","yes":"The week 52 weeks back brought far more first-time buyers than usual, and few of them returned."},"spiked":{"check":"Is an unusually small week from a year ago leaving the window?","yes":"The week 52 weeks back was quiet, so fewer customers lapsed this week than joined."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Is this the quiet stretch after the holidays, when few new buyers arrive to replace those leaving?","yes":"The same weeks last year show the same flat or falling count."},"spiked":{"check":"Is this a sale or holiday week adding many first-time buyers at once?","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"new-customers","label":"New customers","metric":"new-customers","dropped":{"check":"Did fewer first-time buyers arrive to replace the customers rolling off?","yes":"New customers have run below the count leaving the window for several weeks."},"spiked":{"check":"Did a campaign or launch bring a wave of first-time buyers?","yes":"New customers this week are well above their usual range."}},{"id":"win-back","label":"Lapsed customers returning","metric":"returning-customers","dropped":{"check":"Did win-back emails or offers to lapsed customers stop?","yes":"Orders from customers whose previous order was over a year ago fall to near zero."},"spiked":{"check":"Did a win-back campaign bring lapsed customers back?","yes":"Many of this week's returning customers had last ordered more than 52 weeks ago."}}],"diagnose_order":["identity","roll-off","calendar","new-customers","win-back"],"related":["new-customers","returning-customers","repeat-purchase-rate","purchase-frequency","customer-lifetime-value"],"prose":{"why_it_matters":"Active customers is the size of the living customer base: everyone who bought in the past year and can be sold to again. It is a stock that moves by inflows (new and won-back customers) minus outflows (customers whose last order just turned a year old), so it barely moves week to week and any lasting move matters. Northwind's base of about 470,000 grows only while each week's new and returning buyers outnumber the ones rolling off.","pitfalls":["Most of the weekly change is roll-off, the customers who bought exactly 52 weeks ago and not since. A big sale a year ago means a big drop now, and it is known in advance.","Twelve months is the usual window for a store; for a product bought every week, 90 days is fairer. Pick one window and never mix them.","Duplicate customer records inflate the base. Count the store's customer id, not browsers or emails typed differently.","Counting everyone who ever bought includes people who will never buy again and can only grow. An active base must be able to shrink."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "ad-spend": { yaml: "id: ad-spend\nname: Ad spend\naliases:\n  - Marketing spend\n  - Media spend\n  - Paid media spend\n  - Advertising spend\nfamily: acquisition\ncatalog_id: spend\nkind: currency\npolarity: down-is-good\n\ndefinition:\n  one_line: Money spent on paid ads across every synced ad platform in the week, as each platform reports it.\n  formula: Sum of daily spend across ad channels and campaigns\n\nevents:\n  - name: ad_spend\n    description: One row per channel per day, synced from each ad platform's reporting API.\n    also_called: [Ad Spend, ad_performance, campaign_daily_stats]\n    properties:\n      - name: channel\n        description: The platform (google, meta, tiktok, microsoft, pinterest).\n      - name: campaign\n        description: The campaign name or id on that platform.\n      - name: spend\n        description: Amount spent that day, in the store's reporting currency, before agency fees.\n      - name: impressions\n        description: Ads shown that day.\n      - name: clicks\n        description: Link clicks that day, as the platform defines them.\n\nnumerator:\n  label: Ad spend\n  aggregate: sum\n  event: ad_spend\n  property: spend\n\nnoise:\n  type: process\n  min_denominator: 1\n  volume_unit: campaigns with spend a week\n  typical: 20000\n\nexample:\n  business: store\n  level: 300000\n  volume: 60\n  trend: 0.25\n\ndrivers:\n  - id: sync\n    label: Spend sync\n    breakdown: channel\n    dropped:\n      check: Did a platform's sync fail or fall behind, so some days are missing?\n      yes: One channel shows zero or partial spend for some days while its own dashboard shows the usual amount.\n    spiked:\n      check: Is a day synced twice, or a currency recorded as if it were dollars?\n      yes: One channel shows exactly double a day, or a jump that matches an exchange rate.\n  - id: billing\n    label: Billing and account status\n    feed: ad-platforms\n    dropped:\n      check: Was a payment method declined, a spending limit hit, an account suspended or ads disapproved?\n      yes: One platform's spend stops on a single day and its delivery notifications say why.\n    spiked:\n      check: Did a stopped account come back and catch up on delivery?\n      yes: One platform's spend returns after a gap, sometimes above its usual daily rate.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Did a planned push such as Black Friday or a launch end?\n      yes: Budgets return to their usual level the week after the event.\n    spiked:\n      check: Is this a planned sale, holiday or launch week with raised budgets?\n      yes: The same week last year shows the same rise, and the plan says so.\n  - id: campaigns\n    label: Campaigns and budgets\n    breakdown: campaign\n    dropped:\n      check: Did a campaign pause, end, or lose delivery after a learning reset or audience change?\n      yes: One or two campaigns account for most of the fall.\n    spiked:\n      check: Did a new campaign launch, a budget rise, or automated bidding start spending past its usual pace?\n      yes: One or two campaigns account for most of the rise; check whether results rose with them.\n  - id: auction\n    label: Auction prices\n    metric: cpm\n    dropped:\n      check: With budgets uncapped, did cheaper or scarcer impressions lower what the platforms could spend?\n      yes: CPMs fall or delivery is limited while budgets are unchanged.\n    spiked:\n      check: Did auction prices rise, so the same delivery costs more?\n      yes: CPMs rise across platforms in the same week, often in Q4.\n\ndiagnose_order: [sync, billing, calendar, campaigns, auction]\n\nrelated: [mer, ncac, roas, cpm, paid-sessions, blended-cac]\n\nprose:\n  why_it_matters: >-\n    Spend is the one acquisition number the team chooses, so a move that nobody planned is\n    either a broken sync or a campaign spending without supervision. Automated bidding can run\n    well past its usual daily pace after a budget or target change. At $300,000 a week, a sync\n    that misses one day of a platform carrying half the budget understates spend by about 7%,\n    and MER and CAC look about 7% better than they are.\n  pitfalls:\n    - Ad platforms report days in the ad account's time zone. Summed into UTC weeks, a few hours of spend move between weeks, and a time zone change on the account shifts a whole day.\n    - Platforms restate recent spend for invalid clicks and late data. Re-sync the last 7 days every day, or last week's number changes after you report it.\n    - Spend here is media only. Agency fees, creative production and platform tools are real acquisition costs; sync them as their own channel if CAC should include them.\n    - Accounts billed in different currencies need one fixed exchange rate per week, or currency moves look like budget changes.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"ad-spend","name":"Ad spend","aliases":["Marketing spend","Media spend","Paid media spend","Advertising spend"],"family":"acquisition","catalog_id":"spend","kind":"currency","polarity":"down-is-good","definition":{"one_line":"Money spent on paid ads across every synced ad platform in the week, as each platform reports it.","formula":"Sum of daily spend across ad channels and campaigns"},"events":[{"name":"ad_spend","description":"One row per channel per day, synced from each ad platform's reporting API.","also_called":["Ad Spend","ad_performance","campaign_daily_stats"],"properties":[{"name":"channel","description":"The platform (google, meta, tiktok, microsoft, pinterest)."},{"name":"campaign","description":"The campaign name or id on that platform."},{"name":"spend","description":"Amount spent that day, in the store's reporting currency, before agency fees."},{"name":"impressions","description":"Ads shown that day."},{"name":"clicks","description":"Link clicks that day, as the platform defines them."}]}],"numerator":{"label":"Ad spend","aggregate":"sum","event":"ad_spend","property":"spend"},"noise":{"type":"process","min_denominator":1,"volume_unit":"campaigns with spend a week","typical":20000},"example":{"business":"store","level":300000,"volume":60,"trend":0.25},"drivers":[{"id":"sync","label":"Spend sync","breakdown":"channel","dropped":{"check":"Did a platform's sync fail or fall behind, so some days are missing?","yes":"One channel shows zero or partial spend for some days while its own dashboard shows the usual amount."},"spiked":{"check":"Is a day synced twice, or a currency recorded as if it were dollars?","yes":"One channel shows exactly double a day, or a jump that matches an exchange rate."}},{"id":"billing","label":"Billing and account status","feed":"ad-platforms","dropped":{"check":"Was a payment method declined, a spending limit hit, an account suspended or ads disapproved?","yes":"One platform's spend stops on a single day and its delivery notifications say why."},"spiked":{"check":"Did a stopped account come back and catch up on delivery?","yes":"One platform's spend returns after a gap, sometimes above its usual daily rate."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Did a planned push such as Black Friday or a launch end?","yes":"Budgets return to their usual level the week after the event."},"spiked":{"check":"Is this a planned sale, holiday or launch week with raised budgets?","yes":"The same week last year shows the same rise, and the plan says so."}},{"id":"campaigns","label":"Campaigns and budgets","breakdown":"campaign","dropped":{"check":"Did a campaign pause, end, or lose delivery after a learning reset or audience change?","yes":"One or two campaigns account for most of the fall."},"spiked":{"check":"Did a new campaign launch, a budget rise, or automated bidding start spending past its usual pace?","yes":"One or two campaigns account for most of the rise; check whether results rose with them."}},{"id":"auction","label":"Auction prices","metric":"cpm","dropped":{"check":"With budgets uncapped, did cheaper or scarcer impressions lower what the platforms could spend?","yes":"CPMs fall or delivery is limited while budgets are unchanged."},"spiked":{"check":"Did auction prices rise, so the same delivery costs more?","yes":"CPMs rise across platforms in the same week, often in Q4."}}],"diagnose_order":["sync","billing","calendar","campaigns","auction"],"related":["mer","ncac","roas","cpm","paid-sessions","blended-cac"],"prose":{"why_it_matters":"Spend is the one acquisition number the team chooses, so a move that nobody planned is either a broken sync or a campaign spending without supervision. Automated bidding can run well past its usual daily pace after a budget or target change. At $300,000 a week, a sync that misses one day of a platform carrying half the budget understates spend by about 7%, and MER and CAC look about 7% better than they are.","pitfalls":["Ad platforms report days in the ad account's time zone. Summed into UTC weeks, a few hours of spend move between weeks, and a time zone change on the account shifts a whole day.","Platforms restate recent spend for invalid clicks and late data. Re-sync the last 7 days every day, or last week's number changes after you report it.","Spend here is media only. Agency fees, creative production and platform tools are real acquisition costs; sync them as their own channel if CAC should include them.","Accounts billed in different currencies need one fixed exchange rate per week, or currency moves look like budget changes."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "add-to-cart-rate": { yaml: "id: add-to-cart-rate\nname: Add-to-cart rate\naliases:\n  - ATC rate\n  - Add to cart conversion rate\n  - Cart addition rate\nfamily: conversion\ncatalog_id: add_to_cart_rate\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of sessions that viewed a product and added something to the cart, the store's clearest read on product pages.\n  formula: Sessions that added to cart ÷ sessions that viewed a product\n\nevents:\n  - name: product_viewed\n    description: A product detail page rendered with its product, once per view.\n    also_called: [view_item, Product Viewed, product_viewed]\n    properties:\n      - name: product_id\n        description: The product shown.\n  - name: product_added\n    description: An item added to the cart from any button, confirmed by the cart, not the click.\n    also_called: [add_to_cart, Product Added, product_added_to_cart]\n    properties:\n      - name: product_id\n        description: The product added.\n      - name: quantity\n        description: Units added in this action.\n      - name: price\n        description: Unit price at the time of adding, before discounts.\n\nnumerator:\n  label: Sessions that added to cart\n  aggregate: unique_sessions\n  event: product_added\ndenominator:\n  label: Sessions that viewed a product\n  aggregate: unique_sessions\n  event: product_viewed\n\nnoise:\n  type: binomial\n  min_denominator: 300\n  volume_unit: product-viewing sessions a week\n  typical: 0.1\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: store\n  level: 0.108\n  volume: 372000\n  trend: 0.02\n  season: 0.5\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a theme update or a new cart drawer app stop product_added firing on some buttons?\n      yes: Orders and checkout starts hold while recorded adds fall, often from one template or device.\n    spiked:\n      check: Is product_added now firing on quantity changes, on both the drawer and the form, or on page load?\n      yes: Adds per session jump while checkout starts don't follow.\n  - id: price-and-offers\n    label: Prices, sales and the calendar\n    feed: shopping\n    dropped:\n      check: Did a sale end, prices rise, or the free-shipping threshold move this week?\n      yes: Adds fall on the products whose price or offer changed, from the day it changed.\n    spiked:\n      check: Is a sale, a holiday or a new offer lifting adds, and do checkout starts follow?\n      yes: Adds rise on discounted products; if checkout starts don't rise with them, shoppers are comparing, not buying.\n  - id: stock\n    label: Stock and sizes\n    dropped:\n      check: Did best sellers or common sizes go out of stock?\n      yes: Views hold on the top products while their adds fall to near zero.\n    spiked:\n      check: Did a best seller or a missing size come back in stock?\n      yes: Adds jump on the restocked products from the restock day while the rest hold.\n  - id: page-release\n    label: Product page changes\n    dropped:\n      check: Did a release move the add-to-cart button, add a required option, slow the page or change photos or reviews?\n      yes: The drop starts on the release day across every traffic source.\n    spiked:\n      check: Did a release or test ship a clearer buy box, and is it the same for everyone?\n      yes: The rise starts on the release day; confirm the test isn't counting one add twice.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the drop on mobile only, for example a sticky add-to-cart bar that stopped showing?\n      yes: Mobile falls while desktop holds, starting on a release day.\n    spiked:\n      check: Is the rise on one device type only?\n      yes: One device jumps after a release while the other holds.\n  - id: traffic-mix\n    label: Who is browsing\n    breakdown: utm_source\n    dropped:\n      check: Did more browsers arrive from a low-intent source, such as broad paid social or a gift guide?\n      yes: One source gains share of product views and adds far less often than the rest.\n    spiked:\n      check: Did a high-intent source grow, such as email or branded search?\n      yes: One source gains share of product views while each source's own rate holds.\n\ndiagnose_order: [tracking, price-and-offers, stock, page-release, device-split, traffic-mix]\n\nrelated: [product-view-rate, checkout-start-rate, cart-abandonment-rate, conversion-rate, aov]\n\nprose:\n  why_it_matters: >-\n    Add-to-cart rate is where price, photos, reviews and stock show up first, before checkout\n    can help or hurt. On 372,000 product-viewing sessions a week, one point is about 3,700\n    carts, and with a third of carts becoming orders that is roughly 1,200 orders a week.\n  pitfalls:\n    - Shopify's dashboard divides adds by all sessions, not product-viewing sessions, so the same store reads about 6.7% there and 10.8% here. Compare like with like.\n    - Quick-add buttons on collection pages and upsells add to cart without a product view, so heavy quick-add stores see this rate drift up with no change in product pages.\n    - Counting add events instead of sessions rewards quantity buttons; three taps on plus are one shopper. This spec counts sessions.\n    - Adding to cart is cheap intent. A rise that checkout starts don't follow is usually a promotion, a tracking change or price comparison, not better product pages.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"add-to-cart-rate","name":"Add-to-cart rate","aliases":["ATC rate","Add to cart conversion rate","Cart addition rate"],"family":"conversion","catalog_id":"add_to_cart_rate","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of sessions that viewed a product and added something to the cart, the store's clearest read on product pages.","formula":"Sessions that added to cart ÷ sessions that viewed a product"},"events":[{"name":"product_viewed","description":"A product detail page rendered with its product, once per view.","also_called":["view_item","Product Viewed","product_viewed"],"properties":[{"name":"product_id","description":"The product shown."}]},{"name":"product_added","description":"An item added to the cart from any button, confirmed by the cart, not the click.","also_called":["add_to_cart","Product Added","product_added_to_cart"],"properties":[{"name":"product_id","description":"The product added."},{"name":"quantity","description":"Units added in this action."},{"name":"price","description":"Unit price at the time of adding, before discounts."}]}],"numerator":{"label":"Sessions that added to cart","aggregate":"unique_sessions","event":"product_added"},"denominator":{"label":"Sessions that viewed a product","aggregate":"unique_sessions","event":"product_viewed"},"noise":{"type":"binomial","min_denominator":300,"volume_unit":"product-viewing sessions a week","typical":0.1,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"store","level":0.108,"volume":372000,"trend":0.02,"season":0.5},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a theme update or a new cart drawer app stop product_added firing on some buttons?","yes":"Orders and checkout starts hold while recorded adds fall, often from one template or device."},"spiked":{"check":"Is product_added now firing on quantity changes, on both the drawer and the form, or on page load?","yes":"Adds per session jump while checkout starts don't follow."}},{"id":"price-and-offers","label":"Prices, sales and the calendar","feed":"shopping","dropped":{"check":"Did a sale end, prices rise, or the free-shipping threshold move this week?","yes":"Adds fall on the products whose price or offer changed, from the day it changed."},"spiked":{"check":"Is a sale, a holiday or a new offer lifting adds, and do checkout starts follow?","yes":"Adds rise on discounted products; if checkout starts don't rise with them, shoppers are comparing, not buying."}},{"id":"stock","label":"Stock and sizes","dropped":{"check":"Did best sellers or common sizes go out of stock?","yes":"Views hold on the top products while their adds fall to near zero."},"spiked":{"check":"Did a best seller or a missing size come back in stock?","yes":"Adds jump on the restocked products from the restock day while the rest hold."}},{"id":"page-release","label":"Product page changes","dropped":{"check":"Did a release move the add-to-cart button, add a required option, slow the page or change photos or reviews?","yes":"The drop starts on the release day across every traffic source."},"spiked":{"check":"Did a release or test ship a clearer buy box, and is it the same for everyone?","yes":"The rise starts on the release day; confirm the test isn't counting one add twice."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the drop on mobile only, for example a sticky add-to-cart bar that stopped showing?","yes":"Mobile falls while desktop holds, starting on a release day."},"spiked":{"check":"Is the rise on one device type only?","yes":"One device jumps after a release while the other holds."}},{"id":"traffic-mix","label":"Who is browsing","breakdown":"utm_source","dropped":{"check":"Did more browsers arrive from a low-intent source, such as broad paid social or a gift guide?","yes":"One source gains share of product views and adds far less often than the rest."},"spiked":{"check":"Did a high-intent source grow, such as email or branded search?","yes":"One source gains share of product views while each source's own rate holds."}}],"diagnose_order":["tracking","price-and-offers","stock","page-release","device-split","traffic-mix"],"related":["product-view-rate","checkout-start-rate","cart-abandonment-rate","conversion-rate","aov"],"prose":{"why_it_matters":"Add-to-cart rate is where price, photos, reviews and stock show up first, before checkout can help or hurt. On 372,000 product-viewing sessions a week, one point is about 3,700 carts, and with a third of carts becoming orders that is roughly 1,200 orders a week.","pitfalls":["Shopify's dashboard divides adds by all sessions, not product-viewing sessions, so the same store reads about 6.7% there and 10.8% here. Compare like with like.","Quick-add buttons on collection pages and upsells add to cart without a product view, so heavy quick-add stores see this rate drift up with no change in product pages.","Counting add events instead of sessions rewards quantity buttons; three taps on plus are one shopper. This spec counts sessions.","Adding to cart is cheap intent. A rise that checkout starts don't follow is usually a promotion, a tracking change or price comparison, not better product pages."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "aov": { yaml: "id: aov\nname: Average order value\naliases:\n  - Average order value\n  - Average basket value\n  - Average transaction value\n  - Average purchase revenue\nfamily: revenue\ncatalog_id: aov\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: The average paid order's value after discounts, before tax, shipping and refunds.\n  formula: Order revenue after discounts ÷ paid orders\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n      - name: is_first_order\n        description: True when it is the customer's first ever paid order.\n\nnumerator:\n  label: Order revenue\n  aggregate: sum\n  event: order_completed\n  property: total\ndenominator:\n  label: Paid orders\n  aggregate: count\n  event: order_completed\n\nnoise:\n  type: mean\n  cv: 0.9\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 90\n\nexample:\n  business: store\n  level: 97\n  volume: 13300\n  trend: 0.1\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did $0 orders, such as replacements, gifts or influencer seeding, start recording as paid orders?\n      yes: A cluster of orders at or near $0 appears from one day.\n    spiked:\n      check: Did order totals start including tax or shipping, or did one currency arrive unconverted?\n      yes: Totals jump for one country or channel from one day while subtotals hold.\n  - id: calendar\n    label: Shopping calendar\n    feed: shopping\n    dropped:\n      check: Is a sale running, when discounts and cheaper gift items pull the average down?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this a gifting week, or did a sale that lowered the average just end?\n      yes: The same week last year shows the same rise once aligned on the event.\n  - id: discounts\n    label: Discounts\n    metric: discount-rate\n    dropped:\n      check: Did the share of sales given away in discounts rise?\n      yes: Discount rate rises while items per order hold, and the average falls by about the extra discount.\n    spiked:\n      check: Did a promotion end, so orders carry less discount?\n      yes: Discount rate falls by about as much as the average rises.\n  - id: basket-size\n    label: Items per order\n    metric: units-per-order\n    dropped:\n      check: Did orders carry fewer items, after a bundle ended or the free-shipping threshold fell?\n      yes: Units per order fall while the price per unit holds.\n    spiked:\n      check: Did a bundle, a multi-buy offer or a higher free-shipping threshold add items to orders?\n      yes: Units per order rise from the day the offer started.\n  - id: price-and-mix\n    label: Prices and product mix\n    dropped:\n      check: Did sales shift toward cheaper products, such as a low-priced launch or an entry product in ads?\n      yes: The price per unit falls while items per order hold.\n    spiked:\n      check: Did prices rise, a premium product launch, or did a handful of very large orders land?\n      yes: The price per unit rises, or the ten largest orders explain most of the jump.\n  - id: first-orders\n    label: First vs repeat orders\n    breakdown: is_first_order\n    dropped:\n      check: Did first orders, which are usually smaller, take a larger share of orders?\n      yes: Each group's average holds and only the mix moved.\n    spiked:\n      check: Did repeat customers take a larger share, or did first orders grow in size?\n      yes: The mix moved toward repeat orders, or first orders' average rose on its own.\n\ndiagnose_order: [tracking, calendar, discounts, basket-size, price-and-mix, first-orders]\n\nrelated: [net-revenue, orders, units-per-order, discount-rate, revenue-per-session]\n\nprose:\n  why_it_matters: >-\n    Revenue is orders × AOV, so AOV separates \"fewer people bought\" from \"people bought less\".\n    It moves with prices, discounts, basket size and who is buying, not with traffic. At\n    Northwind, $1 of AOV across 13,300 orders is $13,300 a week, the same revenue as about 137\n    more orders.\n  pitfalls:\n    - Averages follow large orders. A few wholesale or bulk orders can lift a small store's AOV 10% in a week; check the median order beside it.\n    - Dividing net revenue after refunds by orders makes AOV move with refunds on earlier weeks' orders. This spec divides the week's own order revenue by its order count and reads refunds in refund rate.\n    - Including tax and shipping makes AOV move with tax rules, destinations and carrier prices. Keep both out.\n    - A promotion that lowers AOV can still raise revenue. Judge AOV with orders beside it, never alone.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"aov","name":"Average order value","aliases":["Average order value","Average basket value","Average transaction value","Average purchase revenue"],"family":"revenue","catalog_id":"aov","kind":"currency","polarity":"up-is-good","definition":{"one_line":"The average paid order's value after discounts, before tax, shipping and refunds.","formula":"Order revenue after discounts ÷ paid orders"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."},{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."},{"name":"is_first_order","description":"True when it is the customer's first ever paid order."}]}],"numerator":{"label":"Order revenue","aggregate":"sum","event":"order_completed","property":"total"},"denominator":{"label":"Paid orders","aggregate":"count","event":"order_completed"},"noise":{"type":"mean","cv":0.9,"min_denominator":50,"volume_unit":"orders a week","typical":90},"example":{"business":"store","level":97,"volume":13300,"trend":0.1,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did $0 orders, such as replacements, gifts or influencer seeding, start recording as paid orders?","yes":"A cluster of orders at or near $0 appears from one day."},"spiked":{"check":"Did order totals start including tax or shipping, or did one currency arrive unconverted?","yes":"Totals jump for one country or channel from one day while subtotals hold."}},{"id":"calendar","label":"Shopping calendar","feed":"shopping","dropped":{"check":"Is a sale running, when discounts and cheaper gift items pull the average down?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this a gifting week, or did a sale that lowered the average just end?","yes":"The same week last year shows the same rise once aligned on the event."}},{"id":"discounts","label":"Discounts","metric":"discount-rate","dropped":{"check":"Did the share of sales given away in discounts rise?","yes":"Discount rate rises while items per order hold, and the average falls by about the extra discount."},"spiked":{"check":"Did a promotion end, so orders carry less discount?","yes":"Discount rate falls by about as much as the average rises."}},{"id":"basket-size","label":"Items per order","metric":"units-per-order","dropped":{"check":"Did orders carry fewer items, after a bundle ended or the free-shipping threshold fell?","yes":"Units per order fall while the price per unit holds."},"spiked":{"check":"Did a bundle, a multi-buy offer or a higher free-shipping threshold add items to orders?","yes":"Units per order rise from the day the offer started."}},{"id":"price-and-mix","label":"Prices and product mix","dropped":{"check":"Did sales shift toward cheaper products, such as a low-priced launch or an entry product in ads?","yes":"The price per unit falls while items per order hold."},"spiked":{"check":"Did prices rise, a premium product launch, or did a handful of very large orders land?","yes":"The price per unit rises, or the ten largest orders explain most of the jump."}},{"id":"first-orders","label":"First vs repeat orders","breakdown":"is_first_order","dropped":{"check":"Did first orders, which are usually smaller, take a larger share of orders?","yes":"Each group's average holds and only the mix moved."},"spiked":{"check":"Did repeat customers take a larger share, or did first orders grow in size?","yes":"The mix moved toward repeat orders, or first orders' average rose on its own."}}],"diagnose_order":["tracking","calendar","discounts","basket-size","price-and-mix","first-orders"],"related":["net-revenue","orders","units-per-order","discount-rate","revenue-per-session"],"prose":{"why_it_matters":"Revenue is orders × AOV, so AOV separates \"fewer people bought\" from \"people bought less\". It moves with prices, discounts, basket size and who is buying, not with traffic. At Northwind, $1 of AOV across 13,300 orders is $13,300 a week, the same revenue as about 137 more orders.","pitfalls":["Averages follow large orders. A few wholesale or bulk orders can lift a small store's AOV 10% in a week; check the median order beside it.","Dividing net revenue after refunds by orders makes AOV move with refunds on earlier weeks' orders. This spec divides the week's own order revenue by its order count and reads refunds in refund rate.","Including tax and shipping makes AOV move with tax rules, destinations and carrier prices. Keep both out.","A promotion that lowers AOV can still raise revenue. Judge AOV with orders beside it, never alone."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "arpa": { yaml: "id: arpa\nname: Average revenue per account\naliases:\n  - ARPA\n  - Average revenue per customer\n  - ARPC\n  - Average MRR per customer\nfamily: subscription\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: The average monthly recurring revenue per paying customer account at the end of the week.\n  formula: MRR at week end ÷ customer accounts with at least one paying subscription, measured Sunday 23:59 UTC\n\nevents:\n  - name: subscription_updated\n    description: Any change to a subscription's plan, quantity, discount or status, with its new monthly amount.\n    also_called: [customer.subscription.updated, Subscription Updated, subscription_changed]\n    properties:\n      - name: subscription_id\n        description: The billing system's subscription id.\n      - name: mrr\n        description: The subscription's monthly amount after the change, after discounts, before tax.\n      - name: status\n        description: active, trialing, past_due or canceled.\n\nnumerator:\n  label: MRR at week end\n  aggregate: sum\n  event: subscription_updated\n  property: mrr\n\nqueries:\n  hogql: |-\n    -- ARPA at the end of each week: MRR ÷ customers with at least one paying (active or past-due) subscription, each subscription at its latest subscription_updated before Monday 00:00 UTC. A customer is the person on the subscription. Last 26 complete weeks, oldest first.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(a.mrr, 0) AS numerator,\n      coalesce(a.accounts, 0) AS denominator,\n      if(denominator = 0, NULL, numerator / denominator) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, sum(account_mrr) AS mrr, count() AS accounts\n      FROM (\n        SELECT week, tupleElement(latest, 1) AS account, sum(tupleElement(latest, 2)) AS account_mrr\n        FROM (\n          SELECT s.week AS week, u.subscription_id AS subscription_id, argMax(tuple(u.person, u.mrr, u.status), u.ts) AS latest\n          FROM (\n            SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n          ) AS s\n          CROSS JOIN (\n            SELECT\n              toString(properties.subscription_id) AS subscription_id,\n              person_id AS person,\n              toTimeZone(timestamp, 'UTC') AS ts,\n              toFloat(properties.mrr) AS mrr,\n              toString(properties.status) AS status\n            FROM events\n            WHERE event = 'subscription_updated'\n              AND properties.subscription_id IS NOT NULL\n              AND toMonday(toTimeZone(timestamp, 'UTC')) < toMonday(toTimeZone(now(), 'UTC'))\n          ) AS u\n          WHERE toMonday(u.ts) <= s.week\n          GROUP BY week, subscription_id\n        )\n        WHERE tupleElement(latest, 3) IN ('active', 'past_due')\n        GROUP BY week, account\n      )\n      WHERE account_mrr > 0\n      GROUP BY week\n    ) AS a ON a.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- ARPA at the end of each week: MRR ÷ customers with at least one paying (active or past-due) subscription, each subscription at its latest subscription_updated before Monday 00:00 UTC. A customer is the user_id on the subscription. Last 26 complete weeks, oldest first.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week, g.week + interval '1 week' AS week_end\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    updates AS (\n      SELECT\n        properties->>'subscription_id' AS subscription_id,\n        user_id AS customer,\n        occurred_at AT TIME ZONE 'UTC' AS ts,\n        CASE WHEN properties->>'mrr' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr')::numeric END AS mrr,\n        properties->>'status' AS status\n      FROM events\n      WHERE event_name = 'subscription_updated'\n        AND properties->>'subscription_id' IS NOT NULL\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n    ),\n    latest AS (\n      SELECT DISTINCT ON (w.week, u.subscription_id) w.week, u.customer, u.mrr, u.status\n      FROM weeks AS w\n      JOIN updates AS u ON u.ts < w.week_end\n      ORDER BY w.week, u.subscription_id, u.ts DESC\n    ),\n    accounts AS (\n      SELECT week, customer, sum(mrr) AS mrr\n      FROM latest\n      WHERE status IN ('active', 'past_due')\n      GROUP BY week, customer\n    ),\n    weekly AS (\n      SELECT week, sum(mrr) AS mrr, count(*) AS accounts\n      FROM accounts\n      WHERE mrr > 0\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      coalesce(a.mrr, 0) AS numerator,\n      coalesce(a.accounts, 0) AS denominator,\n      a.mrr / nullif(a.accounts, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS a ON a.week = w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- ARPA at the end of each week: MRR ÷ customers with at least one paying (active or past-due) subscription, each subscription at its latest subscription_updated before Monday 00:00 UTC. A customer is the user_id on the subscription. Last 26 complete weeks, oldest first.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    updates AS (\n      SELECT\n        JSON_VALUE(properties, '$.subscription_id') AS subscription_id,\n        user_id AS customer,\n        occurred_at,\n        SAFE_CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64) AS mrr,\n        JSON_VALUE(properties, '$.status') AS status\n      FROM events\n      WHERE event_name = 'subscription_updated'\n        AND JSON_VALUE(properties, '$.subscription_id') IS NOT NULL\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    ),\n    latest AS (\n      SELECT w.week, u.customer, u.mrr, u.status\n      FROM weeks AS w\n      CROSS JOIN updates AS u\n      WHERE u.occurred_at < TIMESTAMP(DATE_ADD(w.week, INTERVAL 1 WEEK))\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY w.week, u.subscription_id ORDER BY u.occurred_at DESC) = 1\n    ),\n    accounts AS (\n      SELECT week, customer, SUM(mrr) AS mrr\n      FROM latest\n      WHERE status IN ('active', 'past_due')\n      GROUP BY week, customer\n    ),\n    weekly AS (\n      SELECT week, SUM(mrr) AS mrr, COUNT(*) AS accounts\n      FROM accounts\n      WHERE mrr > 0\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      COALESCE(a.mrr, 0) AS numerator,\n      COALESCE(a.accounts, 0) AS denominator,\n      SAFE_DIVIDE(a.mrr, a.accounts) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS a ON a.week = w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- ARPA at the end of each week: MRR ÷ customers with at least one paying (active or past-due) subscription, each subscription at its latest subscription_updated before Monday 00:00 UTC. A customer is the user_id on the subscription. Last 26 complete weeks, oldest first.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    updates AS (\n      SELECT\n        properties:\"subscription_id\"::string AS subscription_id,\n        user_id AS customer,\n        occurred_at,\n        TRY_TO_DOUBLE(properties:\"mrr\"::string) AS mrr,\n        properties:\"status\"::string AS status\n      FROM events\n      WHERE event_name = 'subscription_updated'\n        AND properties:\"subscription_id\"::string IS NOT NULL\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n    ),\n    latest AS (\n      SELECT w.week, u.customer, u.mrr, u.status\n      FROM weeks AS w\n      JOIN updates AS u ON u.occurred_at < DATEADD(week, 1, w.week)\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY w.week, u.subscription_id ORDER BY u.occurred_at DESC) = 1\n    ),\n    accounts AS (\n      SELECT week, customer, SUM(mrr) AS mrr\n      FROM latest\n      WHERE status IN ('active', 'past_due')\n      GROUP BY week, customer\n    ),\n    weekly AS (\n      SELECT week, SUM(mrr) AS mrr, COUNT(*) AS accounts\n      FROM accounts\n      WHERE mrr > 0\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      COALESCE(a.mrr, 0) AS numerator,\n      COALESCE(a.accounts, 0) AS denominator,\n      a.mrr / NULLIF(a.accounts, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS a ON a.week = w.week\n    ORDER BY w.week;\n\nnoise:\n  type: process\n  min_denominator: 50\n  volume_unit: paying accounts\n  typical: 126\n\nexample:\n  business: saas\n  level: 126\n  volume: 1850\n  trend: 0.14\n\ndrivers:\n  - id: account-counting\n    label: Account counting\n    dropped:\n      check: Did zero-amount, test or duplicate accounts start being counted?\n      yes: The account count jumps with no matching rise in MRR, usually free plans now synced as subscriptions or one customer split across several ids.\n    spiked:\n      check: Did accounts merge or drop out of the count, for example after a customer-id migration?\n      yes: The account count falls with no matching cancellations.\n  - id: pricing\n    label: Pricing and discounts\n    dropped:\n      check: Did a discount, coupon campaign or cheaper plan go live?\n      yes: New and renewing accounts land at lower prices from the launch date.\n    spiked:\n      check: Did a price increase or coupon expiry take effect?\n      yes: Many accounts change amount on the same day with no plan change. It won't repeat.\n  - id: plan-mix\n    label: Plan mix\n    breakdown: plan\n    dropped:\n      check: Has the mix of accounts shifted toward cheaper plans?\n      yes: The share of accounts on the entry plan grows while each plan's own average holds.\n    spiked:\n      check: Has the mix shifted toward larger plans?\n      yes: The share of accounts on the top plans grows while each plan's own average holds.\n  - id: churn-mix\n    label: Who churned\n    metric: logo-churn-rate\n    dropped:\n      check: Did larger accounts churn or downgrade?\n      yes: The MRR lost per departing account is well above ARPA this week.\n    spiked:\n      check: Did many small accounts churn, lifting the average without anyone paying more?\n      yes: Logo churn rises while MRR barely moves. ARPA rose for a bad reason.\n  - id: new-mix\n    label: Who started\n    metric: new-mrr\n    dropped:\n      check: Are new customers starting on smaller plans than the base pays?\n      yes: New MRR per new account is well below ARPA, often after a cheaper plan or a self-serve launch.\n    spiked:\n      check: Did a few large new accounts, or a move upmarket, lift the average?\n      yes: New MRR per new account is well above ARPA; one or two deals explain most of it.\n  - id: expansion\n    label: Expansion\n    metric: expansion-mrr\n    dropped:\n      check: Did upgrades and seat additions slow while accounts kept growing?\n      yes: Expansion MRR falls below its usual range for several weeks.\n    spiked:\n      check: Did upgrades or a usage limit raise what existing accounts pay?\n      yes: Expansion MRR jumps in the weeks ARPA rose.\n\ndiagnose_order: [account-counting, pricing, plan-mix, churn-mix, new-mix, expansion]\n\nrelated: [mrr, new-mrr, expansion-mrr, logo-churn-rate, customer-lifetime-value]\n\nprose:\n  why_it_matters: >-\n    ARPA says what a typical customer is worth each month, and it moves with pricing, packaging\n    and who you sell to rather than with how many you sell. Rising ARPA with a flat customer\n    count is expansion working; rising ARPA because small customers left is churn in disguise.\n    At $126 a month, a $10 move that holds for several weeks is a change in pricing or in who buys.\n  pitfalls:\n    - Divide by paying accounts, not users or seats. A customer with ten seats is one account; counting seats turns ARPA into price per seat.\n    - Free plans and zero-amount subscriptions in the count pull ARPA down every time sign-ups rise. Count only accounts paying more than zero.\n    - A customer with several subscriptions is still one account. Counting subscriptions understates ARPA for exactly the customers who buy the most.\n    - ARPA rising because small customers churned looks like good news on its own. Read it next to logo churn.\n    - When a few enterprise accounts are a large share of MRR, the mean hides the typical customer. Look at the median too.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"arpa","name":"Average revenue per account","aliases":["ARPA","Average revenue per customer","ARPC","Average MRR per customer"],"family":"subscription","kind":"currency","polarity":"up-is-good","definition":{"one_line":"The average monthly recurring revenue per paying customer account at the end of the week.","formula":"MRR at week end ÷ customer accounts with at least one paying subscription, measured Sunday 23:59 UTC"},"events":[{"name":"subscription_updated","description":"Any change to a subscription's plan, quantity, discount or status, with its new monthly amount.","also_called":["customer.subscription.updated","Subscription Updated","subscription_changed"],"properties":[{"name":"subscription_id","description":"The billing system's subscription id."},{"name":"mrr","description":"The subscription's monthly amount after the change, after discounts, before tax."},{"name":"status","description":"active, trialing, past_due or canceled."}]}],"numerator":{"label":"MRR at week end","aggregate":"sum","event":"subscription_updated","property":"mrr"},"queries":{"hogql":"-- ARPA at the end of each week: MRR ÷ customers with at least one paying (active or past-due) subscription, each subscription at its latest subscription_updated before Monday 00:00 UTC. A customer is the person on the subscription. Last 26 complete weeks, oldest first.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(a.mrr, 0) AS numerator,\n  coalesce(a.accounts, 0) AS denominator,\n  if(denominator = 0, NULL, numerator / denominator) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, sum(account_mrr) AS mrr, count() AS accounts\n  FROM (\n    SELECT week, tupleElement(latest, 1) AS account, sum(tupleElement(latest, 2)) AS account_mrr\n    FROM (\n      SELECT s.week AS week, u.subscription_id AS subscription_id, argMax(tuple(u.person, u.mrr, u.status), u.ts) AS latest\n      FROM (\n        SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n      ) AS s\n      CROSS JOIN (\n        SELECT\n          toString(properties.subscription_id) AS subscription_id,\n          person_id AS person,\n          toTimeZone(timestamp, 'UTC') AS ts,\n          toFloat(properties.mrr) AS mrr,\n          toString(properties.status) AS status\n        FROM events\n        WHERE event = 'subscription_updated'\n          AND properties.subscription_id IS NOT NULL\n          AND toMonday(toTimeZone(timestamp, 'UTC')) < toMonday(toTimeZone(now(), 'UTC'))\n      ) AS u\n      WHERE toMonday(u.ts) <= s.week\n      GROUP BY week, subscription_id\n    )\n    WHERE tupleElement(latest, 3) IN ('active', 'past_due')\n    GROUP BY week, account\n  )\n  WHERE account_mrr > 0\n  GROUP BY week\n) AS a ON a.week = w.week\nORDER BY week","postgres":"-- ARPA at the end of each week: MRR ÷ customers with at least one paying (active or past-due) subscription, each subscription at its latest subscription_updated before Monday 00:00 UTC. A customer is the user_id on the subscription. Last 26 complete weeks, oldest first.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week, g.week + interval '1 week' AS week_end\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nupdates AS (\n  SELECT\n    properties->>'subscription_id' AS subscription_id,\n    user_id AS customer,\n    occurred_at AT TIME ZONE 'UTC' AS ts,\n    CASE WHEN properties->>'mrr' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr')::numeric END AS mrr,\n    properties->>'status' AS status\n  FROM events\n  WHERE event_name = 'subscription_updated'\n    AND properties->>'subscription_id' IS NOT NULL\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n),\nlatest AS (\n  SELECT DISTINCT ON (w.week, u.subscription_id) w.week, u.customer, u.mrr, u.status\n  FROM weeks AS w\n  JOIN updates AS u ON u.ts < w.week_end\n  ORDER BY w.week, u.subscription_id, u.ts DESC\n),\naccounts AS (\n  SELECT week, customer, sum(mrr) AS mrr\n  FROM latest\n  WHERE status IN ('active', 'past_due')\n  GROUP BY week, customer\n),\nweekly AS (\n  SELECT week, sum(mrr) AS mrr, count(*) AS accounts\n  FROM accounts\n  WHERE mrr > 0\n  GROUP BY week\n)\nSELECT\n  w.week,\n  coalesce(a.mrr, 0) AS numerator,\n  coalesce(a.accounts, 0) AS denominator,\n  a.mrr / nullif(a.accounts, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS a ON a.week = w.week\nORDER BY w.week;","bigquery":"-- ARPA at the end of each week: MRR ÷ customers with at least one paying (active or past-due) subscription, each subscription at its latest subscription_updated before Monday 00:00 UTC. A customer is the user_id on the subscription. Last 26 complete weeks, oldest first.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nupdates AS (\n  SELECT\n    JSON_VALUE(properties, '$.subscription_id') AS subscription_id,\n    user_id AS customer,\n    occurred_at,\n    SAFE_CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64) AS mrr,\n    JSON_VALUE(properties, '$.status') AS status\n  FROM events\n  WHERE event_name = 'subscription_updated'\n    AND JSON_VALUE(properties, '$.subscription_id') IS NOT NULL\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n),\nlatest AS (\n  SELECT w.week, u.customer, u.mrr, u.status\n  FROM weeks AS w\n  CROSS JOIN updates AS u\n  WHERE u.occurred_at < TIMESTAMP(DATE_ADD(w.week, INTERVAL 1 WEEK))\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY w.week, u.subscription_id ORDER BY u.occurred_at DESC) = 1\n),\naccounts AS (\n  SELECT week, customer, SUM(mrr) AS mrr\n  FROM latest\n  WHERE status IN ('active', 'past_due')\n  GROUP BY week, customer\n),\nweekly AS (\n  SELECT week, SUM(mrr) AS mrr, COUNT(*) AS accounts\n  FROM accounts\n  WHERE mrr > 0\n  GROUP BY week\n)\nSELECT\n  w.week,\n  COALESCE(a.mrr, 0) AS numerator,\n  COALESCE(a.accounts, 0) AS denominator,\n  SAFE_DIVIDE(a.mrr, a.accounts) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS a ON a.week = w.week\nORDER BY w.week;","snowflake":"-- ARPA at the end of each week: MRR ÷ customers with at least one paying (active or past-due) subscription, each subscription at its latest subscription_updated before Monday 00:00 UTC. A customer is the user_id on the subscription. Last 26 complete weeks, oldest first.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nupdates AS (\n  SELECT\n    properties:\"subscription_id\"::string AS subscription_id,\n    user_id AS customer,\n    occurred_at,\n    TRY_TO_DOUBLE(properties:\"mrr\"::string) AS mrr,\n    properties:\"status\"::string AS status\n  FROM events\n  WHERE event_name = 'subscription_updated'\n    AND properties:\"subscription_id\"::string IS NOT NULL\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n),\nlatest AS (\n  SELECT w.week, u.customer, u.mrr, u.status\n  FROM weeks AS w\n  JOIN updates AS u ON u.occurred_at < DATEADD(week, 1, w.week)\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY w.week, u.subscription_id ORDER BY u.occurred_at DESC) = 1\n),\naccounts AS (\n  SELECT week, customer, SUM(mrr) AS mrr\n  FROM latest\n  WHERE status IN ('active', 'past_due')\n  GROUP BY week, customer\n),\nweekly AS (\n  SELECT week, SUM(mrr) AS mrr, COUNT(*) AS accounts\n  FROM accounts\n  WHERE mrr > 0\n  GROUP BY week\n)\nSELECT\n  w.week,\n  COALESCE(a.mrr, 0) AS numerator,\n  COALESCE(a.accounts, 0) AS denominator,\n  a.mrr / NULLIF(a.accounts, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS a ON a.week = w.week\nORDER BY w.week;"},"noise":{"type":"process","min_denominator":50,"volume_unit":"paying accounts","typical":126},"example":{"business":"saas","level":126,"volume":1850,"trend":0.14},"drivers":[{"id":"account-counting","label":"Account counting","dropped":{"check":"Did zero-amount, test or duplicate accounts start being counted?","yes":"The account count jumps with no matching rise in MRR, usually free plans now synced as subscriptions or one customer split across several ids."},"spiked":{"check":"Did accounts merge or drop out of the count, for example after a customer-id migration?","yes":"The account count falls with no matching cancellations."}},{"id":"pricing","label":"Pricing and discounts","dropped":{"check":"Did a discount, coupon campaign or cheaper plan go live?","yes":"New and renewing accounts land at lower prices from the launch date."},"spiked":{"check":"Did a price increase or coupon expiry take effect?","yes":"Many accounts change amount on the same day with no plan change. It won't repeat."}},{"id":"plan-mix","label":"Plan mix","breakdown":"plan","dropped":{"check":"Has the mix of accounts shifted toward cheaper plans?","yes":"The share of accounts on the entry plan grows while each plan's own average holds."},"spiked":{"check":"Has the mix shifted toward larger plans?","yes":"The share of accounts on the top plans grows while each plan's own average holds."}},{"id":"churn-mix","label":"Who churned","metric":"logo-churn-rate","dropped":{"check":"Did larger accounts churn or downgrade?","yes":"The MRR lost per departing account is well above ARPA this week."},"spiked":{"check":"Did many small accounts churn, lifting the average without anyone paying more?","yes":"Logo churn rises while MRR barely moves. ARPA rose for a bad reason."}},{"id":"new-mix","label":"Who started","metric":"new-mrr","dropped":{"check":"Are new customers starting on smaller plans than the base pays?","yes":"New MRR per new account is well below ARPA, often after a cheaper plan or a self-serve launch."},"spiked":{"check":"Did a few large new accounts, or a move upmarket, lift the average?","yes":"New MRR per new account is well above ARPA; one or two deals explain most of it."}},{"id":"expansion","label":"Expansion","metric":"expansion-mrr","dropped":{"check":"Did upgrades and seat additions slow while accounts kept growing?","yes":"Expansion MRR falls below its usual range for several weeks."},"spiked":{"check":"Did upgrades or a usage limit raise what existing accounts pay?","yes":"Expansion MRR jumps in the weeks ARPA rose."}}],"diagnose_order":["account-counting","pricing","plan-mix","churn-mix","new-mix","expansion"],"related":["mrr","new-mrr","expansion-mrr","logo-churn-rate","customer-lifetime-value"],"prose":{"why_it_matters":"ARPA says what a typical customer is worth each month, and it moves with pricing, packaging and who you sell to rather than with how many you sell. Rising ARPA with a flat customer count is expansion working; rising ARPA because small customers left is churn in disguise. At $126 a month, a $10 move that holds for several weeks is a change in pricing or in who buys.","pitfalls":["Divide by paying accounts, not users or seats. A customer with ten seats is one account; counting seats turns ARPA into price per seat.","Free plans and zero-amount subscriptions in the count pull ARPA down every time sign-ups rise. Count only accounts paying more than zero.","A customer with several subscriptions is still one account. Counting subscriptions understates ARPA for exactly the customers who buy the most.","ARPA rising because small customers churned looks like good news on its own. Read it next to logo churn.","When a few enterprise accounts are a large share of MRR, the mean hides the typical customer. Look at the median too."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "blended-cac": { yaml: "id: blended-cac\nname: Blended customer acquisition cost\naliases:\n  - CAC\n  - Customer acquisition cost\n  - Blended CAC\n  - Cost to acquire a customer\nfamily: acquisition\nkind: currency\npolarity: down-is-good\n\ndefinition:\n  one_line: Acquisition spend in the week divided by every new paying customer won that week, whether they came from ads or not.\n  formula: Acquisition spend ÷ customers whose first paid subscription started this week\n\nevents:\n  - name: ad_spend\n    description: One row per channel per day of acquisition cost. Ad platforms sync their media spend; other costs can be added as their own channel.\n    also_called: [Ad Spend, ad_performance, campaign_daily_stats]\n    properties:\n      - name: spend\n        description: Amount spent that day, in the reporting currency.\n      - name: channel\n        description: The platform or cost line (google, linkedin, meta, sales, agency).\n  - name: subscription_started\n    description: A subscription's first paid period began, after any free trial.\n    also_called: [customer.subscription.created, Subscription Started, subscription_activated]\n    properties:\n      - name: subscription_id\n        description: The billing system's subscription id.\n      - name: mrr\n        description: Monthly amount of the new subscription, after discounts, before tax.\n      - name: plan\n        description: The plan the customer started on.\n\nnumerator:\n  label: Acquisition spend\n  aggregate: sum\n  event: ad_spend\n  property: spend\ndenominator:\n  label: New paying customers\n  aggregate: first_time_users\n  event: subscription_started\n\nnoise:\n  type: process\n  min_denominator: 10\n  volume_unit: new paying customers a week\n  typical: 1000\n\nexample:\n  business: saas\n  level: 1150\n  volume: 29\n  trend: 0.1\n\ndrivers:\n  - id: data\n    label: Spend and billing data\n    dropped:\n      check: Is a channel's spend missing, or are migrated or duplicate subscriptions counting as new customers?\n      yes: Spend shows gaps for one channel, or new customers jump on one day with no matching signups.\n    spiked:\n      check: Is spend synced twice, or did a billing change stop new subscriptions being recorded?\n      yes: One channel's spend doubles for a day, or new subscriptions in the billing system exceed those recorded.\n  - id: calendar\n    label: Calendar\n    feed: holidays\n    dropped:\n      check: Did a quarter-end or a promotion bring forward deals that were already in the pipeline?\n      yes: New customers jump in the last week of a quarter or a promotion while spend holds.\n    spiked:\n      check: Is this a holiday week, when buyers are away but campaigns keep spending?\n      yes: New customers fall in holiday weeks and the same weeks last year show it.\n  - id: new-customers\n    label: New paying customers\n    metric: new-paid-accounts\n    dropped:\n      check: Did more customers start paying at steady spend?\n      yes: New paid accounts rise by about as much as CAC falls.\n    spiked:\n      check: Did fewer customers start paying at steady spend?\n      yes: New paid accounts fall by about as much as CAC rises; look at the trial and signup steps next.\n  - id: spend\n    label: Acquisition spend\n    metric: ad-spend\n    feed: ad-platforms\n    dropped:\n      check: Did spend fall while new customers held?\n      yes: Spend falls on channels that were not producing customers this week.\n    spiked:\n      check: Did a new channel, a budget increase or a conference add cost before it adds customers?\n      yes: Spend rises on one channel or line; customers from it, if any, arrive weeks later.\n  - id: trial-conversion\n    label: Trial conversion\n    metric: trial-conversion-rate\n    dropped:\n      check: Did a larger share of trials turn into paying customers?\n      yes: Trial conversion rises while trial starts hold.\n    spiked:\n      check: Did fewer trials convert, from an onboarding, pricing or payment change?\n      yes: Trial conversion falls while trial starts hold.\n  - id: signups\n    label: Signups\n    metric: signups\n    dropped:\n      check: Did signups rise a few weeks ago, and are those cohorts paying now?\n      yes: A signup rise four to eight weeks back lines up with this week's new customers.\n    spiked:\n      check: Did signups fall a few weeks ago, so fewer trials are converting now?\n      yes: A signup drop four to eight weeks back lines up with this week's fall in new customers.\n\ndiagnose_order: [data, calendar, new-customers, spend, trial-conversion, signups]\n\nrelated: [ncac, cac-payback, ltv-to-cac, ad-spend, new-paid-accounts, new-mrr]\n\nprose:\n  why_it_matters: >-\n    CAC is what a new customer costs, and with the revenue they bring it decides how fast the\n    business can grow on its own cash. Blended CAC divides all acquisition spend by all new\n    customers, so it can't be flattered by an attribution model. At $1,150 per customer, $126 a\n    month in revenue and an 80% gross margin, the spend takes about 11 months to earn back.\n  pitfalls:\n    - Fully loaded CAC also includes sales and marketing salaries, agency fees and tools. Synced ad spend alone is media CAC, which in a sales-led business can be a small part of the full cost; add the other costs as their own channel to blend them in.\n    - Spend and customers don't land in the same week. A B2B sale often takes weeks or months from first click, so weekly CAC swings; read the trailing 13 weeks for planning and the weekly number for direction.\n    - Blended CAC improves when organic signups grow, even if every paid channel got worse. Read paid CAC by channel before raising budgets.\n    - Count customers, not subscriptions. A customer adding a second workspace is expansion, not a new customer.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"blended-cac","name":"Blended customer acquisition cost","aliases":["CAC","Customer acquisition cost","Blended CAC","Cost to acquire a customer"],"family":"acquisition","kind":"currency","polarity":"down-is-good","definition":{"one_line":"Acquisition spend in the week divided by every new paying customer won that week, whether they came from ads or not.","formula":"Acquisition spend ÷ customers whose first paid subscription started this week"},"events":[{"name":"ad_spend","description":"One row per channel per day of acquisition cost. Ad platforms sync their media spend; other costs can be added as their own channel.","also_called":["Ad Spend","ad_performance","campaign_daily_stats"],"properties":[{"name":"spend","description":"Amount spent that day, in the reporting currency."},{"name":"channel","description":"The platform or cost line (google, linkedin, meta, sales, agency)."}]},{"name":"subscription_started","description":"A subscription's first paid period began, after any free trial.","also_called":["customer.subscription.created","Subscription Started","subscription_activated"],"properties":[{"name":"subscription_id","description":"The billing system's subscription id."},{"name":"mrr","description":"Monthly amount of the new subscription, after discounts, before tax."},{"name":"plan","description":"The plan the customer started on."}]}],"numerator":{"label":"Acquisition spend","aggregate":"sum","event":"ad_spend","property":"spend"},"denominator":{"label":"New paying customers","aggregate":"first_time_users","event":"subscription_started"},"noise":{"type":"process","min_denominator":10,"volume_unit":"new paying customers a week","typical":1000},"example":{"business":"saas","level":1150,"volume":29,"trend":0.1},"drivers":[{"id":"data","label":"Spend and billing data","dropped":{"check":"Is a channel's spend missing, or are migrated or duplicate subscriptions counting as new customers?","yes":"Spend shows gaps for one channel, or new customers jump on one day with no matching signups."},"spiked":{"check":"Is spend synced twice, or did a billing change stop new subscriptions being recorded?","yes":"One channel's spend doubles for a day, or new subscriptions in the billing system exceed those recorded."}},{"id":"calendar","label":"Calendar","feed":"holidays","dropped":{"check":"Did a quarter-end or a promotion bring forward deals that were already in the pipeline?","yes":"New customers jump in the last week of a quarter or a promotion while spend holds."},"spiked":{"check":"Is this a holiday week, when buyers are away but campaigns keep spending?","yes":"New customers fall in holiday weeks and the same weeks last year show it."}},{"id":"new-customers","label":"New paying customers","metric":"new-paid-accounts","dropped":{"check":"Did more customers start paying at steady spend?","yes":"New paid accounts rise by about as much as CAC falls."},"spiked":{"check":"Did fewer customers start paying at steady spend?","yes":"New paid accounts fall by about as much as CAC rises; look at the trial and signup steps next."}},{"id":"spend","label":"Acquisition spend","metric":"ad-spend","feed":"ad-platforms","dropped":{"check":"Did spend fall while new customers held?","yes":"Spend falls on channels that were not producing customers this week."},"spiked":{"check":"Did a new channel, a budget increase or a conference add cost before it adds customers?","yes":"Spend rises on one channel or line; customers from it, if any, arrive weeks later."}},{"id":"trial-conversion","label":"Trial conversion","metric":"trial-conversion-rate","dropped":{"check":"Did a larger share of trials turn into paying customers?","yes":"Trial conversion rises while trial starts hold."},"spiked":{"check":"Did fewer trials convert, from an onboarding, pricing or payment change?","yes":"Trial conversion falls while trial starts hold."}},{"id":"signups","label":"Signups","metric":"signups","dropped":{"check":"Did signups rise a few weeks ago, and are those cohorts paying now?","yes":"A signup rise four to eight weeks back lines up with this week's new customers."},"spiked":{"check":"Did signups fall a few weeks ago, so fewer trials are converting now?","yes":"A signup drop four to eight weeks back lines up with this week's fall in new customers."}}],"diagnose_order":["data","calendar","new-customers","spend","trial-conversion","signups"],"related":["ncac","cac-payback","ltv-to-cac","ad-spend","new-paid-accounts","new-mrr"],"prose":{"why_it_matters":"CAC is what a new customer costs, and with the revenue they bring it decides how fast the business can grow on its own cash. Blended CAC divides all acquisition spend by all new customers, so it can't be flattered by an attribution model. At $1,150 per customer, $126 a month in revenue and an 80% gross margin, the spend takes about 11 months to earn back.","pitfalls":["Fully loaded CAC also includes sales and marketing salaries, agency fees and tools. Synced ad spend alone is media CAC, which in a sales-led business can be a small part of the full cost; add the other costs as their own channel to blend them in.","Spend and customers don't land in the same week. A B2B sale often takes weeks or months from first click, so weekly CAC swings; read the trailing 13 weeks for planning and the weekly number for direction.","Blended CAC improves when organic signups grow, even if every paid channel got worse. Read paid CAC by channel before raising budgets.","Count customers, not subscriptions. A customer adding a second workspace is expansion, not a new customer."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "bounce-rate": { yaml: "id: bounce-rate\nname: Bounce rate\naliases:\n  - Website bounce rate\n  - Bounced sessions\n  - Single-page session rate\nfamily: traffic\nkind: rate\npolarity: down-is-good\n\ndefinition:\n  one_line: The share of sessions that view one page, take no action and leave within 10 seconds.\n  formula: Sessions with one page view, no click or key action and under 10 seconds ÷ sessions with a page view\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change, captured in the browser.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: $session_id\n        description: Set by the analytics SDK; ties every event in a visit together.\n      - name: $pathname\n        description: The landing page path, for finding the page that bounces.\n  - name: $autocapture\n    description: A click, form change or submit captured automatically by PostHog. Counts as engagement.\n    also_called: [click, user_engagement]\n  - name: $pageleave\n    description: Sent when the visitor leaves a page; its timestamp gives time on the last page.\n    also_called: [page_leave]\n\nnumerator:\n  label: Bounced sessions\n  aggregate: unique_sessions\n  event: $pageview\ndenominator:\n  label: Sessions\n  aggregate: unique_sessions\n  event: $pageview\n\nqueries:\n  hogql: |-\n    -- Bounce rate per week: sessions with one page view, no click or key action and under 10 seconds ÷ sessions with a page view. Each session counts in the week it started. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(s.bounced, 0) AS numerator,\n      coalesce(s.sessions, 0) AS denominator,\n      if(coalesce(s.sessions, 0) = 0, NULL, s.bounced / s.sessions) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT\n        v.week AS week,\n        countIf(v.pageviews = 1 AND v.actions = 0 AND v.milliseconds < 10000) AS bounced,\n        count() AS sessions\n      FROM (\n        SELECT\n          $session_id AS session_id,\n          toMonday(toTimeZone(min(timestamp), 'UTC')) AS week,\n          countIf(event = '$pageview') AS pageviews,\n          countIf(event IN ('$autocapture', 'product_added', 'product_searched', 'checkout_started', 'signed_up', 'order_completed')) AS actions,\n          dateDiff('millisecond', min(timestamp), max(timestamp)) AS milliseconds\n        FROM events\n        WHERE $session_id != ''\n          AND timestamp >= now() - toIntervalWeek(27)\n          AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n        GROUP BY session_id\n        HAVING pageviews > 0\n      ) AS v\n      GROUP BY week\n    ) AS s ON s.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Bounce rate per week: sessions with one page view, no click or key action and under 10 seconds ÷ sessions with a page view. Each session counts in the week it started. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    visits AS (\n      SELECT\n        session_id,\n        date_trunc('week', min(occurred_at) AT TIME ZONE 'UTC')::date AS week,\n        count(*) FILTER (WHERE event_name = '$pageview') AS pageviews,\n        count(*) FILTER (WHERE event_name IN ('$autocapture', 'product_added', 'product_searched', 'checkout_started', 'signed_up', 'order_completed')) AS actions,\n        extract(epoch FROM max(occurred_at) - min(occurred_at)) AS seconds\n      FROM events\n      WHERE session_id <> ''\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n      GROUP BY session_id\n    ),\n    weekly AS (\n      SELECT\n        week,\n        count(*) FILTER (WHERE pageviews = 1 AND actions = 0 AND seconds < 10) AS bounced,\n        count(*) AS sessions\n      FROM visits\n      WHERE pageviews > 0\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      coalesce(s.bounced, 0) AS numerator,\n      coalesce(s.sessions, 0) AS denominator,\n      s.bounced::numeric / nullif(s.sessions, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS s ON s.week = w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Bounce rate per week: sessions with one page view, no click or key action and under 10 seconds ÷ sessions with a page view. Each session counts in the week it started. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    visits AS (\n      SELECT\n        session_id,\n        DATE_TRUNC(DATE(MIN(occurred_at)), ISOWEEK) AS week,\n        COUNTIF(event_name = '$pageview') AS pageviews,\n        COUNTIF(event_name IN ('$autocapture', 'product_added', 'product_searched', 'checkout_started', 'signed_up', 'order_completed')) AS actions,\n        TIMESTAMP_DIFF(MAX(occurred_at), MIN(occurred_at), MILLISECOND) AS milliseconds\n      FROM events\n      WHERE session_id <> ''\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY session_id\n    ),\n    weekly AS (\n      SELECT\n        week,\n        COUNTIF(pageviews = 1 AND actions = 0 AND milliseconds < 10000) AS bounced,\n        COUNT(*) AS sessions\n      FROM visits\n      WHERE pageviews > 0\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      COALESCE(s.bounced, 0) AS numerator,\n      COALESCE(s.sessions, 0) AS denominator,\n      SAFE_DIVIDE(s.bounced, s.sessions) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS s ON s.week = w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Bounce rate per week: sessions with one page view, no click or key action and under 10 seconds ÷ sessions with a page view. Each session counts in the week it started. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    visits AS (\n      SELECT\n        session_id,\n        DATEADD(day, 1 - DAYOFWEEKISO(MIN(occurred_at)), MIN(occurred_at)::date) AS week,\n        COUNT_IF(event_name = '$pageview') AS pageviews,\n        COUNT_IF(event_name IN ('$autocapture', 'product_added', 'product_searched', 'checkout_started', 'signed_up', 'order_completed')) AS actions,\n        DATEDIFF('millisecond', MIN(occurred_at), MAX(occurred_at)) AS milliseconds\n      FROM events\n      WHERE session_id <> ''\n        AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n      GROUP BY session_id\n    ),\n    weekly AS (\n      SELECT\n        week,\n        COUNT_IF(pageviews = 1 AND actions = 0 AND milliseconds < 10000) AS bounced,\n        COUNT(*) AS sessions\n      FROM visits\n      WHERE pageviews > 0\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      COALESCE(s.bounced, 0) AS numerator,\n      COALESCE(s.sessions, 0) AS denominator,\n      s.bounced::float / NULLIF(s.sessions, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS s ON s.week = w.week\n    ORDER BY w.week;\n\nnoise:\n  type: binomial\n  min_denominator: 200\n  volume_unit: sessions a week\n  typical: 0.4\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: store\n  level: 0.38\n  volume: 520000\n  trend: -0.02\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Is a page view or click event now firing twice, so single-page visits no longer look like bounces?\n      yes: Bounce rate falls by many points overnight, page views per session jump, and orders don't move.\n    spiked:\n      check: Did a release stop route changes, clicks or page-leave events being recorded?\n      yes: Bounce rises on the day of a release while orders hold and page views per session fall.\n  - id: bots\n    label: Bots and junk traffic\n    breakdown: $geoip_country_code\n    dropped:\n      check: Did a bot or spam source that always bounced stop?\n      yes: One country, browser or referrer that bounced nearly every time has disappeared.\n    spiked:\n      check: Is a crawler, uptime checker or spam referrer adding one-page visits?\n      yes: The extra sessions come from one country, browser or data-centre network, last zero seconds and never order.\n  - id: site-speed\n    label: Site speed and errors\n    feed: cloudflare\n    dropped:\n      check: Did a slow or broken period last week end?\n      yes: Bounce returns to its usual level once load times recover.\n    spiked:\n      check: Did pages load slowly, error or fail to render, from an outage or a heavy release?\n      yes: Bounce rises in the hours of an incident, or on one device or browser after a release.\n  - id: traffic-mix\n    label: Who arrived\n    metric: paid-sessions\n    breakdown: utm_source\n    dropped:\n      check: Did low-intent traffic, such as broad prospecting or a viral link, shrink?\n      yes: The source that bounced most sends fewer sessions while each source's own bounce rate holds.\n    spiked:\n      check: Did a campaign, social post or press link bring visitors who leave at once?\n      yes: One source grows and bounces far above the rest; every other source holds its rate.\n  - id: landing-pages\n    label: Landing pages\n    breakdown: $pathname\n    dropped:\n      check: Did a landing page get faster, clearer, or start matching its ad better?\n      yes: Bounce falls on that page from the day it changed.\n    spiked:\n      check: Is a sold-out product, a 404 or a changed page catching traffic from an ad or search result?\n      yes: One landing path accounts for most of the extra bounces.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the fall on one device only, after a layout change?\n      yes: One device improves while the others hold.\n    spiked:\n      check: Is the rise on one device only?\n      yes: Mobile bounce jumps after a release, which points at a layout or pop-up problem.\n\ndiagnose_order: [tracking, bots, site-speed, traffic-mix, landing-pages, device-split]\n\nrelated: [sessions, pages-per-session, product-view-rate, conversion-rate, paid-sessions]\n\nprose:\n  why_it_matters: >-\n    Bounce rate is the cheapest early warning a store has: it moves within hours of a broken\n    page, a slow release or a campaign sending the wrong people, long before orders are counted.\n    On 520,000 sessions a week, two extra points of bounce is about 10,000 visits that never see\n    a product, which at a 2% conversion rate is about 200 orders.\n  pitfalls:\n    - Bounce rates from different tools don't compare. Universal Analytics counted any one-page visit, GA4 reports one minus engagement rate, and this spec follows PostHog's rule of one page, no click and under 10 seconds.\n    - A bounce rate that falls to the low teens or below overnight almost always means a page view or event fires twice, not a better site. Check the tags before celebrating.\n    - Without a page-leave event or click tracking, the 10-second rule can't fire and every one-page visit counts as a bounce, so the rate reads high.\n    - A single-page blog post or a store-locator page that answers the question bounces by design. Read bounce by landing page, not as one number.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"bounce-rate","name":"Bounce rate","aliases":["Website bounce rate","Bounced sessions","Single-page session rate"],"family":"traffic","kind":"rate","polarity":"down-is-good","definition":{"one_line":"The share of sessions that view one page, take no action and leave within 10 seconds.","formula":"Sessions with one page view, no click or key action and under 10 seconds ÷ sessions with a page view"},"events":[{"name":"$pageview","description":"One page load or client-side route change, captured in the browser.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"$session_id","description":"Set by the analytics SDK; ties every event in a visit together."},{"name":"$pathname","description":"The landing page path, for finding the page that bounces."}]},{"name":"$autocapture","description":"A click, form change or submit captured automatically by PostHog. Counts as engagement.","also_called":["click","user_engagement"]},{"name":"$pageleave","description":"Sent when the visitor leaves a page; its timestamp gives time on the last page.","also_called":["page_leave"]}],"numerator":{"label":"Bounced sessions","aggregate":"unique_sessions","event":"$pageview"},"denominator":{"label":"Sessions","aggregate":"unique_sessions","event":"$pageview"},"queries":{"hogql":"-- Bounce rate per week: sessions with one page view, no click or key action and under 10 seconds ÷ sessions with a page view. Each session counts in the week it started. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(s.bounced, 0) AS numerator,\n  coalesce(s.sessions, 0) AS denominator,\n  if(coalesce(s.sessions, 0) = 0, NULL, s.bounced / s.sessions) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT\n    v.week AS week,\n    countIf(v.pageviews = 1 AND v.actions = 0 AND v.milliseconds < 10000) AS bounced,\n    count() AS sessions\n  FROM (\n    SELECT\n      $session_id AS session_id,\n      toMonday(toTimeZone(min(timestamp), 'UTC')) AS week,\n      countIf(event = '$pageview') AS pageviews,\n      countIf(event IN ('$autocapture', 'product_added', 'product_searched', 'checkout_started', 'signed_up', 'order_completed')) AS actions,\n      dateDiff('millisecond', min(timestamp), max(timestamp)) AS milliseconds\n    FROM events\n    WHERE $session_id != ''\n      AND timestamp >= now() - toIntervalWeek(27)\n      AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n    GROUP BY session_id\n    HAVING pageviews > 0\n  ) AS v\n  GROUP BY week\n) AS s ON s.week = w.week\nORDER BY week","postgres":"-- Bounce rate per week: sessions with one page view, no click or key action and under 10 seconds ÷ sessions with a page view. Each session counts in the week it started. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nvisits AS (\n  SELECT\n    session_id,\n    date_trunc('week', min(occurred_at) AT TIME ZONE 'UTC')::date AS week,\n    count(*) FILTER (WHERE event_name = '$pageview') AS pageviews,\n    count(*) FILTER (WHERE event_name IN ('$autocapture', 'product_added', 'product_searched', 'checkout_started', 'signed_up', 'order_completed')) AS actions,\n    extract(epoch FROM max(occurred_at) - min(occurred_at)) AS seconds\n  FROM events\n  WHERE session_id <> ''\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n  GROUP BY session_id\n),\nweekly AS (\n  SELECT\n    week,\n    count(*) FILTER (WHERE pageviews = 1 AND actions = 0 AND seconds < 10) AS bounced,\n    count(*) AS sessions\n  FROM visits\n  WHERE pageviews > 0\n  GROUP BY week\n)\nSELECT\n  w.week,\n  coalesce(s.bounced, 0) AS numerator,\n  coalesce(s.sessions, 0) AS denominator,\n  s.bounced::numeric / nullif(s.sessions, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS s ON s.week = w.week\nORDER BY w.week;","bigquery":"-- Bounce rate per week: sessions with one page view, no click or key action and under 10 seconds ÷ sessions with a page view. Each session counts in the week it started. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nvisits AS (\n  SELECT\n    session_id,\n    DATE_TRUNC(DATE(MIN(occurred_at)), ISOWEEK) AS week,\n    COUNTIF(event_name = '$pageview') AS pageviews,\n    COUNTIF(event_name IN ('$autocapture', 'product_added', 'product_searched', 'checkout_started', 'signed_up', 'order_completed')) AS actions,\n    TIMESTAMP_DIFF(MAX(occurred_at), MIN(occurred_at), MILLISECOND) AS milliseconds\n  FROM events\n  WHERE session_id <> ''\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY session_id\n),\nweekly AS (\n  SELECT\n    week,\n    COUNTIF(pageviews = 1 AND actions = 0 AND milliseconds < 10000) AS bounced,\n    COUNT(*) AS sessions\n  FROM visits\n  WHERE pageviews > 0\n  GROUP BY week\n)\nSELECT\n  w.week,\n  COALESCE(s.bounced, 0) AS numerator,\n  COALESCE(s.sessions, 0) AS denominator,\n  SAFE_DIVIDE(s.bounced, s.sessions) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS s ON s.week = w.week\nORDER BY w.week;","snowflake":"-- Bounce rate per week: sessions with one page view, no click or key action and under 10 seconds ÷ sessions with a page view. Each session counts in the week it started. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nvisits AS (\n  SELECT\n    session_id,\n    DATEADD(day, 1 - DAYOFWEEKISO(MIN(occurred_at)), MIN(occurred_at)::date) AS week,\n    COUNT_IF(event_name = '$pageview') AS pageviews,\n    COUNT_IF(event_name IN ('$autocapture', 'product_added', 'product_searched', 'checkout_started', 'signed_up', 'order_completed')) AS actions,\n    DATEDIFF('millisecond', MIN(occurred_at), MAX(occurred_at)) AS milliseconds\n  FROM events\n  WHERE session_id <> ''\n    AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n  GROUP BY session_id\n),\nweekly AS (\n  SELECT\n    week,\n    COUNT_IF(pageviews = 1 AND actions = 0 AND milliseconds < 10000) AS bounced,\n    COUNT(*) AS sessions\n  FROM visits\n  WHERE pageviews > 0\n  GROUP BY week\n)\nSELECT\n  w.week,\n  COALESCE(s.bounced, 0) AS numerator,\n  COALESCE(s.sessions, 0) AS denominator,\n  s.bounced::float / NULLIF(s.sessions, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS s ON s.week = w.week\nORDER BY w.week;"},"noise":{"type":"binomial","min_denominator":200,"volume_unit":"sessions a week","typical":0.4,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"store","level":0.38,"volume":520000,"trend":-0.02},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Is a page view or click event now firing twice, so single-page visits no longer look like bounces?","yes":"Bounce rate falls by many points overnight, page views per session jump, and orders don't move."},"spiked":{"check":"Did a release stop route changes, clicks or page-leave events being recorded?","yes":"Bounce rises on the day of a release while orders hold and page views per session fall."}},{"id":"bots","label":"Bots and junk traffic","breakdown":"$geoip_country_code","dropped":{"check":"Did a bot or spam source that always bounced stop?","yes":"One country, browser or referrer that bounced nearly every time has disappeared."},"spiked":{"check":"Is a crawler, uptime checker or spam referrer adding one-page visits?","yes":"The extra sessions come from one country, browser or data-centre network, last zero seconds and never order."}},{"id":"site-speed","label":"Site speed and errors","feed":"cloudflare","dropped":{"check":"Did a slow or broken period last week end?","yes":"Bounce returns to its usual level once load times recover."},"spiked":{"check":"Did pages load slowly, error or fail to render, from an outage or a heavy release?","yes":"Bounce rises in the hours of an incident, or on one device or browser after a release."}},{"id":"traffic-mix","label":"Who arrived","metric":"paid-sessions","breakdown":"utm_source","dropped":{"check":"Did low-intent traffic, such as broad prospecting or a viral link, shrink?","yes":"The source that bounced most sends fewer sessions while each source's own bounce rate holds."},"spiked":{"check":"Did a campaign, social post or press link bring visitors who leave at once?","yes":"One source grows and bounces far above the rest; every other source holds its rate."}},{"id":"landing-pages","label":"Landing pages","breakdown":"$pathname","dropped":{"check":"Did a landing page get faster, clearer, or start matching its ad better?","yes":"Bounce falls on that page from the day it changed."},"spiked":{"check":"Is a sold-out product, a 404 or a changed page catching traffic from an ad or search result?","yes":"One landing path accounts for most of the extra bounces."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the fall on one device only, after a layout change?","yes":"One device improves while the others hold."},"spiked":{"check":"Is the rise on one device only?","yes":"Mobile bounce jumps after a release, which points at a layout or pop-up problem."}}],"diagnose_order":["tracking","bots","site-speed","traffic-mix","landing-pages","device-split"],"related":["sessions","pages-per-session","product-view-rate","conversion-rate","paid-sessions"],"prose":{"why_it_matters":"Bounce rate is the cheapest early warning a store has: it moves within hours of a broken page, a slow release or a campaign sending the wrong people, long before orders are counted. On 520,000 sessions a week, two extra points of bounce is about 10,000 visits that never see a product, which at a 2% conversion rate is about 200 orders.","pitfalls":["Bounce rates from different tools don't compare. Universal Analytics counted any one-page visit, GA4 reports one minus engagement rate, and this spec follows PostHog's rule of one page, no click and under 10 seconds.","A bounce rate that falls to the low teens or below overnight almost always means a page view or event fires twice, not a better site. Check the tags before celebrating.","Without a page-leave event or click tracking, the 10-second rule can't fire and every one-page visit counts as a bounce, so the rate reads high.","A single-page blog post or a store-locator page that answers the question bounces by design. Read bounce by landing page, not as one number."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "cac-payback": { yaml: "id: cac-payback\nname: CAC payback period\naliases:\n  - Payback period\n  - CAC payback months\n  - Months to recover CAC\nfamily: acquisition\nkind: duration\nduration_unit: months\npolarity: down-is-good\n\ndefinition:\n  one_line: How many months of gross margin from the week's new customers it takes to earn back what was spent to win them.\n  formula: Acquisition spend ÷ (new MRR from first subscriptions × gross margin)\n\nevents:\n  - name: ad_spend\n    description: One row per channel per day of acquisition cost. Ad platforms sync their media spend; other costs can be added as their own channel.\n    also_called: [Ad Spend, ad_performance, campaign_daily_stats]\n    properties:\n      - name: spend\n        description: Amount spent that day, in the reporting currency.\n  - name: subscription_started\n    description: A subscription's first paid period began, after any free trial.\n    also_called: [customer.subscription.created, Subscription Started, subscription_activated]\n    properties:\n      - name: mrr\n        description: Monthly amount of the new subscription, after discounts, before tax. Annual plans divided by twelve.\n      - name: plan\n        description: The plan the customer started on.\n\nnumerator:\n  label: Acquisition spend\n  aggregate: sum\n  event: ad_spend\n  property: spend\ndenominator:\n  label: New MRR × gross margin\n  aggregate: sum\n  event: subscription_started\n  property: mrr\n\nqueries:\n  hogql: |-\n    -- CAC payback per week, in months: acquisition spend ÷ (new MRR from first subscriptions × gross margin). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Gross margin is set to 0.80 below; replace it with your own.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(f.spend, 0) AS numerator,\n      coalesce(f.new_mrr, 0) * 0.80 AS denominator,\n      if(denominator = 0, NULL, numerator / denominator) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT\n        toMonday(toTimeZone(timestamp, 'UTC')) AS week,\n        sumIf(toFloat(properties.spend), event = 'ad_spend') AS spend,\n        sumIf(toFloat(properties.mrr), event = 'subscription_started') AS new_mrr\n      FROM events\n      WHERE event IN ('ad_spend', 'subscription_started')\n        AND timestamp >= now() - toIntervalWeek(27)\n        AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n      GROUP BY week\n    ) AS f ON f.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- CAC payback per week, in months: acquisition spend ÷ (new MRR from first subscriptions × gross margin). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Gross margin is set to 0.80 below; replace it with your own.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    flows AS (\n      SELECT\n        date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n        sum(CASE WHEN properties->>'spend' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'spend')::numeric END) FILTER (WHERE event_name = 'ad_spend') AS spend,\n        sum(CASE WHEN properties->>'mrr' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr')::numeric END) FILTER (WHERE event_name = 'subscription_started') AS new_mrr\n      FROM events\n      WHERE event_name IN ('ad_spend', 'subscription_started')\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n      GROUP BY 1\n    ),\n    totals AS (\n      SELECT w.week, coalesce(f.spend, 0) AS numerator, coalesce(f.new_mrr, 0) * 0.80 AS denominator\n      FROM weeks AS w\n      LEFT JOIN flows AS f ON f.week = w.week\n    )\n    SELECT week, numerator, denominator, numerator / nullif(denominator, 0) AS value\n    FROM totals\n    ORDER BY week;\n  bigquery: |-\n    -- CAC payback per week, in months: acquisition spend ÷ (new MRR from first subscriptions × gross margin). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Gross margin is set to 0.80 below; replace it with your own.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    flows AS (\n      SELECT\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n        SUM(IF(event_name = 'ad_spend', SAFE_CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64), NULL)) AS spend,\n        SUM(IF(event_name = 'subscription_started', SAFE_CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64), NULL)) AS new_mrr\n      FROM events\n      WHERE event_name IN ('ad_spend', 'subscription_started')\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY week\n    ),\n    totals AS (\n      SELECT w.week, COALESCE(f.spend, 0) AS numerator, COALESCE(f.new_mrr, 0) * 0.80 AS denominator\n      FROM weeks AS w\n      LEFT JOIN flows AS f ON f.week = w.week\n    )\n    SELECT week, numerator, denominator, SAFE_DIVIDE(numerator, denominator) AS value\n    FROM totals\n    ORDER BY week;\n  snowflake: |-\n    -- CAC payback per week, in months: acquisition spend ÷ (new MRR from first subscriptions × gross margin). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Gross margin is set to 0.80 below; replace it with your own.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    flows AS (\n      SELECT\n        DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n        SUM(IFF(event_name = 'ad_spend', TRY_TO_DOUBLE(properties:\"spend\"::string), NULL)) AS spend,\n        SUM(IFF(event_name = 'subscription_started', TRY_TO_DOUBLE(properties:\"mrr\"::string), NULL)) AS new_mrr\n      FROM events\n      WHERE event_name IN ('ad_spend', 'subscription_started')\n        AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n      GROUP BY 1\n    ),\n    totals AS (\n      SELECT w.week, COALESCE(f.spend, 0) AS numerator, COALESCE(f.new_mrr, 0) * 0.80 AS denominator\n      FROM weeks AS w\n      LEFT JOIN flows AS f ON f.week = w.week\n    )\n    SELECT week, numerator, denominator, numerator / NULLIF(denominator, 0) AS value\n    FROM totals\n    ORDER BY week;\n\nnoise:\n  type: process\n  min_denominator: 10\n  volume_unit: new subscriptions a week\n  typical: 12\n\nexample:\n  business: saas\n  level: 11.5\n  volume: 29\n  trend: 0.06\n\ndrivers:\n  - id: data\n    label: Spend and billing data\n    dropped:\n      check: Are migrated, reactivated or duplicate subscriptions counting as new MRR, or is spend missing?\n      yes: New MRR jumps on one day with no matching signups, or one channel's spend has gaps.\n    spiked:\n      check: Is spend synced twice, or did a billing change stop new subscriptions being recorded?\n      yes: One channel's spend doubles for a day, or new subscriptions in the billing system exceed those recorded.\n  - id: calendar\n    label: Calendar\n    feed: holidays\n    dropped:\n      check: Did a quarter-end push or an annual-plan promotion bring a cluster of new subscriptions?\n      yes: New MRR jumps in the last week of a quarter or a promotion while spend holds.\n    spiked:\n      check: Is this a holiday week, when buyers are away but campaigns keep spending?\n      yes: New MRR falls in holiday weeks and the same weeks last year show it.\n  - id: cac\n    label: Cost per new customer\n    metric: blended-cac\n    dropped:\n      check: Did each new customer cost less, from cheaper channels or better trial conversion?\n      yes: Blended CAC falls by about as much as payback does, while new-customer revenue holds.\n    spiked:\n      check: Did each new customer cost more, from a new channel, a budget increase or fewer conversions?\n      yes: Blended CAC rises by about as much as payback does, while new-customer revenue holds.\n  - id: new-mrr\n    label: New MRR per customer\n    metric: new-mrr\n    breakdown: plan\n    dropped:\n      check: Did new customers start on bigger plans, more seats or annual contracts?\n      yes: New MRR per new customer rises; the plan mix shifts toward higher tiers.\n    spiked:\n      check: Did new customers start on smaller plans, or did a discount lower first-year prices?\n      yes: New MRR per new customer falls; the plan mix shifts toward entry tiers or discounted prices.\n  - id: spend-timing\n    label: Spend ahead of customers\n    metric: ad-spend\n    feed: ad-platforms\n    dropped:\n      check: Did spend fall while customers from earlier weeks' pipeline kept arriving?\n      yes: Spend falls this week while new MRR holds; expect payback to rise again when those deals run out.\n    spiked:\n      check: Did a budget increase, an event or a new channel add cost before the customers it will bring?\n      yes: Spend rises on one channel or line while new MRR holds; judge it again in four to eight weeks.\n\ndiagnose_order: [data, calendar, spend-timing, cac, new-mrr]\n\nrelated: [blended-cac, ltv-to-cac, new-mrr, arpa, gross-margin, net-revenue-retention]\n\nprose:\n  why_it_matters: >-\n    Payback is how long the business waits to get its acquisition money back, which sets how\n    fast it can grow without raising more. It joins what a customer costs and what they pay each\n    month into one number a founder can plan on. At 11.5 months, a dollar spent this week comes\n    back in just under a year and can then be spent again.\n  pitfalls:\n    - Payback without gross margin overstates how fast money comes back. On 80% margin, revenue-based payback reads 20% too short.\n    - Weekly payback swings with deal timing, because spend leads new customers by weeks or months. Plan on the trailing quarter and read the weekly number for direction only.\n    - It assumes customers stay long enough to pay it back. At Copperline's logo churn of about 0.56% a week, about a quarter of a cohort has left by month 11.5; read it with net revenue retention.\n    - Media spend alone gives a flattering number. Sales salaries, agency fees and tools belong in the spend for a fully loaded payback.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"cac-payback","name":"CAC payback period","aliases":["Payback period","CAC payback months","Months to recover CAC"],"family":"acquisition","kind":"duration","duration_unit":"months","polarity":"down-is-good","definition":{"one_line":"How many months of gross margin from the week's new customers it takes to earn back what was spent to win them.","formula":"Acquisition spend ÷ (new MRR from first subscriptions × gross margin)"},"events":[{"name":"ad_spend","description":"One row per channel per day of acquisition cost. Ad platforms sync their media spend; other costs can be added as their own channel.","also_called":["Ad Spend","ad_performance","campaign_daily_stats"],"properties":[{"name":"spend","description":"Amount spent that day, in the reporting currency."}]},{"name":"subscription_started","description":"A subscription's first paid period began, after any free trial.","also_called":["customer.subscription.created","Subscription Started","subscription_activated"],"properties":[{"name":"mrr","description":"Monthly amount of the new subscription, after discounts, before tax. Annual plans divided by twelve."},{"name":"plan","description":"The plan the customer started on."}]}],"numerator":{"label":"Acquisition spend","aggregate":"sum","event":"ad_spend","property":"spend"},"denominator":{"label":"New MRR × gross margin","aggregate":"sum","event":"subscription_started","property":"mrr"},"queries":{"hogql":"-- CAC payback per week, in months: acquisition spend ÷ (new MRR from first subscriptions × gross margin). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Gross margin is set to 0.80 below; replace it with your own.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(f.spend, 0) AS numerator,\n  coalesce(f.new_mrr, 0) * 0.80 AS denominator,\n  if(denominator = 0, NULL, numerator / denominator) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT\n    toMonday(toTimeZone(timestamp, 'UTC')) AS week,\n    sumIf(toFloat(properties.spend), event = 'ad_spend') AS spend,\n    sumIf(toFloat(properties.mrr), event = 'subscription_started') AS new_mrr\n  FROM events\n  WHERE event IN ('ad_spend', 'subscription_started')\n    AND timestamp >= now() - toIntervalWeek(27)\n    AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n  GROUP BY week\n) AS f ON f.week = w.week\nORDER BY week","postgres":"-- CAC payback per week, in months: acquisition spend ÷ (new MRR from first subscriptions × gross margin). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Gross margin is set to 0.80 below; replace it with your own.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nflows AS (\n  SELECT\n    date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n    sum(CASE WHEN properties->>'spend' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'spend')::numeric END) FILTER (WHERE event_name = 'ad_spend') AS spend,\n    sum(CASE WHEN properties->>'mrr' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr')::numeric END) FILTER (WHERE event_name = 'subscription_started') AS new_mrr\n  FROM events\n  WHERE event_name IN ('ad_spend', 'subscription_started')\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n  GROUP BY 1\n),\ntotals AS (\n  SELECT w.week, coalesce(f.spend, 0) AS numerator, coalesce(f.new_mrr, 0) * 0.80 AS denominator\n  FROM weeks AS w\n  LEFT JOIN flows AS f ON f.week = w.week\n)\nSELECT week, numerator, denominator, numerator / nullif(denominator, 0) AS value\nFROM totals\nORDER BY week;","bigquery":"-- CAC payback per week, in months: acquisition spend ÷ (new MRR from first subscriptions × gross margin). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Gross margin is set to 0.80 below; replace it with your own.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nflows AS (\n  SELECT\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n    SUM(IF(event_name = 'ad_spend', SAFE_CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64), NULL)) AS spend,\n    SUM(IF(event_name = 'subscription_started', SAFE_CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64), NULL)) AS new_mrr\n  FROM events\n  WHERE event_name IN ('ad_spend', 'subscription_started')\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY week\n),\ntotals AS (\n  SELECT w.week, COALESCE(f.spend, 0) AS numerator, COALESCE(f.new_mrr, 0) * 0.80 AS denominator\n  FROM weeks AS w\n  LEFT JOIN flows AS f ON f.week = w.week\n)\nSELECT week, numerator, denominator, SAFE_DIVIDE(numerator, denominator) AS value\nFROM totals\nORDER BY week;","snowflake":"-- CAC payback per week, in months: acquisition spend ÷ (new MRR from first subscriptions × gross margin). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Gross margin is set to 0.80 below; replace it with your own.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nflows AS (\n  SELECT\n    DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n    SUM(IFF(event_name = 'ad_spend', TRY_TO_DOUBLE(properties:\"spend\"::string), NULL)) AS spend,\n    SUM(IFF(event_name = 'subscription_started', TRY_TO_DOUBLE(properties:\"mrr\"::string), NULL)) AS new_mrr\n  FROM events\n  WHERE event_name IN ('ad_spend', 'subscription_started')\n    AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n  GROUP BY 1\n),\ntotals AS (\n  SELECT w.week, COALESCE(f.spend, 0) AS numerator, COALESCE(f.new_mrr, 0) * 0.80 AS denominator\n  FROM weeks AS w\n  LEFT JOIN flows AS f ON f.week = w.week\n)\nSELECT week, numerator, denominator, numerator / NULLIF(denominator, 0) AS value\nFROM totals\nORDER BY week;"},"noise":{"type":"process","min_denominator":10,"volume_unit":"new subscriptions a week","typical":12},"example":{"business":"saas","level":11.5,"volume":29,"trend":0.06},"drivers":[{"id":"data","label":"Spend and billing data","dropped":{"check":"Are migrated, reactivated or duplicate subscriptions counting as new MRR, or is spend missing?","yes":"New MRR jumps on one day with no matching signups, or one channel's spend has gaps."},"spiked":{"check":"Is spend synced twice, or did a billing change stop new subscriptions being recorded?","yes":"One channel's spend doubles for a day, or new subscriptions in the billing system exceed those recorded."}},{"id":"calendar","label":"Calendar","feed":"holidays","dropped":{"check":"Did a quarter-end push or an annual-plan promotion bring a cluster of new subscriptions?","yes":"New MRR jumps in the last week of a quarter or a promotion while spend holds."},"spiked":{"check":"Is this a holiday week, when buyers are away but campaigns keep spending?","yes":"New MRR falls in holiday weeks and the same weeks last year show it."}},{"id":"cac","label":"Cost per new customer","metric":"blended-cac","dropped":{"check":"Did each new customer cost less, from cheaper channels or better trial conversion?","yes":"Blended CAC falls by about as much as payback does, while new-customer revenue holds."},"spiked":{"check":"Did each new customer cost more, from a new channel, a budget increase or fewer conversions?","yes":"Blended CAC rises by about as much as payback does, while new-customer revenue holds."}},{"id":"new-mrr","label":"New MRR per customer","metric":"new-mrr","breakdown":"plan","dropped":{"check":"Did new customers start on bigger plans, more seats or annual contracts?","yes":"New MRR per new customer rises; the plan mix shifts toward higher tiers."},"spiked":{"check":"Did new customers start on smaller plans, or did a discount lower first-year prices?","yes":"New MRR per new customer falls; the plan mix shifts toward entry tiers or discounted prices."}},{"id":"spend-timing","label":"Spend ahead of customers","metric":"ad-spend","feed":"ad-platforms","dropped":{"check":"Did spend fall while customers from earlier weeks' pipeline kept arriving?","yes":"Spend falls this week while new MRR holds; expect payback to rise again when those deals run out."},"spiked":{"check":"Did a budget increase, an event or a new channel add cost before the customers it will bring?","yes":"Spend rises on one channel or line while new MRR holds; judge it again in four to eight weeks."}}],"diagnose_order":["data","calendar","spend-timing","cac","new-mrr"],"related":["blended-cac","ltv-to-cac","new-mrr","arpa","gross-margin","net-revenue-retention"],"prose":{"why_it_matters":"Payback is how long the business waits to get its acquisition money back, which sets how fast it can grow without raising more. It joins what a customer costs and what they pay each month into one number a founder can plan on. At 11.5 months, a dollar spent this week comes back in just under a year and can then be spent again.","pitfalls":["Payback without gross margin overstates how fast money comes back. On 80% margin, revenue-based payback reads 20% too short.","Weekly payback swings with deal timing, because spend leads new customers by weeks or months. Plan on the trailing quarter and read the weekly number for direction only.","It assumes customers stay long enough to pay it back. At Copperline's logo churn of about 0.56% a week, about a quarter of a cohort has left by month 11.5; read it with net revenue retention.","Media spend alone gives a flattering number. Sales salaries, agency fees and tools belong in the spend for a fully loaded payback."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "cart-abandonment-rate": { yaml: "id: cart-abandonment-rate\nname: Cart abandonment rate\naliases:\n  - Cart abandonment\n  - Shopping cart abandonment rate\n  - Abandoned cart rate\nfamily: conversion\nkind: rate\npolarity: down-is-good\n\ndefinition:\n  one_line: The share of shopping carts that never become a paid order, by Baymard's definition of one minus orders over carts.\n  formula: 1 − sessions with a paid order ÷ sessions that added to cart, both counted in the same week\n\nevents:\n  - name: product_added\n    description: An item added to the cart from any button, confirmed by the cart, not the click.\n    also_called: [add_to_cart, Product Added, product_added_to_cart]\n    properties:\n      - name: product_id\n        description: The product added.\n      - name: quantity\n        description: Units added in this action.\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n\nnumerator:\n  label: Sessions that added to cart\n  aggregate: unique_sessions\n  event: product_added\nsubtract:\n  label: Sessions with a paid order\n  aggregate: unique_sessions\n  event: order_completed\ndenominator:\n  label: Sessions that added to cart\n  aggregate: unique_sessions\n  event: product_added\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: carts a week\n  typical: 0.7\n  reference_volumes: [500, 2000, 10000, 40000]\n\nexample:\n  business: store\n  level: 0.67\n  volume: 40000\n  trend: -0.03\n  season: -0.5\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Is a duplicate order event, or a missing add-to-cart event on one platform, shrinking the gap?\n      yes: Orders recorded exceed orders in the payment processor, or adds fall on one device while orders hold.\n    spiked:\n      check: Did an add-to-cart event start firing twice, or did order events stop being recorded?\n      yes: Carts rise without checkout starts following, or recorded orders fall below the processor's count.\n  - id: calendar\n    label: Sale calendar\n    feed: shopping\n    dropped:\n      check: Is this a sale week, when carts that were parked the week before finally convert?\n      yes: Orders rise faster than carts, and the same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is it the week before a sale, when shoppers fill carts and wait for the discount?\n      yes: Carts rise while orders hold, and the same week last year shows the same rise.\n  - id: cart-to-checkout\n    label: Cart to checkout\n    metric: checkout-start-rate\n    dropped:\n      check: Did more carts move on to checkout, after a cart page or shipping message change?\n      yes: Checkout start rate rises by about as much as abandonment falls.\n    spiked:\n      check: Did fewer carts reach checkout, from a cart page change, a surprise cost or a broken button?\n      yes: Checkout start rate falls while checkout completion holds.\n  - id: checkout-completion\n    label: Checkout completion\n    metric: checkout-conversion\n    feed: stripe\n    dropped:\n      check: Did more started checkouts finish, after a checkout fix or a payment method launch?\n      yes: Checkout conversion rises while checkout starts hold.\n    spiked:\n      check: Did more checkouts fail at shipping, account creation or payment?\n      yes: Checkout conversion falls while checkout starts hold; one step or one payment method explains most of it.\n  - id: extra-costs\n    label: Shipping, tax and fees\n    dropped:\n      check: Did a free-shipping offer, a lower threshold or a clearer delivery date go live?\n      yes: Fewer exits at the shipping step from the day it launched.\n    spiked:\n      check: Did shipping prices, thresholds, duties or fees shown late in checkout change?\n      yes: Exits concentrate on the shipping step, starting the day the change shipped.\n  - id: device-mix\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Did desktop take a larger share of carts, or did mobile abandonment fall?\n      yes: Each device's rate holds and the mix moved, or mobile falls after a release.\n    spiked:\n      check: Did mobile take a larger share of carts, or did mobile abandonment rise on its own?\n      yes: Each device's rate holds and only the mix moved, or mobile rises while desktop holds.\n\ndiagnose_order: [tracking, calendar, cart-to-checkout, checkout-completion, extra-costs, device-mix]\n\nrelated: [checkout-start-rate, checkout-conversion, add-to-cart-rate, conversion-rate, payment-success-rate]\n\nprose:\n  why_it_matters: >-\n    About 70 of every 100 carts are abandoned on the average store, by Baymard Institute's\n    average of dozens of studies, and many of those shoppers were only browsing. The part a store\n    can win back is the rest: extra costs shown late, forced accounts, slow delivery and\n    checkouts that ask too much. At Northwind, with 40,000 carts a week, one point of\n    abandonment is about 400 orders.\n  pitfalls:\n    - Cart abandonment is not checkout abandonment. One minus checkout conversion counts only shoppers who started checkout and reads far lower; comparing either with the other's benchmark is a common mistake.\n    - This spec compares carts and orders in aggregate, as Baymard does, so a shopper who adds on Monday and buys on Thursday in a new session counts once on each side and nets out.\n    - Orders placed without an add-to-cart, such as buy-now buttons, reorder links and subscription renewals, pull the rate down. Send product_added for them or exclude them.\n    - Mobile carts are usually abandoned more often than desktop carts, so a rise in mobile share lifts the rate with no change in the store. Split by device before blaming checkout.\n    - The week before a big sale people fill carts and wait. Compare that week with the same week last year, not the week before.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"cart-abandonment-rate","name":"Cart abandonment rate","aliases":["Cart abandonment","Shopping cart abandonment rate","Abandoned cart rate"],"family":"conversion","kind":"rate","polarity":"down-is-good","definition":{"one_line":"The share of shopping carts that never become a paid order, by Baymard's definition of one minus orders over carts.","formula":"1 − sessions with a paid order ÷ sessions that added to cart, both counted in the same week"},"events":[{"name":"product_added","description":"An item added to the cart from any button, confirmed by the cart, not the click.","also_called":["add_to_cart","Product Added","product_added_to_cart"],"properties":[{"name":"product_id","description":"The product added."},{"name":"quantity","description":"Units added in this action."}]},{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."}]}],"numerator":{"label":"Sessions that added to cart","aggregate":"unique_sessions","event":"product_added"},"subtract":{"label":"Sessions with a paid order","aggregate":"unique_sessions","event":"order_completed"},"denominator":{"label":"Sessions that added to cart","aggregate":"unique_sessions","event":"product_added"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"carts a week","typical":0.7,"reference_volumes":[500,2000,10000,40000]},"example":{"business":"store","level":0.67,"volume":40000,"trend":-0.03,"season":-0.5},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Is a duplicate order event, or a missing add-to-cart event on one platform, shrinking the gap?","yes":"Orders recorded exceed orders in the payment processor, or adds fall on one device while orders hold."},"spiked":{"check":"Did an add-to-cart event start firing twice, or did order events stop being recorded?","yes":"Carts rise without checkout starts following, or recorded orders fall below the processor's count."}},{"id":"calendar","label":"Sale calendar","feed":"shopping","dropped":{"check":"Is this a sale week, when carts that were parked the week before finally convert?","yes":"Orders rise faster than carts, and the same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is it the week before a sale, when shoppers fill carts and wait for the discount?","yes":"Carts rise while orders hold, and the same week last year shows the same rise."}},{"id":"cart-to-checkout","label":"Cart to checkout","metric":"checkout-start-rate","dropped":{"check":"Did more carts move on to checkout, after a cart page or shipping message change?","yes":"Checkout start rate rises by about as much as abandonment falls."},"spiked":{"check":"Did fewer carts reach checkout, from a cart page change, a surprise cost or a broken button?","yes":"Checkout start rate falls while checkout completion holds."}},{"id":"checkout-completion","label":"Checkout completion","metric":"checkout-conversion","feed":"stripe","dropped":{"check":"Did more started checkouts finish, after a checkout fix or a payment method launch?","yes":"Checkout conversion rises while checkout starts hold."},"spiked":{"check":"Did more checkouts fail at shipping, account creation or payment?","yes":"Checkout conversion falls while checkout starts hold; one step or one payment method explains most of it."}},{"id":"extra-costs","label":"Shipping, tax and fees","dropped":{"check":"Did a free-shipping offer, a lower threshold or a clearer delivery date go live?","yes":"Fewer exits at the shipping step from the day it launched."},"spiked":{"check":"Did shipping prices, thresholds, duties or fees shown late in checkout change?","yes":"Exits concentrate on the shipping step, starting the day the change shipped."}},{"id":"device-mix","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Did desktop take a larger share of carts, or did mobile abandonment fall?","yes":"Each device's rate holds and the mix moved, or mobile falls after a release."},"spiked":{"check":"Did mobile take a larger share of carts, or did mobile abandonment rise on its own?","yes":"Each device's rate holds and only the mix moved, or mobile rises while desktop holds."}}],"diagnose_order":["tracking","calendar","cart-to-checkout","checkout-completion","extra-costs","device-mix"],"related":["checkout-start-rate","checkout-conversion","add-to-cart-rate","conversion-rate","payment-success-rate"],"prose":{"why_it_matters":"About 70 of every 100 carts are abandoned on the average store, by Baymard Institute's average of dozens of studies, and many of those shoppers were only browsing. The part a store can win back is the rest: extra costs shown late, forced accounts, slow delivery and checkouts that ask too much. At Northwind, with 40,000 carts a week, one point of abandonment is about 400 orders.","pitfalls":["Cart abandonment is not checkout abandonment. One minus checkout conversion counts only shoppers who started checkout and reads far lower; comparing either with the other's benchmark is a common mistake.","This spec compares carts and orders in aggregate, as Baymard does, so a shopper who adds on Monday and buys on Thursday in a new session counts once on each side and nets out.","Orders placed without an add-to-cart, such as buy-now buttons, reorder links and subscription renewals, pull the rate down. Send product_added for them or exclude them.","Mobile carts are usually abandoned more often than desktop carts, so a rise in mobile share lifts the rate with no change in the store. Split by device before blaming checkout.","The week before a big sale people fill carts and wait. Compare that week with the same week last year, not the week before."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "checkout-conversion": { yaml: "id: checkout-conversion\nname: Checkout conversion\naliases:\n  - Checkout completion rate\n  - Checkout conversion rate\n  - Checkout success rate\nfamily: conversion\ncatalog_id: checkout_completion_rate\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of sessions that started checkout and went on to place a paid order, both counted in the same week.\n  formula: Sessions with a paid order ÷ sessions that started checkout\n\nevents:\n  - name: checkout_started\n    description: The first checkout step rendered, before shipping or payment details.\n    also_called: [begin_checkout, Checkout Started, checkout_initiated]\n    properties:\n      - name: checkout_id\n        description: One id per checkout attempt, so reloads don't count twice.\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n\nnumerator:\n  label: Sessions with a paid order\n  aggregate: unique_sessions\n  event: order_completed\ndenominator:\n  label: Sessions that started checkout\n  aggregate: unique_sessions\n  event: checkout_started\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: checkouts started a week\n  typical: 0.62\n\nexample:\n  business: store\n  level: 0.63\n  volume: 20900\n  trend: 0.02\n  season: 0.5\n\ndrivers:\n  - id: payment-failures\n    label: Payment failures\n    metric: payment-success-rate\n    feed: stripe\n    dropped:\n      check: Did payment success fall, and is it one gateway, card brand or wallet?\n      yes: Declines or errors rise for one processor or method while the others hold.\n    spiked:\n      check: Did a payment problem from the week before just clear?\n      yes: Payment success returns to its usual level and conversion recovers with it.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the drop on one device type only?\n      yes: Mobile falls several points while desktop is flat, which points at a release or layout bug.\n    spiked:\n      check: Is the rise on one device type only?\n      yes: One device jumps after a release; confirm it isn't a tracking change before crediting it.\n  - id: shipping-and-fees\n    label: Shipping cost and delivery dates\n    dropped:\n      check: Did shipping prices, thresholds or delivery promises change this week?\n      yes: Drop-off concentrates on the shipping step, starting the day the change shipped.\n    spiked:\n      check: Did a free-shipping threshold or faster delivery promise go live?\n      yes: Fewer exits at the shipping step from the day it launched.\n  - id: discount-codes\n    label: Discount codes\n    metric: promo-code-usage-rate\n    dropped:\n      check: Did a popular code expire, or did a coupon site start listing codes that fail?\n      yes: More sessions enter a code field and leave after an invalid-code message.\n    spiked:\n      check: Is a sale or a leaked code pushing people through?\n      yes: Code usage jumps and order value per order falls.\n  - id: traffic-mix\n    label: Who reached checkout\n    metric: checkout-start-rate\n    breakdown: utm_source\n    dropped:\n      check: Did more low-intent visitors reach checkout, for example from a new campaign?\n      yes: Checkout starts rise from one source whose completion is far below the rest.\n    spiked:\n      check: Did fewer but more committed visitors reach checkout?\n      yes: Checkout starts fall while completion rises; orders barely move.\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did an event, consent banner or tag manager change stop orders being recorded?\n      yes: Orders in the payment processor hold steady while recorded orders fall.\n    spiked:\n      check: Is a duplicate order event or a missing checkout event inflating the rate?\n      yes: Orders recorded exceed orders in the processor, or checkout starts drop to near zero on one platform.\n\ndiagnose_order: [tracking, payment-failures, device-split, shipping-and-fees, discount-codes, traffic-mix]\n\nrelated: [checkout-start-rate, payment-success-rate, conversion-rate, cart-abandonment-rate, add-to-cart-rate]\n\nprose:\n  why_it_matters: >-\n    Checkout is the last step a store controls, so a change here is rarely about demand and\n    almost always about something the team shipped, a partner that broke, or a price the\n    shopper saw late. At Northwind's 20,900 checkout sessions a week, a one-point drop is\n    about 210 lost orders, every week, until someone finds it.\n  pitfalls:\n    - Counting the thank-you page instead of a server-side order event double counts reloads and misses orders paid by redirect methods.\n    - Mixing checkout attempts and sessions in one ratio skews it whenever shoppers restart checkout. Pick one unit for both sides; this spec uses sessions.\n    - Volume decides what counts as a move. At 1,000 checkout sessions a week, a swing of up to about 4 points is chance; at Northwind's 20,900 it is under 1 point.\n    - Black Friday week brings different intent from the week before. Compare it with last year's Black Friday week instead.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"checkout-conversion","name":"Checkout conversion","aliases":["Checkout completion rate","Checkout conversion rate","Checkout success rate"],"family":"conversion","catalog_id":"checkout_completion_rate","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of sessions that started checkout and went on to place a paid order, both counted in the same week.","formula":"Sessions with a paid order ÷ sessions that started checkout"},"events":[{"name":"checkout_started","description":"The first checkout step rendered, before shipping or payment details.","also_called":["begin_checkout","Checkout Started","checkout_initiated"],"properties":[{"name":"checkout_id","description":"One id per checkout attempt, so reloads don't count twice."}]},{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."},{"name":"total","description":"Order value after discounts, before tax and shipping."}]}],"numerator":{"label":"Sessions with a paid order","aggregate":"unique_sessions","event":"order_completed"},"denominator":{"label":"Sessions that started checkout","aggregate":"unique_sessions","event":"checkout_started"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"checkouts started a week","typical":0.62},"example":{"business":"store","level":0.63,"volume":20900,"trend":0.02,"season":0.5},"drivers":[{"id":"payment-failures","label":"Payment failures","metric":"payment-success-rate","feed":"stripe","dropped":{"check":"Did payment success fall, and is it one gateway, card brand or wallet?","yes":"Declines or errors rise for one processor or method while the others hold."},"spiked":{"check":"Did a payment problem from the week before just clear?","yes":"Payment success returns to its usual level and conversion recovers with it."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the drop on one device type only?","yes":"Mobile falls several points while desktop is flat, which points at a release or layout bug."},"spiked":{"check":"Is the rise on one device type only?","yes":"One device jumps after a release; confirm it isn't a tracking change before crediting it."}},{"id":"shipping-and-fees","label":"Shipping cost and delivery dates","dropped":{"check":"Did shipping prices, thresholds or delivery promises change this week?","yes":"Drop-off concentrates on the shipping step, starting the day the change shipped."},"spiked":{"check":"Did a free-shipping threshold or faster delivery promise go live?","yes":"Fewer exits at the shipping step from the day it launched."}},{"id":"discount-codes","label":"Discount codes","metric":"promo-code-usage-rate","dropped":{"check":"Did a popular code expire, or did a coupon site start listing codes that fail?","yes":"More sessions enter a code field and leave after an invalid-code message."},"spiked":{"check":"Is a sale or a leaked code pushing people through?","yes":"Code usage jumps and order value per order falls."}},{"id":"traffic-mix","label":"Who reached checkout","metric":"checkout-start-rate","breakdown":"utm_source","dropped":{"check":"Did more low-intent visitors reach checkout, for example from a new campaign?","yes":"Checkout starts rise from one source whose completion is far below the rest."},"spiked":{"check":"Did fewer but more committed visitors reach checkout?","yes":"Checkout starts fall while completion rises; orders barely move."}},{"id":"tracking","label":"Tracking change","dropped":{"check":"Did an event, consent banner or tag manager change stop orders being recorded?","yes":"Orders in the payment processor hold steady while recorded orders fall."},"spiked":{"check":"Is a duplicate order event or a missing checkout event inflating the rate?","yes":"Orders recorded exceed orders in the processor, or checkout starts drop to near zero on one platform."}}],"diagnose_order":["tracking","payment-failures","device-split","shipping-and-fees","discount-codes","traffic-mix"],"related":["checkout-start-rate","payment-success-rate","conversion-rate","cart-abandonment-rate","add-to-cart-rate"],"prose":{"why_it_matters":"Checkout is the last step a store controls, so a change here is rarely about demand and almost always about something the team shipped, a partner that broke, or a price the shopper saw late. At Northwind's 20,900 checkout sessions a week, a one-point drop is about 210 lost orders, every week, until someone finds it.","pitfalls":["Counting the thank-you page instead of a server-side order event double counts reloads and misses orders paid by redirect methods.","Mixing checkout attempts and sessions in one ratio skews it whenever shoppers restart checkout. Pick one unit for both sides; this spec uses sessions.","Volume decides what counts as a move. At 1,000 checkout sessions a week, a swing of up to about 4 points is chance; at Northwind's 20,900 it is under 1 point.","Black Friday week brings different intent from the week before. Compare it with last year's Black Friday week instead."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "checkout-start-rate": { yaml: "id: checkout-start-rate\nname: Checkout start rate\naliases:\n  - Checkout initiation rate\n  - Cart to checkout rate\n  - Reached checkout rate\nfamily: conversion\ncatalog_id: checkout_start_rate\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of sessions with a cart that went on to start checkout, the step where a cart becomes a decision to buy.\n  formula: Sessions that started checkout ÷ sessions that added to cart\n\nevents:\n  - name: product_added\n    description: An item added to the cart from any button, confirmed by the cart, not the click.\n    also_called: [add_to_cart, Product Added, product_added_to_cart]\n    properties:\n      - name: product_id\n        description: The product added.\n  - name: checkout_started\n    description: The first checkout step rendered, before shipping or payment details.\n    also_called: [begin_checkout, Checkout Started, checkout_initiated]\n    properties:\n      - name: checkout_id\n        description: One id per checkout attempt, so reloads don't count twice.\n\nnumerator:\n  label: Sessions that started checkout\n  aggregate: unique_sessions\n  event: checkout_started\ndenominator:\n  label: Sessions that added to cart\n  aggregate: unique_sessions\n  event: product_added\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: carts a week\n  typical: 0.5\n  reference_volumes: [500, 2000, 10000, 40000]\n\nexample:\n  business: store\n  level: 0.52\n  volume: 40000\n  trend: 0.01\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a checkout app, domain or express-pay change stop checkout_started firing for some shoppers?\n      yes: Orders hold while checkout starts fall, often for one wallet or one device.\n    spiked:\n      check: Is checkout_started firing twice, or when the cart drawer opens rather than when checkout loads?\n      yes: Checkout starts rise while orders don't, or starts per session jump on a release day.\n  - id: calendar\n    label: Sale calendar\n    feed: shopping\n    dropped:\n      check: Is it the week before a sale, when shoppers park items in the cart and wait?\n      yes: Carts rise while checkout starts hold, and the same week last year shows the same dip.\n    spiked:\n      check: Is this a sale or holiday week, when parked carts move to checkout?\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: cart-intent\n    label: How easily people add to cart\n    metric: add-to-cart-rate\n    dropped:\n      check: Did add-to-cart rate jump from looser intent, such as a quick-add launch or a free gift for adding?\n      yes: Carts rise while checkout starts hold, so the rate falls with no loss of orders.\n    spiked:\n      check: Did add-to-cart rate fall, leaving only the most committed carts?\n      yes: Carts fall while checkout starts hold; check orders before celebrating.\n  - id: cart-costs\n    label: Costs shown in the cart\n    dropped:\n      check: Did the cart start showing shipping costs, a minimum order or a higher free-shipping threshold?\n      yes: The drop starts on the day the cart message changed, on every device.\n    spiked:\n      check: Did a free-shipping offer or a lower threshold go live in the cart?\n      yes: The rise starts on the launch day and orders follow.\n  - id: express-checkout\n    label: Express and wallet buttons\n    dropped:\n      check: Did Shop Pay, Apple Pay or PayPal buttons disappear from the cart or move below the fold?\n      yes: Wallet checkouts fall while card checkouts hold, from the day of a theme or app change.\n    spiked:\n      check: Did express buttons start sending shoppers from product pages straight to checkout?\n      yes: Sessions start checkout without an add-to-cart event, so the rate rises with no change in carts.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the drop on one device type only, such as a checkout button hidden on small screens?\n      yes: Mobile falls several points while desktop is flat, starting on a release day.\n    spiked:\n      check: Is the rise on one device type only?\n      yes: One device jumps after a release; confirm it isn't a tracking change before crediting it.\n\ndiagnose_order: [tracking, calendar, cart-intent, cart-costs, express-checkout, device-split]\n\nrelated: [add-to-cart-rate, checkout-conversion, cart-abandonment-rate, conversion-rate, promo-code-usage-rate]\n\nprose:\n  why_it_matters: >-\n    Checkout start rate shows whether a cart turns into a decision to buy. It is where surprise\n    costs, a cart that buries its button or a missing wallet show up, well before payment. At\n    Northwind, with about 40,000 carts a week, one point is 400 checkouts and roughly 250 orders.\n  pitfalls:\n    - Express buttons on product pages skip the cart, so those sessions start checkout without an add-to-cart and lift the rate. Track them as an add or read them separately.\n    - Cart drawers make views of the cart page meaningless; this spec uses the add-to-cart and checkout events, never page views of /cart.\n    - Counting checkout starts instead of sessions double counts shoppers who go back to edit the cart and start again. This spec counts sessions on both sides.\n    - A rise in add-to-cart rate often lowers this rate with no harm done. Read the two together and judge them by orders.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"checkout-start-rate","name":"Checkout start rate","aliases":["Checkout initiation rate","Cart to checkout rate","Reached checkout rate"],"family":"conversion","catalog_id":"checkout_start_rate","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of sessions with a cart that went on to start checkout, the step where a cart becomes a decision to buy.","formula":"Sessions that started checkout ÷ sessions that added to cart"},"events":[{"name":"product_added","description":"An item added to the cart from any button, confirmed by the cart, not the click.","also_called":["add_to_cart","Product Added","product_added_to_cart"],"properties":[{"name":"product_id","description":"The product added."}]},{"name":"checkout_started","description":"The first checkout step rendered, before shipping or payment details.","also_called":["begin_checkout","Checkout Started","checkout_initiated"],"properties":[{"name":"checkout_id","description":"One id per checkout attempt, so reloads don't count twice."}]}],"numerator":{"label":"Sessions that started checkout","aggregate":"unique_sessions","event":"checkout_started"},"denominator":{"label":"Sessions that added to cart","aggregate":"unique_sessions","event":"product_added"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"carts a week","typical":0.5,"reference_volumes":[500,2000,10000,40000]},"example":{"business":"store","level":0.52,"volume":40000,"trend":0.01},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a checkout app, domain or express-pay change stop checkout_started firing for some shoppers?","yes":"Orders hold while checkout starts fall, often for one wallet or one device."},"spiked":{"check":"Is checkout_started firing twice, or when the cart drawer opens rather than when checkout loads?","yes":"Checkout starts rise while orders don't, or starts per session jump on a release day."}},{"id":"calendar","label":"Sale calendar","feed":"shopping","dropped":{"check":"Is it the week before a sale, when shoppers park items in the cart and wait?","yes":"Carts rise while checkout starts hold, and the same week last year shows the same dip."},"spiked":{"check":"Is this a sale or holiday week, when parked carts move to checkout?","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"cart-intent","label":"How easily people add to cart","metric":"add-to-cart-rate","dropped":{"check":"Did add-to-cart rate jump from looser intent, such as a quick-add launch or a free gift for adding?","yes":"Carts rise while checkout starts hold, so the rate falls with no loss of orders."},"spiked":{"check":"Did add-to-cart rate fall, leaving only the most committed carts?","yes":"Carts fall while checkout starts hold; check orders before celebrating."}},{"id":"cart-costs","label":"Costs shown in the cart","dropped":{"check":"Did the cart start showing shipping costs, a minimum order or a higher free-shipping threshold?","yes":"The drop starts on the day the cart message changed, on every device."},"spiked":{"check":"Did a free-shipping offer or a lower threshold go live in the cart?","yes":"The rise starts on the launch day and orders follow."}},{"id":"express-checkout","label":"Express and wallet buttons","dropped":{"check":"Did Shop Pay, Apple Pay or PayPal buttons disappear from the cart or move below the fold?","yes":"Wallet checkouts fall while card checkouts hold, from the day of a theme or app change."},"spiked":{"check":"Did express buttons start sending shoppers from product pages straight to checkout?","yes":"Sessions start checkout without an add-to-cart event, so the rate rises with no change in carts."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the drop on one device type only, such as a checkout button hidden on small screens?","yes":"Mobile falls several points while desktop is flat, starting on a release day."},"spiked":{"check":"Is the rise on one device type only?","yes":"One device jumps after a release; confirm it isn't a tracking change before crediting it."}}],"diagnose_order":["tracking","calendar","cart-intent","cart-costs","express-checkout","device-split"],"related":["add-to-cart-rate","checkout-conversion","cart-abandonment-rate","conversion-rate","promo-code-usage-rate"],"prose":{"why_it_matters":"Checkout start rate shows whether a cart turns into a decision to buy. It is where surprise costs, a cart that buries its button or a missing wallet show up, well before payment. At Northwind, with about 40,000 carts a week, one point is 400 checkouts and roughly 250 orders.","pitfalls":["Express buttons on product pages skip the cart, so those sessions start checkout without an add-to-cart and lift the rate. Track them as an add or read them separately.","Cart drawers make views of the cart page meaningless; this spec uses the add-to-cart and checkout events, never page views of /cart.","Counting checkout starts instead of sessions double counts shoppers who go back to edit the cart and start again. This spec counts sessions on both sides.","A rise in add-to-cart rate often lowers this rate with no harm done. Read the two together and judge them by orders."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "churned-mrr": { yaml: "id: churned-mrr\nname: Churned MRR\naliases:\n  - Churned revenue\n  - Lost MRR\n  - Cancelled MRR\n  - Churn MRR\nfamily: subscription\nkind: currency\npolarity: down-is-good\n\ndefinition:\n  one_line: The monthly recurring revenue lost this week from subscriptions that stopped being billed, at the amount they were paying before they ended.\n  formula: Sum of the last monthly amounts of subscriptions that ended this week, voluntary or for failed payment; downgrades are contraction and count separately\n\nevents:\n  - name: subscription_canceled\n    description: A subscription stopped being billed, at the end of its paid period or after dunning gave up; not the moment someone clicks cancel.\n    also_called: [customer.subscription.deleted, Subscription Cancelled, subscription_ended]\n    properties:\n      - name: subscription_id\n        description: The billing system's subscription id.\n      - name: mrr\n        description: The monthly amount the subscription was paying before it ended, after discounts, before tax.\n      - name: plan\n        description: The plan it was on when it ended.\n      - name: reason\n        description: voluntary or payment_failed, when the billing system records why it ended.\n\nnumerator:\n  label: Churned MRR\n  aggregate: sum\n  event: subscription_canceled\n  property: mrr\n\nnoise:\n  type: compound\n  cv: 0.9\n  min_denominator: 8\n  volume_unit: cancellations a week\n  typical: 1100\n  reference_volumes: [10, 40, 150, 600]\n\nexample:\n  business: saas\n  level: 1115\n  volume: 11\n  trend: 0.25\n\ndrivers:\n  - id: billing-sync\n    label: Billing sync\n    dropped:\n      check: Did cancellations stop reaching the event stream, for example from a broken webhook?\n      yes: The billing system shows more ended subscriptions this week than there are subscription_canceled events.\n    spiked:\n      check: Did a cleanup cancel many old unpaid subscriptions at once?\n      yes: A batch of cancellations lands on one day, mostly subscriptions that had been past due for weeks.\n  - id: failed-payments\n    label: Failed payments\n    feed: stripe\n    breakdown: reason\n    dropped:\n      check: Did a dunning change, retry schedule or card updater recover payments that used to fail?\n      yes: Payment-failed cancellations fall and recovered invoices rise, while voluntary cancellations hold.\n    spiked:\n      check: Did more subscriptions end for failed payments, from expiring cards, a dunning change or a processor incident?\n      yes: Payment-failed cancellations rise while voluntary ones hold; Stripe shows an incident or a rise in declines.\n  - id: renewal-cohort\n    label: Renewals due\n    dropped:\n      check: Did fewer annual or quarterly plans come up for renewal this week?\n      yes: Renewals due this week are below usual; churn returns to normal when they are.\n    spiked:\n      check: Did a large group of annual plans reach their renewal date?\n      yes: Cancellations cluster on subscriptions that started one year ago, often from a launch month.\n  - id: plan-split\n    label: Plan and account size\n    breakdown: plan\n    dropped:\n      check: Is the fall concentrated in one plan, or is the week simply missing one large loss?\n      yes: One plan's cancellations fall to near zero; check whether a change there, such as new onboarding, explains it.\n    spiked:\n      check: Is one plan, or one large account, behind most of the loss?\n      yes: One plan or a single customer is most of the week's churned MRR.\n  - id: price-and-offers\n    label: Price changes and retention offers\n    dropped:\n      check: Did a retention offer, pause option or discount in the cancel flow go live?\n      yes: Customers who reach the cancel flow accept the offer instead; watch whether they leave when it ends.\n    spiked:\n      check: Did a price increase, or a competitor's launch or discount, reach your customers?\n      yes: Cancellations rise among customers on the changed plans, starting the week the notices went out.\n  - id: product-quality\n    label: Product problems\n    metric: error-rate\n    dropped:\n      check: Did a reliability fix or a long-requested feature ship a month or two ago?\n      yes: Cancellation reasons that cited the fixed problem fall away.\n    spiked:\n      check: Did an outage, a bug or a removed feature give customers a reason to leave?\n      yes: Cancellation reasons cite one problem, starting the week after it.\n\ndiagnose_order: [billing-sync, failed-payments, renewal-cohort, plan-split, price-and-offers, product-quality]\n\nrelated: [mrr, logo-churn-rate, gross-revenue-retention, net-new-mrr, quick-ratio]\n\nprose:\n  why_it_matters: >-\n    Churned MRR is the outflow that decides how hard everything else has to work: a SaaS losing\n    2% of MRR a month must replace about a fifth of its revenue every year before it grows at all.\n    Week to week it is lumpy, driven by renewal dates, expiring cards and a few large accounts,\n    so read which subscriptions ended before reading how much they paid.\n  pitfalls:\n    - Booking churn when the customer clicks cancel, rather than when the paid period ends, moves it weeks ahead of the revenue actually stopping. This spec counts the week billing stops.\n    - Failed-payment churn is a billing problem, not a product verdict. Report it apart from voluntary churn, because dunning and card updaters can recover much of it.\n    - Downgrades are contraction, not churn. Folding them in hides whether customers are leaving or paying less.\n    - A customer who leaves and comes back within the month nets to zero in monthly reports but shows as churn, then new business, in weekly ones.\n    - In B2B, a few accounts can be most of a week's churned MRR. Read the list before the total.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"churned-mrr","name":"Churned MRR","aliases":["Churned revenue","Lost MRR","Cancelled MRR","Churn MRR"],"family":"subscription","kind":"currency","polarity":"down-is-good","definition":{"one_line":"The monthly recurring revenue lost this week from subscriptions that stopped being billed, at the amount they were paying before they ended.","formula":"Sum of the last monthly amounts of subscriptions that ended this week, voluntary or for failed payment; downgrades are contraction and count separately"},"events":[{"name":"subscription_canceled","description":"A subscription stopped being billed, at the end of its paid period or after dunning gave up; not the moment someone clicks cancel.","also_called":["customer.subscription.deleted","Subscription Cancelled","subscription_ended"],"properties":[{"name":"subscription_id","description":"The billing system's subscription id."},{"name":"mrr","description":"The monthly amount the subscription was paying before it ended, after discounts, before tax."},{"name":"plan","description":"The plan it was on when it ended."},{"name":"reason","description":"voluntary or payment_failed, when the billing system records why it ended."}]}],"numerator":{"label":"Churned MRR","aggregate":"sum","event":"subscription_canceled","property":"mrr"},"noise":{"type":"compound","cv":0.9,"min_denominator":8,"volume_unit":"cancellations a week","typical":1100,"reference_volumes":[10,40,150,600]},"example":{"business":"saas","level":1115,"volume":11,"trend":0.25},"drivers":[{"id":"billing-sync","label":"Billing sync","dropped":{"check":"Did cancellations stop reaching the event stream, for example from a broken webhook?","yes":"The billing system shows more ended subscriptions this week than there are subscription_canceled events."},"spiked":{"check":"Did a cleanup cancel many old unpaid subscriptions at once?","yes":"A batch of cancellations lands on one day, mostly subscriptions that had been past due for weeks."}},{"id":"failed-payments","label":"Failed payments","feed":"stripe","breakdown":"reason","dropped":{"check":"Did a dunning change, retry schedule or card updater recover payments that used to fail?","yes":"Payment-failed cancellations fall and recovered invoices rise, while voluntary cancellations hold."},"spiked":{"check":"Did more subscriptions end for failed payments, from expiring cards, a dunning change or a processor incident?","yes":"Payment-failed cancellations rise while voluntary ones hold; Stripe shows an incident or a rise in declines."}},{"id":"renewal-cohort","label":"Renewals due","dropped":{"check":"Did fewer annual or quarterly plans come up for renewal this week?","yes":"Renewals due this week are below usual; churn returns to normal when they are."},"spiked":{"check":"Did a large group of annual plans reach their renewal date?","yes":"Cancellations cluster on subscriptions that started one year ago, often from a launch month."}},{"id":"plan-split","label":"Plan and account size","breakdown":"plan","dropped":{"check":"Is the fall concentrated in one plan, or is the week simply missing one large loss?","yes":"One plan's cancellations fall to near zero; check whether a change there, such as new onboarding, explains it."},"spiked":{"check":"Is one plan, or one large account, behind most of the loss?","yes":"One plan or a single customer is most of the week's churned MRR."}},{"id":"price-and-offers","label":"Price changes and retention offers","dropped":{"check":"Did a retention offer, pause option or discount in the cancel flow go live?","yes":"Customers who reach the cancel flow accept the offer instead; watch whether they leave when it ends."},"spiked":{"check":"Did a price increase, or a competitor's launch or discount, reach your customers?","yes":"Cancellations rise among customers on the changed plans, starting the week the notices went out."}},{"id":"product-quality","label":"Product problems","metric":"error-rate","dropped":{"check":"Did a reliability fix or a long-requested feature ship a month or two ago?","yes":"Cancellation reasons that cited the fixed problem fall away."},"spiked":{"check":"Did an outage, a bug or a removed feature give customers a reason to leave?","yes":"Cancellation reasons cite one problem, starting the week after it."}}],"diagnose_order":["billing-sync","failed-payments","renewal-cohort","plan-split","price-and-offers","product-quality"],"related":["mrr","logo-churn-rate","gross-revenue-retention","net-new-mrr","quick-ratio"],"prose":{"why_it_matters":"Churned MRR is the outflow that decides how hard everything else has to work: a SaaS losing 2% of MRR a month must replace about a fifth of its revenue every year before it grows at all. Week to week it is lumpy, driven by renewal dates, expiring cards and a few large accounts, so read which subscriptions ended before reading how much they paid.","pitfalls":["Booking churn when the customer clicks cancel, rather than when the paid period ends, moves it weeks ahead of the revenue actually stopping. This spec counts the week billing stops.","Failed-payment churn is a billing problem, not a product verdict. Report it apart from voluntary churn, because dunning and card updaters can recover much of it.","Downgrades are contraction, not churn. Folding them in hides whether customers are leaving or paying less.","A customer who leaves and comes back within the month nets to zero in monthly reports but shows as churn, then new business, in weekly ones.","In B2B, a few accounts can be most of a week's churned MRR. Read the list before the total."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "contribution-margin": { yaml: "id: contribution-margin\nname: Contribution margin\naliases:\n  - Contribution profit\n  - Contribution after marketing\n  - CM3\nfamily: revenue\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: What is left of the week's net revenue after the cost of the goods sold and the ad spend that sold them.\n  formula: Net revenue − cost of goods − ad spend, by week (subtract fulfilment and payment fees too when you record them)\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n      - name: cost_of_goods\n        description: The landed cost of the order's items, purchase price plus inbound freight and duties.\n  - name: order_refunded\n    description: A refund issued against an earlier order, full or partial.\n    also_called: [refund, Order Refunded, charge.refunded]\n    properties:\n      - name: amount\n        description: The refunded amount, excluding tax and shipping.\n  - name: ad_spend\n    description: One row per channel per day, synced from each ad platform's reporting API.\n    also_called: [Ad Spend, ad_performance, campaign_daily_stats]\n    properties:\n      - name: channel\n        description: The platform or channel, such as meta, google or tiktok.\n      - name: spend\n        description: Spend for the day, in the store's currency.\n\nnumerator:\n  label: Order revenue\n  aggregate: sum\n  event: order_completed\n  property: total\n\nqueries:\n  hogql: |-\n    -- Contribution margin per week: net revenue (order totals − refunds) − cost of goods − ad spend. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(m.net_revenue, 0) AS net_revenue,\n      coalesce(m.cost_of_goods, 0) AS cost_of_goods,\n      coalesce(m.ad_spend, 0) AS ad_spend,\n      net_revenue - cost_of_goods - ad_spend AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT\n        toMonday(toTimeZone(timestamp, 'UTC')) AS week,\n        coalesce(sumIf(toFloat(properties.total), event = 'order_completed'), 0)\n          - coalesce(sumIf(toFloat(properties.amount), event = 'order_refunded'), 0) AS net_revenue,\n        sumIf(toFloat(properties.cost_of_goods), event = 'order_completed') AS cost_of_goods,\n        sumIf(toFloat(properties.spend), event = 'ad_spend') AS ad_spend\n      FROM events\n      WHERE event IN ('order_completed', 'order_refunded', 'ad_spend')\n        AND timestamp >= now() - toIntervalWeek(27)\n        AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n      GROUP BY week\n    ) AS m ON m.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Contribution margin per week: net revenue (order totals − refunds) − cost of goods − ad spend. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    weekly AS (\n      SELECT\n        date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n        coalesce(sum(CASE WHEN properties->>'total' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'total')::numeric END) FILTER (WHERE event_name = 'order_completed'), 0)\n          - coalesce(sum(CASE WHEN properties->>'amount' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'amount')::numeric END) FILTER (WHERE event_name = 'order_refunded'), 0) AS net_revenue,\n        sum(CASE WHEN properties->>'cost_of_goods' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'cost_of_goods')::numeric END) FILTER (WHERE event_name = 'order_completed') AS cost_of_goods,\n        sum(CASE WHEN properties->>'spend' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'spend')::numeric END) FILTER (WHERE event_name = 'ad_spend') AS ad_spend\n      FROM events\n      WHERE event_name IN ('order_completed', 'order_refunded', 'ad_spend')\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n      GROUP BY 1\n    ),\n    totals AS (\n      SELECT\n        w.week,\n        coalesce(m.net_revenue, 0) AS net_revenue,\n        coalesce(m.cost_of_goods, 0) AS cost_of_goods,\n        coalesce(m.ad_spend, 0) AS ad_spend\n      FROM weeks AS w\n      LEFT JOIN weekly AS m ON m.week = w.week\n    )\n    SELECT week, net_revenue, cost_of_goods, ad_spend, net_revenue - cost_of_goods - ad_spend AS value\n    FROM totals\n    ORDER BY week;\n  bigquery: |-\n    -- Contribution margin per week: net revenue (order totals − refunds) − cost of goods − ad spend. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    weekly AS (\n      SELECT\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n        COALESCE(SUM(IF(event_name = 'order_completed', SAFE_CAST(JSON_VALUE(properties, '$.total') AS FLOAT64), NULL)), 0)\n          - COALESCE(SUM(IF(event_name = 'order_refunded', SAFE_CAST(JSON_VALUE(properties, '$.amount') AS FLOAT64), NULL)), 0) AS net_revenue,\n        SUM(IF(event_name = 'order_completed', SAFE_CAST(JSON_VALUE(properties, '$.cost_of_goods') AS FLOAT64), NULL)) AS cost_of_goods,\n        SUM(IF(event_name = 'ad_spend', SAFE_CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64), NULL)) AS ad_spend\n      FROM events\n      WHERE event_name IN ('order_completed', 'order_refunded', 'ad_spend')\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY week\n    ),\n    totals AS (\n      SELECT\n        w.week,\n        COALESCE(m.net_revenue, 0) AS net_revenue,\n        COALESCE(m.cost_of_goods, 0) AS cost_of_goods,\n        COALESCE(m.ad_spend, 0) AS ad_spend\n      FROM weeks AS w\n      LEFT JOIN weekly AS m ON m.week = w.week\n    )\n    SELECT week, net_revenue, cost_of_goods, ad_spend, net_revenue - cost_of_goods - ad_spend AS value\n    FROM totals\n    ORDER BY week;\n  snowflake: |-\n    -- Contribution margin per week: net revenue (order totals − refunds) − cost of goods − ad spend. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    weekly AS (\n      SELECT\n        DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n        COALESCE(SUM(IFF(event_name = 'order_completed', TRY_TO_DOUBLE(properties:\"total\"::string), NULL)), 0)\n          - COALESCE(SUM(IFF(event_name = 'order_refunded', TRY_TO_DOUBLE(properties:\"amount\"::string), NULL)), 0) AS net_revenue,\n        SUM(IFF(event_name = 'order_completed', TRY_TO_DOUBLE(properties:\"cost_of_goods\"::string), NULL)) AS cost_of_goods,\n        SUM(IFF(event_name = 'ad_spend', TRY_TO_DOUBLE(properties:\"spend\"::string), NULL)) AS ad_spend\n      FROM events\n      WHERE event_name IN ('order_completed', 'order_refunded', 'ad_spend')\n        AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n      GROUP BY 1\n    ),\n    totals AS (\n      SELECT\n        w.week,\n        COALESCE(m.net_revenue, 0) AS net_revenue,\n        COALESCE(m.cost_of_goods, 0) AS cost_of_goods,\n        COALESCE(m.ad_spend, 0) AS ad_spend\n      FROM weeks AS w\n      LEFT JOIN weekly AS m ON m.week = w.week\n    )\n    SELECT week, net_revenue, cost_of_goods, ad_spend, net_revenue - cost_of_goods - ad_spend AS value\n    FROM totals\n    ORDER BY week;\n\nnoise:\n  type: process\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 100000\n\nexample:\n  business: store\n  level: 363000\n  volume: 13300\n  trend: 0.15\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Spend and cost data\n    dropped:\n      check: Did ad spend sync twice for a platform, or did cost_of_goods change basis?\n      yes: One channel's spend doubles with no change in its ads manager, or cost per unit jumps on one date.\n    spiked:\n      check: Did an ad platform's spend sync fail, or did products start selling without a recorded cost?\n      yes: One channel shows no spend for some days, or orders with no cost_of_goods appear. Fix the data before celebrating.\n  - id: ad-spend\n    label: Ad spend\n    metric: ad-spend\n    feed: ad-platforms\n    dropped:\n      check: Did ad spend rise faster than the revenue it brought, from a budget increase or a new campaign?\n      yes: Spend rises while net revenue rises less, so each extra dollar of spend returns less than a dollar of margin.\n    spiked:\n      check: Did spend fall, from a budget cut, a paused campaign or an ad account problem?\n      yes: Spend falls while revenue holds this week; watch whether new customers fall in the weeks after.\n  - id: net-revenue\n    label: Net revenue\n    metric: net-revenue\n    feed: shopping\n    dropped:\n      check: Did net revenue fall, from fewer orders, smaller orders or more refunds?\n      yes: Net revenue falls while spend and margin hold.\n    spiked:\n      check: Is this a sale or holiday week, or did revenue rise for a reason that will last?\n      yes: Net revenue rises while spend holds; the same week last year shows whether it's the calendar.\n  - id: gross-margin\n    label: Gross margin\n    metric: gross-margin\n    dropped:\n      check: Did discounts, product mix or unit costs lower gross margin?\n      yes: Gross margin falls while revenue and spend hold.\n    spiked:\n      check: Did a sale end or a price rise lift gross margin?\n      yes: Gross margin rises while revenue and spend hold.\n  - id: efficiency\n    label: Marketing efficiency\n    metric: mer\n    dropped:\n      check: Did each ad dollar bring in less revenue, from rising CPMs or tired creative?\n      yes: MER falls while spend holds.\n    spiked:\n      check: Did each ad dollar bring in more revenue, or did a sale lift revenue on the same spend?\n      yes: MER rises while spend holds; check the calendar before crediting the ads.\n  - id: refunds\n    label: Refunds\n    metric: refund-rate\n    dropped:\n      check: Did refunds jump, after a big sale, a bad batch or a delivery problem?\n      yes: Refund rate rises while gross sales and spend hold.\n    spiked:\n      check: Did refunds fall back after an unusual week?\n      yes: Refund rate returns to its usual level and margin recovers with it.\n\ndiagnose_order: [tracking, ad-spend, net-revenue, gross-margin, efficiency, refunds]\n\nrelated: [net-revenue, gross-margin, ad-spend, mer, refund-rate, ncac]\n\nprose:\n  why_it_matters: >-\n    Revenue can grow while the business earns less; contribution margin is the check. It takes\n    away what the goods cost and what the ads that sold them cost, leaving the money that pays\n    for salaries, rent and profit. At Northwind about $1.29M of net revenue leaves roughly\n    $360,000 after about $620,000 of goods and $300,000 of ads, so a 10% rise in ad spend with\n    flat revenue cuts it by about 8%.\n  pitfalls:\n    - Shipping labels, packaging, fulfilment and payment fees are variable costs too. Leaving them out overstates contribution margin; add them as a per-order estimate if you don't record them.\n    - Ad spend is booked on the day it's spent, but the orders it drives can land days later, so a launch week reads low and the next week high. Use two-week sums when spend moves a lot.\n    - When one platform's spend sync fails, contribution margin jumps by that platform's spend. Check that every channel reported spend before celebrating.\n    - Some teams stop before marketing and call that contribution margin. This spec takes ad spend out because that is the number that says whether growth pays.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"contribution-margin","name":"Contribution margin","aliases":["Contribution profit","Contribution after marketing","CM3"],"family":"revenue","kind":"currency","polarity":"up-is-good","definition":{"one_line":"What is left of the week's net revenue after the cost of the goods sold and the ad spend that sold them.","formula":"Net revenue − cost of goods − ad spend, by week (subtract fulfilment and payment fees too when you record them)"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."},{"name":"cost_of_goods","description":"The landed cost of the order's items, purchase price plus inbound freight and duties."}]},{"name":"order_refunded","description":"A refund issued against an earlier order, full or partial.","also_called":["refund","Order Refunded","charge.refunded"],"properties":[{"name":"amount","description":"The refunded amount, excluding tax and shipping."}]},{"name":"ad_spend","description":"One row per channel per day, synced from each ad platform's reporting API.","also_called":["Ad Spend","ad_performance","campaign_daily_stats"],"properties":[{"name":"channel","description":"The platform or channel, such as meta, google or tiktok."},{"name":"spend","description":"Spend for the day, in the store's currency."}]}],"numerator":{"label":"Order revenue","aggregate":"sum","event":"order_completed","property":"total"},"queries":{"hogql":"-- Contribution margin per week: net revenue (order totals − refunds) − cost of goods − ad spend. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(m.net_revenue, 0) AS net_revenue,\n  coalesce(m.cost_of_goods, 0) AS cost_of_goods,\n  coalesce(m.ad_spend, 0) AS ad_spend,\n  net_revenue - cost_of_goods - ad_spend AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT\n    toMonday(toTimeZone(timestamp, 'UTC')) AS week,\n    coalesce(sumIf(toFloat(properties.total), event = 'order_completed'), 0)\n      - coalesce(sumIf(toFloat(properties.amount), event = 'order_refunded'), 0) AS net_revenue,\n    sumIf(toFloat(properties.cost_of_goods), event = 'order_completed') AS cost_of_goods,\n    sumIf(toFloat(properties.spend), event = 'ad_spend') AS ad_spend\n  FROM events\n  WHERE event IN ('order_completed', 'order_refunded', 'ad_spend')\n    AND timestamp >= now() - toIntervalWeek(27)\n    AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n  GROUP BY week\n) AS m ON m.week = w.week\nORDER BY week","postgres":"-- Contribution margin per week: net revenue (order totals − refunds) − cost of goods − ad spend. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nweekly AS (\n  SELECT\n    date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n    coalesce(sum(CASE WHEN properties->>'total' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'total')::numeric END) FILTER (WHERE event_name = 'order_completed'), 0)\n      - coalesce(sum(CASE WHEN properties->>'amount' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'amount')::numeric END) FILTER (WHERE event_name = 'order_refunded'), 0) AS net_revenue,\n    sum(CASE WHEN properties->>'cost_of_goods' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'cost_of_goods')::numeric END) FILTER (WHERE event_name = 'order_completed') AS cost_of_goods,\n    sum(CASE WHEN properties->>'spend' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'spend')::numeric END) FILTER (WHERE event_name = 'ad_spend') AS ad_spend\n  FROM events\n  WHERE event_name IN ('order_completed', 'order_refunded', 'ad_spend')\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n  GROUP BY 1\n),\ntotals AS (\n  SELECT\n    w.week,\n    coalesce(m.net_revenue, 0) AS net_revenue,\n    coalesce(m.cost_of_goods, 0) AS cost_of_goods,\n    coalesce(m.ad_spend, 0) AS ad_spend\n  FROM weeks AS w\n  LEFT JOIN weekly AS m ON m.week = w.week\n)\nSELECT week, net_revenue, cost_of_goods, ad_spend, net_revenue - cost_of_goods - ad_spend AS value\nFROM totals\nORDER BY week;","bigquery":"-- Contribution margin per week: net revenue (order totals − refunds) − cost of goods − ad spend. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nweekly AS (\n  SELECT\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n    COALESCE(SUM(IF(event_name = 'order_completed', SAFE_CAST(JSON_VALUE(properties, '$.total') AS FLOAT64), NULL)), 0)\n      - COALESCE(SUM(IF(event_name = 'order_refunded', SAFE_CAST(JSON_VALUE(properties, '$.amount') AS FLOAT64), NULL)), 0) AS net_revenue,\n    SUM(IF(event_name = 'order_completed', SAFE_CAST(JSON_VALUE(properties, '$.cost_of_goods') AS FLOAT64), NULL)) AS cost_of_goods,\n    SUM(IF(event_name = 'ad_spend', SAFE_CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64), NULL)) AS ad_spend\n  FROM events\n  WHERE event_name IN ('order_completed', 'order_refunded', 'ad_spend')\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY week\n),\ntotals AS (\n  SELECT\n    w.week,\n    COALESCE(m.net_revenue, 0) AS net_revenue,\n    COALESCE(m.cost_of_goods, 0) AS cost_of_goods,\n    COALESCE(m.ad_spend, 0) AS ad_spend\n  FROM weeks AS w\n  LEFT JOIN weekly AS m ON m.week = w.week\n)\nSELECT week, net_revenue, cost_of_goods, ad_spend, net_revenue - cost_of_goods - ad_spend AS value\nFROM totals\nORDER BY week;","snowflake":"-- Contribution margin per week: net revenue (order totals − refunds) − cost of goods − ad spend. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nweekly AS (\n  SELECT\n    DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n    COALESCE(SUM(IFF(event_name = 'order_completed', TRY_TO_DOUBLE(properties:\"total\"::string), NULL)), 0)\n      - COALESCE(SUM(IFF(event_name = 'order_refunded', TRY_TO_DOUBLE(properties:\"amount\"::string), NULL)), 0) AS net_revenue,\n    SUM(IFF(event_name = 'order_completed', TRY_TO_DOUBLE(properties:\"cost_of_goods\"::string), NULL)) AS cost_of_goods,\n    SUM(IFF(event_name = 'ad_spend', TRY_TO_DOUBLE(properties:\"spend\"::string), NULL)) AS ad_spend\n  FROM events\n  WHERE event_name IN ('order_completed', 'order_refunded', 'ad_spend')\n    AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n  GROUP BY 1\n),\ntotals AS (\n  SELECT\n    w.week,\n    COALESCE(m.net_revenue, 0) AS net_revenue,\n    COALESCE(m.cost_of_goods, 0) AS cost_of_goods,\n    COALESCE(m.ad_spend, 0) AS ad_spend\n  FROM weeks AS w\n  LEFT JOIN weekly AS m ON m.week = w.week\n)\nSELECT week, net_revenue, cost_of_goods, ad_spend, net_revenue - cost_of_goods - ad_spend AS value\nFROM totals\nORDER BY week;"},"noise":{"type":"process","min_denominator":50,"volume_unit":"orders a week","typical":100000},"example":{"business":"store","level":363000,"volume":13300,"trend":0.15,"season":1},"drivers":[{"id":"tracking","label":"Spend and cost data","dropped":{"check":"Did ad spend sync twice for a platform, or did cost_of_goods change basis?","yes":"One channel's spend doubles with no change in its ads manager, or cost per unit jumps on one date."},"spiked":{"check":"Did an ad platform's spend sync fail, or did products start selling without a recorded cost?","yes":"One channel shows no spend for some days, or orders with no cost_of_goods appear. Fix the data before celebrating."}},{"id":"ad-spend","label":"Ad spend","metric":"ad-spend","feed":"ad-platforms","dropped":{"check":"Did ad spend rise faster than the revenue it brought, from a budget increase or a new campaign?","yes":"Spend rises while net revenue rises less, so each extra dollar of spend returns less than a dollar of margin."},"spiked":{"check":"Did spend fall, from a budget cut, a paused campaign or an ad account problem?","yes":"Spend falls while revenue holds this week; watch whether new customers fall in the weeks after."}},{"id":"net-revenue","label":"Net revenue","metric":"net-revenue","feed":"shopping","dropped":{"check":"Did net revenue fall, from fewer orders, smaller orders or more refunds?","yes":"Net revenue falls while spend and margin hold."},"spiked":{"check":"Is this a sale or holiday week, or did revenue rise for a reason that will last?","yes":"Net revenue rises while spend holds; the same week last year shows whether it's the calendar."}},{"id":"gross-margin","label":"Gross margin","metric":"gross-margin","dropped":{"check":"Did discounts, product mix or unit costs lower gross margin?","yes":"Gross margin falls while revenue and spend hold."},"spiked":{"check":"Did a sale end or a price rise lift gross margin?","yes":"Gross margin rises while revenue and spend hold."}},{"id":"efficiency","label":"Marketing efficiency","metric":"mer","dropped":{"check":"Did each ad dollar bring in less revenue, from rising CPMs or tired creative?","yes":"MER falls while spend holds."},"spiked":{"check":"Did each ad dollar bring in more revenue, or did a sale lift revenue on the same spend?","yes":"MER rises while spend holds; check the calendar before crediting the ads."}},{"id":"refunds","label":"Refunds","metric":"refund-rate","dropped":{"check":"Did refunds jump, after a big sale, a bad batch or a delivery problem?","yes":"Refund rate rises while gross sales and spend hold."},"spiked":{"check":"Did refunds fall back after an unusual week?","yes":"Refund rate returns to its usual level and margin recovers with it."}}],"diagnose_order":["tracking","ad-spend","net-revenue","gross-margin","efficiency","refunds"],"related":["net-revenue","gross-margin","ad-spend","mer","refund-rate","ncac"],"prose":{"why_it_matters":"Revenue can grow while the business earns less; contribution margin is the check. It takes away what the goods cost and what the ads that sold them cost, leaving the money that pays for salaries, rent and profit. At Northwind about $1.29M of net revenue leaves roughly $360,000 after about $620,000 of goods and $300,000 of ads, so a 10% rise in ad spend with flat revenue cuts it by about 8%.","pitfalls":["Shipping labels, packaging, fulfilment and payment fees are variable costs too. Leaving them out overstates contribution margin; add them as a per-order estimate if you don't record them.","Ad spend is booked on the day it's spent, but the orders it drives can land days later, so a launch week reads low and the next week high. Use two-week sums when spend moves a lot.","When one platform's spend sync fails, contribution margin jumps by that platform's spend. Check that every channel reported spend before celebrating.","Some teams stop before marketing and call that contribution margin. This spec takes ad spend out because that is the number that says whether growth pays."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "conversion-rate": { yaml: "id: conversion-rate\nname: Conversion rate\naliases:\n  - Ecommerce conversion rate\n  - Store conversion rate\n  - Online store conversion rate\n  - Session conversion rate\n  - Purchase conversion rate\nfamily: conversion\ncatalog_id: conversion_rate\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of sessions that end in a paid order, the whole store funnel in one number.\n  formula: Sessions with a paid order ÷ sessions\n\nevents:\n  - name: $pageview\n    description: A page loaded in the browser. Sessions are the distinct session ids across page views.\n    also_called: [page_view, Page Viewed, page_viewed]\n    properties:\n      - name: $session_id\n        description: The browser session; a new one starts after 30 minutes without activity.\n  - name: order_completed\n    description: A paid order confirmed by the server, carrying the browser's session id.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n      - name: $session_id\n        description: The session the order was placed in, passed from the browser to the server.\n\nnumerator:\n  label: Sessions with a paid order\n  aggregate: unique_sessions\n  event: order_completed\ndenominator:\n  label: Sessions\n  aggregate: unique_sessions\n  event: $pageview\n\nnoise:\n  type: binomial\n  min_denominator: 2000\n  volume_unit: sessions a week\n  typical: 0.02\n  reference_volumes: [2000, 10000, 50000, 250000]\n\nexample:\n  business: store\n  level: 0.0206\n  volume: 600000\n  trend: 0.01\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a consent banner, tag manager or checkout change stop orders, or their session ids, being recorded?\n      yes: Orders in the store platform or payment processor hold while orders recorded in analytics fall.\n    spiked:\n      check: Did page views stop being recorded somewhere, shrinking sessions while orders kept recording?\n      yes: Sessions fall with no matching fall in ad clicks or server logs, often on one browser or after a consent change.\n  - id: calendar\n    label: Shopping calendar\n    feed: shopping\n    dropped:\n      check: Was last week a sale, holiday or payday week, or is this the week before one when shoppers wait?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this a sale, holiday or payday week? Compare with the same week last year before crediting the site.\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: traffic-mix\n    label: Who arrived\n    breakdown: utm_source\n    feed: cloudflare\n    dropped:\n      check: Did sessions grow from a low-intent source or from bots, such as broad paid social, a viral post or a crawler?\n      yes: Sessions jump from one source whose conversion is a fraction of the rest, while orders barely move.\n    spiked:\n      check: Did a low-intent source or a bot wave shrink, lifting the rate without more orders?\n      yes: Sessions fall while orders hold. Check orders before celebrating.\n  - id: add-to-cart\n    label: Product pages and carts\n    metric: add-to-cart-rate\n    dropped:\n      check: Did fewer product viewers add to cart, from price, stock or a product page change?\n      yes: Add-to-cart rate falls by about as much as conversion while checkout steps hold.\n    spiked:\n      check: Did more product viewers add to cart, from a sale, a restock or a page change?\n      yes: Add-to-cart rate rises and checkout starts follow it.\n  - id: checkout\n    label: Checkout and payment\n    metric: checkout-conversion\n    feed: stripe\n    dropped:\n      check: Did more started checkouts fail, at shipping, payment or account creation?\n      yes: Checkout conversion falls while add-to-cart holds; one step or one payment method explains most of it.\n    spiked:\n      check: Did a checkout or payment problem from the week before clear?\n      yes: Checkout conversion returns to its usual level and conversion recovers with it.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the drop on one device type only?\n      yes: Mobile falls while desktop is flat, which points at a release, a layout bug or a browser update.\n    spiked:\n      check: Is the rise on one device type only?\n      yes: One device jumps after a release; confirm it isn't a tracking change before crediting it.\n\ndiagnose_order: [tracking, calendar, traffic-mix, add-to-cart, checkout, device-split]\n\nrelated: [sessions, add-to-cart-rate, checkout-conversion, mobile-conversion-rate, revenue-per-session, product-view-rate]\n\nprose:\n  why_it_matters: >-\n    Conversion rate turns traffic into orders, so almost every change to the store shows up in\n    it eventually. At 600,000 sessions a week, a tenth of a point is 600 orders, about $58,000 a\n    week at Northwind's $97 order. It moves with who arrives as much as with the store, so read it\n    beside the traffic mix before crediting or blaming the site.\n  pitfalls:\n    - Orders sent from the server often carry no session id and fall out of the numerator. Pass the browser's session id onto the order event or conversion reads low.\n    - Orders ÷ sessions and sessions with an order ÷ sessions differ when shoppers place two orders in one visit. This spec counts sessions, like Shopify's online store conversion rate.\n    - A new low-intent channel lowers conversion while adding orders. Never judge a move without orders and sessions beside it.\n    - Channel splits need the session's landing source on every event, including the order; otherwise orders land in an unattributed bucket and every channel looks worse.\n    - Comparing Black Friday week with the week before mixes intent. Compare with last year's Black Friday week instead.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"conversion-rate","name":"Conversion rate","aliases":["Ecommerce conversion rate","Store conversion rate","Online store conversion rate","Session conversion rate","Purchase conversion rate"],"family":"conversion","catalog_id":"conversion_rate","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of sessions that end in a paid order, the whole store funnel in one number.","formula":"Sessions with a paid order ÷ sessions"},"events":[{"name":"$pageview","description":"A page loaded in the browser. Sessions are the distinct session ids across page views.","also_called":["page_view","Page Viewed","page_viewed"],"properties":[{"name":"$session_id","description":"The browser session; a new one starts after 30 minutes without activity."}]},{"name":"order_completed","description":"A paid order confirmed by the server, carrying the browser's session id.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."},{"name":"$session_id","description":"The session the order was placed in, passed from the browser to the server."}]}],"numerator":{"label":"Sessions with a paid order","aggregate":"unique_sessions","event":"order_completed"},"denominator":{"label":"Sessions","aggregate":"unique_sessions","event":"$pageview"},"noise":{"type":"binomial","min_denominator":2000,"volume_unit":"sessions a week","typical":0.02,"reference_volumes":[2000,10000,50000,250000]},"example":{"business":"store","level":0.0206,"volume":600000,"trend":0.01,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a consent banner, tag manager or checkout change stop orders, or their session ids, being recorded?","yes":"Orders in the store platform or payment processor hold while orders recorded in analytics fall."},"spiked":{"check":"Did page views stop being recorded somewhere, shrinking sessions while orders kept recording?","yes":"Sessions fall with no matching fall in ad clicks or server logs, often on one browser or after a consent change."}},{"id":"calendar","label":"Shopping calendar","feed":"shopping","dropped":{"check":"Was last week a sale, holiday or payday week, or is this the week before one when shoppers wait?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this a sale, holiday or payday week? Compare with the same week last year before crediting the site.","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"traffic-mix","label":"Who arrived","breakdown":"utm_source","feed":"cloudflare","dropped":{"check":"Did sessions grow from a low-intent source or from bots, such as broad paid social, a viral post or a crawler?","yes":"Sessions jump from one source whose conversion is a fraction of the rest, while orders barely move."},"spiked":{"check":"Did a low-intent source or a bot wave shrink, lifting the rate without more orders?","yes":"Sessions fall while orders hold. Check orders before celebrating."}},{"id":"add-to-cart","label":"Product pages and carts","metric":"add-to-cart-rate","dropped":{"check":"Did fewer product viewers add to cart, from price, stock or a product page change?","yes":"Add-to-cart rate falls by about as much as conversion while checkout steps hold."},"spiked":{"check":"Did more product viewers add to cart, from a sale, a restock or a page change?","yes":"Add-to-cart rate rises and checkout starts follow it."}},{"id":"checkout","label":"Checkout and payment","metric":"checkout-conversion","feed":"stripe","dropped":{"check":"Did more started checkouts fail, at shipping, payment or account creation?","yes":"Checkout conversion falls while add-to-cart holds; one step or one payment method explains most of it."},"spiked":{"check":"Did a checkout or payment problem from the week before clear?","yes":"Checkout conversion returns to its usual level and conversion recovers with it."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the drop on one device type only?","yes":"Mobile falls while desktop is flat, which points at a release, a layout bug or a browser update."},"spiked":{"check":"Is the rise on one device type only?","yes":"One device jumps after a release; confirm it isn't a tracking change before crediting it."}}],"diagnose_order":["tracking","calendar","traffic-mix","add-to-cart","checkout","device-split"],"related":["sessions","add-to-cart-rate","checkout-conversion","mobile-conversion-rate","revenue-per-session","product-view-rate"],"prose":{"why_it_matters":"Conversion rate turns traffic into orders, so almost every change to the store shows up in it eventually. At 600,000 sessions a week, a tenth of a point is 600 orders, about $58,000 a week at Northwind's $97 order. It moves with who arrives as much as with the store, so read it beside the traffic mix before crediting or blaming the site.","pitfalls":["Orders sent from the server often carry no session id and fall out of the numerator. Pass the browser's session id onto the order event or conversion reads low.","Orders ÷ sessions and sessions with an order ÷ sessions differ when shoppers place two orders in one visit. This spec counts sessions, like Shopify's online store conversion rate.","A new low-intent channel lowers conversion while adding orders. Never judge a move without orders and sessions beside it.","Channel splits need the session's landing source on every event, including the order; otherwise orders land in an unattributed bucket and every channel looks worse.","Comparing Black Friday week with the week before mixes intent. Compare with last year's Black Friday week instead."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "cpc": { yaml: "id: cpc\nname: Cost per click\naliases:\n  - Average CPC\n  - Avg CPC\n  - Cost per link click\nfamily: acquisition\nkind: currency\npolarity: down-is-good\n\ndefinition:\n  one_line: What the store paid, on average, for one ad click in the week, across every synced ad platform.\n  formula: Ad spend ÷ ad clicks\n\nevents:\n  - name: ad_spend\n    description: One row per channel per day, synced from each ad platform's reporting API.\n    also_called: [Ad Spend, ad_performance, campaign_daily_stats]\n    properties:\n      - name: spend\n        description: Amount spent that day, in the store's reporting currency.\n      - name: clicks\n        description: Link clicks that day. Use link clicks, not all clicks, where the platform offers both.\n      - name: channel\n        description: The platform (google, meta, tiktok, microsoft, pinterest).\n      - name: campaign\n        description: The campaign name or id on that platform.\n\nnumerator:\n  label: Ad spend\n  aggregate: sum\n  event: ad_spend\n  property: spend\ndenominator:\n  label: Ad clicks\n  aggregate: sum\n  event: ad_spend\n  property: clicks\n\nnoise:\n  type: process\n  min_denominator: 200\n  volume_unit: ad clicks a week\n  typical: 1.1\n\nexample:\n  business: store\n  level: 1.25\n  volume: 240000\n  trend: 0.06\n\ndrivers:\n  - id: sync\n    label: Click and spend sync\n    breakdown: channel\n    dropped:\n      check: Is a channel syncing all clicks instead of link clicks, or clicks without their spend?\n      yes: One channel's clicks jump while the sessions it sends hold, or its spend is missing for some days.\n    spiked:\n      check: Is a channel syncing spend without its clicks, or did it switch to link clicks only?\n      yes: One channel's clicks fall to near zero or change definition while its spend holds.\n  - id: cpm\n    label: Price of impressions\n    metric: cpm\n    feed: shopping\n    dropped:\n      check: Did impressions get cheaper across platforms?\n      yes: CPM falls by about as much as CPC, and click-through rate holds.\n    spiked:\n      check: Did impressions get more expensive, as they do in Q4 and around Black Friday?\n      yes: CPM rises by about as much as CPC, and click-through rate holds.\n  - id: ctr\n    label: Click-through rate\n    metric: ctr\n    dropped:\n      check: Did more people click each ad, from new creative or a stronger offer?\n      yes: Click-through rate rises by about as much as CPC falls, at a steady CPM.\n    spiked:\n      check: Did fewer people click, from tired creative or a weaker offer?\n      yes: Click-through rate falls by about as much as CPC rises, at a steady CPM.\n  - id: channel-mix\n    label: Channel mix\n    metric: ad-spend\n    breakdown: channel\n    dropped:\n      check: Did budget move toward cheap-click channels such as broad social or display?\n      yes: Each channel's CPC holds but the cheaper channels took a bigger share of spend.\n    spiked:\n      check: Did budget move toward expensive-click channels such as non-brand search or LinkedIn?\n      yes: Each channel's CPC holds but the expensive channels took a bigger share of spend.\n  - id: bidding\n    label: Bidding and competition\n    feed: ad-platforms\n    dropped:\n      check: Did a competitor leave the auction, or a bid cap or target start holding prices down?\n      yes: CPC falls on search campaigns while impression share holds or rises.\n    spiked:\n      check: Did a bid strategy change, a new competitor arrive, or a platform raise its floor prices?\n      yes: CPC rises on the campaigns that changed strategy, or on search terms where a new competitor appears.\n\ndiagnose_order: [sync, cpm, ctr, channel-mix, bidding]\n\nrelated: [cpm, ctr, ad-spend, paid-sessions, paid-conversion-rate]\n\nprose:\n  why_it_matters: >-\n    CPC is what a visitor from an ad costs before they do anything, and it splits into two\n    numbers that move for different reasons: CPC = CPM ÷ (CTR × 1,000). A $1.25 click\n    converting at 2% means $62.50 of media per order, so a 20% rise in CPC adds $12.50 to every\n    paid order unless conversion rises with it.\n  pitfalls:\n    - Clicks are not visits. Some clicks never load the page or are never recorded; at Northwind 240,000 clicks become about 180,000 paid sessions, so cost per paid session is about $1.67, not $1.25.\n    - A blended CPC moves with the budget mix. A non-brand search click can cost several times a social click; split by channel before reading a change.\n    - A cheap click that never converts is expensive. Read CPC with paid conversion rate, never alone.\n    - Meta's \"CPC (all)\" divides by every click, including likes and profile taps. Use cost per link click to match this spec.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"cpc","name":"Cost per click","aliases":["Average CPC","Avg CPC","Cost per link click"],"family":"acquisition","kind":"currency","polarity":"down-is-good","definition":{"one_line":"What the store paid, on average, for one ad click in the week, across every synced ad platform.","formula":"Ad spend ÷ ad clicks"},"events":[{"name":"ad_spend","description":"One row per channel per day, synced from each ad platform's reporting API.","also_called":["Ad Spend","ad_performance","campaign_daily_stats"],"properties":[{"name":"spend","description":"Amount spent that day, in the store's reporting currency."},{"name":"clicks","description":"Link clicks that day. Use link clicks, not all clicks, where the platform offers both."},{"name":"channel","description":"The platform (google, meta, tiktok, microsoft, pinterest)."},{"name":"campaign","description":"The campaign name or id on that platform."}]}],"numerator":{"label":"Ad spend","aggregate":"sum","event":"ad_spend","property":"spend"},"denominator":{"label":"Ad clicks","aggregate":"sum","event":"ad_spend","property":"clicks"},"noise":{"type":"process","min_denominator":200,"volume_unit":"ad clicks a week","typical":1.1},"example":{"business":"store","level":1.25,"volume":240000,"trend":0.06},"drivers":[{"id":"sync","label":"Click and spend sync","breakdown":"channel","dropped":{"check":"Is a channel syncing all clicks instead of link clicks, or clicks without their spend?","yes":"One channel's clicks jump while the sessions it sends hold, or its spend is missing for some days."},"spiked":{"check":"Is a channel syncing spend without its clicks, or did it switch to link clicks only?","yes":"One channel's clicks fall to near zero or change definition while its spend holds."}},{"id":"cpm","label":"Price of impressions","metric":"cpm","feed":"shopping","dropped":{"check":"Did impressions get cheaper across platforms?","yes":"CPM falls by about as much as CPC, and click-through rate holds."},"spiked":{"check":"Did impressions get more expensive, as they do in Q4 and around Black Friday?","yes":"CPM rises by about as much as CPC, and click-through rate holds."}},{"id":"ctr","label":"Click-through rate","metric":"ctr","dropped":{"check":"Did more people click each ad, from new creative or a stronger offer?","yes":"Click-through rate rises by about as much as CPC falls, at a steady CPM."},"spiked":{"check":"Did fewer people click, from tired creative or a weaker offer?","yes":"Click-through rate falls by about as much as CPC rises, at a steady CPM."}},{"id":"channel-mix","label":"Channel mix","metric":"ad-spend","breakdown":"channel","dropped":{"check":"Did budget move toward cheap-click channels such as broad social or display?","yes":"Each channel's CPC holds but the cheaper channels took a bigger share of spend."},"spiked":{"check":"Did budget move toward expensive-click channels such as non-brand search or LinkedIn?","yes":"Each channel's CPC holds but the expensive channels took a bigger share of spend."}},{"id":"bidding","label":"Bidding and competition","feed":"ad-platforms","dropped":{"check":"Did a competitor leave the auction, or a bid cap or target start holding prices down?","yes":"CPC falls on search campaigns while impression share holds or rises."},"spiked":{"check":"Did a bid strategy change, a new competitor arrive, or a platform raise its floor prices?","yes":"CPC rises on the campaigns that changed strategy, or on search terms where a new competitor appears."}}],"diagnose_order":["sync","cpm","ctr","channel-mix","bidding"],"related":["cpm","ctr","ad-spend","paid-sessions","paid-conversion-rate"],"prose":{"why_it_matters":"CPC is what a visitor from an ad costs before they do anything, and it splits into two numbers that move for different reasons: CPC = CPM ÷ (CTR × 1,000). A $1.25 click converting at 2% means $62.50 of media per order, so a 20% rise in CPC adds $12.50 to every paid order unless conversion rises with it.","pitfalls":["Clicks are not visits. Some clicks never load the page or are never recorded; at Northwind 240,000 clicks become about 180,000 paid sessions, so cost per paid session is about $1.67, not $1.25.","A blended CPC moves with the budget mix. A non-brand search click can cost several times a social click; split by channel before reading a change.","A cheap click that never converts is expensive. Read CPC with paid conversion rate, never alone.","Meta's \"CPC (all)\" divides by every click, including likes and profile taps. Use cost per link click to match this spec."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "cpm": { yaml: "id: cpm\nname: Cost per thousand impressions\naliases:\n  - Cost per mille\n  - Cost per thousand\n  - Cost per 1000 impressions\nfamily: acquisition\nkind: currency\npolarity: down-is-good\n\ndefinition:\n  one_line: What the ad platforms charged, on average, to show the ads a thousand times in the week.\n  formula: Ad spend ÷ impressions × 1,000\n\nevents:\n  - name: ad_spend\n    description: One row per channel per day, synced from each ad platform's reporting API.\n    also_called: [Ad Spend, ad_performance, campaign_daily_stats]\n    properties:\n      - name: spend\n        description: Amount spent that day, in the store's reporting currency.\n      - name: impressions\n        description: Ads shown that day, as the platform counts them.\n      - name: channel\n        description: The platform (google, meta, tiktok, microsoft, pinterest).\n\nnumerator:\n  label: Ad spend\n  aggregate: sum\n  event: ad_spend\n  property: spend\ndenominator:\n  label: Impressions\n  aggregate: sum\n  event: ad_spend\n  property: impressions\n\nqueries:\n  hogql: |-\n    -- CPM per week: ad spend ÷ impressions × 1,000, across every synced ad channel. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(s.spend, 0) AS numerator,\n      coalesce(s.impressions, 0) AS denominator,\n      if(coalesce(s.impressions, 0) = 0, NULL, s.spend / s.impressions * 1000) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT\n        toMonday(toTimeZone(timestamp, 'UTC')) AS week,\n        sum(toFloat(properties.spend)) AS spend,\n        sum(toFloat(properties.impressions)) AS impressions\n      FROM events\n      WHERE event = 'ad_spend'\n        AND timestamp >= now() - toIntervalWeek(27)\n        AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n      GROUP BY week\n    ) AS s ON s.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- CPM per week: ad spend ÷ impressions × 1,000, across every synced ad channel. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    spend AS (\n      SELECT\n        date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n        sum(CASE WHEN properties->>'spend' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'spend')::numeric END) AS spend,\n        sum(CASE WHEN properties->>'impressions' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'impressions')::numeric END) AS impressions\n      FROM events\n      WHERE event_name = 'ad_spend'\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n      GROUP BY 1\n    )\n    SELECT\n      w.week,\n      coalesce(s.spend, 0) AS numerator,\n      coalesce(s.impressions, 0) AS denominator,\n      s.spend / nullif(s.impressions, 0) * 1000 AS value\n    FROM weeks AS w\n    LEFT JOIN spend AS s ON s.week = w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- CPM per week: ad spend ÷ impressions × 1,000, across every synced ad channel. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    spend AS (\n      SELECT\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n        SUM(SAFE_CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64)) AS spend,\n        SUM(SAFE_CAST(JSON_VALUE(properties, '$.impressions') AS FLOAT64)) AS impressions\n      FROM events\n      WHERE event_name = 'ad_spend'\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      COALESCE(s.spend, 0) AS numerator,\n      COALESCE(s.impressions, 0) AS denominator,\n      SAFE_DIVIDE(s.spend, s.impressions) * 1000 AS value\n    FROM weeks AS w\n    LEFT JOIN spend AS s ON s.week = w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- CPM per week: ad spend ÷ impressions × 1,000, across every synced ad channel. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    spend AS (\n      SELECT\n        DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n        SUM(TRY_TO_DOUBLE(properties:\"spend\"::string)) AS spend,\n        SUM(TRY_TO_DOUBLE(properties:\"impressions\"::string)) AS impressions\n      FROM events\n      WHERE event_name = 'ad_spend'\n        AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n      GROUP BY 1\n    )\n    SELECT\n      w.week,\n      COALESCE(s.spend, 0) AS numerator,\n      COALESCE(s.impressions, 0) AS denominator,\n      s.spend / NULLIF(s.impressions, 0) * 1000 AS value\n    FROM weeks AS w\n    LEFT JOIN spend AS s ON s.week = w.week\n    ORDER BY w.week;\n\nnoise:\n  type: process\n  min_denominator: 10000\n  volume_unit: impressions a week\n  typical: 12\n\nexample:\n  business: store\n  level: 14.5\n  volume: 21000000\n  trend: 0.08\n\ndrivers:\n  - id: sync\n    label: Impression and spend sync\n    breakdown: channel\n    dropped:\n      check: Is a channel syncing impressions without its spend, or spend that was missing last week?\n      yes: One channel's impressions and spend no longer move together for some days.\n    spiked:\n      check: Is a channel syncing spend without its impressions, or did a platform change how it counts an impression?\n      yes: One channel's impressions fall to near zero or change definition while its spend holds.\n  - id: auction-season\n    label: Auction season\n    feed: shopping\n    dropped:\n      check: Did a high-demand period end, such as the last weeks of Q4?\n      yes: CPMs fall across every platform in the first weeks of January or after a peak.\n    spiked:\n      check: Is this a week when every advertiser bids up, such as Black Friday, Cyber Monday or the run-up to Christmas?\n      yes: CPMs rise across every platform at once; the same weeks last year show the same rise.\n  - id: platform-changes\n    label: Platform changes\n    feed: ad-platforms\n    dropped:\n      check: Did a platform release new inventory or change its auction?\n      yes: CPM falls on one platform only, from a dated change.\n    spiked:\n      check: Did a platform outage, policy change or measurement change limit cheap inventory?\n      yes: CPM rises on one platform only, from a dated change.\n  - id: channel-mix\n    label: Channel and placement mix\n    metric: ad-spend\n    breakdown: channel\n    dropped:\n      check: Did budget shift toward cheap inventory such as display, Audience Network or broad video?\n      yes: Each channel's CPM holds but the share of spend on the cheapest placements grew.\n    spiked:\n      check: Did budget shift toward expensive inventory such as search, LinkedIn or retargeting?\n      yes: Each channel's CPM holds but the share of spend on the most expensive placements grew.\n  - id: targeting-and-creative\n    label: Audience and creative\n    dropped:\n      check: Did a broader audience or a fresh creative with strong engagement lower the price per impression?\n      yes: CPM falls on the campaigns that changed, often with higher click-through.\n    spiked:\n      check: Did audiences narrow, frequency climb, or a tired creative lose its quality ranking?\n      yes: CPM rises on campaigns whose frequency climbed or whose ads ran unchanged for weeks.\n\ndiagnose_order: [sync, auction-season, platform-changes, channel-mix, targeting-and-creative]\n\nrelated: [ad-spend, ctr, cpc, ncac, paid-sessions]\n\nprose:\n  why_it_matters: >-\n    CPM is the price of attention, set by an auction the store doesn't control. When every\n    retailer bids for the same shoppers, as in Black Friday week, CPM rises and every metric\n    downstream gets more expensive with it. At Northwind's $14.50 and 21 million impressions a\n    week, a 20% rise costs about $61,000 more for the same reach.\n  pitfalls:\n    - A blended CPM across platforms moves with the budget mix. Search, LinkedIn and retargeting often cost several times what broad social and display do; split by channel before reading a change.\n    - Platforms count impressions differently. Meta counts an ad when it first appears on screen while Google counts many ads when they are served, so CPMs across platforms don't compare directly.\n    - A falling CPM is not always good news. Cheap placements such as in-app display and Audience Network buy impressions few people notice; read CPM with click-through rate.\n    - Ad-platform days follow the ad account's time zone. Summed into UTC weeks, a little spend and a few impressions land in the neighbouring week.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"cpm","name":"Cost per thousand impressions","aliases":["Cost per mille","Cost per thousand","Cost per 1000 impressions"],"family":"acquisition","kind":"currency","polarity":"down-is-good","definition":{"one_line":"What the ad platforms charged, on average, to show the ads a thousand times in the week.","formula":"Ad spend ÷ impressions × 1,000"},"events":[{"name":"ad_spend","description":"One row per channel per day, synced from each ad platform's reporting API.","also_called":["Ad Spend","ad_performance","campaign_daily_stats"],"properties":[{"name":"spend","description":"Amount spent that day, in the store's reporting currency."},{"name":"impressions","description":"Ads shown that day, as the platform counts them."},{"name":"channel","description":"The platform (google, meta, tiktok, microsoft, pinterest)."}]}],"numerator":{"label":"Ad spend","aggregate":"sum","event":"ad_spend","property":"spend"},"denominator":{"label":"Impressions","aggregate":"sum","event":"ad_spend","property":"impressions"},"queries":{"hogql":"-- CPM per week: ad spend ÷ impressions × 1,000, across every synced ad channel. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(s.spend, 0) AS numerator,\n  coalesce(s.impressions, 0) AS denominator,\n  if(coalesce(s.impressions, 0) = 0, NULL, s.spend / s.impressions * 1000) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT\n    toMonday(toTimeZone(timestamp, 'UTC')) AS week,\n    sum(toFloat(properties.spend)) AS spend,\n    sum(toFloat(properties.impressions)) AS impressions\n  FROM events\n  WHERE event = 'ad_spend'\n    AND timestamp >= now() - toIntervalWeek(27)\n    AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n  GROUP BY week\n) AS s ON s.week = w.week\nORDER BY week","postgres":"-- CPM per week: ad spend ÷ impressions × 1,000, across every synced ad channel. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nspend AS (\n  SELECT\n    date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n    sum(CASE WHEN properties->>'spend' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'spend')::numeric END) AS spend,\n    sum(CASE WHEN properties->>'impressions' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'impressions')::numeric END) AS impressions\n  FROM events\n  WHERE event_name = 'ad_spend'\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n  GROUP BY 1\n)\nSELECT\n  w.week,\n  coalesce(s.spend, 0) AS numerator,\n  coalesce(s.impressions, 0) AS denominator,\n  s.spend / nullif(s.impressions, 0) * 1000 AS value\nFROM weeks AS w\nLEFT JOIN spend AS s ON s.week = w.week\nORDER BY w.week;","bigquery":"-- CPM per week: ad spend ÷ impressions × 1,000, across every synced ad channel. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nspend AS (\n  SELECT\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n    SUM(SAFE_CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64)) AS spend,\n    SUM(SAFE_CAST(JSON_VALUE(properties, '$.impressions') AS FLOAT64)) AS impressions\n  FROM events\n  WHERE event_name = 'ad_spend'\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY week\n)\nSELECT\n  w.week,\n  COALESCE(s.spend, 0) AS numerator,\n  COALESCE(s.impressions, 0) AS denominator,\n  SAFE_DIVIDE(s.spend, s.impressions) * 1000 AS value\nFROM weeks AS w\nLEFT JOIN spend AS s ON s.week = w.week\nORDER BY w.week;","snowflake":"-- CPM per week: ad spend ÷ impressions × 1,000, across every synced ad channel. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nspend AS (\n  SELECT\n    DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n    SUM(TRY_TO_DOUBLE(properties:\"spend\"::string)) AS spend,\n    SUM(TRY_TO_DOUBLE(properties:\"impressions\"::string)) AS impressions\n  FROM events\n  WHERE event_name = 'ad_spend'\n    AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n  GROUP BY 1\n)\nSELECT\n  w.week,\n  COALESCE(s.spend, 0) AS numerator,\n  COALESCE(s.impressions, 0) AS denominator,\n  s.spend / NULLIF(s.impressions, 0) * 1000 AS value\nFROM weeks AS w\nLEFT JOIN spend AS s ON s.week = w.week\nORDER BY w.week;"},"noise":{"type":"process","min_denominator":10000,"volume_unit":"impressions a week","typical":12},"example":{"business":"store","level":14.5,"volume":21000000,"trend":0.08},"drivers":[{"id":"sync","label":"Impression and spend sync","breakdown":"channel","dropped":{"check":"Is a channel syncing impressions without its spend, or spend that was missing last week?","yes":"One channel's impressions and spend no longer move together for some days."},"spiked":{"check":"Is a channel syncing spend without its impressions, or did a platform change how it counts an impression?","yes":"One channel's impressions fall to near zero or change definition while its spend holds."}},{"id":"auction-season","label":"Auction season","feed":"shopping","dropped":{"check":"Did a high-demand period end, such as the last weeks of Q4?","yes":"CPMs fall across every platform in the first weeks of January or after a peak."},"spiked":{"check":"Is this a week when every advertiser bids up, such as Black Friday, Cyber Monday or the run-up to Christmas?","yes":"CPMs rise across every platform at once; the same weeks last year show the same rise."}},{"id":"platform-changes","label":"Platform changes","feed":"ad-platforms","dropped":{"check":"Did a platform release new inventory or change its auction?","yes":"CPM falls on one platform only, from a dated change."},"spiked":{"check":"Did a platform outage, policy change or measurement change limit cheap inventory?","yes":"CPM rises on one platform only, from a dated change."}},{"id":"channel-mix","label":"Channel and placement mix","metric":"ad-spend","breakdown":"channel","dropped":{"check":"Did budget shift toward cheap inventory such as display, Audience Network or broad video?","yes":"Each channel's CPM holds but the share of spend on the cheapest placements grew."},"spiked":{"check":"Did budget shift toward expensive inventory such as search, LinkedIn or retargeting?","yes":"Each channel's CPM holds but the share of spend on the most expensive placements grew."}},{"id":"targeting-and-creative","label":"Audience and creative","dropped":{"check":"Did a broader audience or a fresh creative with strong engagement lower the price per impression?","yes":"CPM falls on the campaigns that changed, often with higher click-through."},"spiked":{"check":"Did audiences narrow, frequency climb, or a tired creative lose its quality ranking?","yes":"CPM rises on campaigns whose frequency climbed or whose ads ran unchanged for weeks."}}],"diagnose_order":["sync","auction-season","platform-changes","channel-mix","targeting-and-creative"],"related":["ad-spend","ctr","cpc","ncac","paid-sessions"],"prose":{"why_it_matters":"CPM is the price of attention, set by an auction the store doesn't control. When every retailer bids for the same shoppers, as in Black Friday week, CPM rises and every metric downstream gets more expensive with it. At Northwind's $14.50 and 21 million impressions a week, a 20% rise costs about $61,000 more for the same reach.","pitfalls":["A blended CPM across platforms moves with the budget mix. Search, LinkedIn and retargeting often cost several times what broad social and display do; split by channel before reading a change.","Platforms count impressions differently. Meta counts an ad when it first appears on screen while Google counts many ads when they are served, so CPMs across platforms don't compare directly.","A falling CPM is not always good news. Cheap placements such as in-app display and Audience Network buy impressions few people notice; read CPM with click-through rate.","Ad-platform days follow the ad account's time zone. Summed into UTC weeks, a little spend and a few impressions land in the neighbouring week."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "ctr": { yaml: "id: ctr\nname: Click-through rate\naliases:\n  - Ad click-through rate\n  - Ad CTR\n  - Clickthrough rate\n  - Link click-through rate\nfamily: acquisition\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of ad impressions in the week that led to a click, across every synced ad platform.\n  formula: Ad clicks ÷ ad impressions\n\nevents:\n  - name: ad_spend\n    description: One row per channel per day, synced from each ad platform's reporting API.\n    also_called: [Ad Spend, ad_performance, campaign_daily_stats]\n    properties:\n      - name: clicks\n        description: Link clicks that day. Use link clicks, not all clicks, where the platform offers both.\n      - name: impressions\n        description: Ads shown that day, as the platform counts them.\n      - name: channel\n        description: The platform (google, meta, tiktok, microsoft, pinterest).\n      - name: campaign\n        description: The campaign name or id on that platform.\n\nnumerator:\n  label: Ad clicks\n  aggregate: sum\n  event: ad_spend\n  property: clicks\ndenominator:\n  label: Impressions\n  aggregate: sum\n  event: ad_spend\n  property: impressions\n\nnoise:\n  type: binomial\n  min_denominator: 10000\n  volume_unit: impressions a week\n  typical: 0.011\n  reference_volumes: [10000, 100000, 1000000, 10000000]\n\nexample:\n  business: store\n  level: 0.0115\n  volume: 21000000\n  trend: -0.05\n\ndrivers:\n  - id: sync\n    label: Click and impression sync\n    breakdown: channel\n    dropped:\n      check: Did a sync miss clicks for some days, or switch one channel from all clicks to link clicks?\n      yes: One channel's clicks fall sharply from one day while its spend and the sessions it sends hold.\n    spiked:\n      check: Is a channel syncing all clicks (likes, profile taps, expands) instead of link clicks, or missing impressions?\n      yes: One channel's CTR jumps several times over while the sessions it sends barely move.\n  - id: channel-mix\n    label: Channel and placement mix\n    breakdown: channel\n    dropped:\n      check: Did budget shift toward low-CTR inventory such as display, video or Audience Network?\n      yes: Each channel's CTR holds but low-CTR placements took a bigger share of impressions.\n    spiked:\n      check: Did budget shift toward high-CTR inventory such as branded search or retargeting?\n      yes: Each channel's CTR holds but high-CTR placements took a bigger share of impressions.\n  - id: creative-fatigue\n    label: Creative fatigue\n    breakdown: campaign\n    dropped:\n      check: Have the same ads run for weeks to the same people?\n      yes: CTR falls steadily on long-running campaigns as frequency climbs.\n    spiked:\n      check: Did new creative, a new offer or a new hook go live?\n      yes: CTR rises on the campaigns that changed from the day they launched.\n  - id: calendar\n    label: Calendar and offers\n    feed: shopping\n    dropped:\n      check: Did a sale end, so ads lost the offer people were clicking for?\n      yes: The same weeks last year show the same fall after the sale.\n    spiked:\n      check: Is a sale, holiday or launch giving people a reason to click?\n      yes: CTR rises across campaigns that mention the offer, and the same week last year shows it too.\n  - id: invalid-clicks\n    label: Bots and accidental clicks\n    metric: bounce-rate\n    dropped:\n      check: Did a platform start filtering invalid clicks, or did an accidental-tap placement stop serving?\n      yes: Clicks fall on one placement while orders from paid traffic hold.\n    spiked:\n      check: Is a bot, click farm or accidental-tap placement adding clicks?\n      yes: Clicks jump on one placement or app, and those visits bounce almost every time.\n\ndiagnose_order: [sync, channel-mix, creative-fatigue, calendar, invalid-clicks]\n\nrelated: [cpm, cpc, paid-sessions, ad-spend, paid-conversion-rate]\n\nprose:\n  why_it_matters: >-\n    Click-through rate is how well the ads earn attention, and with CPM it sets the price of a\n    click: CPC is CPM ÷ (CTR × 1,000). A fall from 1.2% to 1.0% makes every click 20% more\n    expensive at the same CPM. It is also an early sign of creative fatigue, often before cost\n    per order moves.\n  pitfalls:\n    - Use link clicks, not all clicks. Meta's all-clicks include likes, comments and profile taps, so they read well above the link-click rate.\n    - A blended CTR moves with the mix. Search ads usually get several times the CTR of social ads, and display far less; split by channel before reading a change.\n    - A high CTR from an accidental-tap placement is worse than a low one. Check that clicks became sessions that stayed.\n    - At millions of impressions a week, chance barely moves CTR, so most moves are real. Real doesn't mean caused by you; check the platform and the mix first.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"ctr","name":"Click-through rate","aliases":["Ad click-through rate","Ad CTR","Clickthrough rate","Link click-through rate"],"family":"acquisition","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of ad impressions in the week that led to a click, across every synced ad platform.","formula":"Ad clicks ÷ ad impressions"},"events":[{"name":"ad_spend","description":"One row per channel per day, synced from each ad platform's reporting API.","also_called":["Ad Spend","ad_performance","campaign_daily_stats"],"properties":[{"name":"clicks","description":"Link clicks that day. Use link clicks, not all clicks, where the platform offers both."},{"name":"impressions","description":"Ads shown that day, as the platform counts them."},{"name":"channel","description":"The platform (google, meta, tiktok, microsoft, pinterest)."},{"name":"campaign","description":"The campaign name or id on that platform."}]}],"numerator":{"label":"Ad clicks","aggregate":"sum","event":"ad_spend","property":"clicks"},"denominator":{"label":"Impressions","aggregate":"sum","event":"ad_spend","property":"impressions"},"noise":{"type":"binomial","min_denominator":10000,"volume_unit":"impressions a week","typical":0.011,"reference_volumes":[10000,100000,1000000,10000000]},"example":{"business":"store","level":0.0115,"volume":21000000,"trend":-0.05},"drivers":[{"id":"sync","label":"Click and impression sync","breakdown":"channel","dropped":{"check":"Did a sync miss clicks for some days, or switch one channel from all clicks to link clicks?","yes":"One channel's clicks fall sharply from one day while its spend and the sessions it sends hold."},"spiked":{"check":"Is a channel syncing all clicks (likes, profile taps, expands) instead of link clicks, or missing impressions?","yes":"One channel's CTR jumps several times over while the sessions it sends barely move."}},{"id":"channel-mix","label":"Channel and placement mix","breakdown":"channel","dropped":{"check":"Did budget shift toward low-CTR inventory such as display, video or Audience Network?","yes":"Each channel's CTR holds but low-CTR placements took a bigger share of impressions."},"spiked":{"check":"Did budget shift toward high-CTR inventory such as branded search or retargeting?","yes":"Each channel's CTR holds but high-CTR placements took a bigger share of impressions."}},{"id":"creative-fatigue","label":"Creative fatigue","breakdown":"campaign","dropped":{"check":"Have the same ads run for weeks to the same people?","yes":"CTR falls steadily on long-running campaigns as frequency climbs."},"spiked":{"check":"Did new creative, a new offer or a new hook go live?","yes":"CTR rises on the campaigns that changed from the day they launched."}},{"id":"calendar","label":"Calendar and offers","feed":"shopping","dropped":{"check":"Did a sale end, so ads lost the offer people were clicking for?","yes":"The same weeks last year show the same fall after the sale."},"spiked":{"check":"Is a sale, holiday or launch giving people a reason to click?","yes":"CTR rises across campaigns that mention the offer, and the same week last year shows it too."}},{"id":"invalid-clicks","label":"Bots and accidental clicks","metric":"bounce-rate","dropped":{"check":"Did a platform start filtering invalid clicks, or did an accidental-tap placement stop serving?","yes":"Clicks fall on one placement while orders from paid traffic hold."},"spiked":{"check":"Is a bot, click farm or accidental-tap placement adding clicks?","yes":"Clicks jump on one placement or app, and those visits bounce almost every time."}}],"diagnose_order":["sync","channel-mix","creative-fatigue","calendar","invalid-clicks"],"related":["cpm","cpc","paid-sessions","ad-spend","paid-conversion-rate"],"prose":{"why_it_matters":"Click-through rate is how well the ads earn attention, and with CPM it sets the price of a click: CPC is CPM ÷ (CTR × 1,000). A fall from 1.2% to 1.0% makes every click 20% more expensive at the same CPM. It is also an early sign of creative fatigue, often before cost per order moves.","pitfalls":["Use link clicks, not all clicks. Meta's all-clicks include likes, comments and profile taps, so they read well above the link-click rate.","A blended CTR moves with the mix. Search ads usually get several times the CTR of social ads, and display far less; split by channel before reading a change.","A high CTR from an accidental-tap placement is worse than a low one. Check that clicks became sessions that stayed.","At millions of impressions a week, chance barely moves CTR, so most moves are real. Real doesn't mean caused by you; check the platform and the mix first."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "customer-lifetime-value": { yaml: "id: customer-lifetime-value\nname: Customer lifetime value\naliases:\n  - LTV\n  - CLV\n  - CLTV\n  - Lifetime value\n  - 12-month LTV\nfamily: customers\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: The net revenue a new customer brings in their first 365 days, first order included, averaged over the customers who first ordered in the week.\n  formula: Net revenue from cohort customers' orders in the 365 days from each one's first order ÷ customers in the cohort\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: is_first_order\n        description: True when the store has no earlier order from this customer, from its own customer records.\n      - name: customer_id\n        description: The store's customer id, shared by guest and logged-in orders with the same email.\n      - name: order_id\n        description: Unique per order; links refunds back to the order and its customer.\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n  - name: order_refunded\n    description: A refund issued against an earlier order, full or partial.\n    also_called: [refund, Order Refunded]\n    properties:\n      - name: order_id\n        description: The order the refund belongs to.\n      - name: amount\n        description: The refunded amount, excluding tax and shipping.\n\nnumerator:\n  label: Net revenue in each customer's first 365 days\n  aggregate: sum\n  event: order_completed\n  property: total\ndenominator:\n  label: Customers whose first order fell in the week\n  aggregate: unique_users\n  event: order_completed\n  where:\n    - property: is_first_order\n      op: eq\n      value: true\n\nqueries:\n  hogql: |-\n    -- Customer lifetime value (12 months): average net revenue per customer in the 365 days from their first order, first order included and refunds taken off, by first-order week. First-order weeks 79 to 54 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 365 days close.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(c.amount_total, 0) AS numerator,\n      coalesce(c.customers, 0) AS denominator,\n      if(denominator = 0, NULL, numerator / denominator) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(54, 80))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, sum(amount) AS amount_total, count() AS customers\n      FROM (\n        SELECT\n          toMonday(f.first_at) AS week,\n          f.customer_id AS customer_id,\n          sumIf(o.amount, o.ts >= f.first_at AND o.ts < f.first_at + toIntervalDay(365)) AS amount\n        FROM (\n          SELECT customer_id, min(ts) AS first_at\n          FROM (\n            SELECT coalesce(properties.customer_id, toString(person_id)) AS customer_id, toTimeZone(timestamp, 'UTC') AS ts\n            FROM events\n            WHERE event = 'order_completed'\n              AND properties.is_first_order = 'true'\n              AND timestamp >= now() - toIntervalWeek(80)\n              AND toMonday(toTimeZone(timestamp, 'UTC')) >= toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(79)\n          )\n          WHERE customer_id IS NOT NULL\n          GROUP BY customer_id\n        ) AS f\n        INNER JOIN (\n          SELECT po.customer_id AS customer_id, po.ts AS ts, po.total - coalesce(r.refunded, 0) AS amount\n          FROM (\n            SELECT\n              coalesce(properties.customer_id, toString(person_id)) AS customer_id,\n              properties.order_id AS order_id,\n              toTimeZone(timestamp, 'UTC') AS ts,\n              toFloat(properties.total) AS total,\n              toFloat(properties.cost_of_goods) AS cost_of_goods\n            FROM events\n            WHERE event = 'order_completed'\n              AND timestamp >= now() - toIntervalWeek(80)\n              AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(79) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n          ) AS po\n          LEFT JOIN (\n            SELECT properties.order_id AS order_id, sum(toFloat(properties.amount)) AS refunded\n            FROM events\n            WHERE event = 'order_refunded'\n              AND timestamp >= now() - toIntervalWeek(80)\n              AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(79) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n            GROUP BY order_id\n          ) AS r ON r.order_id = po.order_id\n        ) AS o ON o.customer_id = f.customer_id\n        WHERE toMonday(f.first_at) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(79) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(54)\n        GROUP BY week, customer_id\n      )\n      GROUP BY week\n    ) AS c ON c.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Customer lifetime value (12 months): average net revenue per customer in the 365 days from their first order, first order included and refunds taken off, by first-order week. First-order weeks 79 to 54 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 365 days close.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '79 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '54 weeks',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    refunds AS (\n      SELECT properties->>'order_id' AS order_id, sum(CASE WHEN properties->>'amount' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'amount')::numeric END) AS refunded\n      FROM events\n      WHERE event_name = 'order_refunded'\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '79 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n      GROUP BY 1\n    ),\n    orders AS (\n      SELECT\n        coalesce(e.properties->>'customer_id', e.user_id) AS customer_id,\n        e.properties->>'is_first_order' = 'true' AS is_first_order,\n        e.occurred_at AT TIME ZONE 'UTC' AS ts,\n        CASE WHEN e.properties->>'total' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (e.properties->>'total')::numeric END - coalesce(r.refunded, 0) AS amount\n      FROM events AS e\n      LEFT JOIN refunds AS r ON r.order_id = e.properties->>'order_id'\n      WHERE e.event_name = 'order_completed'\n        AND e.occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '79 weeks') AT TIME ZONE 'UTC'\n        AND e.occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n    ),\n    first_orders AS (\n      SELECT customer_id, min(ts) AS first_at\n      FROM orders\n      WHERE is_first_order\n        AND customer_id IS NOT NULL\n        AND ts < date_trunc('week', now() AT TIME ZONE 'UTC') - interval '53 weeks'\n      GROUP BY customer_id\n    ),\n    cohort AS (\n      SELECT date_trunc('week', f.first_at)::date AS week, f.customer_id, sum(o.amount) AS amount\n      FROM first_orders AS f\n      JOIN orders AS o\n        ON o.customer_id = f.customer_id\n       AND o.ts >= f.first_at\n       AND o.ts < f.first_at + interval '365 days'\n      GROUP BY 1, 2\n    )\n    SELECT\n      w.week,\n      coalesce(sum(c.amount), 0) AS numerator,\n      count(c.customer_id) AS denominator,\n      coalesce(sum(c.amount), 0) / nullif(count(c.customer_id), 0) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Customer lifetime value (12 months): average net revenue per customer in the 365 days from their first order, first order included and refunds taken off, by first-order week. First-order weeks 79 to 54 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 365 days close.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 79 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 54 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    refunds AS (\n      SELECT JSON_VALUE(properties, '$.order_id') AS order_id, SUM(SAFE_CAST(JSON_VALUE(properties, '$.amount') AS FLOAT64)) AS refunded\n      FROM events\n      WHERE event_name = 'order_refunded'\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 79 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY order_id\n    ),\n    orders AS (\n      SELECT\n        COALESCE(JSON_VALUE(e.properties, '$.customer_id'), e.user_id) AS customer_id,\n        JSON_VALUE(e.properties, '$.is_first_order') = 'true' AS is_first_order,\n        e.occurred_at,\n        SAFE_CAST(JSON_VALUE(e.properties, '$.total') AS FLOAT64) - COALESCE(r.refunded, 0) AS amount\n      FROM events AS e\n      LEFT JOIN refunds AS r ON r.order_id = JSON_VALUE(e.properties, '$.order_id')\n      WHERE e.event_name = 'order_completed'\n        AND e.occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 79 WEEK))\n        AND e.occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    ),\n    first_orders AS (\n      SELECT customer_id, MIN(occurred_at) AS first_at\n      FROM orders\n      WHERE is_first_order\n        AND customer_id IS NOT NULL\n        AND occurred_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 53 WEEK))\n      GROUP BY customer_id\n    ),\n    cohort AS (\n      SELECT DATE_TRUNC(DATE(f.first_at), ISOWEEK) AS week, f.customer_id, SUM(o.amount) AS amount\n      FROM first_orders AS f\n      JOIN orders AS o\n        ON o.customer_id = f.customer_id\n       AND o.occurred_at >= f.first_at\n       AND o.occurred_at < TIMESTAMP_ADD(f.first_at, INTERVAL 365 DAY)\n      GROUP BY week, f.customer_id\n    )\n    SELECT\n      w.week,\n      COALESCE(SUM(c.amount), 0) AS numerator,\n      COUNT(c.customer_id) AS denominator,\n      SAFE_DIVIDE(COALESCE(SUM(c.amount), 0), COUNT(c.customer_id)) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Customer lifetime value (12 months): average net revenue per customer in the 365 days from their first order, first order included and refunds taken off, by first-order week. First-order weeks 79 to 54 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 365 days close.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -53 - ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    refunds AS (\n      SELECT properties:\"order_id\"::string AS order_id, SUM(TRY_TO_DOUBLE(properties:\"amount\"::string)) AS refunded\n      FROM events\n      WHERE event_name = 'order_refunded'\n        AND occurred_at >= DATEADD(week, -79, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n      GROUP BY 1\n    ),\n    orders AS (\n      SELECT\n        COALESCE(e.properties:\"customer_id\"::string, e.user_id) AS customer_id,\n        e.properties:\"is_first_order\"::string = 'true' AS is_first_order,\n        e.occurred_at,\n        TRY_TO_DOUBLE(e.properties:\"total\"::string) - COALESCE(r.refunded, 0) AS amount\n      FROM events AS e\n      LEFT JOIN refunds AS r ON r.order_id = e.properties:\"order_id\"::string\n      WHERE e.event_name = 'order_completed'\n        AND e.occurred_at >= DATEADD(week, -79, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND e.occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n    ),\n    first_orders AS (\n      SELECT customer_id, MIN(occurred_at) AS first_at\n      FROM orders\n      WHERE is_first_order\n        AND customer_id IS NOT NULL\n        AND occurred_at < DATEADD(week, -53, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n      GROUP BY customer_id\n    ),\n    cohort AS (\n      SELECT DATEADD(day, 1 - DAYOFWEEKISO(f.first_at), f.first_at::date) AS week, f.customer_id, SUM(o.amount) AS amount\n      FROM first_orders AS f\n      JOIN orders AS o\n        ON o.customer_id = f.customer_id\n       AND o.occurred_at >= f.first_at\n       AND o.occurred_at < DATEADD(day, 365, f.first_at)\n      GROUP BY 1, 2\n    )\n    SELECT\n      w.week,\n      COALESCE(SUM(c.amount), 0) AS numerator,\n      COUNT(c.customer_id) AS denominator,\n      COALESCE(SUM(c.amount), 0) / NULLIF(COUNT(c.customer_id), 0) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n\nnoise:\n  type: mean\n  cv: 1.3\n  min_denominator: 200\n  volume_unit: first-time customers in the cohort\n  typical: 140\n\nexample:\n  business: store\n  level: 138\n  volume: 6800\n  trend: 0.04\n\ndrivers:\n  - id: tracking\n    label: Refund and customer records\n    dropped:\n      check: Did refunds start being linked to orders, or a batch of old refunds land against this cohort?\n      yes: Refunds per cohort customer jump while gross order value per customer holds.\n    spiked:\n      check: Did refunds stop syncing, or did duplicate order events inflate the cohort's revenue?\n      yes: Refunds fall to near zero, or orders per customer jump with the same order ids appearing twice.\n  - id: calendar\n    label: Holiday cohorts\n    feed: shopping\n    dropped:\n      check: Is this a Black Friday or holiday cohort? Deal hunters and gift buyers are often worth less over a year.\n      yes: The same cohort weeks last year show the same dip.\n    spiked:\n      check: Is this a cohort from a quiet, full-price season?\n      yes: The same cohort weeks last year show the same rise.\n  - id: cohort-source\n    label: How the cohort was won\n    breakdown: coupon\n    dropped:\n      check: Did the cohort come in on a deep discount, a giveaway or a new paid channel?\n      yes: Customers whose first order used that code are worth far less than the rest of the cohort.\n    spiked:\n      check: Did the cohort come mostly from referrals or full-price buyers?\n      yes: The share of first orders without a discount code is higher than in neighbouring cohorts.\n  - id: second-orders\n    label: Repeat buying\n    metric: second-order-rate\n    dropped:\n      check: Did the cohort reorder less, starting in its first 90 days?\n      yes: The same cohort's second order rate was below normal months ago.\n    spiked:\n      check: Did the cohort reorder more, from a new flow, a loyalty programme or a better product?\n      yes: The same cohort's second order rate was above normal months ago.\n  - id: order-value\n    label: Order value\n    metric: aov\n    dropped:\n      check: Did the cohort's orders get smaller, from discounts or a mix shift to cheaper products?\n      yes: Orders per customer hold while order value falls.\n    spiked:\n      check: Did a price rise or bundles lift the cohort's order value?\n      yes: Orders per customer hold while order value rises.\n  - id: refunds\n    label: Refunds\n    metric: refund-rate\n    dropped:\n      check: Did the cohort refund more, from a bad batch or delivery problems?\n      yes: Gross revenue per customer holds while refunds per customer rise.\n    spiked:\n      check: Did refunds fall after a quality or delivery fix?\n      yes: Refunds per customer run below earlier cohorts.\n\ndiagnose_order: [tracking, calendar, cohort-source, second-orders, order-value, refunds]\n\nrelated: [ltv-to-cac, second-order-rate, purchase-frequency, aov, repeat-purchase-rate]\n\nprose:\n  why_it_matters: >-\n    Lifetime value sets the most a store can pay to win a customer. This spec measures it rather than\n    projects it: 12 months of real orders per cohort, so nothing rests on a guessed lifespan, at the\n    cost of waiting a year to see each cohort. At Northwind a first order averages about $95 and a\n    customer's first year about $138; the difference is what retention earns.\n  pitfalls:\n    - Projected LTV, order value × frequency × lifespan or ARPA ÷ churn, is only as good as its lifespan guess, and a guess of five years can triple it. Report realized value and label any projection as one.\n    - Revenue LTV overstates what a customer is worth. Take off product cost before comparing it with acquisition cost, as LTV to CAC does.\n    - Only cohorts whose 365 days have closed are reported, so the latest point describes customers who first ordered over a year ago. For an early read on recent cohorts, use second order rate.\n    - Refunds belong to the order they reverse. Taking refunds off by refund date instead of by order moves value between cohorts.\n    - Holiday cohorts are larger and often worth less per customer. Compare a cohort with the same week last year.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"customer-lifetime-value","name":"Customer lifetime value","aliases":["LTV","CLV","CLTV","Lifetime value","12-month LTV"],"family":"customers","kind":"currency","polarity":"up-is-good","definition":{"one_line":"The net revenue a new customer brings in their first 365 days, first order included, averaged over the customers who first ordered in the week.","formula":"Net revenue from cohort customers' orders in the 365 days from each one's first order ÷ customers in the cohort"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"is_first_order","description":"True when the store has no earlier order from this customer, from its own customer records."},{"name":"customer_id","description":"The store's customer id, shared by guest and logged-in orders with the same email."},{"name":"order_id","description":"Unique per order; links refunds back to the order and its customer."},{"name":"total","description":"Order value after discounts, before tax and shipping."}]},{"name":"order_refunded","description":"A refund issued against an earlier order, full or partial.","also_called":["refund","Order Refunded"],"properties":[{"name":"order_id","description":"The order the refund belongs to."},{"name":"amount","description":"The refunded amount, excluding tax and shipping."}]}],"numerator":{"label":"Net revenue in each customer's first 365 days","aggregate":"sum","event":"order_completed","property":"total"},"denominator":{"label":"Customers whose first order fell in the week","aggregate":"unique_users","event":"order_completed","where":[{"property":"is_first_order","op":"eq","value":true}]},"queries":{"hogql":"-- Customer lifetime value (12 months): average net revenue per customer in the 365 days from their first order, first order included and refunds taken off, by first-order week. First-order weeks 79 to 54 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 365 days close.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(c.amount_total, 0) AS numerator,\n  coalesce(c.customers, 0) AS denominator,\n  if(denominator = 0, NULL, numerator / denominator) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(54, 80))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, sum(amount) AS amount_total, count() AS customers\n  FROM (\n    SELECT\n      toMonday(f.first_at) AS week,\n      f.customer_id AS customer_id,\n      sumIf(o.amount, o.ts >= f.first_at AND o.ts < f.first_at + toIntervalDay(365)) AS amount\n    FROM (\n      SELECT customer_id, min(ts) AS first_at\n      FROM (\n        SELECT coalesce(properties.customer_id, toString(person_id)) AS customer_id, toTimeZone(timestamp, 'UTC') AS ts\n        FROM events\n        WHERE event = 'order_completed'\n          AND properties.is_first_order = 'true'\n          AND timestamp >= now() - toIntervalWeek(80)\n          AND toMonday(toTimeZone(timestamp, 'UTC')) >= toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(79)\n      )\n      WHERE customer_id IS NOT NULL\n      GROUP BY customer_id\n    ) AS f\n    INNER JOIN (\n      SELECT po.customer_id AS customer_id, po.ts AS ts, po.total - coalesce(r.refunded, 0) AS amount\n      FROM (\n        SELECT\n          coalesce(properties.customer_id, toString(person_id)) AS customer_id,\n          properties.order_id AS order_id,\n          toTimeZone(timestamp, 'UTC') AS ts,\n          toFloat(properties.total) AS total,\n          toFloat(properties.cost_of_goods) AS cost_of_goods\n        FROM events\n        WHERE event = 'order_completed'\n          AND timestamp >= now() - toIntervalWeek(80)\n          AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(79) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n      ) AS po\n      LEFT JOIN (\n        SELECT properties.order_id AS order_id, sum(toFloat(properties.amount)) AS refunded\n        FROM events\n        WHERE event = 'order_refunded'\n          AND timestamp >= now() - toIntervalWeek(80)\n          AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(79) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n        GROUP BY order_id\n      ) AS r ON r.order_id = po.order_id\n    ) AS o ON o.customer_id = f.customer_id\n    WHERE toMonday(f.first_at) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(79) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(54)\n    GROUP BY week, customer_id\n  )\n  GROUP BY week\n) AS c ON c.week = w.week\nORDER BY week","postgres":"-- Customer lifetime value (12 months): average net revenue per customer in the 365 days from their first order, first order included and refunds taken off, by first-order week. First-order weeks 79 to 54 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 365 days close.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '79 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '54 weeks',\n    interval '1 week'\n  ) AS g(week)\n),\nrefunds AS (\n  SELECT properties->>'order_id' AS order_id, sum(CASE WHEN properties->>'amount' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'amount')::numeric END) AS refunded\n  FROM events\n  WHERE event_name = 'order_refunded'\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '79 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n  GROUP BY 1\n),\norders AS (\n  SELECT\n    coalesce(e.properties->>'customer_id', e.user_id) AS customer_id,\n    e.properties->>'is_first_order' = 'true' AS is_first_order,\n    e.occurred_at AT TIME ZONE 'UTC' AS ts,\n    CASE WHEN e.properties->>'total' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (e.properties->>'total')::numeric END - coalesce(r.refunded, 0) AS amount\n  FROM events AS e\n  LEFT JOIN refunds AS r ON r.order_id = e.properties->>'order_id'\n  WHERE e.event_name = 'order_completed'\n    AND e.occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '79 weeks') AT TIME ZONE 'UTC'\n    AND e.occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n),\nfirst_orders AS (\n  SELECT customer_id, min(ts) AS first_at\n  FROM orders\n  WHERE is_first_order\n    AND customer_id IS NOT NULL\n    AND ts < date_trunc('week', now() AT TIME ZONE 'UTC') - interval '53 weeks'\n  GROUP BY customer_id\n),\ncohort AS (\n  SELECT date_trunc('week', f.first_at)::date AS week, f.customer_id, sum(o.amount) AS amount\n  FROM first_orders AS f\n  JOIN orders AS o\n    ON o.customer_id = f.customer_id\n   AND o.ts >= f.first_at\n   AND o.ts < f.first_at + interval '365 days'\n  GROUP BY 1, 2\n)\nSELECT\n  w.week,\n  coalesce(sum(c.amount), 0) AS numerator,\n  count(c.customer_id) AS denominator,\n  coalesce(sum(c.amount), 0) / nullif(count(c.customer_id), 0) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;","bigquery":"-- Customer lifetime value (12 months): average net revenue per customer in the 365 days from their first order, first order included and refunds taken off, by first-order week. First-order weeks 79 to 54 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 365 days close.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 79 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 54 WEEK), INTERVAL 1 WEEK)) AS week\n),\nrefunds AS (\n  SELECT JSON_VALUE(properties, '$.order_id') AS order_id, SUM(SAFE_CAST(JSON_VALUE(properties, '$.amount') AS FLOAT64)) AS refunded\n  FROM events\n  WHERE event_name = 'order_refunded'\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 79 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY order_id\n),\norders AS (\n  SELECT\n    COALESCE(JSON_VALUE(e.properties, '$.customer_id'), e.user_id) AS customer_id,\n    JSON_VALUE(e.properties, '$.is_first_order') = 'true' AS is_first_order,\n    e.occurred_at,\n    SAFE_CAST(JSON_VALUE(e.properties, '$.total') AS FLOAT64) - COALESCE(r.refunded, 0) AS amount\n  FROM events AS e\n  LEFT JOIN refunds AS r ON r.order_id = JSON_VALUE(e.properties, '$.order_id')\n  WHERE e.event_name = 'order_completed'\n    AND e.occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 79 WEEK))\n    AND e.occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n),\nfirst_orders AS (\n  SELECT customer_id, MIN(occurred_at) AS first_at\n  FROM orders\n  WHERE is_first_order\n    AND customer_id IS NOT NULL\n    AND occurred_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 53 WEEK))\n  GROUP BY customer_id\n),\ncohort AS (\n  SELECT DATE_TRUNC(DATE(f.first_at), ISOWEEK) AS week, f.customer_id, SUM(o.amount) AS amount\n  FROM first_orders AS f\n  JOIN orders AS o\n    ON o.customer_id = f.customer_id\n   AND o.occurred_at >= f.first_at\n   AND o.occurred_at < TIMESTAMP_ADD(f.first_at, INTERVAL 365 DAY)\n  GROUP BY week, f.customer_id\n)\nSELECT\n  w.week,\n  COALESCE(SUM(c.amount), 0) AS numerator,\n  COUNT(c.customer_id) AS denominator,\n  SAFE_DIVIDE(COALESCE(SUM(c.amount), 0), COUNT(c.customer_id)) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;","snowflake":"-- Customer lifetime value (12 months): average net revenue per customer in the 365 days from their first order, first order included and refunds taken off, by first-order week. First-order weeks 79 to 54 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 365 days close.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -53 - ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nrefunds AS (\n  SELECT properties:\"order_id\"::string AS order_id, SUM(TRY_TO_DOUBLE(properties:\"amount\"::string)) AS refunded\n  FROM events\n  WHERE event_name = 'order_refunded'\n    AND occurred_at >= DATEADD(week, -79, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n  GROUP BY 1\n),\norders AS (\n  SELECT\n    COALESCE(e.properties:\"customer_id\"::string, e.user_id) AS customer_id,\n    e.properties:\"is_first_order\"::string = 'true' AS is_first_order,\n    e.occurred_at,\n    TRY_TO_DOUBLE(e.properties:\"total\"::string) - COALESCE(r.refunded, 0) AS amount\n  FROM events AS e\n  LEFT JOIN refunds AS r ON r.order_id = e.properties:\"order_id\"::string\n  WHERE e.event_name = 'order_completed'\n    AND e.occurred_at >= DATEADD(week, -79, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND e.occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n),\nfirst_orders AS (\n  SELECT customer_id, MIN(occurred_at) AS first_at\n  FROM orders\n  WHERE is_first_order\n    AND customer_id IS NOT NULL\n    AND occurred_at < DATEADD(week, -53, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n  GROUP BY customer_id\n),\ncohort AS (\n  SELECT DATEADD(day, 1 - DAYOFWEEKISO(f.first_at), f.first_at::date) AS week, f.customer_id, SUM(o.amount) AS amount\n  FROM first_orders AS f\n  JOIN orders AS o\n    ON o.customer_id = f.customer_id\n   AND o.occurred_at >= f.first_at\n   AND o.occurred_at < DATEADD(day, 365, f.first_at)\n  GROUP BY 1, 2\n)\nSELECT\n  w.week,\n  COALESCE(SUM(c.amount), 0) AS numerator,\n  COUNT(c.customer_id) AS denominator,\n  COALESCE(SUM(c.amount), 0) / NULLIF(COUNT(c.customer_id), 0) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;"},"noise":{"type":"mean","cv":1.3,"min_denominator":200,"volume_unit":"first-time customers in the cohort","typical":140},"example":{"business":"store","level":138,"volume":6800,"trend":0.04},"drivers":[{"id":"tracking","label":"Refund and customer records","dropped":{"check":"Did refunds start being linked to orders, or a batch of old refunds land against this cohort?","yes":"Refunds per cohort customer jump while gross order value per customer holds."},"spiked":{"check":"Did refunds stop syncing, or did duplicate order events inflate the cohort's revenue?","yes":"Refunds fall to near zero, or orders per customer jump with the same order ids appearing twice."}},{"id":"calendar","label":"Holiday cohorts","feed":"shopping","dropped":{"check":"Is this a Black Friday or holiday cohort? Deal hunters and gift buyers are often worth less over a year.","yes":"The same cohort weeks last year show the same dip."},"spiked":{"check":"Is this a cohort from a quiet, full-price season?","yes":"The same cohort weeks last year show the same rise."}},{"id":"cohort-source","label":"How the cohort was won","breakdown":"coupon","dropped":{"check":"Did the cohort come in on a deep discount, a giveaway or a new paid channel?","yes":"Customers whose first order used that code are worth far less than the rest of the cohort."},"spiked":{"check":"Did the cohort come mostly from referrals or full-price buyers?","yes":"The share of first orders without a discount code is higher than in neighbouring cohorts."}},{"id":"second-orders","label":"Repeat buying","metric":"second-order-rate","dropped":{"check":"Did the cohort reorder less, starting in its first 90 days?","yes":"The same cohort's second order rate was below normal months ago."},"spiked":{"check":"Did the cohort reorder more, from a new flow, a loyalty programme or a better product?","yes":"The same cohort's second order rate was above normal months ago."}},{"id":"order-value","label":"Order value","metric":"aov","dropped":{"check":"Did the cohort's orders get smaller, from discounts or a mix shift to cheaper products?","yes":"Orders per customer hold while order value falls."},"spiked":{"check":"Did a price rise or bundles lift the cohort's order value?","yes":"Orders per customer hold while order value rises."}},{"id":"refunds","label":"Refunds","metric":"refund-rate","dropped":{"check":"Did the cohort refund more, from a bad batch or delivery problems?","yes":"Gross revenue per customer holds while refunds per customer rise."},"spiked":{"check":"Did refunds fall after a quality or delivery fix?","yes":"Refunds per customer run below earlier cohorts."}}],"diagnose_order":["tracking","calendar","cohort-source","second-orders","order-value","refunds"],"related":["ltv-to-cac","second-order-rate","purchase-frequency","aov","repeat-purchase-rate"],"prose":{"why_it_matters":"Lifetime value sets the most a store can pay to win a customer. This spec measures it rather than projects it: 12 months of real orders per cohort, so nothing rests on a guessed lifespan, at the cost of waiting a year to see each cohort. At Northwind a first order averages about $95 and a customer's first year about $138; the difference is what retention earns.","pitfalls":["Projected LTV, order value × frequency × lifespan or ARPA ÷ churn, is only as good as its lifespan guess, and a guess of five years can triple it. Report realized value and label any projection as one.","Revenue LTV overstates what a customer is worth. Take off product cost before comparing it with acquisition cost, as LTV to CAC does.","Only cohorts whose 365 days have closed are reported, so the latest point describes customers who first ordered over a year ago. For an early read on recent cohorts, use second order rate.","Refunds belong to the order they reverse. Taking refunds off by refund date instead of by order moves value between cohorts.","Holiday cohorts are larger and often worth less per customer. Compare a cohort with the same week last year."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "dau": { yaml: "id: dau\nname: Daily active users\naliases:\n  - DAU\n  - Daily active users (DAU)\n  - Daily actives\nfamily: engagement\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: The average number of distinct people active on each day of the week, Monday to Sunday UTC.\n  formula: Sum of the seven daily counts of distinct people with any event ÷ 7\n\nevents:\n  - name: \"*\"\n    description: Any event a person sends. Activity, not one specific action; the same definition as WAU and MAU.\n    also_called: [All events, Any event, Active event]\n    properties:\n      - name: $session_id\n        description: The session the event belongs to.\n      - name: $os\n        description: The operating system, for splitting by platform.\n\nnumerator:\n  label: Distinct active people\n  aggregate: unique_users\n  event: \"*\"\n\nqueries:\n  hogql: |-\n    -- Daily active users per week: the average of the week's seven daily counts of distinct people with any event (days in UTC). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(d.person_days, 0) AS person_days,\n      person_days / 7 AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT toMonday(day) AS week, count() AS person_days\n      FROM (\n        SELECT DISTINCT person_id, toDate(toTimeZone(timestamp, 'UTC')) AS day\n        FROM events\n        WHERE person_id IS NOT NULL\n          AND timestamp >= now() - toIntervalWeek(27)\n          AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n      )\n      GROUP BY week\n    ) AS d ON d.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Daily active users per week: the average of the week's seven daily counts of distinct people with any event (days in UTC). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    person_days AS (\n      SELECT DISTINCT\n        user_id,\n        (occurred_at AT TIME ZONE 'UTC')::date AS day,\n        date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week\n      FROM events\n      WHERE user_id IS NOT NULL\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n    ),\n    weekly AS (\n      SELECT week, count(*) AS person_days\n      FROM person_days\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      coalesce(d.person_days, 0) AS person_days,\n      coalesce(d.person_days, 0) / 7.0 AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS d ON d.week = w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Daily active users per week: the average of the week's seven daily counts of distinct people with any event (days in UTC). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    person_days AS (\n      SELECT DISTINCT user_id, DATE(occurred_at) AS day\n      FROM events\n      WHERE user_id IS NOT NULL\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    ),\n    weekly AS (\n      SELECT DATE_TRUNC(day, ISOWEEK) AS week, COUNT(*) AS person_days\n      FROM person_days\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      COALESCE(d.person_days, 0) AS person_days,\n      COALESCE(d.person_days, 0) / 7 AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS d ON d.week = w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Daily active users per week: the average of the week's seven daily counts of distinct people with any event (days in UTC). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    person_days AS (\n      SELECT DISTINCT user_id, occurred_at::date AS day\n      FROM events\n      WHERE user_id IS NOT NULL\n        AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n    ),\n    weekly AS (\n      SELECT DATEADD(day, 1 - DAYOFWEEKISO(day), day) AS week, COUNT(*) AS person_days\n      FROM person_days\n      GROUP BY 1\n    )\n    SELECT\n      w.week,\n      COALESCE(d.person_days, 0) AS person_days,\n      COALESCE(d.person_days, 0) / 7 AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS d ON d.week = w.week\n    ORDER BY w.week;\n\nnoise:\n  type: poisson\n  min_denominator: 100\n  volume_unit: daily active users\n  typical: 22000\n\nexample:\n  business: app\n  level: 22000\n  volume: 22000\n  trend: 0.15\n\ndrivers:\n  - id: tracking\n    label: Tracking and bots\n    dropped:\n      check: Did an SDK update, consent banner or ad blocker stop events from one platform or app version?\n      yes: One platform or version goes quiet from the day of a release while the others hold.\n    spiked:\n      check: Is the rise real people, or bots, a duplicated SDK init, or a background event now counting as activity?\n      yes: Events per active person fall sharply, or one event, app version or user agent accounts for the new actives.\n  - id: outage\n    label: Outages\n    feed: cloudflare\n    dropped:\n      check: Was the product, its login or a provider it depends on down for part of the week?\n      yes: DAU falls on the days of an incident and recovers after; the status page or provider feed shows it.\n    spiked:\n      check: Did an outage the week before end, bringing people back?\n      yes: Last week's daily counts had a hole and this week's are back at the usual level.\n  - id: calendar\n    label: Calendar\n    feed: holidays\n    dropped:\n      check: Did a public holiday or school break interrupt daily routines?\n      yes: The same week last year shows the same dip once aligned on the holiday.\n    spiked:\n      check: Is this a seasonal high for the product, such as the new year for a budgeting app?\n      yes: The same weeks last year show the same rise.\n  - id: platform\n    label: Platform and releases\n    breakdown: $os\n    feed: app-stores\n    dropped:\n      check: Is the drop on one platform only, after a release, a store rejection or an OS update?\n      yes: iOS or Android falls from the day of a release or OS update while the web holds.\n    spiked:\n      check: Did a release, store feature or OS update lift one platform?\n      yes: One platform rises from the day the release or feature went live.\n  - id: campaigns\n    label: Push and email campaigns\n    metric: email-click-rate\n    dropped:\n      check: Did a push, email or in-app campaign that usually brings people back not go out?\n      yes: Activity from notification and email opens falls on the days the campaign usually runs.\n    spiked:\n      check: Did a push or email blast bring a one-off wave of opens?\n      yes: DAU jumps on the send day and falls back within days; check how many came back the week after.\n  - id: new-users\n    label: New users\n    metric: signups\n    dropped:\n      check: Did fewer new people arrive this week?\n      yes: New people fall by about as many as DAU did, while returning people hold.\n    spiked:\n      check: Did a launch, a press mention or a paid campaign bring a wave of new people?\n      yes: New people explain the rise while returning people are flat; their week 1 retention decides whether it lasts.\n\ndiagnose_order: [tracking, outage, calendar, platform, campaigns, new-users]\n\nrelated: [wau, mau, stickiness, sessions-per-user, signups]\n\nprose:\n  why_it_matters: >-\n    DAU counts the people who used the product on a given day, the most direct read of whether\n    it has become a habit. This spec reports the week's average of seven daily counts, which\n    removes the weekday cycle that makes single days misleading. At 22,000 daily actives, chance\n    alone moves the weekly average by about 2%, so a 5% move deserves a look and a 1% move does not.\n  pitfalls:\n    - Any event includes events nobody chose to send, such as push notifications received, background refreshes and feature flag checks. Leave passive events out, or DAU counts phones rather than people.\n    - Anonymous and signed-in events from one person count twice until identities are merged. Expect DAU to drop the week merging is fixed.\n    - Comparing one day with the day before mixes weekdays and weekends. Compare weekly averages, or the same weekday.\n    - Bots and uptime checks inflate web DAU. Filter known crawlers and internal accounts before reading a spike.\n    - UTC days split an evening in two for people far from Greenwich. Pick one time zone for daily counts and keep it.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"dau","name":"Daily active users","aliases":["DAU","Daily active users (DAU)","Daily actives"],"family":"engagement","kind":"count","polarity":"up-is-good","definition":{"one_line":"The average number of distinct people active on each day of the week, Monday to Sunday UTC.","formula":"Sum of the seven daily counts of distinct people with any event ÷ 7"},"events":[{"name":"*","description":"Any event a person sends. Activity, not one specific action; the same definition as WAU and MAU.","also_called":["All events","Any event","Active event"],"properties":[{"name":"$session_id","description":"The session the event belongs to."},{"name":"$os","description":"The operating system, for splitting by platform."}]}],"numerator":{"label":"Distinct active people","aggregate":"unique_users","event":"*"},"queries":{"hogql":"-- Daily active users per week: the average of the week's seven daily counts of distinct people with any event (days in UTC). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(d.person_days, 0) AS person_days,\n  person_days / 7 AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT toMonday(day) AS week, count() AS person_days\n  FROM (\n    SELECT DISTINCT person_id, toDate(toTimeZone(timestamp, 'UTC')) AS day\n    FROM events\n    WHERE person_id IS NOT NULL\n      AND timestamp >= now() - toIntervalWeek(27)\n      AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n  )\n  GROUP BY week\n) AS d ON d.week = w.week\nORDER BY week","postgres":"-- Daily active users per week: the average of the week's seven daily counts of distinct people with any event (days in UTC). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nperson_days AS (\n  SELECT DISTINCT\n    user_id,\n    (occurred_at AT TIME ZONE 'UTC')::date AS day,\n    date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week\n  FROM events\n  WHERE user_id IS NOT NULL\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n),\nweekly AS (\n  SELECT week, count(*) AS person_days\n  FROM person_days\n  GROUP BY week\n)\nSELECT\n  w.week,\n  coalesce(d.person_days, 0) AS person_days,\n  coalesce(d.person_days, 0) / 7.0 AS value\nFROM weeks AS w\nLEFT JOIN weekly AS d ON d.week = w.week\nORDER BY w.week;","bigquery":"-- Daily active users per week: the average of the week's seven daily counts of distinct people with any event (days in UTC). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nperson_days AS (\n  SELECT DISTINCT user_id, DATE(occurred_at) AS day\n  FROM events\n  WHERE user_id IS NOT NULL\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n),\nweekly AS (\n  SELECT DATE_TRUNC(day, ISOWEEK) AS week, COUNT(*) AS person_days\n  FROM person_days\n  GROUP BY week\n)\nSELECT\n  w.week,\n  COALESCE(d.person_days, 0) AS person_days,\n  COALESCE(d.person_days, 0) / 7 AS value\nFROM weeks AS w\nLEFT JOIN weekly AS d ON d.week = w.week\nORDER BY w.week;","snowflake":"-- Daily active users per week: the average of the week's seven daily counts of distinct people with any event (days in UTC). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nperson_days AS (\n  SELECT DISTINCT user_id, occurred_at::date AS day\n  FROM events\n  WHERE user_id IS NOT NULL\n    AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n),\nweekly AS (\n  SELECT DATEADD(day, 1 - DAYOFWEEKISO(day), day) AS week, COUNT(*) AS person_days\n  FROM person_days\n  GROUP BY 1\n)\nSELECT\n  w.week,\n  COALESCE(d.person_days, 0) AS person_days,\n  COALESCE(d.person_days, 0) / 7 AS value\nFROM weeks AS w\nLEFT JOIN weekly AS d ON d.week = w.week\nORDER BY w.week;"},"noise":{"type":"poisson","min_denominator":100,"volume_unit":"daily active users","typical":22000},"example":{"business":"app","level":22000,"volume":22000,"trend":0.15},"drivers":[{"id":"tracking","label":"Tracking and bots","dropped":{"check":"Did an SDK update, consent banner or ad blocker stop events from one platform or app version?","yes":"One platform or version goes quiet from the day of a release while the others hold."},"spiked":{"check":"Is the rise real people, or bots, a duplicated SDK init, or a background event now counting as activity?","yes":"Events per active person fall sharply, or one event, app version or user agent accounts for the new actives."}},{"id":"outage","label":"Outages","feed":"cloudflare","dropped":{"check":"Was the product, its login or a provider it depends on down for part of the week?","yes":"DAU falls on the days of an incident and recovers after; the status page or provider feed shows it."},"spiked":{"check":"Did an outage the week before end, bringing people back?","yes":"Last week's daily counts had a hole and this week's are back at the usual level."}},{"id":"calendar","label":"Calendar","feed":"holidays","dropped":{"check":"Did a public holiday or school break interrupt daily routines?","yes":"The same week last year shows the same dip once aligned on the holiday."},"spiked":{"check":"Is this a seasonal high for the product, such as the new year for a budgeting app?","yes":"The same weeks last year show the same rise."}},{"id":"platform","label":"Platform and releases","breakdown":"$os","feed":"app-stores","dropped":{"check":"Is the drop on one platform only, after a release, a store rejection or an OS update?","yes":"iOS or Android falls from the day of a release or OS update while the web holds."},"spiked":{"check":"Did a release, store feature or OS update lift one platform?","yes":"One platform rises from the day the release or feature went live."}},{"id":"campaigns","label":"Push and email campaigns","metric":"email-click-rate","dropped":{"check":"Did a push, email or in-app campaign that usually brings people back not go out?","yes":"Activity from notification and email opens falls on the days the campaign usually runs."},"spiked":{"check":"Did a push or email blast bring a one-off wave of opens?","yes":"DAU jumps on the send day and falls back within days; check how many came back the week after."}},{"id":"new-users","label":"New users","metric":"signups","dropped":{"check":"Did fewer new people arrive this week?","yes":"New people fall by about as many as DAU did, while returning people hold."},"spiked":{"check":"Did a launch, a press mention or a paid campaign bring a wave of new people?","yes":"New people explain the rise while returning people are flat; their week 1 retention decides whether it lasts."}}],"diagnose_order":["tracking","outage","calendar","platform","campaigns","new-users"],"related":["wau","mau","stickiness","sessions-per-user","signups"],"prose":{"why_it_matters":"DAU counts the people who used the product on a given day, the most direct read of whether it has become a habit. This spec reports the week's average of seven daily counts, which removes the weekday cycle that makes single days misleading. At 22,000 daily actives, chance alone moves the weekly average by about 2%, so a 5% move deserves a look and a 1% move does not.","pitfalls":["Any event includes events nobody chose to send, such as push notifications received, background refreshes and feature flag checks. Leave passive events out, or DAU counts phones rather than people.","Anonymous and signed-in events from one person count twice until identities are merged. Expect DAU to drop the week merging is fixed.","Comparing one day with the day before mixes weekdays and weekends. Compare weekly averages, or the same weekday.","Bots and uptime checks inflate web DAU. Filter known crawlers and internal accounts before reading a spike.","UTC days split an evening in two for people far from Greenwich. Pick one time zone for daily counts and keep it."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "demo-request-rate": { yaml: "id: demo-request-rate\nname: Demo request rate\naliases:\n  - Demo conversion rate\n  - Book a demo rate\n  - Contact sales rate\nfamily: activation\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of this week's new visitors who requested a demo or a sales call.\n  formula: People who requested a demo ÷ people whose first ever visit was this week\n\nevents:\n  - name: $pageview\n    description: One per page view; a person's first ever page view marks them as a new visitor.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: utm_source\n        description: The campaign source of the visit, when tagged.\n  - name: demo_requested\n    description: A demo or contact-sales form accepted by the server or the CRM, not a click on the button.\n    also_called: [Demo Requested, generate_lead, form_submitted]\n    properties: []\n\nnumerator:\n  label: People who requested a demo\n  aggregate: unique_users\n  event: demo_requested\ndenominator:\n  label: New visitors\n  aggregate: first_time_users\n  event: $pageview\n\nnoise:\n  type: binomial\n  min_denominator: 2000\n  volume_unit: new visitors a week\n  typical: 0.0025\n  reference_volumes: [5000, 20000, 60000, 200000]\n\nexample:\n  business: saas\n  level: 0.0025\n  volume: 55000\n  trend: 0.03\n\ndrivers:\n  - id: tracking\n    label: Form tracking\n    dropped:\n      check: Did the form, its embed or its event break, for example after a CRM or consent change?\n      yes: Requests in the CRM hold while recorded requests fall, or the form errors on one browser.\n    spiked:\n      check: Is the event firing on button clicks or on every form step instead of once per request?\n      yes: Recorded requests exceed leads in the CRM.\n  - id: spam\n    label: Spam and bots\n    dropped:\n      check: Did a new captcha or email check start rejecting real prospects?\n      yes: Form starts hold while accepted requests fall from the day the filter shipped.\n    spiked:\n      check: Are bots or spammers filling the form?\n      yes: Requests cluster in one country or email domain with fake company names, and none book a meeting.\n  - id: calendar\n    label: Holidays and quarter timing\n    feed: holidays\n    dropped:\n      check: Is this a holiday week, or the end of a quarter when buyers have spent their budget?\n      yes: The same week last year shows the same dip.\n    spiked:\n      check: Is this the start of a quarter or budget season?\n      yes: The same weeks last year show the same rise.\n  - id: traffic-mix\n    label: Who arrived\n    metric: unique-visitors\n    feed: google-search\n    dropped:\n      check: Did low-intent traffic grow, from a viral post, a broad campaign or a blog ranking?\n      yes: New visitors rise from one source that almost never asks for a demo.\n    spiked:\n      check: Did high-intent traffic grow, from comparison pages, review sites or an account-based campaign?\n      yes: New visitors from one high-intent source rise and request demos at several times the usual rate.\n  - id: page-change\n    label: Call to action and pricing page\n    dropped:\n      check: Did the demo button move, a pricing page change, or the form get longer?\n      yes: Clicks on the demo call to action fall from the day the change shipped.\n    spiked:\n      check: Did pricing become contact-sales only, or a demo call to action appear on more pages?\n      yes: Requests rise from the pages where the call to action was added.\n  - id: self-serve\n    label: Self-serve alternative\n    metric: signup-rate\n    dropped:\n      check: Did a free trial or self-serve plan launch, pulling would-be demo requests into signups?\n      yes: Signup rate rises as demo request rate falls, from the same day.\n    spiked:\n      check: Did self-serve signup get harder or a free plan go away?\n      yes: Signup rate falls as demo request rate rises, from the same day.\n\ndiagnose_order: [tracking, spam, calendar, traffic-mix, page-change, self-serve]\n\nrelated: [signup-rate, new-paid-accounts, unique-visitors, trial-starts, signups]\n\nprose:\n  why_it_matters: >-\n    For a sales-led product, a demo request is the signup: the first moment a visitor becomes a lead\n    with a name. It usually runs between 0.2% and 1% of visitors, so the weekly count is small and\n    noisy; at Copperline's 55,000 new visitors a week, a move of a quarter of the rate either way is\n    still chance.\n  pitfalls:\n    - Spam bots fill demo forms. Count requests that pass validation or reach the CRM, or one bad week doubles the rate.\n    - A request is not a qualified meeting. Track the share that books and attends before celebrating a rise.\n    - Adding a free trial or a self-serve plan moves would-be demo requests into signups. Read it next to signup rate after any packaging change.\n    - Long B2B research cycles mean many requesters first visited weeks earlier and count in the numerator only. Compare the rate with itself over time, not with another company's.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"demo-request-rate","name":"Demo request rate","aliases":["Demo conversion rate","Book a demo rate","Contact sales rate"],"family":"activation","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of this week's new visitors who requested a demo or a sales call.","formula":"People who requested a demo ÷ people whose first ever visit was this week"},"events":[{"name":"$pageview","description":"One per page view; a person's first ever page view marks them as a new visitor.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"utm_source","description":"The campaign source of the visit, when tagged."}]},{"name":"demo_requested","description":"A demo or contact-sales form accepted by the server or the CRM, not a click on the button.","also_called":["Demo Requested","generate_lead","form_submitted"],"properties":[]}],"numerator":{"label":"People who requested a demo","aggregate":"unique_users","event":"demo_requested"},"denominator":{"label":"New visitors","aggregate":"first_time_users","event":"$pageview"},"noise":{"type":"binomial","min_denominator":2000,"volume_unit":"new visitors a week","typical":0.0025,"reference_volumes":[5000,20000,60000,200000]},"example":{"business":"saas","level":0.0025,"volume":55000,"trend":0.03},"drivers":[{"id":"tracking","label":"Form tracking","dropped":{"check":"Did the form, its embed or its event break, for example after a CRM or consent change?","yes":"Requests in the CRM hold while recorded requests fall, or the form errors on one browser."},"spiked":{"check":"Is the event firing on button clicks or on every form step instead of once per request?","yes":"Recorded requests exceed leads in the CRM."}},{"id":"spam","label":"Spam and bots","dropped":{"check":"Did a new captcha or email check start rejecting real prospects?","yes":"Form starts hold while accepted requests fall from the day the filter shipped."},"spiked":{"check":"Are bots or spammers filling the form?","yes":"Requests cluster in one country or email domain with fake company names, and none book a meeting."}},{"id":"calendar","label":"Holidays and quarter timing","feed":"holidays","dropped":{"check":"Is this a holiday week, or the end of a quarter when buyers have spent their budget?","yes":"The same week last year shows the same dip."},"spiked":{"check":"Is this the start of a quarter or budget season?","yes":"The same weeks last year show the same rise."}},{"id":"traffic-mix","label":"Who arrived","metric":"unique-visitors","feed":"google-search","dropped":{"check":"Did low-intent traffic grow, from a viral post, a broad campaign or a blog ranking?","yes":"New visitors rise from one source that almost never asks for a demo."},"spiked":{"check":"Did high-intent traffic grow, from comparison pages, review sites or an account-based campaign?","yes":"New visitors from one high-intent source rise and request demos at several times the usual rate."}},{"id":"page-change","label":"Call to action and pricing page","dropped":{"check":"Did the demo button move, a pricing page change, or the form get longer?","yes":"Clicks on the demo call to action fall from the day the change shipped."},"spiked":{"check":"Did pricing become contact-sales only, or a demo call to action appear on more pages?","yes":"Requests rise from the pages where the call to action was added."}},{"id":"self-serve","label":"Self-serve alternative","metric":"signup-rate","dropped":{"check":"Did a free trial or self-serve plan launch, pulling would-be demo requests into signups?","yes":"Signup rate rises as demo request rate falls, from the same day."},"spiked":{"check":"Did self-serve signup get harder or a free plan go away?","yes":"Signup rate falls as demo request rate rises, from the same day."}}],"diagnose_order":["tracking","spam","calendar","traffic-mix","page-change","self-serve"],"related":["signup-rate","new-paid-accounts","unique-visitors","trial-starts","signups"],"prose":{"why_it_matters":"For a sales-led product, a demo request is the signup: the first moment a visitor becomes a lead with a name. It usually runs between 0.2% and 1% of visitors, so the weekly count is small and noisy; at Copperline's 55,000 new visitors a week, a move of a quarter of the rate either way is still chance.","pitfalls":["Spam bots fill demo forms. Count requests that pass validation or reach the CRM, or one bad week doubles the rate.","A request is not a qualified meeting. Track the share that books and attends before celebrating a rise.","Adding a free trial or a self-serve plan moves would-be demo requests into signups. Read it next to signup rate after any packaging change.","Long B2B research cycles mean many requesters first visited weeks earlier and count in the numerator only. Compare the rate with itself over time, not with another company's."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "discount-rate": { yaml: "id: discount-rate\nname: Discount rate\naliases:\n  - Discount percentage\n  - Discounts as a share of sales\n  - Average discount rate\n  - Promotional discount rate\nfamily: revenue\nkind: rate\npolarity: down-is-good\n\ndefinition:\n  one_line: The share of gross sales given away as discounts at checkout, from codes, automatic offers and bundle deals.\n  formula: Discounts ÷ gross sales (order subtotals before discounts)\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: subtotal\n        description: Price × quantity of every item, before discounts, tax and shipping.\n      - name: discount\n        description: The total discount taken off the subtotal, from codes and automatic offers; shipping discounts excluded.\n      - name: coupon\n        description: The code redeemed on the order, if any.\n      - name: is_first_order\n        description: True when it is the customer's first ever paid order.\n\nnumerator:\n  label: Discounts\n  aggregate: sum\n  event: order_completed\n  property: discount\ndenominator:\n  label: Gross sales\n  aggregate: sum\n  event: order_completed\n  property: subtotal\n\nnoise:\n  type: process\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 0.1\n\nexample:\n  business: store\n  level: 0.089\n  volume: 13300\n  trend: 0.05\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a new discount app or checkout stop sending the discount on the order event?\n      yes: Orders with a coupon but a zero discount appear from one day.\n    spiked:\n      check: Did discount start including shipping discounts, gift cards or tax, or subtotal change basis?\n      yes: The rate steps up on one release day with no new offer.\n  - id: calendar\n    label: Sales and the calendar\n    feed: shopping\n    dropped:\n      check: Did a sale end, or was last week a sale week?\n      yes: The same week last year shows the same fall once aligned on the event.\n    spiked:\n      check: Is a sale running, store-wide or on a code? Check orders rose with it.\n      yes: The rise matches the sale's dates, and the same week last year shows it too.\n  - id: codes\n    label: Discount codes\n    metric: promo-code-usage-rate\n    breakdown: coupon\n    dropped:\n      check: Did fewer orders use a code, because a code expired or a leaked one was disabled?\n      yes: Code usage falls by about as much as the discount rate.\n    spiked:\n      check: Did a code leak, or did an influencer or affiliate code take off?\n      yes: One code explains most of the rise, often on orders from channels it was never sent to.\n  - id: offer-depth\n    label: Depth of offers\n    dropped:\n      check: Did the offer get shallower, such as 15% off instead of 25%?\n      yes: The discount per discounted order falls while the number of discounted orders holds.\n    spiked:\n      check: Did a deeper offer run, or did two offers start stacking?\n      yes: The discount per discounted order rises; stacked orders carry both a code and an automatic offer.\n  - id: first-orders\n    label: Welcome offers\n    breakdown: is_first_order\n    dropped:\n      check: Did fewer first-time customers order with a welcome discount?\n      yes: The rate holds within each group and only the share of first orders moved.\n    spiked:\n      check: Did more first-time customers order with a welcome discount, or did the welcome offer grow?\n      yes: The rate on first orders rises, or first orders take a larger share.\n\ndiagnose_order: [tracking, calendar, codes, offer-depth, first-orders]\n\nrelated: [promo-code-usage-rate, gross-sales, gross-margin, aov, net-revenue]\n\nprose:\n  why_it_matters: >-\n    Discount rate is the price of the growth a store buys with promotions, and it creeps as\n    welcome codes, influencer codes, leaked codes and stacked offers each add a point nobody\n    chose. At Northwind, 8.5% of $1.45M of gross sales is about $123,000 a week, and each extra\n    point costs $14,500 of margin a week.\n  pitfalls:\n    - Markdowns made by lowering the product's price never show as discounts. A store that moves from codes to markdowns sees its discount rate fall while it gives away more.\n    - Free-shipping offers aren't in subtotal or discount. Track their cost separately or the price of a free-shipping promotion stays invisible.\n    - Discounts over gross sales measure cost, while the average discount on discounted orders measures offer depth. Don't compare one with the other's benchmark.\n    - Read it with orders. A sale that adds five points of discount and 30% more orders may be the best week of the quarter; the same five points with flat orders gave margin away.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"discount-rate","name":"Discount rate","aliases":["Discount percentage","Discounts as a share of sales","Average discount rate","Promotional discount rate"],"family":"revenue","kind":"rate","polarity":"down-is-good","definition":{"one_line":"The share of gross sales given away as discounts at checkout, from codes, automatic offers and bundle deals.","formula":"Discounts ÷ gross sales (order subtotals before discounts)"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"subtotal","description":"Price × quantity of every item, before discounts, tax and shipping."},{"name":"discount","description":"The total discount taken off the subtotal, from codes and automatic offers; shipping discounts excluded."},{"name":"coupon","description":"The code redeemed on the order, if any."},{"name":"is_first_order","description":"True when it is the customer's first ever paid order."}]}],"numerator":{"label":"Discounts","aggregate":"sum","event":"order_completed","property":"discount"},"denominator":{"label":"Gross sales","aggregate":"sum","event":"order_completed","property":"subtotal"},"noise":{"type":"process","min_denominator":50,"volume_unit":"orders a week","typical":0.1},"example":{"business":"store","level":0.089,"volume":13300,"trend":0.05,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a new discount app or checkout stop sending the discount on the order event?","yes":"Orders with a coupon but a zero discount appear from one day."},"spiked":{"check":"Did discount start including shipping discounts, gift cards or tax, or subtotal change basis?","yes":"The rate steps up on one release day with no new offer."}},{"id":"calendar","label":"Sales and the calendar","feed":"shopping","dropped":{"check":"Did a sale end, or was last week a sale week?","yes":"The same week last year shows the same fall once aligned on the event."},"spiked":{"check":"Is a sale running, store-wide or on a code? Check orders rose with it.","yes":"The rise matches the sale's dates, and the same week last year shows it too."}},{"id":"codes","label":"Discount codes","metric":"promo-code-usage-rate","breakdown":"coupon","dropped":{"check":"Did fewer orders use a code, because a code expired or a leaked one was disabled?","yes":"Code usage falls by about as much as the discount rate."},"spiked":{"check":"Did a code leak, or did an influencer or affiliate code take off?","yes":"One code explains most of the rise, often on orders from channels it was never sent to."}},{"id":"offer-depth","label":"Depth of offers","dropped":{"check":"Did the offer get shallower, such as 15% off instead of 25%?","yes":"The discount per discounted order falls while the number of discounted orders holds."},"spiked":{"check":"Did a deeper offer run, or did two offers start stacking?","yes":"The discount per discounted order rises; stacked orders carry both a code and an automatic offer."}},{"id":"first-orders","label":"Welcome offers","breakdown":"is_first_order","dropped":{"check":"Did fewer first-time customers order with a welcome discount?","yes":"The rate holds within each group and only the share of first orders moved."},"spiked":{"check":"Did more first-time customers order with a welcome discount, or did the welcome offer grow?","yes":"The rate on first orders rises, or first orders take a larger share."}}],"diagnose_order":["tracking","calendar","codes","offer-depth","first-orders"],"related":["promo-code-usage-rate","gross-sales","gross-margin","aov","net-revenue"],"prose":{"why_it_matters":"Discount rate is the price of the growth a store buys with promotions, and it creeps as welcome codes, influencer codes, leaked codes and stacked offers each add a point nobody chose. At Northwind, 8.5% of $1.45M of gross sales is about $123,000 a week, and each extra point costs $14,500 of margin a week.","pitfalls":["Markdowns made by lowering the product's price never show as discounts. A store that moves from codes to markdowns sees its discount rate fall while it gives away more.","Free-shipping offers aren't in subtotal or discount. Track their cost separately or the price of a free-shipping promotion stays invisible.","Discounts over gross sales measure cost, while the average discount on discounted orders measures offer depth. Don't compare one with the other's benchmark.","Read it with orders. A sale that adds five points of discount and 30% more orders may be the best week of the quarter; the same five points with flat orders gave margin away."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "email-click-rate": { yaml: "id: email-click-rate\nname: Email click rate\naliases:\n  - Email CTR\n  - Email click-through rate\n  - Email unique click rate\n  - Newsletter click rate\nfamily: traffic\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of emails delivered in the week whose recipient clicked at least one link in them.\n  formula: Distinct recipient and campaign pairs with a click ÷ distinct recipient and campaign pairs delivered\n\nevents:\n  - name: email_delivered\n    description: The receiving server accepted the email. Bounced and suppressed sends are not deliveries.\n    also_called: [Email Delivered, Received Email, delivered]\n    properties:\n      - name: campaign_id\n        description: The campaign or automated flow message the email belongs to.\n  - name: email_clicked\n    description: A tracked link in the email was opened. One recipient can click many times.\n    also_called: [Email Link Clicked, Clicked Email, click]\n    properties:\n      - name: campaign_id\n        description: The campaign or automated flow message the click belongs to.\n\nnumerator:\n  label: Recipients who clicked\n  aggregate: unique_users\n  event: email_clicked\ndenominator:\n  label: Emails delivered\n  aggregate: count\n  event: email_delivered\n\nqueries:\n  hogql: |-\n    -- Email click rate per week: distinct recipient and campaign pairs that clicked ÷ pairs delivered, each by the week it happened. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(e.clicked, 0) AS numerator,\n      coalesce(e.delivered, 0) AS denominator,\n      if(coalesce(e.delivered, 0) = 0, NULL, e.clicked / e.delivered) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT\n        toMonday(toTimeZone(timestamp, 'UTC')) AS week,\n        uniqExactIf(concat(toString(person_id), ':', toString(properties.campaign_id)), event = 'email_clicked') AS clicked,\n        uniqExactIf(concat(toString(person_id), ':', toString(properties.campaign_id)), event = 'email_delivered') AS delivered\n      FROM events\n      WHERE event IN ('email_delivered', 'email_clicked')\n        AND timestamp >= now() - toIntervalWeek(27)\n        AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n      GROUP BY week\n    ) AS e ON e.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Email click rate per week: distinct recipient and campaign pairs that clicked ÷ pairs delivered, each by the week it happened. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    emails AS (\n      SELECT\n        date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n        count(DISTINCT user_id || ':' || (properties->>'campaign_id')) FILTER (WHERE event_name = 'email_clicked') AS clicked,\n        count(DISTINCT user_id || ':' || (properties->>'campaign_id')) FILTER (WHERE event_name = 'email_delivered') AS delivered\n      FROM events\n      WHERE event_name IN ('email_delivered', 'email_clicked')\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n      GROUP BY 1\n    )\n    SELECT\n      w.week,\n      coalesce(e.clicked, 0) AS numerator,\n      coalesce(e.delivered, 0) AS denominator,\n      e.clicked::numeric / nullif(e.delivered, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN emails AS e ON e.week = w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Email click rate per week: distinct recipient and campaign pairs that clicked ÷ pairs delivered, each by the week it happened. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    emails AS (\n      SELECT\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n        COUNT(DISTINCT IF(event_name = 'email_clicked', CONCAT(user_id, ':', JSON_VALUE(properties, '$.campaign_id')), NULL)) AS clicked,\n        COUNT(DISTINCT IF(event_name = 'email_delivered', CONCAT(user_id, ':', JSON_VALUE(properties, '$.campaign_id')), NULL)) AS delivered\n      FROM events\n      WHERE event_name IN ('email_delivered', 'email_clicked')\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      COALESCE(e.clicked, 0) AS numerator,\n      COALESCE(e.delivered, 0) AS denominator,\n      SAFE_DIVIDE(e.clicked, e.delivered) AS value\n    FROM weeks AS w\n    LEFT JOIN emails AS e ON e.week = w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Email click rate per week: distinct recipient and campaign pairs that clicked ÷ pairs delivered, each by the week it happened. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    emails AS (\n      SELECT\n        DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n        COUNT(DISTINCT IFF(event_name = 'email_clicked', user_id || ':' || properties:\"campaign_id\"::string, NULL)) AS clicked,\n        COUNT(DISTINCT IFF(event_name = 'email_delivered', user_id || ':' || properties:\"campaign_id\"::string, NULL)) AS delivered\n      FROM events\n      WHERE event_name IN ('email_delivered', 'email_clicked')\n        AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n      GROUP BY 1\n    )\n    SELECT\n      w.week,\n      COALESCE(e.clicked, 0) AS numerator,\n      COALESCE(e.delivered, 0) AS denominator,\n      e.clicked::float / NULLIF(e.delivered, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN emails AS e ON e.week = w.week\n    ORDER BY w.week;\n\nnoise:\n  type: binomial\n  min_denominator: 2000\n  volume_unit: emails delivered a week\n  typical: 0.02\n  reference_volumes: [5000, 20000, 100000, 500000]\n\nexample:\n  business: store\n  level: 0.019\n  volume: 240000\n  trend: -0.05\n  season: -0.5\n\ndrivers:\n  - id: tracking\n    label: Link tracking and sync\n    dropped:\n      check: Did the email platform's sync, the click-tracking domain or its certificate break?\n      yes: Clicks fall to near zero for some campaigns while email-driven sessions in analytics hold.\n    spiked:\n      check: Is a sync sending click events twice, or counting each click as a new recipient?\n      yes: Clicks per clicker jump and the rise is identical across every campaign.\n  - id: bot-clicks\n    label: Security scanners\n    dropped:\n      check: Did your email platform start filtering bot clicks?\n      yes: The fall starts on the day of a platform release, mostly on business email domains.\n    spiked:\n      check: Are corporate security scanners clicking every link seconds after delivery?\n      yes: Clicks land within a minute of delivery, hit every link in the email, and produce no sessions.\n  - id: calendar\n    label: Calendar and inbox competition\n    feed: shopping\n    dropped:\n      check: Is this a week when every brand is emailing, such as Black Friday or the week before Christmas?\n      yes: The same week last year shows the same dip in click rate even as revenue from email rises.\n    spiked:\n      check: Was last week a crowded inbox week that this week isn't?\n      yes: The same pair of weeks last year shows the same recovery.\n  - id: audience\n    label: Who was sent to\n    breakdown: campaign_id\n    dropped:\n      check: Did a send go to a larger, less engaged audience, such as the whole list or an old segment?\n      yes: Deliveries jump for one campaign whose click rate is far below the usual ones.\n    spiked:\n      check: Did the week's sends go only to engaged segments, or did a big unengaged send drop out?\n      yes: Deliveries fall while clicks hold, so the rate rises with no change in content.\n  - id: deliverability\n    label: Inbox placement\n    dropped:\n      check: Did emails start landing in spam or the Promotions tab, after a sending change or a spam complaint spike?\n      yes: Deliveries hold but clicks fall on Gmail or Outlook addresses only.\n    spiked:\n      check: Did a sending-domain or authentication fix move emails back to the inbox?\n      yes: Clicks recover on one mailbox provider from the day of the fix.\n  - id: offer\n    label: Offer and content\n    metric: promo-code-usage-rate\n    dropped:\n      check: Did this week's emails carry a weaker offer, no product news or fewer links?\n      yes: Click rate falls on campaigns while automated flows hold.\n    spiked:\n      check: Did a sale, a launch or a restock email go out?\n      yes: One campaign's click rate is several times the usual and accounts for the rise.\n\ndiagnose_order: [tracking, bot-clicks, calendar, audience, deliverability, offer]\n\nrelated: [sessions, new-visitor-share, repeat-purchase-rate, returning-customers, promo-code-usage-rate]\n\nprose:\n  why_it_matters: >-\n    Email is the cheapest repeat traffic a store has, and click rate is the first sign that a\n    list is tiring or a send is landing in spam. Opens stopped meaning much when Apple Mail\n    began pre-loading every email in 2021; clicks still need a person. On 240,000 deliveries a\n    week, half a point is 1,200 fewer people on the site from email.\n  pitfalls:\n    - Use unique clicks over delivered emails. Total clicks over sends counts one keen reader five times and counts bounced addresses as failures.\n    - Corporate security scanners click every link in an email within seconds of delivery. Without bot filtering, business-heavy lists show click rates two or three times the real one.\n    - Clicks are counted in the week they happen, so a Sunday send's clicks fall partly into the next week. Compare weeks with similar send schedules.\n    - Click-to-open rate is a different number. Apple Mail Privacy Protection inflates opens, so it falls for reasons that have nothing to do with the email.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"email-click-rate","name":"Email click rate","aliases":["Email CTR","Email click-through rate","Email unique click rate","Newsletter click rate"],"family":"traffic","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of emails delivered in the week whose recipient clicked at least one link in them.","formula":"Distinct recipient and campaign pairs with a click ÷ distinct recipient and campaign pairs delivered"},"events":[{"name":"email_delivered","description":"The receiving server accepted the email. Bounced and suppressed sends are not deliveries.","also_called":["Email Delivered","Received Email","delivered"],"properties":[{"name":"campaign_id","description":"The campaign or automated flow message the email belongs to."}]},{"name":"email_clicked","description":"A tracked link in the email was opened. One recipient can click many times.","also_called":["Email Link Clicked","Clicked Email","click"],"properties":[{"name":"campaign_id","description":"The campaign or automated flow message the click belongs to."}]}],"numerator":{"label":"Recipients who clicked","aggregate":"unique_users","event":"email_clicked"},"denominator":{"label":"Emails delivered","aggregate":"count","event":"email_delivered"},"queries":{"hogql":"-- Email click rate per week: distinct recipient and campaign pairs that clicked ÷ pairs delivered, each by the week it happened. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(e.clicked, 0) AS numerator,\n  coalesce(e.delivered, 0) AS denominator,\n  if(coalesce(e.delivered, 0) = 0, NULL, e.clicked / e.delivered) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT\n    toMonday(toTimeZone(timestamp, 'UTC')) AS week,\n    uniqExactIf(concat(toString(person_id), ':', toString(properties.campaign_id)), event = 'email_clicked') AS clicked,\n    uniqExactIf(concat(toString(person_id), ':', toString(properties.campaign_id)), event = 'email_delivered') AS delivered\n  FROM events\n  WHERE event IN ('email_delivered', 'email_clicked')\n    AND timestamp >= now() - toIntervalWeek(27)\n    AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n  GROUP BY week\n) AS e ON e.week = w.week\nORDER BY week","postgres":"-- Email click rate per week: distinct recipient and campaign pairs that clicked ÷ pairs delivered, each by the week it happened. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nemails AS (\n  SELECT\n    date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n    count(DISTINCT user_id || ':' || (properties->>'campaign_id')) FILTER (WHERE event_name = 'email_clicked') AS clicked,\n    count(DISTINCT user_id || ':' || (properties->>'campaign_id')) FILTER (WHERE event_name = 'email_delivered') AS delivered\n  FROM events\n  WHERE event_name IN ('email_delivered', 'email_clicked')\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n  GROUP BY 1\n)\nSELECT\n  w.week,\n  coalesce(e.clicked, 0) AS numerator,\n  coalesce(e.delivered, 0) AS denominator,\n  e.clicked::numeric / nullif(e.delivered, 0) AS value\nFROM weeks AS w\nLEFT JOIN emails AS e ON e.week = w.week\nORDER BY w.week;","bigquery":"-- Email click rate per week: distinct recipient and campaign pairs that clicked ÷ pairs delivered, each by the week it happened. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nemails AS (\n  SELECT\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n    COUNT(DISTINCT IF(event_name = 'email_clicked', CONCAT(user_id, ':', JSON_VALUE(properties, '$.campaign_id')), NULL)) AS clicked,\n    COUNT(DISTINCT IF(event_name = 'email_delivered', CONCAT(user_id, ':', JSON_VALUE(properties, '$.campaign_id')), NULL)) AS delivered\n  FROM events\n  WHERE event_name IN ('email_delivered', 'email_clicked')\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY week\n)\nSELECT\n  w.week,\n  COALESCE(e.clicked, 0) AS numerator,\n  COALESCE(e.delivered, 0) AS denominator,\n  SAFE_DIVIDE(e.clicked, e.delivered) AS value\nFROM weeks AS w\nLEFT JOIN emails AS e ON e.week = w.week\nORDER BY w.week;","snowflake":"-- Email click rate per week: distinct recipient and campaign pairs that clicked ÷ pairs delivered, each by the week it happened. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nemails AS (\n  SELECT\n    DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n    COUNT(DISTINCT IFF(event_name = 'email_clicked', user_id || ':' || properties:\"campaign_id\"::string, NULL)) AS clicked,\n    COUNT(DISTINCT IFF(event_name = 'email_delivered', user_id || ':' || properties:\"campaign_id\"::string, NULL)) AS delivered\n  FROM events\n  WHERE event_name IN ('email_delivered', 'email_clicked')\n    AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n  GROUP BY 1\n)\nSELECT\n  w.week,\n  COALESCE(e.clicked, 0) AS numerator,\n  COALESCE(e.delivered, 0) AS denominator,\n  e.clicked::float / NULLIF(e.delivered, 0) AS value\nFROM weeks AS w\nLEFT JOIN emails AS e ON e.week = w.week\nORDER BY w.week;"},"noise":{"type":"binomial","min_denominator":2000,"volume_unit":"emails delivered a week","typical":0.02,"reference_volumes":[5000,20000,100000,500000]},"example":{"business":"store","level":0.019,"volume":240000,"trend":-0.05,"season":-0.5},"drivers":[{"id":"tracking","label":"Link tracking and sync","dropped":{"check":"Did the email platform's sync, the click-tracking domain or its certificate break?","yes":"Clicks fall to near zero for some campaigns while email-driven sessions in analytics hold."},"spiked":{"check":"Is a sync sending click events twice, or counting each click as a new recipient?","yes":"Clicks per clicker jump and the rise is identical across every campaign."}},{"id":"bot-clicks","label":"Security scanners","dropped":{"check":"Did your email platform start filtering bot clicks?","yes":"The fall starts on the day of a platform release, mostly on business email domains."},"spiked":{"check":"Are corporate security scanners clicking every link seconds after delivery?","yes":"Clicks land within a minute of delivery, hit every link in the email, and produce no sessions."}},{"id":"calendar","label":"Calendar and inbox competition","feed":"shopping","dropped":{"check":"Is this a week when every brand is emailing, such as Black Friday or the week before Christmas?","yes":"The same week last year shows the same dip in click rate even as revenue from email rises."},"spiked":{"check":"Was last week a crowded inbox week that this week isn't?","yes":"The same pair of weeks last year shows the same recovery."}},{"id":"audience","label":"Who was sent to","breakdown":"campaign_id","dropped":{"check":"Did a send go to a larger, less engaged audience, such as the whole list or an old segment?","yes":"Deliveries jump for one campaign whose click rate is far below the usual ones."},"spiked":{"check":"Did the week's sends go only to engaged segments, or did a big unengaged send drop out?","yes":"Deliveries fall while clicks hold, so the rate rises with no change in content."}},{"id":"deliverability","label":"Inbox placement","dropped":{"check":"Did emails start landing in spam or the Promotions tab, after a sending change or a spam complaint spike?","yes":"Deliveries hold but clicks fall on Gmail or Outlook addresses only."},"spiked":{"check":"Did a sending-domain or authentication fix move emails back to the inbox?","yes":"Clicks recover on one mailbox provider from the day of the fix."}},{"id":"offer","label":"Offer and content","metric":"promo-code-usage-rate","dropped":{"check":"Did this week's emails carry a weaker offer, no product news or fewer links?","yes":"Click rate falls on campaigns while automated flows hold."},"spiked":{"check":"Did a sale, a launch or a restock email go out?","yes":"One campaign's click rate is several times the usual and accounts for the rise."}}],"diagnose_order":["tracking","bot-clicks","calendar","audience","deliverability","offer"],"related":["sessions","new-visitor-share","repeat-purchase-rate","returning-customers","promo-code-usage-rate"],"prose":{"why_it_matters":"Email is the cheapest repeat traffic a store has, and click rate is the first sign that a list is tiring or a send is landing in spam. Opens stopped meaning much when Apple Mail began pre-loading every email in 2021; clicks still need a person. On 240,000 deliveries a week, half a point is 1,200 fewer people on the site from email.","pitfalls":["Use unique clicks over delivered emails. Total clicks over sends counts one keen reader five times and counts bounced addresses as failures.","Corporate security scanners click every link in an email within seconds of delivery. Without bot filtering, business-heavy lists show click rates two or three times the real one.","Clicks are counted in the week they happen, so a Sunday send's clicks fall partly into the next week. Compare weeks with similar send schedules.","Click-to-open rate is a different number. Apple Mail Privacy Protection inflates opens, so it falls for reasons that have nothing to do with the email."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "error-rate": { yaml: "id: error-rate\nname: Error rate\naliases:\n  - Session error rate\n  - Exception rate\n  - Sessions with errors\n  - JavaScript error rate\nfamily: engagement\nkind: rate\npolarity: down-is-good\n\ndefinition:\n  one_line: The share of sessions in which the product raised at least one error, Monday to Sunday UTC.\n  formula: Sessions with at least one exception ÷ sessions\n\nevents:\n  - name: $exception\n    description: An error the product raised and the SDK captured, one event per exception.\n    also_called: [Exception, error, app_crash]\n    properties:\n      - name: $exception_type\n        description: The error's type or class, for grouping.\n      - name: $session_id\n        description: The session it happened in; must match the session id on other events.\n  - name: \"*\"\n    description: Any event a person sends; its session id counts the sessions the rate divides by.\n    also_called: [All events, Any event]\n    properties:\n      - name: $browser\n        description: The browser, for splitting web sessions.\n      - name: $app_version\n        description: The app version, for splitting mobile sessions by release.\n\nnumerator:\n  label: Sessions with an error\n  aggregate: unique_sessions\n  event: $exception\ndenominator:\n  label: Sessions\n  aggregate: unique_sessions\n  event: \"*\"\n\nnoise:\n  type: binomial\n  min_denominator: 500\n  volume_unit: sessions a week\n  typical: 0.018\n  reference_volumes: [2000, 10000, 50000, 200000]\n\nexample:\n  business: app\n  level: 0.018\n  volume: 180000\n  trend: 0.15\n\ndrivers:\n  - id: instrumentation\n    label: Error capture\n    dropped:\n      check: Did error reporting break, get sampled down, or get blocked on one platform?\n      yes: Exceptions fall to near zero on one platform, or the SDK version or sampling setting changed the day it fell.\n    spiked:\n      check: Did error capture get wider, from a new SDK, autocapture turned on or a new platform reporting?\n      yes: Errors rise from the day capture changed, mostly types that existed before but weren't recorded.\n  - id: third-party\n    label: Providers and third-party scripts\n    feed: cloudflare\n    dropped:\n      check: Did a provider incident from last week clear?\n      yes: Network and script-load errors fall back to their usual level after the incident ended.\n    spiked:\n      check: Did a CDN, API provider or third-party script fail?\n      yes: Network and script-load errors rise across app versions at the time of a provider incident.\n  - id: release\n    label: Releases\n    breakdown: $app_version\n    feed: app-stores\n    dropped:\n      check: Did a fix ship, and are people updating to it?\n      yes: The top error falls as the fixed version's share of sessions rises.\n    spiked:\n      check: Did a release ship this week, and are the new errors from its version?\n      yes: One error type appears on the new version only, starting the day it rolled out.\n  - id: browser\n    label: Browser and device\n    breakdown: $browser\n    dropped:\n      check: Did a browser update fix a compatibility problem?\n      yes: One browser's error rate falls on its release date while the others hold.\n    spiked:\n      check: Is it one browser or browser version, for example after a browser update?\n      yes: One browser's error rate jumps on its release date while the others hold.\n  - id: session-mix\n    label: What counts as a session\n    metric: sessions\n    dropped:\n      check: Did a wave of short sessions from a campaign or bots inflate the denominator?\n      yes: Sessions jump from one source with very few events each, while errors per real session hold.\n    spiked:\n      check: Did bots or a crawler start running sessions that hit errors?\n      yes: Error sessions concentrate on one user agent or country with no real usage.\n\ndiagnose_order: [instrumentation, third-party, release, browser, session-mix]\n\nrelated: [sessions-per-user, dau, week-1-retention, bounce-rate, conversion-rate]\n\nprose:\n  why_it_matters: >-\n    Error rate counts sessions that hit at least one exception, which is closer to what people\n    feel than a raw error count: a broken page that throws fifty errors is one bad session. It\n    is the fastest quality signal after a release. At 180,000 sessions a week and 1.8%, chance\n    moves it by less than 0.1 point, so almost any visible change has a cause.\n  pitfalls:\n    - Counting errors instead of sessions with errors lets one looping page dominate the number. This spec counts each session once.\n    - Error capture changes with SDK versions, sampling and ad blockers. A jump on the day capture changed is a measurement change, not a quality change.\n    - Browser extensions, third-party scripts and bots throw errors you can't fix. Filter them, or the rate moves with things outside the product.\n    - Exceptions without the session id used by other events never reach the numerator. Check that both carry the same $session_id.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"error-rate","name":"Error rate","aliases":["Session error rate","Exception rate","Sessions with errors","JavaScript error rate"],"family":"engagement","kind":"rate","polarity":"down-is-good","definition":{"one_line":"The share of sessions in which the product raised at least one error, Monday to Sunday UTC.","formula":"Sessions with at least one exception ÷ sessions"},"events":[{"name":"$exception","description":"An error the product raised and the SDK captured, one event per exception.","also_called":["Exception","error","app_crash"],"properties":[{"name":"$exception_type","description":"The error's type or class, for grouping."},{"name":"$session_id","description":"The session it happened in; must match the session id on other events."}]},{"name":"*","description":"Any event a person sends; its session id counts the sessions the rate divides by.","also_called":["All events","Any event"],"properties":[{"name":"$browser","description":"The browser, for splitting web sessions."},{"name":"$app_version","description":"The app version, for splitting mobile sessions by release."}]}],"numerator":{"label":"Sessions with an error","aggregate":"unique_sessions","event":"$exception"},"denominator":{"label":"Sessions","aggregate":"unique_sessions","event":"*"},"noise":{"type":"binomial","min_denominator":500,"volume_unit":"sessions a week","typical":0.018,"reference_volumes":[2000,10000,50000,200000]},"example":{"business":"app","level":0.018,"volume":180000,"trend":0.15},"drivers":[{"id":"instrumentation","label":"Error capture","dropped":{"check":"Did error reporting break, get sampled down, or get blocked on one platform?","yes":"Exceptions fall to near zero on one platform, or the SDK version or sampling setting changed the day it fell."},"spiked":{"check":"Did error capture get wider, from a new SDK, autocapture turned on or a new platform reporting?","yes":"Errors rise from the day capture changed, mostly types that existed before but weren't recorded."}},{"id":"third-party","label":"Providers and third-party scripts","feed":"cloudflare","dropped":{"check":"Did a provider incident from last week clear?","yes":"Network and script-load errors fall back to their usual level after the incident ended."},"spiked":{"check":"Did a CDN, API provider or third-party script fail?","yes":"Network and script-load errors rise across app versions at the time of a provider incident."}},{"id":"release","label":"Releases","breakdown":"$app_version","feed":"app-stores","dropped":{"check":"Did a fix ship, and are people updating to it?","yes":"The top error falls as the fixed version's share of sessions rises."},"spiked":{"check":"Did a release ship this week, and are the new errors from its version?","yes":"One error type appears on the new version only, starting the day it rolled out."}},{"id":"browser","label":"Browser and device","breakdown":"$browser","dropped":{"check":"Did a browser update fix a compatibility problem?","yes":"One browser's error rate falls on its release date while the others hold."},"spiked":{"check":"Is it one browser or browser version, for example after a browser update?","yes":"One browser's error rate jumps on its release date while the others hold."}},{"id":"session-mix","label":"What counts as a session","metric":"sessions","dropped":{"check":"Did a wave of short sessions from a campaign or bots inflate the denominator?","yes":"Sessions jump from one source with very few events each, while errors per real session hold."},"spiked":{"check":"Did bots or a crawler start running sessions that hit errors?","yes":"Error sessions concentrate on one user agent or country with no real usage."}}],"diagnose_order":["instrumentation","third-party","release","browser","session-mix"],"related":["sessions-per-user","dau","week-1-retention","bounce-rate","conversion-rate"],"prose":{"why_it_matters":"Error rate counts sessions that hit at least one exception, which is closer to what people feel than a raw error count: a broken page that throws fifty errors is one bad session. It is the fastest quality signal after a release. At 180,000 sessions a week and 1.8%, chance moves it by less than 0.1 point, so almost any visible change has a cause.","pitfalls":["Counting errors instead of sessions with errors lets one looping page dominate the number. This spec counts each session once.","Error capture changes with SDK versions, sampling and ad blockers. A jump on the day capture changed is a measurement change, not a quality change.","Browser extensions, third-party scripts and bots throw errors you can't fix. Filter them, or the rate moves with things outside the product.","Exceptions without the session id used by other events never reach the numerator. Check that both carry the same $session_id."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "expansion-mrr": { yaml: "id: expansion-mrr\nname: Expansion MRR\naliases:\n  - Expansion revenue\n  - Upsell MRR\n  - Upgrade MRR\n  - Expansion monthly recurring revenue\nfamily: subscription\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: The monthly recurring revenue added this week by paying customers who upgraded, added seats or usage, or bought add-ons.\n  formula: Sum of monthly amount increases on subscriptions that were already paying\n\nevents:\n  - name: subscription_expanded\n    description: A paying subscription's monthly amount went up from a plan upgrade, more seats, more usage or an add-on.\n    also_called: [Subscription Upgraded, plan_upgraded, customer.subscription.updated]\n    properties:\n      - name: subscription_id\n        description: The billing system's subscription id.\n      - name: mrr_delta\n        description: How much the monthly amount rose, as a positive number, after discounts and before tax.\n      - name: plan\n        description: The plan after the change.\n\nnumerator:\n  label: Expansion MRR\n  aggregate: sum\n  event: subscription_expanded\n  property: mrr_delta\n\nnoise:\n  type: compound\n  cv: 1.2\n  min_denominator: 10\n  volume_unit: expansions a week\n  typical: 900\n  reference_volumes: [10, 40, 150, 600]\n\nexample:\n  business: saas\n  level: 890\n  volume: 24\n  trend: 0.35\n\ndrivers:\n  - id: billing-changes\n    label: Billing changes\n    dropped:\n      check: Are upgrades now recorded as a cancellation plus a new subscription, after a billing or checkout change?\n      yes: Expansion falls while new and churned MRR both rise by similar amounts on the same customers.\n    spiked:\n      check: Did a price migration, coupon expiry or currency change raise amounts without customers choosing to buy more?\n      yes: Many subscriptions expand on the same day by the same percentage, with no plan change.\n  - id: calendar\n    label: Calendar\n    feed: holidays\n    dropped:\n      check: Is this a holiday week, when customers' own teams and budgets pause?\n      yes: The same week last year shows the same dip once aligned on the holiday.\n    spiked:\n      check: Is it the start of a quarter or fiscal year, when customers add seats with new budgets?\n      yes: Seat additions cluster in the same weeks of earlier years.\n  - id: large-accounts\n    label: Large accounts\n    dropped:\n      check: Did an upgrade from a large account that usually lands now slip to another week?\n      yes: The usual large expansions are missing and the rest of the week looks ordinary.\n    spiked:\n      check: Is one account most of the week's expansion?\n      yes: A single customer explains most of the total. Treat it as a deal, not a trend.\n  - id: plan-mix\n    label: Upgrade paths by plan\n    breakdown: plan\n    dropped:\n      check: Did upgrades from one plan stop, for example after a packaging or pricing page change?\n      yes: One plan's upgrades vanish while the others hold.\n    spiked:\n      check: Is one plan upgrading far more than usual?\n      yes: One plan explains most of the rise, starting the week its limits or price changed.\n  - id: usage-limits\n    label: Seats and usage limits\n    dropped:\n      check: Are customers adding fewer seats or less usage, for example from hiring freezes on their side?\n      yes: Seat and usage additions per account fall across plans, not in one segment.\n    spiked:\n      check: Did a usage limit or a seat-based feature push accounts over a threshold?\n      yes: Expansions cluster at one plan's limit, starting the week the limit or feature shipped.\n  - id: feature-adoption\n    label: Adoption of paid features\n    metric: feature-adoption-rate\n    dropped:\n      check: Are fewer people using the feature that usually leads to an upgrade?\n      yes: Adoption of that feature fell a few weeks before expansion did.\n    spiked:\n      check: Did more people start using a feature that sits behind an upgrade?\n      yes: Adoption of the gated feature rose in the weeks before upgrades did.\n\ndiagnose_order: [billing-changes, calendar, large-accounts, plan-mix, usage-limits, feature-adoption]\n\nrelated: [mrr, net-revenue-retention, net-new-mrr, arpa, feature-adoption-rate]\n\nprose:\n  why_it_matters: >-\n    Expansion is revenue you don't have to acquire, and it is what lets net revenue retention\n    pass 100%. A company whose paying customers add 1.6% to MRR each month can lose 1.6% to churn\n    and still hold its base without a single new customer. It arrives in lumps, from seat\n    additions and plan upgrades, so one week says little; four weeks of it against churn say a lot.\n  pitfalls:\n    - A customer who cancels and immediately buys a bigger plan shows up as churn plus new business, which hides expansion and inflates both. Record plan changes on the same subscription.\n    - Price increases and coupon expiries raise MRR without anyone choosing to buy more. Tag them, because they won't repeat.\n    - Usage-based charges that swing month to month add expansion one month and contraction the next. Net them per account per month, or both flows look larger than they are.\n    - A churned customer who comes back is reactivation, not expansion. Keep it with new MRR or on its own line.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"expansion-mrr","name":"Expansion MRR","aliases":["Expansion revenue","Upsell MRR","Upgrade MRR","Expansion monthly recurring revenue"],"family":"subscription","kind":"currency","polarity":"up-is-good","definition":{"one_line":"The monthly recurring revenue added this week by paying customers who upgraded, added seats or usage, or bought add-ons.","formula":"Sum of monthly amount increases on subscriptions that were already paying"},"events":[{"name":"subscription_expanded","description":"A paying subscription's monthly amount went up from a plan upgrade, more seats, more usage or an add-on.","also_called":["Subscription Upgraded","plan_upgraded","customer.subscription.updated"],"properties":[{"name":"subscription_id","description":"The billing system's subscription id."},{"name":"mrr_delta","description":"How much the monthly amount rose, as a positive number, after discounts and before tax."},{"name":"plan","description":"The plan after the change."}]}],"numerator":{"label":"Expansion MRR","aggregate":"sum","event":"subscription_expanded","property":"mrr_delta"},"noise":{"type":"compound","cv":1.2,"min_denominator":10,"volume_unit":"expansions a week","typical":900,"reference_volumes":[10,40,150,600]},"example":{"business":"saas","level":890,"volume":24,"trend":0.35},"drivers":[{"id":"billing-changes","label":"Billing changes","dropped":{"check":"Are upgrades now recorded as a cancellation plus a new subscription, after a billing or checkout change?","yes":"Expansion falls while new and churned MRR both rise by similar amounts on the same customers."},"spiked":{"check":"Did a price migration, coupon expiry or currency change raise amounts without customers choosing to buy more?","yes":"Many subscriptions expand on the same day by the same percentage, with no plan change."}},{"id":"calendar","label":"Calendar","feed":"holidays","dropped":{"check":"Is this a holiday week, when customers' own teams and budgets pause?","yes":"The same week last year shows the same dip once aligned on the holiday."},"spiked":{"check":"Is it the start of a quarter or fiscal year, when customers add seats with new budgets?","yes":"Seat additions cluster in the same weeks of earlier years."}},{"id":"large-accounts","label":"Large accounts","dropped":{"check":"Did an upgrade from a large account that usually lands now slip to another week?","yes":"The usual large expansions are missing and the rest of the week looks ordinary."},"spiked":{"check":"Is one account most of the week's expansion?","yes":"A single customer explains most of the total. Treat it as a deal, not a trend."}},{"id":"plan-mix","label":"Upgrade paths by plan","breakdown":"plan","dropped":{"check":"Did upgrades from one plan stop, for example after a packaging or pricing page change?","yes":"One plan's upgrades vanish while the others hold."},"spiked":{"check":"Is one plan upgrading far more than usual?","yes":"One plan explains most of the rise, starting the week its limits or price changed."}},{"id":"usage-limits","label":"Seats and usage limits","dropped":{"check":"Are customers adding fewer seats or less usage, for example from hiring freezes on their side?","yes":"Seat and usage additions per account fall across plans, not in one segment."},"spiked":{"check":"Did a usage limit or a seat-based feature push accounts over a threshold?","yes":"Expansions cluster at one plan's limit, starting the week the limit or feature shipped."}},{"id":"feature-adoption","label":"Adoption of paid features","metric":"feature-adoption-rate","dropped":{"check":"Are fewer people using the feature that usually leads to an upgrade?","yes":"Adoption of that feature fell a few weeks before expansion did."},"spiked":{"check":"Did more people start using a feature that sits behind an upgrade?","yes":"Adoption of the gated feature rose in the weeks before upgrades did."}}],"diagnose_order":["billing-changes","calendar","large-accounts","plan-mix","usage-limits","feature-adoption"],"related":["mrr","net-revenue-retention","net-new-mrr","arpa","feature-adoption-rate"],"prose":{"why_it_matters":"Expansion is revenue you don't have to acquire, and it is what lets net revenue retention pass 100%. A company whose paying customers add 1.6% to MRR each month can lose 1.6% to churn and still hold its base without a single new customer. It arrives in lumps, from seat additions and plan upgrades, so one week says little; four weeks of it against churn say a lot.","pitfalls":["A customer who cancels and immediately buys a bigger plan shows up as churn plus new business, which hides expansion and inflates both. Record plan changes on the same subscription.","Price increases and coupon expiries raise MRR without anyone choosing to buy more. Tag them, because they won't repeat.","Usage-based charges that swing month to month add expansion one month and contraction the next. Net them per account per month, or both flows look larger than they are.","A churned customer who comes back is reactivation, not expansion. Keep it with new MRR or on its own line."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "feature-adoption-rate": { yaml: "id: feature-adoption-rate\nname: Feature adoption rate\naliases:\n  - Feature adoption\n  - Feature usage rate\n  - Feature engagement rate\nfamily: engagement\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of this week's active people who used a given feature at least once.\n  formula: Distinct people with feature_used for the feature ÷ distinct active people, in the same week; set the feature filter to yours\n\nevents:\n  - name: feature_used\n    description: A person used a feature, sent when the action completes, not when its screen opens.\n    also_called: [Feature Used, feature_clicked, feature_engaged]\n    properties:\n      - name: feature\n        description: The feature's stable name. Replace your_feature in the filter with it.\n  - name: \"*\"\n    description: Any event a person sends; the active people the rate divides by.\n    also_called: [All events, Any event, Active event]\n\nnumerator:\n  label: People who used the feature\n  aggregate: unique_users\n  event: feature_used\n  where:\n    - property: feature\n      op: eq\n      value: your_feature\ndenominator:\n  label: Active people\n  aggregate: unique_users\n  event: \"*\"\n\nnoise:\n  type: binomial\n  min_denominator: 200\n  volume_unit: weekly active users\n  typical: 0.24\n\nexample:\n  business: app\n  level: 0.24\n  volume: 52000\n  trend: 0.15\n\ndrivers:\n  - id: tracking\n    label: The feature's event\n    dropped:\n      check: Did the event stop firing, get renamed, or change its feature value on one platform?\n      yes: feature_used for this feature drops to near zero on one platform or app version.\n    spiked:\n      check: Does the event now fire on view instead of on use, or twice per use?\n      yes: Uses per person jump with no change in people, or the event fires as soon as the screen opens.\n  - id: entry-point\n    label: Where people find it\n    dropped:\n      check: Did a release move, hide or remove the way in?\n      yes: Adoption falls from the release date on the platform that shipped it.\n    spiked:\n      check: Did a launch, an announcement or a new placement put it in front of more people?\n      yes: Adoption jumps from the launch day; watch whether repeat use follows or it fades within a week.\n  - id: platform\n    label: Platform and releases\n    breakdown: $os\n    feed: app-stores\n    dropped:\n      check: Is the fall on one platform only?\n      yes: One platform falls from a release date while the others hold.\n    spiked:\n      check: Did the feature just reach a platform that lacked it?\n      yes: Adoption on the new platform climbs from zero while the others hold.\n  - id: user-mix\n    label: Who is active\n    metric: wau\n    dropped:\n      check: Did many new or casual people join the active base?\n      yes: WAU rises from new people who haven't reached the feature yet; adoption among returning people holds.\n    spiked:\n      check: Did casual people drop out of the active base?\n      yes: WAU falls while the number of people using the feature holds, so the rate rises with no new adoption.\n  - id: plan-gating\n    label: Plan access\n    breakdown: plan\n    dropped:\n      check: Did the feature move behind a paywall or a plan limit?\n      yes: Adoption falls only on free or lower plans.\n    spiked:\n      check: Did the feature become available on more plans?\n      yes: Adoption rises on the plans that just gained it.\n\ndiagnose_order: [tracking, entry-point, platform, user-mix, plan-gating]\n\nrelated: [wau, activation-rate, stickiness, week-4-retention, sessions-per-user]\n\nprose:\n  why_it_matters: >-\n    Feature adoption shows whether what you built is being found and used by the people who were\n    there to use it. It is the first number to read after a launch, and it predicts retention\n    when the feature is the reason people stay. At 52,000 weekly actives and 24% adoption, chance\n    moves the rate by only about half a point, so most visible moves have a cause.\n  pitfalls:\n    - Divide by active people, not all accounts or sign-ups, or growth in dormant accounts makes adoption look like it is falling.\n    - Send the event on use, not on view. An event that fires when the screen opens measures navigation, not adoption.\n    - A launch week measures curiosity. Judge a new feature on repeat use in the weeks after.\n    - Track one feature per series. Averaging across features hides which one moved.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"feature-adoption-rate","name":"Feature adoption rate","aliases":["Feature adoption","Feature usage rate","Feature engagement rate"],"family":"engagement","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of this week's active people who used a given feature at least once.","formula":"Distinct people with feature_used for the feature ÷ distinct active people, in the same week; set the feature filter to yours"},"events":[{"name":"feature_used","description":"A person used a feature, sent when the action completes, not when its screen opens.","also_called":["Feature Used","feature_clicked","feature_engaged"],"properties":[{"name":"feature","description":"The feature's stable name. Replace your_feature in the filter with it."}]},{"name":"*","description":"Any event a person sends; the active people the rate divides by.","also_called":["All events","Any event","Active event"]}],"numerator":{"label":"People who used the feature","aggregate":"unique_users","event":"feature_used","where":[{"property":"feature","op":"eq","value":"your_feature"}]},"denominator":{"label":"Active people","aggregate":"unique_users","event":"*"},"noise":{"type":"binomial","min_denominator":200,"volume_unit":"weekly active users","typical":0.24},"example":{"business":"app","level":0.24,"volume":52000,"trend":0.15},"drivers":[{"id":"tracking","label":"The feature's event","dropped":{"check":"Did the event stop firing, get renamed, or change its feature value on one platform?","yes":"feature_used for this feature drops to near zero on one platform or app version."},"spiked":{"check":"Does the event now fire on view instead of on use, or twice per use?","yes":"Uses per person jump with no change in people, or the event fires as soon as the screen opens."}},{"id":"entry-point","label":"Where people find it","dropped":{"check":"Did a release move, hide or remove the way in?","yes":"Adoption falls from the release date on the platform that shipped it."},"spiked":{"check":"Did a launch, an announcement or a new placement put it in front of more people?","yes":"Adoption jumps from the launch day; watch whether repeat use follows or it fades within a week."}},{"id":"platform","label":"Platform and releases","breakdown":"$os","feed":"app-stores","dropped":{"check":"Is the fall on one platform only?","yes":"One platform falls from a release date while the others hold."},"spiked":{"check":"Did the feature just reach a platform that lacked it?","yes":"Adoption on the new platform climbs from zero while the others hold."}},{"id":"user-mix","label":"Who is active","metric":"wau","dropped":{"check":"Did many new or casual people join the active base?","yes":"WAU rises from new people who haven't reached the feature yet; adoption among returning people holds."},"spiked":{"check":"Did casual people drop out of the active base?","yes":"WAU falls while the number of people using the feature holds, so the rate rises with no new adoption."}},{"id":"plan-gating","label":"Plan access","breakdown":"plan","dropped":{"check":"Did the feature move behind a paywall or a plan limit?","yes":"Adoption falls only on free or lower plans."},"spiked":{"check":"Did the feature become available on more plans?","yes":"Adoption rises on the plans that just gained it."}}],"diagnose_order":["tracking","entry-point","platform","user-mix","plan-gating"],"related":["wau","activation-rate","stickiness","week-4-retention","sessions-per-user"],"prose":{"why_it_matters":"Feature adoption shows whether what you built is being found and used by the people who were there to use it. It is the first number to read after a launch, and it predicts retention when the feature is the reason people stay. At 52,000 weekly actives and 24% adoption, chance moves the rate by only about half a point, so most visible moves have a cause.","pitfalls":["Divide by active people, not all accounts or sign-ups, or growth in dormant accounts makes adoption look like it is falling.","Send the event on use, not on view. An event that fires when the screen opens measures navigation, not adoption.","A launch week measures curiosity. Judge a new feature on repeat use in the weeks after.","Track one feature per series. Averaging across features hides which one moved."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "gross-margin": { yaml: "id: gross-margin\nname: Gross margin\naliases:\n  - Gross margin percentage\n  - Gross profit margin\n  - Product margin\nfamily: revenue\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of order revenue left after the cost of the goods sold, for orders paid this week.\n  formula: (Order revenue − cost of goods) ÷ order revenue, after discounts, before tax, shipping and refunds\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n      - name: cost_of_goods\n        description: The landed cost of the order's items, purchase price plus inbound freight and duties.\n\nnumerator:\n  label: Order revenue\n  aggregate: sum\n  event: order_completed\n  property: total\nsubtract:\n  label: Cost of goods\n  aggregate: sum\n  event: order_completed\n  property: cost_of_goods\ndenominator:\n  label: Order revenue\n  aggregate: sum\n  event: order_completed\n  property: total\n\nnoise:\n  type: process\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 0.55\n\nexample:\n  business: store\n  level: 0.532\n  volume: 13300\n  trend: -0.02\n\ndrivers:\n  - id: cost-data\n    label: Cost data\n    dropped:\n      check: Did cost_of_goods change basis, for example adding freight or loading a new supplier price list?\n      yes: Cost per unit jumps for many products on one date, with no new purchase order behind it.\n    spiked:\n      check: Are products selling without a recorded cost, counting as free?\n      yes: The share of orders with no cost_of_goods rises, usually on new products.\n  - id: discounts\n    label: Discounts and sales\n    metric: discount-rate\n    feed: shopping\n    dropped:\n      check: Did discounts rise, from a sale, a code or a stacked offer?\n      yes: Discount rate rises by about as much as margin falls.\n    spiked:\n      check: Did a sale end, so orders carry less discount?\n      yes: Discount rate falls by about as much as margin rises.\n  - id: product-mix\n    label: Product mix\n    dropped:\n      check: Did low-margin products, such as bundles, clearance or a new hero product, take a larger share of sales?\n      yes: Each product's own margin holds and only the mix moved.\n    spiked:\n      check: Did high-margin products take a larger share of sales?\n      yes: Each product's own margin holds and only the mix moved.\n  - id: landed-cost\n    label: Supplier, freight and duties\n    dropped:\n      check: Did supplier prices, freight or tariffs raise unit costs?\n      yes: Cost per unit rises on the same products, often when a new purchase order is received.\n    spiked:\n      check: Did a cheaper batch of stock start selling? Check it's not a cost data error first.\n      yes: Cost per unit falls on the products from one purchase order.\n  - id: pricing\n    label: Prices\n    dropped:\n      check: Did list prices fall, or did a price test lower them for some shoppers?\n      yes: Revenue per unit falls while cost per unit holds.\n    spiked:\n      check: Did a price rise take effect?\n      yes: Revenue per unit rises from the price change date while cost per unit holds.\n\ndiagnose_order: [cost-data, discounts, product-mix, landed-cost, pricing]\n\nrelated: [contribution-margin, discount-rate, net-revenue, aov, refund-rate]\n\nprose:\n  why_it_matters: >-\n    Gross margin decides how much of each dollar of revenue is left for marketing, shipping and\n    everything else. A store at 58% margin that slips to 55% has lost about 5% of what it has to\n    spend with revenue unchanged; at Northwind that is about $40,000 a week.\n  pitfalls:\n    - Cost of goods should be the landed cost per unit, the purchase price plus inbound freight and duties. Supplier price alone overstates margin by several points for imported goods.\n    - Products without a recorded cost count as free and pull margin up. New products are the usual culprit.\n    - This spec matches each order's revenue to its own cost and leaves refunds out, because a refund event carries no cost. Read refund rate beside it.\n    - Shipping, packaging and payment fees aren't cost of goods. Including them mixes gross margin with contribution margin and breaks comparisons with industry figures.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"gross-margin","name":"Gross margin","aliases":["Gross margin percentage","Gross profit margin","Product margin"],"family":"revenue","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of order revenue left after the cost of the goods sold, for orders paid this week.","formula":"(Order revenue − cost of goods) ÷ order revenue, after discounts, before tax, shipping and refunds"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."},{"name":"cost_of_goods","description":"The landed cost of the order's items, purchase price plus inbound freight and duties."}]}],"numerator":{"label":"Order revenue","aggregate":"sum","event":"order_completed","property":"total"},"subtract":{"label":"Cost of goods","aggregate":"sum","event":"order_completed","property":"cost_of_goods"},"denominator":{"label":"Order revenue","aggregate":"sum","event":"order_completed","property":"total"},"noise":{"type":"process","min_denominator":50,"volume_unit":"orders a week","typical":0.55},"example":{"business":"store","level":0.532,"volume":13300,"trend":-0.02},"drivers":[{"id":"cost-data","label":"Cost data","dropped":{"check":"Did cost_of_goods change basis, for example adding freight or loading a new supplier price list?","yes":"Cost per unit jumps for many products on one date, with no new purchase order behind it."},"spiked":{"check":"Are products selling without a recorded cost, counting as free?","yes":"The share of orders with no cost_of_goods rises, usually on new products."}},{"id":"discounts","label":"Discounts and sales","metric":"discount-rate","feed":"shopping","dropped":{"check":"Did discounts rise, from a sale, a code or a stacked offer?","yes":"Discount rate rises by about as much as margin falls."},"spiked":{"check":"Did a sale end, so orders carry less discount?","yes":"Discount rate falls by about as much as margin rises."}},{"id":"product-mix","label":"Product mix","dropped":{"check":"Did low-margin products, such as bundles, clearance or a new hero product, take a larger share of sales?","yes":"Each product's own margin holds and only the mix moved."},"spiked":{"check":"Did high-margin products take a larger share of sales?","yes":"Each product's own margin holds and only the mix moved."}},{"id":"landed-cost","label":"Supplier, freight and duties","dropped":{"check":"Did supplier prices, freight or tariffs raise unit costs?","yes":"Cost per unit rises on the same products, often when a new purchase order is received."},"spiked":{"check":"Did a cheaper batch of stock start selling? Check it's not a cost data error first.","yes":"Cost per unit falls on the products from one purchase order."}},{"id":"pricing","label":"Prices","dropped":{"check":"Did list prices fall, or did a price test lower them for some shoppers?","yes":"Revenue per unit falls while cost per unit holds."},"spiked":{"check":"Did a price rise take effect?","yes":"Revenue per unit rises from the price change date while cost per unit holds."}}],"diagnose_order":["cost-data","discounts","product-mix","landed-cost","pricing"],"related":["contribution-margin","discount-rate","net-revenue","aov","refund-rate"],"prose":{"why_it_matters":"Gross margin decides how much of each dollar of revenue is left for marketing, shipping and everything else. A store at 58% margin that slips to 55% has lost about 5% of what it has to spend with revenue unchanged; at Northwind that is about $40,000 a week.","pitfalls":["Cost of goods should be the landed cost per unit, the purchase price plus inbound freight and duties. Supplier price alone overstates margin by several points for imported goods.","Products without a recorded cost count as free and pull margin up. New products are the usual culprit.","This spec matches each order's revenue to its own cost and leaves refunds out, because a refund event carries no cost. Read refund rate beside it.","Shipping, packaging and payment fees aren't cost of goods. Including them mixes gross margin with contribution margin and breaks comparisons with industry figures."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "gross-revenue-retention": { yaml: "id: gross-revenue-retention\nname: Gross revenue retention\naliases:\n  - GRR\n  - Gross dollar retention\n  - GDR\n  - Gross retention\n  - Gross revenue retention rate\nfamily: subscription\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of what customers paid 12 months ago that they still pay today, counting churn and downgrades but no expansion.\n  formula: Sum over customers paying 52 weeks earlier of the lesser of their MRR now and their MRR then ÷ their MRR then\n\nevents:\n  - name: subscription_updated\n    description: Any change to a subscription's plan, quantity, discount or status, with its new monthly amount.\n    also_called: [customer.subscription.updated, Subscription Updated, subscription_changed]\n    properties:\n      - name: subscription_id\n        description: The billing system's subscription id.\n      - name: mrr\n        description: The subscription's monthly amount after the change, after discounts, before tax.\n      - name: status\n        description: active, trialing, past_due or canceled.\n\nnumerator:\n  label: MRR kept from customers paying a year ago, capped at what each paid then\n  aggregate: sum\n  event: subscription_updated\n  property: mrr\n\nqueries:\n  hogql: |-\n    -- Gross revenue retention, trailing 12 months, for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: MRR at the week's end from customers who were paying at the end of the same week 52 weeks earlier, each capped at what it paid then, ÷ their MRR then. A customer is the person on the subscription; customers who started since are left out, and those who left count as zero.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(r.kept_total, 0) AS numerator,\n      coalesce(r.start_total, 0) AS denominator,\n      if(denominator = 0, NULL, numerator / denominator) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, sum(least(end_mrr, start_mrr)) AS kept_total, sum(start_mrr) AS start_total\n      FROM (\n        SELECT\n          week,\n          account,\n          coalesce(sumIf(sub_mrr, weeks_back = 52), 0) AS start_mrr,\n          coalesce(sumIf(sub_mrr, weeks_back = 0), 0) AS end_mrr\n        FROM (\n          SELECT\n            week,\n            weeks_back,\n            tupleElement(latest, 1) AS account,\n            if(tupleElement(latest, 3) IN ('active', 'past_due'), tupleElement(latest, 2), 0) AS sub_mrr\n          FROM (\n            SELECT s.week AS week, s.weeks_back AS weeks_back, u.subscription_id AS subscription_id, argMax(tuple(u.person, u.mrr, u.status), u.ts) AS latest\n            FROM (\n              SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week, arrayJoin([0, 52]) AS weeks_back\n            ) AS s\n            CROSS JOIN (\n              SELECT\n                toString(properties.subscription_id) AS subscription_id,\n                person_id AS person,\n                toTimeZone(timestamp, 'UTC') AS ts,\n                toFloat(properties.mrr) AS mrr,\n                toString(properties.status) AS status\n              FROM events\n              WHERE event = 'subscription_updated'\n                AND properties.subscription_id IS NOT NULL\n                AND toMonday(toTimeZone(timestamp, 'UTC')) < toMonday(toTimeZone(now(), 'UTC'))\n            ) AS u\n            WHERE toMonday(u.ts) <= s.week - toIntervalWeek(s.weeks_back)\n            GROUP BY week, weeks_back, subscription_id\n          )\n        )\n        GROUP BY week, account\n      )\n      WHERE start_mrr > 0\n      GROUP BY week\n    ) AS r ON r.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Gross revenue retention, trailing 12 months, for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: MRR at the week's end from customers who were paying at the end of the same week 52 weeks earlier, each capped at what it paid then, ÷ their MRR then. A customer is the user_id on the subscription; customers who started since are left out, and those who left count as zero.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    snaps AS (\n      SELECT w.week, b.weeks_back, w.week + 7 * (1 - b.weeks_back) AS cutoff\n      FROM weeks AS w\n      CROSS JOIN (VALUES (0), (52)) AS b(weeks_back)\n    ),\n    updates AS (\n      SELECT\n        properties->>'subscription_id' AS subscription_id,\n        user_id AS customer,\n        occurred_at AT TIME ZONE 'UTC' AS ts,\n        CASE WHEN properties->>'mrr' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr')::numeric END AS mrr,\n        properties->>'status' AS status\n      FROM events\n      WHERE event_name = 'subscription_updated'\n        AND properties->>'subscription_id' IS NOT NULL\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n    ),\n    latest AS (\n      SELECT DISTINCT ON (s.week, s.weeks_back, u.subscription_id) s.week, s.weeks_back, u.customer, u.mrr, u.status\n      FROM snaps AS s\n      JOIN updates AS u ON u.ts < s.cutoff\n      ORDER BY s.week, s.weeks_back, u.subscription_id, u.ts DESC\n    ),\n    customers AS (\n      SELECT\n        week,\n        customer,\n        coalesce(sum(mrr) FILTER (WHERE weeks_back = 52), 0) AS start_mrr,\n        coalesce(sum(mrr) FILTER (WHERE weeks_back = 0), 0) AS end_mrr\n      FROM latest\n      WHERE status IN ('active', 'past_due')\n      GROUP BY week, customer\n    ),\n    weekly AS (\n      SELECT week, sum(least(end_mrr, start_mrr)) AS kept_mrr, sum(start_mrr) AS start_mrr\n      FROM customers\n      WHERE start_mrr > 0\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      coalesce(r.kept_mrr, 0) AS numerator,\n      coalesce(r.start_mrr, 0) AS denominator,\n      r.kept_mrr / nullif(r.start_mrr, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS r ON r.week = w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Gross revenue retention, trailing 12 months, for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: MRR at the week's end from customers who were paying at the end of the same week 52 weeks earlier, each capped at what it paid then, ÷ their MRR then. A customer is the user_id on the subscription; customers who started since are left out, and those who left count as zero.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    snaps AS (\n      SELECT w.week, weeks_back, TIMESTAMP(DATE_ADD(w.week, INTERVAL (1 - weeks_back) WEEK)) AS cutoff\n      FROM weeks AS w\n      CROSS JOIN UNNEST([0, 52]) AS weeks_back\n    ),\n    updates AS (\n      SELECT\n        JSON_VALUE(properties, '$.subscription_id') AS subscription_id,\n        user_id AS customer,\n        occurred_at,\n        SAFE_CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64) AS mrr,\n        JSON_VALUE(properties, '$.status') AS status\n      FROM events\n      WHERE event_name = 'subscription_updated'\n        AND JSON_VALUE(properties, '$.subscription_id') IS NOT NULL\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    ),\n    latest AS (\n      SELECT s.week, s.weeks_back, u.customer, u.mrr, u.status\n      FROM snaps AS s\n      CROSS JOIN updates AS u\n      WHERE u.occurred_at < s.cutoff\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY s.week, s.weeks_back, u.subscription_id ORDER BY u.occurred_at DESC) = 1\n    ),\n    customers AS (\n      SELECT\n        week,\n        customer,\n        COALESCE(SUM(IF(weeks_back = 52, mrr, NULL)), 0) AS start_mrr,\n        COALESCE(SUM(IF(weeks_back = 0, mrr, NULL)), 0) AS end_mrr\n      FROM latest\n      WHERE status IN ('active', 'past_due')\n      GROUP BY week, customer\n    ),\n    weekly AS (\n      SELECT week, SUM(LEAST(end_mrr, start_mrr)) AS kept_mrr, SUM(start_mrr) AS start_mrr\n      FROM customers\n      WHERE start_mrr > 0\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      COALESCE(r.kept_mrr, 0) AS numerator,\n      COALESCE(r.start_mrr, 0) AS denominator,\n      SAFE_DIVIDE(r.kept_mrr, r.start_mrr) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS r ON r.week = w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Gross revenue retention, trailing 12 months, for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: MRR at the week's end from customers who were paying at the end of the same week 52 weeks earlier, each capped at what it paid then, ÷ their MRR then. A customer is the user_id on the subscription; customers who started since are left out, and those who left count as zero.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    snaps AS (\n      SELECT w.week, b.weeks_back, DATEADD(week, 1 - b.weeks_back, w.week) AS cutoff\n      FROM weeks AS w\n      CROSS JOIN (VALUES (0), (52)) AS b (weeks_back)\n    ),\n    updates AS (\n      SELECT\n        properties:\"subscription_id\"::string AS subscription_id,\n        user_id AS customer,\n        occurred_at,\n        TRY_TO_DOUBLE(properties:\"mrr\"::string) AS mrr,\n        properties:\"status\"::string AS status\n      FROM events\n      WHERE event_name = 'subscription_updated'\n        AND properties:\"subscription_id\"::string IS NOT NULL\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n    ),\n    latest AS (\n      SELECT s.week, s.weeks_back, u.customer, u.mrr, u.status\n      FROM snaps AS s\n      JOIN updates AS u ON u.occurred_at < s.cutoff\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY s.week, s.weeks_back, u.subscription_id ORDER BY u.occurred_at DESC) = 1\n    ),\n    customers AS (\n      SELECT\n        week,\n        customer,\n        COALESCE(SUM(IFF(weeks_back = 52, mrr, NULL)), 0) AS start_mrr,\n        COALESCE(SUM(IFF(weeks_back = 0, mrr, NULL)), 0) AS end_mrr\n      FROM latest\n      WHERE status IN ('active', 'past_due')\n      GROUP BY week, customer\n    ),\n    weekly AS (\n      SELECT week, SUM(LEAST(end_mrr, start_mrr)) AS kept_mrr, SUM(start_mrr) AS start_mrr\n      FROM customers\n      WHERE start_mrr > 0\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      COALESCE(r.kept_mrr, 0) AS numerator,\n      COALESCE(r.start_mrr, 0) AS denominator,\n      r.kept_mrr / NULLIF(r.start_mrr, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS r ON r.week = w.week\n    ORDER BY w.week;\n\nnoise:\n  type: process\n  min_denominator: 50\n  volume_unit: customers in the starting cohort\n  typical: 0.88\n\nexample:\n  business: saas\n  level: 0.88\n  volume: 1570\n  trend: 0\n\ndrivers:\n  - id: customer-ids\n    label: Customer ids\n    dropped:\n      check: Did a customer-id migration or a billing change split existing customers, so their MRR now looks new?\n      yes: Customers in the starting cohort show zero MRR while new customers with the same names or domains appear.\n    spiked:\n      check: Did accounts merge, so customers who left now look retained?\n      yes: Cohort customers who canceled show MRR again from subscriptions that belong to someone else.\n  - id: cohort-window\n    label: Which customers are in the window\n    dropped:\n      check: Did a cohort with unusually high churn enter the starting window?\n      yes: The move starts the week a large or poorly fitted signup month from 12 months ago crosses the window edge.\n    spiked:\n      check: Did a cohort with unusually high churn leave the starting window?\n      yes: The move starts the week that cohort crosses the window edge, with no change in this week's behaviour.\n  - id: involuntary\n    label: Failed payments\n    feed: stripe\n    dropped:\n      check: Did more of last year's customers lapse for failed payments?\n      yes: A rising share of the cohort's lost MRR ended in past_due; Stripe shows declines or an incident.\n    spiked:\n      check: Did dunning or a card updater recover customers who used to lapse?\n      yes: Fewer cohort customers end in past_due and then canceled.\n  - id: logo-split\n    label: Many small losses or a few large ones\n    metric: logo-churn-rate\n    dropped:\n      check: Is the loss many small customers or a few large ones?\n      yes: Rising logo churn means many small losses; flat logo churn with falling GRR means a few large accounts left or shrank.\n    spiked:\n      check: Is the improvement broad, or one large account that stayed?\n      yes: Logo churn falls too when it is broad; otherwise one renewal explains it.\n  - id: churn\n    label: Churned MRR\n    metric: churned-mrr\n    dropped:\n      check: Did more of last year's customers cancel?\n      yes: Churned MRR from customers older than 12 months rises over the trailing quarter.\n    spiked:\n      check: Did cancellations among long-standing customers slow?\n      yes: Churned MRR from customers older than 12 months falls over the trailing quarter.\n  - id: contraction\n    label: Downgrades\n    breakdown: plan\n    dropped:\n      check: Are customers keeping the product but paying less, with fewer seats, cheaper plans or smaller commitments?\n      yes: Contraction among cohort customers rises while cancellations hold, often after their own budget cuts.\n    spiked:\n      check: Did downgrades slow, or was a downgrade path removed?\n      yes: Contraction among cohort customers falls; if a cheaper plan was removed, watch churn.\n\ndiagnose_order: [customer-ids, cohort-window, involuntary, logo-split, churn, contraction]\n\nrelated: [net-revenue-retention, churned-mrr, logo-churn-rate, mrr, customer-lifetime-value]\n\nprose:\n  why_it_matters: >-\n    Gross revenue retention is the floor under net retention: what last year's customers still\n    pay if no one expands. It cannot pass 100%, which makes it the cleanest read of churn and\n    downgrades, and the number investors use to judge product fit. A SaaS at 88% has to replace\n    12% of last year's revenue before any growth counts.\n  pitfalls:\n    - Cap each customer at its starting MRR before summing. Letting one customer's expansion offset another's downgrade is NRR, not GRR.\n    - Measure per customer, not per subscription, or a plan change done as cancel and resubscribe counts as churn.\n    - A monthly GRR and a 12-month fixed-cohort GRR are different numbers. 99% a month compounds to 89% a year only if churn is the same at every customer age, which it rarely is.\n    - A customer who leaves and returns within the year counts at what it pays now, capped. Don't count its return as new business in this cohort.\n    - Failed-payment lapses pull GRR down as much as cancellations. Split them, because the fix is in billing, not the product.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"gross-revenue-retention","name":"Gross revenue retention","aliases":["GRR","Gross dollar retention","GDR","Gross retention","Gross revenue retention rate"],"family":"subscription","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of what customers paid 12 months ago that they still pay today, counting churn and downgrades but no expansion.","formula":"Sum over customers paying 52 weeks earlier of the lesser of their MRR now and their MRR then ÷ their MRR then"},"events":[{"name":"subscription_updated","description":"Any change to a subscription's plan, quantity, discount or status, with its new monthly amount.","also_called":["customer.subscription.updated","Subscription Updated","subscription_changed"],"properties":[{"name":"subscription_id","description":"The billing system's subscription id."},{"name":"mrr","description":"The subscription's monthly amount after the change, after discounts, before tax."},{"name":"status","description":"active, trialing, past_due or canceled."}]}],"numerator":{"label":"MRR kept from customers paying a year ago, capped at what each paid then","aggregate":"sum","event":"subscription_updated","property":"mrr"},"queries":{"hogql":"-- Gross revenue retention, trailing 12 months, for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: MRR at the week's end from customers who were paying at the end of the same week 52 weeks earlier, each capped at what it paid then, ÷ their MRR then. A customer is the person on the subscription; customers who started since are left out, and those who left count as zero.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(r.kept_total, 0) AS numerator,\n  coalesce(r.start_total, 0) AS denominator,\n  if(denominator = 0, NULL, numerator / denominator) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, sum(least(end_mrr, start_mrr)) AS kept_total, sum(start_mrr) AS start_total\n  FROM (\n    SELECT\n      week,\n      account,\n      coalesce(sumIf(sub_mrr, weeks_back = 52), 0) AS start_mrr,\n      coalesce(sumIf(sub_mrr, weeks_back = 0), 0) AS end_mrr\n    FROM (\n      SELECT\n        week,\n        weeks_back,\n        tupleElement(latest, 1) AS account,\n        if(tupleElement(latest, 3) IN ('active', 'past_due'), tupleElement(latest, 2), 0) AS sub_mrr\n      FROM (\n        SELECT s.week AS week, s.weeks_back AS weeks_back, u.subscription_id AS subscription_id, argMax(tuple(u.person, u.mrr, u.status), u.ts) AS latest\n        FROM (\n          SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week, arrayJoin([0, 52]) AS weeks_back\n        ) AS s\n        CROSS JOIN (\n          SELECT\n            toString(properties.subscription_id) AS subscription_id,\n            person_id AS person,\n            toTimeZone(timestamp, 'UTC') AS ts,\n            toFloat(properties.mrr) AS mrr,\n            toString(properties.status) AS status\n          FROM events\n          WHERE event = 'subscription_updated'\n            AND properties.subscription_id IS NOT NULL\n            AND toMonday(toTimeZone(timestamp, 'UTC')) < toMonday(toTimeZone(now(), 'UTC'))\n        ) AS u\n        WHERE toMonday(u.ts) <= s.week - toIntervalWeek(s.weeks_back)\n        GROUP BY week, weeks_back, subscription_id\n      )\n    )\n    GROUP BY week, account\n  )\n  WHERE start_mrr > 0\n  GROUP BY week\n) AS r ON r.week = w.week\nORDER BY week","postgres":"-- Gross revenue retention, trailing 12 months, for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: MRR at the week's end from customers who were paying at the end of the same week 52 weeks earlier, each capped at what it paid then, ÷ their MRR then. A customer is the user_id on the subscription; customers who started since are left out, and those who left count as zero.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nsnaps AS (\n  SELECT w.week, b.weeks_back, w.week + 7 * (1 - b.weeks_back) AS cutoff\n  FROM weeks AS w\n  CROSS JOIN (VALUES (0), (52)) AS b(weeks_back)\n),\nupdates AS (\n  SELECT\n    properties->>'subscription_id' AS subscription_id,\n    user_id AS customer,\n    occurred_at AT TIME ZONE 'UTC' AS ts,\n    CASE WHEN properties->>'mrr' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr')::numeric END AS mrr,\n    properties->>'status' AS status\n  FROM events\n  WHERE event_name = 'subscription_updated'\n    AND properties->>'subscription_id' IS NOT NULL\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n),\nlatest AS (\n  SELECT DISTINCT ON (s.week, s.weeks_back, u.subscription_id) s.week, s.weeks_back, u.customer, u.mrr, u.status\n  FROM snaps AS s\n  JOIN updates AS u ON u.ts < s.cutoff\n  ORDER BY s.week, s.weeks_back, u.subscription_id, u.ts DESC\n),\ncustomers AS (\n  SELECT\n    week,\n    customer,\n    coalesce(sum(mrr) FILTER (WHERE weeks_back = 52), 0) AS start_mrr,\n    coalesce(sum(mrr) FILTER (WHERE weeks_back = 0), 0) AS end_mrr\n  FROM latest\n  WHERE status IN ('active', 'past_due')\n  GROUP BY week, customer\n),\nweekly AS (\n  SELECT week, sum(least(end_mrr, start_mrr)) AS kept_mrr, sum(start_mrr) AS start_mrr\n  FROM customers\n  WHERE start_mrr > 0\n  GROUP BY week\n)\nSELECT\n  w.week,\n  coalesce(r.kept_mrr, 0) AS numerator,\n  coalesce(r.start_mrr, 0) AS denominator,\n  r.kept_mrr / nullif(r.start_mrr, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS r ON r.week = w.week\nORDER BY w.week;","bigquery":"-- Gross revenue retention, trailing 12 months, for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: MRR at the week's end from customers who were paying at the end of the same week 52 weeks earlier, each capped at what it paid then, ÷ their MRR then. A customer is the user_id on the subscription; customers who started since are left out, and those who left count as zero.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nsnaps AS (\n  SELECT w.week, weeks_back, TIMESTAMP(DATE_ADD(w.week, INTERVAL (1 - weeks_back) WEEK)) AS cutoff\n  FROM weeks AS w\n  CROSS JOIN UNNEST([0, 52]) AS weeks_back\n),\nupdates AS (\n  SELECT\n    JSON_VALUE(properties, '$.subscription_id') AS subscription_id,\n    user_id AS customer,\n    occurred_at,\n    SAFE_CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64) AS mrr,\n    JSON_VALUE(properties, '$.status') AS status\n  FROM events\n  WHERE event_name = 'subscription_updated'\n    AND JSON_VALUE(properties, '$.subscription_id') IS NOT NULL\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n),\nlatest AS (\n  SELECT s.week, s.weeks_back, u.customer, u.mrr, u.status\n  FROM snaps AS s\n  CROSS JOIN updates AS u\n  WHERE u.occurred_at < s.cutoff\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY s.week, s.weeks_back, u.subscription_id ORDER BY u.occurred_at DESC) = 1\n),\ncustomers AS (\n  SELECT\n    week,\n    customer,\n    COALESCE(SUM(IF(weeks_back = 52, mrr, NULL)), 0) AS start_mrr,\n    COALESCE(SUM(IF(weeks_back = 0, mrr, NULL)), 0) AS end_mrr\n  FROM latest\n  WHERE status IN ('active', 'past_due')\n  GROUP BY week, customer\n),\nweekly AS (\n  SELECT week, SUM(LEAST(end_mrr, start_mrr)) AS kept_mrr, SUM(start_mrr) AS start_mrr\n  FROM customers\n  WHERE start_mrr > 0\n  GROUP BY week\n)\nSELECT\n  w.week,\n  COALESCE(r.kept_mrr, 0) AS numerator,\n  COALESCE(r.start_mrr, 0) AS denominator,\n  SAFE_DIVIDE(r.kept_mrr, r.start_mrr) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS r ON r.week = w.week\nORDER BY w.week;","snowflake":"-- Gross revenue retention, trailing 12 months, for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: MRR at the week's end from customers who were paying at the end of the same week 52 weeks earlier, each capped at what it paid then, ÷ their MRR then. A customer is the user_id on the subscription; customers who started since are left out, and those who left count as zero.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nsnaps AS (\n  SELECT w.week, b.weeks_back, DATEADD(week, 1 - b.weeks_back, w.week) AS cutoff\n  FROM weeks AS w\n  CROSS JOIN (VALUES (0), (52)) AS b (weeks_back)\n),\nupdates AS (\n  SELECT\n    properties:\"subscription_id\"::string AS subscription_id,\n    user_id AS customer,\n    occurred_at,\n    TRY_TO_DOUBLE(properties:\"mrr\"::string) AS mrr,\n    properties:\"status\"::string AS status\n  FROM events\n  WHERE event_name = 'subscription_updated'\n    AND properties:\"subscription_id\"::string IS NOT NULL\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n),\nlatest AS (\n  SELECT s.week, s.weeks_back, u.customer, u.mrr, u.status\n  FROM snaps AS s\n  JOIN updates AS u ON u.occurred_at < s.cutoff\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY s.week, s.weeks_back, u.subscription_id ORDER BY u.occurred_at DESC) = 1\n),\ncustomers AS (\n  SELECT\n    week,\n    customer,\n    COALESCE(SUM(IFF(weeks_back = 52, mrr, NULL)), 0) AS start_mrr,\n    COALESCE(SUM(IFF(weeks_back = 0, mrr, NULL)), 0) AS end_mrr\n  FROM latest\n  WHERE status IN ('active', 'past_due')\n  GROUP BY week, customer\n),\nweekly AS (\n  SELECT week, SUM(LEAST(end_mrr, start_mrr)) AS kept_mrr, SUM(start_mrr) AS start_mrr\n  FROM customers\n  WHERE start_mrr > 0\n  GROUP BY week\n)\nSELECT\n  w.week,\n  COALESCE(r.kept_mrr, 0) AS numerator,\n  COALESCE(r.start_mrr, 0) AS denominator,\n  r.kept_mrr / NULLIF(r.start_mrr, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS r ON r.week = w.week\nORDER BY w.week;"},"noise":{"type":"process","min_denominator":50,"volume_unit":"customers in the starting cohort","typical":0.88},"example":{"business":"saas","level":0.88,"volume":1570,"trend":0},"drivers":[{"id":"customer-ids","label":"Customer ids","dropped":{"check":"Did a customer-id migration or a billing change split existing customers, so their MRR now looks new?","yes":"Customers in the starting cohort show zero MRR while new customers with the same names or domains appear."},"spiked":{"check":"Did accounts merge, so customers who left now look retained?","yes":"Cohort customers who canceled show MRR again from subscriptions that belong to someone else."}},{"id":"cohort-window","label":"Which customers are in the window","dropped":{"check":"Did a cohort with unusually high churn enter the starting window?","yes":"The move starts the week a large or poorly fitted signup month from 12 months ago crosses the window edge."},"spiked":{"check":"Did a cohort with unusually high churn leave the starting window?","yes":"The move starts the week that cohort crosses the window edge, with no change in this week's behaviour."}},{"id":"involuntary","label":"Failed payments","feed":"stripe","dropped":{"check":"Did more of last year's customers lapse for failed payments?","yes":"A rising share of the cohort's lost MRR ended in past_due; Stripe shows declines or an incident."},"spiked":{"check":"Did dunning or a card updater recover customers who used to lapse?","yes":"Fewer cohort customers end in past_due and then canceled."}},{"id":"logo-split","label":"Many small losses or a few large ones","metric":"logo-churn-rate","dropped":{"check":"Is the loss many small customers or a few large ones?","yes":"Rising logo churn means many small losses; flat logo churn with falling GRR means a few large accounts left or shrank."},"spiked":{"check":"Is the improvement broad, or one large account that stayed?","yes":"Logo churn falls too when it is broad; otherwise one renewal explains it."}},{"id":"churn","label":"Churned MRR","metric":"churned-mrr","dropped":{"check":"Did more of last year's customers cancel?","yes":"Churned MRR from customers older than 12 months rises over the trailing quarter."},"spiked":{"check":"Did cancellations among long-standing customers slow?","yes":"Churned MRR from customers older than 12 months falls over the trailing quarter."}},{"id":"contraction","label":"Downgrades","breakdown":"plan","dropped":{"check":"Are customers keeping the product but paying less, with fewer seats, cheaper plans or smaller commitments?","yes":"Contraction among cohort customers rises while cancellations hold, often after their own budget cuts."},"spiked":{"check":"Did downgrades slow, or was a downgrade path removed?","yes":"Contraction among cohort customers falls; if a cheaper plan was removed, watch churn."}}],"diagnose_order":["customer-ids","cohort-window","involuntary","logo-split","churn","contraction"],"related":["net-revenue-retention","churned-mrr","logo-churn-rate","mrr","customer-lifetime-value"],"prose":{"why_it_matters":"Gross revenue retention is the floor under net retention: what last year's customers still pay if no one expands. It cannot pass 100%, which makes it the cleanest read of churn and downgrades, and the number investors use to judge product fit. A SaaS at 88% has to replace 12% of last year's revenue before any growth counts.","pitfalls":["Cap each customer at its starting MRR before summing. Letting one customer's expansion offset another's downgrade is NRR, not GRR.","Measure per customer, not per subscription, or a plan change done as cancel and resubscribe counts as churn.","A monthly GRR and a 12-month fixed-cohort GRR are different numbers. 99% a month compounds to 89% a year only if churn is the same at every customer age, which it rarely is.","A customer who leaves and returns within the year counts at what it pays now, capped. Don't count its return as new business in this cohort.","Failed-payment lapses pull GRR down as much as cancellations. Split them, because the fix is in billing, not the product."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "gross-sales": { yaml: "id: gross-sales\nname: Gross sales\naliases:\n  - Gross revenue\n  - Gross merchandise value\n  - GMV\n  - Sales before discounts\nfamily: revenue\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: The value of products sold this week at their selling price, before discounts, refunds, tax and shipping.\n  formula: Sum of order subtotals before discounts, excluding tax and shipping\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: subtotal\n        description: Price × quantity of every item, before discounts, tax and shipping.\n      - name: discount\n        description: The total discount on the order, read in discount rate.\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n\nnumerator:\n  label: Gross sales\n  aggregate: sum\n  event: order_completed\n  property: subtotal\n\nnoise:\n  type: compound\n  cv: 0.9\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 300000\n\nexample:\n  business: store\n  level: 1450000\n  volume: 13300\n  trend: 0.2\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did subtotal stop being sent, or change meaning, for example to after discounts?\n      yes: Subtotal ÷ order total jumps or falls on one release day with no change in offers.\n    spiked:\n      check: Did subtotal start including tax or shipping, or did one currency start arriving unconverted?\n      yes: Order subtotals jump for one country or channel from one day.\n  - id: calendar\n    label: Shopping calendar\n    feed: shopping\n    dropped:\n      check: Was last week a sale, holiday or gifting week?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this a sale, holiday or gifting week?\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: orders\n    label: Orders\n    metric: orders\n    dropped:\n      check: Did the number of orders fall, or only what each order is worth before discounts?\n      yes: Orders fall by about as much as gross sales.\n    spiked:\n      check: Is the rise in the number of orders rather than their size?\n      yes: Orders rise by about as much as gross sales.\n  - id: discounts\n    label: Promotions\n    metric: discount-rate\n    dropped:\n      check: Did a promotion end that had been pulling demand forward?\n      yes: Discount rate falls with gross sales while net revenue falls less.\n    spiked:\n      check: Is a promotion lifting gross sales while discounts eat the gain? Check net revenue before celebrating.\n      yes: Discount rate rises with gross sales, and net revenue grows far less.\n  - id: basket-size\n    label: Items per order\n    metric: units-per-order\n    dropped:\n      check: Did shoppers buy fewer items per order, after a bundle ended or a free-shipping threshold fell?\n      yes: Units per order fall while orders hold.\n    spiked:\n      check: Did a bundle, multi-buy offer or higher free-shipping threshold add items to orders?\n      yes: Units per order rise from the day the offer started.\n  - id: price-and-mix\n    label: Prices and product mix\n    dropped:\n      check: Did prices fall, or did sales shift toward cheaper products?\n      yes: Units hold while the average price per unit falls, often on a few products.\n    spiked:\n      check: Did prices rise, a premium product launch, or a few very large orders land?\n      yes: The average price per unit rises, or the largest orders explain most of the jump.\n\ndiagnose_order: [tracking, calendar, orders, discounts, basket-size, price-and-mix]\n\nrelated: [net-revenue, discount-rate, refund-rate, aov, units-per-order]\n\nprose:\n  why_it_matters: >-\n    Gross sales measure demand at full price, before the store decides what to give back.\n    Read beside net revenue, the gap is the cost of promotions and returns; at Northwind, $1.45M\n    of gross sales becomes $1.33M after discounts and about $1.29M after refunds. A promotion\n    that grows gross sales 20% while net revenue grows 5% bought most of its growth.\n  pitfalls:\n    - Shopify's gross sales is price × quantity before discounts, but some platforms' gross revenue includes tax and shipping. Say which one you report; this spec excludes both.\n    - Marking a price down on the product lowers gross sales itself, while a code adds a discount. Two sales of the same depth look different here, so know which kind each one was.\n    - Gross sales rise with every promotion that works on volume. Never report them without net revenue beside them.\n    - A few wholesale or bulk orders can move a small store's week by 10% or more. Check the order count and the largest orders before the total.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"gross-sales","name":"Gross sales","aliases":["Gross revenue","Gross merchandise value","GMV","Sales before discounts"],"family":"revenue","kind":"currency","polarity":"up-is-good","definition":{"one_line":"The value of products sold this week at their selling price, before discounts, refunds, tax and shipping.","formula":"Sum of order subtotals before discounts, excluding tax and shipping"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"subtotal","description":"Price × quantity of every item, before discounts, tax and shipping."},{"name":"discount","description":"The total discount on the order, read in discount rate."},{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."}]}],"numerator":{"label":"Gross sales","aggregate":"sum","event":"order_completed","property":"subtotal"},"noise":{"type":"compound","cv":0.9,"min_denominator":50,"volume_unit":"orders a week","typical":300000},"example":{"business":"store","level":1450000,"volume":13300,"trend":0.2,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did subtotal stop being sent, or change meaning, for example to after discounts?","yes":"Subtotal ÷ order total jumps or falls on one release day with no change in offers."},"spiked":{"check":"Did subtotal start including tax or shipping, or did one currency start arriving unconverted?","yes":"Order subtotals jump for one country or channel from one day."}},{"id":"calendar","label":"Shopping calendar","feed":"shopping","dropped":{"check":"Was last week a sale, holiday or gifting week?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this a sale, holiday or gifting week?","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"orders","label":"Orders","metric":"orders","dropped":{"check":"Did the number of orders fall, or only what each order is worth before discounts?","yes":"Orders fall by about as much as gross sales."},"spiked":{"check":"Is the rise in the number of orders rather than their size?","yes":"Orders rise by about as much as gross sales."}},{"id":"discounts","label":"Promotions","metric":"discount-rate","dropped":{"check":"Did a promotion end that had been pulling demand forward?","yes":"Discount rate falls with gross sales while net revenue falls less."},"spiked":{"check":"Is a promotion lifting gross sales while discounts eat the gain? Check net revenue before celebrating.","yes":"Discount rate rises with gross sales, and net revenue grows far less."}},{"id":"basket-size","label":"Items per order","metric":"units-per-order","dropped":{"check":"Did shoppers buy fewer items per order, after a bundle ended or a free-shipping threshold fell?","yes":"Units per order fall while orders hold."},"spiked":{"check":"Did a bundle, multi-buy offer or higher free-shipping threshold add items to orders?","yes":"Units per order rise from the day the offer started."}},{"id":"price-and-mix","label":"Prices and product mix","dropped":{"check":"Did prices fall, or did sales shift toward cheaper products?","yes":"Units hold while the average price per unit falls, often on a few products."},"spiked":{"check":"Did prices rise, a premium product launch, or a few very large orders land?","yes":"The average price per unit rises, or the largest orders explain most of the jump."}}],"diagnose_order":["tracking","calendar","orders","discounts","basket-size","price-and-mix"],"related":["net-revenue","discount-rate","refund-rate","aov","units-per-order"],"prose":{"why_it_matters":"Gross sales measure demand at full price, before the store decides what to give back. Read beside net revenue, the gap is the cost of promotions and returns; at Northwind, $1.45M of gross sales becomes $1.33M after discounts and about $1.29M after refunds. A promotion that grows gross sales 20% while net revenue grows 5% bought most of its growth.","pitfalls":["Shopify's gross sales is price × quantity before discounts, but some platforms' gross revenue includes tax and shipping. Say which one you report; this spec excludes both.","Marking a price down on the product lowers gross sales itself, while a code adds a discount. Two sales of the same depth look different here, so know which kind each one was.","Gross sales rise with every promotion that works on volume. Never report them without net revenue beside them.","A few wholesale or bulk orders can move a small store's week by 10% or more. Check the order count and the largest orders before the total."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "invite-rate": { yaml: "id: invite-rate\nname: Invite rate\naliases:\n  - Teammate invite rate\n  - Invitation rate\n  - Viral invite rate\nfamily: activation\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of people who signed up in a week who invited at least one other person within 7 days of signing up.\n  formula: Signups who sent an invite within 7 days ÷ signups, by signup week\n\nevents:\n  - name: signed_up\n    description: An account created, sent by the server when the account exists, not when the form is submitted.\n    also_called: [sign_up, Signed Up, user_signed_up, account_created]\n    properties:\n      - name: method\n        description: How the account was created, such as email, google, sso or invite.\n      - name: plan\n        description: The plan chosen at signup, if any.\n  - name: invite_sent\n    description: An invitation to the product sent to another person, one event per invitation.\n    also_called: [Invite Sent, Invitation Sent, user_invited]\n    properties: []\n\nnumerator:\n  label: Signups who invited someone within 7 days\n  aggregate: unique_users\n  event: invite_sent\ndenominator:\n  label: People who signed up\n  aggregate: unique_users\n  event: signed_up\n\nqueries:\n  hogql: |-\n    -- Invite rate: of people whose first signup fell in each week, the share who sent at least one invite within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(c.converted_people, 0) AS numerator,\n      coalesce(c.people, 0) AS denominator,\n      if(denominator = 0, NULL, numerator / denominator) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(2, 28))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, countIf(converted) AS converted_people, count() AS people\n      FROM (\n        SELECT\n          toMonday(s.start_at) AS week,\n          s.person_id AS person_id,\n          countIf(x.ts >= s.start_at AND x.ts < s.start_at + toIntervalDay(7)) > 0 AS converted\n        FROM (\n          SELECT person_id, min(toTimeZone(timestamp, 'UTC')) AS start_at\n          FROM events\n          WHERE event = 'signed_up'\n            AND person_id IS NOT NULL\n          GROUP BY person_id\n        ) AS s\n        LEFT JOIN (\n          SELECT person_id, toTimeZone(timestamp, 'UTC') AS ts\n          FROM events\n          WHERE event = 'invite_sent'\n            AND timestamp >= now() - toIntervalWeek(29)\n        ) AS x ON x.person_id = s.person_id\n        WHERE toMonday(s.start_at) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(27) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(2)\n        GROUP BY week, person_id\n      )\n      GROUP BY week\n    ) AS c ON c.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Invite rate: of people whose first signup fell in each week, the share who sent at least one invite within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '27 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '2 weeks',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    starts AS (\n      SELECT user_id, min(occurred_at AT TIME ZONE 'UTC') AS start_at\n      FROM events\n      WHERE event_name = 'signed_up'\n        AND user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    cohort AS (\n      SELECT\n        date_trunc('week', s.start_at)::date AS week,\n        s.user_id,\n        count(x.occurred_at) > 0 AS converted\n      FROM starts AS s\n      LEFT JOIN events AS x\n        ON x.user_id = s.user_id\n       AND x.event_name = 'invite_sent'\n       AND x.occurred_at AT TIME ZONE 'UTC' >= s.start_at\n       AND x.occurred_at AT TIME ZONE 'UTC' < s.start_at + interval '7 days'\n      WHERE s.start_at >= date_trunc('week', now() AT TIME ZONE 'UTC') - interval '27 weeks'\n        AND s.start_at < date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week'\n      GROUP BY 1, 2\n    )\n    SELECT\n      w.week,\n      count(c.user_id) FILTER (WHERE c.converted) AS numerator,\n      count(c.user_id) AS denominator,\n      (count(c.user_id) FILTER (WHERE c.converted))::numeric / nullif(count(c.user_id), 0) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Invite rate: of people whose first signup fell in each week, the share who sent at least one invite within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 27 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 2 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    starts AS (\n      SELECT user_id, MIN(occurred_at) AS start_at\n      FROM events\n      WHERE event_name = 'signed_up'\n        AND user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    cohort AS (\n      SELECT\n        DATE_TRUNC(DATE(s.start_at), ISOWEEK) AS week,\n        s.user_id,\n        COUNT(x.occurred_at) > 0 AS converted\n      FROM starts AS s\n      LEFT JOIN events AS x\n        ON x.user_id = s.user_id\n       AND x.event_name = 'invite_sent'\n       AND x.occurred_at >= s.start_at\n       AND x.occurred_at < TIMESTAMP_ADD(s.start_at, INTERVAL 7 DAY)\n      WHERE s.start_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 27 WEEK))\n        AND s.start_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK))\n      GROUP BY week, s.user_id\n    )\n    SELECT\n      w.week,\n      COUNTIF(c.converted) AS numerator,\n      COUNT(c.user_id) AS denominator,\n      SAFE_DIVIDE(COUNTIF(c.converted), COUNT(c.user_id)) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Invite rate: of people whose first signup fell in each week, the share who sent at least one invite within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 - ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    starts AS (\n      SELECT user_id, MIN(occurred_at) AS start_at\n      FROM events\n      WHERE event_name = 'signed_up'\n        AND user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    cohort AS (\n      SELECT\n        DATEADD(day, 1 - DAYOFWEEKISO(s.start_at), s.start_at::date) AS week,\n        s.user_id,\n        COUNT(x.occurred_at) > 0 AS converted\n      FROM starts AS s\n      LEFT JOIN events AS x\n        ON x.user_id = s.user_id\n       AND x.event_name = 'invite_sent'\n       AND x.occurred_at >= s.start_at\n       AND x.occurred_at < DATEADD(day, 7, s.start_at)\n      WHERE s.start_at >= DATEADD(week, -27, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND s.start_at < DATEADD(week, -1, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n      GROUP BY 1, 2\n    )\n    SELECT\n      w.week,\n      COUNT_IF(c.converted) AS numerator,\n      COUNT(c.user_id) AS denominator,\n      COUNT_IF(c.converted)::float / NULLIF(COUNT(c.user_id), 0) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: signups in the cohort\n  typical: 0.16\n\nexample:\n  business: saas\n  level: 0.16\n  volume: 2200\n  trend: 0.05\n\ndrivers:\n  - id: tracking\n    label: Invite event\n    dropped:\n      check: Did the invite event stop firing for one invite path, such as share links or bulk invites?\n      yes: Invites from one path fall to zero while accepted invites in the database hold.\n    spiked:\n      check: Is the event firing on opening the invite dialog, or once per address in a bulk upload counted as several people?\n      yes: Invites recorded far exceed invitations stored, or the rise comes from dialog opens with no addresses.\n  - id: invite-flow\n    label: Invite prompt\n    breakdown: $device_type\n    dropped:\n      check: Did the invite prompt move, get hidden, or break on one device?\n      yes: Invites fall from the day of a release, concentrated on one device or screen.\n    spiked:\n      check: Was an invite step added to onboarding, or made more prominent?\n      yes: Invites rise from the release date; check that invitees accept and use the product.\n  - id: plan-limits\n    label: Seats and pricing\n    breakdown: plan\n    dropped:\n      check: Did seat limits tighten or per-seat pricing start, making an invite cost money?\n      yes: Invites fall on the affected plans from the day of the change while others hold.\n    spiked:\n      check: Did a plan add free seats or remove a seat limit?\n      yes: Invites rise on that plan from the day of the change.\n  - id: signup-mix\n    label: Who signed up\n    metric: signups\n    breakdown: method\n    dropped:\n      check: Did more of the cohort arrive by invite? Invitees join an existing team and invite less.\n      yes: The share of signups by invite rose while the rate within each method held.\n    spiked:\n      check: Did more of the cohort arrive as team founders, from a campaign aimed at managers?\n      yes: The share of signups by email or SSO rose while the rate within each method held.\n  - id: activation\n    label: Reaching value first\n    metric: activation-rate\n    dropped:\n      check: Did fewer people reach the point where sharing the product makes sense?\n      yes: Activation fell for the same cohorts, and invites fell among non-activated users first.\n    spiked:\n      check: Did more people reach the point where sharing makes sense?\n      yes: Activation rose for the same cohorts by a similar share.\n\ndiagnose_order: [tracking, invite-flow, plan-limits, signup-mix, activation]\n\nrelated: [activation-rate, signups, onboarding-completion-rate, week-1-retention, feature-adoption-rate]\n\nprose:\n  why_it_matters: >-\n    In a team product the first invite is the moment a trial becomes something more than one person\n    relies on, and it drives the viral loop: every new user who invites others brings signups nobody\n    paid for. Team tools often count an early invite as part of activation. At Copperline about 16%\n    of new signups invite someone in their first week.\n  pitfalls:\n    - Count people who invite, not invites sent. An admin inviting forty colleagues from a spreadsheet is one inviter.\n    - Invited users sign up too, and they invite less. A week with many invite-driven signups lowers the rate with no change in the product.\n    - A forced invite step in onboarding raises the rate and fills the list with invites nobody accepts. Track the share of invites accepted alongside it.\n    - Only cohorts whose 7 days have closed are reported, so the latest point is the signups of two weeks ago.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"invite-rate","name":"Invite rate","aliases":["Teammate invite rate","Invitation rate","Viral invite rate"],"family":"activation","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of people who signed up in a week who invited at least one other person within 7 days of signing up.","formula":"Signups who sent an invite within 7 days ÷ signups, by signup week"},"events":[{"name":"signed_up","description":"An account created, sent by the server when the account exists, not when the form is submitted.","also_called":["sign_up","Signed Up","user_signed_up","account_created"],"properties":[{"name":"method","description":"How the account was created, such as email, google, sso or invite."},{"name":"plan","description":"The plan chosen at signup, if any."}]},{"name":"invite_sent","description":"An invitation to the product sent to another person, one event per invitation.","also_called":["Invite Sent","Invitation Sent","user_invited"],"properties":[]}],"numerator":{"label":"Signups who invited someone within 7 days","aggregate":"unique_users","event":"invite_sent"},"denominator":{"label":"People who signed up","aggregate":"unique_users","event":"signed_up"},"queries":{"hogql":"-- Invite rate: of people whose first signup fell in each week, the share who sent at least one invite within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(c.converted_people, 0) AS numerator,\n  coalesce(c.people, 0) AS denominator,\n  if(denominator = 0, NULL, numerator / denominator) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(2, 28))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, countIf(converted) AS converted_people, count() AS people\n  FROM (\n    SELECT\n      toMonday(s.start_at) AS week,\n      s.person_id AS person_id,\n      countIf(x.ts >= s.start_at AND x.ts < s.start_at + toIntervalDay(7)) > 0 AS converted\n    FROM (\n      SELECT person_id, min(toTimeZone(timestamp, 'UTC')) AS start_at\n      FROM events\n      WHERE event = 'signed_up'\n        AND person_id IS NOT NULL\n      GROUP BY person_id\n    ) AS s\n    LEFT JOIN (\n      SELECT person_id, toTimeZone(timestamp, 'UTC') AS ts\n      FROM events\n      WHERE event = 'invite_sent'\n        AND timestamp >= now() - toIntervalWeek(29)\n    ) AS x ON x.person_id = s.person_id\n    WHERE toMonday(s.start_at) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(27) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(2)\n    GROUP BY week, person_id\n  )\n  GROUP BY week\n) AS c ON c.week = w.week\nORDER BY week","postgres":"-- Invite rate: of people whose first signup fell in each week, the share who sent at least one invite within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '27 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '2 weeks',\n    interval '1 week'\n  ) AS g(week)\n),\nstarts AS (\n  SELECT user_id, min(occurred_at AT TIME ZONE 'UTC') AS start_at\n  FROM events\n  WHERE event_name = 'signed_up'\n    AND user_id IS NOT NULL\n  GROUP BY user_id\n),\ncohort AS (\n  SELECT\n    date_trunc('week', s.start_at)::date AS week,\n    s.user_id,\n    count(x.occurred_at) > 0 AS converted\n  FROM starts AS s\n  LEFT JOIN events AS x\n    ON x.user_id = s.user_id\n   AND x.event_name = 'invite_sent'\n   AND x.occurred_at AT TIME ZONE 'UTC' >= s.start_at\n   AND x.occurred_at AT TIME ZONE 'UTC' < s.start_at + interval '7 days'\n  WHERE s.start_at >= date_trunc('week', now() AT TIME ZONE 'UTC') - interval '27 weeks'\n    AND s.start_at < date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week'\n  GROUP BY 1, 2\n)\nSELECT\n  w.week,\n  count(c.user_id) FILTER (WHERE c.converted) AS numerator,\n  count(c.user_id) AS denominator,\n  (count(c.user_id) FILTER (WHERE c.converted))::numeric / nullif(count(c.user_id), 0) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;","bigquery":"-- Invite rate: of people whose first signup fell in each week, the share who sent at least one invite within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 27 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 2 WEEK), INTERVAL 1 WEEK)) AS week\n),\nstarts AS (\n  SELECT user_id, MIN(occurred_at) AS start_at\n  FROM events\n  WHERE event_name = 'signed_up'\n    AND user_id IS NOT NULL\n  GROUP BY user_id\n),\ncohort AS (\n  SELECT\n    DATE_TRUNC(DATE(s.start_at), ISOWEEK) AS week,\n    s.user_id,\n    COUNT(x.occurred_at) > 0 AS converted\n  FROM starts AS s\n  LEFT JOIN events AS x\n    ON x.user_id = s.user_id\n   AND x.event_name = 'invite_sent'\n   AND x.occurred_at >= s.start_at\n   AND x.occurred_at < TIMESTAMP_ADD(s.start_at, INTERVAL 7 DAY)\n  WHERE s.start_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 27 WEEK))\n    AND s.start_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK))\n  GROUP BY week, s.user_id\n)\nSELECT\n  w.week,\n  COUNTIF(c.converted) AS numerator,\n  COUNT(c.user_id) AS denominator,\n  SAFE_DIVIDE(COUNTIF(c.converted), COUNT(c.user_id)) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;","snowflake":"-- Invite rate: of people whose first signup fell in each week, the share who sent at least one invite within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 - ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nstarts AS (\n  SELECT user_id, MIN(occurred_at) AS start_at\n  FROM events\n  WHERE event_name = 'signed_up'\n    AND user_id IS NOT NULL\n  GROUP BY user_id\n),\ncohort AS (\n  SELECT\n    DATEADD(day, 1 - DAYOFWEEKISO(s.start_at), s.start_at::date) AS week,\n    s.user_id,\n    COUNT(x.occurred_at) > 0 AS converted\n  FROM starts AS s\n  LEFT JOIN events AS x\n    ON x.user_id = s.user_id\n   AND x.event_name = 'invite_sent'\n   AND x.occurred_at >= s.start_at\n   AND x.occurred_at < DATEADD(day, 7, s.start_at)\n  WHERE s.start_at >= DATEADD(week, -27, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND s.start_at < DATEADD(week, -1, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n  GROUP BY 1, 2\n)\nSELECT\n  w.week,\n  COUNT_IF(c.converted) AS numerator,\n  COUNT(c.user_id) AS denominator,\n  COUNT_IF(c.converted)::float / NULLIF(COUNT(c.user_id), 0) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"signups in the cohort","typical":0.16},"example":{"business":"saas","level":0.16,"volume":2200,"trend":0.05},"drivers":[{"id":"tracking","label":"Invite event","dropped":{"check":"Did the invite event stop firing for one invite path, such as share links or bulk invites?","yes":"Invites from one path fall to zero while accepted invites in the database hold."},"spiked":{"check":"Is the event firing on opening the invite dialog, or once per address in a bulk upload counted as several people?","yes":"Invites recorded far exceed invitations stored, or the rise comes from dialog opens with no addresses."}},{"id":"invite-flow","label":"Invite prompt","breakdown":"$device_type","dropped":{"check":"Did the invite prompt move, get hidden, or break on one device?","yes":"Invites fall from the day of a release, concentrated on one device or screen."},"spiked":{"check":"Was an invite step added to onboarding, or made more prominent?","yes":"Invites rise from the release date; check that invitees accept and use the product."}},{"id":"plan-limits","label":"Seats and pricing","breakdown":"plan","dropped":{"check":"Did seat limits tighten or per-seat pricing start, making an invite cost money?","yes":"Invites fall on the affected plans from the day of the change while others hold."},"spiked":{"check":"Did a plan add free seats or remove a seat limit?","yes":"Invites rise on that plan from the day of the change."}},{"id":"signup-mix","label":"Who signed up","metric":"signups","breakdown":"method","dropped":{"check":"Did more of the cohort arrive by invite? Invitees join an existing team and invite less.","yes":"The share of signups by invite rose while the rate within each method held."},"spiked":{"check":"Did more of the cohort arrive as team founders, from a campaign aimed at managers?","yes":"The share of signups by email or SSO rose while the rate within each method held."}},{"id":"activation","label":"Reaching value first","metric":"activation-rate","dropped":{"check":"Did fewer people reach the point where sharing the product makes sense?","yes":"Activation fell for the same cohorts, and invites fell among non-activated users first."},"spiked":{"check":"Did more people reach the point where sharing makes sense?","yes":"Activation rose for the same cohorts by a similar share."}}],"diagnose_order":["tracking","invite-flow","plan-limits","signup-mix","activation"],"related":["activation-rate","signups","onboarding-completion-rate","week-1-retention","feature-adoption-rate"],"prose":{"why_it_matters":"In a team product the first invite is the moment a trial becomes something more than one person relies on, and it drives the viral loop: every new user who invites others brings signups nobody paid for. Team tools often count an early invite as part of activation. At Copperline about 16% of new signups invite someone in their first week.","pitfalls":["Count people who invite, not invites sent. An admin inviting forty colleagues from a spreadsheet is one inviter.","Invited users sign up too, and they invite less. A week with many invite-driven signups lowers the rate with no change in the product.","A forced invite step in onboarding raises the rate and fills the list with invites nobody accepts. Track the share of invites accepted alongside it.","Only cohorts whose 7 days have closed are reported, so the latest point is the signups of two weeks ago."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "logo-churn-rate": { yaml: "id: logo-churn-rate\nname: Logo churn rate\naliases:\n  - Customer churn rate\n  - Churn rate\n  - Logo churn\n  - Account churn rate\n  - Subscriber churn rate\nfamily: subscription\nkind: rate\npolarity: down-is-good\n\ndefinition:\n  one_line: The share of customers paying at the start of the week who were no longer paying at its end.\n  formula: Customers paying at Monday 00:00 UTC with no paying subscription at Sunday 23:59 ÷ customers paying at Monday 00:00\n\nevents:\n  - name: subscription_updated\n    description: Any change to a subscription's plan, quantity, discount or status, with its new monthly amount.\n    also_called: [customer.subscription.updated, Subscription Updated, subscription_changed]\n    properties:\n      - name: subscription_id\n        description: The billing system's subscription id.\n      - name: mrr\n        description: The subscription's monthly amount after the change; zero on a free plan.\n      - name: status\n        description: active, trialing, past_due or canceled.\n\nnumerator:\n  label: Customers who stopped paying\n  aggregate: unique_users\n  event: subscription_updated\n  where:\n    - property: status\n      op: eq\n      value: canceled\n\nqueries:\n  hogql: |-\n    -- Logo churn rate for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: customers paying at the start of the week with no paying subscription at its end ÷ customers paying at the start. A customer is the person on the subscription; paying means active or past_due with MRR above zero, at each subscription's latest subscription_updated.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(c.churned, 0) AS numerator,\n      coalesce(c.paying, 0) AS denominator,\n      if(denominator = 0, NULL, numerator / denominator) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, countIf(paying_end = 0) AS churned, count() AS paying\n      FROM (\n        SELECT week, account, maxIf(paying, weeks_back = 1) AS paying_start, maxIf(paying, weeks_back = 0) AS paying_end\n        FROM (\n          SELECT\n            week,\n            weeks_back,\n            tupleElement(latest, 1) AS account,\n            if(tupleElement(latest, 3) IN ('active', 'past_due') AND tupleElement(latest, 2) > 0, 1, 0) AS paying\n          FROM (\n            SELECT s.week AS week, s.weeks_back AS weeks_back, u.subscription_id AS subscription_id, argMax(tuple(u.person, u.mrr, u.status), u.ts) AS latest\n            FROM (\n              SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week, arrayJoin([0, 1]) AS weeks_back\n            ) AS s\n            CROSS JOIN (\n              SELECT\n                toString(properties.subscription_id) AS subscription_id,\n                person_id AS person,\n                toTimeZone(timestamp, 'UTC') AS ts,\n                toFloat(properties.mrr) AS mrr,\n                toString(properties.status) AS status\n              FROM events\n              WHERE event = 'subscription_updated'\n                AND properties.subscription_id IS NOT NULL\n                AND person_id IS NOT NULL\n                AND toMonday(toTimeZone(timestamp, 'UTC')) < toMonday(toTimeZone(now(), 'UTC'))\n            ) AS u\n            WHERE toMonday(u.ts) <= s.week - toIntervalWeek(s.weeks_back)\n            GROUP BY week, weeks_back, subscription_id\n          )\n        )\n        GROUP BY week, account\n      )\n      WHERE paying_start = 1\n      GROUP BY week\n    ) AS c ON c.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Logo churn rate for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: customers paying at the start of the week with no paying subscription at its end ÷ customers paying at the start. A customer is the user_id on the subscription; paying means active or past_due with MRR above zero, at each subscription's latest subscription_updated.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    snaps AS (\n      SELECT w.week, b.weeks_back, w.week + 7 * (1 - b.weeks_back) AS cutoff\n      FROM weeks AS w\n      CROSS JOIN (VALUES (0), (1)) AS b(weeks_back)\n    ),\n    updates AS (\n      SELECT\n        properties->>'subscription_id' AS subscription_id,\n        user_id AS customer,\n        occurred_at AT TIME ZONE 'UTC' AS ts,\n        CASE WHEN properties->>'mrr' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr')::numeric END AS mrr,\n        properties->>'status' AS status\n      FROM events\n      WHERE event_name = 'subscription_updated'\n        AND properties->>'subscription_id' IS NOT NULL\n        AND user_id IS NOT NULL\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n    ),\n    latest AS (\n      SELECT DISTINCT ON (s.week, s.weeks_back, u.subscription_id) s.week, s.weeks_back, u.customer, u.mrr, u.status\n      FROM snaps AS s\n      JOIN updates AS u ON u.ts < s.cutoff\n      ORDER BY s.week, s.weeks_back, u.subscription_id, u.ts DESC\n    ),\n    paying AS (\n      SELECT DISTINCT week, weeks_back, customer\n      FROM latest\n      WHERE status IN ('active', 'past_due') AND mrr > 0\n    ),\n    weekly AS (\n      SELECT st.week, count(*) FILTER (WHERE en.customer IS NULL) AS churned, count(*) AS paying\n      FROM paying AS st\n      LEFT JOIN paying AS en ON en.week = st.week AND en.weeks_back = 0 AND en.customer = st.customer\n      WHERE st.weeks_back = 1\n      GROUP BY st.week\n    )\n    SELECT\n      w.week,\n      coalesce(c.churned, 0) AS numerator,\n      coalesce(c.paying, 0) AS denominator,\n      c.churned::numeric / nullif(c.paying, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS c ON c.week = w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Logo churn rate for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: customers paying at the start of the week with no paying subscription at its end ÷ customers paying at the start. A customer is the user_id on the subscription; paying means active or past_due with MRR above zero, at each subscription's latest subscription_updated.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    snaps AS (\n      SELECT w.week, weeks_back, TIMESTAMP(DATE_ADD(w.week, INTERVAL (1 - weeks_back) WEEK)) AS cutoff\n      FROM weeks AS w\n      CROSS JOIN UNNEST([0, 1]) AS weeks_back\n    ),\n    updates AS (\n      SELECT\n        JSON_VALUE(properties, '$.subscription_id') AS subscription_id,\n        user_id AS customer,\n        occurred_at,\n        SAFE_CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64) AS mrr,\n        JSON_VALUE(properties, '$.status') AS status\n      FROM events\n      WHERE event_name = 'subscription_updated'\n        AND JSON_VALUE(properties, '$.subscription_id') IS NOT NULL\n        AND user_id IS NOT NULL\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    ),\n    latest AS (\n      SELECT s.week, s.weeks_back, u.customer, u.mrr, u.status\n      FROM snaps AS s\n      CROSS JOIN updates AS u\n      WHERE u.occurred_at < s.cutoff\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY s.week, s.weeks_back, u.subscription_id ORDER BY u.occurred_at DESC) = 1\n    ),\n    paying AS (\n      SELECT DISTINCT week, weeks_back, customer\n      FROM latest\n      WHERE status IN ('active', 'past_due') AND mrr > 0\n    ),\n    weekly AS (\n      SELECT st.week, COUNTIF(en.customer IS NULL) AS churned, COUNT(*) AS paying\n      FROM paying AS st\n      LEFT JOIN paying AS en ON en.week = st.week AND en.weeks_back = 0 AND en.customer = st.customer\n      WHERE st.weeks_back = 1\n      GROUP BY st.week\n    )\n    SELECT\n      w.week,\n      COALESCE(c.churned, 0) AS numerator,\n      COALESCE(c.paying, 0) AS denominator,\n      SAFE_DIVIDE(c.churned, c.paying) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS c ON c.week = w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Logo churn rate for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: customers paying at the start of the week with no paying subscription at its end ÷ customers paying at the start. A customer is the user_id on the subscription; paying means active or past_due with MRR above zero, at each subscription's latest subscription_updated.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    snaps AS (\n      SELECT w.week, b.weeks_back, DATEADD(week, 1 - b.weeks_back, w.week) AS cutoff\n      FROM weeks AS w\n      CROSS JOIN (VALUES (0), (1)) AS b (weeks_back)\n    ),\n    updates AS (\n      SELECT\n        properties:\"subscription_id\"::string AS subscription_id,\n        user_id AS customer,\n        occurred_at,\n        TRY_TO_DOUBLE(properties:\"mrr\"::string) AS mrr,\n        properties:\"status\"::string AS status\n      FROM events\n      WHERE event_name = 'subscription_updated'\n        AND properties:\"subscription_id\"::string IS NOT NULL\n        AND user_id IS NOT NULL\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n    ),\n    latest AS (\n      SELECT s.week, s.weeks_back, u.customer, u.mrr, u.status\n      FROM snaps AS s\n      JOIN updates AS u ON u.occurred_at < s.cutoff\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY s.week, s.weeks_back, u.subscription_id ORDER BY u.occurred_at DESC) = 1\n    ),\n    paying AS (\n      SELECT DISTINCT week, weeks_back, customer\n      FROM latest\n      WHERE status IN ('active', 'past_due') AND mrr > 0\n    ),\n    weekly AS (\n      SELECT st.week, COUNT_IF(en.customer IS NULL) AS churned, COUNT(*) AS paying\n      FROM paying AS st\n      LEFT JOIN paying AS en ON en.week = st.week AND en.weeks_back = 0 AND en.customer = st.customer\n      WHERE st.weeks_back = 1\n      GROUP BY st.week\n    )\n    SELECT\n      w.week,\n      COALESCE(c.churned, 0) AS numerator,\n      COALESCE(c.paying, 0) AS denominator,\n      c.churned::float / NULLIF(c.paying, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS c ON c.week = w.week\n    ORDER BY w.week;\n\nnoise:\n  type: binomial\n  min_denominator: 300\n  volume_unit: paying customers at week start\n  typical: 0.0056\n  reference_volumes: [500, 2000, 8000, 30000]\n\nexample:\n  business: saas\n  level: 0.0056\n  volume: 1850\n  trend: 0.18\n\ndrivers:\n  - id: billing-sync\n    label: Billing sync\n    dropped:\n      check: Did cancellations or status changes stop reaching the event log?\n      yes: The billing system shows more ended subscriptions this week than the snapshot does.\n    spiked:\n      check: Did a sync or migration mark live customers as canceled, or cancel old unpaid subscriptions in bulk?\n      yes: Customers leave the paying count on one day with no cancellation in the billing system, or the ones that left had been past due for weeks.\n  - id: involuntary\n    label: Failed payments\n    feed: stripe\n    dropped:\n      check: Did dunning, retries or a card updater recover customers who would have lapsed?\n      yes: Fewer customers end in past_due and then canceled, while voluntary cancellations hold.\n    spiked:\n      check: Did more customers lapse for failed payments, from expiring cards, a dunning change or a processor incident?\n      yes: The extra churn is customers who went past_due first; Stripe shows an incident or more declines.\n  - id: renewal-cohort\n    label: Renewals due\n    dropped:\n      check: Did few annual or quarterly renewals fall due this week?\n      yes: Renewals due were unusually few; expect the rate to return to normal when they are.\n    spiked:\n      check: Did a large group of annual plans reach their renewal date?\n      yes: The customers who left cluster on start dates one year ago.\n  - id: plan-split\n    label: Plan\n    breakdown: plan\n    dropped:\n      check: Is the fall concentrated in one plan?\n      yes: One plan's churn falls after a change there, such as new onboarding or a price cut.\n    spiked:\n      check: Is one plan losing far more customers than the rest?\n      yes: One plan's churn jumps, often the cheapest, after a price or packaging change.\n  - id: new-customers\n    label: New customers leaving early\n    metric: activation-rate\n    dropped:\n      check: Did cohorts that went through a better onboarding reach their first renewals?\n      yes: Customers who signed up after an onboarding change churn less in their first months than earlier cohorts.\n    spiked:\n      check: Is the churn concentrated in customers in their first 90 days?\n      yes: Young customers are most of the churn, which points at onboarding, activation or a mis-sold segment.\n  - id: usage-decline\n    label: Usage before leaving\n    metric: wau\n    dropped:\n      check: Did usage at accounts that looked at risk recover?\n      yes: Weekly active users at low-usage accounts rose in the weeks before they would have renewed.\n    spiked:\n      check: Did the customers who left stop using the product weeks before they canceled?\n      yes: Active users at those accounts fell for a month or more first, so the cause is upstream, in usage.\n\ndiagnose_order: [billing-sync, involuntary, renewal-cohort, plan-split, new-customers, usage-decline]\n\nrelated: [churned-mrr, gross-revenue-retention, net-revenue-retention, arpa, customer-lifetime-value]\n\nprose:\n  why_it_matters: >-\n    Logo churn counts customers, not dollars, so it shows people leaving even when a few large\n    accounts keep revenue churn low. A weekly rate of 0.56% sounds small and is about 2.4% a\n    month, which replaces a quarter of the customer base every year. At 1,900 customers, chance\n    alone moves one week's rate by nearly as much as the rate itself, so read it over four weeks\n    or more.\n  pitfalls:\n    - Divide by customers paying at the start of the period. Using the end, or an average, lets this week's sign-ups dilute the rate.\n    - Customers who start and leave inside the same week are not in the starting count, so they are not in the numerator either. Count them on their own if they are common.\n    - A weekly rate is not a monthly rate divided by four. Convert with 1 − (1 − weekly)^4.35, which turns 0.56% a week into about 2.4% a month.\n    - Moving to a free plan is churn here, because the customer stopped paying. Report it apart from cancellations if free plans are common.\n    - Counting subscriptions instead of customers inflates churn every time someone changes plan by canceling one subscription and starting another.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"logo-churn-rate","name":"Logo churn rate","aliases":["Customer churn rate","Churn rate","Logo churn","Account churn rate","Subscriber churn rate"],"family":"subscription","kind":"rate","polarity":"down-is-good","definition":{"one_line":"The share of customers paying at the start of the week who were no longer paying at its end.","formula":"Customers paying at Monday 00:00 UTC with no paying subscription at Sunday 23:59 ÷ customers paying at Monday 00:00"},"events":[{"name":"subscription_updated","description":"Any change to a subscription's plan, quantity, discount or status, with its new monthly amount.","also_called":["customer.subscription.updated","Subscription Updated","subscription_changed"],"properties":[{"name":"subscription_id","description":"The billing system's subscription id."},{"name":"mrr","description":"The subscription's monthly amount after the change; zero on a free plan."},{"name":"status","description":"active, trialing, past_due or canceled."}]}],"numerator":{"label":"Customers who stopped paying","aggregate":"unique_users","event":"subscription_updated","where":[{"property":"status","op":"eq","value":"canceled"}]},"queries":{"hogql":"-- Logo churn rate for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: customers paying at the start of the week with no paying subscription at its end ÷ customers paying at the start. A customer is the person on the subscription; paying means active or past_due with MRR above zero, at each subscription's latest subscription_updated.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(c.churned, 0) AS numerator,\n  coalesce(c.paying, 0) AS denominator,\n  if(denominator = 0, NULL, numerator / denominator) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, countIf(paying_end = 0) AS churned, count() AS paying\n  FROM (\n    SELECT week, account, maxIf(paying, weeks_back = 1) AS paying_start, maxIf(paying, weeks_back = 0) AS paying_end\n    FROM (\n      SELECT\n        week,\n        weeks_back,\n        tupleElement(latest, 1) AS account,\n        if(tupleElement(latest, 3) IN ('active', 'past_due') AND tupleElement(latest, 2) > 0, 1, 0) AS paying\n      FROM (\n        SELECT s.week AS week, s.weeks_back AS weeks_back, u.subscription_id AS subscription_id, argMax(tuple(u.person, u.mrr, u.status), u.ts) AS latest\n        FROM (\n          SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week, arrayJoin([0, 1]) AS weeks_back\n        ) AS s\n        CROSS JOIN (\n          SELECT\n            toString(properties.subscription_id) AS subscription_id,\n            person_id AS person,\n            toTimeZone(timestamp, 'UTC') AS ts,\n            toFloat(properties.mrr) AS mrr,\n            toString(properties.status) AS status\n          FROM events\n          WHERE event = 'subscription_updated'\n            AND properties.subscription_id IS NOT NULL\n            AND person_id IS NOT NULL\n            AND toMonday(toTimeZone(timestamp, 'UTC')) < toMonday(toTimeZone(now(), 'UTC'))\n        ) AS u\n        WHERE toMonday(u.ts) <= s.week - toIntervalWeek(s.weeks_back)\n        GROUP BY week, weeks_back, subscription_id\n      )\n    )\n    GROUP BY week, account\n  )\n  WHERE paying_start = 1\n  GROUP BY week\n) AS c ON c.week = w.week\nORDER BY week","postgres":"-- Logo churn rate for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: customers paying at the start of the week with no paying subscription at its end ÷ customers paying at the start. A customer is the user_id on the subscription; paying means active or past_due with MRR above zero, at each subscription's latest subscription_updated.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nsnaps AS (\n  SELECT w.week, b.weeks_back, w.week + 7 * (1 - b.weeks_back) AS cutoff\n  FROM weeks AS w\n  CROSS JOIN (VALUES (0), (1)) AS b(weeks_back)\n),\nupdates AS (\n  SELECT\n    properties->>'subscription_id' AS subscription_id,\n    user_id AS customer,\n    occurred_at AT TIME ZONE 'UTC' AS ts,\n    CASE WHEN properties->>'mrr' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr')::numeric END AS mrr,\n    properties->>'status' AS status\n  FROM events\n  WHERE event_name = 'subscription_updated'\n    AND properties->>'subscription_id' IS NOT NULL\n    AND user_id IS NOT NULL\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n),\nlatest AS (\n  SELECT DISTINCT ON (s.week, s.weeks_back, u.subscription_id) s.week, s.weeks_back, u.customer, u.mrr, u.status\n  FROM snaps AS s\n  JOIN updates AS u ON u.ts < s.cutoff\n  ORDER BY s.week, s.weeks_back, u.subscription_id, u.ts DESC\n),\npaying AS (\n  SELECT DISTINCT week, weeks_back, customer\n  FROM latest\n  WHERE status IN ('active', 'past_due') AND mrr > 0\n),\nweekly AS (\n  SELECT st.week, count(*) FILTER (WHERE en.customer IS NULL) AS churned, count(*) AS paying\n  FROM paying AS st\n  LEFT JOIN paying AS en ON en.week = st.week AND en.weeks_back = 0 AND en.customer = st.customer\n  WHERE st.weeks_back = 1\n  GROUP BY st.week\n)\nSELECT\n  w.week,\n  coalesce(c.churned, 0) AS numerator,\n  coalesce(c.paying, 0) AS denominator,\n  c.churned::numeric / nullif(c.paying, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS c ON c.week = w.week\nORDER BY w.week;","bigquery":"-- Logo churn rate for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: customers paying at the start of the week with no paying subscription at its end ÷ customers paying at the start. A customer is the user_id on the subscription; paying means active or past_due with MRR above zero, at each subscription's latest subscription_updated.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nsnaps AS (\n  SELECT w.week, weeks_back, TIMESTAMP(DATE_ADD(w.week, INTERVAL (1 - weeks_back) WEEK)) AS cutoff\n  FROM weeks AS w\n  CROSS JOIN UNNEST([0, 1]) AS weeks_back\n),\nupdates AS (\n  SELECT\n    JSON_VALUE(properties, '$.subscription_id') AS subscription_id,\n    user_id AS customer,\n    occurred_at,\n    SAFE_CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64) AS mrr,\n    JSON_VALUE(properties, '$.status') AS status\n  FROM events\n  WHERE event_name = 'subscription_updated'\n    AND JSON_VALUE(properties, '$.subscription_id') IS NOT NULL\n    AND user_id IS NOT NULL\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n),\nlatest AS (\n  SELECT s.week, s.weeks_back, u.customer, u.mrr, u.status\n  FROM snaps AS s\n  CROSS JOIN updates AS u\n  WHERE u.occurred_at < s.cutoff\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY s.week, s.weeks_back, u.subscription_id ORDER BY u.occurred_at DESC) = 1\n),\npaying AS (\n  SELECT DISTINCT week, weeks_back, customer\n  FROM latest\n  WHERE status IN ('active', 'past_due') AND mrr > 0\n),\nweekly AS (\n  SELECT st.week, COUNTIF(en.customer IS NULL) AS churned, COUNT(*) AS paying\n  FROM paying AS st\n  LEFT JOIN paying AS en ON en.week = st.week AND en.weeks_back = 0 AND en.customer = st.customer\n  WHERE st.weeks_back = 1\n  GROUP BY st.week\n)\nSELECT\n  w.week,\n  COALESCE(c.churned, 0) AS numerator,\n  COALESCE(c.paying, 0) AS denominator,\n  SAFE_DIVIDE(c.churned, c.paying) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS c ON c.week = w.week\nORDER BY w.week;","snowflake":"-- Logo churn rate for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: customers paying at the start of the week with no paying subscription at its end ÷ customers paying at the start. A customer is the user_id on the subscription; paying means active or past_due with MRR above zero, at each subscription's latest subscription_updated.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nsnaps AS (\n  SELECT w.week, b.weeks_back, DATEADD(week, 1 - b.weeks_back, w.week) AS cutoff\n  FROM weeks AS w\n  CROSS JOIN (VALUES (0), (1)) AS b (weeks_back)\n),\nupdates AS (\n  SELECT\n    properties:\"subscription_id\"::string AS subscription_id,\n    user_id AS customer,\n    occurred_at,\n    TRY_TO_DOUBLE(properties:\"mrr\"::string) AS mrr,\n    properties:\"status\"::string AS status\n  FROM events\n  WHERE event_name = 'subscription_updated'\n    AND properties:\"subscription_id\"::string IS NOT NULL\n    AND user_id IS NOT NULL\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n),\nlatest AS (\n  SELECT s.week, s.weeks_back, u.customer, u.mrr, u.status\n  FROM snaps AS s\n  JOIN updates AS u ON u.occurred_at < s.cutoff\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY s.week, s.weeks_back, u.subscription_id ORDER BY u.occurred_at DESC) = 1\n),\npaying AS (\n  SELECT DISTINCT week, weeks_back, customer\n  FROM latest\n  WHERE status IN ('active', 'past_due') AND mrr > 0\n),\nweekly AS (\n  SELECT st.week, COUNT_IF(en.customer IS NULL) AS churned, COUNT(*) AS paying\n  FROM paying AS st\n  LEFT JOIN paying AS en ON en.week = st.week AND en.weeks_back = 0 AND en.customer = st.customer\n  WHERE st.weeks_back = 1\n  GROUP BY st.week\n)\nSELECT\n  w.week,\n  COALESCE(c.churned, 0) AS numerator,\n  COALESCE(c.paying, 0) AS denominator,\n  c.churned::float / NULLIF(c.paying, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS c ON c.week = w.week\nORDER BY w.week;"},"noise":{"type":"binomial","min_denominator":300,"volume_unit":"paying customers at week start","typical":0.0056,"reference_volumes":[500,2000,8000,30000]},"example":{"business":"saas","level":0.0056,"volume":1850,"trend":0.18},"drivers":[{"id":"billing-sync","label":"Billing sync","dropped":{"check":"Did cancellations or status changes stop reaching the event log?","yes":"The billing system shows more ended subscriptions this week than the snapshot does."},"spiked":{"check":"Did a sync or migration mark live customers as canceled, or cancel old unpaid subscriptions in bulk?","yes":"Customers leave the paying count on one day with no cancellation in the billing system, or the ones that left had been past due for weeks."}},{"id":"involuntary","label":"Failed payments","feed":"stripe","dropped":{"check":"Did dunning, retries or a card updater recover customers who would have lapsed?","yes":"Fewer customers end in past_due and then canceled, while voluntary cancellations hold."},"spiked":{"check":"Did more customers lapse for failed payments, from expiring cards, a dunning change or a processor incident?","yes":"The extra churn is customers who went past_due first; Stripe shows an incident or more declines."}},{"id":"renewal-cohort","label":"Renewals due","dropped":{"check":"Did few annual or quarterly renewals fall due this week?","yes":"Renewals due were unusually few; expect the rate to return to normal when they are."},"spiked":{"check":"Did a large group of annual plans reach their renewal date?","yes":"The customers who left cluster on start dates one year ago."}},{"id":"plan-split","label":"Plan","breakdown":"plan","dropped":{"check":"Is the fall concentrated in one plan?","yes":"One plan's churn falls after a change there, such as new onboarding or a price cut."},"spiked":{"check":"Is one plan losing far more customers than the rest?","yes":"One plan's churn jumps, often the cheapest, after a price or packaging change."}},{"id":"new-customers","label":"New customers leaving early","metric":"activation-rate","dropped":{"check":"Did cohorts that went through a better onboarding reach their first renewals?","yes":"Customers who signed up after an onboarding change churn less in their first months than earlier cohorts."},"spiked":{"check":"Is the churn concentrated in customers in their first 90 days?","yes":"Young customers are most of the churn, which points at onboarding, activation or a mis-sold segment."}},{"id":"usage-decline","label":"Usage before leaving","metric":"wau","dropped":{"check":"Did usage at accounts that looked at risk recover?","yes":"Weekly active users at low-usage accounts rose in the weeks before they would have renewed."},"spiked":{"check":"Did the customers who left stop using the product weeks before they canceled?","yes":"Active users at those accounts fell for a month or more first, so the cause is upstream, in usage."}}],"diagnose_order":["billing-sync","involuntary","renewal-cohort","plan-split","new-customers","usage-decline"],"related":["churned-mrr","gross-revenue-retention","net-revenue-retention","arpa","customer-lifetime-value"],"prose":{"why_it_matters":"Logo churn counts customers, not dollars, so it shows people leaving even when a few large accounts keep revenue churn low. A weekly rate of 0.56% sounds small and is about 2.4% a month, which replaces a quarter of the customer base every year. At 1,900 customers, chance alone moves one week's rate by nearly as much as the rate itself, so read it over four weeks or more.","pitfalls":["Divide by customers paying at the start of the period. Using the end, or an average, lets this week's sign-ups dilute the rate.","Customers who start and leave inside the same week are not in the starting count, so they are not in the numerator either. Count them on their own if they are common.","A weekly rate is not a monthly rate divided by four. Convert with 1 − (1 − weekly)^4.35, which turns 0.56% a week into about 2.4% a month.","Moving to a free plan is churn here, because the customer stopped paying. Report it apart from cancellations if free plans are common.","Counting subscriptions instead of customers inflates churn every time someone changes plan by canceling one subscription and starting another."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "ltv-to-cac": { yaml: "id: ltv-to-cac\nname: LTV to CAC\naliases:\n  - LTV:CAC\n  - LTV/CAC ratio\n  - LTV to CAC ratio\n  - CLV to CAC ratio\nfamily: customers\nkind: ratio\npolarity: up-is-good\n\ndefinition:\n  one_line: The gross profit a week's new customers bring in their first 365 days, for every dollar of ad spend that week.\n  formula: 12-month gross profit per new customer ÷ new customer acquisition cost, by first-order week (the cohort's 12-month gross profit ÷ that week's ad spend)\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: is_first_order\n        description: True when the store has no earlier order from this customer, from its own customer records.\n      - name: customer_id\n        description: The store's customer id, shared by guest and logged-in orders with the same email.\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n      - name: cost_of_goods\n        description: What the items in the order cost the store.\n  - name: order_refunded\n    description: A refund issued against an earlier order, full or partial.\n    also_called: [refund, Order Refunded]\n    properties:\n      - name: order_id\n        description: The order the refund belongs to.\n      - name: amount\n        description: The refunded amount, excluding tax and shipping.\n  - name: ad_spend\n    description: One row per ad channel per day, synced from the ad platforms.\n    also_called: [Ad Spend, ad_cost, campaign_cost]\n    properties:\n      - name: spend\n        description: The day's spend on the channel, in the store's currency.\n      - name: channel\n        description: The ad platform, such as meta or google.\n\nnumerator:\n  label: Cohort gross profit in its first 365 days\n  aggregate: sum\n  event: order_completed\n  property: total\ndenominator:\n  label: Ad spend in the cohort week\n  aggregate: sum\n  event: ad_spend\n  property: spend\n\nqueries:\n  hogql: |-\n    -- LTV to CAC: gross profit (order totals − cost of goods − refunds) from each first-order week's new customers over their first 365 days ÷ ad spend in that week. First-order weeks 79 to 54 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 365 days close.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(c.amount_total, 0) AS numerator,\n      coalesce(a.spend, 0) AS denominator,\n      if(denominator = 0, NULL, numerator / denominator) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(54, 80))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, sum(amount) AS amount_total, count() AS customers\n      FROM (\n        SELECT\n          toMonday(f.first_at) AS week,\n          f.customer_id AS customer_id,\n          sumIf(o.amount, o.ts >= f.first_at AND o.ts < f.first_at + toIntervalDay(365)) AS amount\n        FROM (\n          SELECT customer_id, min(ts) AS first_at\n          FROM (\n            SELECT coalesce(properties.customer_id, toString(person_id)) AS customer_id, toTimeZone(timestamp, 'UTC') AS ts\n            FROM events\n            WHERE event = 'order_completed'\n              AND properties.is_first_order = 'true'\n              AND timestamp >= now() - toIntervalWeek(80)\n              AND toMonday(toTimeZone(timestamp, 'UTC')) >= toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(79)\n          )\n          WHERE customer_id IS NOT NULL\n          GROUP BY customer_id\n        ) AS f\n        INNER JOIN (\n          SELECT po.customer_id AS customer_id, po.ts AS ts, po.total - coalesce(po.cost_of_goods, 0) - coalesce(r.refunded, 0) AS amount\n          FROM (\n            SELECT\n              coalesce(properties.customer_id, toString(person_id)) AS customer_id,\n              properties.order_id AS order_id,\n              toTimeZone(timestamp, 'UTC') AS ts,\n              toFloat(properties.total) AS total,\n              toFloat(properties.cost_of_goods) AS cost_of_goods\n            FROM events\n            WHERE event = 'order_completed'\n              AND timestamp >= now() - toIntervalWeek(80)\n              AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(79) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n          ) AS po\n          LEFT JOIN (\n            SELECT properties.order_id AS order_id, sum(toFloat(properties.amount)) AS refunded\n            FROM events\n            WHERE event = 'order_refunded'\n              AND timestamp >= now() - toIntervalWeek(80)\n              AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(79) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n            GROUP BY order_id\n          ) AS r ON r.order_id = po.order_id\n        ) AS o ON o.customer_id = f.customer_id\n        WHERE toMonday(f.first_at) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(79) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(54)\n        GROUP BY week, customer_id\n      )\n      GROUP BY week\n    ) AS c ON c.week = w.week\n    LEFT JOIN (\n      SELECT toMonday(toTimeZone(timestamp, 'UTC')) AS week, sum(toFloat(properties.spend)) AS spend\n      FROM events\n      WHERE event = 'ad_spend'\n        AND timestamp >= now() - toIntervalWeek(80)\n        AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(79) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(54)\n      GROUP BY week\n    ) AS a ON a.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- LTV to CAC: gross profit (order totals − cost of goods − refunds) from each first-order week's new customers over their first 365 days ÷ ad spend in that week. First-order weeks 79 to 54 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 365 days close.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '79 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '54 weeks',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    refunds AS (\n      SELECT properties->>'order_id' AS order_id, sum(CASE WHEN properties->>'amount' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'amount')::numeric END) AS refunded\n      FROM events\n      WHERE event_name = 'order_refunded'\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '79 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n      GROUP BY 1\n    ),\n    orders AS (\n      SELECT\n        coalesce(e.properties->>'customer_id', e.user_id) AS customer_id,\n        e.properties->>'is_first_order' = 'true' AS is_first_order,\n        e.occurred_at AT TIME ZONE 'UTC' AS ts,\n        CASE WHEN e.properties->>'total' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (e.properties->>'total')::numeric END\n          - coalesce(CASE WHEN e.properties->>'cost_of_goods' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (e.properties->>'cost_of_goods')::numeric END, 0)\n          - coalesce(r.refunded, 0) AS amount\n      FROM events AS e\n      LEFT JOIN refunds AS r ON r.order_id = e.properties->>'order_id'\n      WHERE e.event_name = 'order_completed'\n        AND e.occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '79 weeks') AT TIME ZONE 'UTC'\n        AND e.occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n    ),\n    first_orders AS (\n      SELECT customer_id, min(ts) AS first_at\n      FROM orders\n      WHERE is_first_order\n        AND customer_id IS NOT NULL\n        AND ts < date_trunc('week', now() AT TIME ZONE 'UTC') - interval '53 weeks'\n      GROUP BY customer_id\n    ),\n    cohort AS (\n      SELECT date_trunc('week', f.first_at)::date AS week, f.customer_id, sum(o.amount) AS amount\n      FROM first_orders AS f\n      JOIN orders AS o\n        ON o.customer_id = f.customer_id\n       AND o.ts >= f.first_at\n       AND o.ts < f.first_at + interval '365 days'\n      GROUP BY 1, 2\n    ),\n    spend AS (\n      SELECT date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week, sum(CASE WHEN properties->>'spend' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'spend')::numeric END) AS spend\n      FROM events\n      WHERE event_name = 'ad_spend'\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '79 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '53 weeks') AT TIME ZONE 'UTC'\n      GROUP BY 1\n    ),\n    profit AS (\n      SELECT week, sum(amount) AS gross_profit\n      FROM cohort\n      GROUP BY week\n    ),\n    totals AS (\n      SELECT w.week, coalesce(p.gross_profit, 0) AS gross_profit, coalesce(s.spend, 0) AS spend\n      FROM weeks AS w\n      LEFT JOIN profit AS p ON p.week = w.week\n      LEFT JOIN spend AS s ON s.week = w.week\n    )\n    SELECT week, gross_profit AS numerator, spend AS denominator, gross_profit / nullif(spend, 0) AS value\n    FROM totals\n    ORDER BY week;\n  bigquery: |-\n    -- LTV to CAC: gross profit (order totals − cost of goods − refunds) from each first-order week's new customers over their first 365 days ÷ ad spend in that week. First-order weeks 79 to 54 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 365 days close.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 79 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 54 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    refunds AS (\n      SELECT JSON_VALUE(properties, '$.order_id') AS order_id, SUM(SAFE_CAST(JSON_VALUE(properties, '$.amount') AS FLOAT64)) AS refunded\n      FROM events\n      WHERE event_name = 'order_refunded'\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 79 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY order_id\n    ),\n    orders AS (\n      SELECT\n        COALESCE(JSON_VALUE(e.properties, '$.customer_id'), e.user_id) AS customer_id,\n        JSON_VALUE(e.properties, '$.is_first_order') = 'true' AS is_first_order,\n        e.occurred_at,\n        SAFE_CAST(JSON_VALUE(e.properties, '$.total') AS FLOAT64)\n          - COALESCE(SAFE_CAST(JSON_VALUE(e.properties, '$.cost_of_goods') AS FLOAT64), 0)\n          - COALESCE(r.refunded, 0) AS amount\n      FROM events AS e\n      LEFT JOIN refunds AS r ON r.order_id = JSON_VALUE(e.properties, '$.order_id')\n      WHERE e.event_name = 'order_completed'\n        AND e.occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 79 WEEK))\n        AND e.occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    ),\n    first_orders AS (\n      SELECT customer_id, MIN(occurred_at) AS first_at\n      FROM orders\n      WHERE is_first_order\n        AND customer_id IS NOT NULL\n        AND occurred_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 53 WEEK))\n      GROUP BY customer_id\n    ),\n    cohort AS (\n      SELECT DATE_TRUNC(DATE(f.first_at), ISOWEEK) AS week, f.customer_id, SUM(o.amount) AS amount\n      FROM first_orders AS f\n      JOIN orders AS o\n        ON o.customer_id = f.customer_id\n       AND o.occurred_at >= f.first_at\n       AND o.occurred_at < TIMESTAMP_ADD(f.first_at, INTERVAL 365 DAY)\n      GROUP BY week, f.customer_id\n    ),\n    spend AS (\n      SELECT DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week, SUM(SAFE_CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64)) AS spend\n      FROM events\n      WHERE event_name = 'ad_spend'\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 79 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 53 WEEK))\n      GROUP BY week\n    ),\n    profit AS (\n      SELECT week, SUM(amount) AS gross_profit\n      FROM cohort\n      GROUP BY week\n    ),\n    totals AS (\n      SELECT w.week, COALESCE(p.gross_profit, 0) AS gross_profit, COALESCE(s.spend, 0) AS spend\n      FROM weeks AS w\n      LEFT JOIN profit AS p ON p.week = w.week\n      LEFT JOIN spend AS s ON s.week = w.week\n    )\n    SELECT week, gross_profit AS numerator, spend AS denominator, SAFE_DIVIDE(gross_profit, spend) AS value\n    FROM totals\n    ORDER BY week;\n  snowflake: |-\n    -- LTV to CAC: gross profit (order totals − cost of goods − refunds) from each first-order week's new customers over their first 365 days ÷ ad spend in that week. First-order weeks 79 to 54 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 365 days close.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -53 - ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    refunds AS (\n      SELECT properties:\"order_id\"::string AS order_id, SUM(TRY_TO_DOUBLE(properties:\"amount\"::string)) AS refunded\n      FROM events\n      WHERE event_name = 'order_refunded'\n        AND occurred_at >= DATEADD(week, -79, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n      GROUP BY 1\n    ),\n    orders AS (\n      SELECT\n        COALESCE(e.properties:\"customer_id\"::string, e.user_id) AS customer_id,\n        e.properties:\"is_first_order\"::string = 'true' AS is_first_order,\n        e.occurred_at,\n        TRY_TO_DOUBLE(e.properties:\"total\"::string)\n          - COALESCE(TRY_TO_DOUBLE(e.properties:\"cost_of_goods\"::string), 0)\n          - COALESCE(r.refunded, 0) AS amount\n      FROM events AS e\n      LEFT JOIN refunds AS r ON r.order_id = e.properties:\"order_id\"::string\n      WHERE e.event_name = 'order_completed'\n        AND e.occurred_at >= DATEADD(week, -79, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND e.occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n    ),\n    first_orders AS (\n      SELECT customer_id, MIN(occurred_at) AS first_at\n      FROM orders\n      WHERE is_first_order\n        AND customer_id IS NOT NULL\n        AND occurred_at < DATEADD(week, -53, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n      GROUP BY customer_id\n    ),\n    cohort AS (\n      SELECT DATEADD(day, 1 - DAYOFWEEKISO(f.first_at), f.first_at::date) AS week, f.customer_id, SUM(o.amount) AS amount\n      FROM first_orders AS f\n      JOIN orders AS o\n        ON o.customer_id = f.customer_id\n       AND o.occurred_at >= f.first_at\n       AND o.occurred_at < DATEADD(day, 365, f.first_at)\n      GROUP BY 1, 2\n    ),\n    spend AS (\n      SELECT DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week, SUM(TRY_TO_DOUBLE(properties:\"spend\"::string)) AS spend\n      FROM events\n      WHERE event_name = 'ad_spend'\n        AND occurred_at >= DATEADD(week, -79, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(week, -53, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n      GROUP BY 1\n    ),\n    profit AS (\n      SELECT week, SUM(amount) AS gross_profit\n      FROM cohort\n      GROUP BY week\n    ),\n    totals AS (\n      SELECT w.week, COALESCE(p.gross_profit, 0) AS gross_profit, COALESCE(s.spend, 0) AS spend\n      FROM weeks AS w\n      LEFT JOIN profit AS p ON p.week = w.week\n      LEFT JOIN spend AS s ON s.week = w.week\n    )\n    SELECT week, gross_profit AS numerator, spend AS denominator, gross_profit / NULLIF(spend, 0) AS value\n    FROM totals\n    ORDER BY week;\n\nnoise:\n  type: process\n  min_denominator: 200\n  volume_unit: first-time customers in the cohort\n  typical: 1.7\n\nexample:\n  business: store\n  level: 1.7\n  volume: 6800\n  trend: -0.05\n\ndrivers:\n  - id: spend-tracking\n    label: Spend records\n    dropped:\n      check: Was spend double counted in the cohort week, such as a platform synced twice or a monthly invoice booked in one week?\n      yes: Spend in the cohort week is far above the ad platforms' own reports for those days.\n    spiked:\n      check: Did a channel's spend fail to sync for the cohort week?\n      yes: One channel shows zero or partial spend on days it was running.\n  - id: calendar\n    label: Holiday cohorts\n    feed: shopping\n    dropped:\n      check: Is this a Black Friday or holiday cohort, won at a peak price and reordering less?\n      yes: The same cohort weeks last year show the same dip.\n    spiked:\n      check: Is this a quiet-season cohort, won cheaply from returning visitors and organic search?\n      yes: The same cohort weeks last year show the same rise.\n  - id: cac\n    label: Acquisition cost\n    metric: ncac\n    dropped:\n      check: Did new customers cost more to win in the cohort week?\n      yes: New customer CAC for that week sits above its usual range while 12-month value holds.\n    spiked:\n      check: Did new customers cost less to win, from cheaper media or more organic buyers?\n      yes: New customer CAC for that week sits below its usual range.\n  - id: ltv\n    label: 12-month value\n    metric: customer-lifetime-value\n    dropped:\n      check: Did the cohort spend less in its first year?\n      yes: Customer lifetime value for the cohort falls while CAC holds.\n    spiked:\n      check: Did the cohort spend more in its first year?\n      yes: Customer lifetime value for the cohort rises while CAC holds.\n  - id: margin\n    label: Gross margin\n    metric: gross-margin\n    dropped:\n      check: Did product costs rise or discounts deepen during the cohort's year?\n      yes: Revenue per customer holds while gross margin on their orders falls.\n    spiked:\n      check: Did a price rise or cheaper sourcing lift margin on the cohort's orders?\n      yes: Gross margin on the cohort's orders runs above earlier cohorts.\n  - id: channel-mix\n    label: Channel mix\n    feed: ad-platforms\n    dropped:\n      check: Did spend shift in the cohort week to a channel that wins lower-value buyers?\n      yes: Spend share moved to one channel whose customers have a lower 12-month value.\n    spiked:\n      check: Did spend shift toward channels whose customers are worth more?\n      yes: Spend share moved to a channel whose customers have a higher 12-month value.\n\ndiagnose_order: [spend-tracking, calendar, cac, ltv, margin, channel-mix]\n\nrelated: [customer-lifetime-value, ncac, blended-cac, cac-payback, gross-margin]\n\nprose:\n  why_it_matters: >-\n    LTV to CAC asks whether acquisition pays: at 1.0 a cohort's first year of gross profit only just\n    repays what it cost to win. SaaS investors look for 3 or more over a customer's lifetime; on 12\n    months of realized gross profit, healthy stores usually sit between 1.5 and 3. It checks growth\n    in both directions: below 1 is growth bought too dear, and well above 3 often means the budget\n    could be larger.\n  pitfalls:\n    - Use gross profit, not revenue. A revenue ratio of 3 at a 40% margin is a gross-profit ratio of 1.2, which barely pays back.\n    - Blended CAC divides all spend by all new customers and credits paid media with organic buyers, which flatters the ratio. Read paid-channel numbers before raising budgets.\n    - Ratios built from projected lifetimes, such as ARPA × margin ÷ churn in SaaS, explode as churn nears zero. Cap the lifetime at 3 to 5 years, or use realized months as this spec does.\n    - Spend booked in the wrong week, from monthly invoices or a failed sync, makes one cohort look free and the next ruinous. Check daily spend by channel before reading a jump.\n    - Only cohorts whose 365 days have closed are reported, so this lags by a year. Steer today's acquisition with new customer CAC and second order rate.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"ltv-to-cac","name":"LTV to CAC","aliases":["LTV:CAC","LTV/CAC ratio","LTV to CAC ratio","CLV to CAC ratio"],"family":"customers","kind":"ratio","polarity":"up-is-good","definition":{"one_line":"The gross profit a week's new customers bring in their first 365 days, for every dollar of ad spend that week.","formula":"12-month gross profit per new customer ÷ new customer acquisition cost, by first-order week (the cohort's 12-month gross profit ÷ that week's ad spend)"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"is_first_order","description":"True when the store has no earlier order from this customer, from its own customer records."},{"name":"customer_id","description":"The store's customer id, shared by guest and logged-in orders with the same email."},{"name":"total","description":"Order value after discounts, before tax and shipping."},{"name":"cost_of_goods","description":"What the items in the order cost the store."}]},{"name":"order_refunded","description":"A refund issued against an earlier order, full or partial.","also_called":["refund","Order Refunded"],"properties":[{"name":"order_id","description":"The order the refund belongs to."},{"name":"amount","description":"The refunded amount, excluding tax and shipping."}]},{"name":"ad_spend","description":"One row per ad channel per day, synced from the ad platforms.","also_called":["Ad Spend","ad_cost","campaign_cost"],"properties":[{"name":"spend","description":"The day's spend on the channel, in the store's currency."},{"name":"channel","description":"The ad platform, such as meta or google."}]}],"numerator":{"label":"Cohort gross profit in its first 365 days","aggregate":"sum","event":"order_completed","property":"total"},"denominator":{"label":"Ad spend in the cohort week","aggregate":"sum","event":"ad_spend","property":"spend"},"queries":{"hogql":"-- LTV to CAC: gross profit (order totals − cost of goods − refunds) from each first-order week's new customers over their first 365 days ÷ ad spend in that week. First-order weeks 79 to 54 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 365 days close.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(c.amount_total, 0) AS numerator,\n  coalesce(a.spend, 0) AS denominator,\n  if(denominator = 0, NULL, numerator / denominator) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(54, 80))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, sum(amount) AS amount_total, count() AS customers\n  FROM (\n    SELECT\n      toMonday(f.first_at) AS week,\n      f.customer_id AS customer_id,\n      sumIf(o.amount, o.ts >= f.first_at AND o.ts < f.first_at + toIntervalDay(365)) AS amount\n    FROM (\n      SELECT customer_id, min(ts) AS first_at\n      FROM (\n        SELECT coalesce(properties.customer_id, toString(person_id)) AS customer_id, toTimeZone(timestamp, 'UTC') AS ts\n        FROM events\n        WHERE event = 'order_completed'\n          AND properties.is_first_order = 'true'\n          AND timestamp >= now() - toIntervalWeek(80)\n          AND toMonday(toTimeZone(timestamp, 'UTC')) >= toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(79)\n      )\n      WHERE customer_id IS NOT NULL\n      GROUP BY customer_id\n    ) AS f\n    INNER JOIN (\n      SELECT po.customer_id AS customer_id, po.ts AS ts, po.total - coalesce(po.cost_of_goods, 0) - coalesce(r.refunded, 0) AS amount\n      FROM (\n        SELECT\n          coalesce(properties.customer_id, toString(person_id)) AS customer_id,\n          properties.order_id AS order_id,\n          toTimeZone(timestamp, 'UTC') AS ts,\n          toFloat(properties.total) AS total,\n          toFloat(properties.cost_of_goods) AS cost_of_goods\n        FROM events\n        WHERE event = 'order_completed'\n          AND timestamp >= now() - toIntervalWeek(80)\n          AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(79) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n      ) AS po\n      LEFT JOIN (\n        SELECT properties.order_id AS order_id, sum(toFloat(properties.amount)) AS refunded\n        FROM events\n        WHERE event = 'order_refunded'\n          AND timestamp >= now() - toIntervalWeek(80)\n          AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(79) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n        GROUP BY order_id\n      ) AS r ON r.order_id = po.order_id\n    ) AS o ON o.customer_id = f.customer_id\n    WHERE toMonday(f.first_at) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(79) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(54)\n    GROUP BY week, customer_id\n  )\n  GROUP BY week\n) AS c ON c.week = w.week\nLEFT JOIN (\n  SELECT toMonday(toTimeZone(timestamp, 'UTC')) AS week, sum(toFloat(properties.spend)) AS spend\n  FROM events\n  WHERE event = 'ad_spend'\n    AND timestamp >= now() - toIntervalWeek(80)\n    AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(79) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(54)\n  GROUP BY week\n) AS a ON a.week = w.week\nORDER BY week","postgres":"-- LTV to CAC: gross profit (order totals − cost of goods − refunds) from each first-order week's new customers over their first 365 days ÷ ad spend in that week. First-order weeks 79 to 54 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 365 days close.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '79 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '54 weeks',\n    interval '1 week'\n  ) AS g(week)\n),\nrefunds AS (\n  SELECT properties->>'order_id' AS order_id, sum(CASE WHEN properties->>'amount' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'amount')::numeric END) AS refunded\n  FROM events\n  WHERE event_name = 'order_refunded'\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '79 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n  GROUP BY 1\n),\norders AS (\n  SELECT\n    coalesce(e.properties->>'customer_id', e.user_id) AS customer_id,\n    e.properties->>'is_first_order' = 'true' AS is_first_order,\n    e.occurred_at AT TIME ZONE 'UTC' AS ts,\n    CASE WHEN e.properties->>'total' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (e.properties->>'total')::numeric END\n      - coalesce(CASE WHEN e.properties->>'cost_of_goods' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (e.properties->>'cost_of_goods')::numeric END, 0)\n      - coalesce(r.refunded, 0) AS amount\n  FROM events AS e\n  LEFT JOIN refunds AS r ON r.order_id = e.properties->>'order_id'\n  WHERE e.event_name = 'order_completed'\n    AND e.occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '79 weeks') AT TIME ZONE 'UTC'\n    AND e.occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n),\nfirst_orders AS (\n  SELECT customer_id, min(ts) AS first_at\n  FROM orders\n  WHERE is_first_order\n    AND customer_id IS NOT NULL\n    AND ts < date_trunc('week', now() AT TIME ZONE 'UTC') - interval '53 weeks'\n  GROUP BY customer_id\n),\ncohort AS (\n  SELECT date_trunc('week', f.first_at)::date AS week, f.customer_id, sum(o.amount) AS amount\n  FROM first_orders AS f\n  JOIN orders AS o\n    ON o.customer_id = f.customer_id\n   AND o.ts >= f.first_at\n   AND o.ts < f.first_at + interval '365 days'\n  GROUP BY 1, 2\n),\nspend AS (\n  SELECT date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week, sum(CASE WHEN properties->>'spend' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'spend')::numeric END) AS spend\n  FROM events\n  WHERE event_name = 'ad_spend'\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '79 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '53 weeks') AT TIME ZONE 'UTC'\n  GROUP BY 1\n),\nprofit AS (\n  SELECT week, sum(amount) AS gross_profit\n  FROM cohort\n  GROUP BY week\n),\ntotals AS (\n  SELECT w.week, coalesce(p.gross_profit, 0) AS gross_profit, coalesce(s.spend, 0) AS spend\n  FROM weeks AS w\n  LEFT JOIN profit AS p ON p.week = w.week\n  LEFT JOIN spend AS s ON s.week = w.week\n)\nSELECT week, gross_profit AS numerator, spend AS denominator, gross_profit / nullif(spend, 0) AS value\nFROM totals\nORDER BY week;","bigquery":"-- LTV to CAC: gross profit (order totals − cost of goods − refunds) from each first-order week's new customers over their first 365 days ÷ ad spend in that week. First-order weeks 79 to 54 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 365 days close.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 79 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 54 WEEK), INTERVAL 1 WEEK)) AS week\n),\nrefunds AS (\n  SELECT JSON_VALUE(properties, '$.order_id') AS order_id, SUM(SAFE_CAST(JSON_VALUE(properties, '$.amount') AS FLOAT64)) AS refunded\n  FROM events\n  WHERE event_name = 'order_refunded'\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 79 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY order_id\n),\norders AS (\n  SELECT\n    COALESCE(JSON_VALUE(e.properties, '$.customer_id'), e.user_id) AS customer_id,\n    JSON_VALUE(e.properties, '$.is_first_order') = 'true' AS is_first_order,\n    e.occurred_at,\n    SAFE_CAST(JSON_VALUE(e.properties, '$.total') AS FLOAT64)\n      - COALESCE(SAFE_CAST(JSON_VALUE(e.properties, '$.cost_of_goods') AS FLOAT64), 0)\n      - COALESCE(r.refunded, 0) AS amount\n  FROM events AS e\n  LEFT JOIN refunds AS r ON r.order_id = JSON_VALUE(e.properties, '$.order_id')\n  WHERE e.event_name = 'order_completed'\n    AND e.occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 79 WEEK))\n    AND e.occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n),\nfirst_orders AS (\n  SELECT customer_id, MIN(occurred_at) AS first_at\n  FROM orders\n  WHERE is_first_order\n    AND customer_id IS NOT NULL\n    AND occurred_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 53 WEEK))\n  GROUP BY customer_id\n),\ncohort AS (\n  SELECT DATE_TRUNC(DATE(f.first_at), ISOWEEK) AS week, f.customer_id, SUM(o.amount) AS amount\n  FROM first_orders AS f\n  JOIN orders AS o\n    ON o.customer_id = f.customer_id\n   AND o.occurred_at >= f.first_at\n   AND o.occurred_at < TIMESTAMP_ADD(f.first_at, INTERVAL 365 DAY)\n  GROUP BY week, f.customer_id\n),\nspend AS (\n  SELECT DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week, SUM(SAFE_CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64)) AS spend\n  FROM events\n  WHERE event_name = 'ad_spend'\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 79 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 53 WEEK))\n  GROUP BY week\n),\nprofit AS (\n  SELECT week, SUM(amount) AS gross_profit\n  FROM cohort\n  GROUP BY week\n),\ntotals AS (\n  SELECT w.week, COALESCE(p.gross_profit, 0) AS gross_profit, COALESCE(s.spend, 0) AS spend\n  FROM weeks AS w\n  LEFT JOIN profit AS p ON p.week = w.week\n  LEFT JOIN spend AS s ON s.week = w.week\n)\nSELECT week, gross_profit AS numerator, spend AS denominator, SAFE_DIVIDE(gross_profit, spend) AS value\nFROM totals\nORDER BY week;","snowflake":"-- LTV to CAC: gross profit (order totals − cost of goods − refunds) from each first-order week's new customers over their first 365 days ÷ ad spend in that week. First-order weeks 79 to 54 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 365 days close.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -53 - ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nrefunds AS (\n  SELECT properties:\"order_id\"::string AS order_id, SUM(TRY_TO_DOUBLE(properties:\"amount\"::string)) AS refunded\n  FROM events\n  WHERE event_name = 'order_refunded'\n    AND occurred_at >= DATEADD(week, -79, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n  GROUP BY 1\n),\norders AS (\n  SELECT\n    COALESCE(e.properties:\"customer_id\"::string, e.user_id) AS customer_id,\n    e.properties:\"is_first_order\"::string = 'true' AS is_first_order,\n    e.occurred_at,\n    TRY_TO_DOUBLE(e.properties:\"total\"::string)\n      - COALESCE(TRY_TO_DOUBLE(e.properties:\"cost_of_goods\"::string), 0)\n      - COALESCE(r.refunded, 0) AS amount\n  FROM events AS e\n  LEFT JOIN refunds AS r ON r.order_id = e.properties:\"order_id\"::string\n  WHERE e.event_name = 'order_completed'\n    AND e.occurred_at >= DATEADD(week, -79, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND e.occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n),\nfirst_orders AS (\n  SELECT customer_id, MIN(occurred_at) AS first_at\n  FROM orders\n  WHERE is_first_order\n    AND customer_id IS NOT NULL\n    AND occurred_at < DATEADD(week, -53, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n  GROUP BY customer_id\n),\ncohort AS (\n  SELECT DATEADD(day, 1 - DAYOFWEEKISO(f.first_at), f.first_at::date) AS week, f.customer_id, SUM(o.amount) AS amount\n  FROM first_orders AS f\n  JOIN orders AS o\n    ON o.customer_id = f.customer_id\n   AND o.occurred_at >= f.first_at\n   AND o.occurred_at < DATEADD(day, 365, f.first_at)\n  GROUP BY 1, 2\n),\nspend AS (\n  SELECT DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week, SUM(TRY_TO_DOUBLE(properties:\"spend\"::string)) AS spend\n  FROM events\n  WHERE event_name = 'ad_spend'\n    AND occurred_at >= DATEADD(week, -79, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(week, -53, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n  GROUP BY 1\n),\nprofit AS (\n  SELECT week, SUM(amount) AS gross_profit\n  FROM cohort\n  GROUP BY week\n),\ntotals AS (\n  SELECT w.week, COALESCE(p.gross_profit, 0) AS gross_profit, COALESCE(s.spend, 0) AS spend\n  FROM weeks AS w\n  LEFT JOIN profit AS p ON p.week = w.week\n  LEFT JOIN spend AS s ON s.week = w.week\n)\nSELECT week, gross_profit AS numerator, spend AS denominator, gross_profit / NULLIF(spend, 0) AS value\nFROM totals\nORDER BY week;"},"noise":{"type":"process","min_denominator":200,"volume_unit":"first-time customers in the cohort","typical":1.7},"example":{"business":"store","level":1.7,"volume":6800,"trend":-0.05},"drivers":[{"id":"spend-tracking","label":"Spend records","dropped":{"check":"Was spend double counted in the cohort week, such as a platform synced twice or a monthly invoice booked in one week?","yes":"Spend in the cohort week is far above the ad platforms' own reports for those days."},"spiked":{"check":"Did a channel's spend fail to sync for the cohort week?","yes":"One channel shows zero or partial spend on days it was running."}},{"id":"calendar","label":"Holiday cohorts","feed":"shopping","dropped":{"check":"Is this a Black Friday or holiday cohort, won at a peak price and reordering less?","yes":"The same cohort weeks last year show the same dip."},"spiked":{"check":"Is this a quiet-season cohort, won cheaply from returning visitors and organic search?","yes":"The same cohort weeks last year show the same rise."}},{"id":"cac","label":"Acquisition cost","metric":"ncac","dropped":{"check":"Did new customers cost more to win in the cohort week?","yes":"New customer CAC for that week sits above its usual range while 12-month value holds."},"spiked":{"check":"Did new customers cost less to win, from cheaper media or more organic buyers?","yes":"New customer CAC for that week sits below its usual range."}},{"id":"ltv","label":"12-month value","metric":"customer-lifetime-value","dropped":{"check":"Did the cohort spend less in its first year?","yes":"Customer lifetime value for the cohort falls while CAC holds."},"spiked":{"check":"Did the cohort spend more in its first year?","yes":"Customer lifetime value for the cohort rises while CAC holds."}},{"id":"margin","label":"Gross margin","metric":"gross-margin","dropped":{"check":"Did product costs rise or discounts deepen during the cohort's year?","yes":"Revenue per customer holds while gross margin on their orders falls."},"spiked":{"check":"Did a price rise or cheaper sourcing lift margin on the cohort's orders?","yes":"Gross margin on the cohort's orders runs above earlier cohorts."}},{"id":"channel-mix","label":"Channel mix","feed":"ad-platforms","dropped":{"check":"Did spend shift in the cohort week to a channel that wins lower-value buyers?","yes":"Spend share moved to one channel whose customers have a lower 12-month value."},"spiked":{"check":"Did spend shift toward channels whose customers are worth more?","yes":"Spend share moved to a channel whose customers have a higher 12-month value."}}],"diagnose_order":["spend-tracking","calendar","cac","ltv","margin","channel-mix"],"related":["customer-lifetime-value","ncac","blended-cac","cac-payback","gross-margin"],"prose":{"why_it_matters":"LTV to CAC asks whether acquisition pays: at 1.0 a cohort's first year of gross profit only just repays what it cost to win. SaaS investors look for 3 or more over a customer's lifetime; on 12 months of realized gross profit, healthy stores usually sit between 1.5 and 3. It checks growth in both directions: below 1 is growth bought too dear, and well above 3 often means the budget could be larger.","pitfalls":["Use gross profit, not revenue. A revenue ratio of 3 at a 40% margin is a gross-profit ratio of 1.2, which barely pays back.","Blended CAC divides all spend by all new customers and credits paid media with organic buyers, which flatters the ratio. Read paid-channel numbers before raising budgets.","Ratios built from projected lifetimes, such as ARPA × margin ÷ churn in SaaS, explode as churn nears zero. Cap the lifetime at 3 to 5 years, or use realized months as this spec does.","Spend booked in the wrong week, from monthly invoices or a failed sync, makes one cohort look free and the next ruinous. Check daily spend by channel before reading a jump.","Only cohorts whose 365 days have closed are reported, so this lags by a year. Steer today's acquisition with new customer CAC and second order rate."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "mau": { yaml: "id: mau\nname: Monthly active users\naliases:\n  - MAU\n  - Monthly active users (MAU)\n  - Monthly actives\n  - 28-day active users\nfamily: engagement\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: The number of distinct people active at least once in the 28 days ending this Sunday.\n  formula: Distinct people with any event in the 28 days ending Sunday 23:59 UTC\n\nevents:\n  - name: \"*\"\n    description: Any event a person sends. Activity, not one specific action; the same definition as DAU and WAU.\n    also_called: [All events, Any event, Active event]\n    properties:\n      - name: $os\n        description: The operating system, for splitting by platform.\n\nnumerator:\n  label: Distinct active people in 28 days\n  aggregate: unique_users\n  event: \"*\"\n\nqueries:\n  hogql: |-\n    -- Monthly active users per week: distinct people with any event in the four weeks (28 days) ending that Sunday. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT w.week AS week, coalesce(m.people, 0) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, count(DISTINCT person_id) AS people\n      FROM (\n        SELECT person_id, active_week + toIntervalWeek(arrayJoin([0, 1, 2, 3])) AS week\n        FROM (\n          SELECT DISTINCT person_id, toMonday(toTimeZone(timestamp, 'UTC')) AS active_week\n          FROM events\n          WHERE person_id IS NOT NULL\n            AND timestamp >= now() - toIntervalWeek(30)\n            AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(29) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n        )\n      )\n      WHERE week BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n      GROUP BY week\n    ) AS m ON m.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Monthly active users per week: distinct people with any event in the four weeks (28 days) ending that Sunday. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    active AS (\n      SELECT DISTINCT user_id, date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS active_week\n      FROM events\n      WHERE user_id IS NOT NULL\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '29 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n    ),\n    monthly AS (\n      SELECT w.week, count(DISTINCT a.user_id) AS people\n      FROM weeks AS w\n      JOIN active AS a ON a.active_week BETWEEN w.week - 21 AND w.week\n      GROUP BY w.week\n    )\n    SELECT w.week, coalesce(m.people, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN monthly AS m ON m.week = w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Monthly active users per week: distinct people with any event in the four weeks (28 days) ending that Sunday. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    active AS (\n      SELECT DISTINCT user_id, DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS active_week\n      FROM events\n      WHERE user_id IS NOT NULL\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 29 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    ),\n    monthly AS (\n      SELECT w.week, COUNT(DISTINCT a.user_id) AS people\n      FROM weeks AS w\n      JOIN active AS a ON a.active_week BETWEEN DATE_SUB(w.week, INTERVAL 3 WEEK) AND w.week\n      GROUP BY w.week\n    )\n    SELECT w.week, COALESCE(m.people, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN monthly AS m ON m.week = w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Monthly active users per week: distinct people with any event in the four weeks (28 days) ending that Sunday. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    active AS (\n      SELECT DISTINCT user_id, DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS active_week\n      FROM events\n      WHERE user_id IS NOT NULL\n        AND occurred_at >= DATEADD(week, -29, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n    ),\n    monthly AS (\n      SELECT w.week, COUNT(DISTINCT a.user_id) AS people\n      FROM weeks AS w\n      JOIN active AS a ON a.active_week BETWEEN DATEADD(week, -3, w.week) AND w.week\n      GROUP BY w.week\n    )\n    SELECT w.week, COALESCE(m.people, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN monthly AS m ON m.week = w.week\n    ORDER BY w.week;\n\nnoise:\n  type: process\n  min_denominator: 100\n  volume_unit: monthly active users\n  typical: 120000\n\nexample:\n  business: app\n  level: 120000\n  volume: 120000\n  trend: 0.15\n\ndrivers:\n  - id: tracking\n    label: Tracking and identity\n    dropped:\n      check: Did an SDK update, consent change or identity merge reduce the people counted?\n      yes: MAU falls on one platform or app version from one date, or falls the week duplicate ids were merged.\n    spiked:\n      check: Did bots, duplicated ids or a newly tracked surface, such as logged-out web pages, add people?\n      yes: The new actives have one or two events each and come from one platform, page or user agent.\n  - id: window\n    label: The 28-day window\n    dropped:\n      check: Did an unusually large week, from a launch or campaign, just leave the 28-day window?\n      yes: MAU falls exactly four weeks after a spike in new people, with no change in this week's activity.\n    spiked:\n      check: Did an unusually weak week, from an outage or holiday, just leave the window?\n      yes: MAU rises four weeks after a dip, with no change in this week's activity.\n  - id: calendar\n    label: Calendar\n    feed: holidays\n    dropped:\n      check: Does the window cover a holiday period when people use the product less?\n      yes: The same four weeks last year show the same dip.\n    spiked:\n      check: Does the window cover a seasonal high for the product?\n      yes: The same four weeks last year show the same rise.\n  - id: new-users\n    label: New users\n    metric: signups\n    dropped:\n      check: Did fewer new people arrive over the last four weeks?\n      yes: Sign-ups fell in the weeks inside the window by about as many as MAU did.\n    spiked:\n      check: Did a launch or campaign bring a wave of new people in the last four weeks?\n      yes: Sign-ups inside the window explain the rise; stickiness falls if they used it once.\n  - id: retention\n    label: Retention of recent cohorts\n    metric: week-4-retention\n    dropped:\n      check: Are recent cohorts staying active for fewer weeks?\n      yes: Week 4 retention of recent cohorts falls, so fewer of last month's newcomers are still counted.\n    spiked:\n      check: Are recent cohorts staying longer?\n      yes: Week 4 retention of recent cohorts rises.\n  - id: resurrected\n    label: Resurrected users\n    metric: resurrected-users\n    dropped:\n      check: Did fewer lapsed people come back over the last four weeks?\n      yes: Resurrected users are below their usual range for the weeks inside the window.\n    spiked:\n      check: Did a win-back campaign bring lapsed people back?\n      yes: Resurrected users explain most of the rise.\n\ndiagnose_order: [tracking, window, calendar, new-users, retention, resurrected]\n\nrelated: [dau, wau, stickiness, week-4-retention, resurrected-users]\n\nprose:\n  why_it_matters: >-\n    MAU is the size of the audience a product reaches in a month, and the base every engagement\n    ratio divides by. Each week's figure shares three of its four weeks with the week before, so\n    it moves slowly, and a drop usually started up to four weeks ago. A fixed 28-day window keeps\n    every month the same length, so February doesn't look like a decline.\n  pitfalls:\n    - Calendar months run 28 to 31 days, which moves MAU by several percent on length alone. A fixed 28-day window removes that.\n    - Consecutive weeks share three weeks of activity, so MAU looks smoother than the business is. Read WAU and new users to see what changed this week.\n    - One push or email blast can add tens of thousands of people who open once. They inflate MAU for four weeks and drag stickiness down.\n    - Logged-out visitors and signed-in people counted together double count anyone who signs in during the window.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"mau","name":"Monthly active users","aliases":["MAU","Monthly active users (MAU)","Monthly actives","28-day active users"],"family":"engagement","kind":"count","polarity":"up-is-good","definition":{"one_line":"The number of distinct people active at least once in the 28 days ending this Sunday.","formula":"Distinct people with any event in the 28 days ending Sunday 23:59 UTC"},"events":[{"name":"*","description":"Any event a person sends. Activity, not one specific action; the same definition as DAU and WAU.","also_called":["All events","Any event","Active event"],"properties":[{"name":"$os","description":"The operating system, for splitting by platform."}]}],"numerator":{"label":"Distinct active people in 28 days","aggregate":"unique_users","event":"*"},"queries":{"hogql":"-- Monthly active users per week: distinct people with any event in the four weeks (28 days) ending that Sunday. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT w.week AS week, coalesce(m.people, 0) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, count(DISTINCT person_id) AS people\n  FROM (\n    SELECT person_id, active_week + toIntervalWeek(arrayJoin([0, 1, 2, 3])) AS week\n    FROM (\n      SELECT DISTINCT person_id, toMonday(toTimeZone(timestamp, 'UTC')) AS active_week\n      FROM events\n      WHERE person_id IS NOT NULL\n        AND timestamp >= now() - toIntervalWeek(30)\n        AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(29) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n    )\n  )\n  WHERE week BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n  GROUP BY week\n) AS m ON m.week = w.week\nORDER BY week","postgres":"-- Monthly active users per week: distinct people with any event in the four weeks (28 days) ending that Sunday. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nactive AS (\n  SELECT DISTINCT user_id, date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS active_week\n  FROM events\n  WHERE user_id IS NOT NULL\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '29 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n),\nmonthly AS (\n  SELECT w.week, count(DISTINCT a.user_id) AS people\n  FROM weeks AS w\n  JOIN active AS a ON a.active_week BETWEEN w.week - 21 AND w.week\n  GROUP BY w.week\n)\nSELECT w.week, coalesce(m.people, 0) AS value\nFROM weeks AS w\nLEFT JOIN monthly AS m ON m.week = w.week\nORDER BY w.week;","bigquery":"-- Monthly active users per week: distinct people with any event in the four weeks (28 days) ending that Sunday. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nactive AS (\n  SELECT DISTINCT user_id, DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS active_week\n  FROM events\n  WHERE user_id IS NOT NULL\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 29 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n),\nmonthly AS (\n  SELECT w.week, COUNT(DISTINCT a.user_id) AS people\n  FROM weeks AS w\n  JOIN active AS a ON a.active_week BETWEEN DATE_SUB(w.week, INTERVAL 3 WEEK) AND w.week\n  GROUP BY w.week\n)\nSELECT w.week, COALESCE(m.people, 0) AS value\nFROM weeks AS w\nLEFT JOIN monthly AS m ON m.week = w.week\nORDER BY w.week;","snowflake":"-- Monthly active users per week: distinct people with any event in the four weeks (28 days) ending that Sunday. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nactive AS (\n  SELECT DISTINCT user_id, DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS active_week\n  FROM events\n  WHERE user_id IS NOT NULL\n    AND occurred_at >= DATEADD(week, -29, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n),\nmonthly AS (\n  SELECT w.week, COUNT(DISTINCT a.user_id) AS people\n  FROM weeks AS w\n  JOIN active AS a ON a.active_week BETWEEN DATEADD(week, -3, w.week) AND w.week\n  GROUP BY w.week\n)\nSELECT w.week, COALESCE(m.people, 0) AS value\nFROM weeks AS w\nLEFT JOIN monthly AS m ON m.week = w.week\nORDER BY w.week;"},"noise":{"type":"process","min_denominator":100,"volume_unit":"monthly active users","typical":120000},"example":{"business":"app","level":120000,"volume":120000,"trend":0.15},"drivers":[{"id":"tracking","label":"Tracking and identity","dropped":{"check":"Did an SDK update, consent change or identity merge reduce the people counted?","yes":"MAU falls on one platform or app version from one date, or falls the week duplicate ids were merged."},"spiked":{"check":"Did bots, duplicated ids or a newly tracked surface, such as logged-out web pages, add people?","yes":"The new actives have one or two events each and come from one platform, page or user agent."}},{"id":"window","label":"The 28-day window","dropped":{"check":"Did an unusually large week, from a launch or campaign, just leave the 28-day window?","yes":"MAU falls exactly four weeks after a spike in new people, with no change in this week's activity."},"spiked":{"check":"Did an unusually weak week, from an outage or holiday, just leave the window?","yes":"MAU rises four weeks after a dip, with no change in this week's activity."}},{"id":"calendar","label":"Calendar","feed":"holidays","dropped":{"check":"Does the window cover a holiday period when people use the product less?","yes":"The same four weeks last year show the same dip."},"spiked":{"check":"Does the window cover a seasonal high for the product?","yes":"The same four weeks last year show the same rise."}},{"id":"new-users","label":"New users","metric":"signups","dropped":{"check":"Did fewer new people arrive over the last four weeks?","yes":"Sign-ups fell in the weeks inside the window by about as many as MAU did."},"spiked":{"check":"Did a launch or campaign bring a wave of new people in the last four weeks?","yes":"Sign-ups inside the window explain the rise; stickiness falls if they used it once."}},{"id":"retention","label":"Retention of recent cohorts","metric":"week-4-retention","dropped":{"check":"Are recent cohorts staying active for fewer weeks?","yes":"Week 4 retention of recent cohorts falls, so fewer of last month's newcomers are still counted."},"spiked":{"check":"Are recent cohorts staying longer?","yes":"Week 4 retention of recent cohorts rises."}},{"id":"resurrected","label":"Resurrected users","metric":"resurrected-users","dropped":{"check":"Did fewer lapsed people come back over the last four weeks?","yes":"Resurrected users are below their usual range for the weeks inside the window."},"spiked":{"check":"Did a win-back campaign bring lapsed people back?","yes":"Resurrected users explain most of the rise."}}],"diagnose_order":["tracking","window","calendar","new-users","retention","resurrected"],"related":["dau","wau","stickiness","week-4-retention","resurrected-users"],"prose":{"why_it_matters":"MAU is the size of the audience a product reaches in a month, and the base every engagement ratio divides by. Each week's figure shares three of its four weeks with the week before, so it moves slowly, and a drop usually started up to four weeks ago. A fixed 28-day window keeps every month the same length, so February doesn't look like a decline.","pitfalls":["Calendar months run 28 to 31 days, which moves MAU by several percent on length alone. A fixed 28-day window removes that.","Consecutive weeks share three weeks of activity, so MAU looks smoother than the business is. Read WAU and new users to see what changed this week.","One push or email blast can add tens of thousands of people who open once. They inflate MAU for four weeks and drag stickiness down.","Logged-out visitors and signed-in people counted together double count anyone who signs in during the window."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "mer": { yaml: "id: mer\nname: Marketing efficiency ratio\naliases:\n  - Blended ROAS\n  - Media efficiency ratio\n  - Total ROAS\nfamily: acquisition\ncatalog_id: mer\nkind: ratio\npolarity: up-is-good\n\ndefinition:\n  one_line: All net revenue in the week for each dollar of ad spend, with no attribution to any channel.\n  formula: (Order revenue − refunds) ÷ ad spend, both by the week they happened\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n  - name: order_refunded\n    description: A refund issued against an earlier order, full or partial.\n    also_called: [refund, Order Refunded]\n    properties:\n      - name: amount\n        description: The refunded amount, excluding tax and shipping.\n  - name: ad_spend\n    description: One row per channel per day, synced from each ad platform's reporting API.\n    also_called: [Ad Spend, ad_performance, campaign_daily_stats]\n    properties:\n      - name: spend\n        description: Amount spent that day, in the store's reporting currency.\n\nnumerator:\n  label: Order revenue\n  aggregate: sum\n  event: order_completed\n  property: total\nsubtract:\n  label: Refunds issued\n  aggregate: sum\n  event: order_refunded\n  property: amount\ndenominator:\n  label: Ad spend\n  aggregate: sum\n  event: ad_spend\n  property: spend\n\nnoise:\n  type: process\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 3.5\n\nexample:\n  business: store\n  level: 4.3\n  volume: 13000\n  trend: -0.04\n\ndrivers:\n  - id: spend-sync\n    label: Spend sync\n    dropped:\n      check: Is a day of spend synced twice, or a currency recorded at the wrong rate?\n      yes: One channel's spend doubles for a day or jumps by an exchange rate, and MER falls by the same share.\n    spiked:\n      check: Is a channel's spend missing for some days?\n      yes: One channel shows zero or partial spend while its own dashboard shows the usual amount.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Did budgets rise ahead of an event before the revenue arrived, or did a sale end?\n      yes: The same weeks last year show the same dip once aligned on the event.\n    spiked:\n      check: Is this a sale, holiday or payday week, when demand rises faster than spend?\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: spend\n    label: Ad spend\n    metric: ad-spend\n    feed: ad-platforms\n    dropped:\n      check: Did spend rise faster than revenue?\n      yes: Spend rises more than revenue does; the extra budget is buying less than the average.\n    spiked:\n      check: Did spend fall while revenue held?\n      yes: Spend falls and revenue barely moves, so some of that spend was buying sales that would have happened anyway.\n  - id: revenue\n    label: Net revenue\n    metric: net-revenue\n    dropped:\n      check: Did revenue fall at steady spend, from conversion, stock, pricing or refunds?\n      yes: Revenue falls while spend holds; the revenue driver tree says which part moved.\n    spiked:\n      check: Did revenue rise at steady spend, from a launch, a press mention or a price rise?\n      yes: Revenue rises while spend holds, usually through organic, direct or email traffic.\n  - id: returning-demand\n    label: Returning customers\n    metric: repeat-order-share\n    dropped:\n      check: Did returning customers, who cost little to bring back, order less?\n      yes: Repeat orders fall while first orders hold.\n    spiked:\n      check: Did a restock, a launch or an email bring returning customers back in numbers?\n      yes: Repeat orders jump while first orders and spend hold.\n\ndiagnose_order: [spend-sync, calendar, spend, revenue, returning-demand]\n\nrelated: [roas, ad-spend, net-revenue, ncac, contribution-margin]\n\nprose:\n  why_it_matters: >-\n    MER is the one efficiency number no ad platform can inflate: total revenue over total\n    spend, with no attribution model in between. Platform ROAS can say every channel is\n    profitable while MER falls; when they disagree, MER is right about the business. A store at\n    a MER of 4.3 with a 60% gross margin makes $2.58 of gross margin per ad dollar, or $1.58\n    after paying for the ad, before any other cost.\n  pitfalls:\n    - MER credits ads with revenue they didn't cause, such as repeat customers, email and word of mouth. A store with a loyal base can show a high MER while new-customer acquisition loses money; read nCAC next to it.\n    - Revenue and spend both follow the calendar, but not in step. Budgets often rise before a sale and revenue lands after it, so compare weeks with the same week last year, not the week before.\n    - Ad spend here is media only. Agency fees, creative and tools make the real ratio lower.\n    - Gross revenue and net revenue give different ratios. This spec uses revenue after discounts and refunds, before tax and shipping, the same as net revenue.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"mer","name":"Marketing efficiency ratio","aliases":["Blended ROAS","Media efficiency ratio","Total ROAS"],"family":"acquisition","catalog_id":"mer","kind":"ratio","polarity":"up-is-good","definition":{"one_line":"All net revenue in the week for each dollar of ad spend, with no attribution to any channel.","formula":"(Order revenue − refunds) ÷ ad spend, both by the week they happened"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."}]},{"name":"order_refunded","description":"A refund issued against an earlier order, full or partial.","also_called":["refund","Order Refunded"],"properties":[{"name":"amount","description":"The refunded amount, excluding tax and shipping."}]},{"name":"ad_spend","description":"One row per channel per day, synced from each ad platform's reporting API.","also_called":["Ad Spend","ad_performance","campaign_daily_stats"],"properties":[{"name":"spend","description":"Amount spent that day, in the store's reporting currency."}]}],"numerator":{"label":"Order revenue","aggregate":"sum","event":"order_completed","property":"total"},"subtract":{"label":"Refunds issued","aggregate":"sum","event":"order_refunded","property":"amount"},"denominator":{"label":"Ad spend","aggregate":"sum","event":"ad_spend","property":"spend"},"noise":{"type":"process","min_denominator":50,"volume_unit":"orders a week","typical":3.5},"example":{"business":"store","level":4.3,"volume":13000,"trend":-0.04},"drivers":[{"id":"spend-sync","label":"Spend sync","dropped":{"check":"Is a day of spend synced twice, or a currency recorded at the wrong rate?","yes":"One channel's spend doubles for a day or jumps by an exchange rate, and MER falls by the same share."},"spiked":{"check":"Is a channel's spend missing for some days?","yes":"One channel shows zero or partial spend while its own dashboard shows the usual amount."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Did budgets rise ahead of an event before the revenue arrived, or did a sale end?","yes":"The same weeks last year show the same dip once aligned on the event."},"spiked":{"check":"Is this a sale, holiday or payday week, when demand rises faster than spend?","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"spend","label":"Ad spend","metric":"ad-spend","feed":"ad-platforms","dropped":{"check":"Did spend rise faster than revenue?","yes":"Spend rises more than revenue does; the extra budget is buying less than the average."},"spiked":{"check":"Did spend fall while revenue held?","yes":"Spend falls and revenue barely moves, so some of that spend was buying sales that would have happened anyway."}},{"id":"revenue","label":"Net revenue","metric":"net-revenue","dropped":{"check":"Did revenue fall at steady spend, from conversion, stock, pricing or refunds?","yes":"Revenue falls while spend holds; the revenue driver tree says which part moved."},"spiked":{"check":"Did revenue rise at steady spend, from a launch, a press mention or a price rise?","yes":"Revenue rises while spend holds, usually through organic, direct or email traffic."}},{"id":"returning-demand","label":"Returning customers","metric":"repeat-order-share","dropped":{"check":"Did returning customers, who cost little to bring back, order less?","yes":"Repeat orders fall while first orders hold."},"spiked":{"check":"Did a restock, a launch or an email bring returning customers back in numbers?","yes":"Repeat orders jump while first orders and spend hold."}}],"diagnose_order":["spend-sync","calendar","spend","revenue","returning-demand"],"related":["roas","ad-spend","net-revenue","ncac","contribution-margin"],"prose":{"why_it_matters":"MER is the one efficiency number no ad platform can inflate: total revenue over total spend, with no attribution model in between. Platform ROAS can say every channel is profitable while MER falls; when they disagree, MER is right about the business. A store at a MER of 4.3 with a 60% gross margin makes $2.58 of gross margin per ad dollar, or $1.58 after paying for the ad, before any other cost.","pitfalls":["MER credits ads with revenue they didn't cause, such as repeat customers, email and word of mouth. A store with a loyal base can show a high MER while new-customer acquisition loses money; read nCAC next to it.","Revenue and spend both follow the calendar, but not in step. Budgets often rise before a sale and revenue lands after it, so compare weeks with the same week last year, not the week before.","Ad spend here is media only. Agency fees, creative and tools make the real ratio lower.","Gross revenue and net revenue give different ratios. This spec uses revenue after discounts and refunds, before tax and shipping, the same as net revenue."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "mobile-conversion-rate": { yaml: "id: mobile-conversion-rate\nname: Mobile conversion rate\naliases:\n  - Mobile ecommerce conversion rate\n  - Mobile store conversion rate\n  - Mobile CVR\nfamily: conversion\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of sessions on phones that end in a paid order. Tablets are left out, as GA4 reports them separately.\n  formula: Mobile sessions with a paid order ÷ mobile sessions\n\nevents:\n  - name: $pageview\n    description: A page loaded in the browser. Sessions are the distinct session ids across page views.\n    also_called: [page_view, Page Viewed, page_viewed]\n    properties:\n      - name: $session_id\n        description: The browser session; a new one starts after 30 minutes without activity.\n      - name: $device_type\n        description: Mobile, Desktop or Tablet, from the browser's user agent.\n  - name: order_completed\n    description: A paid order confirmed by the server, carrying the browser's session id and device type.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n      - name: $device_type\n        description: The device the order was placed on, copied from the browser session.\n\nnumerator:\n  label: Mobile sessions with a paid order\n  aggregate: unique_sessions\n  event: order_completed\n  where:\n    - property: $device_type\n      op: eq\n      value: Mobile\ndenominator:\n  label: Mobile sessions\n  aggregate: unique_sessions\n  event: $pageview\n  where:\n    - property: $device_type\n      op: eq\n      value: Mobile\n\nnoise:\n  type: binomial\n  min_denominator: 2000\n  volume_unit: mobile sessions a week\n  typical: 0.016\n  reference_volumes: [2000, 10000, 50000, 250000]\n\nexample:\n  business: store\n  level: 0.0204\n  volume: 408000\n  trend: 0.04\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Are orders losing their device type or session id, for example after moving the order event to the server?\n      yes: Orders with no device type rise while mobile orders fall by about as much.\n    spiked:\n      check: Did mobile page views stop recording somewhere, or did tablets start reporting as mobile?\n      yes: Mobile sessions fall with no matching fall in mobile ad clicks, or tablet sessions drop to near zero.\n  - id: os-and-browsers\n    label: iOS, Android and browser releases\n    breakdown: $os\n    feed: app-stores\n    dropped:\n      check: Did an iOS, Android, Safari or Chrome release this week break a payment sheet, autofill or a script?\n      yes: The drop concentrates on one operating system or browser version, from its release date.\n    spiked:\n      check: Did a platform update or your own fix clear a problem from an earlier release?\n      yes: The affected system returns to its usual rate and the others never moved.\n  - id: mobile-release\n    label: Mobile site release\n    dropped:\n      check: Did a release change the mobile product page, menu, sticky add-to-cart bar or checkout layout?\n      yes: The drop starts on the release day and desktop conversion holds.\n    spiked:\n      check: Did a mobile release or test ship, and is it on for everyone?\n      yes: The rise starts on the release day; confirm it isn't a tracking change before crediting it.\n  - id: traffic-mix\n    label: Social and in-app traffic\n    breakdown: utm_source\n    dropped:\n      check: Did more mobile traffic come from social ads that open in Instagram or TikTok's in-app browser?\n      yes: Sessions from one social source grow, and those sessions convert at a fraction of the mobile web.\n    spiked:\n      check: Did a social campaign pause, or did email and branded search take a larger share of mobile visits?\n      yes: Each source's own rate holds and only the mix moved.\n  - id: wallets\n    label: Wallets and payment sheets\n    feed: stripe\n    dropped:\n      check: Did Apple Pay, Google Pay or Shop Pay drop out of mobile checkout or start failing?\n      yes: Wallet payments on mobile fall while card payments hold.\n    spiked:\n      check: Did a wallet button launch on product pages or in the cart?\n      yes: Wallet orders rise from the launch day and mobile checkouts get shorter.\n\ndiagnose_order: [tracking, os-and-browsers, mobile-release, traffic-mix, wallets]\n\nrelated: [conversion-rate, mobile-session-share, checkout-conversion, payment-success-rate, bounce-rate]\n\nprose:\n  why_it_matters: >-\n    Phones bring about two thirds of store sessions but convert well below desktop; at\n    Northwind, 1.9% against 2.9%. Mobile is where a store loses the most orders to small things,\n    such as a hidden button, a slow page or a payment sheet that doesn't open. Closing a fifth\n    of the gap on 408,000 mobile sessions a week is about 800 orders.\n  pitfalls:\n    - Orders sent from the server carry no device type, so mobile conversion reads near zero. Copy the device type and session id from the browser onto the order event.\n    - Tablets convert closer to desktop than to phones. This spec leaves them out; including them reads higher and isn't comparable.\n    - In-app browsers from Instagram and TikTok count as mobile sessions but convert far below the mobile web, so a social campaign lowers the rate without anything breaking.\n    - A shopper who browses on a phone and buys on a laptop counts as a lost mobile session and a desktop order. Read mobile conversion for change over time, not as what mobile is worth.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"mobile-conversion-rate","name":"Mobile conversion rate","aliases":["Mobile ecommerce conversion rate","Mobile store conversion rate","Mobile CVR"],"family":"conversion","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of sessions on phones that end in a paid order. Tablets are left out, as GA4 reports them separately.","formula":"Mobile sessions with a paid order ÷ mobile sessions"},"events":[{"name":"$pageview","description":"A page loaded in the browser. Sessions are the distinct session ids across page views.","also_called":["page_view","Page Viewed","page_viewed"],"properties":[{"name":"$session_id","description":"The browser session; a new one starts after 30 minutes without activity."},{"name":"$device_type","description":"Mobile, Desktop or Tablet, from the browser's user agent."}]},{"name":"order_completed","description":"A paid order confirmed by the server, carrying the browser's session id and device type.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."},{"name":"$device_type","description":"The device the order was placed on, copied from the browser session."}]}],"numerator":{"label":"Mobile sessions with a paid order","aggregate":"unique_sessions","event":"order_completed","where":[{"property":"$device_type","op":"eq","value":"Mobile"}]},"denominator":{"label":"Mobile sessions","aggregate":"unique_sessions","event":"$pageview","where":[{"property":"$device_type","op":"eq","value":"Mobile"}]},"noise":{"type":"binomial","min_denominator":2000,"volume_unit":"mobile sessions a week","typical":0.016,"reference_volumes":[2000,10000,50000,250000]},"example":{"business":"store","level":0.0204,"volume":408000,"trend":0.04,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Are orders losing their device type or session id, for example after moving the order event to the server?","yes":"Orders with no device type rise while mobile orders fall by about as much."},"spiked":{"check":"Did mobile page views stop recording somewhere, or did tablets start reporting as mobile?","yes":"Mobile sessions fall with no matching fall in mobile ad clicks, or tablet sessions drop to near zero."}},{"id":"os-and-browsers","label":"iOS, Android and browser releases","breakdown":"$os","feed":"app-stores","dropped":{"check":"Did an iOS, Android, Safari or Chrome release this week break a payment sheet, autofill or a script?","yes":"The drop concentrates on one operating system or browser version, from its release date."},"spiked":{"check":"Did a platform update or your own fix clear a problem from an earlier release?","yes":"The affected system returns to its usual rate and the others never moved."}},{"id":"mobile-release","label":"Mobile site release","dropped":{"check":"Did a release change the mobile product page, menu, sticky add-to-cart bar or checkout layout?","yes":"The drop starts on the release day and desktop conversion holds."},"spiked":{"check":"Did a mobile release or test ship, and is it on for everyone?","yes":"The rise starts on the release day; confirm it isn't a tracking change before crediting it."}},{"id":"traffic-mix","label":"Social and in-app traffic","breakdown":"utm_source","dropped":{"check":"Did more mobile traffic come from social ads that open in Instagram or TikTok's in-app browser?","yes":"Sessions from one social source grow, and those sessions convert at a fraction of the mobile web."},"spiked":{"check":"Did a social campaign pause, or did email and branded search take a larger share of mobile visits?","yes":"Each source's own rate holds and only the mix moved."}},{"id":"wallets","label":"Wallets and payment sheets","feed":"stripe","dropped":{"check":"Did Apple Pay, Google Pay or Shop Pay drop out of mobile checkout or start failing?","yes":"Wallet payments on mobile fall while card payments hold."},"spiked":{"check":"Did a wallet button launch on product pages or in the cart?","yes":"Wallet orders rise from the launch day and mobile checkouts get shorter."}}],"diagnose_order":["tracking","os-and-browsers","mobile-release","traffic-mix","wallets"],"related":["conversion-rate","mobile-session-share","checkout-conversion","payment-success-rate","bounce-rate"],"prose":{"why_it_matters":"Phones bring about two thirds of store sessions but convert well below desktop; at Northwind, 1.9% against 2.9%. Mobile is where a store loses the most orders to small things, such as a hidden button, a slow page or a payment sheet that doesn't open. Closing a fifth of the gap on 408,000 mobile sessions a week is about 800 orders.","pitfalls":["Orders sent from the server carry no device type, so mobile conversion reads near zero. Copy the device type and session id from the browser onto the order event.","Tablets convert closer to desktop than to phones. This spec leaves them out; including them reads higher and isn't comparable.","In-app browsers from Instagram and TikTok count as mobile sessions but convert far below the mobile web, so a social campaign lowers the rate without anything breaking.","A shopper who browses on a phone and buys on a laptop counts as a lost mobile session and a desktop order. Read mobile conversion for change over time, not as what mobile is worth."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "mobile-session-share": { yaml: "id: mobile-session-share\nname: Mobile session share\naliases:\n  - Mobile traffic share\n  - Mobile share of traffic\n  - Mobile traffic percentage\n  - Mobile sessions\nfamily: traffic\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of the week's sessions that happened on a phone, not counting tablets.\n  formula: Sessions on a mobile device ÷ all sessions\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change, captured in the browser.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: $device_type\n        description: Mobile, Desktop or Tablet, parsed from the user agent.\n      - name: $session_id\n        description: Set by the analytics SDK; ties the page view to a visit.\n      - name: utm_source\n        description: The campaign source from the landing URL (google, facebook, tiktok).\n\nnumerator:\n  label: Mobile sessions\n  aggregate: unique_sessions\n  event: $pageview\n  where:\n    - property: $device_type\n      op: eq\n      value: Mobile\ndenominator:\n  label: Sessions\n  aggregate: unique_sessions\n  event: $pageview\n\nnoise:\n  type: binomial\n  min_denominator: 200\n  volume_unit: sessions a week\n  typical: 0.7\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: app\n  level: 0.78\n  volume: 150000\n  trend: 0.02\n\ndrivers:\n  - id: tracking\n    label: Device detection and bots\n    breakdown: $browser\n    dropped:\n      check: Is a desktop bot or crawler adding sessions, or did a user-agent change reclassify phones?\n      yes: Desktop sessions jump from one browser or data-centre network that never orders.\n    spiked:\n      check: Did an in-app browser, a tracking fix or a mobile bot start counting more phone sessions?\n      yes: Mobile sessions rise from one browser or app webview while orders hold.\n  - id: calendar\n    label: Calendar\n    feed: holidays\n    dropped:\n      check: Did a holiday or long weekend end, sending people back to desks?\n      yes: The same weeks last year show the same shift back to desktop.\n    spiked:\n      check: Is this a holiday or vacation week, when people browse from phones?\n      yes: The same week last year shows the same rise in mobile share.\n  - id: paid-social\n    label: Paid social\n    metric: paid-sessions\n    breakdown: utm_source\n    dropped:\n      check: Did paid social spend, which is almost all mobile, fall or pause?\n      yes: Sessions from Meta, TikTok or Snap fall and the mobile share falls with them.\n    spiked:\n      check: Did a paid social campaign or creator push start?\n      yes: Sessions from a social source jump and nearly all of them are on phones.\n  - id: email-and-sms\n    label: Email and SMS sends\n    breakdown: utm_medium\n    dropped:\n      check: Did fewer email or SMS sends go out this week?\n      yes: Email and SMS sessions, mostly on phones, fall by enough to explain the shift.\n    spiked:\n      check: Did a big email or SMS campaign go out?\n      yes: Sessions tagged email or sms jump on the send days, mostly on phones.\n  - id: desktop-sources\n    label: Desktop-heavy sources\n    metric: organic-sessions\n    dropped:\n      check: Did search, B2B or work-hours traffic, which skews desktop, grow?\n      yes: Desktop sessions rise from search or one referrer while mobile holds.\n    spiked:\n      check: Did desktop-heavy sources such as search or a partner site shrink?\n      yes: Desktop sessions fall from one source while mobile holds.\n\ndiagnose_order: [tracking, calendar, paid-social, email-and-sms, desktop-sources]\n\nrelated: [sessions, mobile-conversion-rate, conversion-rate, bounce-rate, paid-sessions]\n\nprose:\n  why_it_matters: >-\n    Phones bring most store visits but convert at about half the desktop rate, so the device\n    mix moves store conversion with no change to the site. When mobile share rises from 70% to\n    75%, a store converting 1.8% on mobile and 3.6% on desktop loses about 0.09 points of\n    conversion from the mix alone. Check this before blaming checkout.\n  pitfalls:\n    - Tablets are not mobile here. Tools that fold tablets into mobile read 3 to 8 points higher.\n    - Device type comes from the user agent. Browser changes such as reduced user-agent strings and in-app webviews can move sessions between devices without anyone changing what they use.\n    - The share can rise because desktop fell. Read it with mobile and desktop session counts side by side.\n    - Bots usually announce a desktop user agent, so a bot wave lowers mobile share. Rule that out before reading a falling share as a change in shoppers.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"mobile-session-share","name":"Mobile session share","aliases":["Mobile traffic share","Mobile share of traffic","Mobile traffic percentage","Mobile sessions"],"family":"traffic","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of the week's sessions that happened on a phone, not counting tablets.","formula":"Sessions on a mobile device ÷ all sessions"},"events":[{"name":"$pageview","description":"One page load or client-side route change, captured in the browser.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"$device_type","description":"Mobile, Desktop or Tablet, parsed from the user agent."},{"name":"$session_id","description":"Set by the analytics SDK; ties the page view to a visit."},{"name":"utm_source","description":"The campaign source from the landing URL (google, facebook, tiktok)."}]}],"numerator":{"label":"Mobile sessions","aggregate":"unique_sessions","event":"$pageview","where":[{"property":"$device_type","op":"eq","value":"Mobile"}]},"denominator":{"label":"Sessions","aggregate":"unique_sessions","event":"$pageview"},"noise":{"type":"binomial","min_denominator":200,"volume_unit":"sessions a week","typical":0.7,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"app","level":0.78,"volume":150000,"trend":0.02},"drivers":[{"id":"tracking","label":"Device detection and bots","breakdown":"$browser","dropped":{"check":"Is a desktop bot or crawler adding sessions, or did a user-agent change reclassify phones?","yes":"Desktop sessions jump from one browser or data-centre network that never orders."},"spiked":{"check":"Did an in-app browser, a tracking fix or a mobile bot start counting more phone sessions?","yes":"Mobile sessions rise from one browser or app webview while orders hold."}},{"id":"calendar","label":"Calendar","feed":"holidays","dropped":{"check":"Did a holiday or long weekend end, sending people back to desks?","yes":"The same weeks last year show the same shift back to desktop."},"spiked":{"check":"Is this a holiday or vacation week, when people browse from phones?","yes":"The same week last year shows the same rise in mobile share."}},{"id":"paid-social","label":"Paid social","metric":"paid-sessions","breakdown":"utm_source","dropped":{"check":"Did paid social spend, which is almost all mobile, fall or pause?","yes":"Sessions from Meta, TikTok or Snap fall and the mobile share falls with them."},"spiked":{"check":"Did a paid social campaign or creator push start?","yes":"Sessions from a social source jump and nearly all of them are on phones."}},{"id":"email-and-sms","label":"Email and SMS sends","breakdown":"utm_medium","dropped":{"check":"Did fewer email or SMS sends go out this week?","yes":"Email and SMS sessions, mostly on phones, fall by enough to explain the shift."},"spiked":{"check":"Did a big email or SMS campaign go out?","yes":"Sessions tagged email or sms jump on the send days, mostly on phones."}},{"id":"desktop-sources","label":"Desktop-heavy sources","metric":"organic-sessions","dropped":{"check":"Did search, B2B or work-hours traffic, which skews desktop, grow?","yes":"Desktop sessions rise from search or one referrer while mobile holds."},"spiked":{"check":"Did desktop-heavy sources such as search or a partner site shrink?","yes":"Desktop sessions fall from one source while mobile holds."}}],"diagnose_order":["tracking","calendar","paid-social","email-and-sms","desktop-sources"],"related":["sessions","mobile-conversion-rate","conversion-rate","bounce-rate","paid-sessions"],"prose":{"why_it_matters":"Phones bring most store visits but convert at about half the desktop rate, so the device mix moves store conversion with no change to the site. When mobile share rises from 70% to 75%, a store converting 1.8% on mobile and 3.6% on desktop loses about 0.09 points of conversion from the mix alone. Check this before blaming checkout.","pitfalls":["Tablets are not mobile here. Tools that fold tablets into mobile read 3 to 8 points higher.","Device type comes from the user agent. Browser changes such as reduced user-agent strings and in-app webviews can move sessions between devices without anyone changing what they use.","The share can rise because desktop fell. Read it with mobile and desktop session counts side by side.","Bots usually announce a desktop user agent, so a bot wave lowers mobile share. Rule that out before reading a falling share as a change in shoppers."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "mrr": { yaml: "id: mrr\nname: Monthly recurring revenue\naliases:\n  - MRR\n  - Monthly recurring revenue (MRR)\nfamily: subscription\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: The monthly value of every active subscription at the end of the week, with annual plans divided by twelve.\n  formula: Sum of active subscriptions' monthly amounts, measured Sunday 23:59 UTC\n\nevents:\n  - name: subscription_updated\n    description: Any change to a subscription's plan, quantity, discount or status, with its new monthly amount.\n    also_called: [customer.subscription.updated, Subscription Updated, subscription_changed]\n    properties:\n      - name: subscription_id\n        description: The billing system's subscription id.\n      - name: mrr\n        description: The subscription's monthly amount after the change, after discounts, before tax.\n      - name: status\n        description: active, trialing, past_due or canceled.\n\nnumerator:\n  label: MRR at week end\n  aggregate: sum\n  event: subscription_updated\n  property: mrr\n\nqueries:\n  hogql: |-\n    -- MRR at the end of each week: the monthly amounts of every active or past-due subscription, each at its latest subscription_updated before Monday 00:00 UTC. Last 26 complete weeks, oldest first.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT w.week AS week, coalesce(m.mrr, 0) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, sum(tupleElement(latest, 1)) AS mrr\n      FROM (\n        SELECT s.week AS week, u.subscription_id AS subscription_id, argMax(tuple(u.mrr, u.status), u.ts) AS latest\n        FROM (\n          SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n        ) AS s\n        CROSS JOIN (\n          SELECT\n            toString(properties.subscription_id) AS subscription_id,\n            toTimeZone(timestamp, 'UTC') AS ts,\n            toFloat(properties.mrr) AS mrr,\n            toString(properties.status) AS status\n          FROM events\n          WHERE event = 'subscription_updated'\n            AND properties.subscription_id IS NOT NULL\n            AND toMonday(toTimeZone(timestamp, 'UTC')) < toMonday(toTimeZone(now(), 'UTC'))\n        ) AS u\n        WHERE toMonday(u.ts) <= s.week\n        GROUP BY week, subscription_id\n      )\n      WHERE tupleElement(latest, 2) IN ('active', 'past_due')\n      GROUP BY week\n    ) AS m ON m.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- MRR at the end of each week: the monthly amounts of every active or past-due subscription, each at its latest subscription_updated before Monday 00:00 UTC. Last 26 complete weeks, oldest first.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week, g.week + interval '1 week' AS week_end\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    updates AS (\n      SELECT\n        properties->>'subscription_id' AS subscription_id,\n        occurred_at AT TIME ZONE 'UTC' AS ts,\n        CASE WHEN properties->>'mrr' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr')::numeric END AS mrr,\n        properties->>'status' AS status\n      FROM events\n      WHERE event_name = 'subscription_updated'\n        AND properties->>'subscription_id' IS NOT NULL\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n    ),\n    latest AS (\n      SELECT DISTINCT ON (w.week, u.subscription_id) w.week, u.mrr, u.status\n      FROM weeks AS w\n      JOIN updates AS u ON u.ts < w.week_end\n      ORDER BY w.week, u.subscription_id, u.ts DESC\n    ),\n    mrr AS (\n      SELECT week, sum(mrr) AS mrr\n      FROM latest\n      WHERE status IN ('active', 'past_due')\n      GROUP BY week\n    )\n    SELECT w.week, coalesce(m.mrr, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN mrr AS m ON m.week = w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- MRR at the end of each week: the monthly amounts of every active or past-due subscription, each at its latest subscription_updated before Monday 00:00 UTC. Last 26 complete weeks, oldest first.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    updates AS (\n      SELECT\n        JSON_VALUE(properties, '$.subscription_id') AS subscription_id,\n        occurred_at,\n        SAFE_CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64) AS mrr,\n        JSON_VALUE(properties, '$.status') AS status\n      FROM events\n      WHERE event_name = 'subscription_updated'\n        AND JSON_VALUE(properties, '$.subscription_id') IS NOT NULL\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    ),\n    latest AS (\n      SELECT w.week, u.mrr, u.status\n      FROM weeks AS w\n      CROSS JOIN updates AS u\n      WHERE u.occurred_at < TIMESTAMP(DATE_ADD(w.week, INTERVAL 1 WEEK))\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY w.week, u.subscription_id ORDER BY u.occurred_at DESC) = 1\n    ),\n    mrr AS (\n      SELECT week, SUM(mrr) AS mrr\n      FROM latest\n      WHERE status IN ('active', 'past_due')\n      GROUP BY week\n    )\n    SELECT w.week, COALESCE(m.mrr, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN mrr AS m ON m.week = w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- MRR at the end of each week: the monthly amounts of every active or past-due subscription, each at its latest subscription_updated before Monday 00:00 UTC. Last 26 complete weeks, oldest first.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    updates AS (\n      SELECT\n        properties:\"subscription_id\"::string AS subscription_id,\n        occurred_at,\n        TRY_TO_DOUBLE(properties:\"mrr\"::string) AS mrr,\n        properties:\"status\"::string AS status\n      FROM events\n      WHERE event_name = 'subscription_updated'\n        AND properties:\"subscription_id\"::string IS NOT NULL\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n    ),\n    latest AS (\n      SELECT w.week, u.mrr, u.status\n      FROM weeks AS w\n      JOIN updates AS u ON u.occurred_at < DATEADD(week, 1, w.week)\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY w.week, u.subscription_id ORDER BY u.occurred_at DESC) = 1\n    ),\n    mrr AS (\n      SELECT week, SUM(mrr) AS mrr\n      FROM latest\n      WHERE status IN ('active', 'past_due')\n      GROUP BY week\n    )\n    SELECT w.week, COALESCE(m.mrr, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN mrr AS m ON m.week = w.week\n    ORDER BY w.week;\n\nnoise:\n  type: process\n  min_denominator: 20\n  volume_unit: active subscriptions\n  typical: 180000\n\nexample:\n  business: saas\n  level: 240000\n  volume: 1900\n  trend: 0.35\n\ndrivers:\n  - id: new-mrr\n    label: New MRR\n    metric: new-mrr\n    dropped:\n      check: Did fewer new customers start paying, or start on smaller plans?\n      yes: New MRR falls below its usual range while churn holds.\n    spiked:\n      check: Did a launch, a sales push or one large deal add new MRR?\n      yes: New MRR jumps; check whether one customer accounts for most of it.\n  - id: expansion\n    label: Expansion\n    metric: expansion-mrr\n    dropped:\n      check: Did upgrades and seat additions slow?\n      yes: Expansion MRR falls while new and churned MRR hold.\n    spiked:\n      check: Did a price change or a usage limit push customers to upgrade?\n      yes: Expansion MRR jumps in the week the change shipped.\n  - id: churn\n    label: Churned MRR\n    metric: churned-mrr\n    feed: stripe\n    dropped:\n      check: Did cancellations, downgrades or failed renewals rise?\n      yes: Churned MRR rises; failed payments or one large account explain most of it.\n    spiked:\n      check: Did churn fall unusually low, or did failed payments recover?\n      yes: Churned MRR falls and recovered dunning payments appear.\n  - id: billing-calendar\n    label: Billing calendar\n    dropped:\n      check: Did a cohort of annual plans come up for renewal this week?\n      yes: A cluster of renewals dated one year after a big signup month.\n    spiked:\n      check: Is a migration or a currency revaluation changing amounts without customers acting?\n      yes: Many subscriptions change amount on the same day with no plan change.\n\ndiagnose_order: [billing-calendar, churn, new-mrr, expansion]\n\nrelated: [new-mrr, expansion-mrr, churned-mrr, net-new-mrr, arpa]\n\nprose:\n  why_it_matters: >-\n    MRR is the stock that every other subscription number flows into: new and expansion MRR\n    add to it, churn and contraction take from it. Because it is a stock, it barely moves week\n    to week, which is exactly why a small move matters. Read its flows to see why it moved;\n    read MRR itself to see whether the business is growing.\n  pitfalls:\n    - Counting trials or unpaid invoices as MRR inflates it until they lapse. Count only subscriptions that pay.\n    - Annual plans divided by twelve smooth revenue; booking them in full the month they are paid makes MRR spike and fall back.\n    - Discounts and coupons belong in MRR at the discounted amount, or MRR overstates what customers pay.\n    - A week with a currency revaluation or a price migration moves MRR with no change in customers. Note it on the week.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"mrr","name":"Monthly recurring revenue","aliases":["MRR","Monthly recurring revenue (MRR)"],"family":"subscription","kind":"currency","polarity":"up-is-good","definition":{"one_line":"The monthly value of every active subscription at the end of the week, with annual plans divided by twelve.","formula":"Sum of active subscriptions' monthly amounts, measured Sunday 23:59 UTC"},"events":[{"name":"subscription_updated","description":"Any change to a subscription's plan, quantity, discount or status, with its new monthly amount.","also_called":["customer.subscription.updated","Subscription Updated","subscription_changed"],"properties":[{"name":"subscription_id","description":"The billing system's subscription id."},{"name":"mrr","description":"The subscription's monthly amount after the change, after discounts, before tax."},{"name":"status","description":"active, trialing, past_due or canceled."}]}],"numerator":{"label":"MRR at week end","aggregate":"sum","event":"subscription_updated","property":"mrr"},"queries":{"hogql":"-- MRR at the end of each week: the monthly amounts of every active or past-due subscription, each at its latest subscription_updated before Monday 00:00 UTC. Last 26 complete weeks, oldest first.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT w.week AS week, coalesce(m.mrr, 0) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, sum(tupleElement(latest, 1)) AS mrr\n  FROM (\n    SELECT s.week AS week, u.subscription_id AS subscription_id, argMax(tuple(u.mrr, u.status), u.ts) AS latest\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS s\n    CROSS JOIN (\n      SELECT\n        toString(properties.subscription_id) AS subscription_id,\n        toTimeZone(timestamp, 'UTC') AS ts,\n        toFloat(properties.mrr) AS mrr,\n        toString(properties.status) AS status\n      FROM events\n      WHERE event = 'subscription_updated'\n        AND properties.subscription_id IS NOT NULL\n        AND toMonday(toTimeZone(timestamp, 'UTC')) < toMonday(toTimeZone(now(), 'UTC'))\n    ) AS u\n    WHERE toMonday(u.ts) <= s.week\n    GROUP BY week, subscription_id\n  )\n  WHERE tupleElement(latest, 2) IN ('active', 'past_due')\n  GROUP BY week\n) AS m ON m.week = w.week\nORDER BY week","postgres":"-- MRR at the end of each week: the monthly amounts of every active or past-due subscription, each at its latest subscription_updated before Monday 00:00 UTC. Last 26 complete weeks, oldest first.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week, g.week + interval '1 week' AS week_end\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nupdates AS (\n  SELECT\n    properties->>'subscription_id' AS subscription_id,\n    occurred_at AT TIME ZONE 'UTC' AS ts,\n    CASE WHEN properties->>'mrr' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr')::numeric END AS mrr,\n    properties->>'status' AS status\n  FROM events\n  WHERE event_name = 'subscription_updated'\n    AND properties->>'subscription_id' IS NOT NULL\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n),\nlatest AS (\n  SELECT DISTINCT ON (w.week, u.subscription_id) w.week, u.mrr, u.status\n  FROM weeks AS w\n  JOIN updates AS u ON u.ts < w.week_end\n  ORDER BY w.week, u.subscription_id, u.ts DESC\n),\nmrr AS (\n  SELECT week, sum(mrr) AS mrr\n  FROM latest\n  WHERE status IN ('active', 'past_due')\n  GROUP BY week\n)\nSELECT w.week, coalesce(m.mrr, 0) AS value\nFROM weeks AS w\nLEFT JOIN mrr AS m ON m.week = w.week\nORDER BY w.week;","bigquery":"-- MRR at the end of each week: the monthly amounts of every active or past-due subscription, each at its latest subscription_updated before Monday 00:00 UTC. Last 26 complete weeks, oldest first.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nupdates AS (\n  SELECT\n    JSON_VALUE(properties, '$.subscription_id') AS subscription_id,\n    occurred_at,\n    SAFE_CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64) AS mrr,\n    JSON_VALUE(properties, '$.status') AS status\n  FROM events\n  WHERE event_name = 'subscription_updated'\n    AND JSON_VALUE(properties, '$.subscription_id') IS NOT NULL\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n),\nlatest AS (\n  SELECT w.week, u.mrr, u.status\n  FROM weeks AS w\n  CROSS JOIN updates AS u\n  WHERE u.occurred_at < TIMESTAMP(DATE_ADD(w.week, INTERVAL 1 WEEK))\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY w.week, u.subscription_id ORDER BY u.occurred_at DESC) = 1\n),\nmrr AS (\n  SELECT week, SUM(mrr) AS mrr\n  FROM latest\n  WHERE status IN ('active', 'past_due')\n  GROUP BY week\n)\nSELECT w.week, COALESCE(m.mrr, 0) AS value\nFROM weeks AS w\nLEFT JOIN mrr AS m ON m.week = w.week\nORDER BY w.week;","snowflake":"-- MRR at the end of each week: the monthly amounts of every active or past-due subscription, each at its latest subscription_updated before Monday 00:00 UTC. Last 26 complete weeks, oldest first.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nupdates AS (\n  SELECT\n    properties:\"subscription_id\"::string AS subscription_id,\n    occurred_at,\n    TRY_TO_DOUBLE(properties:\"mrr\"::string) AS mrr,\n    properties:\"status\"::string AS status\n  FROM events\n  WHERE event_name = 'subscription_updated'\n    AND properties:\"subscription_id\"::string IS NOT NULL\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n),\nlatest AS (\n  SELECT w.week, u.mrr, u.status\n  FROM weeks AS w\n  JOIN updates AS u ON u.occurred_at < DATEADD(week, 1, w.week)\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY w.week, u.subscription_id ORDER BY u.occurred_at DESC) = 1\n),\nmrr AS (\n  SELECT week, SUM(mrr) AS mrr\n  FROM latest\n  WHERE status IN ('active', 'past_due')\n  GROUP BY week\n)\nSELECT w.week, COALESCE(m.mrr, 0) AS value\nFROM weeks AS w\nLEFT JOIN mrr AS m ON m.week = w.week\nORDER BY w.week;"},"noise":{"type":"process","min_denominator":20,"volume_unit":"active subscriptions","typical":180000},"example":{"business":"saas","level":240000,"volume":1900,"trend":0.35},"drivers":[{"id":"new-mrr","label":"New MRR","metric":"new-mrr","dropped":{"check":"Did fewer new customers start paying, or start on smaller plans?","yes":"New MRR falls below its usual range while churn holds."},"spiked":{"check":"Did a launch, a sales push or one large deal add new MRR?","yes":"New MRR jumps; check whether one customer accounts for most of it."}},{"id":"expansion","label":"Expansion","metric":"expansion-mrr","dropped":{"check":"Did upgrades and seat additions slow?","yes":"Expansion MRR falls while new and churned MRR hold."},"spiked":{"check":"Did a price change or a usage limit push customers to upgrade?","yes":"Expansion MRR jumps in the week the change shipped."}},{"id":"churn","label":"Churned MRR","metric":"churned-mrr","feed":"stripe","dropped":{"check":"Did cancellations, downgrades or failed renewals rise?","yes":"Churned MRR rises; failed payments or one large account explain most of it."},"spiked":{"check":"Did churn fall unusually low, or did failed payments recover?","yes":"Churned MRR falls and recovered dunning payments appear."}},{"id":"billing-calendar","label":"Billing calendar","dropped":{"check":"Did a cohort of annual plans come up for renewal this week?","yes":"A cluster of renewals dated one year after a big signup month."},"spiked":{"check":"Is a migration or a currency revaluation changing amounts without customers acting?","yes":"Many subscriptions change amount on the same day with no plan change."}}],"diagnose_order":["billing-calendar","churn","new-mrr","expansion"],"related":["new-mrr","expansion-mrr","churned-mrr","net-new-mrr","arpa"],"prose":{"why_it_matters":"MRR is the stock that every other subscription number flows into: new and expansion MRR add to it, churn and contraction take from it. Because it is a stock, it barely moves week to week, which is exactly why a small move matters. Read its flows to see why it moved; read MRR itself to see whether the business is growing.","pitfalls":["Counting trials or unpaid invoices as MRR inflates it until they lapse. Count only subscriptions that pay.","Annual plans divided by twelve smooth revenue; booking them in full the month they are paid makes MRR spike and fall back.","Discounts and coupons belong in MRR at the discounted amount, or MRR overstates what customers pay.","A week with a currency revaluation or a price migration moves MRR with no change in customers. Note it on the week."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "ncac": { yaml: "id: ncac\nname: New customer acquisition cost\naliases:\n  - nCAC\n  - NCPA\n  - New customer CPA\n  - Cost per new customer\nfamily: acquisition\ncatalog_id: ncac\nkind: currency\npolarity: down-is-good\n\ndefinition:\n  one_line: Ad spend in the week divided by the customers who placed their first ever order that week.\n  formula: Ad spend ÷ first orders\n\nevents:\n  - name: ad_spend\n    description: One row per channel per day, synced from each ad platform's reporting API.\n    also_called: [Ad Spend, ad_performance, campaign_daily_stats]\n    properties:\n      - name: spend\n        description: Amount spent that day, in the store's reporting currency.\n      - name: channel\n        description: The platform (google, meta, tiktok, microsoft, pinterest).\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: is_first_order\n        description: True when this is the customer's first ever paid order, by email or customer id, across guest and account checkouts.\n      - name: customer_id\n        description: The store's customer id, stable across orders.\n\nnumerator:\n  label: Ad spend\n  aggregate: sum\n  event: ad_spend\n  property: spend\ndenominator:\n  label: First orders\n  aggregate: count\n  event: order_completed\n  where:\n    - property: is_first_order\n      op: eq\n      value: true\n\nnoise:\n  type: process\n  min_denominator: 20\n  volume_unit: new customers a week\n  typical: 55\n\nexample:\n  business: store\n  level: 58\n  volume: 5200\n  trend: 0.12\n\ndrivers:\n  - id: data\n    label: Spend and first-order data\n    dropped:\n      check: Is spend missing for a channel, or are returning customers being flagged as first orders?\n      yes: One channel's spend has gaps, or first orders jump while total orders hold, often after a platform or checkout migration.\n    spiked:\n      check: Is spend synced twice, or did a change stop first orders being flagged?\n      yes: One channel's spend doubles for a day, or first orders fall to near zero while total orders hold.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Is this a sale or gifting week that brings in first-time buyers at the same spend?\n      yes: First orders jump in the event week and the same week last year shows the same fall in nCAC.\n    spiked:\n      check: Did a sale end, or is spend rising ahead of an event before buyers arrive?\n      yes: The same weeks last year show the same rise once aligned on the event.\n  - id: new-customers\n    label: New customers\n    metric: new-customers\n    dropped:\n      check: Did more first-time customers order at steady spend?\n      yes: New customers rise by about as much as nCAC falls.\n    spiked:\n      check: Did fewer first-time customers order at steady spend?\n      yes: New customers fall by about as much as nCAC rises; check paid conversion and traffic next.\n  - id: spend\n    label: Ad spend\n    metric: ad-spend\n    feed: ad-platforms\n    dropped:\n      check: Did spend fall, cutting the least efficient campaigns first?\n      yes: Spend falls more than new customers do.\n    spiked:\n      check: Did a budget increase or a new prospecting campaign add spend faster than customers?\n      yes: Spend rises on one channel while new customers grow less; scaling usually raises nCAC.\n  - id: cpm\n    label: Price of attention\n    metric: cpm\n    dropped:\n      check: Did impressions get cheaper across platforms?\n      yes: CPM falls by about as much as nCAC, while click-through and conversion hold.\n    spiked:\n      check: Did impressions get more expensive, as they do in Q4?\n      yes: CPM rises by about as much as nCAC, while click-through and conversion hold.\n  - id: paid-conversion\n    label: Paid conversion rate\n    metric: paid-conversion-rate\n    dropped:\n      check: Did more paid visits turn into first orders?\n      yes: Paid conversion rises while CPC holds.\n    spiked:\n      check: Did fewer paid visits order, from a landing page, offer, stock or checkout problem?\n      yes: Paid conversion falls while CPC holds.\n\ndiagnose_order: [data, calendar, new-customers, spend, cpm, paid-conversion]\n\nrelated: [blended-cac, mer, ad-spend, new-customers, ltv-to-cac, cpm]\n\nprose:\n  why_it_matters: >-\n    nCAC is the price of growth for a store: what the ads cost for each customer who had never\n    bought before. Returning customers are left out of the denominator, so it can't be flattered\n    by a loyal base the way MER can. At $58 per new customer and a $100 first order with 60%\n    gross margin, the first order alone pays the ad back with $2 to spare.\n  pitfalls:\n    - Ad spend divided by all orders is cost per order, not nCAC. Including returning customers makes acquisition look two or three times cheaper on a store with a strong repeat base.\n    - All new customers are in the denominator, including those from organic search, email signups and word of mouth. A week with a press mention lowers nCAC without the ads doing anything.\n    - First orders need one customer identity across guest and account checkouts. Matching by email misses people who buy again with a different address and makes them new twice.\n    - Spend in one week buys customers over the next several. Weekly nCAC swings when budgets change fast; read a four-week view before cutting a channel.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"ncac","name":"New customer acquisition cost","aliases":["nCAC","NCPA","New customer CPA","Cost per new customer"],"family":"acquisition","catalog_id":"ncac","kind":"currency","polarity":"down-is-good","definition":{"one_line":"Ad spend in the week divided by the customers who placed their first ever order that week.","formula":"Ad spend ÷ first orders"},"events":[{"name":"ad_spend","description":"One row per channel per day, synced from each ad platform's reporting API.","also_called":["Ad Spend","ad_performance","campaign_daily_stats"],"properties":[{"name":"spend","description":"Amount spent that day, in the store's reporting currency."},{"name":"channel","description":"The platform (google, meta, tiktok, microsoft, pinterest)."}]},{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"is_first_order","description":"True when this is the customer's first ever paid order, by email or customer id, across guest and account checkouts."},{"name":"customer_id","description":"The store's customer id, stable across orders."}]}],"numerator":{"label":"Ad spend","aggregate":"sum","event":"ad_spend","property":"spend"},"denominator":{"label":"First orders","aggregate":"count","event":"order_completed","where":[{"property":"is_first_order","op":"eq","value":true}]},"noise":{"type":"process","min_denominator":20,"volume_unit":"new customers a week","typical":55},"example":{"business":"store","level":58,"volume":5200,"trend":0.12},"drivers":[{"id":"data","label":"Spend and first-order data","dropped":{"check":"Is spend missing for a channel, or are returning customers being flagged as first orders?","yes":"One channel's spend has gaps, or first orders jump while total orders hold, often after a platform or checkout migration."},"spiked":{"check":"Is spend synced twice, or did a change stop first orders being flagged?","yes":"One channel's spend doubles for a day, or first orders fall to near zero while total orders hold."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Is this a sale or gifting week that brings in first-time buyers at the same spend?","yes":"First orders jump in the event week and the same week last year shows the same fall in nCAC."},"spiked":{"check":"Did a sale end, or is spend rising ahead of an event before buyers arrive?","yes":"The same weeks last year show the same rise once aligned on the event."}},{"id":"new-customers","label":"New customers","metric":"new-customers","dropped":{"check":"Did more first-time customers order at steady spend?","yes":"New customers rise by about as much as nCAC falls."},"spiked":{"check":"Did fewer first-time customers order at steady spend?","yes":"New customers fall by about as much as nCAC rises; check paid conversion and traffic next."}},{"id":"spend","label":"Ad spend","metric":"ad-spend","feed":"ad-platforms","dropped":{"check":"Did spend fall, cutting the least efficient campaigns first?","yes":"Spend falls more than new customers do."},"spiked":{"check":"Did a budget increase or a new prospecting campaign add spend faster than customers?","yes":"Spend rises on one channel while new customers grow less; scaling usually raises nCAC."}},{"id":"cpm","label":"Price of attention","metric":"cpm","dropped":{"check":"Did impressions get cheaper across platforms?","yes":"CPM falls by about as much as nCAC, while click-through and conversion hold."},"spiked":{"check":"Did impressions get more expensive, as they do in Q4?","yes":"CPM rises by about as much as nCAC, while click-through and conversion hold."}},{"id":"paid-conversion","label":"Paid conversion rate","metric":"paid-conversion-rate","dropped":{"check":"Did more paid visits turn into first orders?","yes":"Paid conversion rises while CPC holds."},"spiked":{"check":"Did fewer paid visits order, from a landing page, offer, stock or checkout problem?","yes":"Paid conversion falls while CPC holds."}}],"diagnose_order":["data","calendar","new-customers","spend","cpm","paid-conversion"],"related":["blended-cac","mer","ad-spend","new-customers","ltv-to-cac","cpm"],"prose":{"why_it_matters":"nCAC is the price of growth for a store: what the ads cost for each customer who had never bought before. Returning customers are left out of the denominator, so it can't be flattered by a loyal base the way MER can. At $58 per new customer and a $100 first order with 60% gross margin, the first order alone pays the ad back with $2 to spare.","pitfalls":["Ad spend divided by all orders is cost per order, not nCAC. Including returning customers makes acquisition look two or three times cheaper on a store with a strong repeat base.","All new customers are in the denominator, including those from organic search, email signups and word of mouth. A week with a press mention lowers nCAC without the ads doing anything.","First orders need one customer identity across guest and account checkouts. Matching by email misses people who buy again with a different address and makes them new twice.","Spend in one week buys customers over the next several. Weekly nCAC swings when budgets change fast; read a four-week view before cutting a channel."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "net-new-mrr": { yaml: "id: net-new-mrr\nname: Net new MRR\naliases:\n  - Net MRR growth\n  - Net MRR change\n  - MRR growth\n  - Net new monthly recurring revenue\nfamily: subscription\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: How much monthly recurring revenue grew or shrank this week, the sum of its four movements; it can be negative.\n  formula: New MRR + expansion MRR − contraction MRR − churned MRR\n\nevents:\n  - name: subscription_started\n    description: A subscription's first paid period began.\n    also_called: [Subscription Started, subscription_created]\n    properties:\n      - name: mrr\n        description: The new subscription's monthly amount.\n  - name: subscription_expanded\n    description: A paying subscription's monthly amount went up.\n    also_called: [Subscription Upgraded, plan_upgraded]\n    properties:\n      - name: mrr_delta\n        description: How much it rose, as a positive number.\n  - name: subscription_contracted\n    description: A paying subscription's monthly amount went down from a downgrade, fewer seats or less usage, without ending.\n    also_called: [Subscription Downgraded, plan_downgraded]\n    properties:\n      - name: mrr_delta\n        description: How much it fell, as a positive number.\n  - name: subscription_canceled\n    description: A subscription stopped being billed.\n    also_called: [customer.subscription.deleted, Subscription Cancelled]\n    properties:\n      - name: mrr\n        description: The monthly amount it was paying before it ended.\n\nnumerator:\n  label: New MRR, before the other three movements\n  aggregate: sum\n  event: subscription_started\n  property: mrr\n\nqueries:\n  hogql: |-\n    -- Net new MRR per week: new + expansion − contraction − churned MRR, each from its event in that week. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(f.new_mrr, 0) AS new_mrr,\n      coalesce(f.expansion_mrr, 0) AS expansion_mrr,\n      coalesce(f.contraction_mrr, 0) AS contraction_mrr,\n      coalesce(f.churned_mrr, 0) AS churned_mrr,\n      new_mrr + expansion_mrr - contraction_mrr - churned_mrr AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT\n        toMonday(toTimeZone(timestamp, 'UTC')) AS week,\n        sumIf(toFloat(properties.mrr), event = 'subscription_started') AS new_mrr,\n        sumIf(toFloat(properties.mrr_delta), event = 'subscription_expanded') AS expansion_mrr,\n        sumIf(toFloat(properties.mrr_delta), event = 'subscription_contracted') AS contraction_mrr,\n        sumIf(toFloat(properties.mrr), event = 'subscription_canceled') AS churned_mrr\n      FROM events\n      WHERE event IN ('subscription_started', 'subscription_expanded', 'subscription_contracted', 'subscription_canceled')\n        AND timestamp >= now() - toIntervalWeek(27)\n        AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n      GROUP BY week\n    ) AS f ON f.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Net new MRR per week: new + expansion − contraction − churned MRR, each from its event in that week. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    flows AS (\n      SELECT\n        date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n        sum(CASE WHEN properties->>'mrr' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr')::numeric END) FILTER (WHERE event_name = 'subscription_started') AS new_mrr,\n        sum(CASE WHEN properties->>'mrr_delta' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr_delta')::numeric END) FILTER (WHERE event_name = 'subscription_expanded') AS expansion_mrr,\n        sum(CASE WHEN properties->>'mrr_delta' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr_delta')::numeric END) FILTER (WHERE event_name = 'subscription_contracted') AS contraction_mrr,\n        sum(CASE WHEN properties->>'mrr' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr')::numeric END) FILTER (WHERE event_name = 'subscription_canceled') AS churned_mrr\n      FROM events\n      WHERE event_name IN ('subscription_started', 'subscription_expanded', 'subscription_contracted', 'subscription_canceled')\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n      GROUP BY 1\n    ),\n    totals AS (\n      SELECT\n        w.week,\n        coalesce(f.new_mrr, 0) AS new_mrr,\n        coalesce(f.expansion_mrr, 0) AS expansion_mrr,\n        coalesce(f.contraction_mrr, 0) AS contraction_mrr,\n        coalesce(f.churned_mrr, 0) AS churned_mrr\n      FROM weeks AS w\n      LEFT JOIN flows AS f ON f.week = w.week\n    )\n    SELECT week, new_mrr, expansion_mrr, contraction_mrr, churned_mrr, new_mrr + expansion_mrr - contraction_mrr - churned_mrr AS value\n    FROM totals\n    ORDER BY week;\n  bigquery: |-\n    -- Net new MRR per week: new + expansion − contraction − churned MRR, each from its event in that week. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    flows AS (\n      SELECT\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n        SUM(IF(event_name = 'subscription_started', SAFE_CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64), NULL)) AS new_mrr,\n        SUM(IF(event_name = 'subscription_expanded', SAFE_CAST(JSON_VALUE(properties, '$.mrr_delta') AS FLOAT64), NULL)) AS expansion_mrr,\n        SUM(IF(event_name = 'subscription_contracted', SAFE_CAST(JSON_VALUE(properties, '$.mrr_delta') AS FLOAT64), NULL)) AS contraction_mrr,\n        SUM(IF(event_name = 'subscription_canceled', SAFE_CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64), NULL)) AS churned_mrr\n      FROM events\n      WHERE event_name IN ('subscription_started', 'subscription_expanded', 'subscription_contracted', 'subscription_canceled')\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY week\n    ),\n    totals AS (\n      SELECT\n        w.week,\n        COALESCE(f.new_mrr, 0) AS new_mrr,\n        COALESCE(f.expansion_mrr, 0) AS expansion_mrr,\n        COALESCE(f.contraction_mrr, 0) AS contraction_mrr,\n        COALESCE(f.churned_mrr, 0) AS churned_mrr\n      FROM weeks AS w\n      LEFT JOIN flows AS f ON f.week = w.week\n    )\n    SELECT week, new_mrr, expansion_mrr, contraction_mrr, churned_mrr, new_mrr + expansion_mrr - contraction_mrr - churned_mrr AS value\n    FROM totals\n    ORDER BY week;\n  snowflake: |-\n    -- Net new MRR per week: new + expansion − contraction − churned MRR, each from its event in that week. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    flows AS (\n      SELECT\n        DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n        SUM(IFF(event_name = 'subscription_started', TRY_TO_DOUBLE(properties:\"mrr\"::string), NULL)) AS new_mrr,\n        SUM(IFF(event_name = 'subscription_expanded', TRY_TO_DOUBLE(properties:\"mrr_delta\"::string), NULL)) AS expansion_mrr,\n        SUM(IFF(event_name = 'subscription_contracted', TRY_TO_DOUBLE(properties:\"mrr_delta\"::string), NULL)) AS contraction_mrr,\n        SUM(IFF(event_name = 'subscription_canceled', TRY_TO_DOUBLE(properties:\"mrr\"::string), NULL)) AS churned_mrr\n      FROM events\n      WHERE event_name IN ('subscription_started', 'subscription_expanded', 'subscription_contracted', 'subscription_canceled')\n        AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n      GROUP BY 1\n    ),\n    totals AS (\n      SELECT\n        w.week,\n        COALESCE(f.new_mrr, 0) AS new_mrr,\n        COALESCE(f.expansion_mrr, 0) AS expansion_mrr,\n        COALESCE(f.contraction_mrr, 0) AS contraction_mrr,\n        COALESCE(f.churned_mrr, 0) AS churned_mrr\n      FROM weeks AS w\n      LEFT JOIN flows AS f ON f.week = w.week\n    )\n    SELECT week, new_mrr, expansion_mrr, contraction_mrr, churned_mrr, new_mrr + expansion_mrr - contraction_mrr - churned_mrr AS value\n    FROM totals\n    ORDER BY week;\n\nnoise:\n  type: process\n  min_denominator: 20\n  volume_unit: MRR movements a week\n  typical: 1400\n\nexample:\n  business: saas\n  level: 1410\n  volume: 45\n  trend: 0.35\n\ndrivers:\n  - id: reconciliation\n    label: Movements vs MRR\n    metric: mrr\n    dropped:\n      check: Does this week's net new MRR match the change in MRR from last Sunday to this one?\n      yes: A gap between them means a movement is missing from the event stream, usually a plan change or cancellation that never synced.\n    spiked:\n      check: Does the rise match the change in MRR, or is it larger?\n      yes: Net new MRR runs ahead of the MRR change, which points at a backfill or duplicated subscription_started events.\n  - id: calendar\n    label: Calendar\n    feed: holidays\n    dropped:\n      check: Is this a holiday week, when purchases pause but renewals and cancellations don't?\n      yes: New MRR falls, churn holds, and the same week last year shows the same dip.\n    spiked:\n      check: Is this the last week of a quarter, when sales-led deals close?\n      yes: New MRR jumps in the same closing week of earlier quarters too.\n  - id: churned\n    label: Churned MRR\n    metric: churned-mrr\n    dropped:\n      check: Did more subscriptions end, or larger ones?\n      yes: Churned MRR rises by about as much as net new MRR fell.\n    spiked:\n      check: Did churn fall unusually low, or did failed payments recover?\n      yes: Churned MRR falls by about as much as net new MRR rose.\n  - id: new\n    label: New MRR\n    metric: new-mrr\n    dropped:\n      check: Did fewer customers start paying, or start on smaller plans?\n      yes: New MRR falls by about as much as net new MRR while churn holds.\n    spiked:\n      check: Did a launch, a sales push or one large deal add new MRR?\n      yes: New MRR jumps; check whether one customer is most of it.\n  - id: expansion\n    label: Expansion MRR\n    metric: expansion-mrr\n    dropped:\n      check: Did upgrades and seat additions slow?\n      yes: Expansion MRR falls while new and churned MRR hold.\n    spiked:\n      check: Did a price change or a usage limit push customers to upgrade?\n      yes: Expansion MRR jumps in the week the change shipped.\n  - id: contraction\n    label: Contraction MRR\n    breakdown: plan\n    dropped:\n      check: Did more customers move to cheaper plans or fewer seats without leaving?\n      yes: subscription_contracted totals rise, often concentrated in one plan or after customers' own budget cuts.\n    spiked:\n      check: Did downgrades slow, or was a downgrade path removed?\n      yes: Contraction falls; if a cheaper plan was removed, watch whether churn rises instead.\n\ndiagnose_order: [reconciliation, calendar, churned, new, expansion, contraction]\n\nrelated: [mrr, new-mrr, expansion-mrr, churned-mrr, quick-ratio]\n\nprose:\n  why_it_matters: >-\n    Net new MRR is the week's change in MRR explained by its four movements, and the one number\n    that says whether the subscription business grew. A B2B SaaS at $240k MRR growing 35% a year\n    adds about $1,400 in an ordinary week, the difference between roughly $2,800 coming in and\n    $1,400 going out, so one bad week on either side can turn it negative. Never read it without\n    its parts: the same net figure can be strong sales hiding a churn problem.\n  pitfalls:\n    - Net new MRR must equal the change in the MRR snapshot from one Sunday to the next. When it doesn't, a movement is missing, usually a plan change or cancellation that never reached the event stream.\n    - Currency revaluations and price migrations change MRR without a customer acting. Classify them on their own, or they land in expansion or contraction.\n    - Because it is the difference of two flows of similar size, it swings far more in percentage terms than any of its parts. Judge it in dollars against its own range, not as a percent change.\n    - Reactivated customers belong with new MRR or on their own line, never netted against churn, or both flows look smaller than they are.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"net-new-mrr","name":"Net new MRR","aliases":["Net MRR growth","Net MRR change","MRR growth","Net new monthly recurring revenue"],"family":"subscription","kind":"currency","polarity":"up-is-good","definition":{"one_line":"How much monthly recurring revenue grew or shrank this week, the sum of its four movements; it can be negative.","formula":"New MRR + expansion MRR − contraction MRR − churned MRR"},"events":[{"name":"subscription_started","description":"A subscription's first paid period began.","also_called":["Subscription Started","subscription_created"],"properties":[{"name":"mrr","description":"The new subscription's monthly amount."}]},{"name":"subscription_expanded","description":"A paying subscription's monthly amount went up.","also_called":["Subscription Upgraded","plan_upgraded"],"properties":[{"name":"mrr_delta","description":"How much it rose, as a positive number."}]},{"name":"subscription_contracted","description":"A paying subscription's monthly amount went down from a downgrade, fewer seats or less usage, without ending.","also_called":["Subscription Downgraded","plan_downgraded"],"properties":[{"name":"mrr_delta","description":"How much it fell, as a positive number."}]},{"name":"subscription_canceled","description":"A subscription stopped being billed.","also_called":["customer.subscription.deleted","Subscription Cancelled"],"properties":[{"name":"mrr","description":"The monthly amount it was paying before it ended."}]}],"numerator":{"label":"New MRR, before the other three movements","aggregate":"sum","event":"subscription_started","property":"mrr"},"queries":{"hogql":"-- Net new MRR per week: new + expansion − contraction − churned MRR, each from its event in that week. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(f.new_mrr, 0) AS new_mrr,\n  coalesce(f.expansion_mrr, 0) AS expansion_mrr,\n  coalesce(f.contraction_mrr, 0) AS contraction_mrr,\n  coalesce(f.churned_mrr, 0) AS churned_mrr,\n  new_mrr + expansion_mrr - contraction_mrr - churned_mrr AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT\n    toMonday(toTimeZone(timestamp, 'UTC')) AS week,\n    sumIf(toFloat(properties.mrr), event = 'subscription_started') AS new_mrr,\n    sumIf(toFloat(properties.mrr_delta), event = 'subscription_expanded') AS expansion_mrr,\n    sumIf(toFloat(properties.mrr_delta), event = 'subscription_contracted') AS contraction_mrr,\n    sumIf(toFloat(properties.mrr), event = 'subscription_canceled') AS churned_mrr\n  FROM events\n  WHERE event IN ('subscription_started', 'subscription_expanded', 'subscription_contracted', 'subscription_canceled')\n    AND timestamp >= now() - toIntervalWeek(27)\n    AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n  GROUP BY week\n) AS f ON f.week = w.week\nORDER BY week","postgres":"-- Net new MRR per week: new + expansion − contraction − churned MRR, each from its event in that week. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nflows AS (\n  SELECT\n    date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n    sum(CASE WHEN properties->>'mrr' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr')::numeric END) FILTER (WHERE event_name = 'subscription_started') AS new_mrr,\n    sum(CASE WHEN properties->>'mrr_delta' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr_delta')::numeric END) FILTER (WHERE event_name = 'subscription_expanded') AS expansion_mrr,\n    sum(CASE WHEN properties->>'mrr_delta' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr_delta')::numeric END) FILTER (WHERE event_name = 'subscription_contracted') AS contraction_mrr,\n    sum(CASE WHEN properties->>'mrr' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr')::numeric END) FILTER (WHERE event_name = 'subscription_canceled') AS churned_mrr\n  FROM events\n  WHERE event_name IN ('subscription_started', 'subscription_expanded', 'subscription_contracted', 'subscription_canceled')\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n  GROUP BY 1\n),\ntotals AS (\n  SELECT\n    w.week,\n    coalesce(f.new_mrr, 0) AS new_mrr,\n    coalesce(f.expansion_mrr, 0) AS expansion_mrr,\n    coalesce(f.contraction_mrr, 0) AS contraction_mrr,\n    coalesce(f.churned_mrr, 0) AS churned_mrr\n  FROM weeks AS w\n  LEFT JOIN flows AS f ON f.week = w.week\n)\nSELECT week, new_mrr, expansion_mrr, contraction_mrr, churned_mrr, new_mrr + expansion_mrr - contraction_mrr - churned_mrr AS value\nFROM totals\nORDER BY week;","bigquery":"-- Net new MRR per week: new + expansion − contraction − churned MRR, each from its event in that week. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nflows AS (\n  SELECT\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n    SUM(IF(event_name = 'subscription_started', SAFE_CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64), NULL)) AS new_mrr,\n    SUM(IF(event_name = 'subscription_expanded', SAFE_CAST(JSON_VALUE(properties, '$.mrr_delta') AS FLOAT64), NULL)) AS expansion_mrr,\n    SUM(IF(event_name = 'subscription_contracted', SAFE_CAST(JSON_VALUE(properties, '$.mrr_delta') AS FLOAT64), NULL)) AS contraction_mrr,\n    SUM(IF(event_name = 'subscription_canceled', SAFE_CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64), NULL)) AS churned_mrr\n  FROM events\n  WHERE event_name IN ('subscription_started', 'subscription_expanded', 'subscription_contracted', 'subscription_canceled')\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY week\n),\ntotals AS (\n  SELECT\n    w.week,\n    COALESCE(f.new_mrr, 0) AS new_mrr,\n    COALESCE(f.expansion_mrr, 0) AS expansion_mrr,\n    COALESCE(f.contraction_mrr, 0) AS contraction_mrr,\n    COALESCE(f.churned_mrr, 0) AS churned_mrr\n  FROM weeks AS w\n  LEFT JOIN flows AS f ON f.week = w.week\n)\nSELECT week, new_mrr, expansion_mrr, contraction_mrr, churned_mrr, new_mrr + expansion_mrr - contraction_mrr - churned_mrr AS value\nFROM totals\nORDER BY week;","snowflake":"-- Net new MRR per week: new + expansion − contraction − churned MRR, each from its event in that week. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nflows AS (\n  SELECT\n    DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n    SUM(IFF(event_name = 'subscription_started', TRY_TO_DOUBLE(properties:\"mrr\"::string), NULL)) AS new_mrr,\n    SUM(IFF(event_name = 'subscription_expanded', TRY_TO_DOUBLE(properties:\"mrr_delta\"::string), NULL)) AS expansion_mrr,\n    SUM(IFF(event_name = 'subscription_contracted', TRY_TO_DOUBLE(properties:\"mrr_delta\"::string), NULL)) AS contraction_mrr,\n    SUM(IFF(event_name = 'subscription_canceled', TRY_TO_DOUBLE(properties:\"mrr\"::string), NULL)) AS churned_mrr\n  FROM events\n  WHERE event_name IN ('subscription_started', 'subscription_expanded', 'subscription_contracted', 'subscription_canceled')\n    AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n  GROUP BY 1\n),\ntotals AS (\n  SELECT\n    w.week,\n    COALESCE(f.new_mrr, 0) AS new_mrr,\n    COALESCE(f.expansion_mrr, 0) AS expansion_mrr,\n    COALESCE(f.contraction_mrr, 0) AS contraction_mrr,\n    COALESCE(f.churned_mrr, 0) AS churned_mrr\n  FROM weeks AS w\n  LEFT JOIN flows AS f ON f.week = w.week\n)\nSELECT week, new_mrr, expansion_mrr, contraction_mrr, churned_mrr, new_mrr + expansion_mrr - contraction_mrr - churned_mrr AS value\nFROM totals\nORDER BY week;"},"noise":{"type":"process","min_denominator":20,"volume_unit":"MRR movements a week","typical":1400},"example":{"business":"saas","level":1410,"volume":45,"trend":0.35},"drivers":[{"id":"reconciliation","label":"Movements vs MRR","metric":"mrr","dropped":{"check":"Does this week's net new MRR match the change in MRR from last Sunday to this one?","yes":"A gap between them means a movement is missing from the event stream, usually a plan change or cancellation that never synced."},"spiked":{"check":"Does the rise match the change in MRR, or is it larger?","yes":"Net new MRR runs ahead of the MRR change, which points at a backfill or duplicated subscription_started events."}},{"id":"calendar","label":"Calendar","feed":"holidays","dropped":{"check":"Is this a holiday week, when purchases pause but renewals and cancellations don't?","yes":"New MRR falls, churn holds, and the same week last year shows the same dip."},"spiked":{"check":"Is this the last week of a quarter, when sales-led deals close?","yes":"New MRR jumps in the same closing week of earlier quarters too."}},{"id":"churned","label":"Churned MRR","metric":"churned-mrr","dropped":{"check":"Did more subscriptions end, or larger ones?","yes":"Churned MRR rises by about as much as net new MRR fell."},"spiked":{"check":"Did churn fall unusually low, or did failed payments recover?","yes":"Churned MRR falls by about as much as net new MRR rose."}},{"id":"new","label":"New MRR","metric":"new-mrr","dropped":{"check":"Did fewer customers start paying, or start on smaller plans?","yes":"New MRR falls by about as much as net new MRR while churn holds."},"spiked":{"check":"Did a launch, a sales push or one large deal add new MRR?","yes":"New MRR jumps; check whether one customer is most of it."}},{"id":"expansion","label":"Expansion MRR","metric":"expansion-mrr","dropped":{"check":"Did upgrades and seat additions slow?","yes":"Expansion MRR falls while new and churned MRR hold."},"spiked":{"check":"Did a price change or a usage limit push customers to upgrade?","yes":"Expansion MRR jumps in the week the change shipped."}},{"id":"contraction","label":"Contraction MRR","breakdown":"plan","dropped":{"check":"Did more customers move to cheaper plans or fewer seats without leaving?","yes":"subscription_contracted totals rise, often concentrated in one plan or after customers' own budget cuts."},"spiked":{"check":"Did downgrades slow, or was a downgrade path removed?","yes":"Contraction falls; if a cheaper plan was removed, watch whether churn rises instead."}}],"diagnose_order":["reconciliation","calendar","churned","new","expansion","contraction"],"related":["mrr","new-mrr","expansion-mrr","churned-mrr","quick-ratio"],"prose":{"why_it_matters":"Net new MRR is the week's change in MRR explained by its four movements, and the one number that says whether the subscription business grew. A B2B SaaS at $240k MRR growing 35% a year adds about $1,400 in an ordinary week, the difference between roughly $2,800 coming in and $1,400 going out, so one bad week on either side can turn it negative. Never read it without its parts: the same net figure can be strong sales hiding a churn problem.","pitfalls":["Net new MRR must equal the change in the MRR snapshot from one Sunday to the next. When it doesn't, a movement is missing, usually a plan change or cancellation that never reached the event stream.","Currency revaluations and price migrations change MRR without a customer acting. Classify them on their own, or they land in expansion or contraction.","Because it is the difference of two flows of similar size, it swings far more in percentage terms than any of its parts. Judge it in dollars against its own range, not as a percent change.","Reactivated customers belong with new MRR or on their own line, never netted against churn, or both flows look smaller than they are."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "net-revenue-retention": { yaml: "id: net-revenue-retention\nname: Net revenue retention\naliases:\n  - NRR\n  - NDR\n  - Net dollar retention\n  - Net revenue retention rate\n  - Net retention\nfamily: subscription\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The MRR today from customers who were paying 12 months ago, as a share of what they paid then, after expansion, contraction and churn.\n  formula: MRR at this week's end from customers paying 52 weeks earlier ÷ their MRR then; customers who started since are left out\n\nevents:\n  - name: subscription_updated\n    description: Any change to a subscription's plan, quantity, discount or status, with its new monthly amount.\n    also_called: [customer.subscription.updated, Subscription Updated, subscription_changed]\n    properties:\n      - name: subscription_id\n        description: The billing system's subscription id.\n      - name: mrr\n        description: The subscription's monthly amount after the change, after discounts, before tax.\n      - name: status\n        description: active, trialing, past_due or canceled.\n\nnumerator:\n  label: MRR now from customers paying a year ago\n  aggregate: sum\n  event: subscription_updated\n  property: mrr\n\nqueries:\n  hogql: |-\n    -- Net revenue retention, trailing 12 months, for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: MRR at the week's end from customers who were paying at the end of the same week 52 weeks earlier ÷ their MRR then. A customer is the person on the subscription; customers who started since are left out, and those who left count as zero.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(r.end_total, 0) AS numerator,\n      coalesce(r.start_total, 0) AS denominator,\n      if(denominator = 0, NULL, numerator / denominator) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, sum(end_mrr) AS end_total, sum(start_mrr) AS start_total\n      FROM (\n        SELECT\n          week,\n          account,\n          coalesce(sumIf(sub_mrr, weeks_back = 52), 0) AS start_mrr,\n          coalesce(sumIf(sub_mrr, weeks_back = 0), 0) AS end_mrr\n        FROM (\n          SELECT\n            week,\n            weeks_back,\n            tupleElement(latest, 1) AS account,\n            if(tupleElement(latest, 3) IN ('active', 'past_due'), tupleElement(latest, 2), 0) AS sub_mrr\n          FROM (\n            SELECT s.week AS week, s.weeks_back AS weeks_back, u.subscription_id AS subscription_id, argMax(tuple(u.person, u.mrr, u.status), u.ts) AS latest\n            FROM (\n              SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week, arrayJoin([0, 52]) AS weeks_back\n            ) AS s\n            CROSS JOIN (\n              SELECT\n                toString(properties.subscription_id) AS subscription_id,\n                person_id AS person,\n                toTimeZone(timestamp, 'UTC') AS ts,\n                toFloat(properties.mrr) AS mrr,\n                toString(properties.status) AS status\n              FROM events\n              WHERE event = 'subscription_updated'\n                AND properties.subscription_id IS NOT NULL\n                AND toMonday(toTimeZone(timestamp, 'UTC')) < toMonday(toTimeZone(now(), 'UTC'))\n            ) AS u\n            WHERE toMonday(u.ts) <= s.week - toIntervalWeek(s.weeks_back)\n            GROUP BY week, weeks_back, subscription_id\n          )\n        )\n        GROUP BY week, account\n      )\n      WHERE start_mrr > 0\n      GROUP BY week\n    ) AS r ON r.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Net revenue retention, trailing 12 months, for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: MRR at the week's end from customers who were paying at the end of the same week 52 weeks earlier ÷ their MRR then. A customer is the user_id on the subscription; customers who started since are left out, and those who left count as zero.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    snaps AS (\n      SELECT w.week, b.weeks_back, w.week + 7 * (1 - b.weeks_back) AS cutoff\n      FROM weeks AS w\n      CROSS JOIN (VALUES (0), (52)) AS b(weeks_back)\n    ),\n    updates AS (\n      SELECT\n        properties->>'subscription_id' AS subscription_id,\n        user_id AS customer,\n        occurred_at AT TIME ZONE 'UTC' AS ts,\n        CASE WHEN properties->>'mrr' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr')::numeric END AS mrr,\n        properties->>'status' AS status\n      FROM events\n      WHERE event_name = 'subscription_updated'\n        AND properties->>'subscription_id' IS NOT NULL\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n    ),\n    latest AS (\n      SELECT DISTINCT ON (s.week, s.weeks_back, u.subscription_id) s.week, s.weeks_back, u.customer, u.mrr, u.status\n      FROM snaps AS s\n      JOIN updates AS u ON u.ts < s.cutoff\n      ORDER BY s.week, s.weeks_back, u.subscription_id, u.ts DESC\n    ),\n    customers AS (\n      SELECT\n        week,\n        customer,\n        coalesce(sum(mrr) FILTER (WHERE weeks_back = 52), 0) AS start_mrr,\n        coalesce(sum(mrr) FILTER (WHERE weeks_back = 0), 0) AS end_mrr\n      FROM latest\n      WHERE status IN ('active', 'past_due')\n      GROUP BY week, customer\n    ),\n    weekly AS (\n      SELECT week, sum(end_mrr) AS end_mrr, sum(start_mrr) AS start_mrr\n      FROM customers\n      WHERE start_mrr > 0\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      coalesce(r.end_mrr, 0) AS numerator,\n      coalesce(r.start_mrr, 0) AS denominator,\n      r.end_mrr / nullif(r.start_mrr, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS r ON r.week = w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Net revenue retention, trailing 12 months, for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: MRR at the week's end from customers who were paying at the end of the same week 52 weeks earlier ÷ their MRR then. A customer is the user_id on the subscription; customers who started since are left out, and those who left count as zero.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    snaps AS (\n      SELECT w.week, weeks_back, TIMESTAMP(DATE_ADD(w.week, INTERVAL (1 - weeks_back) WEEK)) AS cutoff\n      FROM weeks AS w\n      CROSS JOIN UNNEST([0, 52]) AS weeks_back\n    ),\n    updates AS (\n      SELECT\n        JSON_VALUE(properties, '$.subscription_id') AS subscription_id,\n        user_id AS customer,\n        occurred_at,\n        SAFE_CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64) AS mrr,\n        JSON_VALUE(properties, '$.status') AS status\n      FROM events\n      WHERE event_name = 'subscription_updated'\n        AND JSON_VALUE(properties, '$.subscription_id') IS NOT NULL\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    ),\n    latest AS (\n      SELECT s.week, s.weeks_back, u.customer, u.mrr, u.status\n      FROM snaps AS s\n      CROSS JOIN updates AS u\n      WHERE u.occurred_at < s.cutoff\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY s.week, s.weeks_back, u.subscription_id ORDER BY u.occurred_at DESC) = 1\n    ),\n    customers AS (\n      SELECT\n        week,\n        customer,\n        COALESCE(SUM(IF(weeks_back = 52, mrr, NULL)), 0) AS start_mrr,\n        COALESCE(SUM(IF(weeks_back = 0, mrr, NULL)), 0) AS end_mrr\n      FROM latest\n      WHERE status IN ('active', 'past_due')\n      GROUP BY week, customer\n    ),\n    weekly AS (\n      SELECT week, SUM(end_mrr) AS end_mrr, SUM(start_mrr) AS start_mrr\n      FROM customers\n      WHERE start_mrr > 0\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      COALESCE(r.end_mrr, 0) AS numerator,\n      COALESCE(r.start_mrr, 0) AS denominator,\n      SAFE_DIVIDE(r.end_mrr, r.start_mrr) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS r ON r.week = w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Net revenue retention, trailing 12 months, for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: MRR at the week's end from customers who were paying at the end of the same week 52 weeks earlier ÷ their MRR then. A customer is the user_id on the subscription; customers who started since are left out, and those who left count as zero.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    snaps AS (\n      SELECT w.week, b.weeks_back, DATEADD(week, 1 - b.weeks_back, w.week) AS cutoff\n      FROM weeks AS w\n      CROSS JOIN (VALUES (0), (52)) AS b (weeks_back)\n    ),\n    updates AS (\n      SELECT\n        properties:\"subscription_id\"::string AS subscription_id,\n        user_id AS customer,\n        occurred_at,\n        TRY_TO_DOUBLE(properties:\"mrr\"::string) AS mrr,\n        properties:\"status\"::string AS status\n      FROM events\n      WHERE event_name = 'subscription_updated'\n        AND properties:\"subscription_id\"::string IS NOT NULL\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n    ),\n    latest AS (\n      SELECT s.week, s.weeks_back, u.customer, u.mrr, u.status\n      FROM snaps AS s\n      JOIN updates AS u ON u.occurred_at < s.cutoff\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY s.week, s.weeks_back, u.subscription_id ORDER BY u.occurred_at DESC) = 1\n    ),\n    customers AS (\n      SELECT\n        week,\n        customer,\n        COALESCE(SUM(IFF(weeks_back = 52, mrr, NULL)), 0) AS start_mrr,\n        COALESCE(SUM(IFF(weeks_back = 0, mrr, NULL)), 0) AS end_mrr\n      FROM latest\n      WHERE status IN ('active', 'past_due')\n      GROUP BY week, customer\n    ),\n    weekly AS (\n      SELECT week, SUM(end_mrr) AS end_mrr, SUM(start_mrr) AS start_mrr\n      FROM customers\n      WHERE start_mrr > 0\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      COALESCE(r.end_mrr, 0) AS numerator,\n      COALESCE(r.start_mrr, 0) AS denominator,\n      r.end_mrr / NULLIF(r.start_mrr, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS r ON r.week = w.week\n    ORDER BY w.week;\n\nnoise:\n  type: process\n  min_denominator: 50\n  volume_unit: customers in the starting cohort\n  typical: 1.01\n\nexample:\n  business: saas\n  level: 1.01\n  volume: 1570\n  trend: 0\n\ndrivers:\n  - id: customer-ids\n    label: Customer ids\n    dropped:\n      check: Did a customer-id migration or a billing change split existing customers, so their MRR now looks new?\n      yes: Customers in the starting cohort show zero MRR while new customers with the same names or domains appear.\n    spiked:\n      check: Did accounts merge, attaching new subscriptions to customers from a year ago?\n      yes: Cohort customers gain MRR from subscriptions that started this year with no upgrade event.\n  - id: cohort-window\n    label: Which customers are in the window\n    dropped:\n      check: Did a strong cohort leave the starting window, or a weak one enter it?\n      yes: The move starts the week a big signup month from 12 months ago crosses the window edge, with no change in this week's behaviour.\n    spiked:\n      check: Did a weak cohort leave the starting window, or a strong one enter it?\n      yes: The move starts the week a cohort with unusual churn crosses the window edge, with no change in this week's behaviour.\n  - id: large-accounts\n    label: Large accounts\n    dropped:\n      check: Did one large customer churn or downgrade?\n      yes: Leaving out the ten largest customers, NRR is flat; one of them explains the move.\n    spiked:\n      check: Did one large customer expand?\n      yes: Leaving out the ten largest customers, NRR is flat; one big upgrade explains the move.\n  - id: churn\n    label: Churned MRR\n    metric: churned-mrr\n    feed: stripe\n    dropped:\n      check: Did more of last year's customers cancel or lapse for failed payments?\n      yes: Churned MRR from customers older than 12 months rises over the trailing quarter.\n    spiked:\n      check: Did cancellations among long-standing customers slow?\n      yes: Churned MRR from customers older than 12 months falls over the trailing quarter.\n  - id: contraction\n    label: Downgrades\n    breakdown: plan\n    dropped:\n      check: Are customers keeping the product but paying less, with fewer seats, cheaper plans or smaller commitments?\n      yes: Contraction among cohort customers rises while cancellations hold, often after their own budget cuts.\n    spiked:\n      check: Did downgrades slow, or was a downgrade path removed?\n      yes: Contraction among cohort customers falls; if a cheaper plan was removed, watch churn.\n  - id: expansion\n    label: Expansion\n    metric: expansion-mrr\n    dropped:\n      check: Are last year's customers adding fewer seats, upgrades and add-ons?\n      yes: Expansion MRR from customers older than 12 months falls over the trailing quarter.\n    spiked:\n      check: Did upgrades, seat growth or a price increase lift what last year's customers pay?\n      yes: Expansion from cohort customers rises; a price increase shows as many accounts rising by the same percentage.\n\ndiagnose_order: [customer-ids, cohort-window, large-accounts, churn, contraction, expansion]\n\nrelated: [gross-revenue-retention, expansion-mrr, churned-mrr, logo-churn-rate, mrr]\n\nprose:\n  why_it_matters: >-\n    Net revenue retention asks whether last year's customers pay more or less today, with no help\n    from new sales. Above 100% the existing base grows on its own; at 101% NRR and 88% gross\n    retention, churn and downgrades take 12% a year and expansion from the customers who stay\n    wins back 13%. It is a trailing-year figure that moves slowly by design, so a one-point move\n    is worth explaining.\n  pitfalls:\n    - A monthly NRR and a trailing 12-month NRR on a fixed cohort are different numbers, and compounding the monthly one doesn't give the annual. This spec uses the 12-month fixed cohort that public SaaS companies report.\n    - New customers stay out of both sides until they are a year old. Including them turns NRR into MRR growth.\n    - Measuring per subscription instead of per customer counts a plan change done as cancel and resubscribe as churn, and the new subscription never enters the cohort.\n    - At a few thousand customers, one large account can move NRR by several points. Report it with and without the largest customers.\n    - A price increase lifts NRR once, for a year. Note the week it reaches renewals, or it reads as a lasting improvement in expansion.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"net-revenue-retention","name":"Net revenue retention","aliases":["NRR","NDR","Net dollar retention","Net revenue retention rate","Net retention"],"family":"subscription","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The MRR today from customers who were paying 12 months ago, as a share of what they paid then, after expansion, contraction and churn.","formula":"MRR at this week's end from customers paying 52 weeks earlier ÷ their MRR then; customers who started since are left out"},"events":[{"name":"subscription_updated","description":"Any change to a subscription's plan, quantity, discount or status, with its new monthly amount.","also_called":["customer.subscription.updated","Subscription Updated","subscription_changed"],"properties":[{"name":"subscription_id","description":"The billing system's subscription id."},{"name":"mrr","description":"The subscription's monthly amount after the change, after discounts, before tax."},{"name":"status","description":"active, trialing, past_due or canceled."}]}],"numerator":{"label":"MRR now from customers paying a year ago","aggregate":"sum","event":"subscription_updated","property":"mrr"},"queries":{"hogql":"-- Net revenue retention, trailing 12 months, for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: MRR at the week's end from customers who were paying at the end of the same week 52 weeks earlier ÷ their MRR then. A customer is the person on the subscription; customers who started since are left out, and those who left count as zero.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(r.end_total, 0) AS numerator,\n  coalesce(r.start_total, 0) AS denominator,\n  if(denominator = 0, NULL, numerator / denominator) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, sum(end_mrr) AS end_total, sum(start_mrr) AS start_total\n  FROM (\n    SELECT\n      week,\n      account,\n      coalesce(sumIf(sub_mrr, weeks_back = 52), 0) AS start_mrr,\n      coalesce(sumIf(sub_mrr, weeks_back = 0), 0) AS end_mrr\n    FROM (\n      SELECT\n        week,\n        weeks_back,\n        tupleElement(latest, 1) AS account,\n        if(tupleElement(latest, 3) IN ('active', 'past_due'), tupleElement(latest, 2), 0) AS sub_mrr\n      FROM (\n        SELECT s.week AS week, s.weeks_back AS weeks_back, u.subscription_id AS subscription_id, argMax(tuple(u.person, u.mrr, u.status), u.ts) AS latest\n        FROM (\n          SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week, arrayJoin([0, 52]) AS weeks_back\n        ) AS s\n        CROSS JOIN (\n          SELECT\n            toString(properties.subscription_id) AS subscription_id,\n            person_id AS person,\n            toTimeZone(timestamp, 'UTC') AS ts,\n            toFloat(properties.mrr) AS mrr,\n            toString(properties.status) AS status\n          FROM events\n          WHERE event = 'subscription_updated'\n            AND properties.subscription_id IS NOT NULL\n            AND toMonday(toTimeZone(timestamp, 'UTC')) < toMonday(toTimeZone(now(), 'UTC'))\n        ) AS u\n        WHERE toMonday(u.ts) <= s.week - toIntervalWeek(s.weeks_back)\n        GROUP BY week, weeks_back, subscription_id\n      )\n    )\n    GROUP BY week, account\n  )\n  WHERE start_mrr > 0\n  GROUP BY week\n) AS r ON r.week = w.week\nORDER BY week","postgres":"-- Net revenue retention, trailing 12 months, for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: MRR at the week's end from customers who were paying at the end of the same week 52 weeks earlier ÷ their MRR then. A customer is the user_id on the subscription; customers who started since are left out, and those who left count as zero.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nsnaps AS (\n  SELECT w.week, b.weeks_back, w.week + 7 * (1 - b.weeks_back) AS cutoff\n  FROM weeks AS w\n  CROSS JOIN (VALUES (0), (52)) AS b(weeks_back)\n),\nupdates AS (\n  SELECT\n    properties->>'subscription_id' AS subscription_id,\n    user_id AS customer,\n    occurred_at AT TIME ZONE 'UTC' AS ts,\n    CASE WHEN properties->>'mrr' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr')::numeric END AS mrr,\n    properties->>'status' AS status\n  FROM events\n  WHERE event_name = 'subscription_updated'\n    AND properties->>'subscription_id' IS NOT NULL\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n),\nlatest AS (\n  SELECT DISTINCT ON (s.week, s.weeks_back, u.subscription_id) s.week, s.weeks_back, u.customer, u.mrr, u.status\n  FROM snaps AS s\n  JOIN updates AS u ON u.ts < s.cutoff\n  ORDER BY s.week, s.weeks_back, u.subscription_id, u.ts DESC\n),\ncustomers AS (\n  SELECT\n    week,\n    customer,\n    coalesce(sum(mrr) FILTER (WHERE weeks_back = 52), 0) AS start_mrr,\n    coalesce(sum(mrr) FILTER (WHERE weeks_back = 0), 0) AS end_mrr\n  FROM latest\n  WHERE status IN ('active', 'past_due')\n  GROUP BY week, customer\n),\nweekly AS (\n  SELECT week, sum(end_mrr) AS end_mrr, sum(start_mrr) AS start_mrr\n  FROM customers\n  WHERE start_mrr > 0\n  GROUP BY week\n)\nSELECT\n  w.week,\n  coalesce(r.end_mrr, 0) AS numerator,\n  coalesce(r.start_mrr, 0) AS denominator,\n  r.end_mrr / nullif(r.start_mrr, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS r ON r.week = w.week\nORDER BY w.week;","bigquery":"-- Net revenue retention, trailing 12 months, for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: MRR at the week's end from customers who were paying at the end of the same week 52 weeks earlier ÷ their MRR then. A customer is the user_id on the subscription; customers who started since are left out, and those who left count as zero.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nsnaps AS (\n  SELECT w.week, weeks_back, TIMESTAMP(DATE_ADD(w.week, INTERVAL (1 - weeks_back) WEEK)) AS cutoff\n  FROM weeks AS w\n  CROSS JOIN UNNEST([0, 52]) AS weeks_back\n),\nupdates AS (\n  SELECT\n    JSON_VALUE(properties, '$.subscription_id') AS subscription_id,\n    user_id AS customer,\n    occurred_at,\n    SAFE_CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64) AS mrr,\n    JSON_VALUE(properties, '$.status') AS status\n  FROM events\n  WHERE event_name = 'subscription_updated'\n    AND JSON_VALUE(properties, '$.subscription_id') IS NOT NULL\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n),\nlatest AS (\n  SELECT s.week, s.weeks_back, u.customer, u.mrr, u.status\n  FROM snaps AS s\n  CROSS JOIN updates AS u\n  WHERE u.occurred_at < s.cutoff\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY s.week, s.weeks_back, u.subscription_id ORDER BY u.occurred_at DESC) = 1\n),\ncustomers AS (\n  SELECT\n    week,\n    customer,\n    COALESCE(SUM(IF(weeks_back = 52, mrr, NULL)), 0) AS start_mrr,\n    COALESCE(SUM(IF(weeks_back = 0, mrr, NULL)), 0) AS end_mrr\n  FROM latest\n  WHERE status IN ('active', 'past_due')\n  GROUP BY week, customer\n),\nweekly AS (\n  SELECT week, SUM(end_mrr) AS end_mrr, SUM(start_mrr) AS start_mrr\n  FROM customers\n  WHERE start_mrr > 0\n  GROUP BY week\n)\nSELECT\n  w.week,\n  COALESCE(r.end_mrr, 0) AS numerator,\n  COALESCE(r.start_mrr, 0) AS denominator,\n  SAFE_DIVIDE(r.end_mrr, r.start_mrr) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS r ON r.week = w.week\nORDER BY w.week;","snowflake":"-- Net revenue retention, trailing 12 months, for each of the last 26 complete weeks (Monday 00:00 UTC), oldest first: MRR at the week's end from customers who were paying at the end of the same week 52 weeks earlier ÷ their MRR then. A customer is the user_id on the subscription; customers who started since are left out, and those who left count as zero.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nsnaps AS (\n  SELECT w.week, b.weeks_back, DATEADD(week, 1 - b.weeks_back, w.week) AS cutoff\n  FROM weeks AS w\n  CROSS JOIN (VALUES (0), (52)) AS b (weeks_back)\n),\nupdates AS (\n  SELECT\n    properties:\"subscription_id\"::string AS subscription_id,\n    user_id AS customer,\n    occurred_at,\n    TRY_TO_DOUBLE(properties:\"mrr\"::string) AS mrr,\n    properties:\"status\"::string AS status\n  FROM events\n  WHERE event_name = 'subscription_updated'\n    AND properties:\"subscription_id\"::string IS NOT NULL\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n),\nlatest AS (\n  SELECT s.week, s.weeks_back, u.customer, u.mrr, u.status\n  FROM snaps AS s\n  JOIN updates AS u ON u.occurred_at < s.cutoff\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY s.week, s.weeks_back, u.subscription_id ORDER BY u.occurred_at DESC) = 1\n),\ncustomers AS (\n  SELECT\n    week,\n    customer,\n    COALESCE(SUM(IFF(weeks_back = 52, mrr, NULL)), 0) AS start_mrr,\n    COALESCE(SUM(IFF(weeks_back = 0, mrr, NULL)), 0) AS end_mrr\n  FROM latest\n  WHERE status IN ('active', 'past_due')\n  GROUP BY week, customer\n),\nweekly AS (\n  SELECT week, SUM(end_mrr) AS end_mrr, SUM(start_mrr) AS start_mrr\n  FROM customers\n  WHERE start_mrr > 0\n  GROUP BY week\n)\nSELECT\n  w.week,\n  COALESCE(r.end_mrr, 0) AS numerator,\n  COALESCE(r.start_mrr, 0) AS denominator,\n  r.end_mrr / NULLIF(r.start_mrr, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS r ON r.week = w.week\nORDER BY w.week;"},"noise":{"type":"process","min_denominator":50,"volume_unit":"customers in the starting cohort","typical":1.01},"example":{"business":"saas","level":1.01,"volume":1570,"trend":0},"drivers":[{"id":"customer-ids","label":"Customer ids","dropped":{"check":"Did a customer-id migration or a billing change split existing customers, so their MRR now looks new?","yes":"Customers in the starting cohort show zero MRR while new customers with the same names or domains appear."},"spiked":{"check":"Did accounts merge, attaching new subscriptions to customers from a year ago?","yes":"Cohort customers gain MRR from subscriptions that started this year with no upgrade event."}},{"id":"cohort-window","label":"Which customers are in the window","dropped":{"check":"Did a strong cohort leave the starting window, or a weak one enter it?","yes":"The move starts the week a big signup month from 12 months ago crosses the window edge, with no change in this week's behaviour."},"spiked":{"check":"Did a weak cohort leave the starting window, or a strong one enter it?","yes":"The move starts the week a cohort with unusual churn crosses the window edge, with no change in this week's behaviour."}},{"id":"large-accounts","label":"Large accounts","dropped":{"check":"Did one large customer churn or downgrade?","yes":"Leaving out the ten largest customers, NRR is flat; one of them explains the move."},"spiked":{"check":"Did one large customer expand?","yes":"Leaving out the ten largest customers, NRR is flat; one big upgrade explains the move."}},{"id":"churn","label":"Churned MRR","metric":"churned-mrr","feed":"stripe","dropped":{"check":"Did more of last year's customers cancel or lapse for failed payments?","yes":"Churned MRR from customers older than 12 months rises over the trailing quarter."},"spiked":{"check":"Did cancellations among long-standing customers slow?","yes":"Churned MRR from customers older than 12 months falls over the trailing quarter."}},{"id":"contraction","label":"Downgrades","breakdown":"plan","dropped":{"check":"Are customers keeping the product but paying less, with fewer seats, cheaper plans or smaller commitments?","yes":"Contraction among cohort customers rises while cancellations hold, often after their own budget cuts."},"spiked":{"check":"Did downgrades slow, or was a downgrade path removed?","yes":"Contraction among cohort customers falls; if a cheaper plan was removed, watch churn."}},{"id":"expansion","label":"Expansion","metric":"expansion-mrr","dropped":{"check":"Are last year's customers adding fewer seats, upgrades and add-ons?","yes":"Expansion MRR from customers older than 12 months falls over the trailing quarter."},"spiked":{"check":"Did upgrades, seat growth or a price increase lift what last year's customers pay?","yes":"Expansion from cohort customers rises; a price increase shows as many accounts rising by the same percentage."}}],"diagnose_order":["customer-ids","cohort-window","large-accounts","churn","contraction","expansion"],"related":["gross-revenue-retention","expansion-mrr","churned-mrr","logo-churn-rate","mrr"],"prose":{"why_it_matters":"Net revenue retention asks whether last year's customers pay more or less today, with no help from new sales. Above 100% the existing base grows on its own; at 101% NRR and 88% gross retention, churn and downgrades take 12% a year and expansion from the customers who stay wins back 13%. It is a trailing-year figure that moves slowly by design, so a one-point move is worth explaining.","pitfalls":["A monthly NRR and a trailing 12-month NRR on a fixed cohort are different numbers, and compounding the monthly one doesn't give the annual. This spec uses the 12-month fixed cohort that public SaaS companies report.","New customers stay out of both sides until they are a year old. Including them turns NRR into MRR growth.","Measuring per subscription instead of per customer counts a plan change done as cancel and resubscribe as churn, and the new subscription never enters the cohort.","At a few thousand customers, one large account can move NRR by several points. Report it with and without the largest customers.","A price increase lifts NRR once, for a year. Note the week it reaches renewals, or it reads as a lasting improvement in expansion."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "net-revenue": { yaml: "id: net-revenue\nname: Net revenue\naliases:\n  - Weekly revenue\n  - Net sales\nfamily: revenue\ncatalog_id: revenue\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: Order revenue after discounts from orders paid this week, minus refunds issued this week, before tax and shipping.\n  formula: Sum of order totals after discounts − refunds issued in the week, both excluding tax and shipping\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n  - name: order_refunded\n    description: A refund issued against an earlier order, full or partial.\n    also_called: [refund, Order Refunded, charge.refunded]\n    properties:\n      - name: order_id\n        description: The order refunded.\n      - name: amount\n        description: The refunded amount, excluding tax and shipping.\n\nnumerator:\n  label: Net revenue\n  aggregate: sum\n  event: order_completed\n  property: total\nsubtract:\n  label: Refunds issued\n  aggregate: sum\n  event: order_refunded\n  property: amount\n\nnoise:\n  type: compound\n  cv: 0.9\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 260000\n\nexample:\n  business: store\n  level: 1290000\n  volume: 13300\n  trend: 0.2\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did order events stop arriving from one checkout, app or country, or did total change meaning?\n      yes: The store's own sales report holds while recorded revenue falls from one day.\n    spiked:\n      check: Are orders recorded twice, test orders included, or totals arriving in another currency or with tax added?\n      yes: Recorded revenue exceeds the store's sales report, or the same order_id appears more than once.\n  - id: orders\n    label: Orders\n    metric: orders\n    dropped:\n      check: Did the number of orders fall, or only what each order is worth?\n      yes: Orders fall by about as much as revenue while order value holds.\n    spiked:\n      check: Is the rise in the number of orders rather than their size?\n      yes: Orders rise by about as much as revenue while order value holds.\n  - id: order-value\n    label: Order value\n    metric: aov\n    dropped:\n      check: Did the average order shrink, from a discount, a mix shift or fewer items per order?\n      yes: Order value falls while the number of orders holds.\n    spiked:\n      check: Did a few large orders or a price rise lift the average?\n      yes: Order value jumps, often driven by a handful of orders far above the usual size.\n  - id: traffic\n    label: Traffic\n    metric: sessions\n    feed: google-search\n    dropped:\n      check: Did fewer people arrive, and from which channel?\n      yes: Sessions fall in one channel by about as much as orders do.\n    spiked:\n      check: Did a campaign, press mention or ranking change bring more visitors?\n      yes: Sessions rise in one channel, and conversion holds.\n  - id: conversion\n    label: Store conversion\n    metric: conversion-rate\n    dropped:\n      check: Did the share of visits that buy fall, and at which step?\n      yes: Conversion falls while traffic holds; one funnel step explains most of it.\n    spiked:\n      check: Did more visits buy, and at which step?\n      yes: Conversion rises while traffic holds; one funnel step explains most of it.\n  - id: refunds\n    label: Refunds\n    metric: refund-rate\n    dropped:\n      check: Did refunds spike, from a bad batch, a delivery failure or a chargeback wave?\n      yes: Gross sales hold while refunds rise.\n    spiked:\n      check: Did refunds fall back after an unusual week?\n      yes: Refunds return to their usual share and net revenue recovers.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Is last week's comparison a sale, holiday or payday week?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this week a sale, holiday or payday week?\n      yes: The same week last year shows the same jump once aligned on the event.\n\ndiagnose_order: [tracking, calendar, orders, order-value, refunds, traffic, conversion]\n\nrelated: [orders, aov, conversion-rate, gross-sales, refund-rate]\n\nprose:\n  why_it_matters: >-\n    Revenue is the number everyone reads first, which is why it is the worst number to act on\n    alone. It is orders times order value, and orders are traffic times conversion; a move in\n    revenue is only useful once you know which of those moved. Most weeks, nothing did, and the\n    honest answer is that the change is the ordinary wobble of thousands of orders of different sizes.\n  pitfalls:\n    - Refunds are subtracted in the week they are issued, not the week of the order they belong to, as in Shopify's net sales. A big sale week's returns land in the weeks after it.\n    - Including tax and shipping makes revenue move with tax rules and carrier prices you don't control.\n    - A few very large orders can move a small store's week by 10% or more. Check the order count before the total.\n    - Revenue in several currencies needs a constant exchange rate across the weeks being compared, or currency moves look like sales.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"net-revenue","name":"Net revenue","aliases":["Weekly revenue","Net sales"],"family":"revenue","catalog_id":"revenue","kind":"currency","polarity":"up-is-good","definition":{"one_line":"Order revenue after discounts from orders paid this week, minus refunds issued this week, before tax and shipping.","formula":"Sum of order totals after discounts − refunds issued in the week, both excluding tax and shipping"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."},{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."}]},{"name":"order_refunded","description":"A refund issued against an earlier order, full or partial.","also_called":["refund","Order Refunded","charge.refunded"],"properties":[{"name":"order_id","description":"The order refunded."},{"name":"amount","description":"The refunded amount, excluding tax and shipping."}]}],"numerator":{"label":"Net revenue","aggregate":"sum","event":"order_completed","property":"total"},"subtract":{"label":"Refunds issued","aggregate":"sum","event":"order_refunded","property":"amount"},"noise":{"type":"compound","cv":0.9,"min_denominator":50,"volume_unit":"orders a week","typical":260000},"example":{"business":"store","level":1290000,"volume":13300,"trend":0.2,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did order events stop arriving from one checkout, app or country, or did total change meaning?","yes":"The store's own sales report holds while recorded revenue falls from one day."},"spiked":{"check":"Are orders recorded twice, test orders included, or totals arriving in another currency or with tax added?","yes":"Recorded revenue exceeds the store's sales report, or the same order_id appears more than once."}},{"id":"orders","label":"Orders","metric":"orders","dropped":{"check":"Did the number of orders fall, or only what each order is worth?","yes":"Orders fall by about as much as revenue while order value holds."},"spiked":{"check":"Is the rise in the number of orders rather than their size?","yes":"Orders rise by about as much as revenue while order value holds."}},{"id":"order-value","label":"Order value","metric":"aov","dropped":{"check":"Did the average order shrink, from a discount, a mix shift or fewer items per order?","yes":"Order value falls while the number of orders holds."},"spiked":{"check":"Did a few large orders or a price rise lift the average?","yes":"Order value jumps, often driven by a handful of orders far above the usual size."}},{"id":"traffic","label":"Traffic","metric":"sessions","feed":"google-search","dropped":{"check":"Did fewer people arrive, and from which channel?","yes":"Sessions fall in one channel by about as much as orders do."},"spiked":{"check":"Did a campaign, press mention or ranking change bring more visitors?","yes":"Sessions rise in one channel, and conversion holds."}},{"id":"conversion","label":"Store conversion","metric":"conversion-rate","dropped":{"check":"Did the share of visits that buy fall, and at which step?","yes":"Conversion falls while traffic holds; one funnel step explains most of it."},"spiked":{"check":"Did more visits buy, and at which step?","yes":"Conversion rises while traffic holds; one funnel step explains most of it."}},{"id":"refunds","label":"Refunds","metric":"refund-rate","dropped":{"check":"Did refunds spike, from a bad batch, a delivery failure or a chargeback wave?","yes":"Gross sales hold while refunds rise."},"spiked":{"check":"Did refunds fall back after an unusual week?","yes":"Refunds return to their usual share and net revenue recovers."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Is last week's comparison a sale, holiday or payday week?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this week a sale, holiday or payday week?","yes":"The same week last year shows the same jump once aligned on the event."}}],"diagnose_order":["tracking","calendar","orders","order-value","refunds","traffic","conversion"],"related":["orders","aov","conversion-rate","gross-sales","refund-rate"],"prose":{"why_it_matters":"Revenue is the number everyone reads first, which is why it is the worst number to act on alone. It is orders times order value, and orders are traffic times conversion; a move in revenue is only useful once you know which of those moved. Most weeks, nothing did, and the honest answer is that the change is the ordinary wobble of thousands of orders of different sizes.","pitfalls":["Refunds are subtracted in the week they are issued, not the week of the order they belong to, as in Shopify's net sales. A big sale week's returns land in the weeks after it.","Including tax and shipping makes revenue move with tax rules and carrier prices you don't control.","A few very large orders can move a small store's week by 10% or more. Check the order count before the total.","Revenue in several currencies needs a constant exchange rate across the weeks being compared, or currency moves look like sales."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "new-customer-revenue-share": { yaml: "id: new-customer-revenue-share\nname: New customer revenue share\naliases:\n  - First-order revenue share\n  - Revenue from new customers\n  - New vs returning revenue\nfamily: customers\nkind: rate\npolarity: down-is-good\n\ndefinition:\n  one_line: The share of this week's order revenue that came from customers' first orders.\n  formula: Order totals of first orders ÷ order totals of all orders, after discounts, before tax, shipping and refunds\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: is_first_order\n        description: True when the store has no earlier order from this customer, from its own customer records.\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n      - name: coupon\n        description: The discount code used, if any.\n\nnumerator:\n  label: Revenue from first orders\n  aggregate: sum\n  event: order_completed\n  property: total\n  where:\n    - property: is_first_order\n      op: eq\n      value: true\ndenominator:\n  label: Revenue from all orders\n  aggregate: sum\n  event: order_completed\n  property: total\n  where:\n    - property: is_first_order\n      op: is_set\n\nnoise:\n  type: process\n  min_denominator: 100\n  volume_unit: orders a week\n  typical: 0.58\n\nexample:\n  business: store\n  level: 0.58\n  volume: 13300\n  trend: -0.02\n  season: 0.5\n\ndrivers:\n  - id: tracking\n    label: First-order flag\n    dropped:\n      check: Did an import or customer merge start marking first orders as repeat?\n      yes: The share falls on one day while new customers in the store admin hold.\n    spiked:\n      check: Did a migration, a checkout app or a guest-checkout change reset order history, so returning buyers look new?\n      yes: The share jumps overnight while total revenue barely moves.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Is this the quiet week after a sale, or a loyalty or members-only event?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this a sale, holiday or launch week that brings first-time buyers?\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: new-customers\n    label: New customers\n    metric: new-customers\n    dropped:\n      check: Did fewer first-time buyers arrive, for example after paid spend was cut?\n      yes: New customers fall while returning customers hold.\n    spiked:\n      check: Did a campaign, a launch or a press mention bring a wave of first-time buyers?\n      yes: New customers rise while returning customers hold.\n  - id: returning-customers\n    label: Returning customers\n    metric: returning-customers\n    dropped:\n      check: Did a campaign or a restock bring existing customers back?\n      yes: Returning customers rise while new customers hold; the share fell for a good reason.\n    spiked:\n      check: Did existing customers stop coming back, from a missed email or a stock-out?\n      yes: Returning customers fall while new customers hold; the share rose by subtraction.\n  - id: first-order-value\n    label: First-order offers\n    breakdown: coupon\n    dropped:\n      check: Did a welcome discount deepen, making first orders smaller?\n      yes: First-order count holds while revenue per first order falls, concentrated in one code.\n    spiked:\n      check: Did a welcome discount end, or a bundle lift first-order value?\n      yes: First-order count holds while revenue per first order rises.\n\ndiagnose_order: [tracking, calendar, new-customers, returning-customers, first-order-value]\n\nrelated: [new-customers, repeat-order-share, returning-customers, net-revenue, ncac]\n\nprose:\n  why_it_matters: >-\n    New customer revenue share splits revenue into what the store bought this week and what it kept.\n    A store that earns most of its revenue from first orders depends on acquisition spend for its\n    growth, and its revenue falls when spend does; at Northwind the share is about 58%. Read it with\n    repeat order share, its mirror in order counts.\n  pitfalls:\n    - First orders are often smaller because of welcome discounts, so this share runs a few points below the share of orders from new customers. Both are right; don't mix them.\n    - The share moves when either side does. It climbs when existing customers stop buying and falls when acquisition stalls, so check new and returning customers before calling a move good or bad.\n    - It is a share of order totals before refunds, which can't be split by first or repeat order in the week they are issued. A sale week with heavy returns overstates it.\n    - Orders without the first-order flag are left out of both sides. If many lack it, fix the tracking before reading the share.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"new-customer-revenue-share","name":"New customer revenue share","aliases":["First-order revenue share","Revenue from new customers","New vs returning revenue"],"family":"customers","kind":"rate","polarity":"down-is-good","definition":{"one_line":"The share of this week's order revenue that came from customers' first orders.","formula":"Order totals of first orders ÷ order totals of all orders, after discounts, before tax, shipping and refunds"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"is_first_order","description":"True when the store has no earlier order from this customer, from its own customer records."},{"name":"total","description":"Order value after discounts, before tax and shipping."},{"name":"coupon","description":"The discount code used, if any."}]}],"numerator":{"label":"Revenue from first orders","aggregate":"sum","event":"order_completed","property":"total","where":[{"property":"is_first_order","op":"eq","value":true}]},"denominator":{"label":"Revenue from all orders","aggregate":"sum","event":"order_completed","property":"total","where":[{"property":"is_first_order","op":"is_set"}]},"noise":{"type":"process","min_denominator":100,"volume_unit":"orders a week","typical":0.58},"example":{"business":"store","level":0.58,"volume":13300,"trend":-0.02,"season":0.5},"drivers":[{"id":"tracking","label":"First-order flag","dropped":{"check":"Did an import or customer merge start marking first orders as repeat?","yes":"The share falls on one day while new customers in the store admin hold."},"spiked":{"check":"Did a migration, a checkout app or a guest-checkout change reset order history, so returning buyers look new?","yes":"The share jumps overnight while total revenue barely moves."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Is this the quiet week after a sale, or a loyalty or members-only event?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this a sale, holiday or launch week that brings first-time buyers?","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"new-customers","label":"New customers","metric":"new-customers","dropped":{"check":"Did fewer first-time buyers arrive, for example after paid spend was cut?","yes":"New customers fall while returning customers hold."},"spiked":{"check":"Did a campaign, a launch or a press mention bring a wave of first-time buyers?","yes":"New customers rise while returning customers hold."}},{"id":"returning-customers","label":"Returning customers","metric":"returning-customers","dropped":{"check":"Did a campaign or a restock bring existing customers back?","yes":"Returning customers rise while new customers hold; the share fell for a good reason."},"spiked":{"check":"Did existing customers stop coming back, from a missed email or a stock-out?","yes":"Returning customers fall while new customers hold; the share rose by subtraction."}},{"id":"first-order-value","label":"First-order offers","breakdown":"coupon","dropped":{"check":"Did a welcome discount deepen, making first orders smaller?","yes":"First-order count holds while revenue per first order falls, concentrated in one code."},"spiked":{"check":"Did a welcome discount end, or a bundle lift first-order value?","yes":"First-order count holds while revenue per first order rises."}}],"diagnose_order":["tracking","calendar","new-customers","returning-customers","first-order-value"],"related":["new-customers","repeat-order-share","returning-customers","net-revenue","ncac"],"prose":{"why_it_matters":"New customer revenue share splits revenue into what the store bought this week and what it kept. A store that earns most of its revenue from first orders depends on acquisition spend for its growth, and its revenue falls when spend does; at Northwind the share is about 58%. Read it with repeat order share, its mirror in order counts.","pitfalls":["First orders are often smaller because of welcome discounts, so this share runs a few points below the share of orders from new customers. Both are right; don't mix them.","The share moves when either side does. It climbs when existing customers stop buying and falls when acquisition stalls, so check new and returning customers before calling a move good or bad.","It is a share of order totals before refunds, which can't be split by first or repeat order in the week they are issued. A sale week with heavy returns overstates it.","Orders without the first-order flag are left out of both sides. If many lack it, fix the tracking before reading the share."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "new-customers": { yaml: "id: new-customers\nname: New customers\naliases:\n  - First-time customers\n  - First-time buyers\n  - New buyers\nfamily: customers\ncatalog_id: new_customers\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: Customers placing their first ever order this week, each counted once.\n  formula: Distinct customers with an order flagged as their first, by order week\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: is_first_order\n        description: True when the store has no earlier order from this customer, from its own customer records.\n      - name: customer_id\n        description: The store's customer id, shared by guest and logged-in orders with the same email.\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n      - name: coupon\n        description: The discount code used, if any.\n\nnumerator:\n  label: Customers with a first order\n  aggregate: unique_users\n  event: order_completed\n  where:\n    - property: is_first_order\n      op: eq\n      value: true\n\nnoise:\n  type: poisson\n  min_denominator: 30\n  volume_unit: new customers a week\n  typical: 8000\n\nexample:\n  business: store\n  level: 8100\n  volume: 8100\n  trend: 0.18\n\ndrivers:\n  - id: tracking\n    label: First-order flag\n    dropped:\n      check: Did a checkout app, store migration or tracking change stop the first-order flag being set?\n      yes: Total orders hold while orders flagged as first fall, and the store's own new-customer report disagrees.\n    spiked:\n      check: Did a migration, customer import or guest-checkout change reset order history, so returning buyers look new?\n      yes: New customers jump while total orders barely move and returning customers fall by about the same number.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Was last week a sale or holiday week, or is this the lull after one?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this week Black Friday, a holiday or a store-wide sale?\n      yes: The same week last year shows the same jump; sale weeks bring more first-time buyers than any others.\n  - id: paid-acquisition\n    label: Paid acquisition\n    metric: ad-spend\n    feed: ad-platforms\n    dropped:\n      check: Did ad spend fall, a campaign pause, or an ad account get limited or disapproved?\n      yes: Spend or impressions fall in one channel on the same days that first orders do.\n    spiked:\n      check: Did spend rise or a new campaign launch?\n      yes: New customers rise with spend in one channel; check new customer CAC to see what they cost.\n  - id: offers\n    label: First-order offers\n    breakdown: coupon\n    dropped:\n      check: Did a welcome discount, free-shipping offer or affiliate code end?\n      yes: First orders using that code fall to near zero while other first orders hold.\n    spiked:\n      check: Is one code, an influencer or an affiliate behind the jump?\n      yes: A single coupon accounts for most of the extra first orders.\n  - id: traffic\n    label: New visitors\n    metric: sessions\n    feed: google-search\n    dropped:\n      check: Did fewer people arrive, and from which channel?\n      yes: Sessions fall in one channel, often organic search after a ranking change, by about as much as first orders.\n    spiked:\n      check: Did a press mention, a viral post or a ranking gain bring new visitors?\n      yes: Sessions rise from one referrer or channel in the days first orders do.\n  - id: conversion\n    label: Store conversion\n    metric: conversion-rate\n    dropped:\n      check: Did the share of visits that buy fall, and at which step?\n      yes: Traffic holds while conversion falls; one funnel step explains most of it.\n    spiked:\n      check: Did a site change or a price cut make more first-time visitors buy?\n      yes: Traffic holds while conversion rises from the day the change shipped.\n\ndiagnose_order: [tracking, calendar, paid-acquisition, offers, traffic, conversion]\n\nrelated: [returning-customers, repeat-order-share, ncac, second-order-rate, new-customer-revenue-share]\n\nprose:\n  why_it_matters: >-\n    New customers are the part of demand a store has to win again every week; at Northwind they\n    place about 62% of orders. The count is also the denominator of acquisition cost, so a miscount\n    moves new customer CAC, LTV to CAC and payback with it. Read it with what it cost: twice the new\n    customers at three times the price is not growth.\n  pitfalls:\n    - Deriving the first order from analytics history makes every buyer look new for months after tracking starts. Use the store's own records, such as Shopify's customer order count, to set the flag.\n    - Guest checkouts under a new email, or a customer who changes email, count as new again. Match customers on the store's customer id, not the browser.\n    - A store migration, a new checkout app or a customer import can reset order history and turn returning buyers into new ones overnight; total orders stay flat while this jumps.\n    - Sale weeks fill this number with discount buyers who rarely come back. Compare Black Friday with last year's Black Friday, and judge the cohort later by its second order rate.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"new-customers","name":"New customers","aliases":["First-time customers","First-time buyers","New buyers"],"family":"customers","catalog_id":"new_customers","kind":"count","polarity":"up-is-good","definition":{"one_line":"Customers placing their first ever order this week, each counted once.","formula":"Distinct customers with an order flagged as their first, by order week"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"is_first_order","description":"True when the store has no earlier order from this customer, from its own customer records."},{"name":"customer_id","description":"The store's customer id, shared by guest and logged-in orders with the same email."},{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."},{"name":"coupon","description":"The discount code used, if any."}]}],"numerator":{"label":"Customers with a first order","aggregate":"unique_users","event":"order_completed","where":[{"property":"is_first_order","op":"eq","value":true}]},"noise":{"type":"poisson","min_denominator":30,"volume_unit":"new customers a week","typical":8000},"example":{"business":"store","level":8100,"volume":8100,"trend":0.18},"drivers":[{"id":"tracking","label":"First-order flag","dropped":{"check":"Did a checkout app, store migration or tracking change stop the first-order flag being set?","yes":"Total orders hold while orders flagged as first fall, and the store's own new-customer report disagrees."},"spiked":{"check":"Did a migration, customer import or guest-checkout change reset order history, so returning buyers look new?","yes":"New customers jump while total orders barely move and returning customers fall by about the same number."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Was last week a sale or holiday week, or is this the lull after one?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this week Black Friday, a holiday or a store-wide sale?","yes":"The same week last year shows the same jump; sale weeks bring more first-time buyers than any others."}},{"id":"paid-acquisition","label":"Paid acquisition","metric":"ad-spend","feed":"ad-platforms","dropped":{"check":"Did ad spend fall, a campaign pause, or an ad account get limited or disapproved?","yes":"Spend or impressions fall in one channel on the same days that first orders do."},"spiked":{"check":"Did spend rise or a new campaign launch?","yes":"New customers rise with spend in one channel; check new customer CAC to see what they cost."}},{"id":"offers","label":"First-order offers","breakdown":"coupon","dropped":{"check":"Did a welcome discount, free-shipping offer or affiliate code end?","yes":"First orders using that code fall to near zero while other first orders hold."},"spiked":{"check":"Is one code, an influencer or an affiliate behind the jump?","yes":"A single coupon accounts for most of the extra first orders."}},{"id":"traffic","label":"New visitors","metric":"sessions","feed":"google-search","dropped":{"check":"Did fewer people arrive, and from which channel?","yes":"Sessions fall in one channel, often organic search after a ranking change, by about as much as first orders."},"spiked":{"check":"Did a press mention, a viral post or a ranking gain bring new visitors?","yes":"Sessions rise from one referrer or channel in the days first orders do."}},{"id":"conversion","label":"Store conversion","metric":"conversion-rate","dropped":{"check":"Did the share of visits that buy fall, and at which step?","yes":"Traffic holds while conversion falls; one funnel step explains most of it."},"spiked":{"check":"Did a site change or a price cut make more first-time visitors buy?","yes":"Traffic holds while conversion rises from the day the change shipped."}}],"diagnose_order":["tracking","calendar","paid-acquisition","offers","traffic","conversion"],"related":["returning-customers","repeat-order-share","ncac","second-order-rate","new-customer-revenue-share"],"prose":{"why_it_matters":"New customers are the part of demand a store has to win again every week; at Northwind they place about 62% of orders. The count is also the denominator of acquisition cost, so a miscount moves new customer CAC, LTV to CAC and payback with it. Read it with what it cost: twice the new customers at three times the price is not growth.","pitfalls":["Deriving the first order from analytics history makes every buyer look new for months after tracking starts. Use the store's own records, such as Shopify's customer order count, to set the flag.","Guest checkouts under a new email, or a customer who changes email, count as new again. Match customers on the store's customer id, not the browser.","A store migration, a new checkout app or a customer import can reset order history and turn returning buyers into new ones overnight; total orders stay flat while this jumps.","Sale weeks fill this number with discount buyers who rarely come back. Compare Black Friday with last year's Black Friday, and judge the cohort later by its second order rate."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "new-mrr": { yaml: "id: new-mrr\nname: New MRR\naliases:\n  - New business MRR\n  - New monthly recurring revenue\n  - New subscription MRR\nfamily: subscription\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: The monthly recurring revenue added by subscriptions that made their first payment this week.\n  formula: Sum of the monthly amounts of subscriptions whose first paid period started this week, annual plans divided by twelve\n\nevents:\n  - name: subscription_started\n    description: A subscription's first paid period began, sent by the billing system when the first payment succeeds; not the trial start.\n    also_called: [Subscription Started, subscription_activated, invoice.paid (first)]\n    properties:\n      - name: subscription_id\n        description: The billing system's subscription id.\n      - name: mrr\n        description: The subscription's monthly amount after discounts, before tax; annual plans divided by twelve.\n      - name: plan\n        description: The plan the subscription started on.\n\nnumerator:\n  label: New MRR\n  aggregate: sum\n  event: subscription_started\n  property: mrr\n\nnoise:\n  type: compound\n  cv: 0.9\n  min_denominator: 10\n  volume_unit: new subscriptions a week\n  typical: 2000\n  reference_volumes: [10, 40, 150, 600]\n\nexample:\n  business: saas\n  level: 1920\n  volume: 29\n  trend: 0.3\n\ndrivers:\n  - id: billing-sync\n    label: Billing sync\n    dropped:\n      check: Did the billing sync stop or lag, so subscriptions that started don't appear as events?\n      yes: The billing system shows more new subscriptions this week than there are subscription_started events.\n    spiked:\n      check: Did a backfill or a re-sync replay old subscriptions as new this week?\n      yes: Many subscription_started events arrive at once, for subscriptions whose first invoice is weeks old.\n  - id: calendar\n    label: Calendar\n    feed: holidays\n    dropped:\n      check: Is this a holiday week, when business buyers pause purchases?\n      yes: The same week last year shows the same dip once aligned on the holiday.\n    spiked:\n      check: Is this the last week of a month or quarter, when sales-led deals close?\n      yes: Deals cluster in the same closing week in earlier quarters too.\n  - id: first-payments\n    label: First payments\n    feed: stripe\n    dropped:\n      check: Did the checkout or the first payment fail for people trying to subscribe?\n      yes: Declines or errors on first invoices rise, often during a processor incident, while trials ending holds.\n    spiked:\n      check: Did a price change, promotion or launch push people to start paying this week?\n      yes: Starts cluster from the day it went live; check how many leave when the discount ends.\n  - id: new-accounts\n    label: How many started\n    metric: new-paid-accounts\n    dropped:\n      check: Did fewer accounts start paying, or did the same number start smaller?\n      yes: New paid accounts fall by about as much as new MRR while MRR per new account holds.\n    spiked:\n      check: Is the rise in the number of new accounts rather than their size?\n      yes: New paid accounts rise by about as much as new MRR.\n  - id: plan-mix\n    label: Plan mix\n    breakdown: plan\n    dropped:\n      check: Are new customers starting on smaller plans, or did starts on the top plan stop?\n      yes: New subscriptions hold but the share on the top plan falls, and new MRR per start drops.\n    spiked:\n      check: Did one large deal, or a shift to bigger plans, lift the total?\n      yes: One or two subscriptions are most of the week's new MRR. Treat it as a deal, not a trend.\n  - id: trial-conversion\n    label: Trials converting\n    metric: trial-conversion-rate\n    dropped:\n      check: Did fewer of the trials ending this week convert, or did fewer trials end?\n      yes: Conversion of ending trials falls while the number ending holds; if starts fell one trial length ago, the drop is that lag arriving.\n    spiked:\n      check: Did a large batch of trials end at once, from a launch or campaign one trial length ago?\n      yes: Conversions rise in step with trials that started one trial length earlier.\n\ndiagnose_order: [billing-sync, calendar, first-payments, new-accounts, plan-mix, trial-conversion]\n\nrelated: [mrr, net-new-mrr, new-paid-accounts, trial-conversion-rate, arpa]\n\nprose:\n  why_it_matters: >-\n    New MRR is the inflow from customers paying for the first time, and for a growing SaaS company\n    it is usually the largest of the four MRR movements. It is also the noisiest: at 29 new\n    subscriptions a week, chance alone can move it by about 70% week to week, so one large deal\n    looks like a breakout. Read it over four weeks, split into how many accounts started and\n    what each one pays.\n  pitfalls:\n    - Counting a subscription when the trial starts rather than when it first pays books MRR that may never arrive. This spec counts the first paid period.\n    - A customer who cancels and later resubscribes is reactivation, not new business; ChartMogul and Baremetrics report it on its own line. Unless reactivations are marked, new MRR overstates acquisition.\n    - Annual plans belong at one twelfth of the contract. Booking the full year in the week it is paid makes one deal look like a month of growth.\n    - A discounted first month counts at the price actually charged; the step up when the discount ends is expansion, recorded the week it happens.\n    - At a few dozen starts a week, one enterprise deal can be half the total. Check how many subscriptions started before reading the amount.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"new-mrr","name":"New MRR","aliases":["New business MRR","New monthly recurring revenue","New subscription MRR"],"family":"subscription","kind":"currency","polarity":"up-is-good","definition":{"one_line":"The monthly recurring revenue added by subscriptions that made their first payment this week.","formula":"Sum of the monthly amounts of subscriptions whose first paid period started this week, annual plans divided by twelve"},"events":[{"name":"subscription_started","description":"A subscription's first paid period began, sent by the billing system when the first payment succeeds; not the trial start.","also_called":["Subscription Started","subscription_activated","invoice.paid (first)"],"properties":[{"name":"subscription_id","description":"The billing system's subscription id."},{"name":"mrr","description":"The subscription's monthly amount after discounts, before tax; annual plans divided by twelve."},{"name":"plan","description":"The plan the subscription started on."}]}],"numerator":{"label":"New MRR","aggregate":"sum","event":"subscription_started","property":"mrr"},"noise":{"type":"compound","cv":0.9,"min_denominator":10,"volume_unit":"new subscriptions a week","typical":2000,"reference_volumes":[10,40,150,600]},"example":{"business":"saas","level":1920,"volume":29,"trend":0.3},"drivers":[{"id":"billing-sync","label":"Billing sync","dropped":{"check":"Did the billing sync stop or lag, so subscriptions that started don't appear as events?","yes":"The billing system shows more new subscriptions this week than there are subscription_started events."},"spiked":{"check":"Did a backfill or a re-sync replay old subscriptions as new this week?","yes":"Many subscription_started events arrive at once, for subscriptions whose first invoice is weeks old."}},{"id":"calendar","label":"Calendar","feed":"holidays","dropped":{"check":"Is this a holiday week, when business buyers pause purchases?","yes":"The same week last year shows the same dip once aligned on the holiday."},"spiked":{"check":"Is this the last week of a month or quarter, when sales-led deals close?","yes":"Deals cluster in the same closing week in earlier quarters too."}},{"id":"first-payments","label":"First payments","feed":"stripe","dropped":{"check":"Did the checkout or the first payment fail for people trying to subscribe?","yes":"Declines or errors on first invoices rise, often during a processor incident, while trials ending holds."},"spiked":{"check":"Did a price change, promotion or launch push people to start paying this week?","yes":"Starts cluster from the day it went live; check how many leave when the discount ends."}},{"id":"new-accounts","label":"How many started","metric":"new-paid-accounts","dropped":{"check":"Did fewer accounts start paying, or did the same number start smaller?","yes":"New paid accounts fall by about as much as new MRR while MRR per new account holds."},"spiked":{"check":"Is the rise in the number of new accounts rather than their size?","yes":"New paid accounts rise by about as much as new MRR."}},{"id":"plan-mix","label":"Plan mix","breakdown":"plan","dropped":{"check":"Are new customers starting on smaller plans, or did starts on the top plan stop?","yes":"New subscriptions hold but the share on the top plan falls, and new MRR per start drops."},"spiked":{"check":"Did one large deal, or a shift to bigger plans, lift the total?","yes":"One or two subscriptions are most of the week's new MRR. Treat it as a deal, not a trend."}},{"id":"trial-conversion","label":"Trials converting","metric":"trial-conversion-rate","dropped":{"check":"Did fewer of the trials ending this week convert, or did fewer trials end?","yes":"Conversion of ending trials falls while the number ending holds; if starts fell one trial length ago, the drop is that lag arriving."},"spiked":{"check":"Did a large batch of trials end at once, from a launch or campaign one trial length ago?","yes":"Conversions rise in step with trials that started one trial length earlier."}}],"diagnose_order":["billing-sync","calendar","first-payments","new-accounts","plan-mix","trial-conversion"],"related":["mrr","net-new-mrr","new-paid-accounts","trial-conversion-rate","arpa"],"prose":{"why_it_matters":"New MRR is the inflow from customers paying for the first time, and for a growing SaaS company it is usually the largest of the four MRR movements. It is also the noisiest: at 29 new subscriptions a week, chance alone can move it by about 70% week to week, so one large deal looks like a breakout. Read it over four weeks, split into how many accounts started and what each one pays.","pitfalls":["Counting a subscription when the trial starts rather than when it first pays books MRR that may never arrive. This spec counts the first paid period.","A customer who cancels and later resubscribes is reactivation, not new business; ChartMogul and Baremetrics report it on its own line. Unless reactivations are marked, new MRR overstates acquisition.","Annual plans belong at one twelfth of the contract. Booking the full year in the week it is paid makes one deal look like a month of growth.","A discounted first month counts at the price actually charged; the step up when the discount ends is expansion, recorded the week it happens.","At a few dozen starts a week, one enterprise deal can be half the total. Check how many subscriptions started before reading the amount."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "new-paid-accounts": { yaml: "id: new-paid-accounts\nname: New paid accounts\naliases:\n  - New paying customers\n  - New paying accounts\n  - New logos\nfamily: activation\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: Accounts that started their first ever paid subscription this week.\n  formula: People whose first subscription_started event falls in the week\n\nevents:\n  - name: subscription_started\n    description: A subscription's first paid period began, sent by the billing system when the first payment succeeds; not the trial start.\n    also_called: [Subscription Started, subscription_activated, invoice.paid (first)]\n    properties:\n      - name: subscription_id\n        description: The billing system's subscription id.\n      - name: plan\n        description: The plan subscribed to.\n      - name: mrr\n        description: The subscription's monthly amount after discounts, before tax.\n\nnumerator:\n  label: Accounts with a first paid subscription\n  aggregate: first_time_users\n  event: subscription_started\n\nnoise:\n  type: poisson\n  min_denominator: 10\n  volume_unit: new paid accounts a week\n  typical: 29\n  reference_volumes: [10, 30, 100, 300]\n\nexample:\n  business: saas\n  level: 29\n  volume: 29\n  trend: 0.3\n\ndrivers:\n  - id: billing-tracking\n    label: Billing events\n    feed: stripe\n    dropped:\n      check: Did subscription events stop syncing from billing, or did first payments start failing?\n      yes: New subscriptions in the billing dashboard hold while recorded ones fall, or failed first charges rise.\n    spiked:\n      check: Did a billing migration or plan change fire subscription_started for existing customers?\n      yes: Many of this week's new accounts had paid before under another subscription id.\n  - id: calendar\n    label: Month and quarter end\n    feed: holidays\n    dropped:\n      check: Is this a holiday week, or the first week of a month after a month-end rush?\n      yes: The same point in the month or year shows the same dip in earlier periods.\n    spiked:\n      check: Is this the last week of a month or quarter, when sales-led deals close?\n      yes: The same point in earlier months shows the same jump.\n  - id: trial-conversion\n    label: Trial conversion\n    metric: trial-conversion-rate\n    dropped:\n      check: Did a smaller share of trials convert?\n      yes: Trial conversion for the cohorts ending this week is below its usual range while trial starts held.\n    spiked:\n      check: Did a larger share of trials convert, after a pricing or onboarding change?\n      yes: Trial conversion for the cohorts ending this week is above its usual range.\n  - id: trial-starts\n    label: Trials a few weeks ago\n    metric: trial-starts\n    dropped:\n      check: Were trial starts low two to four weeks ago?\n      yes: Trial starts dipped one trial length earlier while conversion held.\n    spiked:\n      check: Was there a wave of trials two to four weeks ago?\n      yes: Trial starts rose one trial length earlier while conversion held.\n  - id: sales-pipeline\n    label: Sales-led deals\n    metric: demo-request-rate\n    dropped:\n      check: Did fewer demos or sales deals close this week?\n      yes: Deals closed in the CRM fall, often after a dip in demo requests a month or two earlier.\n    spiked:\n      check: Did a batch of sales deals close together?\n      yes: A few accounts closed through sales explain most of the rise.\n  - id: pricing\n    label: Pricing and plans\n    breakdown: plan\n    dropped:\n      check: Did prices rise, or a cheap plan or discount go away?\n      yes: New accounts fall on the affected plan from the day of the change.\n    spiked:\n      check: Did a discount, a new entry plan or a price-rise deadline pull purchases forward?\n      yes: New accounts jump on one plan, and the following weeks run below normal.\n\ndiagnose_order: [billing-tracking, calendar, trial-conversion, trial-starts, sales-pipeline, pricing]\n\nrelated: [trial-conversion-rate, trial-starts, new-mrr, mrr, demo-request-rate]\n\nprose:\n  why_it_matters: >-\n    New paid accounts is where acquisition finally shows up as revenue. It counts first purchases\n    only, so a customer who cancels and comes back isn't new again. At 29 a week, chance alone moves\n    the count by about half, so judge it on four-week sums and look to trial conversion and the sales\n    pipeline for the cause.\n  pitfalls:\n    - Reactivations are not new accounts. Counting every subscription start inflates the number after a win-back campaign, so this spec counts first subscriptions only.\n    - Sales-led deals close at month and quarter end, so a weekly count looks lumpy for reasons nobody needs to fix.\n    - A billing migration or plan restructure can fire subscription events for existing customers. Check the count against the billing system after any migration.\n    - First is judged from the subscription history the analytics project holds. A customer who paid before tracking began and returns now counts as new, so backfill past subscriptions from billing when tracking starts.\n    - Count accounts, not users. When several teammates can buy for one workspace, identify the account as the paying person or group, or one purchase counts twice.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"new-paid-accounts","name":"New paid accounts","aliases":["New paying customers","New paying accounts","New logos"],"family":"activation","kind":"count","polarity":"up-is-good","definition":{"one_line":"Accounts that started their first ever paid subscription this week.","formula":"People whose first subscription_started event falls in the week"},"events":[{"name":"subscription_started","description":"A subscription's first paid period began, sent by the billing system when the first payment succeeds; not the trial start.","also_called":["Subscription Started","subscription_activated","invoice.paid (first)"],"properties":[{"name":"subscription_id","description":"The billing system's subscription id."},{"name":"plan","description":"The plan subscribed to."},{"name":"mrr","description":"The subscription's monthly amount after discounts, before tax."}]}],"numerator":{"label":"Accounts with a first paid subscription","aggregate":"first_time_users","event":"subscription_started"},"noise":{"type":"poisson","min_denominator":10,"volume_unit":"new paid accounts a week","typical":29,"reference_volumes":[10,30,100,300]},"example":{"business":"saas","level":29,"volume":29,"trend":0.3},"drivers":[{"id":"billing-tracking","label":"Billing events","feed":"stripe","dropped":{"check":"Did subscription events stop syncing from billing, or did first payments start failing?","yes":"New subscriptions in the billing dashboard hold while recorded ones fall, or failed first charges rise."},"spiked":{"check":"Did a billing migration or plan change fire subscription_started for existing customers?","yes":"Many of this week's new accounts had paid before under another subscription id."}},{"id":"calendar","label":"Month and quarter end","feed":"holidays","dropped":{"check":"Is this a holiday week, or the first week of a month after a month-end rush?","yes":"The same point in the month or year shows the same dip in earlier periods."},"spiked":{"check":"Is this the last week of a month or quarter, when sales-led deals close?","yes":"The same point in earlier months shows the same jump."}},{"id":"trial-conversion","label":"Trial conversion","metric":"trial-conversion-rate","dropped":{"check":"Did a smaller share of trials convert?","yes":"Trial conversion for the cohorts ending this week is below its usual range while trial starts held."},"spiked":{"check":"Did a larger share of trials convert, after a pricing or onboarding change?","yes":"Trial conversion for the cohorts ending this week is above its usual range."}},{"id":"trial-starts","label":"Trials a few weeks ago","metric":"trial-starts","dropped":{"check":"Were trial starts low two to four weeks ago?","yes":"Trial starts dipped one trial length earlier while conversion held."},"spiked":{"check":"Was there a wave of trials two to four weeks ago?","yes":"Trial starts rose one trial length earlier while conversion held."}},{"id":"sales-pipeline","label":"Sales-led deals","metric":"demo-request-rate","dropped":{"check":"Did fewer demos or sales deals close this week?","yes":"Deals closed in the CRM fall, often after a dip in demo requests a month or two earlier."},"spiked":{"check":"Did a batch of sales deals close together?","yes":"A few accounts closed through sales explain most of the rise."}},{"id":"pricing","label":"Pricing and plans","breakdown":"plan","dropped":{"check":"Did prices rise, or a cheap plan or discount go away?","yes":"New accounts fall on the affected plan from the day of the change."},"spiked":{"check":"Did a discount, a new entry plan or a price-rise deadline pull purchases forward?","yes":"New accounts jump on one plan, and the following weeks run below normal."}}],"diagnose_order":["billing-tracking","calendar","trial-conversion","trial-starts","sales-pipeline","pricing"],"related":["trial-conversion-rate","trial-starts","new-mrr","mrr","demo-request-rate"],"prose":{"why_it_matters":"New paid accounts is where acquisition finally shows up as revenue. It counts first purchases only, so a customer who cancels and comes back isn't new again. At 29 a week, chance alone moves the count by about half, so judge it on four-week sums and look to trial conversion and the sales pipeline for the cause.","pitfalls":["Reactivations are not new accounts. Counting every subscription start inflates the number after a win-back campaign, so this spec counts first subscriptions only.","Sales-led deals close at month and quarter end, so a weekly count looks lumpy for reasons nobody needs to fix.","A billing migration or plan restructure can fire subscription events for existing customers. Check the count against the billing system after any migration.","First is judged from the subscription history the analytics project holds. A customer who paid before tracking began and returns now counts as new, so backfill past subscriptions from billing when tracking starts.","Count accounts, not users. When several teammates can buy for one workspace, identify the account as the paying person or group, or one purchase counts twice."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "new-visitor-share": { yaml: "id: new-visitor-share\nname: New visitor share\naliases:\n  - New visitor rate\n  - Percent new visitors\n  - New vs returning visitors\nfamily: traffic\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of the week's unique visitors who had never viewed a page on the site before.\n  formula: Visitors whose first ever page view is this week ÷ unique visitors this week\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change, captured in the browser.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: utm_source\n        description: The campaign source from the landing URL (google, facebook, newsletter).\n      - name: $referring_domain\n        description: The domain the visitor came from, or $direct when there was none.\n\nnumerator:\n  label: First-time visitors\n  aggregate: first_time_users\n  event: $pageview\ndenominator:\n  label: Unique visitors\n  aggregate: unique_users\n  event: $pageview\n\nnoise:\n  type: binomial\n  min_denominator: 200\n  volume_unit: visitors a week\n  typical: 0.65\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: store\n  level: 0.64\n  volume: 390000\n  trend: -0.03\n\ndrivers:\n  - id: identity\n    label: Cookies and identity\n    breakdown: $browser\n    dropped:\n      check: Did a login, identity merge or tracking fix start recognising people who used to look new?\n      yes: The share falls on the day of the change while sessions and orders hold.\n    spiked:\n      check: Did cookies start resetting, from a consent change, a new domain or a browser update?\n      yes: The share jumps in one browser, sessions per visitor fall, and returning customers suddenly look new.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Did a gifting or sale period end, leaving mostly regulars?\n      yes: The same weeks last year show the same fall after the event.\n    spiked:\n      check: Is this a gifting or sale week that brings people who don't usually visit?\n      yes: The same week last year shows the same rise.\n  - id: prospecting\n    label: Prospecting spend\n    metric: paid-sessions\n    feed: ad-platforms\n    dropped:\n      check: Did prospecting campaigns pause or shift budget to retargeting?\n      yes: Paid sessions fall, or their mix moves toward retargeting audiences.\n    spiked:\n      check: Did a new prospecting campaign or a budget increase start?\n      yes: Paid sessions rise from one platform and most of them are first visits.\n  - id: email\n    label: Email and returning traffic\n    metric: email-click-rate\n    dropped:\n      check: Did a big email or SMS send bring regulars back, diluting the share?\n      yes: Returning visitors jump on send days while first-time visitors hold.\n    spiked:\n      check: Did the usual emails go out less, so fewer regulars came back?\n      yes: Email-driven sessions fall while first-time visitors hold.\n  - id: press-and-referrals\n    label: Press and referrals\n    metric: referral-sessions\n    dropped:\n      check: Did a referral source that sends new people dry up?\n      yes: One referring domain that sent first visits has stopped.\n    spiked:\n      check: Did a press piece, creator post or viral link send a wave of new people?\n      yes: One referring domain explains most of the first visits and fades within days.\n\ndiagnose_order: [identity, calendar, prospecting, email, press-and-referrals]\n\nrelated: [unique-visitors, sessions, returning-customers, new-customers, paid-sessions]\n\nprose:\n  why_it_matters: >-\n    A store grows only if new people keep finding it, and this share shows whether this week's\n    traffic is reach or the same regulars coming back. It also explains other moves: new\n    visitors convert at a fraction of returning ones, so when the share jumps from 70% to 78%,\n    expect store conversion to dip with no change to the site.\n  pitfalls:\n    - A new visitor is new to this browser's cookie. Cleared cookies, private browsing, a second device and Safari's seven-day cookie limit all make returning people look new, so the share runs high.\n    - A share can rise with no new people at all, when returning visitors fall. Read it next to the count of first-time visitors.\n    - The first-visit test needs the full history. A query limited to recent months calls everyone seen before that window new.\n    - Changing the domain, the analytics project or the cookie name resets everyone to new for months.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"new-visitor-share","name":"New visitor share","aliases":["New visitor rate","Percent new visitors","New vs returning visitors"],"family":"traffic","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of the week's unique visitors who had never viewed a page on the site before.","formula":"Visitors whose first ever page view is this week ÷ unique visitors this week"},"events":[{"name":"$pageview","description":"One page load or client-side route change, captured in the browser.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"utm_source","description":"The campaign source from the landing URL (google, facebook, newsletter)."},{"name":"$referring_domain","description":"The domain the visitor came from, or $direct when there was none."}]}],"numerator":{"label":"First-time visitors","aggregate":"first_time_users","event":"$pageview"},"denominator":{"label":"Unique visitors","aggregate":"unique_users","event":"$pageview"},"noise":{"type":"binomial","min_denominator":200,"volume_unit":"visitors a week","typical":0.65,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"store","level":0.64,"volume":390000,"trend":-0.03},"drivers":[{"id":"identity","label":"Cookies and identity","breakdown":"$browser","dropped":{"check":"Did a login, identity merge or tracking fix start recognising people who used to look new?","yes":"The share falls on the day of the change while sessions and orders hold."},"spiked":{"check":"Did cookies start resetting, from a consent change, a new domain or a browser update?","yes":"The share jumps in one browser, sessions per visitor fall, and returning customers suddenly look new."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Did a gifting or sale period end, leaving mostly regulars?","yes":"The same weeks last year show the same fall after the event."},"spiked":{"check":"Is this a gifting or sale week that brings people who don't usually visit?","yes":"The same week last year shows the same rise."}},{"id":"prospecting","label":"Prospecting spend","metric":"paid-sessions","feed":"ad-platforms","dropped":{"check":"Did prospecting campaigns pause or shift budget to retargeting?","yes":"Paid sessions fall, or their mix moves toward retargeting audiences."},"spiked":{"check":"Did a new prospecting campaign or a budget increase start?","yes":"Paid sessions rise from one platform and most of them are first visits."}},{"id":"email","label":"Email and returning traffic","metric":"email-click-rate","dropped":{"check":"Did a big email or SMS send bring regulars back, diluting the share?","yes":"Returning visitors jump on send days while first-time visitors hold."},"spiked":{"check":"Did the usual emails go out less, so fewer regulars came back?","yes":"Email-driven sessions fall while first-time visitors hold."}},{"id":"press-and-referrals","label":"Press and referrals","metric":"referral-sessions","dropped":{"check":"Did a referral source that sends new people dry up?","yes":"One referring domain that sent first visits has stopped."},"spiked":{"check":"Did a press piece, creator post or viral link send a wave of new people?","yes":"One referring domain explains most of the first visits and fades within days."}}],"diagnose_order":["identity","calendar","prospecting","email","press-and-referrals"],"related":["unique-visitors","sessions","returning-customers","new-customers","paid-sessions"],"prose":{"why_it_matters":"A store grows only if new people keep finding it, and this share shows whether this week's traffic is reach or the same regulars coming back. It also explains other moves: new visitors convert at a fraction of returning ones, so when the share jumps from 70% to 78%, expect store conversion to dip with no change to the site.","pitfalls":["A new visitor is new to this browser's cookie. Cleared cookies, private browsing, a second device and Safari's seven-day cookie limit all make returning people look new, so the share runs high.","A share can rise with no new people at all, when returning visitors fall. Read it next to the count of first-time visitors.","The first-visit test needs the full history. A query limited to recent months calls everyone seen before that window new.","Changing the domain, the analytics project or the cookie name resets everyone to new for months."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "onboarding-completion-rate": { yaml: "id: onboarding-completion-rate\nname: Onboarding completion rate\naliases:\n  - Onboarding completion\n  - Onboarding rate\n  - Setup completion rate\nfamily: activation\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of people who signed up in a week who finished onboarding within 7 days of signing up.\n  formula: Signups who completed onboarding within 7 days ÷ signups, by signup week\n\nevents:\n  - name: signed_up\n    description: An account created, sent by the server when the account exists, not when the form is submitted.\n    also_called: [sign_up, Signed Up, user_signed_up, account_created]\n    properties:\n      - name: method\n        description: How the account was created, such as email, google, sso or invite.\n  - name: onboarding_completed\n    description: The last required onboarding step finished, not skipped.\n    also_called: [Onboarding Completed, tutorial_complete, setup_completed]\n    properties: []\n\nnumerator:\n  label: Signups who completed onboarding within 7 days\n  aggregate: unique_users\n  event: onboarding_completed\ndenominator:\n  label: People who signed up\n  aggregate: unique_users\n  event: signed_up\n\nqueries:\n  hogql: |-\n    -- Onboarding completion rate: of people whose first signup fell in each week, the share who completed onboarding within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(c.converted_people, 0) AS numerator,\n      coalesce(c.people, 0) AS denominator,\n      if(denominator = 0, NULL, numerator / denominator) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(2, 28))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, countIf(converted) AS converted_people, count() AS people\n      FROM (\n        SELECT\n          toMonday(s.start_at) AS week,\n          s.person_id AS person_id,\n          countIf(x.ts >= s.start_at AND x.ts < s.start_at + toIntervalDay(7)) > 0 AS converted\n        FROM (\n          SELECT person_id, min(toTimeZone(timestamp, 'UTC')) AS start_at\n          FROM events\n          WHERE event = 'signed_up'\n            AND person_id IS NOT NULL\n          GROUP BY person_id\n        ) AS s\n        LEFT JOIN (\n          SELECT person_id, toTimeZone(timestamp, 'UTC') AS ts\n          FROM events\n          WHERE event = 'onboarding_completed'\n            AND timestamp >= now() - toIntervalWeek(29)\n        ) AS x ON x.person_id = s.person_id\n        WHERE toMonday(s.start_at) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(27) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(2)\n        GROUP BY week, person_id\n      )\n      GROUP BY week\n    ) AS c ON c.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Onboarding completion rate: of people whose first signup fell in each week, the share who completed onboarding within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '27 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '2 weeks',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    starts AS (\n      SELECT user_id, min(occurred_at AT TIME ZONE 'UTC') AS start_at\n      FROM events\n      WHERE event_name = 'signed_up'\n        AND user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    cohort AS (\n      SELECT\n        date_trunc('week', s.start_at)::date AS week,\n        s.user_id,\n        count(x.occurred_at) > 0 AS converted\n      FROM starts AS s\n      LEFT JOIN events AS x\n        ON x.user_id = s.user_id\n       AND x.event_name = 'onboarding_completed'\n       AND x.occurred_at AT TIME ZONE 'UTC' >= s.start_at\n       AND x.occurred_at AT TIME ZONE 'UTC' < s.start_at + interval '7 days'\n      WHERE s.start_at >= date_trunc('week', now() AT TIME ZONE 'UTC') - interval '27 weeks'\n        AND s.start_at < date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week'\n      GROUP BY 1, 2\n    )\n    SELECT\n      w.week,\n      count(c.user_id) FILTER (WHERE c.converted) AS numerator,\n      count(c.user_id) AS denominator,\n      (count(c.user_id) FILTER (WHERE c.converted))::numeric / nullif(count(c.user_id), 0) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Onboarding completion rate: of people whose first signup fell in each week, the share who completed onboarding within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 27 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 2 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    starts AS (\n      SELECT user_id, MIN(occurred_at) AS start_at\n      FROM events\n      WHERE event_name = 'signed_up'\n        AND user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    cohort AS (\n      SELECT\n        DATE_TRUNC(DATE(s.start_at), ISOWEEK) AS week,\n        s.user_id,\n        COUNT(x.occurred_at) > 0 AS converted\n      FROM starts AS s\n      LEFT JOIN events AS x\n        ON x.user_id = s.user_id\n       AND x.event_name = 'onboarding_completed'\n       AND x.occurred_at >= s.start_at\n       AND x.occurred_at < TIMESTAMP_ADD(s.start_at, INTERVAL 7 DAY)\n      WHERE s.start_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 27 WEEK))\n        AND s.start_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK))\n      GROUP BY week, s.user_id\n    )\n    SELECT\n      w.week,\n      COUNTIF(c.converted) AS numerator,\n      COUNT(c.user_id) AS denominator,\n      SAFE_DIVIDE(COUNTIF(c.converted), COUNT(c.user_id)) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Onboarding completion rate: of people whose first signup fell in each week, the share who completed onboarding within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 - ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    starts AS (\n      SELECT user_id, MIN(occurred_at) AS start_at\n      FROM events\n      WHERE event_name = 'signed_up'\n        AND user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    cohort AS (\n      SELECT\n        DATEADD(day, 1 - DAYOFWEEKISO(s.start_at), s.start_at::date) AS week,\n        s.user_id,\n        COUNT(x.occurred_at) > 0 AS converted\n      FROM starts AS s\n      LEFT JOIN events AS x\n        ON x.user_id = s.user_id\n       AND x.event_name = 'onboarding_completed'\n       AND x.occurred_at >= s.start_at\n       AND x.occurred_at < DATEADD(day, 7, s.start_at)\n      WHERE s.start_at >= DATEADD(week, -27, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND s.start_at < DATEADD(week, -1, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n      GROUP BY 1, 2\n    )\n    SELECT\n      w.week,\n      COUNT_IF(c.converted) AS numerator,\n      COUNT(c.user_id) AS denominator,\n      COUNT_IF(c.converted)::float / NULLIF(COUNT(c.user_id), 0) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: signups in the cohort\n  typical: 0.61\n\nexample:\n  business: saas\n  level: 0.61\n  volume: 2200\n  trend: 0.04\n\ndrivers:\n  - id: tracking\n    label: Onboarding event\n    dropped:\n      check: Did the completion event move, get renamed, or stop firing on one platform?\n      yes: Completion falls overnight on one platform or app version while people still reach the screens after onboarding.\n    spiked:\n      check: Does the event now fire when people skip, or at an earlier step?\n      yes: Completion jumps overnight while activation for the same cohorts doesn't move.\n  - id: errors\n    label: Errors and outages\n    metric: error-rate\n    feed: cloudflare\n    dropped:\n      check: Did an error, an outage or a slow third-party step block people mid-onboarding?\n      yes: Errors on one onboarding step rose on the days the cohort was signing up.\n    spiked:\n      check: Did a fix to a failing step ship?\n      yes: The step that failed before now completes, and completion recovers from the release date.\n  - id: flow-change\n    label: Onboarding flow\n    breakdown: $device_type\n    dropped:\n      check: Was a step added, or did the flow break on one device or browser?\n      yes: Drop-off concentrates on one step or one device from the day of a release.\n    spiked:\n      check: Was a step removed, made optional or pre-filled?\n      yes: Completion rises from the release date on every device; check that activation rose too.\n  - id: signup-quality\n    label: Who signed up\n    metric: signups\n    breakdown: utm_source\n    dropped:\n      check: Did the cohort include a wave of low-intent or bot signups?\n      yes: Signups from one source rose that week and almost none of them finished onboarding.\n    spiked:\n      check: Did a low-intent source stop, leaving a smaller, more committed cohort?\n      yes: Signups from one source fell that week while completion elsewhere held.\n  - id: method\n    label: Signup method\n    breakdown: method\n    dropped:\n      check: Did more people sign up by a method that sends them through a longer flow, such as email instead of single sign-on?\n      yes: The mix shifted toward the slower method while completion within each method held.\n    spiked:\n      check: Did more people arrive by invite or single sign-on, which skip steps?\n      yes: The mix shifted toward invited or SSO signups while completion within each method held.\n\ndiagnose_order: [tracking, errors, flow-change, signup-quality, method]\n\nrelated: [activation-rate, time-to-value, signups, invite-rate, error-rate]\n\nprose:\n  why_it_matters: >-\n    Onboarding is the one part of activation a product team fully controls: every step is a screen\n    someone designed, and every step loses people. Measured on the same cohorts and window as\n    activation rate, the gap between the two says whether onboarding teaches the product or only gets\n    people through a form. At Copperline about 61% finish onboarding while 34% activate.\n  pitfalls:\n    - Adding or removing a step changes what complete means. Note the release date and compare only cohorts on the same flow.\n    - High completion with flat activation means onboarding is easy but not useful; skippable checklists often look like this.\n    - People who press skip must not fire onboarding_completed, or the rate measures patience, not setup.\n    - Only cohorts whose 7 days have closed are reported, so the latest point is the signups of two weeks ago.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"onboarding-completion-rate","name":"Onboarding completion rate","aliases":["Onboarding completion","Onboarding rate","Setup completion rate"],"family":"activation","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of people who signed up in a week who finished onboarding within 7 days of signing up.","formula":"Signups who completed onboarding within 7 days ÷ signups, by signup week"},"events":[{"name":"signed_up","description":"An account created, sent by the server when the account exists, not when the form is submitted.","also_called":["sign_up","Signed Up","user_signed_up","account_created"],"properties":[{"name":"method","description":"How the account was created, such as email, google, sso or invite."}]},{"name":"onboarding_completed","description":"The last required onboarding step finished, not skipped.","also_called":["Onboarding Completed","tutorial_complete","setup_completed"],"properties":[]}],"numerator":{"label":"Signups who completed onboarding within 7 days","aggregate":"unique_users","event":"onboarding_completed"},"denominator":{"label":"People who signed up","aggregate":"unique_users","event":"signed_up"},"queries":{"hogql":"-- Onboarding completion rate: of people whose first signup fell in each week, the share who completed onboarding within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(c.converted_people, 0) AS numerator,\n  coalesce(c.people, 0) AS denominator,\n  if(denominator = 0, NULL, numerator / denominator) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(2, 28))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, countIf(converted) AS converted_people, count() AS people\n  FROM (\n    SELECT\n      toMonday(s.start_at) AS week,\n      s.person_id AS person_id,\n      countIf(x.ts >= s.start_at AND x.ts < s.start_at + toIntervalDay(7)) > 0 AS converted\n    FROM (\n      SELECT person_id, min(toTimeZone(timestamp, 'UTC')) AS start_at\n      FROM events\n      WHERE event = 'signed_up'\n        AND person_id IS NOT NULL\n      GROUP BY person_id\n    ) AS s\n    LEFT JOIN (\n      SELECT person_id, toTimeZone(timestamp, 'UTC') AS ts\n      FROM events\n      WHERE event = 'onboarding_completed'\n        AND timestamp >= now() - toIntervalWeek(29)\n    ) AS x ON x.person_id = s.person_id\n    WHERE toMonday(s.start_at) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(27) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(2)\n    GROUP BY week, person_id\n  )\n  GROUP BY week\n) AS c ON c.week = w.week\nORDER BY week","postgres":"-- Onboarding completion rate: of people whose first signup fell in each week, the share who completed onboarding within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '27 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '2 weeks',\n    interval '1 week'\n  ) AS g(week)\n),\nstarts AS (\n  SELECT user_id, min(occurred_at AT TIME ZONE 'UTC') AS start_at\n  FROM events\n  WHERE event_name = 'signed_up'\n    AND user_id IS NOT NULL\n  GROUP BY user_id\n),\ncohort AS (\n  SELECT\n    date_trunc('week', s.start_at)::date AS week,\n    s.user_id,\n    count(x.occurred_at) > 0 AS converted\n  FROM starts AS s\n  LEFT JOIN events AS x\n    ON x.user_id = s.user_id\n   AND x.event_name = 'onboarding_completed'\n   AND x.occurred_at AT TIME ZONE 'UTC' >= s.start_at\n   AND x.occurred_at AT TIME ZONE 'UTC' < s.start_at + interval '7 days'\n  WHERE s.start_at >= date_trunc('week', now() AT TIME ZONE 'UTC') - interval '27 weeks'\n    AND s.start_at < date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week'\n  GROUP BY 1, 2\n)\nSELECT\n  w.week,\n  count(c.user_id) FILTER (WHERE c.converted) AS numerator,\n  count(c.user_id) AS denominator,\n  (count(c.user_id) FILTER (WHERE c.converted))::numeric / nullif(count(c.user_id), 0) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;","bigquery":"-- Onboarding completion rate: of people whose first signup fell in each week, the share who completed onboarding within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 27 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 2 WEEK), INTERVAL 1 WEEK)) AS week\n),\nstarts AS (\n  SELECT user_id, MIN(occurred_at) AS start_at\n  FROM events\n  WHERE event_name = 'signed_up'\n    AND user_id IS NOT NULL\n  GROUP BY user_id\n),\ncohort AS (\n  SELECT\n    DATE_TRUNC(DATE(s.start_at), ISOWEEK) AS week,\n    s.user_id,\n    COUNT(x.occurred_at) > 0 AS converted\n  FROM starts AS s\n  LEFT JOIN events AS x\n    ON x.user_id = s.user_id\n   AND x.event_name = 'onboarding_completed'\n   AND x.occurred_at >= s.start_at\n   AND x.occurred_at < TIMESTAMP_ADD(s.start_at, INTERVAL 7 DAY)\n  WHERE s.start_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 27 WEEK))\n    AND s.start_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK))\n  GROUP BY week, s.user_id\n)\nSELECT\n  w.week,\n  COUNTIF(c.converted) AS numerator,\n  COUNT(c.user_id) AS denominator,\n  SAFE_DIVIDE(COUNTIF(c.converted), COUNT(c.user_id)) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;","snowflake":"-- Onboarding completion rate: of people whose first signup fell in each week, the share who completed onboarding within 7 days of signing up. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 - ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nstarts AS (\n  SELECT user_id, MIN(occurred_at) AS start_at\n  FROM events\n  WHERE event_name = 'signed_up'\n    AND user_id IS NOT NULL\n  GROUP BY user_id\n),\ncohort AS (\n  SELECT\n    DATEADD(day, 1 - DAYOFWEEKISO(s.start_at), s.start_at::date) AS week,\n    s.user_id,\n    COUNT(x.occurred_at) > 0 AS converted\n  FROM starts AS s\n  LEFT JOIN events AS x\n    ON x.user_id = s.user_id\n   AND x.event_name = 'onboarding_completed'\n   AND x.occurred_at >= s.start_at\n   AND x.occurred_at < DATEADD(day, 7, s.start_at)\n  WHERE s.start_at >= DATEADD(week, -27, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND s.start_at < DATEADD(week, -1, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n  GROUP BY 1, 2\n)\nSELECT\n  w.week,\n  COUNT_IF(c.converted) AS numerator,\n  COUNT(c.user_id) AS denominator,\n  COUNT_IF(c.converted)::float / NULLIF(COUNT(c.user_id), 0) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"signups in the cohort","typical":0.61},"example":{"business":"saas","level":0.61,"volume":2200,"trend":0.04},"drivers":[{"id":"tracking","label":"Onboarding event","dropped":{"check":"Did the completion event move, get renamed, or stop firing on one platform?","yes":"Completion falls overnight on one platform or app version while people still reach the screens after onboarding."},"spiked":{"check":"Does the event now fire when people skip, or at an earlier step?","yes":"Completion jumps overnight while activation for the same cohorts doesn't move."}},{"id":"errors","label":"Errors and outages","metric":"error-rate","feed":"cloudflare","dropped":{"check":"Did an error, an outage or a slow third-party step block people mid-onboarding?","yes":"Errors on one onboarding step rose on the days the cohort was signing up."},"spiked":{"check":"Did a fix to a failing step ship?","yes":"The step that failed before now completes, and completion recovers from the release date."}},{"id":"flow-change","label":"Onboarding flow","breakdown":"$device_type","dropped":{"check":"Was a step added, or did the flow break on one device or browser?","yes":"Drop-off concentrates on one step or one device from the day of a release."},"spiked":{"check":"Was a step removed, made optional or pre-filled?","yes":"Completion rises from the release date on every device; check that activation rose too."}},{"id":"signup-quality","label":"Who signed up","metric":"signups","breakdown":"utm_source","dropped":{"check":"Did the cohort include a wave of low-intent or bot signups?","yes":"Signups from one source rose that week and almost none of them finished onboarding."},"spiked":{"check":"Did a low-intent source stop, leaving a smaller, more committed cohort?","yes":"Signups from one source fell that week while completion elsewhere held."}},{"id":"method","label":"Signup method","breakdown":"method","dropped":{"check":"Did more people sign up by a method that sends them through a longer flow, such as email instead of single sign-on?","yes":"The mix shifted toward the slower method while completion within each method held."},"spiked":{"check":"Did more people arrive by invite or single sign-on, which skip steps?","yes":"The mix shifted toward invited or SSO signups while completion within each method held."}}],"diagnose_order":["tracking","errors","flow-change","signup-quality","method"],"related":["activation-rate","time-to-value","signups","invite-rate","error-rate"],"prose":{"why_it_matters":"Onboarding is the one part of activation a product team fully controls: every step is a screen someone designed, and every step loses people. Measured on the same cohorts and window as activation rate, the gap between the two says whether onboarding teaches the product or only gets people through a form. At Copperline about 61% finish onboarding while 34% activate.","pitfalls":["Adding or removing a step changes what complete means. Note the release date and compare only cohorts on the same flow.","High completion with flat activation means onboarding is easy but not useful; skippable checklists often look like this.","People who press skip must not fire onboarding_completed, or the rate measures patience, not setup.","Only cohorts whose 7 days have closed are reported, so the latest point is the signups of two weeks ago."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "orders": { yaml: "id: orders\nname: Orders\naliases:\n  - Order count\n  - Weekly orders\n  - Number of orders\n  - Paid orders\n  - Transactions\nfamily: revenue\ncatalog_id: orders\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: The number of paid orders placed in the week, each counted once, before any refunds.\n  formula: Count of paid orders, by the week they were paid\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server or the payment processor, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n      - name: is_first_order\n        description: True when it is the customer's first ever paid order.\n\nnumerator:\n  label: Paid orders\n  aggregate: count\n  event: order_completed\n\nnoise:\n  type: poisson\n  min_denominator: 30\n  volume_unit: orders a week\n  typical: 3000\n\nexample:\n  business: store\n  level: 13300\n  volume: 13300\n  trend: 0.2\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did recorded orders fall while the store platform or payment processor shows the usual count?\n      yes: The processor's order count holds, often after a checkout, consent or tag change.\n    spiked:\n      check: Are orders duplicated by thank-you page reloads or webhook retries, or are test orders included?\n      yes: Recorded orders exceed the processor's count, or the same order_id appears more than once.\n  - id: calendar\n    label: Shopping calendar\n    feed: shopping\n    dropped:\n      check: Was last week a sale, holiday or payday week, or is this the week before one?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this a sale, holiday or payday week?\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: payments\n    label: Payment outages\n    metric: payment-success-rate\n    feed: stripe\n    dropped:\n      check: Did a processor incident or a fraud rule block payments for part of the week?\n      yes: Payment success falls for one gateway or method during the hours orders are missing.\n    spiked:\n      check: Did a payment problem from the week before clear?\n      yes: Payment success returns to its usual level and orders recover with it.\n  - id: traffic\n    label: Traffic\n    metric: sessions\n    feed: google-search\n    dropped:\n      check: Did fewer people arrive, and from which channel?\n      yes: Sessions fall in one channel by about as much as orders do, while conversion holds.\n    spiked:\n      check: Did a campaign, press mention or ranking change bring more visitors who buy?\n      yes: Sessions rise in one channel and conversion holds; a bot wave would lift sessions but not orders.\n  - id: conversion\n    label: Store conversion\n    metric: conversion-rate\n    dropped:\n      check: Did the share of visits that buy fall, and at which funnel step?\n      yes: Conversion falls while traffic holds; one step explains most of it.\n    spiked:\n      check: Did more visits buy, and at which funnel step?\n      yes: Conversion rises while traffic holds; one step explains most of it.\n  - id: first-orders\n    label: First vs repeat orders\n    metric: new-customers\n    breakdown: is_first_order\n    dropped:\n      check: Did first orders fall, after an ad budget cut or a campaign ending, while repeat orders held?\n      yes: New customers fall by about as much as orders.\n    spiked:\n      check: Did an email, a launch or a restock bring back past customers?\n      yes: Repeat orders jump while first orders hold.\n\ndiagnose_order: [tracking, calendar, payments, traffic, conversion, first-orders]\n\nrelated: [net-revenue, aov, conversion-rate, sessions, new-customers]\n\nprose:\n  why_it_matters: >-\n    Orders are the store's heartbeat, a count of decisions to buy, free of price and basket\n    effects. Because they are a count, chance alone moves them by about 2.8 ÷ √N: a store with\n    800 orders a week swings ±10% on noise, while Northwind's 13,300 swing about ±2.5%.\n  pitfalls:\n    - Count orders from the server or the payment processor, never from thank-you page views, which double count reloads and miss redirect payments.\n    - Removing fully refunded orders rewrites past weeks for a month or more after they close. This spec counts orders when paid and reads refunds in refund rate.\n    - Test orders, draft orders and $0 replacement orders inflate the count. Flag them at the source rather than filtering in every query.\n    - Subscription renewals and marketplace orders follow their own calendars; mixed in with site orders, a renewal date looks like a sales spike.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"orders","name":"Orders","aliases":["Order count","Weekly orders","Number of orders","Paid orders","Transactions"],"family":"revenue","catalog_id":"orders","kind":"count","polarity":"up-is-good","definition":{"one_line":"The number of paid orders placed in the week, each counted once, before any refunds.","formula":"Count of paid orders, by the week they were paid"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server or the payment processor, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."},{"name":"is_first_order","description":"True when it is the customer's first ever paid order."}]}],"numerator":{"label":"Paid orders","aggregate":"count","event":"order_completed"},"noise":{"type":"poisson","min_denominator":30,"volume_unit":"orders a week","typical":3000},"example":{"business":"store","level":13300,"volume":13300,"trend":0.2},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did recorded orders fall while the store platform or payment processor shows the usual count?","yes":"The processor's order count holds, often after a checkout, consent or tag change."},"spiked":{"check":"Are orders duplicated by thank-you page reloads or webhook retries, or are test orders included?","yes":"Recorded orders exceed the processor's count, or the same order_id appears more than once."}},{"id":"calendar","label":"Shopping calendar","feed":"shopping","dropped":{"check":"Was last week a sale, holiday or payday week, or is this the week before one?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this a sale, holiday or payday week?","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"payments","label":"Payment outages","metric":"payment-success-rate","feed":"stripe","dropped":{"check":"Did a processor incident or a fraud rule block payments for part of the week?","yes":"Payment success falls for one gateway or method during the hours orders are missing."},"spiked":{"check":"Did a payment problem from the week before clear?","yes":"Payment success returns to its usual level and orders recover with it."}},{"id":"traffic","label":"Traffic","metric":"sessions","feed":"google-search","dropped":{"check":"Did fewer people arrive, and from which channel?","yes":"Sessions fall in one channel by about as much as orders do, while conversion holds."},"spiked":{"check":"Did a campaign, press mention or ranking change bring more visitors who buy?","yes":"Sessions rise in one channel and conversion holds; a bot wave would lift sessions but not orders."}},{"id":"conversion","label":"Store conversion","metric":"conversion-rate","dropped":{"check":"Did the share of visits that buy fall, and at which funnel step?","yes":"Conversion falls while traffic holds; one step explains most of it."},"spiked":{"check":"Did more visits buy, and at which funnel step?","yes":"Conversion rises while traffic holds; one step explains most of it."}},{"id":"first-orders","label":"First vs repeat orders","metric":"new-customers","breakdown":"is_first_order","dropped":{"check":"Did first orders fall, after an ad budget cut or a campaign ending, while repeat orders held?","yes":"New customers fall by about as much as orders."},"spiked":{"check":"Did an email, a launch or a restock bring back past customers?","yes":"Repeat orders jump while first orders hold."}}],"diagnose_order":["tracking","calendar","payments","traffic","conversion","first-orders"],"related":["net-revenue","aov","conversion-rate","sessions","new-customers"],"prose":{"why_it_matters":"Orders are the store's heartbeat, a count of decisions to buy, free of price and basket effects. Because they are a count, chance alone moves them by about 2.8 ÷ √N: a store with 800 orders a week swings ±10% on noise, while Northwind's 13,300 swing about ±2.5%.","pitfalls":["Count orders from the server or the payment processor, never from thank-you page views, which double count reloads and miss redirect payments.","Removing fully refunded orders rewrites past weeks for a month or more after they close. This spec counts orders when paid and reads refunds in refund rate.","Test orders, draft orders and $0 replacement orders inflate the count. Flag them at the source rather than filtering in every query.","Subscription renewals and marketplace orders follow their own calendars; mixed in with site orders, a renewal date looks like a sales spike."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "organic-sessions": { yaml: "id: organic-sessions\nname: Organic search sessions\naliases:\n  - Organic traffic\n  - Organic search traffic\n  - SEO traffic\nfamily: traffic\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: Visits that arrived from an unpaid search result, judged by the first page of the visit.\n  formula: Sessions whose first page view came from a search engine, or is tagged utm_medium=organic, with no paid tag or ad click id\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change, captured in the browser.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: $session_id\n        description: Set by the analytics SDK; the session's first page view decides its channel.\n      - name: $referring_domain\n        description: The domain the visitor came from, or $direct when there was none.\n      - name: utm_medium\n        description: The campaign medium from the landing URL. When set, it decides the channel.\n      - name: gclid\n        description: Google Ads click id, added by auto-tagging. Also gbraid, wbraid, and msclkid for Microsoft Ads. Marks the visit as paid.\n\nnumerator:\n  label: Organic search sessions\n  aggregate: unique_sessions\n  event: $pageview\n  where:\n    - property: utm_medium\n      op: is_not_set\n    - property: $referring_domain\n      op: in\n      value: [www.google.com, google.com, www.bing.com, duckduckgo.com, search.yahoo.com, yandex.ru, www.ecosia.org, search.brave.com]\n\nqueries:\n  hogql: |-\n    -- Organic search sessions per week: sessions whose first page view came from a search engine (or is tagged utm_medium=organic), with no paid tag or ad click id. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT w.week AS week, coalesce(s.sessions, 0) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, count() AS sessions\n      FROM (\n        SELECT\n          $session_id AS session_id,\n          toMonday(toTimeZone(min(timestamp), 'UTC')) AS week,\n          argMin(lower(coalesce(properties.utm_medium, '')), timestamp) AS medium,\n          argMin(lower(coalesce(properties.$referring_domain, '')), timestamp) AS referrer,\n          argMin(coalesce(properties.gclid, properties.gbraid, properties.wbraid, properties.msclkid, '') <> '', timestamp) AS ad_click\n        FROM events\n        WHERE event = '$pageview'\n          AND $session_id != ''\n          AND timestamp >= now() - toIntervalWeek(27)\n          AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n        GROUP BY session_id\n      )\n      WHERE NOT (match(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n        AND (medium = 'organic' OR (medium = '' AND match(referrer, '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')))\n      GROUP BY week\n    ) AS s ON s.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Organic search sessions per week: sessions whose first page view came from a search engine (or is tagged utm_medium=organic), with no paid tag or ad click id. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    entries AS (\n      SELECT DISTINCT ON (session_id)\n        session_id,\n        date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n        lower(coalesce(properties->>'utm_medium', '')) AS medium,\n        lower(coalesce(properties->>'$referring_domain', '')) AS referrer,\n        coalesce(properties->>'gclid', properties->>'gbraid', properties->>'wbraid', properties->>'msclkid', '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id <> ''\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n      ORDER BY session_id, occurred_at\n    ),\n    weekly AS (\n      SELECT week, count(*) AS sessions\n      FROM entries\n      WHERE NOT (medium ~ '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$' OR ad_click)\n        AND (medium = 'organic' OR (medium = '' AND referrer ~ '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$'))\n      GROUP BY week\n    )\n    SELECT w.week, coalesce(s.sessions, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS s ON s.week = w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Organic search sessions per week: sessions whose first page view came from a search engine (or is tagged utm_medium=organic), with no paid tag or ad click id. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    entries AS (\n      SELECT\n        session_id,\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n        LOWER(COALESCE(JSON_VALUE(properties, '$.utm_medium'), '')) AS medium,\n        LOWER(COALESCE(JSON_VALUE(properties, '$.\"$referring_domain\"'), '')) AS referrer,\n        COALESCE(JSON_VALUE(properties, '$.gclid'), JSON_VALUE(properties, '$.gbraid'), JSON_VALUE(properties, '$.wbraid'), JSON_VALUE(properties, '$.msclkid'), '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id <> ''\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n    ),\n    weekly AS (\n      SELECT week, COUNT(*) AS sessions\n      FROM entries\n      WHERE NOT (REGEXP_CONTAINS(medium, r'^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n        AND (medium = 'organic' OR (medium = '' AND REGEXP_CONTAINS(referrer, r'^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')))\n      GROUP BY week\n    )\n    SELECT w.week, COALESCE(s.sessions, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS s ON s.week = w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Organic search sessions per week: sessions whose first page view came from a search engine (or is tagged utm_medium=organic), with no paid tag or ad click id. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    entries AS (\n      SELECT\n        session_id,\n        DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n        LOWER(COALESCE(properties:\"utm_medium\"::string, '')) AS medium,\n        LOWER(COALESCE(properties:\"$referring_domain\"::string, '')) AS referrer,\n        COALESCE(properties:\"gclid\"::string, properties:\"gbraid\"::string, properties:\"wbraid\"::string, properties:\"msclkid\"::string, '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id <> ''\n        AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n    ),\n    weekly AS (\n      SELECT week, COUNT(*) AS sessions\n      FROM entries\n      WHERE NOT (REGEXP_LIKE(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n        AND (medium = 'organic' OR (medium = '' AND REGEXP_LIKE(referrer, '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')))\n      GROUP BY week\n    )\n    SELECT w.week, COALESCE(s.sessions, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS s ON s.week = w.week\n    ORDER BY w.week;\n\nnoise:\n  type: poisson\n  min_denominator: 100\n  volume_unit: organic sessions a week\n  typical: 12000\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: store\n  level: 125000\n  volume: 125000\n  trend: 0.08\n\ndrivers:\n  - id: classification\n    label: Tracking and channel rules\n    dropped:\n      check: Did a redirect, consent change or new domain strip the referrer, so search visits now look direct?\n      yes: Direct sessions rise by about as much as organic falls, from the day of the change.\n    spiked:\n      check: Did paid search lose its tags, so ad clicks now count as organic?\n      yes: Paid search sessions fall by about as much as organic rises, often after auto-tagging was switched off or a redirect dropped the click id.\n  - id: google-update\n    label: Google updates and results pages\n    feed: google-search\n    dropped:\n      check: Did a core update, a ranking loss or an AI Overview start taking clicks from key queries?\n      yes: The fall starts on a dated update and concentrates on a few landing pages or query groups.\n    spiked:\n      check: Did a core update or a new results feature reward the site's pages?\n      yes: The rise starts on a dated update and holds for more than one week.\n  - id: calendar\n    label: Seasonal search demand\n    feed: shopping\n    dropped:\n      check: Did people simply search less for what the store sells, after a holiday or a season?\n      yes: The same weeks last year show the same fall once aligned on the event.\n    spiked:\n      check: Is this a gifting, sale or seasonal week when people search more?\n      yes: The same week last year shows the same rise.\n  - id: brand-demand\n    label: Branded searches\n    metric: ad-spend\n    dropped:\n      check: Did advertising, press or a launch that drove people to search the brand name stop?\n      yes: Visits landing on the home page from search fall while product-page search visits hold.\n    spiked:\n      check: Did a campaign, a press piece or a creator post make people search the brand?\n      yes: The rise lands on the home page and brand queries, and fades when the campaign ends.\n  - id: landing-pages\n    label: Pages that rank\n    breakdown: $pathname\n    dropped:\n      check: Did a ranking page get removed, redirected, noindexed or slower?\n      yes: One or two landing paths account for most of the fall.\n    spiked:\n      check: Did a new or updated page start ranking for a valuable query?\n      yes: One or two landing paths account for most of the rise.\n\ndiagnose_order: [classification, google-update, calendar, brand-demand, landing-pages]\n\nrelated: [sessions, paid-sessions, referral-sessions, new-visitor-share, conversion-rate]\n\nprose:\n  why_it_matters: >-\n    Organic search is the traffic a store doesn't pay for each week, so it sets how much of\n    growth has to be bought. It also moves on dates you can look up: Google ships several core\n    updates a year, and a store with 125,000 organic sessions a week can lose 15% in the days\n    after one without changing a thing.\n  pitfalls:\n    - Google Ads auto-tagging adds a gclid but no UTM tags. Without checking the click id, paid search clicks land in organic and organic looks better than it is.\n    - Organic here means search engines only, GA4's Organic Search group. Unpaid social posts, emails and links from other sites are separate channels, and GA4's Organic Social, Organic Video and Organic Shopping groups are not included.\n    - Visits from ChatGPT, Perplexity and other AI assistants arrive as referrals, not search, even when they answer what used to be a search. Read them in referral sessions.\n    - Search engines don't pass the keyword, so this number can't tell branded from unbranded searches. Use Search Console for that split, and expect its clicks never to match sessions exactly, because consent banners, ad blockers and slow pages lose some visits.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"organic-sessions","name":"Organic search sessions","aliases":["Organic traffic","Organic search traffic","SEO traffic"],"family":"traffic","kind":"count","polarity":"up-is-good","definition":{"one_line":"Visits that arrived from an unpaid search result, judged by the first page of the visit.","formula":"Sessions whose first page view came from a search engine, or is tagged utm_medium=organic, with no paid tag or ad click id"},"events":[{"name":"$pageview","description":"One page load or client-side route change, captured in the browser.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"$session_id","description":"Set by the analytics SDK; the session's first page view decides its channel."},{"name":"$referring_domain","description":"The domain the visitor came from, or $direct when there was none."},{"name":"utm_medium","description":"The campaign medium from the landing URL. When set, it decides the channel."},{"name":"gclid","description":"Google Ads click id, added by auto-tagging. Also gbraid, wbraid, and msclkid for Microsoft Ads. Marks the visit as paid."}]}],"numerator":{"label":"Organic search sessions","aggregate":"unique_sessions","event":"$pageview","where":[{"property":"utm_medium","op":"is_not_set"},{"property":"$referring_domain","op":"in","value":["www.google.com","google.com","www.bing.com","duckduckgo.com","search.yahoo.com","yandex.ru","www.ecosia.org","search.brave.com"]}]},"queries":{"hogql":"-- Organic search sessions per week: sessions whose first page view came from a search engine (or is tagged utm_medium=organic), with no paid tag or ad click id. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT w.week AS week, coalesce(s.sessions, 0) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, count() AS sessions\n  FROM (\n    SELECT\n      $session_id AS session_id,\n      toMonday(toTimeZone(min(timestamp), 'UTC')) AS week,\n      argMin(lower(coalesce(properties.utm_medium, '')), timestamp) AS medium,\n      argMin(lower(coalesce(properties.$referring_domain, '')), timestamp) AS referrer,\n      argMin(coalesce(properties.gclid, properties.gbraid, properties.wbraid, properties.msclkid, '') <> '', timestamp) AS ad_click\n    FROM events\n    WHERE event = '$pageview'\n      AND $session_id != ''\n      AND timestamp >= now() - toIntervalWeek(27)\n      AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n    GROUP BY session_id\n  )\n  WHERE NOT (match(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n    AND (medium = 'organic' OR (medium = '' AND match(referrer, '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')))\n  GROUP BY week\n) AS s ON s.week = w.week\nORDER BY week","postgres":"-- Organic search sessions per week: sessions whose first page view came from a search engine (or is tagged utm_medium=organic), with no paid tag or ad click id. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nentries AS (\n  SELECT DISTINCT ON (session_id)\n    session_id,\n    date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n    lower(coalesce(properties->>'utm_medium', '')) AS medium,\n    lower(coalesce(properties->>'$referring_domain', '')) AS referrer,\n    coalesce(properties->>'gclid', properties->>'gbraid', properties->>'wbraid', properties->>'msclkid', '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id <> ''\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n  ORDER BY session_id, occurred_at\n),\nweekly AS (\n  SELECT week, count(*) AS sessions\n  FROM entries\n  WHERE NOT (medium ~ '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$' OR ad_click)\n    AND (medium = 'organic' OR (medium = '' AND referrer ~ '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$'))\n  GROUP BY week\n)\nSELECT w.week, coalesce(s.sessions, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS s ON s.week = w.week\nORDER BY w.week;","bigquery":"-- Organic search sessions per week: sessions whose first page view came from a search engine (or is tagged utm_medium=organic), with no paid tag or ad click id. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nentries AS (\n  SELECT\n    session_id,\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n    LOWER(COALESCE(JSON_VALUE(properties, '$.utm_medium'), '')) AS medium,\n    LOWER(COALESCE(JSON_VALUE(properties, '$.\"$referring_domain\"'), '')) AS referrer,\n    COALESCE(JSON_VALUE(properties, '$.gclid'), JSON_VALUE(properties, '$.gbraid'), JSON_VALUE(properties, '$.wbraid'), JSON_VALUE(properties, '$.msclkid'), '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id <> ''\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n),\nweekly AS (\n  SELECT week, COUNT(*) AS sessions\n  FROM entries\n  WHERE NOT (REGEXP_CONTAINS(medium, r'^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n    AND (medium = 'organic' OR (medium = '' AND REGEXP_CONTAINS(referrer, r'^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')))\n  GROUP BY week\n)\nSELECT w.week, COALESCE(s.sessions, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS s ON s.week = w.week\nORDER BY w.week;","snowflake":"-- Organic search sessions per week: sessions whose first page view came from a search engine (or is tagged utm_medium=organic), with no paid tag or ad click id. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nentries AS (\n  SELECT\n    session_id,\n    DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n    LOWER(COALESCE(properties:\"utm_medium\"::string, '')) AS medium,\n    LOWER(COALESCE(properties:\"$referring_domain\"::string, '')) AS referrer,\n    COALESCE(properties:\"gclid\"::string, properties:\"gbraid\"::string, properties:\"wbraid\"::string, properties:\"msclkid\"::string, '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id <> ''\n    AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n),\nweekly AS (\n  SELECT week, COUNT(*) AS sessions\n  FROM entries\n  WHERE NOT (REGEXP_LIKE(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n    AND (medium = 'organic' OR (medium = '' AND REGEXP_LIKE(referrer, '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')))\n  GROUP BY week\n)\nSELECT w.week, COALESCE(s.sessions, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS s ON s.week = w.week\nORDER BY w.week;"},"noise":{"type":"poisson","min_denominator":100,"volume_unit":"organic sessions a week","typical":12000,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"store","level":125000,"volume":125000,"trend":0.08},"drivers":[{"id":"classification","label":"Tracking and channel rules","dropped":{"check":"Did a redirect, consent change or new domain strip the referrer, so search visits now look direct?","yes":"Direct sessions rise by about as much as organic falls, from the day of the change."},"spiked":{"check":"Did paid search lose its tags, so ad clicks now count as organic?","yes":"Paid search sessions fall by about as much as organic rises, often after auto-tagging was switched off or a redirect dropped the click id."}},{"id":"google-update","label":"Google updates and results pages","feed":"google-search","dropped":{"check":"Did a core update, a ranking loss or an AI Overview start taking clicks from key queries?","yes":"The fall starts on a dated update and concentrates on a few landing pages or query groups."},"spiked":{"check":"Did a core update or a new results feature reward the site's pages?","yes":"The rise starts on a dated update and holds for more than one week."}},{"id":"calendar","label":"Seasonal search demand","feed":"shopping","dropped":{"check":"Did people simply search less for what the store sells, after a holiday or a season?","yes":"The same weeks last year show the same fall once aligned on the event."},"spiked":{"check":"Is this a gifting, sale or seasonal week when people search more?","yes":"The same week last year shows the same rise."}},{"id":"brand-demand","label":"Branded searches","metric":"ad-spend","dropped":{"check":"Did advertising, press or a launch that drove people to search the brand name stop?","yes":"Visits landing on the home page from search fall while product-page search visits hold."},"spiked":{"check":"Did a campaign, a press piece or a creator post make people search the brand?","yes":"The rise lands on the home page and brand queries, and fades when the campaign ends."}},{"id":"landing-pages","label":"Pages that rank","breakdown":"$pathname","dropped":{"check":"Did a ranking page get removed, redirected, noindexed or slower?","yes":"One or two landing paths account for most of the fall."},"spiked":{"check":"Did a new or updated page start ranking for a valuable query?","yes":"One or two landing paths account for most of the rise."}}],"diagnose_order":["classification","google-update","calendar","brand-demand","landing-pages"],"related":["sessions","paid-sessions","referral-sessions","new-visitor-share","conversion-rate"],"prose":{"why_it_matters":"Organic search is the traffic a store doesn't pay for each week, so it sets how much of growth has to be bought. It also moves on dates you can look up: Google ships several core updates a year, and a store with 125,000 organic sessions a week can lose 15% in the days after one without changing a thing.","pitfalls":["Google Ads auto-tagging adds a gclid but no UTM tags. Without checking the click id, paid search clicks land in organic and organic looks better than it is.","Organic here means search engines only, GA4's Organic Search group. Unpaid social posts, emails and links from other sites are separate channels, and GA4's Organic Social, Organic Video and Organic Shopping groups are not included.","Visits from ChatGPT, Perplexity and other AI assistants arrive as referrals, not search, even when they answer what used to be a search. Read them in referral sessions.","Search engines don't pass the keyword, so this number can't tell branded from unbranded searches. Use Search Console for that split, and expect its clicks never to match sessions exactly, because consent banners, ad blockers and slow pages lose some visits."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "pages-per-session": { yaml: "id: pages-per-session\nname: Pages per session\naliases:\n  - Pages per visit\n  - Pageviews per session\n  - Views per session\n  - Page depth\nfamily: traffic\nkind: ratio\npolarity: up-is-good\n\ndefinition:\n  one_line: The average number of pages viewed in one visit, across all visits in the week.\n  formula: Page views ÷ sessions with a page view\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change, captured in the browser.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: $session_id\n        description: Set by the analytics SDK; ties the page view to a visit.\n      - name: $pathname\n        description: The page's path, for finding where visits end.\n      - name: $device_type\n        description: Mobile, Desktop or Tablet.\n\nnumerator:\n  label: Page views\n  aggregate: count\n  event: $pageview\ndenominator:\n  label: Sessions\n  aggregate: unique_sessions\n  event: $pageview\n\nnoise:\n  type: mean\n  cv: 1.3\n  min_denominator: 200\n  volume_unit: sessions a week\n  typical: 3.4\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: store\n  level: 3.6\n  volume: 520000\n  trend: 0\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    breakdown: $browser\n    dropped:\n      check: Did a release stop client-side route changes from sending a page view?\n      yes: Page views fall on the release day while sessions, product views and orders hold.\n    spiked:\n      check: Is a page view firing twice, from two tags or a router that reports every route change twice?\n      yes: Pages per session rise by about one (a second tag on page load) or nearly double (every route change sent twice) overnight while orders don't move.\n  - id: bounce\n    label: One-page visits\n    metric: bounce-rate\n    dropped:\n      check: Did more visits leave after the first page?\n      yes: Bounce rate rises by enough to explain the fall; visits that stay browse as deeply as before.\n    spiked:\n      check: Did fewer visits bounce, or did a bot that viewed one page stop?\n      yes: Bounce rate falls and the visits that remain look like last week's.\n  - id: traffic-mix\n    label: Who arrived\n    metric: paid-sessions\n    breakdown: utm_medium\n    dropped:\n      check: Did a larger share of visits come from paid social, email or a viral link, which browse less?\n      yes: Every channel holds its own depth but the shallow channel grew.\n    spiked:\n      check: Did returning visitors or search traffic, which browse more, grow as a share?\n      yes: Every channel holds its own depth but the deep channel grew.\n  - id: navigation\n    label: Navigation, search and collections\n    metric: product-view-rate\n    breakdown: $pathname\n    dropped:\n      check: Did a menu, collection page or on-site search change make it harder to find more products?\n      yes: Fewer visits move from collection or search pages to product pages after the change.\n    spiked:\n      check: Did a change add steps, such as pagination, a quiz or an interstitial, without adding interest?\n      yes: Pages per session rise but product views and orders per session don't.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the fall on one device only?\n      yes: One device drops after a layout or menu change while the other holds.\n    spiked:\n      check: Is the rise on one device only?\n      yes: One device rises after a release; confirm it isn't a page view firing twice there.\n\ndiagnose_order: [tracking, bounce, traffic-mix, navigation, device-split]\n\nrelated: [bounce-rate, sessions, product-view-rate, conversion-rate, sessions-per-user]\n\nprose:\n  why_it_matters: >-\n    Pages per session says how far an average visit gets into the store. It moves with intent,\n    with navigation and with tracking, and only the first two are real. A store averaging 3.6\n    pages gains nothing from 4.0 if the extra page is a slower checkout or a second page view\n    firing; read it with product views and conversion, never alone.\n  pitfalls:\n    - On a single-page app, page views depend on whether every route change is tracked. A router update can change this number by a full page with no change in behaviour.\n    - More pages is not always better. Pagination, quizzes and confusing menus add pages to visits that end the same way.\n    - The average hides a long tail. A few bots or heavy browsers viewing hundreds of pages can lift it; check the median when it jumps.\n    - Comparing with GA4 views per session needs the same unit. GA4 counts screen views from apps too and divides by all sessions, not sessions with a page view.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"pages-per-session","name":"Pages per session","aliases":["Pages per visit","Pageviews per session","Views per session","Page depth"],"family":"traffic","kind":"ratio","polarity":"up-is-good","definition":{"one_line":"The average number of pages viewed in one visit, across all visits in the week.","formula":"Page views ÷ sessions with a page view"},"events":[{"name":"$pageview","description":"One page load or client-side route change, captured in the browser.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"$session_id","description":"Set by the analytics SDK; ties the page view to a visit."},{"name":"$pathname","description":"The page's path, for finding where visits end."},{"name":"$device_type","description":"Mobile, Desktop or Tablet."}]}],"numerator":{"label":"Page views","aggregate":"count","event":"$pageview"},"denominator":{"label":"Sessions","aggregate":"unique_sessions","event":"$pageview"},"noise":{"type":"mean","cv":1.3,"min_denominator":200,"volume_unit":"sessions a week","typical":3.4,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"store","level":3.6,"volume":520000,"trend":0},"drivers":[{"id":"tracking","label":"Tracking change","breakdown":"$browser","dropped":{"check":"Did a release stop client-side route changes from sending a page view?","yes":"Page views fall on the release day while sessions, product views and orders hold."},"spiked":{"check":"Is a page view firing twice, from two tags or a router that reports every route change twice?","yes":"Pages per session rise by about one (a second tag on page load) or nearly double (every route change sent twice) overnight while orders don't move."}},{"id":"bounce","label":"One-page visits","metric":"bounce-rate","dropped":{"check":"Did more visits leave after the first page?","yes":"Bounce rate rises by enough to explain the fall; visits that stay browse as deeply as before."},"spiked":{"check":"Did fewer visits bounce, or did a bot that viewed one page stop?","yes":"Bounce rate falls and the visits that remain look like last week's."}},{"id":"traffic-mix","label":"Who arrived","metric":"paid-sessions","breakdown":"utm_medium","dropped":{"check":"Did a larger share of visits come from paid social, email or a viral link, which browse less?","yes":"Every channel holds its own depth but the shallow channel grew."},"spiked":{"check":"Did returning visitors or search traffic, which browse more, grow as a share?","yes":"Every channel holds its own depth but the deep channel grew."}},{"id":"navigation","label":"Navigation, search and collections","metric":"product-view-rate","breakdown":"$pathname","dropped":{"check":"Did a menu, collection page or on-site search change make it harder to find more products?","yes":"Fewer visits move from collection or search pages to product pages after the change."},"spiked":{"check":"Did a change add steps, such as pagination, a quiz or an interstitial, without adding interest?","yes":"Pages per session rise but product views and orders per session don't."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the fall on one device only?","yes":"One device drops after a layout or menu change while the other holds."},"spiked":{"check":"Is the rise on one device only?","yes":"One device rises after a release; confirm it isn't a page view firing twice there."}}],"diagnose_order":["tracking","bounce","traffic-mix","navigation","device-split"],"related":["bounce-rate","sessions","product-view-rate","conversion-rate","sessions-per-user"],"prose":{"why_it_matters":"Pages per session says how far an average visit gets into the store. It moves with intent, with navigation and with tracking, and only the first two are real. A store averaging 3.6 pages gains nothing from 4.0 if the extra page is a slower checkout or a second page view firing; read it with product views and conversion, never alone.","pitfalls":["On a single-page app, page views depend on whether every route change is tracked. A router update can change this number by a full page with no change in behaviour.","More pages is not always better. Pagination, quizzes and confusing menus add pages to visits that end the same way.","The average hides a long tail. A few bots or heavy browsers viewing hundreds of pages can lift it; check the median when it jumps.","Comparing with GA4 views per session needs the same unit. GA4 counts screen views from apps too and divides by all sessions, not sessions with a page view."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "paid-conversion-rate": { yaml: "id: paid-conversion-rate\nname: Paid conversion rate\naliases:\n  - Paid traffic conversion rate\n  - Ad conversion rate\n  - Paid session conversion rate\nfamily: acquisition\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of visits that arrived through a paid ad and placed an order in the same visit.\n  formula: Paid-ad sessions with an order ÷ paid-ad sessions\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change; the session's first page view decides whether it came from an ad.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: utm_medium\n        description: The campaign medium from the landing URL. Paid when it contains \"cp\", starts with \"paid\", or is ppc, retargeting, display or banner.\n      - name: utm_source\n        description: The platform that sent the click (google, facebook, tiktok).\n      - name: gclid\n        description: Google Ads click id from auto-tagging. Also gbraid, wbraid, and msclkid for Microsoft Ads.\n  - name: order_completed\n    description: A paid order confirmed by the server, carrying the session id of the visit it was placed in.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: $session_id\n        description: The visit the order was placed in, passed from the browser to the server event.\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n\nnumerator:\n  label: Paid sessions with an order\n  aggregate: unique_sessions\n  event: order_completed\ndenominator:\n  label: Paid sessions\n  aggregate: unique_sessions\n  event: $pageview\n  where:\n    - property: utm_medium\n      op: in\n      value: [cpc, ppc, cpm, paid, paid_search, paid_social, paidsocial, display, retargeting]\n\nqueries:\n  hogql: |-\n    -- Paid conversion rate per week: sessions that arrived through a paid ad (paid utm_medium or ad click id on the first page view) and placed an order ÷ sessions that arrived through a paid ad. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(s.converted, 0) AS numerator,\n      coalesce(s.sessions, 0) AS denominator,\n      if(denominator = 0, NULL, numerator / denominator) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, countIf(orders > 0) AS converted, count() AS sessions\n      FROM (\n        SELECT\n          $session_id AS session_id,\n          toMonday(toTimeZone(minIf(timestamp, event = '$pageview'), 'UTC')) AS week,\n          argMinIf(lower(coalesce(properties.utm_medium, '')), timestamp, event = '$pageview') AS medium,\n          argMinIf(coalesce(properties.gclid, properties.gbraid, properties.wbraid, properties.msclkid, '') <> '', timestamp, event = '$pageview') AS ad_click,\n          countIf(event = 'order_completed') AS orders\n        FROM events\n        WHERE event IN ('$pageview', 'order_completed')\n          AND $session_id != ''\n          AND timestamp >= now() - toIntervalWeek(27)\n          AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n        GROUP BY session_id\n        HAVING countIf(event = '$pageview') > 0\n      )\n      WHERE (match(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n      GROUP BY week\n    ) AS s ON s.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Paid conversion rate per week: sessions that arrived through a paid ad (paid utm_medium or ad click id on the first page view) and placed an order ÷ sessions that arrived through a paid ad. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    entries AS (\n      SELECT DISTINCT ON (session_id)\n        session_id,\n        date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n        lower(coalesce(properties->>'utm_medium', '')) AS medium,\n        coalesce(properties->>'gclid', properties->>'gbraid', properties->>'wbraid', properties->>'msclkid', '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id <> ''\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n      ORDER BY session_id, occurred_at\n    ),\n    ordered AS (\n      SELECT DISTINCT session_id\n      FROM events\n      WHERE event_name = 'order_completed'\n        AND session_id <> ''\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n    ),\n    weekly AS (\n      SELECT e.week, count(o.session_id) AS converted, count(*) AS sessions\n      FROM entries AS e\n      LEFT JOIN ordered AS o ON o.session_id = e.session_id\n      WHERE (e.medium ~ '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$' OR e.ad_click)\n      GROUP BY e.week\n    )\n    SELECT\n      w.week,\n      coalesce(s.converted, 0) AS numerator,\n      coalesce(s.sessions, 0) AS denominator,\n      s.converted::numeric / nullif(s.sessions, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS s ON s.week = w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Paid conversion rate per week: sessions that arrived through a paid ad (paid utm_medium or ad click id on the first page view) and placed an order ÷ sessions that arrived through a paid ad. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    entries AS (\n      SELECT\n        session_id,\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n        LOWER(COALESCE(JSON_VALUE(properties, '$.utm_medium'), '')) AS medium,\n        COALESCE(JSON_VALUE(properties, '$.gclid'), JSON_VALUE(properties, '$.gbraid'), JSON_VALUE(properties, '$.wbraid'), JSON_VALUE(properties, '$.msclkid'), '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id <> ''\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n    ),\n    ordered AS (\n      SELECT DISTINCT session_id\n      FROM events\n      WHERE event_name = 'order_completed'\n        AND session_id <> ''\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    ),\n    weekly AS (\n      SELECT e.week, COUNT(o.session_id) AS converted, COUNT(*) AS sessions\n      FROM entries AS e\n      LEFT JOIN ordered AS o ON o.session_id = e.session_id\n      WHERE (REGEXP_CONTAINS(e.medium, r'^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR e.ad_click)\n      GROUP BY e.week\n    )\n    SELECT\n      w.week,\n      COALESCE(s.converted, 0) AS numerator,\n      COALESCE(s.sessions, 0) AS denominator,\n      SAFE_DIVIDE(s.converted, s.sessions) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS s ON s.week = w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Paid conversion rate per week: sessions that arrived through a paid ad (paid utm_medium or ad click id on the first page view) and placed an order ÷ sessions that arrived through a paid ad. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    entries AS (\n      SELECT\n        session_id,\n        DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n        LOWER(COALESCE(properties:\"utm_medium\"::string, '')) AS medium,\n        COALESCE(properties:\"gclid\"::string, properties:\"gbraid\"::string, properties:\"wbraid\"::string, properties:\"msclkid\"::string, '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id <> ''\n        AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n    ),\n    ordered AS (\n      SELECT DISTINCT session_id\n      FROM events\n      WHERE event_name = 'order_completed'\n        AND session_id <> ''\n        AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n    ),\n    weekly AS (\n      SELECT e.week, COUNT(o.session_id) AS converted, COUNT(*) AS sessions\n      FROM entries AS e\n      LEFT JOIN ordered AS o ON o.session_id = e.session_id\n      WHERE (REGEXP_LIKE(e.medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR e.ad_click)\n      GROUP BY e.week\n    )\n    SELECT\n      w.week,\n      COALESCE(s.converted, 0) AS numerator,\n      COALESCE(s.sessions, 0) AS denominator,\n      s.converted::float / NULLIF(s.sessions, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS s ON s.week = w.week\n    ORDER BY w.week;\n\nnoise:\n  type: binomial\n  min_denominator: 300\n  volume_unit: paid sessions a week\n  typical: 0.02\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: store\n  level: 0.021\n  volume: 180000\n  trend: 0\n\ndrivers:\n  - id: tracking\n    label: Tracking and attribution\n    dropped:\n      check: Did orders stop carrying the browser's session id, or did a redirect strip tags from the landing URL?\n      yes: Total orders hold while orders matched to paid sessions fall, from the day of a checkout or redirect change.\n    spiked:\n      check: Did paid sessions lose tags, shrinking the denominator, or are orders recorded twice?\n      yes: Paid sessions fall with no fall in ad clicks, or recorded orders exceed the store admin's.\n  - id: landing\n    label: Landing pages and site health\n    feed: cloudflare\n    dropped:\n      check: Did a landing page break, slow down, sell out or stop matching its ad?\n      yes: Bounce from paid traffic rises on one landing path or device from a dated change.\n    spiked:\n      check: Did a faster or better-matched landing page go live, or did last week's outage end?\n      yes: The rise starts on the day of the page change on the campaigns that use it.\n  - id: calendar\n    label: Calendar and offers\n    feed: shopping\n    dropped:\n      check: Did a sale or holiday end, so the same ads now reach people with less reason to buy?\n      yes: The same weeks last year show the same fall after the event.\n    spiked:\n      check: Is a sale, holiday or new offer turning the same clicks into more orders?\n      yes: The same week last year shows the same rise, and promo code use is up.\n  - id: audience\n    label: Who the ads reached\n    metric: paid-sessions\n    breakdown: utm_source\n    dropped:\n      check: Did spend shift to prospecting, a new platform or broad audiences that convert lower?\n      yes: Each source holds its own rate but a low-converting one grew its share of paid sessions.\n    spiked:\n      check: Did spend shift to retargeting or branded search, which convert far higher?\n      yes: Each source holds its own rate but a high-converting one grew its share.\n  - id: checkout\n    label: Checkout and payment\n    metric: checkout-conversion\n    feed: stripe\n    dropped:\n      check: Did checkout or payment break for everyone, not only paid visitors?\n      yes: Checkout conversion falls across all channels in the same days.\n    spiked:\n      check: Did a checkout or payment fix lift every channel?\n      yes: Checkout conversion rises across all channels from the day of the fix.\n  - id: device\n    label: Mobile conversion\n    metric: mobile-conversion-rate\n    dropped:\n      check: Did mobile conversion fall, where most paid social traffic lands?\n      yes: Mobile conversion falls while desktop holds.\n    spiked:\n      check: Did a mobile fix or a faster mobile page lift conversion?\n      yes: Mobile conversion rises while desktop holds.\n\ndiagnose_order: [tracking, landing, calendar, audience, checkout, device]\n\nrelated: [conversion-rate, paid-sessions, roas, ncac, cpc, checkout-conversion]\n\nprose:\n  why_it_matters: >-\n    This is the step between a paid click and an order, and the one the store, not the ad\n    platform, controls. With cost per click fixed by the auction, it sets what a paid order\n    costs: at $1.25 a click, 2.1% conversion is $60 of media per order, and 1.7% is $74.\n  pitfalls:\n    - Same-visit attribution misses buyers who click an ad and come back later to buy, often a large share of ad-driven orders, so this rate reads lower than the platforms' own, which credit orders days after the click.\n    - Prospecting and retargeting often convert several times apart. A move in the blended rate is usually a mix change; split by source and campaign first.\n    - Server-side order events need the browser's session id passed through checkout, or orders can't be matched to the visit that brought them.\n    - Google Ads auto-tagged clicks carry a gclid and no UTM tags. This query counts the click id; a tag-only rule drops those sessions from the denominator.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"paid-conversion-rate","name":"Paid conversion rate","aliases":["Paid traffic conversion rate","Ad conversion rate","Paid session conversion rate"],"family":"acquisition","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of visits that arrived through a paid ad and placed an order in the same visit.","formula":"Paid-ad sessions with an order ÷ paid-ad sessions"},"events":[{"name":"$pageview","description":"One page load or client-side route change; the session's first page view decides whether it came from an ad.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"utm_medium","description":"The campaign medium from the landing URL. Paid when it contains \"cp\", starts with \"paid\", or is ppc, retargeting, display or banner."},{"name":"utm_source","description":"The platform that sent the click (google, facebook, tiktok)."},{"name":"gclid","description":"Google Ads click id from auto-tagging. Also gbraid, wbraid, and msclkid for Microsoft Ads."}]},{"name":"order_completed","description":"A paid order confirmed by the server, carrying the session id of the visit it was placed in.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"$session_id","description":"The visit the order was placed in, passed from the browser to the server event."},{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."}]}],"numerator":{"label":"Paid sessions with an order","aggregate":"unique_sessions","event":"order_completed"},"denominator":{"label":"Paid sessions","aggregate":"unique_sessions","event":"$pageview","where":[{"property":"utm_medium","op":"in","value":["cpc","ppc","cpm","paid","paid_search","paid_social","paidsocial","display","retargeting"]}]},"queries":{"hogql":"-- Paid conversion rate per week: sessions that arrived through a paid ad (paid utm_medium or ad click id on the first page view) and placed an order ÷ sessions that arrived through a paid ad. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(s.converted, 0) AS numerator,\n  coalesce(s.sessions, 0) AS denominator,\n  if(denominator = 0, NULL, numerator / denominator) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, countIf(orders > 0) AS converted, count() AS sessions\n  FROM (\n    SELECT\n      $session_id AS session_id,\n      toMonday(toTimeZone(minIf(timestamp, event = '$pageview'), 'UTC')) AS week,\n      argMinIf(lower(coalesce(properties.utm_medium, '')), timestamp, event = '$pageview') AS medium,\n      argMinIf(coalesce(properties.gclid, properties.gbraid, properties.wbraid, properties.msclkid, '') <> '', timestamp, event = '$pageview') AS ad_click,\n      countIf(event = 'order_completed') AS orders\n    FROM events\n    WHERE event IN ('$pageview', 'order_completed')\n      AND $session_id != ''\n      AND timestamp >= now() - toIntervalWeek(27)\n      AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n    GROUP BY session_id\n    HAVING countIf(event = '$pageview') > 0\n  )\n  WHERE (match(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n  GROUP BY week\n) AS s ON s.week = w.week\nORDER BY week","postgres":"-- Paid conversion rate per week: sessions that arrived through a paid ad (paid utm_medium or ad click id on the first page view) and placed an order ÷ sessions that arrived through a paid ad. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nentries AS (\n  SELECT DISTINCT ON (session_id)\n    session_id,\n    date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n    lower(coalesce(properties->>'utm_medium', '')) AS medium,\n    coalesce(properties->>'gclid', properties->>'gbraid', properties->>'wbraid', properties->>'msclkid', '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id <> ''\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n  ORDER BY session_id, occurred_at\n),\nordered AS (\n  SELECT DISTINCT session_id\n  FROM events\n  WHERE event_name = 'order_completed'\n    AND session_id <> ''\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n),\nweekly AS (\n  SELECT e.week, count(o.session_id) AS converted, count(*) AS sessions\n  FROM entries AS e\n  LEFT JOIN ordered AS o ON o.session_id = e.session_id\n  WHERE (e.medium ~ '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$' OR e.ad_click)\n  GROUP BY e.week\n)\nSELECT\n  w.week,\n  coalesce(s.converted, 0) AS numerator,\n  coalesce(s.sessions, 0) AS denominator,\n  s.converted::numeric / nullif(s.sessions, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS s ON s.week = w.week\nORDER BY w.week;","bigquery":"-- Paid conversion rate per week: sessions that arrived through a paid ad (paid utm_medium or ad click id on the first page view) and placed an order ÷ sessions that arrived through a paid ad. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nentries AS (\n  SELECT\n    session_id,\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n    LOWER(COALESCE(JSON_VALUE(properties, '$.utm_medium'), '')) AS medium,\n    COALESCE(JSON_VALUE(properties, '$.gclid'), JSON_VALUE(properties, '$.gbraid'), JSON_VALUE(properties, '$.wbraid'), JSON_VALUE(properties, '$.msclkid'), '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id <> ''\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n),\nordered AS (\n  SELECT DISTINCT session_id\n  FROM events\n  WHERE event_name = 'order_completed'\n    AND session_id <> ''\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n),\nweekly AS (\n  SELECT e.week, COUNT(o.session_id) AS converted, COUNT(*) AS sessions\n  FROM entries AS e\n  LEFT JOIN ordered AS o ON o.session_id = e.session_id\n  WHERE (REGEXP_CONTAINS(e.medium, r'^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR e.ad_click)\n  GROUP BY e.week\n)\nSELECT\n  w.week,\n  COALESCE(s.converted, 0) AS numerator,\n  COALESCE(s.sessions, 0) AS denominator,\n  SAFE_DIVIDE(s.converted, s.sessions) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS s ON s.week = w.week\nORDER BY w.week;","snowflake":"-- Paid conversion rate per week: sessions that arrived through a paid ad (paid utm_medium or ad click id on the first page view) and placed an order ÷ sessions that arrived through a paid ad. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nentries AS (\n  SELECT\n    session_id,\n    DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n    LOWER(COALESCE(properties:\"utm_medium\"::string, '')) AS medium,\n    COALESCE(properties:\"gclid\"::string, properties:\"gbraid\"::string, properties:\"wbraid\"::string, properties:\"msclkid\"::string, '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id <> ''\n    AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n),\nordered AS (\n  SELECT DISTINCT session_id\n  FROM events\n  WHERE event_name = 'order_completed'\n    AND session_id <> ''\n    AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n),\nweekly AS (\n  SELECT e.week, COUNT(o.session_id) AS converted, COUNT(*) AS sessions\n  FROM entries AS e\n  LEFT JOIN ordered AS o ON o.session_id = e.session_id\n  WHERE (REGEXP_LIKE(e.medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR e.ad_click)\n  GROUP BY e.week\n)\nSELECT\n  w.week,\n  COALESCE(s.converted, 0) AS numerator,\n  COALESCE(s.sessions, 0) AS denominator,\n  s.converted::float / NULLIF(s.sessions, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS s ON s.week = w.week\nORDER BY w.week;"},"noise":{"type":"binomial","min_denominator":300,"volume_unit":"paid sessions a week","typical":0.02,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"store","level":0.021,"volume":180000,"trend":0},"drivers":[{"id":"tracking","label":"Tracking and attribution","dropped":{"check":"Did orders stop carrying the browser's session id, or did a redirect strip tags from the landing URL?","yes":"Total orders hold while orders matched to paid sessions fall, from the day of a checkout or redirect change."},"spiked":{"check":"Did paid sessions lose tags, shrinking the denominator, or are orders recorded twice?","yes":"Paid sessions fall with no fall in ad clicks, or recorded orders exceed the store admin's."}},{"id":"landing","label":"Landing pages and site health","feed":"cloudflare","dropped":{"check":"Did a landing page break, slow down, sell out or stop matching its ad?","yes":"Bounce from paid traffic rises on one landing path or device from a dated change."},"spiked":{"check":"Did a faster or better-matched landing page go live, or did last week's outage end?","yes":"The rise starts on the day of the page change on the campaigns that use it."}},{"id":"calendar","label":"Calendar and offers","feed":"shopping","dropped":{"check":"Did a sale or holiday end, so the same ads now reach people with less reason to buy?","yes":"The same weeks last year show the same fall after the event."},"spiked":{"check":"Is a sale, holiday or new offer turning the same clicks into more orders?","yes":"The same week last year shows the same rise, and promo code use is up."}},{"id":"audience","label":"Who the ads reached","metric":"paid-sessions","breakdown":"utm_source","dropped":{"check":"Did spend shift to prospecting, a new platform or broad audiences that convert lower?","yes":"Each source holds its own rate but a low-converting one grew its share of paid sessions."},"spiked":{"check":"Did spend shift to retargeting or branded search, which convert far higher?","yes":"Each source holds its own rate but a high-converting one grew its share."}},{"id":"checkout","label":"Checkout and payment","metric":"checkout-conversion","feed":"stripe","dropped":{"check":"Did checkout or payment break for everyone, not only paid visitors?","yes":"Checkout conversion falls across all channels in the same days."},"spiked":{"check":"Did a checkout or payment fix lift every channel?","yes":"Checkout conversion rises across all channels from the day of the fix."}},{"id":"device","label":"Mobile conversion","metric":"mobile-conversion-rate","dropped":{"check":"Did mobile conversion fall, where most paid social traffic lands?","yes":"Mobile conversion falls while desktop holds."},"spiked":{"check":"Did a mobile fix or a faster mobile page lift conversion?","yes":"Mobile conversion rises while desktop holds."}}],"diagnose_order":["tracking","landing","calendar","audience","checkout","device"],"related":["conversion-rate","paid-sessions","roas","ncac","cpc","checkout-conversion"],"prose":{"why_it_matters":"This is the step between a paid click and an order, and the one the store, not the ad platform, controls. With cost per click fixed by the auction, it sets what a paid order costs: at $1.25 a click, 2.1% conversion is $60 of media per order, and 1.7% is $74.","pitfalls":["Same-visit attribution misses buyers who click an ad and come back later to buy, often a large share of ad-driven orders, so this rate reads lower than the platforms' own, which credit orders days after the click.","Prospecting and retargeting often convert several times apart. A move in the blended rate is usually a mix change; split by source and campaign first.","Server-side order events need the browser's session id passed through checkout, or orders can't be matched to the visit that brought them.","Google Ads auto-tagged clicks carry a gclid and no UTM tags. This query counts the click id; a tag-only rule drops those sessions from the denominator."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "paid-sessions": { yaml: "id: paid-sessions\nname: Paid sessions\naliases:\n  - Paid traffic\n  - Paid visits\n  - Paid media sessions\nfamily: traffic\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: Visits that arrived from a paid ad, judged by the campaign tag or ad click id on the first page of the visit.\n  formula: Sessions whose first page view has a paid utm_medium (cpc, cpm, paid_social, display) or a Google or Microsoft ad click id\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change, captured in the browser.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: $session_id\n        description: Set by the analytics SDK; the session's first page view decides its channel.\n      - name: utm_medium\n        description: The campaign medium from the landing URL. Paid when it contains \"cp\", starts with \"paid\", or is ppc, retargeting, display or banner.\n      - name: utm_source\n        description: The platform that sent the click (google, facebook, tiktok).\n      - name: gclid\n        description: Google Ads click id, added by auto-tagging. Also gbraid, wbraid, and msclkid for Microsoft Ads.\n\nnumerator:\n  label: Paid sessions\n  aggregate: unique_sessions\n  event: $pageview\n  where:\n    - property: utm_medium\n      op: in\n      value: [cpc, ppc, cpm, paid, paid_search, paid_social, paidsocial, display, retargeting]\n\nqueries:\n  hogql: |-\n    -- Paid sessions per week: sessions whose first page view carries a paid utm_medium (GA4's paid rule) or an ad click id. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT w.week AS week, coalesce(s.sessions, 0) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, count() AS sessions\n      FROM (\n        SELECT\n          $session_id AS session_id,\n          toMonday(toTimeZone(min(timestamp), 'UTC')) AS week,\n          argMin(lower(coalesce(properties.utm_medium, '')), timestamp) AS medium,\n          argMin(coalesce(properties.gclid, properties.gbraid, properties.wbraid, properties.msclkid, '') <> '', timestamp) AS ad_click\n        FROM events\n        WHERE event = '$pageview'\n          AND $session_id != ''\n          AND timestamp >= now() - toIntervalWeek(27)\n          AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n        GROUP BY session_id\n      )\n      WHERE (match(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n      GROUP BY week\n    ) AS s ON s.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Paid sessions per week: sessions whose first page view carries a paid utm_medium (GA4's paid rule) or an ad click id. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    entries AS (\n      SELECT DISTINCT ON (session_id)\n        session_id,\n        date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n        lower(coalesce(properties->>'utm_medium', '')) AS medium,\n        coalesce(properties->>'gclid', properties->>'gbraid', properties->>'wbraid', properties->>'msclkid', '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id <> ''\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n      ORDER BY session_id, occurred_at\n    ),\n    weekly AS (\n      SELECT week, count(*) AS sessions\n      FROM entries\n      WHERE (medium ~ '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$' OR ad_click)\n      GROUP BY week\n    )\n    SELECT w.week, coalesce(s.sessions, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS s ON s.week = w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Paid sessions per week: sessions whose first page view carries a paid utm_medium (GA4's paid rule) or an ad click id. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    entries AS (\n      SELECT\n        session_id,\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n        LOWER(COALESCE(JSON_VALUE(properties, '$.utm_medium'), '')) AS medium,\n        COALESCE(JSON_VALUE(properties, '$.gclid'), JSON_VALUE(properties, '$.gbraid'), JSON_VALUE(properties, '$.wbraid'), JSON_VALUE(properties, '$.msclkid'), '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id <> ''\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n    ),\n    weekly AS (\n      SELECT week, COUNT(*) AS sessions\n      FROM entries\n      WHERE (REGEXP_CONTAINS(medium, r'^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n      GROUP BY week\n    )\n    SELECT w.week, COALESCE(s.sessions, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS s ON s.week = w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Paid sessions per week: sessions whose first page view carries a paid utm_medium (GA4's paid rule) or an ad click id. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    entries AS (\n      SELECT\n        session_id,\n        DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n        LOWER(COALESCE(properties:\"utm_medium\"::string, '')) AS medium,\n        COALESCE(properties:\"gclid\"::string, properties:\"gbraid\"::string, properties:\"wbraid\"::string, properties:\"msclkid\"::string, '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id <> ''\n        AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n    ),\n    weekly AS (\n      SELECT week, COUNT(*) AS sessions\n      FROM entries\n      WHERE (REGEXP_LIKE(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n      GROUP BY week\n    )\n    SELECT w.week, COALESCE(s.sessions, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS s ON s.week = w.week\n    ORDER BY w.week;\n\nnoise:\n  type: poisson\n  min_denominator: 100\n  volume_unit: paid sessions a week\n  typical: 15000\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: store\n  level: 180000\n  volume: 180000\n  trend: 0.2\n\ndrivers:\n  - id: tagging\n    label: Campaign tags and click ids\n    dropped:\n      check: Did a new campaign, landing page or redirect lose its UTM tags or click id?\n      yes: Organic or direct sessions rise by about as much as paid falls, from the day the campaign or redirect changed.\n    spiked:\n      check: Did someone tag non-paid links as paid, such as a newsletter or an influencer link with utm_medium=cpc?\n      yes: The new paid sessions come from a source with no spend behind it.\n  - id: spend\n    label: Ad spend\n    metric: ad-spend\n    feed: ad-platforms\n    dropped:\n      check: Did spend fall, from a paused campaign, a budget cut, a declined card or a rejected ad?\n      yes: Spend on one platform falls by about the same share as its paid sessions.\n    spiked:\n      check: Did a budget increase or a new campaign start?\n      yes: Spend rises on one platform by about the share paid sessions did; check that conversion held.\n  - id: cpc\n    label: Cost per click\n    metric: cpc\n    dropped:\n      check: With spend steady, did each click get more expensive?\n      yes: CPC rises on one platform while spend holds, so the same budget buys fewer clicks.\n    spiked:\n      check: With spend steady, did clicks get cheaper?\n      yes: CPC falls; check whether a cheap placement such as Audience Network or display is buying low-quality clicks.\n  - id: invalid-clicks\n    label: Bots and invalid clicks\n    breakdown: $geoip_country_code\n    dropped:\n      check: Did the platform start filtering a bot source that used to click?\n      yes: Clicks fall in one country or placement while orders hold.\n    spiked:\n      check: Is a bot, click farm or an accidental-click placement inflating visits?\n      yes: The new sessions bounce at once, come from one placement, country or app, and never order.\n  - id: landing\n    label: Landing page availability\n    feed: cloudflare\n    dropped:\n      check: Did the landing page error or redirect, so clicks were paid for but never recorded as visits?\n      yes: Platform clicks hold while recorded paid sessions fall in the hours of an incident.\n    spiked:\n      check: Was last week depressed by a landing-page outage?\n      yes: Last week shows the gap; this week is back to its usual level.\n\ndiagnose_order: [tagging, spend, cpc, invalid-clicks, landing]\n\nrelated: [ad-spend, cpc, ctr, paid-conversion-rate, sessions, organic-sessions]\n\nprose:\n  why_it_matters: >-\n    Paid sessions are the traffic the store buys, so they should move with spend and almost\n    nothing else. When they don't, either the price of a click changed or the tracking did.\n    Ad platforms report clicks, not visits; some paid clicks never become a recorded session,\n    and a sudden widening of that gap is worth watching on its own.\n  pitfalls:\n    - Clicks in the ad platform and sessions in analytics never match. Slow pages, consent banners, ad blockers and accidental taps on mobile all lose visits between the two.\n    - Google Ads auto-tagging adds a gclid but no UTM tags. Checking only utm_medium puts those clicks in organic search.\n    - The classification is by first page view. A visitor who clicks an ad, leaves and returns later from a bookmark is paid once and direct the second time.\n    - Tags are case sensitive in most tools. CPC, Cpc and cpc split one channel three ways unless the query lowercases them, as this one does.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"paid-sessions","name":"Paid sessions","aliases":["Paid traffic","Paid visits","Paid media sessions"],"family":"traffic","kind":"count","polarity":"up-is-good","definition":{"one_line":"Visits that arrived from a paid ad, judged by the campaign tag or ad click id on the first page of the visit.","formula":"Sessions whose first page view has a paid utm_medium (cpc, cpm, paid_social, display) or a Google or Microsoft ad click id"},"events":[{"name":"$pageview","description":"One page load or client-side route change, captured in the browser.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"$session_id","description":"Set by the analytics SDK; the session's first page view decides its channel."},{"name":"utm_medium","description":"The campaign medium from the landing URL. Paid when it contains \"cp\", starts with \"paid\", or is ppc, retargeting, display or banner."},{"name":"utm_source","description":"The platform that sent the click (google, facebook, tiktok)."},{"name":"gclid","description":"Google Ads click id, added by auto-tagging. Also gbraid, wbraid, and msclkid for Microsoft Ads."}]}],"numerator":{"label":"Paid sessions","aggregate":"unique_sessions","event":"$pageview","where":[{"property":"utm_medium","op":"in","value":["cpc","ppc","cpm","paid","paid_search","paid_social","paidsocial","display","retargeting"]}]},"queries":{"hogql":"-- Paid sessions per week: sessions whose first page view carries a paid utm_medium (GA4's paid rule) or an ad click id. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT w.week AS week, coalesce(s.sessions, 0) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, count() AS sessions\n  FROM (\n    SELECT\n      $session_id AS session_id,\n      toMonday(toTimeZone(min(timestamp), 'UTC')) AS week,\n      argMin(lower(coalesce(properties.utm_medium, '')), timestamp) AS medium,\n      argMin(coalesce(properties.gclid, properties.gbraid, properties.wbraid, properties.msclkid, '') <> '', timestamp) AS ad_click\n    FROM events\n    WHERE event = '$pageview'\n      AND $session_id != ''\n      AND timestamp >= now() - toIntervalWeek(27)\n      AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n    GROUP BY session_id\n  )\n  WHERE (match(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n  GROUP BY week\n) AS s ON s.week = w.week\nORDER BY week","postgres":"-- Paid sessions per week: sessions whose first page view carries a paid utm_medium (GA4's paid rule) or an ad click id. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nentries AS (\n  SELECT DISTINCT ON (session_id)\n    session_id,\n    date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n    lower(coalesce(properties->>'utm_medium', '')) AS medium,\n    coalesce(properties->>'gclid', properties->>'gbraid', properties->>'wbraid', properties->>'msclkid', '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id <> ''\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n  ORDER BY session_id, occurred_at\n),\nweekly AS (\n  SELECT week, count(*) AS sessions\n  FROM entries\n  WHERE (medium ~ '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$' OR ad_click)\n  GROUP BY week\n)\nSELECT w.week, coalesce(s.sessions, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS s ON s.week = w.week\nORDER BY w.week;","bigquery":"-- Paid sessions per week: sessions whose first page view carries a paid utm_medium (GA4's paid rule) or an ad click id. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nentries AS (\n  SELECT\n    session_id,\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n    LOWER(COALESCE(JSON_VALUE(properties, '$.utm_medium'), '')) AS medium,\n    COALESCE(JSON_VALUE(properties, '$.gclid'), JSON_VALUE(properties, '$.gbraid'), JSON_VALUE(properties, '$.wbraid'), JSON_VALUE(properties, '$.msclkid'), '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id <> ''\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n),\nweekly AS (\n  SELECT week, COUNT(*) AS sessions\n  FROM entries\n  WHERE (REGEXP_CONTAINS(medium, r'^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n  GROUP BY week\n)\nSELECT w.week, COALESCE(s.sessions, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS s ON s.week = w.week\nORDER BY w.week;","snowflake":"-- Paid sessions per week: sessions whose first page view carries a paid utm_medium (GA4's paid rule) or an ad click id. Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nentries AS (\n  SELECT\n    session_id,\n    DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n    LOWER(COALESCE(properties:\"utm_medium\"::string, '')) AS medium,\n    COALESCE(properties:\"gclid\"::string, properties:\"gbraid\"::string, properties:\"wbraid\"::string, properties:\"msclkid\"::string, '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id <> ''\n    AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n),\nweekly AS (\n  SELECT week, COUNT(*) AS sessions\n  FROM entries\n  WHERE (REGEXP_LIKE(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n  GROUP BY week\n)\nSELECT w.week, COALESCE(s.sessions, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS s ON s.week = w.week\nORDER BY w.week;"},"noise":{"type":"poisson","min_denominator":100,"volume_unit":"paid sessions a week","typical":15000,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"store","level":180000,"volume":180000,"trend":0.2},"drivers":[{"id":"tagging","label":"Campaign tags and click ids","dropped":{"check":"Did a new campaign, landing page or redirect lose its UTM tags or click id?","yes":"Organic or direct sessions rise by about as much as paid falls, from the day the campaign or redirect changed."},"spiked":{"check":"Did someone tag non-paid links as paid, such as a newsletter or an influencer link with utm_medium=cpc?","yes":"The new paid sessions come from a source with no spend behind it."}},{"id":"spend","label":"Ad spend","metric":"ad-spend","feed":"ad-platforms","dropped":{"check":"Did spend fall, from a paused campaign, a budget cut, a declined card or a rejected ad?","yes":"Spend on one platform falls by about the same share as its paid sessions."},"spiked":{"check":"Did a budget increase or a new campaign start?","yes":"Spend rises on one platform by about the share paid sessions did; check that conversion held."}},{"id":"cpc","label":"Cost per click","metric":"cpc","dropped":{"check":"With spend steady, did each click get more expensive?","yes":"CPC rises on one platform while spend holds, so the same budget buys fewer clicks."},"spiked":{"check":"With spend steady, did clicks get cheaper?","yes":"CPC falls; check whether a cheap placement such as Audience Network or display is buying low-quality clicks."}},{"id":"invalid-clicks","label":"Bots and invalid clicks","breakdown":"$geoip_country_code","dropped":{"check":"Did the platform start filtering a bot source that used to click?","yes":"Clicks fall in one country or placement while orders hold."},"spiked":{"check":"Is a bot, click farm or an accidental-click placement inflating visits?","yes":"The new sessions bounce at once, come from one placement, country or app, and never order."}},{"id":"landing","label":"Landing page availability","feed":"cloudflare","dropped":{"check":"Did the landing page error or redirect, so clicks were paid for but never recorded as visits?","yes":"Platform clicks hold while recorded paid sessions fall in the hours of an incident."},"spiked":{"check":"Was last week depressed by a landing-page outage?","yes":"Last week shows the gap; this week is back to its usual level."}}],"diagnose_order":["tagging","spend","cpc","invalid-clicks","landing"],"related":["ad-spend","cpc","ctr","paid-conversion-rate","sessions","organic-sessions"],"prose":{"why_it_matters":"Paid sessions are the traffic the store buys, so they should move with spend and almost nothing else. When they don't, either the price of a click changed or the tracking did. Ad platforms report clicks, not visits; some paid clicks never become a recorded session, and a sudden widening of that gap is worth watching on its own.","pitfalls":["Clicks in the ad platform and sessions in analytics never match. Slow pages, consent banners, ad blockers and accidental taps on mobile all lose visits between the two.","Google Ads auto-tagging adds a gclid but no UTM tags. Checking only utm_medium puts those clicks in organic search.","The classification is by first page view. A visitor who clicks an ad, leaves and returns later from a bookmark is paid once and direct the second time.","Tags are case sensitive in most tools. CPC, Cpc and cpc split one channel three ways unless the query lowercases them, as this one does."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "payment-success-rate": { yaml: "id: payment-success-rate\nname: Payment success rate\naliases:\n  - Payment authorization rate\n  - Authorization rate\n  - Payment approval rate\n  - Payment acceptance rate\nfamily: conversion\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of payment attempts that succeed, across every gateway and payment method, in the week.\n  formula: Successful payment attempts ÷ all payment attempts (succeeded + failed)\n\nevents:\n  - name: payment_succeeded\n    description: A payment authorized and captured, from the processor's webhook, not the browser.\n    also_called: [payment_intent.succeeded, charge.succeeded, Payment Succeeded]\n    properties:\n      - name: gateway\n        description: The processor that handled it (stripe, adyen, paypal, shopify_payments).\n      - name: method\n        description: card, apple_pay, google_pay, paypal, klarna and so on.\n      - name: amount\n        description: The amount attempted.\n  - name: payment_failed\n    description: A payment attempt declined or errored, one event per attempt, from the processor's webhook.\n    also_called: [payment_intent.payment_failed, charge.failed, Payment Failed]\n    properties:\n      - name: gateway\n        description: The processor that handled it.\n      - name: method\n        description: The payment method attempted.\n      - name: decline_code\n        description: The issuer's or processor's reason, such as insufficient_funds, do_not_honor or fraudulent.\n\nnumerator:\n  label: Successful payment attempts\n  aggregate: count\n  event: payment_succeeded\n\nqueries:\n  hogql: |-\n    -- Payment success rate per week: successful payment attempts ÷ all attempts (succeeded + failed). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(p.succeeded, 0) AS numerator,\n      coalesce(p.attempts, 0) AS denominator,\n      if(coalesce(p.attempts, 0) = 0, NULL, p.succeeded / p.attempts) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT\n        toMonday(toTimeZone(timestamp, 'UTC')) AS week,\n        countIf(event = 'payment_succeeded') AS succeeded,\n        count() AS attempts\n      FROM events\n      WHERE event IN ('payment_succeeded', 'payment_failed')\n        AND timestamp >= now() - toIntervalWeek(27)\n        AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n      GROUP BY week\n    ) AS p ON p.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Payment success rate per week: successful payment attempts ÷ all attempts (succeeded + failed). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    payments AS (\n      SELECT\n        date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n        count(*) FILTER (WHERE event_name = 'payment_succeeded') AS succeeded,\n        count(*) AS attempts\n      FROM events\n      WHERE event_name IN ('payment_succeeded', 'payment_failed')\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n      GROUP BY 1\n    )\n    SELECT\n      w.week,\n      coalesce(p.succeeded, 0) AS numerator,\n      coalesce(p.attempts, 0) AS denominator,\n      p.succeeded::numeric / nullif(p.attempts, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN payments AS p ON p.week = w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Payment success rate per week: successful payment attempts ÷ all attempts (succeeded + failed). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    payments AS (\n      SELECT\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n        COUNTIF(event_name = 'payment_succeeded') AS succeeded,\n        COUNT(*) AS attempts\n      FROM events\n      WHERE event_name IN ('payment_succeeded', 'payment_failed')\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      COALESCE(p.succeeded, 0) AS numerator,\n      COALESCE(p.attempts, 0) AS denominator,\n      SAFE_DIVIDE(p.succeeded, p.attempts) AS value\n    FROM weeks AS w\n    LEFT JOIN payments AS p ON p.week = w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Payment success rate per week: successful payment attempts ÷ all attempts (succeeded + failed). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    payments AS (\n      SELECT\n        DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n        COUNT_IF(event_name = 'payment_succeeded') AS succeeded,\n        COUNT(*) AS attempts\n      FROM events\n      WHERE event_name IN ('payment_succeeded', 'payment_failed')\n        AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n      GROUP BY 1\n    )\n    SELECT\n      w.week,\n      COALESCE(p.succeeded, 0) AS numerator,\n      COALESCE(p.attempts, 0) AS denominator,\n      p.succeeded::float / NULLIF(p.attempts, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN payments AS p ON p.week = w.week\n    ORDER BY w.week;\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: payment attempts a week\n  typical: 0.92\n\nexample:\n  business: store\n  level: 0.93\n  volume: 14300\n  trend: 0\n\ndrivers:\n  - id: card-testing\n    label: Card testing and bots\n    dropped:\n      check: Is a card-testing attack sending bursts of failed attempts with stolen cards?\n      yes: Failed attempts spike within hours from a few sessions or IPs, with small amounts and codes like incorrect_cvc, while orders hold.\n    spiked:\n      check: Did a card-testing attack from last week stop, or did a new rule block bots before they reach the processor?\n      yes: Failed attempts fall back while successful payments hold; the rise is a smaller denominator, not more customers paying.\n  - id: processor\n    label: Processor incidents\n    breakdown: gateway\n    feed: stripe\n    dropped:\n      check: Did one gateway or processor have an outage or a degraded period this week?\n      yes: Failures concentrate on one gateway during the hours of an incident on its status page.\n    spiked:\n      check: Did an incident from the week before clear?\n      yes: The affected gateway returns to its usual rate and the others never moved.\n  - id: method\n    label: Payment methods\n    breakdown: method\n    dropped:\n      check: Is one method failing, such as Apple Pay, PayPal, a buy-now-pay-later provider or 3-D Secure cards?\n      yes: One method's success falls while cards and the other methods hold.\n    spiked:\n      check: Did wallets, which approve more often than typed cards, gain share, or did a weak method get removed?\n      yes: Each method's own rate holds and only the mix moved.\n  - id: fraud-rules\n    label: Fraud rules and 3-D Secure\n    breakdown: decline_code\n    dropped:\n      check: Did a fraud rule, risk setting or 3-D Secure change start blocking good customers?\n      yes: One decline code, such as fraudulent or authentication_required, rises from the day the rule changed.\n    spiked:\n      check: Was a fraud rule loosened? Check disputes before celebrating.\n      yes: Blocked attempts fall from the day of the change, and fraud disputes may rise a few weeks later.\n  - id: country-mix\n    label: Countries and card issuers\n    breakdown: $geoip_country_code\n    dropped:\n      check: Did more attempts come from countries where cross-border cards decline more often, for example after a new campaign?\n      yes: One country's share of attempts grows and its success rate sits well below the rest.\n    spiked:\n      check: Did a low-approval country shrink, or did a local payment method launch there?\n      yes: The country mix moved, or one country's rate rose from the day a method launched.\n\ndiagnose_order: [card-testing, processor, method, fraud-rules, country-mix]\n\nrelated: [checkout-conversion, conversion-rate, orders, mobile-conversion-rate, net-revenue]\n\nprose:\n  why_it_matters: >-\n    Every failed payment is a shopper who had already decided to buy and typed in a card. A fall\n    is rarely about the shopper; it is a processor incident, a fraud rule or a bot testing stolen\n    cards. At Northwind, with about 14,000 attempts a week, one point is 140 failed attempts a\n    week, most of them from people who were already at checkout.\n  pitfalls:\n    - Retries count as attempts, so a shopper who is declined twice and then pays is one success in three. Read checkout conversion beside it to see what shoppers experienced.\n    - Card-testing bots can send thousands of failed attempts in an hour and pull a week down ten points with no real customer affected. Split by session or IP before reacting.\n    - Record payment events from the processor's webhooks, not the browser. Browser events miss redirect methods such as PayPal and Klarna and duplicate on reloads.\n    - Processors disagree on what a failure is; a 3-D Secure challenge the shopper abandons is a failure in some and nothing in others. Changing processors moves the rate with no change in approvals.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"payment-success-rate","name":"Payment success rate","aliases":["Payment authorization rate","Authorization rate","Payment approval rate","Payment acceptance rate"],"family":"conversion","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of payment attempts that succeed, across every gateway and payment method, in the week.","formula":"Successful payment attempts ÷ all payment attempts (succeeded + failed)"},"events":[{"name":"payment_succeeded","description":"A payment authorized and captured, from the processor's webhook, not the browser.","also_called":["payment_intent.succeeded","charge.succeeded","Payment Succeeded"],"properties":[{"name":"gateway","description":"The processor that handled it (stripe, adyen, paypal, shopify_payments)."},{"name":"method","description":"card, apple_pay, google_pay, paypal, klarna and so on."},{"name":"amount","description":"The amount attempted."}]},{"name":"payment_failed","description":"A payment attempt declined or errored, one event per attempt, from the processor's webhook.","also_called":["payment_intent.payment_failed","charge.failed","Payment Failed"],"properties":[{"name":"gateway","description":"The processor that handled it."},{"name":"method","description":"The payment method attempted."},{"name":"decline_code","description":"The issuer's or processor's reason, such as insufficient_funds, do_not_honor or fraudulent."}]}],"numerator":{"label":"Successful payment attempts","aggregate":"count","event":"payment_succeeded"},"queries":{"hogql":"-- Payment success rate per week: successful payment attempts ÷ all attempts (succeeded + failed). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(p.succeeded, 0) AS numerator,\n  coalesce(p.attempts, 0) AS denominator,\n  if(coalesce(p.attempts, 0) = 0, NULL, p.succeeded / p.attempts) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT\n    toMonday(toTimeZone(timestamp, 'UTC')) AS week,\n    countIf(event = 'payment_succeeded') AS succeeded,\n    count() AS attempts\n  FROM events\n  WHERE event IN ('payment_succeeded', 'payment_failed')\n    AND timestamp >= now() - toIntervalWeek(27)\n    AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n  GROUP BY week\n) AS p ON p.week = w.week\nORDER BY week","postgres":"-- Payment success rate per week: successful payment attempts ÷ all attempts (succeeded + failed). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\npayments AS (\n  SELECT\n    date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n    count(*) FILTER (WHERE event_name = 'payment_succeeded') AS succeeded,\n    count(*) AS attempts\n  FROM events\n  WHERE event_name IN ('payment_succeeded', 'payment_failed')\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n  GROUP BY 1\n)\nSELECT\n  w.week,\n  coalesce(p.succeeded, 0) AS numerator,\n  coalesce(p.attempts, 0) AS denominator,\n  p.succeeded::numeric / nullif(p.attempts, 0) AS value\nFROM weeks AS w\nLEFT JOIN payments AS p ON p.week = w.week\nORDER BY w.week;","bigquery":"-- Payment success rate per week: successful payment attempts ÷ all attempts (succeeded + failed). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\npayments AS (\n  SELECT\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n    COUNTIF(event_name = 'payment_succeeded') AS succeeded,\n    COUNT(*) AS attempts\n  FROM events\n  WHERE event_name IN ('payment_succeeded', 'payment_failed')\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY week\n)\nSELECT\n  w.week,\n  COALESCE(p.succeeded, 0) AS numerator,\n  COALESCE(p.attempts, 0) AS denominator,\n  SAFE_DIVIDE(p.succeeded, p.attempts) AS value\nFROM weeks AS w\nLEFT JOIN payments AS p ON p.week = w.week\nORDER BY w.week;","snowflake":"-- Payment success rate per week: successful payment attempts ÷ all attempts (succeeded + failed). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\npayments AS (\n  SELECT\n    DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n    COUNT_IF(event_name = 'payment_succeeded') AS succeeded,\n    COUNT(*) AS attempts\n  FROM events\n  WHERE event_name IN ('payment_succeeded', 'payment_failed')\n    AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n  GROUP BY 1\n)\nSELECT\n  w.week,\n  COALESCE(p.succeeded, 0) AS numerator,\n  COALESCE(p.attempts, 0) AS denominator,\n  p.succeeded::float / NULLIF(p.attempts, 0) AS value\nFROM weeks AS w\nLEFT JOIN payments AS p ON p.week = w.week\nORDER BY w.week;"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"payment attempts a week","typical":0.92},"example":{"business":"store","level":0.93,"volume":14300,"trend":0},"drivers":[{"id":"card-testing","label":"Card testing and bots","dropped":{"check":"Is a card-testing attack sending bursts of failed attempts with stolen cards?","yes":"Failed attempts spike within hours from a few sessions or IPs, with small amounts and codes like incorrect_cvc, while orders hold."},"spiked":{"check":"Did a card-testing attack from last week stop, or did a new rule block bots before they reach the processor?","yes":"Failed attempts fall back while successful payments hold; the rise is a smaller denominator, not more customers paying."}},{"id":"processor","label":"Processor incidents","breakdown":"gateway","feed":"stripe","dropped":{"check":"Did one gateway or processor have an outage or a degraded period this week?","yes":"Failures concentrate on one gateway during the hours of an incident on its status page."},"spiked":{"check":"Did an incident from the week before clear?","yes":"The affected gateway returns to its usual rate and the others never moved."}},{"id":"method","label":"Payment methods","breakdown":"method","dropped":{"check":"Is one method failing, such as Apple Pay, PayPal, a buy-now-pay-later provider or 3-D Secure cards?","yes":"One method's success falls while cards and the other methods hold."},"spiked":{"check":"Did wallets, which approve more often than typed cards, gain share, or did a weak method get removed?","yes":"Each method's own rate holds and only the mix moved."}},{"id":"fraud-rules","label":"Fraud rules and 3-D Secure","breakdown":"decline_code","dropped":{"check":"Did a fraud rule, risk setting or 3-D Secure change start blocking good customers?","yes":"One decline code, such as fraudulent or authentication_required, rises from the day the rule changed."},"spiked":{"check":"Was a fraud rule loosened? Check disputes before celebrating.","yes":"Blocked attempts fall from the day of the change, and fraud disputes may rise a few weeks later."}},{"id":"country-mix","label":"Countries and card issuers","breakdown":"$geoip_country_code","dropped":{"check":"Did more attempts come from countries where cross-border cards decline more often, for example after a new campaign?","yes":"One country's share of attempts grows and its success rate sits well below the rest."},"spiked":{"check":"Did a low-approval country shrink, or did a local payment method launch there?","yes":"The country mix moved, or one country's rate rose from the day a method launched."}}],"diagnose_order":["card-testing","processor","method","fraud-rules","country-mix"],"related":["checkout-conversion","conversion-rate","orders","mobile-conversion-rate","net-revenue"],"prose":{"why_it_matters":"Every failed payment is a shopper who had already decided to buy and typed in a card. A fall is rarely about the shopper; it is a processor incident, a fraud rule or a bot testing stolen cards. At Northwind, with about 14,000 attempts a week, one point is 140 failed attempts a week, most of them from people who were already at checkout.","pitfalls":["Retries count as attempts, so a shopper who is declined twice and then pays is one success in three. Read checkout conversion beside it to see what shoppers experienced.","Card-testing bots can send thousands of failed attempts in an hour and pull a week down ten points with no real customer affected. Split by session or IP before reacting.","Record payment events from the processor's webhooks, not the browser. Browser events miss redirect methods such as PayPal and Klarna and duplicate on reloads.","Processors disagree on what a failure is; a 3-D Secure challenge the shopper abandons is a failure in some and nothing in others. Changing processors moves the rate with no change in approvals."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "product-view-rate": { yaml: "id: product-view-rate\nname: Product view rate\naliases:\n  - Product page view rate\n  - PDP view rate\n  - Product detail view rate\nfamily: conversion\ncatalog_id: product_view_rate\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of sessions that viewed at least one product page, the first step of the store funnel.\n  formula: Sessions with a product view ÷ sessions\n\nevents:\n  - name: $pageview\n    description: A page loaded in the browser. Sessions are the distinct session ids across page views.\n    also_called: [page_view, Page Viewed, page, page_viewed]\n    properties:\n      - name: $session_id\n        description: The browser session; a new one starts after 30 minutes without activity.\n  - name: product_viewed\n    description: A product detail page rendered with its product, once per view.\n    also_called: [view_item, Product Viewed, product_viewed]\n    properties:\n      - name: product_id\n        description: The product shown.\n      - name: price\n        description: The price shown, before discounts.\n\nnumerator:\n  label: Sessions that viewed a product\n  aggregate: unique_sessions\n  event: product_viewed\ndenominator:\n  label: Sessions\n  aggregate: unique_sessions\n  event: $pageview\n\nnoise:\n  type: binomial\n  min_denominator: 500\n  volume_unit: sessions a week\n  typical: 0.55\n  reference_volumes: [2000, 10000, 50000, 250000]\n\nexample:\n  business: store\n  level: 0.62\n  volume: 600000\n  trend: 0\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a theme, app or tag change stop product_viewed firing on some product templates?\n      yes: Page views on product URLs hold while product_viewed events fall, often on one template or device.\n    spiked:\n      check: Is product_viewed now firing on quick views, collection grids or twice per page?\n      yes: Product views per session jump, or the event appears on paths that are not product pages.\n  - id: bot-traffic\n    label: Bots and junk sessions\n    breakdown: $browser\n    dropped:\n      check: Did a wave of bot or junk sessions add visits that never reach a product?\n      yes: Sessions jump from one browser, country or referrer with one page per session and almost no product views.\n    spiked:\n      check: Did a bot source stop, shrinking the denominator rather than lifting real browsing?\n      yes: Sessions fall from one browser or country while sessions that viewed a product hold.\n  - id: traffic-mix\n    label: Landing channel\n    breakdown: utm_source\n    dropped:\n      check: Did a channel that rarely browses grow, such as a viral blog post, a giveaway or broad paid social?\n      yes: One source gains share of sessions and its product view rate sits far below the rest.\n    spiked:\n      check: Did campaigns start sending people straight to product pages, or did a low-intent source shrink?\n      yes: One source's share or view rate moves from the day a campaign or link changed.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the drop on one device type only, for example after a mobile menu or search change?\n      yes: Mobile falls several points while desktop is flat, starting on a release day.\n    spiked:\n      check: Is the rise on one device type only?\n      yes: One device jumps after a release; confirm product_viewed didn't start firing twice there first.\n  - id: navigation\n    label: Homepage and navigation\n    dropped:\n      check: Did a homepage, menu, search or collection change make products harder to reach?\n      yes: Sessions that land on the changed page view fewer products from the day it shipped, on every channel.\n    spiked:\n      check: Did a homepage, menu or collection change put products one click closer?\n      yes: Sessions that land on the changed page view more products from the day it shipped, on every channel.\n\ndiagnose_order: [tracking, bot-traffic, traffic-mix, device-split, navigation]\n\nrelated: [sessions, bounce-rate, add-to-cart-rate, conversion-rate, pages-per-session]\n\nprose:\n  why_it_matters: >-\n    Product view rate says whether visitors find something worth a closer look, before price,\n    stock or checkout can matter. On a store with 600,000 sessions a week, one point is 6,000\n    sessions that never see a product; at the 3.6% of product viewers who go on to order, that\n    is about 200 orders a week.\n  pitfalls:\n    - Counting product views instead of sessions with a product view lets a few heavy browsers lift the rate. This spec counts each session once.\n    - Decide whether quick-view pop-ups count as product views and keep that choice; switching it moves the rate several points with no change in shoppers.\n    - Bot and crawler sessions land in the denominator only, so a bot wave reads as a fall in browsing. Split sessions by browser and country before acting.\n    - Landing pages with their own buy button skip the product page, so the rate falls while sales hold. Fire product_viewed on those pages or read add-to-cart over all sessions instead.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"product-view-rate","name":"Product view rate","aliases":["Product page view rate","PDP view rate","Product detail view rate"],"family":"conversion","catalog_id":"product_view_rate","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of sessions that viewed at least one product page, the first step of the store funnel.","formula":"Sessions with a product view ÷ sessions"},"events":[{"name":"$pageview","description":"A page loaded in the browser. Sessions are the distinct session ids across page views.","also_called":["page_view","Page Viewed","page","page_viewed"],"properties":[{"name":"$session_id","description":"The browser session; a new one starts after 30 minutes without activity."}]},{"name":"product_viewed","description":"A product detail page rendered with its product, once per view.","also_called":["view_item","Product Viewed","product_viewed"],"properties":[{"name":"product_id","description":"The product shown."},{"name":"price","description":"The price shown, before discounts."}]}],"numerator":{"label":"Sessions that viewed a product","aggregate":"unique_sessions","event":"product_viewed"},"denominator":{"label":"Sessions","aggregate":"unique_sessions","event":"$pageview"},"noise":{"type":"binomial","min_denominator":500,"volume_unit":"sessions a week","typical":0.55,"reference_volumes":[2000,10000,50000,250000]},"example":{"business":"store","level":0.62,"volume":600000,"trend":0},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a theme, app or tag change stop product_viewed firing on some product templates?","yes":"Page views on product URLs hold while product_viewed events fall, often on one template or device."},"spiked":{"check":"Is product_viewed now firing on quick views, collection grids or twice per page?","yes":"Product views per session jump, or the event appears on paths that are not product pages."}},{"id":"bot-traffic","label":"Bots and junk sessions","breakdown":"$browser","dropped":{"check":"Did a wave of bot or junk sessions add visits that never reach a product?","yes":"Sessions jump from one browser, country or referrer with one page per session and almost no product views."},"spiked":{"check":"Did a bot source stop, shrinking the denominator rather than lifting real browsing?","yes":"Sessions fall from one browser or country while sessions that viewed a product hold."}},{"id":"traffic-mix","label":"Landing channel","breakdown":"utm_source","dropped":{"check":"Did a channel that rarely browses grow, such as a viral blog post, a giveaway or broad paid social?","yes":"One source gains share of sessions and its product view rate sits far below the rest."},"spiked":{"check":"Did campaigns start sending people straight to product pages, or did a low-intent source shrink?","yes":"One source's share or view rate moves from the day a campaign or link changed."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the drop on one device type only, for example after a mobile menu or search change?","yes":"Mobile falls several points while desktop is flat, starting on a release day."},"spiked":{"check":"Is the rise on one device type only?","yes":"One device jumps after a release; confirm product_viewed didn't start firing twice there first."}},{"id":"navigation","label":"Homepage and navigation","dropped":{"check":"Did a homepage, menu, search or collection change make products harder to reach?","yes":"Sessions that land on the changed page view fewer products from the day it shipped, on every channel."},"spiked":{"check":"Did a homepage, menu or collection change put products one click closer?","yes":"Sessions that land on the changed page view more products from the day it shipped, on every channel."}}],"diagnose_order":["tracking","bot-traffic","traffic-mix","device-split","navigation"],"related":["sessions","bounce-rate","add-to-cart-rate","conversion-rate","pages-per-session"],"prose":{"why_it_matters":"Product view rate says whether visitors find something worth a closer look, before price, stock or checkout can matter. On a store with 600,000 sessions a week, one point is 6,000 sessions that never see a product; at the 3.6% of product viewers who go on to order, that is about 200 orders a week.","pitfalls":["Counting product views instead of sessions with a product view lets a few heavy browsers lift the rate. This spec counts each session once.","Decide whether quick-view pop-ups count as product views and keep that choice; switching it moves the rate several points with no change in shoppers.","Bot and crawler sessions land in the denominator only, so a bot wave reads as a fall in browsing. Split sessions by browser and country before acting.","Landing pages with their own buy button skip the product page, so the rate falls while sales hold. Fire product_viewed on those pages or read add-to-cart over all sessions instead."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "promo-code-usage-rate": { yaml: "id: promo-code-usage-rate\nname: Promo code usage rate\naliases:\n  - Coupon usage rate\n  - Discount code usage rate\n  - Coupon redemption rate\n  - Promo code redemption rate\nfamily: conversion\nkind: rate\npolarity: down-is-good\n\ndefinition:\n  one_line: The share of this week's paid orders placed with a discount code.\n  formula: Paid orders with a discount code ÷ paid orders\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: coupon\n        description: The code redeemed on the order; absent when no code was used.\n      - name: discount\n        description: The total discount on the order, from codes and automatic offers.\n  - name: coupon_applied\n    description: A code entered at cart or checkout, valid or not.\n    also_called: [Coupon Entered, Coupon Applied, Coupon Denied]\n    properties:\n      - name: coupon\n        description: The code entered.\n      - name: valid\n        description: Whether the code was accepted.\n\nnumerator:\n  label: Orders with a code\n  aggregate: count\n  event: order_completed\n  where:\n    - property: coupon\n      op: is_set\ndenominator:\n  label: Paid orders\n  aggregate: count\n  event: order_completed\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: orders a week\n  typical: 0.25\n\nexample:\n  business: store\n  level: 0.24\n  volume: 13300\n  trend: 0.03\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a checkout migration or a new discount app stop sending the code on the order event?\n      yes: Discounts on orders hold while the coupon field goes blank from one day.\n    spiked:\n      check: Is the order event now sending an empty string or an automatic offer's name as the coupon?\n      yes: Orders with a coupon but no discount appear, or one code name shows up on most orders.\n  - id: campaigns\n    label: Sales and campaign codes\n    feed: shopping\n    dropped:\n      check: Did a sale end or a campaign code expire this week?\n      yes: One or two campaign codes that carried last week's orders fall away.\n    spiked:\n      check: Is a sale running on a code, or did an email or SMS send one this week?\n      yes: One or two campaign codes explain most of the rise, starting on the send or launch day.\n  - id: leaked-codes\n    label: Leaked codes\n    breakdown: coupon\n    dropped:\n      check: Did you disable a code that had leaked to coupon sites or browser extensions?\n      yes: That code's uses fall to zero and invalid attempts with it appear in coupon_applied.\n    spiked:\n      check: Did a code leak to a coupon site, a browser extension or a deal forum?\n      yes: One code's uses climb across channels it was never sent to, often on first orders.\n  - id: invalid-codes\n    label: Codes that fail\n    dropped:\n      check: Did codes start failing, from an expiry, a new minimum spend or a discount app error?\n      yes: coupon_applied with valid false rises, and checkout conversion may fall with it.\n    spiked:\n      check: Did the code field move up to the cart or become more visible, sending shoppers to look for codes?\n      yes: Uses of codes nobody sent this week rise from the day the field moved.\n  - id: partner-codes\n    label: Influencer and affiliate codes\n    breakdown: utm_source\n    dropped:\n      check: Did an influencer, affiliate or podcast campaign with its own code end?\n      yes: The partner's code and its traffic source fall away together.\n    spiked:\n      check: Did an influencer, affiliate or podcast campaign with its own code launch?\n      yes: The partner's code accounts for most of the rise, with orders from its source.\n  - id: new-customers\n    label: First orders and welcome codes\n    metric: new-customers\n    dropped:\n      check: Did fewer first-time customers arrive with a welcome code?\n      yes: Welcome code uses fall with new customers while repeat customers' code use holds.\n    spiked:\n      check: Did more first-time customers arrive with a welcome code, from a pop-up change or an ad push?\n      yes: Welcome code uses rise with new customers while repeat customers' code use holds.\n\ndiagnose_order: [tracking, campaigns, leaked-codes, invalid-codes, partner-codes, new-customers]\n\nrelated: [discount-rate, aov, checkout-conversion, new-customers, gross-margin]\n\nprose:\n  why_it_matters: >-\n    Every coded order is margin given away, and code usage creeps: a welcome code, an influencer\n    code and a leaked code each add a few points that nobody decided on. At Northwind, 24% of\n    13,300 weekly orders use a code; five more points is about 665 more discounted orders a\n    week.\n  pitfalls:\n    - Automatic discounts and free-shipping rules leave the coupon empty, so a store that moves from codes to automatic offers sees code usage fall while it discounts more. Read discount rate beside it.\n    - Send no coupon property when no code was used. An empty string counts as a code in most query engines, including this spec's test.\n    - Welcome codes tie code usage to the new-customer mix, so a week with more first orders shows more codes without any change in promotions.\n    - Browser coupon extensions try every code they know at checkout, so a code shared once can spread to a large share of orders within days. Watch the top code's share, not only the total.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"promo-code-usage-rate","name":"Promo code usage rate","aliases":["Coupon usage rate","Discount code usage rate","Coupon redemption rate","Promo code redemption rate"],"family":"conversion","kind":"rate","polarity":"down-is-good","definition":{"one_line":"The share of this week's paid orders placed with a discount code.","formula":"Paid orders with a discount code ÷ paid orders"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"coupon","description":"The code redeemed on the order; absent when no code was used."},{"name":"discount","description":"The total discount on the order, from codes and automatic offers."}]},{"name":"coupon_applied","description":"A code entered at cart or checkout, valid or not.","also_called":["Coupon Entered","Coupon Applied","Coupon Denied"],"properties":[{"name":"coupon","description":"The code entered."},{"name":"valid","description":"Whether the code was accepted."}]}],"numerator":{"label":"Orders with a code","aggregate":"count","event":"order_completed","where":[{"property":"coupon","op":"is_set"}]},"denominator":{"label":"Paid orders","aggregate":"count","event":"order_completed"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"orders a week","typical":0.25},"example":{"business":"store","level":0.24,"volume":13300,"trend":0.03,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a checkout migration or a new discount app stop sending the code on the order event?","yes":"Discounts on orders hold while the coupon field goes blank from one day."},"spiked":{"check":"Is the order event now sending an empty string or an automatic offer's name as the coupon?","yes":"Orders with a coupon but no discount appear, or one code name shows up on most orders."}},{"id":"campaigns","label":"Sales and campaign codes","feed":"shopping","dropped":{"check":"Did a sale end or a campaign code expire this week?","yes":"One or two campaign codes that carried last week's orders fall away."},"spiked":{"check":"Is a sale running on a code, or did an email or SMS send one this week?","yes":"One or two campaign codes explain most of the rise, starting on the send or launch day."}},{"id":"leaked-codes","label":"Leaked codes","breakdown":"coupon","dropped":{"check":"Did you disable a code that had leaked to coupon sites or browser extensions?","yes":"That code's uses fall to zero and invalid attempts with it appear in coupon_applied."},"spiked":{"check":"Did a code leak to a coupon site, a browser extension or a deal forum?","yes":"One code's uses climb across channels it was never sent to, often on first orders."}},{"id":"invalid-codes","label":"Codes that fail","dropped":{"check":"Did codes start failing, from an expiry, a new minimum spend or a discount app error?","yes":"coupon_applied with valid false rises, and checkout conversion may fall with it."},"spiked":{"check":"Did the code field move up to the cart or become more visible, sending shoppers to look for codes?","yes":"Uses of codes nobody sent this week rise from the day the field moved."}},{"id":"partner-codes","label":"Influencer and affiliate codes","breakdown":"utm_source","dropped":{"check":"Did an influencer, affiliate or podcast campaign with its own code end?","yes":"The partner's code and its traffic source fall away together."},"spiked":{"check":"Did an influencer, affiliate or podcast campaign with its own code launch?","yes":"The partner's code accounts for most of the rise, with orders from its source."}},{"id":"new-customers","label":"First orders and welcome codes","metric":"new-customers","dropped":{"check":"Did fewer first-time customers arrive with a welcome code?","yes":"Welcome code uses fall with new customers while repeat customers' code use holds."},"spiked":{"check":"Did more first-time customers arrive with a welcome code, from a pop-up change or an ad push?","yes":"Welcome code uses rise with new customers while repeat customers' code use holds."}}],"diagnose_order":["tracking","campaigns","leaked-codes","invalid-codes","partner-codes","new-customers"],"related":["discount-rate","aov","checkout-conversion","new-customers","gross-margin"],"prose":{"why_it_matters":"Every coded order is margin given away, and code usage creeps: a welcome code, an influencer code and a leaked code each add a few points that nobody decided on. At Northwind, 24% of 13,300 weekly orders use a code; five more points is about 665 more discounted orders a week.","pitfalls":["Automatic discounts and free-shipping rules leave the coupon empty, so a store that moves from codes to automatic offers sees code usage fall while it discounts more. Read discount rate beside it.","Send no coupon property when no code was used. An empty string counts as a code in most query engines, including this spec's test.","Welcome codes tie code usage to the new-customer mix, so a week with more first orders shows more codes without any change in promotions.","Browser coupon extensions try every code they know at checkout, so a code shared once can spread to a large share of orders within days. Watch the top code's share, not only the total."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "purchase-frequency": { yaml: "id: purchase-frequency\nname: Purchase frequency\naliases:\n  - Order frequency\n  - Orders per customer\n  - Average purchase frequency\nfamily: customers\nkind: ratio\npolarity: up-is-good\n\ndefinition:\n  one_line: How many orders the average customer placed in the last 52 weeks, counting customers with at least one order.\n  formula: Orders in the trailing 52 weeks ÷ distinct customers who ordered in them, at each week's end\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: customer_id\n        description: The store's customer id, shared by guest and logged-in orders with the same email.\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n\nnumerator:\n  label: Orders in 52 weeks\n  aggregate: count\n  event: order_completed\ndenominator:\n  label: Customers with an order in 52 weeks\n  aggregate: unique_users\n  event: order_completed\n\nqueries:\n  hogql: |-\n    -- Purchase frequency: distinct orders in the 52 weeks ending each week (Monday 00:00 UTC) ÷ customers who ordered in them, for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its person_id when that is missing.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(a.order_count, 0) AS numerator,\n      coalesce(a.customers, 0) AS denominator,\n      if(denominator = 0, NULL, numerator / denominator) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, sum(orders) AS order_count, count() AS customers\n      FROM (\n        SELECT s.week AS week, o.customer_id AS customer_id, uniqExact(o.order_id) AS orders\n        FROM (\n          SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n        ) AS s\n        CROSS JOIN (\n          SELECT\n            coalesce(properties.customer_id, toString(person_id)) AS customer_id,\n            properties.order_id AS order_id,\n            toMonday(toTimeZone(timestamp, 'UTC')) AS order_week\n          FROM events\n          WHERE event = 'order_completed'\n            AND timestamp >= now() - toIntervalWeek(78)\n            AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(77) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n        ) AS o\n        WHERE o.order_week BETWEEN s.week - toIntervalWeek(51) AND s.week\n          AND o.customer_id IS NOT NULL\n        GROUP BY week, customer_id\n      )\n      GROUP BY week\n    ) AS a ON a.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Purchase frequency: distinct orders in the 52 weeks ending each week (Monday 00:00 UTC) ÷ customers who ordered in them, for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its user_id when that is missing.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    orders AS (\n      SELECT\n        coalesce(properties->>'customer_id', user_id) AS customer_id,\n        properties->>'order_id' AS order_id,\n        date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week\n      FROM events\n      WHERE event_name = 'order_completed'\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '77 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n    ),\n    per_customer AS (\n      SELECT w.week, o.customer_id, count(DISTINCT o.order_id) AS orders\n      FROM weeks AS w\n      JOIN orders AS o ON o.week BETWEEN w.week - 357 AND w.week\n      WHERE o.customer_id IS NOT NULL\n      GROUP BY w.week, o.customer_id\n    ),\n    weekly AS (\n      SELECT week, sum(orders) AS order_count, count(*) AS customers\n      FROM per_customer\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      coalesce(a.order_count, 0) AS numerator,\n      coalesce(a.customers, 0) AS denominator,\n      a.order_count::numeric / nullif(a.customers, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS a ON a.week = w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Purchase frequency: distinct orders in the 52 weeks ending each week (Monday 00:00 UTC) ÷ customers who ordered in them, for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its user_id when that is missing.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    orders AS (\n      SELECT\n        COALESCE(JSON_VALUE(properties, '$.customer_id'), user_id) AS customer_id,\n        JSON_VALUE(properties, '$.order_id') AS order_id,\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week\n      FROM events\n      WHERE event_name = 'order_completed'\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 77 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    ),\n    per_customer AS (\n      SELECT w.week, o.customer_id, COUNT(DISTINCT o.order_id) AS orders\n      FROM weeks AS w\n      JOIN orders AS o ON o.week BETWEEN DATE_SUB(w.week, INTERVAL 51 WEEK) AND w.week\n      WHERE o.customer_id IS NOT NULL\n      GROUP BY w.week, o.customer_id\n    ),\n    weekly AS (\n      SELECT week, SUM(orders) AS order_count, COUNT(*) AS customers\n      FROM per_customer\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      COALESCE(a.order_count, 0) AS numerator,\n      COALESCE(a.customers, 0) AS denominator,\n      SAFE_DIVIDE(a.order_count, a.customers) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS a ON a.week = w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Purchase frequency: distinct orders in the 52 weeks ending each week (Monday 00:00 UTC) ÷ customers who ordered in them, for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its user_id when that is missing.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    orders AS (\n      SELECT\n        COALESCE(properties:\"customer_id\"::string, user_id) AS customer_id,\n        properties:\"order_id\"::string AS order_id,\n        DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week\n      FROM events\n      WHERE event_name = 'order_completed'\n        AND occurred_at >= DATEADD(week, -77, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n    ),\n    per_customer AS (\n      SELECT w.week, o.customer_id, COUNT(DISTINCT o.order_id) AS orders\n      FROM weeks AS w\n      JOIN orders AS o ON o.week BETWEEN DATEADD(week, -51, w.week) AND w.week\n      WHERE o.customer_id IS NOT NULL\n      GROUP BY w.week, o.customer_id\n    ),\n    weekly AS (\n      SELECT week, SUM(orders) AS order_count, COUNT(*) AS customers\n      FROM per_customer\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      COALESCE(a.order_count, 0) AS numerator,\n      COALESCE(a.customers, 0) AS denominator,\n      a.order_count::float / NULLIF(a.customers, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS a ON a.week = w.week\n    ORDER BY w.week;\n\nnoise:\n  type: process\n  min_denominator: 200\n  volume_unit: customers who ordered in the last 52 weeks\n  typical: 1.44\n\nexample:\n  business: store\n  level: 1.44\n  volume: 470000\n  trend: 0.02\n\ndrivers:\n  - id: order-splitting\n    label: How orders are recorded\n    dropped:\n      check: Did customer matching break, so one buyer's orders are spread across several ids?\n      yes: Customers in the window grow faster than orders, and most of the new ids have a single order.\n    spiked:\n      check: Did a checkout change start splitting one purchase into several orders, or did a duplicate order event appear?\n      yes: Orders rise faster than revenue and order value falls by about the same share.\n  - id: roll-off\n    label: The week leaving the window\n    dropped:\n      check: Is a week of heavy repeat buying from a year ago leaving the 52-week window?\n      yes: The week 52 weeks back had far more repeat orders than usual.\n    spiked:\n      check: Is a week of one-time sale buyers from a year ago leaving the window?\n      yes: The week 52 weeks back was a sale week with a flood of first orders that never returned.\n  - id: acquisition-mix\n    label: New customers entering\n    metric: new-customers\n    dropped:\n      check: Did many new customers join recently? They have had little time to reorder, so frequency falls as they arrive.\n      yes: New customers over the last 8 to 12 weeks run well above the same weeks last year.\n    spiked:\n      check: Did acquisition slow, leaving a base of longer-standing customers?\n      yes: New customers run below last year while orders from returning customers hold.\n  - id: second-orders\n    label: Second orders from recent cohorts\n    metric: second-order-rate\n    dropped:\n      check: Are recent cohorts reordering less within 90 days?\n      yes: Second order rate has fallen for the last few mature cohorts.\n    spiked:\n      check: Are recent cohorts reordering more within 90 days?\n      yes: Second order rate has risen for the last few mature cohorts.\n  - id: retention-marketing\n    label: Replenishment and retention\n    metric: email-click-rate\n    dropped:\n      check: Did a replenishment reminder, subscription option or loyalty offer stop?\n      yes: Orders from that flow or programme fell to near zero weeks ago.\n    spiked:\n      check: Did a subscribe-and-save option, loyalty programme or replenishment flow launch?\n      yes: Orders from the new programme account for most of the gain.\n\ndiagnose_order: [order-splitting, roll-off, acquisition-mix, second-orders, retention-marketing]\n\nrelated: [repeat-purchase-rate, customer-lifetime-value, aov, active-customers, second-order-rate]\n\nprose:\n  why_it_matters: >-\n    Purchase frequency is half of what a customer is worth: a year of revenue per customer is order\n    value times how often they order. Moving from 1.40 to 1.50 orders a year lifts what each customer\n    is worth by about 7% without spending a dollar more on acquisition. It changes slowly; a sudden weekly jump is usually a change in how orders are\n    recorded.\n  pitfalls:\n    - Splitting one purchase into several orders, for pre-orders or separate shipments, raises frequency without anyone buying more. Count orders the way the customer placed them.\n    - New customers have had less time to reorder, so a fast-growing store's frequency falls even while loyalty holds. Compare cohorts of the same age when it matters.\n    - Frequency over 90 days and over 365 days are different numbers. This spec uses 52 weeks and every comparison must too.\n    - A handful of wholesale or reseller accounts with dozens of orders each can lift the average. Exclude them or report them separately.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"purchase-frequency","name":"Purchase frequency","aliases":["Order frequency","Orders per customer","Average purchase frequency"],"family":"customers","kind":"ratio","polarity":"up-is-good","definition":{"one_line":"How many orders the average customer placed in the last 52 weeks, counting customers with at least one order.","formula":"Orders in the trailing 52 weeks ÷ distinct customers who ordered in them, at each week's end"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"customer_id","description":"The store's customer id, shared by guest and logged-in orders with the same email."},{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."}]}],"numerator":{"label":"Orders in 52 weeks","aggregate":"count","event":"order_completed"},"denominator":{"label":"Customers with an order in 52 weeks","aggregate":"unique_users","event":"order_completed"},"queries":{"hogql":"-- Purchase frequency: distinct orders in the 52 weeks ending each week (Monday 00:00 UTC) ÷ customers who ordered in them, for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its person_id when that is missing.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(a.order_count, 0) AS numerator,\n  coalesce(a.customers, 0) AS denominator,\n  if(denominator = 0, NULL, numerator / denominator) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, sum(orders) AS order_count, count() AS customers\n  FROM (\n    SELECT s.week AS week, o.customer_id AS customer_id, uniqExact(o.order_id) AS orders\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS s\n    CROSS JOIN (\n      SELECT\n        coalesce(properties.customer_id, toString(person_id)) AS customer_id,\n        properties.order_id AS order_id,\n        toMonday(toTimeZone(timestamp, 'UTC')) AS order_week\n      FROM events\n      WHERE event = 'order_completed'\n        AND timestamp >= now() - toIntervalWeek(78)\n        AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(77) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n    ) AS o\n    WHERE o.order_week BETWEEN s.week - toIntervalWeek(51) AND s.week\n      AND o.customer_id IS NOT NULL\n    GROUP BY week, customer_id\n  )\n  GROUP BY week\n) AS a ON a.week = w.week\nORDER BY week","postgres":"-- Purchase frequency: distinct orders in the 52 weeks ending each week (Monday 00:00 UTC) ÷ customers who ordered in them, for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its user_id when that is missing.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\norders AS (\n  SELECT\n    coalesce(properties->>'customer_id', user_id) AS customer_id,\n    properties->>'order_id' AS order_id,\n    date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week\n  FROM events\n  WHERE event_name = 'order_completed'\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '77 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n),\nper_customer AS (\n  SELECT w.week, o.customer_id, count(DISTINCT o.order_id) AS orders\n  FROM weeks AS w\n  JOIN orders AS o ON o.week BETWEEN w.week - 357 AND w.week\n  WHERE o.customer_id IS NOT NULL\n  GROUP BY w.week, o.customer_id\n),\nweekly AS (\n  SELECT week, sum(orders) AS order_count, count(*) AS customers\n  FROM per_customer\n  GROUP BY week\n)\nSELECT\n  w.week,\n  coalesce(a.order_count, 0) AS numerator,\n  coalesce(a.customers, 0) AS denominator,\n  a.order_count::numeric / nullif(a.customers, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS a ON a.week = w.week\nORDER BY w.week;","bigquery":"-- Purchase frequency: distinct orders in the 52 weeks ending each week (Monday 00:00 UTC) ÷ customers who ordered in them, for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its user_id when that is missing.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\norders AS (\n  SELECT\n    COALESCE(JSON_VALUE(properties, '$.customer_id'), user_id) AS customer_id,\n    JSON_VALUE(properties, '$.order_id') AS order_id,\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week\n  FROM events\n  WHERE event_name = 'order_completed'\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 77 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n),\nper_customer AS (\n  SELECT w.week, o.customer_id, COUNT(DISTINCT o.order_id) AS orders\n  FROM weeks AS w\n  JOIN orders AS o ON o.week BETWEEN DATE_SUB(w.week, INTERVAL 51 WEEK) AND w.week\n  WHERE o.customer_id IS NOT NULL\n  GROUP BY w.week, o.customer_id\n),\nweekly AS (\n  SELECT week, SUM(orders) AS order_count, COUNT(*) AS customers\n  FROM per_customer\n  GROUP BY week\n)\nSELECT\n  w.week,\n  COALESCE(a.order_count, 0) AS numerator,\n  COALESCE(a.customers, 0) AS denominator,\n  SAFE_DIVIDE(a.order_count, a.customers) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS a ON a.week = w.week\nORDER BY w.week;","snowflake":"-- Purchase frequency: distinct orders in the 52 weeks ending each week (Monday 00:00 UTC) ÷ customers who ordered in them, for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its user_id when that is missing.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\norders AS (\n  SELECT\n    COALESCE(properties:\"customer_id\"::string, user_id) AS customer_id,\n    properties:\"order_id\"::string AS order_id,\n    DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week\n  FROM events\n  WHERE event_name = 'order_completed'\n    AND occurred_at >= DATEADD(week, -77, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n),\nper_customer AS (\n  SELECT w.week, o.customer_id, COUNT(DISTINCT o.order_id) AS orders\n  FROM weeks AS w\n  JOIN orders AS o ON o.week BETWEEN DATEADD(week, -51, w.week) AND w.week\n  WHERE o.customer_id IS NOT NULL\n  GROUP BY w.week, o.customer_id\n),\nweekly AS (\n  SELECT week, SUM(orders) AS order_count, COUNT(*) AS customers\n  FROM per_customer\n  GROUP BY week\n)\nSELECT\n  w.week,\n  COALESCE(a.order_count, 0) AS numerator,\n  COALESCE(a.customers, 0) AS denominator,\n  a.order_count::float / NULLIF(a.customers, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS a ON a.week = w.week\nORDER BY w.week;"},"noise":{"type":"process","min_denominator":200,"volume_unit":"customers who ordered in the last 52 weeks","typical":1.44},"example":{"business":"store","level":1.44,"volume":470000,"trend":0.02},"drivers":[{"id":"order-splitting","label":"How orders are recorded","dropped":{"check":"Did customer matching break, so one buyer's orders are spread across several ids?","yes":"Customers in the window grow faster than orders, and most of the new ids have a single order."},"spiked":{"check":"Did a checkout change start splitting one purchase into several orders, or did a duplicate order event appear?","yes":"Orders rise faster than revenue and order value falls by about the same share."}},{"id":"roll-off","label":"The week leaving the window","dropped":{"check":"Is a week of heavy repeat buying from a year ago leaving the 52-week window?","yes":"The week 52 weeks back had far more repeat orders than usual."},"spiked":{"check":"Is a week of one-time sale buyers from a year ago leaving the window?","yes":"The week 52 weeks back was a sale week with a flood of first orders that never returned."}},{"id":"acquisition-mix","label":"New customers entering","metric":"new-customers","dropped":{"check":"Did many new customers join recently? They have had little time to reorder, so frequency falls as they arrive.","yes":"New customers over the last 8 to 12 weeks run well above the same weeks last year."},"spiked":{"check":"Did acquisition slow, leaving a base of longer-standing customers?","yes":"New customers run below last year while orders from returning customers hold."}},{"id":"second-orders","label":"Second orders from recent cohorts","metric":"second-order-rate","dropped":{"check":"Are recent cohorts reordering less within 90 days?","yes":"Second order rate has fallen for the last few mature cohorts."},"spiked":{"check":"Are recent cohorts reordering more within 90 days?","yes":"Second order rate has risen for the last few mature cohorts."}},{"id":"retention-marketing","label":"Replenishment and retention","metric":"email-click-rate","dropped":{"check":"Did a replenishment reminder, subscription option or loyalty offer stop?","yes":"Orders from that flow or programme fell to near zero weeks ago."},"spiked":{"check":"Did a subscribe-and-save option, loyalty programme or replenishment flow launch?","yes":"Orders from the new programme account for most of the gain."}}],"diagnose_order":["order-splitting","roll-off","acquisition-mix","second-orders","retention-marketing"],"related":["repeat-purchase-rate","customer-lifetime-value","aov","active-customers","second-order-rate"],"prose":{"why_it_matters":"Purchase frequency is half of what a customer is worth: a year of revenue per customer is order value times how often they order. Moving from 1.40 to 1.50 orders a year lifts what each customer is worth by about 7% without spending a dollar more on acquisition. It changes slowly; a sudden weekly jump is usually a change in how orders are recorded.","pitfalls":["Splitting one purchase into several orders, for pre-orders or separate shipments, raises frequency without anyone buying more. Count orders the way the customer placed them.","New customers have had less time to reorder, so a fast-growing store's frequency falls even while loyalty holds. Compare cohorts of the same age when it matters.","Frequency over 90 days and over 365 days are different numbers. This spec uses 52 weeks and every comparison must too.","A handful of wholesale or reseller accounts with dozens of orders each can lift the average. Exclude them or report them separately."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "quick-ratio": { yaml: "id: quick-ratio\nname: SaaS quick ratio\naliases:\n  - Quick ratio\n  - MRR quick ratio\n  - Growth quick ratio\nfamily: subscription\nkind: ratio\npolarity: up-is-good\n\ndefinition:\n  one_line: Dollars of MRR gained for every dollar lost over the four weeks ending this Sunday, new plus expansion over churned plus contraction.\n  formula: (New MRR + expansion MRR) ÷ (churned MRR + contraction MRR), summed over the four weeks ending Sunday 23:59 UTC\n\nevents:\n  - name: subscription_started\n    description: A subscription's first paid period began, sent by the billing system when the first payment succeeds; not the trial start.\n    also_called: [Subscription Started, subscription_activated, invoice.paid (first)]\n    properties:\n      - name: mrr\n        description: The new subscription's monthly amount.\n  - name: subscription_expanded\n    description: A paying subscription's monthly amount went up.\n    also_called: [Subscription Upgraded, plan_upgraded]\n    properties:\n      - name: mrr_delta\n        description: How much it rose, as a positive number.\n  - name: subscription_contracted\n    description: A paying subscription's monthly amount went down without ending.\n    also_called: [Subscription Downgraded, plan_downgraded]\n    properties:\n      - name: mrr_delta\n        description: How much it fell, as a positive number.\n  - name: subscription_canceled\n    description: A subscription stopped being billed.\n    also_called: [customer.subscription.deleted, Subscription Cancelled]\n    properties:\n      - name: mrr\n        description: The monthly amount it was paying before it ended.\n\nnumerator:\n  label: New MRR, before expansion is added\n  aggregate: sum\n  event: subscription_started\n  property: mrr\n\nqueries:\n  hogql: |-\n    -- SaaS quick ratio per week, over the four weeks ending that Sunday: (new + expansion MRR) ÷ (churned + contraction MRR). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(sum(f.gained), 0) AS numerator,\n      coalesce(sum(f.lost), 0) AS denominator,\n      if(denominator = 0, NULL, numerator / denominator) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT\n        active_week + toIntervalWeek(arrayJoin([0, 1, 2, 3])) AS week,\n        gained,\n        lost\n      FROM (\n        SELECT\n          toMonday(toTimeZone(timestamp, 'UTC')) AS active_week,\n          coalesce(sumIf(toFloat(properties.mrr), event = 'subscription_started'), 0)\n            + coalesce(sumIf(toFloat(properties.mrr_delta), event = 'subscription_expanded'), 0) AS gained,\n          coalesce(sumIf(toFloat(properties.mrr), event = 'subscription_canceled'), 0)\n            + coalesce(sumIf(toFloat(properties.mrr_delta), event = 'subscription_contracted'), 0) AS lost\n        FROM events\n        WHERE event IN ('subscription_started', 'subscription_expanded', 'subscription_contracted', 'subscription_canceled')\n          AND timestamp >= now() - toIntervalWeek(30)\n          AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(29) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n        GROUP BY active_week\n      )\n    ) AS f ON f.week = w.week\n    GROUP BY w.week\n    ORDER BY week\n  postgres: |-\n    -- SaaS quick ratio per week, over the four weeks ending that Sunday: (new + expansion MRR) ÷ (churned + contraction MRR). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    flows AS (\n      SELECT\n        date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n        coalesce(sum(CASE WHEN properties->>'mrr' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr')::numeric END) FILTER (WHERE event_name = 'subscription_started'), 0)\n          + coalesce(sum(CASE WHEN properties->>'mrr_delta' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr_delta')::numeric END) FILTER (WHERE event_name = 'subscription_expanded'), 0) AS gained,\n        coalesce(sum(CASE WHEN properties->>'mrr' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr')::numeric END) FILTER (WHERE event_name = 'subscription_canceled'), 0)\n          + coalesce(sum(CASE WHEN properties->>'mrr_delta' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr_delta')::numeric END) FILTER (WHERE event_name = 'subscription_contracted'), 0) AS lost\n      FROM events\n      WHERE event_name IN ('subscription_started', 'subscription_expanded', 'subscription_contracted', 'subscription_canceled')\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '29 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n      GROUP BY 1\n    ),\n    totals AS (\n      SELECT w.week, coalesce(sum(f.gained), 0) AS gained, coalesce(sum(f.lost), 0) AS lost\n      FROM weeks AS w\n      LEFT JOIN flows AS f ON f.week BETWEEN w.week - 21 AND w.week\n      GROUP BY w.week\n    )\n    SELECT week, gained AS numerator, lost AS denominator, gained / nullif(lost, 0) AS value\n    FROM totals\n    ORDER BY week;\n  bigquery: |-\n    -- SaaS quick ratio per week, over the four weeks ending that Sunday: (new + expansion MRR) ÷ (churned + contraction MRR). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    flows AS (\n      SELECT\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n        COALESCE(SUM(IF(event_name = 'subscription_started', SAFE_CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64), NULL)), 0)\n          + COALESCE(SUM(IF(event_name = 'subscription_expanded', SAFE_CAST(JSON_VALUE(properties, '$.mrr_delta') AS FLOAT64), NULL)), 0) AS gained,\n        COALESCE(SUM(IF(event_name = 'subscription_canceled', SAFE_CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64), NULL)), 0)\n          + COALESCE(SUM(IF(event_name = 'subscription_contracted', SAFE_CAST(JSON_VALUE(properties, '$.mrr_delta') AS FLOAT64), NULL)), 0) AS lost\n      FROM events\n      WHERE event_name IN ('subscription_started', 'subscription_expanded', 'subscription_contracted', 'subscription_canceled')\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 29 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY week\n    ),\n    totals AS (\n      SELECT w.week, COALESCE(SUM(f.gained), 0) AS gained, COALESCE(SUM(f.lost), 0) AS lost\n      FROM weeks AS w\n      LEFT JOIN flows AS f ON f.week BETWEEN DATE_SUB(w.week, INTERVAL 3 WEEK) AND w.week\n      GROUP BY w.week\n    )\n    SELECT week, gained AS numerator, lost AS denominator, SAFE_DIVIDE(gained, lost) AS value\n    FROM totals\n    ORDER BY week;\n  snowflake: |-\n    -- SaaS quick ratio per week, over the four weeks ending that Sunday: (new + expansion MRR) ÷ (churned + contraction MRR). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    flows AS (\n      SELECT\n        DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n        COALESCE(SUM(IFF(event_name = 'subscription_started', TRY_TO_DOUBLE(properties:\"mrr\"::string), NULL)), 0)\n          + COALESCE(SUM(IFF(event_name = 'subscription_expanded', TRY_TO_DOUBLE(properties:\"mrr_delta\"::string), NULL)), 0) AS gained,\n        COALESCE(SUM(IFF(event_name = 'subscription_canceled', TRY_TO_DOUBLE(properties:\"mrr\"::string), NULL)), 0)\n          + COALESCE(SUM(IFF(event_name = 'subscription_contracted', TRY_TO_DOUBLE(properties:\"mrr_delta\"::string), NULL)), 0) AS lost\n      FROM events\n      WHERE event_name IN ('subscription_started', 'subscription_expanded', 'subscription_contracted', 'subscription_canceled')\n        AND occurred_at >= DATEADD(week, -29, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n      GROUP BY 1\n    ),\n    totals AS (\n      SELECT w.week, COALESCE(SUM(f.gained), 0) AS gained, COALESCE(SUM(f.lost), 0) AS lost\n      FROM weeks AS w\n      LEFT JOIN flows AS f ON f.week BETWEEN DATEADD(week, -3, w.week) AND w.week\n      GROUP BY w.week\n    )\n    SELECT week, gained AS numerator, lost AS denominator, gained / NULLIF(lost, 0) AS value\n    FROM totals\n    ORDER BY week;\n\nnoise:\n  type: process\n  min_denominator: 20\n  volume_unit: MRR movements in four weeks\n  typical: 2\n\nexample:\n  business: saas\n  level: 2\n  volume: 180\n  trend: 0\n\ndrivers:\n  - id: window-effects\n    label: Large movements entering or leaving the window\n    dropped:\n      check: Did one large cancellation or downgrade land in the four-week window?\n      yes: One loss is a big share of four weeks of lost MRR; the ratio recovers when it leaves the window four weeks later.\n    spiked:\n      check: Did lost MRR fall unusually low, so a small denominator inflates the ratio?\n      yes: Churned plus contraction MRR is well below its usual four-week level while gains hold.\n  - id: calendar\n    label: Calendar\n    feed: holidays\n    dropped:\n      check: Does the window cover the holidays, when purchases pause but renewals and cancellations don't?\n      yes: Gains fall while losses hold, and the same weeks last year show the same dip.\n    spiked:\n      check: Does the window cover a quarter end, when sales-led deals close?\n      yes: New MRR is concentrated in the closing week, as in earlier quarters.\n  - id: churn\n    label: Churned MRR\n    metric: churned-mrr\n    dropped:\n      check: Did cancellations rise over the four weeks?\n      yes: Churned MRR is above its usual range while gains hold.\n    spiked:\n      check: Did cancellations fall, or failed payments recover?\n      yes: Churned MRR is below its usual range while gains hold.\n  - id: new\n    label: New MRR\n    metric: new-mrr\n    dropped:\n      check: Did fewer customers start paying over the four weeks?\n      yes: New MRR is below its usual range while losses hold.\n    spiked:\n      check: Did a launch, a sales push or one large deal add new MRR?\n      yes: New MRR is above its usual range; check whether one customer is most of it.\n  - id: expansion\n    label: Expansion MRR\n    metric: expansion-mrr\n    dropped:\n      check: Did upgrades and seat additions slow?\n      yes: Expansion MRR is below its usual range while new and lost MRR hold.\n    spiked:\n      check: Did a price change or a usage limit push customers to upgrade?\n      yes: Expansion MRR jumps from the week the change shipped.\n  - id: contraction\n    label: Contraction MRR\n    breakdown: plan\n    dropped:\n      check: Did more customers move to cheaper plans or fewer seats?\n      yes: Contraction rises, often in one plan or after customers' own budget cuts.\n    spiked:\n      check: Did downgrades slow?\n      yes: Contraction falls below its usual range while cancellations hold.\n\ndiagnose_order: [window-effects, calendar, churn, new, expansion, contraction]\n\nrelated: [net-new-mrr, new-mrr, expansion-mrr, churned-mrr, net-revenue-retention]\n\nprose:\n  why_it_matters: >-\n    The quick ratio, popularised by Mamoon Hamid at Social Capital, says how efficiently a\n    subscription business grows: how many dollars of MRR it adds for each one it loses. Below 1\n    it is shrinking; above 4 is the usual mark of efficient early-stage growth. Two companies\n    adding the same net new MRR can sit at 1.5 and at 6, and only one of them can keep it up.\n  pitfalls:\n    - One week has too few movements for a stable ratio, and one quiet week of churn sends it past 10. This spec sums four weeks.\n    - The ratio says nothing about scale. A 4 on $500 of losses and a 4 on $50,000 are different businesses, so read it next to net new MRR.\n    - Leaving contraction out of the denominator flatters companies whose customers downgrade rather than cancel.\n    - A mature company with low churn and slow sales can have the same ratio as a fast-growing one with high churn. Compare against your own history, not a universal threshold.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"quick-ratio","name":"SaaS quick ratio","aliases":["Quick ratio","MRR quick ratio","Growth quick ratio"],"family":"subscription","kind":"ratio","polarity":"up-is-good","definition":{"one_line":"Dollars of MRR gained for every dollar lost over the four weeks ending this Sunday, new plus expansion over churned plus contraction.","formula":"(New MRR + expansion MRR) ÷ (churned MRR + contraction MRR), summed over the four weeks ending Sunday 23:59 UTC"},"events":[{"name":"subscription_started","description":"A subscription's first paid period began, sent by the billing system when the first payment succeeds; not the trial start.","also_called":["Subscription Started","subscription_activated","invoice.paid (first)"],"properties":[{"name":"mrr","description":"The new subscription's monthly amount."}]},{"name":"subscription_expanded","description":"A paying subscription's monthly amount went up.","also_called":["Subscription Upgraded","plan_upgraded"],"properties":[{"name":"mrr_delta","description":"How much it rose, as a positive number."}]},{"name":"subscription_contracted","description":"A paying subscription's monthly amount went down without ending.","also_called":["Subscription Downgraded","plan_downgraded"],"properties":[{"name":"mrr_delta","description":"How much it fell, as a positive number."}]},{"name":"subscription_canceled","description":"A subscription stopped being billed.","also_called":["customer.subscription.deleted","Subscription Cancelled"],"properties":[{"name":"mrr","description":"The monthly amount it was paying before it ended."}]}],"numerator":{"label":"New MRR, before expansion is added","aggregate":"sum","event":"subscription_started","property":"mrr"},"queries":{"hogql":"-- SaaS quick ratio per week, over the four weeks ending that Sunday: (new + expansion MRR) ÷ (churned + contraction MRR). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(sum(f.gained), 0) AS numerator,\n  coalesce(sum(f.lost), 0) AS denominator,\n  if(denominator = 0, NULL, numerator / denominator) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT\n    active_week + toIntervalWeek(arrayJoin([0, 1, 2, 3])) AS week,\n    gained,\n    lost\n  FROM (\n    SELECT\n      toMonday(toTimeZone(timestamp, 'UTC')) AS active_week,\n      coalesce(sumIf(toFloat(properties.mrr), event = 'subscription_started'), 0)\n        + coalesce(sumIf(toFloat(properties.mrr_delta), event = 'subscription_expanded'), 0) AS gained,\n      coalesce(sumIf(toFloat(properties.mrr), event = 'subscription_canceled'), 0)\n        + coalesce(sumIf(toFloat(properties.mrr_delta), event = 'subscription_contracted'), 0) AS lost\n    FROM events\n    WHERE event IN ('subscription_started', 'subscription_expanded', 'subscription_contracted', 'subscription_canceled')\n      AND timestamp >= now() - toIntervalWeek(30)\n      AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(29) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n    GROUP BY active_week\n  )\n) AS f ON f.week = w.week\nGROUP BY w.week\nORDER BY week","postgres":"-- SaaS quick ratio per week, over the four weeks ending that Sunday: (new + expansion MRR) ÷ (churned + contraction MRR). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nflows AS (\n  SELECT\n    date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n    coalesce(sum(CASE WHEN properties->>'mrr' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr')::numeric END) FILTER (WHERE event_name = 'subscription_started'), 0)\n      + coalesce(sum(CASE WHEN properties->>'mrr_delta' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr_delta')::numeric END) FILTER (WHERE event_name = 'subscription_expanded'), 0) AS gained,\n    coalesce(sum(CASE WHEN properties->>'mrr' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr')::numeric END) FILTER (WHERE event_name = 'subscription_canceled'), 0)\n      + coalesce(sum(CASE WHEN properties->>'mrr_delta' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'mrr_delta')::numeric END) FILTER (WHERE event_name = 'subscription_contracted'), 0) AS lost\n  FROM events\n  WHERE event_name IN ('subscription_started', 'subscription_expanded', 'subscription_contracted', 'subscription_canceled')\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '29 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n  GROUP BY 1\n),\ntotals AS (\n  SELECT w.week, coalesce(sum(f.gained), 0) AS gained, coalesce(sum(f.lost), 0) AS lost\n  FROM weeks AS w\n  LEFT JOIN flows AS f ON f.week BETWEEN w.week - 21 AND w.week\n  GROUP BY w.week\n)\nSELECT week, gained AS numerator, lost AS denominator, gained / nullif(lost, 0) AS value\nFROM totals\nORDER BY week;","bigquery":"-- SaaS quick ratio per week, over the four weeks ending that Sunday: (new + expansion MRR) ÷ (churned + contraction MRR). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nflows AS (\n  SELECT\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n    COALESCE(SUM(IF(event_name = 'subscription_started', SAFE_CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64), NULL)), 0)\n      + COALESCE(SUM(IF(event_name = 'subscription_expanded', SAFE_CAST(JSON_VALUE(properties, '$.mrr_delta') AS FLOAT64), NULL)), 0) AS gained,\n    COALESCE(SUM(IF(event_name = 'subscription_canceled', SAFE_CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64), NULL)), 0)\n      + COALESCE(SUM(IF(event_name = 'subscription_contracted', SAFE_CAST(JSON_VALUE(properties, '$.mrr_delta') AS FLOAT64), NULL)), 0) AS lost\n  FROM events\n  WHERE event_name IN ('subscription_started', 'subscription_expanded', 'subscription_contracted', 'subscription_canceled')\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 29 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY week\n),\ntotals AS (\n  SELECT w.week, COALESCE(SUM(f.gained), 0) AS gained, COALESCE(SUM(f.lost), 0) AS lost\n  FROM weeks AS w\n  LEFT JOIN flows AS f ON f.week BETWEEN DATE_SUB(w.week, INTERVAL 3 WEEK) AND w.week\n  GROUP BY w.week\n)\nSELECT week, gained AS numerator, lost AS denominator, SAFE_DIVIDE(gained, lost) AS value\nFROM totals\nORDER BY week;","snowflake":"-- SaaS quick ratio per week, over the four weeks ending that Sunday: (new + expansion MRR) ÷ (churned + contraction MRR). Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nflows AS (\n  SELECT\n    DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n    COALESCE(SUM(IFF(event_name = 'subscription_started', TRY_TO_DOUBLE(properties:\"mrr\"::string), NULL)), 0)\n      + COALESCE(SUM(IFF(event_name = 'subscription_expanded', TRY_TO_DOUBLE(properties:\"mrr_delta\"::string), NULL)), 0) AS gained,\n    COALESCE(SUM(IFF(event_name = 'subscription_canceled', TRY_TO_DOUBLE(properties:\"mrr\"::string), NULL)), 0)\n      + COALESCE(SUM(IFF(event_name = 'subscription_contracted', TRY_TO_DOUBLE(properties:\"mrr_delta\"::string), NULL)), 0) AS lost\n  FROM events\n  WHERE event_name IN ('subscription_started', 'subscription_expanded', 'subscription_contracted', 'subscription_canceled')\n    AND occurred_at >= DATEADD(week, -29, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n  GROUP BY 1\n),\ntotals AS (\n  SELECT w.week, COALESCE(SUM(f.gained), 0) AS gained, COALESCE(SUM(f.lost), 0) AS lost\n  FROM weeks AS w\n  LEFT JOIN flows AS f ON f.week BETWEEN DATEADD(week, -3, w.week) AND w.week\n  GROUP BY w.week\n)\nSELECT week, gained AS numerator, lost AS denominator, gained / NULLIF(lost, 0) AS value\nFROM totals\nORDER BY week;"},"noise":{"type":"process","min_denominator":20,"volume_unit":"MRR movements in four weeks","typical":2},"example":{"business":"saas","level":2,"volume":180,"trend":0},"drivers":[{"id":"window-effects","label":"Large movements entering or leaving the window","dropped":{"check":"Did one large cancellation or downgrade land in the four-week window?","yes":"One loss is a big share of four weeks of lost MRR; the ratio recovers when it leaves the window four weeks later."},"spiked":{"check":"Did lost MRR fall unusually low, so a small denominator inflates the ratio?","yes":"Churned plus contraction MRR is well below its usual four-week level while gains hold."}},{"id":"calendar","label":"Calendar","feed":"holidays","dropped":{"check":"Does the window cover the holidays, when purchases pause but renewals and cancellations don't?","yes":"Gains fall while losses hold, and the same weeks last year show the same dip."},"spiked":{"check":"Does the window cover a quarter end, when sales-led deals close?","yes":"New MRR is concentrated in the closing week, as in earlier quarters."}},{"id":"churn","label":"Churned MRR","metric":"churned-mrr","dropped":{"check":"Did cancellations rise over the four weeks?","yes":"Churned MRR is above its usual range while gains hold."},"spiked":{"check":"Did cancellations fall, or failed payments recover?","yes":"Churned MRR is below its usual range while gains hold."}},{"id":"new","label":"New MRR","metric":"new-mrr","dropped":{"check":"Did fewer customers start paying over the four weeks?","yes":"New MRR is below its usual range while losses hold."},"spiked":{"check":"Did a launch, a sales push or one large deal add new MRR?","yes":"New MRR is above its usual range; check whether one customer is most of it."}},{"id":"expansion","label":"Expansion MRR","metric":"expansion-mrr","dropped":{"check":"Did upgrades and seat additions slow?","yes":"Expansion MRR is below its usual range while new and lost MRR hold."},"spiked":{"check":"Did a price change or a usage limit push customers to upgrade?","yes":"Expansion MRR jumps from the week the change shipped."}},{"id":"contraction","label":"Contraction MRR","breakdown":"plan","dropped":{"check":"Did more customers move to cheaper plans or fewer seats?","yes":"Contraction rises, often in one plan or after customers' own budget cuts."},"spiked":{"check":"Did downgrades slow?","yes":"Contraction falls below its usual range while cancellations hold."}}],"diagnose_order":["window-effects","calendar","churn","new","expansion","contraction"],"related":["net-new-mrr","new-mrr","expansion-mrr","churned-mrr","net-revenue-retention"],"prose":{"why_it_matters":"The quick ratio, popularised by Mamoon Hamid at Social Capital, says how efficiently a subscription business grows: how many dollars of MRR it adds for each one it loses. Below 1 it is shrinking; above 4 is the usual mark of efficient early-stage growth. Two companies adding the same net new MRR can sit at 1.5 and at 6, and only one of them can keep it up.","pitfalls":["One week has too few movements for a stable ratio, and one quiet week of churn sends it past 10. This spec sums four weeks.","The ratio says nothing about scale. A 4 on $500 of losses and a 4 on $50,000 are different businesses, so read it next to net new MRR.","Leaving contraction out of the denominator flatters companies whose customers downgrade rather than cancel.","A mature company with low churn and slow sales can have the same ratio as a fast-growing one with high churn. Compare against your own history, not a universal threshold."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "referral-sessions": { yaml: "id: referral-sessions\nname: Referral sessions\naliases:\n  - Referral traffic\n  - Referral visits\n  - Referring site traffic\nfamily: traffic\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: Visits that arrived through a link on another website that is not a search engine, a social network or an ad.\n  formula: Sessions whose first page view came from another site (not search, social, a payment page or this site) with no campaign tag, or tagged utm_medium=referral\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change, captured in the browser.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: $session_id\n        description: Set by the analytics SDK; the session's first page view decides its channel.\n      - name: $referring_domain\n        description: The domain the visitor came from, or $direct when there was none.\n      - name: $host\n        description: This site's own domain, so internal links and returns from checkout don't count as referrals.\n      - name: utm_medium\n        description: The campaign medium from the landing URL. When set, it decides the channel.\n\nnumerator:\n  label: Referral sessions\n  aggregate: unique_sessions\n  event: $pageview\n  where:\n    - property: utm_medium\n      op: is_not_set\n    - property: $referring_domain\n      op: not_in\n      value: [$direct, www.google.com, www.bing.com, duckduckgo.com, www.facebook.com, l.facebook.com, t.co, www.instagram.com]\n\nqueries:\n  hogql: |-\n    -- Referral sessions per week: sessions whose first page view came from another site that is not a search engine, social network, payment page or this site, and carried no campaign tag (or is tagged utm_medium=referral). Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT w.week AS week, coalesce(s.sessions, 0) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, count() AS sessions\n      FROM (\n        SELECT\n          $session_id AS session_id,\n          toMonday(toTimeZone(min(timestamp), 'UTC')) AS week,\n          argMin(lower(coalesce(properties.utm_medium, '')), timestamp) AS medium,\n          argMin(lower(coalesce(properties.$referring_domain, '')), timestamp) AS referrer,\n          argMin(lower(coalesce(properties.$host, '')), timestamp) AS host,\n          argMin(coalesce(properties.gclid, properties.gbraid, properties.wbraid, properties.msclkid, '') <> '', timestamp) AS ad_click\n        FROM events\n        WHERE event = '$pageview'\n          AND $session_id != ''\n          AND timestamp >= now() - toIntervalWeek(27)\n          AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n        GROUP BY session_id\n      )\n      WHERE NOT (match(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n        AND (\n          medium = 'referral'\n          OR (\n            medium = ''\n            AND referrer NOT IN ('', '$direct')\n            AND replaceRegexpOne(referrer, '^www[.]', '') <> replaceRegexpOne(host, '^www[.]', '')\n            AND NOT match(referrer, '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')\n            AND NOT match(referrer, '^(www[.]|m[.]|l[.]|lm[.]|out[.])?(facebook|instagram|linkedin|pinterest|reddit|tiktok|youtube|twitter)[.][a-z.]+$|^(x[.]com|t[.]co|lnkd[.]in|threads[.]net|bsky[.]app)$')\n            AND NOT match(referrer, '^(.*[.])?(paypal|stripe|klarna|afterpay|affirm)[.]com$|^shop[.]app$')\n          )\n        )\n      GROUP BY week\n    ) AS s ON s.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Referral sessions per week: sessions whose first page view came from another site that is not a search engine, social network, payment page or this site, and carried no campaign tag (or is tagged utm_medium=referral). Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    entries AS (\n      SELECT DISTINCT ON (session_id)\n        session_id,\n        date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n        lower(coalesce(properties->>'utm_medium', '')) AS medium,\n        lower(coalesce(properties->>'$referring_domain', '')) AS referrer,\n        lower(coalesce(properties->>'$host', '')) AS host,\n        coalesce(properties->>'gclid', properties->>'gbraid', properties->>'wbraid', properties->>'msclkid', '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id <> ''\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n      ORDER BY session_id, occurred_at\n    ),\n    weekly AS (\n      SELECT week, count(*) AS sessions\n      FROM entries\n      WHERE NOT (medium ~ '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$' OR ad_click)\n        AND (\n          medium = 'referral'\n          OR (\n            medium = ''\n            AND referrer NOT IN ('', '$direct')\n            AND regexp_replace(referrer, '^www[.]', '') <> regexp_replace(host, '^www[.]', '')\n            AND NOT referrer ~ '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$'\n            AND NOT referrer ~ '^(www[.]|m[.]|l[.]|lm[.]|out[.])?(facebook|instagram|linkedin|pinterest|reddit|tiktok|youtube|twitter)[.][a-z.]+$|^(x[.]com|t[.]co|lnkd[.]in|threads[.]net|bsky[.]app)$'\n            AND NOT referrer ~ '^(.*[.])?(paypal|stripe|klarna|afterpay|affirm)[.]com$|^shop[.]app$'\n          )\n        )\n      GROUP BY week\n    )\n    SELECT w.week, coalesce(s.sessions, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS s ON s.week = w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Referral sessions per week: sessions whose first page view came from another site that is not a search engine, social network, payment page or this site, and carried no campaign tag (or is tagged utm_medium=referral). Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    entries AS (\n      SELECT\n        session_id,\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n        LOWER(COALESCE(JSON_VALUE(properties, '$.utm_medium'), '')) AS medium,\n        LOWER(COALESCE(JSON_VALUE(properties, '$.\"$referring_domain\"'), '')) AS referrer,\n        LOWER(COALESCE(JSON_VALUE(properties, '$.\"$host\"'), '')) AS host,\n        COALESCE(JSON_VALUE(properties, '$.gclid'), JSON_VALUE(properties, '$.gbraid'), JSON_VALUE(properties, '$.wbraid'), JSON_VALUE(properties, '$.msclkid'), '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id <> ''\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n    ),\n    weekly AS (\n      SELECT week, COUNT(*) AS sessions\n      FROM entries\n      WHERE NOT (REGEXP_CONTAINS(medium, r'^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n        AND (\n          medium = 'referral'\n          OR (\n            medium = ''\n            AND referrer NOT IN ('', '$direct')\n            AND REGEXP_REPLACE(referrer, r'^www[.]', '') <> REGEXP_REPLACE(host, r'^www[.]', '')\n            AND NOT REGEXP_CONTAINS(referrer, r'^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')\n            AND NOT REGEXP_CONTAINS(referrer, r'^(www[.]|m[.]|l[.]|lm[.]|out[.])?(facebook|instagram|linkedin|pinterest|reddit|tiktok|youtube|twitter)[.][a-z.]+$|^(x[.]com|t[.]co|lnkd[.]in|threads[.]net|bsky[.]app)$')\n            AND NOT REGEXP_CONTAINS(referrer, r'^(.*[.])?(paypal|stripe|klarna|afterpay|affirm)[.]com$|^shop[.]app$')\n          )\n        )\n      GROUP BY week\n    )\n    SELECT w.week, COALESCE(s.sessions, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS s ON s.week = w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Referral sessions per week: sessions whose first page view came from another site that is not a search engine, social network, payment page or this site, and carried no campaign tag (or is tagged utm_medium=referral). Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    entries AS (\n      SELECT\n        session_id,\n        DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n        LOWER(COALESCE(properties:\"utm_medium\"::string, '')) AS medium,\n        LOWER(COALESCE(properties:\"$referring_domain\"::string, '')) AS referrer,\n        LOWER(COALESCE(properties:\"$host\"::string, '')) AS host,\n        COALESCE(properties:\"gclid\"::string, properties:\"gbraid\"::string, properties:\"wbraid\"::string, properties:\"msclkid\"::string, '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id <> ''\n        AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n    ),\n    weekly AS (\n      SELECT week, COUNT(*) AS sessions\n      FROM entries\n      WHERE NOT (REGEXP_LIKE(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n        AND (\n          medium = 'referral'\n          OR (\n            medium = ''\n            AND referrer NOT IN ('', '$direct')\n            AND REGEXP_REPLACE(referrer, '^www[.]', '') <> REGEXP_REPLACE(host, '^www[.]', '')\n            AND NOT REGEXP_LIKE(referrer, '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')\n            AND NOT REGEXP_LIKE(referrer, '^(www[.]|m[.]|l[.]|lm[.]|out[.])?(facebook|instagram|linkedin|pinterest|reddit|tiktok|youtube|twitter)[.][a-z.]+$|^(x[.]com|t[.]co|lnkd[.]in|threads[.]net|bsky[.]app)$')\n            AND NOT REGEXP_LIKE(referrer, '^(.*[.])?(paypal|stripe|klarna|afterpay|affirm)[.]com$|^shop[.]app$')\n          )\n        )\n      GROUP BY week\n    )\n    SELECT w.week, COALESCE(s.sessions, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS s ON s.week = w.week\n    ORDER BY w.week;\n\nnoise:\n  type: poisson\n  min_denominator: 50\n  volume_unit: referral sessions a week\n  typical: 2500\n  reference_volumes: [200, 1000, 5000, 25000]\n\nexample:\n  business: store\n  level: 21000\n  volume: 21000\n  trend: 0.05\n\ndrivers:\n  - id: self-referrals\n    label: Self-referrals and classification\n    breakdown: $referring_domain\n    dropped:\n      check: Did a referrer change, a new domain or stricter referrer policy turn referrals into direct visits?\n      yes: Direct sessions rise by about as much as referrals fall, from the day of the change.\n    spiked:\n      check: Are your own subdomains, a payment page or a login provider showing up as referrers?\n      yes: The top new referrer is a checkout, payment, help-centre or sign-in domain you own or use.\n  - id: referral-spam\n    label: Bots and referral spam\n    breakdown: $geoip_country_code\n    dropped:\n      check: Did a spam referrer that used to send junk visits stop?\n      yes: One unfamiliar domain that bounced every time has disappeared.\n    spiked:\n      check: Is an unknown domain sending visits that bounce at once and never buy?\n      yes: One unfamiliar referrer explains the rise, with near-total bounce and no orders.\n  - id: top-referrer\n    label: Press, creators and partners\n    breakdown: $referring_domain\n    dropped:\n      check: Did a link that sent steady traffic come down, or did last week's press mention fade?\n      yes: One referring domain that sent many visits last week sends few this week.\n    spiked:\n      check: Did an article, a gift guide, a creator or a partner link to the store?\n      yes: One referring domain explains most of the rise; expect it to fade within one or two weeks.\n  - id: ai-assistants\n    label: AI assistants\n    dropped:\n      check: Did visits from chatgpt.com, perplexity.ai, gemini.google.com or copilot.microsoft.com fall?\n      yes: The AI assistant referrers send fewer visits, often after a model or citation change on their side.\n    spiked:\n      check: Are AI assistants citing the store more often?\n      yes: chatgpt.com, perplexity.ai and similar referrers grow steadily, landing on product and guide pages.\n  - id: affiliates\n    label: Affiliate and coupon sites\n    dropped:\n      check: Did an affiliate network, coupon site or marketplace listing stop linking?\n      yes: Referrals from coupon or affiliate domains fall and affiliate orders fall with them.\n    spiked:\n      check: Did a coupon or deal site start listing the store, possibly with a leaked code?\n      yes: A coupon domain grows and promo-code use rises with it.\n\ndiagnose_order: [self-referrals, referral-spam, top-referrer, ai-assistants, affiliates]\n\nrelated: [sessions, organic-sessions, paid-sessions, new-visitor-share, promo-code-usage-rate]\n\nprose:\n  why_it_matters: >-\n    Referrals are earned traffic: press, gift guides, creators, partners and, more and more, AI\n    assistants that cite the store. They are spiky by nature, so a single article can double a\n    week and be gone the next. On a store with 21,000 referral sessions a week, the question is\n    always which one domain moved, not whether referrals did.\n  pitfalls:\n    - Payment pages, sign-in providers and your own subdomains show up as referrers when a visit restarts after them. This spec drops this site's domain and common payment pages; add others you see.\n    - Many apps and sites strip the referrer. Links from email clients, messaging apps and some social apps arrive as direct visits, not referrals.\n    - Referral spam sends fake visits with a made-up referrer. It never orders, so check orders from a new referrer before thanking anyone.\n    - Social networks and search engines are excluded here and counted in their own channels. Tools group the long tail differently, so referral totals rarely match GA4.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"referral-sessions","name":"Referral sessions","aliases":["Referral traffic","Referral visits","Referring site traffic"],"family":"traffic","kind":"count","polarity":"up-is-good","definition":{"one_line":"Visits that arrived through a link on another website that is not a search engine, a social network or an ad.","formula":"Sessions whose first page view came from another site (not search, social, a payment page or this site) with no campaign tag, or tagged utm_medium=referral"},"events":[{"name":"$pageview","description":"One page load or client-side route change, captured in the browser.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"$session_id","description":"Set by the analytics SDK; the session's first page view decides its channel."},{"name":"$referring_domain","description":"The domain the visitor came from, or $direct when there was none."},{"name":"$host","description":"This site's own domain, so internal links and returns from checkout don't count as referrals."},{"name":"utm_medium","description":"The campaign medium from the landing URL. When set, it decides the channel."}]}],"numerator":{"label":"Referral sessions","aggregate":"unique_sessions","event":"$pageview","where":[{"property":"utm_medium","op":"is_not_set"},{"property":"$referring_domain","op":"not_in","value":["$direct","www.google.com","www.bing.com","duckduckgo.com","www.facebook.com","l.facebook.com","t.co","www.instagram.com"]}]},"queries":{"hogql":"-- Referral sessions per week: sessions whose first page view came from another site that is not a search engine, social network, payment page or this site, and carried no campaign tag (or is tagged utm_medium=referral). Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT w.week AS week, coalesce(s.sessions, 0) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, count() AS sessions\n  FROM (\n    SELECT\n      $session_id AS session_id,\n      toMonday(toTimeZone(min(timestamp), 'UTC')) AS week,\n      argMin(lower(coalesce(properties.utm_medium, '')), timestamp) AS medium,\n      argMin(lower(coalesce(properties.$referring_domain, '')), timestamp) AS referrer,\n      argMin(lower(coalesce(properties.$host, '')), timestamp) AS host,\n      argMin(coalesce(properties.gclid, properties.gbraid, properties.wbraid, properties.msclkid, '') <> '', timestamp) AS ad_click\n    FROM events\n    WHERE event = '$pageview'\n      AND $session_id != ''\n      AND timestamp >= now() - toIntervalWeek(27)\n      AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n    GROUP BY session_id\n  )\n  WHERE NOT (match(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n    AND (\n      medium = 'referral'\n      OR (\n        medium = ''\n        AND referrer NOT IN ('', '$direct')\n        AND replaceRegexpOne(referrer, '^www[.]', '') <> replaceRegexpOne(host, '^www[.]', '')\n        AND NOT match(referrer, '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')\n        AND NOT match(referrer, '^(www[.]|m[.]|l[.]|lm[.]|out[.])?(facebook|instagram|linkedin|pinterest|reddit|tiktok|youtube|twitter)[.][a-z.]+$|^(x[.]com|t[.]co|lnkd[.]in|threads[.]net|bsky[.]app)$')\n        AND NOT match(referrer, '^(.*[.])?(paypal|stripe|klarna|afterpay|affirm)[.]com$|^shop[.]app$')\n      )\n    )\n  GROUP BY week\n) AS s ON s.week = w.week\nORDER BY week","postgres":"-- Referral sessions per week: sessions whose first page view came from another site that is not a search engine, social network, payment page or this site, and carried no campaign tag (or is tagged utm_medium=referral). Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nentries AS (\n  SELECT DISTINCT ON (session_id)\n    session_id,\n    date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week,\n    lower(coalesce(properties->>'utm_medium', '')) AS medium,\n    lower(coalesce(properties->>'$referring_domain', '')) AS referrer,\n    lower(coalesce(properties->>'$host', '')) AS host,\n    coalesce(properties->>'gclid', properties->>'gbraid', properties->>'wbraid', properties->>'msclkid', '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id <> ''\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n  ORDER BY session_id, occurred_at\n),\nweekly AS (\n  SELECT week, count(*) AS sessions\n  FROM entries\n  WHERE NOT (medium ~ '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$' OR ad_click)\n    AND (\n      medium = 'referral'\n      OR (\n        medium = ''\n        AND referrer NOT IN ('', '$direct')\n        AND regexp_replace(referrer, '^www[.]', '') <> regexp_replace(host, '^www[.]', '')\n        AND NOT referrer ~ '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$'\n        AND NOT referrer ~ '^(www[.]|m[.]|l[.]|lm[.]|out[.])?(facebook|instagram|linkedin|pinterest|reddit|tiktok|youtube|twitter)[.][a-z.]+$|^(x[.]com|t[.]co|lnkd[.]in|threads[.]net|bsky[.]app)$'\n        AND NOT referrer ~ '^(.*[.])?(paypal|stripe|klarna|afterpay|affirm)[.]com$|^shop[.]app$'\n      )\n    )\n  GROUP BY week\n)\nSELECT w.week, coalesce(s.sessions, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS s ON s.week = w.week\nORDER BY w.week;","bigquery":"-- Referral sessions per week: sessions whose first page view came from another site that is not a search engine, social network, payment page or this site, and carried no campaign tag (or is tagged utm_medium=referral). Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nentries AS (\n  SELECT\n    session_id,\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n    LOWER(COALESCE(JSON_VALUE(properties, '$.utm_medium'), '')) AS medium,\n    LOWER(COALESCE(JSON_VALUE(properties, '$.\"$referring_domain\"'), '')) AS referrer,\n    LOWER(COALESCE(JSON_VALUE(properties, '$.\"$host\"'), '')) AS host,\n    COALESCE(JSON_VALUE(properties, '$.gclid'), JSON_VALUE(properties, '$.gbraid'), JSON_VALUE(properties, '$.wbraid'), JSON_VALUE(properties, '$.msclkid'), '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id <> ''\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n),\nweekly AS (\n  SELECT week, COUNT(*) AS sessions\n  FROM entries\n  WHERE NOT (REGEXP_CONTAINS(medium, r'^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n    AND (\n      medium = 'referral'\n      OR (\n        medium = ''\n        AND referrer NOT IN ('', '$direct')\n        AND REGEXP_REPLACE(referrer, r'^www[.]', '') <> REGEXP_REPLACE(host, r'^www[.]', '')\n        AND NOT REGEXP_CONTAINS(referrer, r'^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')\n        AND NOT REGEXP_CONTAINS(referrer, r'^(www[.]|m[.]|l[.]|lm[.]|out[.])?(facebook|instagram|linkedin|pinterest|reddit|tiktok|youtube|twitter)[.][a-z.]+$|^(x[.]com|t[.]co|lnkd[.]in|threads[.]net|bsky[.]app)$')\n        AND NOT REGEXP_CONTAINS(referrer, r'^(.*[.])?(paypal|stripe|klarna|afterpay|affirm)[.]com$|^shop[.]app$')\n      )\n    )\n  GROUP BY week\n)\nSELECT w.week, COALESCE(s.sessions, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS s ON s.week = w.week\nORDER BY w.week;","snowflake":"-- Referral sessions per week: sessions whose first page view came from another site that is not a search engine, social network, payment page or this site, and carried no campaign tag (or is tagged utm_medium=referral). Each session counts in the week of its first page view. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nentries AS (\n  SELECT\n    session_id,\n    DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week,\n    LOWER(COALESCE(properties:\"utm_medium\"::string, '')) AS medium,\n    LOWER(COALESCE(properties:\"$referring_domain\"::string, '')) AS referrer,\n    LOWER(COALESCE(properties:\"$host\"::string, '')) AS host,\n    COALESCE(properties:\"gclid\"::string, properties:\"gbraid\"::string, properties:\"wbraid\"::string, properties:\"msclkid\"::string, '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id <> ''\n    AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n),\nweekly AS (\n  SELECT week, COUNT(*) AS sessions\n  FROM entries\n  WHERE NOT (REGEXP_LIKE(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n    AND (\n      medium = 'referral'\n      OR (\n        medium = ''\n        AND referrer NOT IN ('', '$direct')\n        AND REGEXP_REPLACE(referrer, '^www[.]', '') <> REGEXP_REPLACE(host, '^www[.]', '')\n        AND NOT REGEXP_LIKE(referrer, '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')\n        AND NOT REGEXP_LIKE(referrer, '^(www[.]|m[.]|l[.]|lm[.]|out[.])?(facebook|instagram|linkedin|pinterest|reddit|tiktok|youtube|twitter)[.][a-z.]+$|^(x[.]com|t[.]co|lnkd[.]in|threads[.]net|bsky[.]app)$')\n        AND NOT REGEXP_LIKE(referrer, '^(.*[.])?(paypal|stripe|klarna|afterpay|affirm)[.]com$|^shop[.]app$')\n      )\n    )\n  GROUP BY week\n)\nSELECT w.week, COALESCE(s.sessions, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS s ON s.week = w.week\nORDER BY w.week;"},"noise":{"type":"poisson","min_denominator":50,"volume_unit":"referral sessions a week","typical":2500,"reference_volumes":[200,1000,5000,25000]},"example":{"business":"store","level":21000,"volume":21000,"trend":0.05},"drivers":[{"id":"self-referrals","label":"Self-referrals and classification","breakdown":"$referring_domain","dropped":{"check":"Did a referrer change, a new domain or stricter referrer policy turn referrals into direct visits?","yes":"Direct sessions rise by about as much as referrals fall, from the day of the change."},"spiked":{"check":"Are your own subdomains, a payment page or a login provider showing up as referrers?","yes":"The top new referrer is a checkout, payment, help-centre or sign-in domain you own or use."}},{"id":"referral-spam","label":"Bots and referral spam","breakdown":"$geoip_country_code","dropped":{"check":"Did a spam referrer that used to send junk visits stop?","yes":"One unfamiliar domain that bounced every time has disappeared."},"spiked":{"check":"Is an unknown domain sending visits that bounce at once and never buy?","yes":"One unfamiliar referrer explains the rise, with near-total bounce and no orders."}},{"id":"top-referrer","label":"Press, creators and partners","breakdown":"$referring_domain","dropped":{"check":"Did a link that sent steady traffic come down, or did last week's press mention fade?","yes":"One referring domain that sent many visits last week sends few this week."},"spiked":{"check":"Did an article, a gift guide, a creator or a partner link to the store?","yes":"One referring domain explains most of the rise; expect it to fade within one or two weeks."}},{"id":"ai-assistants","label":"AI assistants","dropped":{"check":"Did visits from chatgpt.com, perplexity.ai, gemini.google.com or copilot.microsoft.com fall?","yes":"The AI assistant referrers send fewer visits, often after a model or citation change on their side."},"spiked":{"check":"Are AI assistants citing the store more often?","yes":"chatgpt.com, perplexity.ai and similar referrers grow steadily, landing on product and guide pages."}},{"id":"affiliates","label":"Affiliate and coupon sites","dropped":{"check":"Did an affiliate network, coupon site or marketplace listing stop linking?","yes":"Referrals from coupon or affiliate domains fall and affiliate orders fall with them."},"spiked":{"check":"Did a coupon or deal site start listing the store, possibly with a leaked code?","yes":"A coupon domain grows and promo-code use rises with it."}}],"diagnose_order":["self-referrals","referral-spam","top-referrer","ai-assistants","affiliates"],"related":["sessions","organic-sessions","paid-sessions","new-visitor-share","promo-code-usage-rate"],"prose":{"why_it_matters":"Referrals are earned traffic: press, gift guides, creators, partners and, more and more, AI assistants that cite the store. They are spiky by nature, so a single article can double a week and be gone the next. On a store with 21,000 referral sessions a week, the question is always which one domain moved, not whether referrals did.","pitfalls":["Payment pages, sign-in providers and your own subdomains show up as referrers when a visit restarts after them. This spec drops this site's domain and common payment pages; add others you see.","Many apps and sites strip the referrer. Links from email clients, messaging apps and some social apps arrive as direct visits, not referrals.","Referral spam sends fake visits with a made-up referrer. It never orders, so check orders from a new referrer before thanking anyone.","Social networks and search engines are excluded here and counted in their own channels. Tools group the long tail differently, so referral totals rarely match GA4."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "refund-rate": { yaml: "id: refund-rate\nname: Refund rate\naliases:\n  - Return rate\n  - Returns rate\n  - Refund percentage\nfamily: revenue\nkind: rate\npolarity: down-is-good\n\ndefinition:\n  one_line: Refunds issued this week as a share of this week's order revenue.\n  formula: Refunds issued ÷ order revenue after discounts, each by the week it happened\n\nevents:\n  - name: order_refunded\n    description: A refund issued against an earlier order, full or partial.\n    also_called: [refund, Order Refunded, charge.refunded]\n    properties:\n      - name: order_id\n        description: The order refunded; links the refund to the week it was sold.\n      - name: amount\n        description: The refunded amount, excluding tax and shipping.\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n\nnumerator:\n  label: Refunds issued\n  aggregate: sum\n  event: order_refunded\n  property: amount\ndenominator:\n  label: Order revenue\n  aggregate: sum\n  event: order_completed\n  property: total\n\nnoise:\n  type: process\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 0.06\n\nexample:\n  business: store\n  level: 0.0335\n  volume: 13300\n  trend: 0\n\ndrivers:\n  - id: tracking\n    label: Tracking and processing\n    dropped:\n      check: Did refund events stop syncing, for example after a returns app or processor change?\n      yes: Refunds in the payment processor hold while recorded refunds fall.\n    spiked:\n      check: Did a backlog of refunds get processed in one batch, or are refunds recorded twice?\n      yes: Refunds cluster on one or two days, or the same order_id carries a partial and a full refund.\n  - id: past-sales\n    label: Last month's sales\n    feed: shopping\n    dropped:\n      check: Did a post-season wave of returns just end?\n      yes: Refunds fall back as the orders from the busy weeks pass their return window.\n    spiked:\n      check: Did a big sale or gifting season end two to six weeks ago?\n      yes: Refunds rise in step with the orders of those weeks, not this week's, and the same weeks last year show it.\n  - id: product-batch\n    label: One product or batch\n    dropped:\n      check: Did fixing a defect, a size chart or a product description cut returns on one product?\n      yes: Refunds on that product fall from the weeks after the fix.\n    spiked:\n      check: Is one product, size or batch behind most of the refunds?\n      yes: Return reasons cluster on one product, often defective, not as described or wrong size.\n  - id: delivery\n    label: Delivery problems\n    dropped:\n      check: Did a carrier or warehouse problem that caused refunds clear?\n      yes: Refunds for orders not received fall back to their usual level.\n    spiked:\n      check: Did a carrier delay, lost parcels or a warehouse error lead to refunds for orders not received?\n      yes: Refunds for orders not received rise in one region or with one carrier.\n  - id: fraud\n    label: Fraud and disputes\n    feed: stripe\n    dropped:\n      check: Did tighter fraud rules cut refunds issued to settle disputes?\n      yes: Refunds on first orders with high values or shared addresses fall.\n    spiked:\n      check: Did a fraud ring or a wave of disputes get settled with refunds?\n      yes: Refunds concentrate on first orders with high values, new cards or shared shipping addresses.\n  - id: policy\n    label: Return policy\n    dropped:\n      check: Did the return window shorten, return shipping start costing, or exchanges get pushed over refunds?\n      yes: Refunds fall from the policy date while exchanges rise.\n    spiked:\n      check: Did returns become free, the window lengthen, or a try-before-you-buy option launch?\n      yes: Refunds rise from the policy date, on orders placed after it.\n\ndiagnose_order: [tracking, past-sales, product-batch, delivery, fraud, policy]\n\nrelated: [net-revenue, orders, gross-margin, contribution-margin, gross-sales]\n\nprose:\n  why_it_matters: >-\n    Refunds are revenue the store already counted and then gave back, often with shipping paid both ways.\n    Because they follow sales by two to six weeks, the rate moves with last month's orders as\n    much as with today's quality. At Northwind, about 3.4% of $1.33M of order revenue is\n    refunded, roughly $45,000 a week; one more point costs $13,300 a week before return shipping.\n  pitfalls:\n    - This spec divides refunds issued this week by this week's order revenue, so the rate rises for weeks after a big sale with no quality problem. For product quality, group refunds by the week of the original order instead.\n    - Exchanges and store credit aren't refunds and don't appear here, so a store that pushes exchanges sees the rate fall while returns hold.\n    - Partial refunds, price adjustments and goodwill credits count as refunds here. Tag them if you want returns alone.\n    - Return rate is often quoted as orders or units returned ÷ orders or units sold. This spec is by value, so a week of partial refunds or high-priced returns moves the two apart.\n    - Chargebacks run through a separate flow in most processors and appear here only if they are recorded as refunds.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"refund-rate","name":"Refund rate","aliases":["Return rate","Returns rate","Refund percentage"],"family":"revenue","kind":"rate","polarity":"down-is-good","definition":{"one_line":"Refunds issued this week as a share of this week's order revenue.","formula":"Refunds issued ÷ order revenue after discounts, each by the week it happened"},"events":[{"name":"order_refunded","description":"A refund issued against an earlier order, full or partial.","also_called":["refund","Order Refunded","charge.refunded"],"properties":[{"name":"order_id","description":"The order refunded; links the refund to the week it was sold."},{"name":"amount","description":"The refunded amount, excluding tax and shipping."}]},{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."}]}],"numerator":{"label":"Refunds issued","aggregate":"sum","event":"order_refunded","property":"amount"},"denominator":{"label":"Order revenue","aggregate":"sum","event":"order_completed","property":"total"},"noise":{"type":"process","min_denominator":50,"volume_unit":"orders a week","typical":0.06},"example":{"business":"store","level":0.0335,"volume":13300,"trend":0},"drivers":[{"id":"tracking","label":"Tracking and processing","dropped":{"check":"Did refund events stop syncing, for example after a returns app or processor change?","yes":"Refunds in the payment processor hold while recorded refunds fall."},"spiked":{"check":"Did a backlog of refunds get processed in one batch, or are refunds recorded twice?","yes":"Refunds cluster on one or two days, or the same order_id carries a partial and a full refund."}},{"id":"past-sales","label":"Last month's sales","feed":"shopping","dropped":{"check":"Did a post-season wave of returns just end?","yes":"Refunds fall back as the orders from the busy weeks pass their return window."},"spiked":{"check":"Did a big sale or gifting season end two to six weeks ago?","yes":"Refunds rise in step with the orders of those weeks, not this week's, and the same weeks last year show it."}},{"id":"product-batch","label":"One product or batch","dropped":{"check":"Did fixing a defect, a size chart or a product description cut returns on one product?","yes":"Refunds on that product fall from the weeks after the fix."},"spiked":{"check":"Is one product, size or batch behind most of the refunds?","yes":"Return reasons cluster on one product, often defective, not as described or wrong size."}},{"id":"delivery","label":"Delivery problems","dropped":{"check":"Did a carrier or warehouse problem that caused refunds clear?","yes":"Refunds for orders not received fall back to their usual level."},"spiked":{"check":"Did a carrier delay, lost parcels or a warehouse error lead to refunds for orders not received?","yes":"Refunds for orders not received rise in one region or with one carrier."}},{"id":"fraud","label":"Fraud and disputes","feed":"stripe","dropped":{"check":"Did tighter fraud rules cut refunds issued to settle disputes?","yes":"Refunds on first orders with high values or shared addresses fall."},"spiked":{"check":"Did a fraud ring or a wave of disputes get settled with refunds?","yes":"Refunds concentrate on first orders with high values, new cards or shared shipping addresses."}},{"id":"policy","label":"Return policy","dropped":{"check":"Did the return window shorten, return shipping start costing, or exchanges get pushed over refunds?","yes":"Refunds fall from the policy date while exchanges rise."},"spiked":{"check":"Did returns become free, the window lengthen, or a try-before-you-buy option launch?","yes":"Refunds rise from the policy date, on orders placed after it."}}],"diagnose_order":["tracking","past-sales","product-batch","delivery","fraud","policy"],"related":["net-revenue","orders","gross-margin","contribution-margin","gross-sales"],"prose":{"why_it_matters":"Refunds are revenue the store already counted and then gave back, often with shipping paid both ways. Because they follow sales by two to six weeks, the rate moves with last month's orders as much as with today's quality. At Northwind, about 3.4% of $1.33M of order revenue is refunded, roughly $45,000 a week; one more point costs $13,300 a week before return shipping.","pitfalls":["This spec divides refunds issued this week by this week's order revenue, so the rate rises for weeks after a big sale with no quality problem. For product quality, group refunds by the week of the original order instead.","Exchanges and store credit aren't refunds and don't appear here, so a store that pushes exchanges sees the rate fall while returns hold.","Partial refunds, price adjustments and goodwill credits count as refunds here. Tag them if you want returns alone.","Return rate is often quoted as orders or units returned ÷ orders or units sold. This spec is by value, so a week of partial refunds or high-priced returns moves the two apart.","Chargebacks run through a separate flow in most processors and appear here only if they are recorded as refunds."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "repeat-order-share": { yaml: "id: repeat-order-share\nname: Repeat order share\naliases:\n  - Repeat share\n  - Returning customer order share\n  - Share of orders from returning customers\nfamily: customers\ncatalog_id: repeat_share\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of this week's orders placed by customers who had ordered before.\n  formula: Orders not flagged as a first order ÷ orders with the first-order flag set\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: is_first_order\n        description: True when the store has no earlier order from this customer, from its own customer records.\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n\nnumerator:\n  label: Repeat orders\n  aggregate: count\n  event: order_completed\n  where:\n    - property: is_first_order\n      op: eq\n      value: false\ndenominator:\n  label: Orders\n  aggregate: count\n  event: order_completed\n  where:\n    - property: is_first_order\n      op: is_set\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: orders a week\n  typical: 0.38\n\nexample:\n  business: store\n  level: 0.38\n  volume: 13300\n  trend: 0.03\n  season: -0.5\n\ndrivers:\n  - id: tracking\n    label: First-order flag\n    dropped:\n      check: Did a checkout or account change reset order history, so repeat buyers are flagged as first orders?\n      yes: The share falls overnight while repeat orders from email and logged-in customers hold.\n    spiked:\n      check: Did an import or a customer merge mark first orders as repeat, or did the flag stop being set on first orders?\n      yes: The share jumps on one day and the count of flagged first orders falls far below new customers in the store admin.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Is this a sale or holiday week that brings in first-time buyers?\n      yes: The same week last year shows the same dip; Black Friday weeks often run several points lower.\n    spiked:\n      check: Is this the quiet week after a sale, or a members-only or loyalty event?\n      yes: The same week last year shows the same rise once aligned on the event.\n  - id: new-customers\n    label: New customers\n    metric: new-customers\n    dropped:\n      check: Did new customers rise? A strong acquisition week lowers the share with no change in loyalty.\n      yes: New customers are up while returning customers hold.\n    spiked:\n      check: Did new customers fall, for example after paid spend was cut?\n      yes: New customers are down while returning customers hold; the share rose by subtraction.\n  - id: returning-customers\n    label: Returning customers\n    metric: returning-customers\n    dropped:\n      check: Did fewer existing customers come back this week?\n      yes: Returning customers fall while new customers hold.\n    spiked:\n      check: Did more existing customers come back, from a campaign, a restock or a loyalty offer?\n      yes: Returning customers rise while new customers hold.\n  - id: email\n    label: Email and retention flows\n    metric: email-click-rate\n    dropped:\n      check: Did a regular campaign or flow fail to send, or land in spam?\n      yes: Email clicks fall on the days repeat orders do.\n    spiked:\n      check: Did a campaign go to the whole list?\n      yes: Repeat orders cluster in the two days after the send.\n\ndiagnose_order: [tracking, calendar, new-customers, returning-customers, email]\n\nrelated: [new-customers, returning-customers, repeat-purchase-rate, orders, new-customer-revenue-share]\n\nprose:\n  why_it_matters: >-\n    Repeat order share says how much of a week's demand the store didn't have to buy. Because it is\n    a share, it moves when either side moves: a strong acquisition week lowers it with no change in\n    loyalty. At 13,300 orders a week a move of up to about 1.2 points can be chance; past that, check which\n    side changed before calling it retention.\n  pitfalls:\n    - A share falls when new customers rise. Read it with the new and returning customer counts before calling it a loyalty problem.\n    - Black Friday and launch weeks bring a flood of first orders and pull the share down by several points. Compare with the same week last year.\n    - Orders without the first-order flag are left out of both sides. If many orders lack it, fix the tracking first, because the share of a subset can drift on its own.\n    - This is a share of orders this week, not repeat purchase rate, which is a share of customers over a year. The two are often quoted under the same name.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"repeat-order-share","name":"Repeat order share","aliases":["Repeat share","Returning customer order share","Share of orders from returning customers"],"family":"customers","catalog_id":"repeat_share","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of this week's orders placed by customers who had ordered before.","formula":"Orders not flagged as a first order ÷ orders with the first-order flag set"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"is_first_order","description":"True when the store has no earlier order from this customer, from its own customer records."},{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."}]}],"numerator":{"label":"Repeat orders","aggregate":"count","event":"order_completed","where":[{"property":"is_first_order","op":"eq","value":false}]},"denominator":{"label":"Orders","aggregate":"count","event":"order_completed","where":[{"property":"is_first_order","op":"is_set"}]},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"orders a week","typical":0.38},"example":{"business":"store","level":0.38,"volume":13300,"trend":0.03,"season":-0.5},"drivers":[{"id":"tracking","label":"First-order flag","dropped":{"check":"Did a checkout or account change reset order history, so repeat buyers are flagged as first orders?","yes":"The share falls overnight while repeat orders from email and logged-in customers hold."},"spiked":{"check":"Did an import or a customer merge mark first orders as repeat, or did the flag stop being set on first orders?","yes":"The share jumps on one day and the count of flagged first orders falls far below new customers in the store admin."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Is this a sale or holiday week that brings in first-time buyers?","yes":"The same week last year shows the same dip; Black Friday weeks often run several points lower."},"spiked":{"check":"Is this the quiet week after a sale, or a members-only or loyalty event?","yes":"The same week last year shows the same rise once aligned on the event."}},{"id":"new-customers","label":"New customers","metric":"new-customers","dropped":{"check":"Did new customers rise? A strong acquisition week lowers the share with no change in loyalty.","yes":"New customers are up while returning customers hold."},"spiked":{"check":"Did new customers fall, for example after paid spend was cut?","yes":"New customers are down while returning customers hold; the share rose by subtraction."}},{"id":"returning-customers","label":"Returning customers","metric":"returning-customers","dropped":{"check":"Did fewer existing customers come back this week?","yes":"Returning customers fall while new customers hold."},"spiked":{"check":"Did more existing customers come back, from a campaign, a restock or a loyalty offer?","yes":"Returning customers rise while new customers hold."}},{"id":"email","label":"Email and retention flows","metric":"email-click-rate","dropped":{"check":"Did a regular campaign or flow fail to send, or land in spam?","yes":"Email clicks fall on the days repeat orders do."},"spiked":{"check":"Did a campaign go to the whole list?","yes":"Repeat orders cluster in the two days after the send."}}],"diagnose_order":["tracking","calendar","new-customers","returning-customers","email"],"related":["new-customers","returning-customers","repeat-purchase-rate","orders","new-customer-revenue-share"],"prose":{"why_it_matters":"Repeat order share says how much of a week's demand the store didn't have to buy. Because it is a share, it moves when either side moves: a strong acquisition week lowers it with no change in loyalty. At 13,300 orders a week a move of up to about 1.2 points can be chance; past that, check which side changed before calling it retention.","pitfalls":["A share falls when new customers rise. Read it with the new and returning customer counts before calling it a loyalty problem.","Black Friday and launch weeks bring a flood of first orders and pull the share down by several points. Compare with the same week last year.","Orders without the first-order flag are left out of both sides. If many orders lack it, fix the tracking first, because the share of a subset can drift on its own.","This is a share of orders this week, not repeat purchase rate, which is a share of customers over a year. The two are often quoted under the same name."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "repeat-purchase-rate": { yaml: "id: repeat-purchase-rate\nname: Repeat purchase rate\naliases:\n  - Returning customer rate\n  - Repeat customer rate\n  - Repeat rate\n  - RPR\nfamily: customers\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of customers who ordered in the last 52 weeks who ordered at least twice in that time.\n  formula: Customers with 2 or more orders in the trailing 52 weeks ÷ customers with any order in them, at each week's end\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: customer_id\n        description: The store's customer id, shared by guest and logged-in orders with the same email.\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n\nnumerator:\n  label: Customers with 2 or more orders in 52 weeks\n  aggregate: unique_users\n  event: order_completed\ndenominator:\n  label: Customers with an order in 52 weeks\n  aggregate: unique_users\n  event: order_completed\n\nqueries:\n  hogql: |-\n    -- Repeat purchase rate: customers with 2 or more distinct orders in the 52 weeks ending each week (Monday 00:00 UTC) ÷ customers with any order in them, for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its person_id when that is missing.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(a.repeaters, 0) AS numerator,\n      coalesce(a.customers, 0) AS denominator,\n      if(denominator = 0, NULL, numerator / denominator) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, countIf(orders >= 2) AS repeaters, count() AS customers\n      FROM (\n        SELECT s.week AS week, o.customer_id AS customer_id, uniqExact(o.order_id) AS orders\n        FROM (\n          SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n        ) AS s\n        CROSS JOIN (\n          SELECT\n            coalesce(properties.customer_id, toString(person_id)) AS customer_id,\n            properties.order_id AS order_id,\n            toMonday(toTimeZone(timestamp, 'UTC')) AS order_week\n          FROM events\n          WHERE event = 'order_completed'\n            AND timestamp >= now() - toIntervalWeek(78)\n            AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(77) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n        ) AS o\n        WHERE o.order_week BETWEEN s.week - toIntervalWeek(51) AND s.week\n          AND o.customer_id IS NOT NULL\n        GROUP BY week, customer_id\n      )\n      GROUP BY week\n    ) AS a ON a.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Repeat purchase rate: customers with 2 or more distinct orders in the 52 weeks ending each week (Monday 00:00 UTC) ÷ customers with any order in them, for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its user_id when that is missing.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    orders AS (\n      SELECT\n        coalesce(properties->>'customer_id', user_id) AS customer_id,\n        properties->>'order_id' AS order_id,\n        date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week\n      FROM events\n      WHERE event_name = 'order_completed'\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '77 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n    ),\n    per_customer AS (\n      SELECT w.week, o.customer_id, count(DISTINCT o.order_id) AS orders\n      FROM weeks AS w\n      JOIN orders AS o ON o.week BETWEEN w.week - 357 AND w.week\n      WHERE o.customer_id IS NOT NULL\n      GROUP BY w.week, o.customer_id\n    ),\n    weekly AS (\n      SELECT week, count(*) FILTER (WHERE orders >= 2) AS repeaters, count(*) AS customers\n      FROM per_customer\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      coalesce(a.repeaters, 0) AS numerator,\n      coalesce(a.customers, 0) AS denominator,\n      a.repeaters::numeric / nullif(a.customers, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS a ON a.week = w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Repeat purchase rate: customers with 2 or more distinct orders in the 52 weeks ending each week (Monday 00:00 UTC) ÷ customers with any order in them, for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its user_id when that is missing.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    orders AS (\n      SELECT\n        COALESCE(JSON_VALUE(properties, '$.customer_id'), user_id) AS customer_id,\n        JSON_VALUE(properties, '$.order_id') AS order_id,\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week\n      FROM events\n      WHERE event_name = 'order_completed'\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 77 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    ),\n    per_customer AS (\n      SELECT w.week, o.customer_id, COUNT(DISTINCT o.order_id) AS orders\n      FROM weeks AS w\n      JOIN orders AS o ON o.week BETWEEN DATE_SUB(w.week, INTERVAL 51 WEEK) AND w.week\n      WHERE o.customer_id IS NOT NULL\n      GROUP BY w.week, o.customer_id\n    ),\n    weekly AS (\n      SELECT week, COUNTIF(orders >= 2) AS repeaters, COUNT(*) AS customers\n      FROM per_customer\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      COALESCE(a.repeaters, 0) AS numerator,\n      COALESCE(a.customers, 0) AS denominator,\n      SAFE_DIVIDE(a.repeaters, a.customers) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS a ON a.week = w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Repeat purchase rate: customers with 2 or more distinct orders in the 52 weeks ending each week (Monday 00:00 UTC) ÷ customers with any order in them, for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its user_id when that is missing.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    orders AS (\n      SELECT\n        COALESCE(properties:\"customer_id\"::string, user_id) AS customer_id,\n        properties:\"order_id\"::string AS order_id,\n        DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week\n      FROM events\n      WHERE event_name = 'order_completed'\n        AND occurred_at >= DATEADD(week, -77, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n    ),\n    per_customer AS (\n      SELECT w.week, o.customer_id, COUNT(DISTINCT o.order_id) AS orders\n      FROM weeks AS w\n      JOIN orders AS o ON o.week BETWEEN DATEADD(week, -51, w.week) AND w.week\n      WHERE o.customer_id IS NOT NULL\n      GROUP BY w.week, o.customer_id\n    ),\n    weekly AS (\n      SELECT week, COUNT_IF(orders >= 2) AS repeaters, COUNT(*) AS customers\n      FROM per_customer\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      COALESCE(a.repeaters, 0) AS numerator,\n      COALESCE(a.customers, 0) AS denominator,\n      a.repeaters::float / NULLIF(a.customers, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS a ON a.week = w.week\n    ORDER BY w.week;\n\nnoise:\n  type: process\n  min_denominator: 200\n  volume_unit: customers who ordered in the last 52 weeks\n  typical: 0.27\n\nexample:\n  business: store\n  level: 0.27\n  volume: 470000\n  trend: 0.03\n\ndrivers:\n  - id: identity\n    label: Customer matching\n    dropped:\n      check: Did customer matching break, so one buyer now appears under several ids?\n      yes: Customers in the window grow faster than orders, and customers with a single order jump.\n    spiked:\n      check: Did a merge or import collapse duplicate customer records into one?\n      yes: Customers in the window fall on one day while orders don't change.\n  - id: roll-off\n    label: The week leaving the window\n    dropped:\n      check: Is an unusually strong repeat week from a year ago leaving the 52-week window?\n      yes: The week 52 weeks back had far more repeat orders than usual, such as last year's holiday peak.\n    spiked:\n      check: Is a week full of one-time buyers from a year ago leaving the window?\n      yes: The week 52 weeks back was a sale week with a flood of first orders that never returned.\n  - id: acquisition-mix\n    label: New customers entering\n    metric: new-customers\n    dropped:\n      check: Did a large wave of new customers enter the window? They haven't had time to reorder, which lowers the rate for months.\n      yes: New customers over the last 8 to 12 weeks run well above the same weeks last year.\n    spiked:\n      check: Did acquisition slow? Fewer fresh customers lifts the rate with no change in loyalty.\n      yes: New customers over recent weeks run below last year while returning customers hold.\n  - id: second-orders\n    label: Second orders from recent cohorts\n    metric: second-order-rate\n    dropped:\n      check: Are recent cohorts coming back less within their first 90 days?\n      yes: Second order rate has fallen for the last few mature cohorts.\n    spiked:\n      check: Are recent cohorts coming back more within their first 90 days?\n      yes: Second order rate has risen for the last few mature cohorts.\n  - id: retention-marketing\n    label: Email and retention flows\n    metric: email-click-rate\n    dropped:\n      check: Did a post-purchase, replenishment or win-back flow stop sending?\n      yes: Flow sends or clicks fell weeks ago and repeat orders have been thinning since.\n    spiked:\n      check: Did a new flow, a loyalty programme or a subscription option launch?\n      yes: Repeat orders from the new flow or programme account for most of the gain.\n\ndiagnose_order: [identity, roll-off, acquisition-mix, second-orders, retention-marketing]\n\nrelated: [second-order-rate, purchase-frequency, repeat-order-share, customer-lifetime-value, active-customers]\n\nprose:\n  why_it_matters: >-\n    Repeat purchase rate is the share of a year's buyers who came back at least once, and the\n    retention number most store reports quote. Each week adds one week of orders to a 52-week\n    window and drops another, so it moves slowly and a move of even half a point is worth a look.\n    It is the long view of retention; second order rate is the early warning.\n  pitfalls:\n    - Store dashboards often compute it over whatever date range is selected, and some count a customer as repeat when they have any earlier order, even one outside the range. This spec counts 2 or more orders inside the 52 weeks.\n    - The window decides the number. A 90-day and a 365-day rate for the same store can differ several times over; this spec uses 52 weeks, and every comparison must too.\n    - Fast growth lowers it, because customers won in the last few months haven't had time to reorder. Read it next to new customers before blaming retention.\n    - One buyer split across several ids, through guest checkout or a new email, counts as two one-time customers and drags the rate down. Match on the store's customer id.\n    - A weekly move is often the week leaving the window rather than this week's behaviour. Look at what happened 52 weeks ago before looking for a cause today.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"repeat-purchase-rate","name":"Repeat purchase rate","aliases":["Returning customer rate","Repeat customer rate","Repeat rate","RPR"],"family":"customers","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of customers who ordered in the last 52 weeks who ordered at least twice in that time.","formula":"Customers with 2 or more orders in the trailing 52 weeks ÷ customers with any order in them, at each week's end"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"customer_id","description":"The store's customer id, shared by guest and logged-in orders with the same email."},{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."}]}],"numerator":{"label":"Customers with 2 or more orders in 52 weeks","aggregate":"unique_users","event":"order_completed"},"denominator":{"label":"Customers with an order in 52 weeks","aggregate":"unique_users","event":"order_completed"},"queries":{"hogql":"-- Repeat purchase rate: customers with 2 or more distinct orders in the 52 weeks ending each week (Monday 00:00 UTC) ÷ customers with any order in them, for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its person_id when that is missing.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(a.repeaters, 0) AS numerator,\n  coalesce(a.customers, 0) AS denominator,\n  if(denominator = 0, NULL, numerator / denominator) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, countIf(orders >= 2) AS repeaters, count() AS customers\n  FROM (\n    SELECT s.week AS week, o.customer_id AS customer_id, uniqExact(o.order_id) AS orders\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS s\n    CROSS JOIN (\n      SELECT\n        coalesce(properties.customer_id, toString(person_id)) AS customer_id,\n        properties.order_id AS order_id,\n        toMonday(toTimeZone(timestamp, 'UTC')) AS order_week\n      FROM events\n      WHERE event = 'order_completed'\n        AND timestamp >= now() - toIntervalWeek(78)\n        AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(77) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n    ) AS o\n    WHERE o.order_week BETWEEN s.week - toIntervalWeek(51) AND s.week\n      AND o.customer_id IS NOT NULL\n    GROUP BY week, customer_id\n  )\n  GROUP BY week\n) AS a ON a.week = w.week\nORDER BY week","postgres":"-- Repeat purchase rate: customers with 2 or more distinct orders in the 52 weeks ending each week (Monday 00:00 UTC) ÷ customers with any order in them, for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its user_id when that is missing.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\norders AS (\n  SELECT\n    coalesce(properties->>'customer_id', user_id) AS customer_id,\n    properties->>'order_id' AS order_id,\n    date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week\n  FROM events\n  WHERE event_name = 'order_completed'\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '77 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n),\nper_customer AS (\n  SELECT w.week, o.customer_id, count(DISTINCT o.order_id) AS orders\n  FROM weeks AS w\n  JOIN orders AS o ON o.week BETWEEN w.week - 357 AND w.week\n  WHERE o.customer_id IS NOT NULL\n  GROUP BY w.week, o.customer_id\n),\nweekly AS (\n  SELECT week, count(*) FILTER (WHERE orders >= 2) AS repeaters, count(*) AS customers\n  FROM per_customer\n  GROUP BY week\n)\nSELECT\n  w.week,\n  coalesce(a.repeaters, 0) AS numerator,\n  coalesce(a.customers, 0) AS denominator,\n  a.repeaters::numeric / nullif(a.customers, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS a ON a.week = w.week\nORDER BY w.week;","bigquery":"-- Repeat purchase rate: customers with 2 or more distinct orders in the 52 weeks ending each week (Monday 00:00 UTC) ÷ customers with any order in them, for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its user_id when that is missing.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\norders AS (\n  SELECT\n    COALESCE(JSON_VALUE(properties, '$.customer_id'), user_id) AS customer_id,\n    JSON_VALUE(properties, '$.order_id') AS order_id,\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week\n  FROM events\n  WHERE event_name = 'order_completed'\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 77 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n),\nper_customer AS (\n  SELECT w.week, o.customer_id, COUNT(DISTINCT o.order_id) AS orders\n  FROM weeks AS w\n  JOIN orders AS o ON o.week BETWEEN DATE_SUB(w.week, INTERVAL 51 WEEK) AND w.week\n  WHERE o.customer_id IS NOT NULL\n  GROUP BY w.week, o.customer_id\n),\nweekly AS (\n  SELECT week, COUNTIF(orders >= 2) AS repeaters, COUNT(*) AS customers\n  FROM per_customer\n  GROUP BY week\n)\nSELECT\n  w.week,\n  COALESCE(a.repeaters, 0) AS numerator,\n  COALESCE(a.customers, 0) AS denominator,\n  SAFE_DIVIDE(a.repeaters, a.customers) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS a ON a.week = w.week\nORDER BY w.week;","snowflake":"-- Repeat purchase rate: customers with 2 or more distinct orders in the 52 weeks ending each week (Monday 00:00 UTC) ÷ customers with any order in them, for each of the last 26 complete weeks, oldest first. A customer is the order's customer_id, or its user_id when that is missing.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\norders AS (\n  SELECT\n    COALESCE(properties:\"customer_id\"::string, user_id) AS customer_id,\n    properties:\"order_id\"::string AS order_id,\n    DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week\n  FROM events\n  WHERE event_name = 'order_completed'\n    AND occurred_at >= DATEADD(week, -77, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n),\nper_customer AS (\n  SELECT w.week, o.customer_id, COUNT(DISTINCT o.order_id) AS orders\n  FROM weeks AS w\n  JOIN orders AS o ON o.week BETWEEN DATEADD(week, -51, w.week) AND w.week\n  WHERE o.customer_id IS NOT NULL\n  GROUP BY w.week, o.customer_id\n),\nweekly AS (\n  SELECT week, COUNT_IF(orders >= 2) AS repeaters, COUNT(*) AS customers\n  FROM per_customer\n  GROUP BY week\n)\nSELECT\n  w.week,\n  COALESCE(a.repeaters, 0) AS numerator,\n  COALESCE(a.customers, 0) AS denominator,\n  a.repeaters::float / NULLIF(a.customers, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS a ON a.week = w.week\nORDER BY w.week;"},"noise":{"type":"process","min_denominator":200,"volume_unit":"customers who ordered in the last 52 weeks","typical":0.27},"example":{"business":"store","level":0.27,"volume":470000,"trend":0.03},"drivers":[{"id":"identity","label":"Customer matching","dropped":{"check":"Did customer matching break, so one buyer now appears under several ids?","yes":"Customers in the window grow faster than orders, and customers with a single order jump."},"spiked":{"check":"Did a merge or import collapse duplicate customer records into one?","yes":"Customers in the window fall on one day while orders don't change."}},{"id":"roll-off","label":"The week leaving the window","dropped":{"check":"Is an unusually strong repeat week from a year ago leaving the 52-week window?","yes":"The week 52 weeks back had far more repeat orders than usual, such as last year's holiday peak."},"spiked":{"check":"Is a week full of one-time buyers from a year ago leaving the window?","yes":"The week 52 weeks back was a sale week with a flood of first orders that never returned."}},{"id":"acquisition-mix","label":"New customers entering","metric":"new-customers","dropped":{"check":"Did a large wave of new customers enter the window? They haven't had time to reorder, which lowers the rate for months.","yes":"New customers over the last 8 to 12 weeks run well above the same weeks last year."},"spiked":{"check":"Did acquisition slow? Fewer fresh customers lifts the rate with no change in loyalty.","yes":"New customers over recent weeks run below last year while returning customers hold."}},{"id":"second-orders","label":"Second orders from recent cohorts","metric":"second-order-rate","dropped":{"check":"Are recent cohorts coming back less within their first 90 days?","yes":"Second order rate has fallen for the last few mature cohorts."},"spiked":{"check":"Are recent cohorts coming back more within their first 90 days?","yes":"Second order rate has risen for the last few mature cohorts."}},{"id":"retention-marketing","label":"Email and retention flows","metric":"email-click-rate","dropped":{"check":"Did a post-purchase, replenishment or win-back flow stop sending?","yes":"Flow sends or clicks fell weeks ago and repeat orders have been thinning since."},"spiked":{"check":"Did a new flow, a loyalty programme or a subscription option launch?","yes":"Repeat orders from the new flow or programme account for most of the gain."}}],"diagnose_order":["identity","roll-off","acquisition-mix","second-orders","retention-marketing"],"related":["second-order-rate","purchase-frequency","repeat-order-share","customer-lifetime-value","active-customers"],"prose":{"why_it_matters":"Repeat purchase rate is the share of a year's buyers who came back at least once, and the retention number most store reports quote. Each week adds one week of orders to a 52-week window and drops another, so it moves slowly and a move of even half a point is worth a look. It is the long view of retention; second order rate is the early warning.","pitfalls":["Store dashboards often compute it over whatever date range is selected, and some count a customer as repeat when they have any earlier order, even one outside the range. This spec counts 2 or more orders inside the 52 weeks.","The window decides the number. A 90-day and a 365-day rate for the same store can differ several times over; this spec uses 52 weeks, and every comparison must too.","Fast growth lowers it, because customers won in the last few months haven't had time to reorder. Read it next to new customers before blaming retention.","One buyer split across several ids, through guest checkout or a new email, counts as two one-time customers and drags the rate down. Match on the store's customer id.","A weekly move is often the week leaving the window rather than this week's behaviour. Look at what happened 52 weeks ago before looking for a cause today."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "resurrected-users": { yaml: "id: resurrected-users\nname: Resurrected users\naliases:\n  - Reactivated users\n  - Returning dormant users\n  - Resurrections\n  - Win-back users\nfamily: engagement\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: People active this week who were inactive last week but had been active before, the lapsed users who came back.\n  formula: Distinct people active this week, with no activity the week before and some activity in an earlier week\n\nevents:\n  - name: \"*\"\n    description: Any event a person sends. Activity, not one specific action; the same definition as WAU.\n    also_called: [All events, Any event, Active event]\n    properties:\n      - name: $os\n        description: The operating system, for splitting by platform.\n\nnumerator:\n  label: People back after a week or more away\n  aggregate: returning_users\n  event: \"*\"\n\nqueries:\n  hogql: |-\n    -- Resurrected users per week: distinct people active in the week, with no event in the week before and a first event before that. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT w.week AS week, coalesce(r.people, 0) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, count() AS people\n      FROM (\n        SELECT\n          a.person_id AS person_id,\n          arrayJoin(a.active_weeks) AS week,\n          a.active_weeks AS active_weeks,\n          f.first_week AS first_week\n        FROM (\n          SELECT person_id, groupUniqArray(toMonday(toTimeZone(timestamp, 'UTC'))) AS active_weeks\n          FROM events\n          WHERE person_id IS NOT NULL\n            AND timestamp >= now() - toIntervalWeek(28)\n            AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(27) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n          GROUP BY person_id\n        ) AS a\n        INNER JOIN (\n          SELECT person_id, toMonday(min(toTimeZone(timestamp, 'UTC'))) AS first_week\n          FROM events\n          WHERE person_id IS NOT NULL\n          GROUP BY person_id\n        ) AS f ON f.person_id = a.person_id\n      )\n      WHERE week BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n        AND first_week < week - toIntervalWeek(1)\n        AND NOT has(active_weeks, week - toIntervalWeek(1))\n      GROUP BY week\n    ) AS r ON r.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Resurrected users per week: distinct people active in the week, with no event in the week before and a first event before that. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    active AS (\n      SELECT DISTINCT user_id, date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week\n      FROM events\n      WHERE user_id IS NOT NULL\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '27 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n    ),\n    firsts AS (\n      SELECT user_id, min(occurred_at AT TIME ZONE 'UTC') AS first_at\n      FROM events\n      WHERE user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    resurrected AS (\n      SELECT a.week, count(*) AS people\n      FROM active AS a\n      JOIN firsts AS f ON f.user_id = a.user_id\n      LEFT JOIN active AS prev ON prev.user_id = a.user_id AND prev.week = a.week - 7\n      WHERE prev.user_id IS NULL\n        AND f.first_at < a.week - 7\n      GROUP BY a.week\n    )\n    SELECT w.week, coalesce(r.people, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN resurrected AS r ON r.week = w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Resurrected users per week: distinct people active in the week, with no event in the week before and a first event before that. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    active AS (\n      SELECT DISTINCT user_id, DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week\n      FROM events\n      WHERE user_id IS NOT NULL\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 27 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    ),\n    firsts AS (\n      SELECT user_id, MIN(occurred_at) AS first_at\n      FROM events\n      WHERE user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    resurrected AS (\n      SELECT a.week, COUNT(*) AS people\n      FROM active AS a\n      JOIN firsts AS f ON f.user_id = a.user_id\n      LEFT JOIN active AS prev ON prev.user_id = a.user_id AND prev.week = DATE_SUB(a.week, INTERVAL 1 WEEK)\n      WHERE prev.user_id IS NULL\n        AND f.first_at < TIMESTAMP(DATE_SUB(a.week, INTERVAL 1 WEEK))\n      GROUP BY a.week\n    )\n    SELECT w.week, COALESCE(r.people, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN resurrected AS r ON r.week = w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Resurrected users per week: distinct people active in the week, with no event in the week before and a first event before that. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    active AS (\n      SELECT DISTINCT user_id, DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week\n      FROM events\n      WHERE user_id IS NOT NULL\n        AND occurred_at >= DATEADD(week, -27, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n    ),\n    firsts AS (\n      SELECT user_id, MIN(occurred_at) AS first_at\n      FROM events\n      WHERE user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    resurrected AS (\n      SELECT a.week, COUNT(*) AS people\n      FROM active AS a\n      JOIN firsts AS f ON f.user_id = a.user_id\n      LEFT JOIN active AS prev ON prev.user_id = a.user_id AND prev.week = DATEADD(week, -1, a.week)\n      WHERE prev.user_id IS NULL\n        AND f.first_at < DATEADD(week, -1, a.week)\n      GROUP BY a.week\n    )\n    SELECT w.week, COALESCE(r.people, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN resurrected AS r ON r.week = w.week\n    ORDER BY w.week;\n\nnoise:\n  type: poisson\n  min_denominator: 50\n  volume_unit: resurrected users a week\n  typical: 6500\n\nexample:\n  business: app\n  level: 6500\n  volume: 6500\n  trend: 0.12\n\ndrivers:\n  - id: tracking\n    label: Identity and tracking\n    dropped:\n      check: Did returning people stop being recognised, so they now appear as new users instead?\n      yes: New users rise as resurrected users fall, by about the same number, from one date.\n    spiked:\n      check: Did an identity or SDK change wake up old ids, or merge old anonymous ids into active people?\n      yes: Resurrected users jump on one platform or app version, with very few events per person.\n  - id: calendar\n    label: Last week's dip\n    feed: holidays\n    dropped:\n      check: Was last week unusually busy, so fewer regulars had a gap?\n      yes: Last week's WAU was above its range and this week's resurrections fall by a similar number.\n    spiked:\n      check: Was last week a holiday or outage week, so regulars who skipped it now count as resurrected?\n      yes: People retained from the week before fell last week, and resurrections rise this week by a similar number.\n  - id: campaigns\n    label: Win-back campaigns\n    metric: email-click-rate\n    dropped:\n      check: Did a regular win-back email or push skip this week, or start landing in spam?\n      yes: Returns from campaign links and notification opens fall while other returns hold.\n    spiked:\n      check: Did a win-back email, push or ad campaign go out?\n      yes: Resurrections cluster on the send days and arrive through the campaign's link or notification.\n  - id: platform\n    label: Platform and releases\n    breakdown: $os\n    feed: app-stores\n    dropped:\n      check: Did a forced update or a login problem stop lapsed people getting back in on one platform?\n      yes: Resurrections fall on one platform from a release date while the others hold.\n    spiked:\n      check: Did a release, store feature or new integration bring lapsed people back on one platform?\n      yes: Resurrections rise on one platform from the release date.\n  - id: dormant-pool\n    label: How many people have lapsed\n    metric: week-4-retention\n    dropped:\n      check: Is the pool of lapsed people smaller, because fewer people lapsed in recent months?\n      yes: Retention of recent cohorts rose, so fewer lapsed and fewer can come back. Not bad news.\n    spiked:\n      check: Did a large group lapse recently, growing the pool that can come back?\n      yes: Retention of recent cohorts fell a few weeks ago, and part of the loss is now returning.\n\ndiagnose_order: [tracking, calendar, campaigns, platform, dormant-pool]\n\nrelated: [wau, dau, mau, week-4-retention, email-click-rate]\n\nprose:\n  why_it_matters: >-\n    Resurrected users are the lapsed people who came back, one of the three groups, with new and\n    retained people, that make up weekly actives. A steady stream of returners means the product\n    stays useful between bursts of use; a falling one, with steady sign-ups, means people who leave\n    stay gone. At 6,500 a week, chance alone moves it by about 3.5%.\n  pitfalls:\n    - Resurrection depends on the period. A weekly product's regulars skip a week now and then, so weekly resurrections include ordinary gaps; pick the period that matches how often the product is used.\n    - A holiday or outage week inflates the next week's resurrections, because regulars who skipped it count as returning.\n    - Identity changes that split one person into two ids turn regulars into new users, and merges turn new users into resurrected ones.\n    - Win-back campaigns raise resurrections for a week. Judge them on how many of those people are still active a month later.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"resurrected-users","name":"Resurrected users","aliases":["Reactivated users","Returning dormant users","Resurrections","Win-back users"],"family":"engagement","kind":"count","polarity":"up-is-good","definition":{"one_line":"People active this week who were inactive last week but had been active before, the lapsed users who came back.","formula":"Distinct people active this week, with no activity the week before and some activity in an earlier week"},"events":[{"name":"*","description":"Any event a person sends. Activity, not one specific action; the same definition as WAU.","also_called":["All events","Any event","Active event"],"properties":[{"name":"$os","description":"The operating system, for splitting by platform."}]}],"numerator":{"label":"People back after a week or more away","aggregate":"returning_users","event":"*"},"queries":{"hogql":"-- Resurrected users per week: distinct people active in the week, with no event in the week before and a first event before that. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT w.week AS week, coalesce(r.people, 0) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, count() AS people\n  FROM (\n    SELECT\n      a.person_id AS person_id,\n      arrayJoin(a.active_weeks) AS week,\n      a.active_weeks AS active_weeks,\n      f.first_week AS first_week\n    FROM (\n      SELECT person_id, groupUniqArray(toMonday(toTimeZone(timestamp, 'UTC'))) AS active_weeks\n      FROM events\n      WHERE person_id IS NOT NULL\n        AND timestamp >= now() - toIntervalWeek(28)\n        AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(27) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n      GROUP BY person_id\n    ) AS a\n    INNER JOIN (\n      SELECT person_id, toMonday(min(toTimeZone(timestamp, 'UTC'))) AS first_week\n      FROM events\n      WHERE person_id IS NOT NULL\n      GROUP BY person_id\n    ) AS f ON f.person_id = a.person_id\n  )\n  WHERE week BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n    AND first_week < week - toIntervalWeek(1)\n    AND NOT has(active_weeks, week - toIntervalWeek(1))\n  GROUP BY week\n) AS r ON r.week = w.week\nORDER BY week","postgres":"-- Resurrected users per week: distinct people active in the week, with no event in the week before and a first event before that. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nactive AS (\n  SELECT DISTINCT user_id, date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week\n  FROM events\n  WHERE user_id IS NOT NULL\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '27 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n),\nfirsts AS (\n  SELECT user_id, min(occurred_at AT TIME ZONE 'UTC') AS first_at\n  FROM events\n  WHERE user_id IS NOT NULL\n  GROUP BY user_id\n),\nresurrected AS (\n  SELECT a.week, count(*) AS people\n  FROM active AS a\n  JOIN firsts AS f ON f.user_id = a.user_id\n  LEFT JOIN active AS prev ON prev.user_id = a.user_id AND prev.week = a.week - 7\n  WHERE prev.user_id IS NULL\n    AND f.first_at < a.week - 7\n  GROUP BY a.week\n)\nSELECT w.week, coalesce(r.people, 0) AS value\nFROM weeks AS w\nLEFT JOIN resurrected AS r ON r.week = w.week\nORDER BY w.week;","bigquery":"-- Resurrected users per week: distinct people active in the week, with no event in the week before and a first event before that. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nactive AS (\n  SELECT DISTINCT user_id, DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week\n  FROM events\n  WHERE user_id IS NOT NULL\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 27 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n),\nfirsts AS (\n  SELECT user_id, MIN(occurred_at) AS first_at\n  FROM events\n  WHERE user_id IS NOT NULL\n  GROUP BY user_id\n),\nresurrected AS (\n  SELECT a.week, COUNT(*) AS people\n  FROM active AS a\n  JOIN firsts AS f ON f.user_id = a.user_id\n  LEFT JOIN active AS prev ON prev.user_id = a.user_id AND prev.week = DATE_SUB(a.week, INTERVAL 1 WEEK)\n  WHERE prev.user_id IS NULL\n    AND f.first_at < TIMESTAMP(DATE_SUB(a.week, INTERVAL 1 WEEK))\n  GROUP BY a.week\n)\nSELECT w.week, COALESCE(r.people, 0) AS value\nFROM weeks AS w\nLEFT JOIN resurrected AS r ON r.week = w.week\nORDER BY w.week;","snowflake":"-- Resurrected users per week: distinct people active in the week, with no event in the week before and a first event before that. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nactive AS (\n  SELECT DISTINCT user_id, DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week\n  FROM events\n  WHERE user_id IS NOT NULL\n    AND occurred_at >= DATEADD(week, -27, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n),\nfirsts AS (\n  SELECT user_id, MIN(occurred_at) AS first_at\n  FROM events\n  WHERE user_id IS NOT NULL\n  GROUP BY user_id\n),\nresurrected AS (\n  SELECT a.week, COUNT(*) AS people\n  FROM active AS a\n  JOIN firsts AS f ON f.user_id = a.user_id\n  LEFT JOIN active AS prev ON prev.user_id = a.user_id AND prev.week = DATEADD(week, -1, a.week)\n  WHERE prev.user_id IS NULL\n    AND f.first_at < DATEADD(week, -1, a.week)\n  GROUP BY a.week\n)\nSELECT w.week, COALESCE(r.people, 0) AS value\nFROM weeks AS w\nLEFT JOIN resurrected AS r ON r.week = w.week\nORDER BY w.week;"},"noise":{"type":"poisson","min_denominator":50,"volume_unit":"resurrected users a week","typical":6500},"example":{"business":"app","level":6500,"volume":6500,"trend":0.12},"drivers":[{"id":"tracking","label":"Identity and tracking","dropped":{"check":"Did returning people stop being recognised, so they now appear as new users instead?","yes":"New users rise as resurrected users fall, by about the same number, from one date."},"spiked":{"check":"Did an identity or SDK change wake up old ids, or merge old anonymous ids into active people?","yes":"Resurrected users jump on one platform or app version, with very few events per person."}},{"id":"calendar","label":"Last week's dip","feed":"holidays","dropped":{"check":"Was last week unusually busy, so fewer regulars had a gap?","yes":"Last week's WAU was above its range and this week's resurrections fall by a similar number."},"spiked":{"check":"Was last week a holiday or outage week, so regulars who skipped it now count as resurrected?","yes":"People retained from the week before fell last week, and resurrections rise this week by a similar number."}},{"id":"campaigns","label":"Win-back campaigns","metric":"email-click-rate","dropped":{"check":"Did a regular win-back email or push skip this week, or start landing in spam?","yes":"Returns from campaign links and notification opens fall while other returns hold."},"spiked":{"check":"Did a win-back email, push or ad campaign go out?","yes":"Resurrections cluster on the send days and arrive through the campaign's link or notification."}},{"id":"platform","label":"Platform and releases","breakdown":"$os","feed":"app-stores","dropped":{"check":"Did a forced update or a login problem stop lapsed people getting back in on one platform?","yes":"Resurrections fall on one platform from a release date while the others hold."},"spiked":{"check":"Did a release, store feature or new integration bring lapsed people back on one platform?","yes":"Resurrections rise on one platform from the release date."}},{"id":"dormant-pool","label":"How many people have lapsed","metric":"week-4-retention","dropped":{"check":"Is the pool of lapsed people smaller, because fewer people lapsed in recent months?","yes":"Retention of recent cohorts rose, so fewer lapsed and fewer can come back. Not bad news."},"spiked":{"check":"Did a large group lapse recently, growing the pool that can come back?","yes":"Retention of recent cohorts fell a few weeks ago, and part of the loss is now returning."}}],"diagnose_order":["tracking","calendar","campaigns","platform","dormant-pool"],"related":["wau","dau","mau","week-4-retention","email-click-rate"],"prose":{"why_it_matters":"Resurrected users are the lapsed people who came back, one of the three groups, with new and retained people, that make up weekly actives. A steady stream of returners means the product stays useful between bursts of use; a falling one, with steady sign-ups, means people who leave stay gone. At 6,500 a week, chance alone moves it by about 3.5%.","pitfalls":["Resurrection depends on the period. A weekly product's regulars skip a week now and then, so weekly resurrections include ordinary gaps; pick the period that matches how often the product is used.","A holiday or outage week inflates the next week's resurrections, because regulars who skipped it count as returning.","Identity changes that split one person into two ids turn regulars into new users, and merges turn new users into resurrected ones.","Win-back campaigns raise resurrections for a week. Judge them on how many of those people are still active a month later."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "returning-customers": { yaml: "id: returning-customers\nname: Returning customers\naliases:\n  - Repeat customers\n  - Returning buyers\n  - Repeat buyers\nfamily: customers\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: Customers who placed an order this week and had ordered at least once before, each counted once.\n  formula: Distinct customers with an order not flagged as their first, by order week\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: is_first_order\n        description: True when the store has no earlier order from this customer, from its own customer records.\n      - name: customer_id\n        description: The store's customer id, shared by guest and logged-in orders with the same email.\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n\nnumerator:\n  label: Customers with a repeat order\n  aggregate: unique_users\n  event: order_completed\n  where:\n    - property: is_first_order\n      op: eq\n      value: false\n\nnoise:\n  type: poisson\n  min_denominator: 30\n  volume_unit: returning customers a week\n  typical: 4700\n\nexample:\n  business: store\n  level: 4700\n  volume: 4700\n  trend: 0.2\n\ndrivers:\n  - id: identity\n    label: Customer matching\n    dropped:\n      check: Did logins, guest checkout or customer matching change, so returning buyers are now recorded as new?\n      yes: Returning customers fall, new customers rise by about the same number, and total orders hold.\n    spiked:\n      check: Did a customer merge or import link old guest orders to accounts?\n      yes: Returning customers jump on the day of the import with no matching rise in orders.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Was last week a sale or holiday week, or is this the lull after one?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this a sale, a holiday or a payday week that brings existing customers back?\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: email\n    label: Email and retention flows\n    metric: email-click-rate\n    dropped:\n      check: Did fewer campaign or flow emails go out, or start landing in spam?\n      yes: Emails delivered or clicks fall, and repeat orders from email fall on the same days.\n    spiked:\n      check: Did a campaign or a sale announcement go to the whole list?\n      yes: Repeat orders cluster in the two days after the send.\n  - id: stock\n    label: Bestsellers in stock\n    dropped:\n      check: Is a product that customers reorder out of stock or discontinued?\n      yes: Repeat orders containing that product fall to near zero while other repeat orders hold.\n    spiked:\n      check: Did a restock or a relaunch bring waiting customers back?\n      yes: Repeat orders jump in the week the product returned, many from back-in-stock emails.\n  - id: customer-base\n    label: Size of the customer base\n    metric: active-customers\n    dropped:\n      check: Is the base of recent buyers smaller than it was, after a weaker acquisition season?\n      yes: Active customers have been falling for weeks; this week continues a trend rather than starting one.\n    spiked:\n      check: Did a large wave of first-time buyers a few months ago start ordering again?\n      yes: The rise matches the size of cohorts won one to three months earlier, such as last Black Friday.\n\ndiagnose_order: [identity, calendar, email, stock, customer-base]\n\nrelated: [new-customers, repeat-order-share, repeat-purchase-rate, active-customers, purchase-frequency]\n\nprose:\n  why_it_matters: >-\n    Returning customers buy without a new acquisition cost, so each of their orders carries more\n    margin than a first order. At Northwind about 4,700 come back each week and place 38% of\n    orders. The count grows only when the customer base grows and keeps buying, which makes it the\n    plainest weekly read of retention a store has; a sudden drop usually traces to an email, a\n    stock-out or a customer-matching change, not to demand.\n  pitfalls:\n    - A customer whose first and second orders land in the same week counts once as new and once as returning, so new plus returning can exceed the week's customers by a few.\n    - When logins or customer matching break, returning buyers are recorded as new. Returning falls, new rises by the same number, and orders don't move.\n    - The count grows with the customer base. A rising count can hide a falling repeat rate in a growing store, so read repeat purchase rate next to it.\n    - Subscription renewals placed automatically are repeat orders too. Report them separately when they are a large share, or a billing-date cluster looks like loyalty.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"returning-customers","name":"Returning customers","aliases":["Repeat customers","Returning buyers","Repeat buyers"],"family":"customers","kind":"count","polarity":"up-is-good","definition":{"one_line":"Customers who placed an order this week and had ordered at least once before, each counted once.","formula":"Distinct customers with an order not flagged as their first, by order week"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"is_first_order","description":"True when the store has no earlier order from this customer, from its own customer records."},{"name":"customer_id","description":"The store's customer id, shared by guest and logged-in orders with the same email."},{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."}]}],"numerator":{"label":"Customers with a repeat order","aggregate":"unique_users","event":"order_completed","where":[{"property":"is_first_order","op":"eq","value":false}]},"noise":{"type":"poisson","min_denominator":30,"volume_unit":"returning customers a week","typical":4700},"example":{"business":"store","level":4700,"volume":4700,"trend":0.2},"drivers":[{"id":"identity","label":"Customer matching","dropped":{"check":"Did logins, guest checkout or customer matching change, so returning buyers are now recorded as new?","yes":"Returning customers fall, new customers rise by about the same number, and total orders hold."},"spiked":{"check":"Did a customer merge or import link old guest orders to accounts?","yes":"Returning customers jump on the day of the import with no matching rise in orders."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Was last week a sale or holiday week, or is this the lull after one?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this a sale, a holiday or a payday week that brings existing customers back?","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"email","label":"Email and retention flows","metric":"email-click-rate","dropped":{"check":"Did fewer campaign or flow emails go out, or start landing in spam?","yes":"Emails delivered or clicks fall, and repeat orders from email fall on the same days."},"spiked":{"check":"Did a campaign or a sale announcement go to the whole list?","yes":"Repeat orders cluster in the two days after the send."}},{"id":"stock","label":"Bestsellers in stock","dropped":{"check":"Is a product that customers reorder out of stock or discontinued?","yes":"Repeat orders containing that product fall to near zero while other repeat orders hold."},"spiked":{"check":"Did a restock or a relaunch bring waiting customers back?","yes":"Repeat orders jump in the week the product returned, many from back-in-stock emails."}},{"id":"customer-base","label":"Size of the customer base","metric":"active-customers","dropped":{"check":"Is the base of recent buyers smaller than it was, after a weaker acquisition season?","yes":"Active customers have been falling for weeks; this week continues a trend rather than starting one."},"spiked":{"check":"Did a large wave of first-time buyers a few months ago start ordering again?","yes":"The rise matches the size of cohorts won one to three months earlier, such as last Black Friday."}}],"diagnose_order":["identity","calendar","email","stock","customer-base"],"related":["new-customers","repeat-order-share","repeat-purchase-rate","active-customers","purchase-frequency"],"prose":{"why_it_matters":"Returning customers buy without a new acquisition cost, so each of their orders carries more margin than a first order. At Northwind about 4,700 come back each week and place 38% of orders. The count grows only when the customer base grows and keeps buying, which makes it the plainest weekly read of retention a store has; a sudden drop usually traces to an email, a stock-out or a customer-matching change, not to demand.","pitfalls":["A customer whose first and second orders land in the same week counts once as new and once as returning, so new plus returning can exceed the week's customers by a few.","When logins or customer matching break, returning buyers are recorded as new. Returning falls, new rises by the same number, and orders don't move.","The count grows with the customer base. A rising count can hide a falling repeat rate in a growing store, so read repeat purchase rate next to it.","Subscription renewals placed automatically are repeat orders too. Report them separately when they are a large share, or a billing-date cluster looks like loyalty."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "revenue-per-session": { yaml: "id: revenue-per-session\nname: Revenue per session\naliases:\n  - Revenue per visit\n  - RPS\n  - Session value\nfamily: revenue\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: Order revenue earned per session, the one number that combines conversion rate and order value.\n  formula: Order revenue after discounts ÷ sessions\n\nevents:\n  - name: $pageview\n    description: A page loaded in the browser. Sessions are the distinct session ids across page views.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: $session_id\n        description: The browser session; a new one starts after 30 minutes without activity.\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n\nnumerator:\n  label: Order revenue\n  aggregate: sum\n  event: order_completed\n  property: total\ndenominator:\n  label: Sessions\n  aggregate: unique_sessions\n  event: $pageview\n\nnoise:\n  type: mean\n  cv: 9\n  min_denominator: 2000\n  volume_unit: sessions a week\n  typical: 2\n  reference_volumes: [2000, 10000, 50000, 250000]\n\nexample:\n  business: store\n  level: 2.15\n  volume: 600000\n  trend: 0.1\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did orders stop recording, or did a new tag start splitting visits into extra sessions?\n      yes: Orders in the store platform hold while recorded orders fall, or sessions per visitor jump on one day.\n    spiked:\n      check: Did page views stop recording on some pages or browsers, or did orders start recording twice?\n      yes: Sessions fall with no matching fall in ad clicks, or the same order_id appears twice.\n  - id: calendar\n    label: Shopping calendar\n    feed: shopping\n    dropped:\n      check: Was last week a sale, holiday or payday week?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this a sale, holiday or payday week?\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: traffic-mix\n    label: Who arrived\n    breakdown: utm_source\n    dropped:\n      check: Did sessions grow from a low-intent source or from bots?\n      yes: Sessions jump from one source that earns a fraction of the rest per visit, while revenue barely moves.\n    spiked:\n      check: Did a low-intent source or a bot wave shrink, lifting revenue per session without more revenue?\n      yes: Sessions fall while revenue holds. Check total revenue before celebrating.\n  - id: conversion\n    label: Store conversion\n    metric: conversion-rate\n    dropped:\n      check: Did a smaller share of sessions buy?\n      yes: Conversion falls by about as much as revenue per session while order value holds.\n    spiked:\n      check: Did a larger share of sessions buy?\n      yes: Conversion rises by about as much as revenue per session while order value holds.\n  - id: order-value\n    label: Order value\n    metric: aov\n    dropped:\n      check: Did orders get smaller, from discounts, fewer items or cheaper products?\n      yes: Order value falls while conversion holds.\n    spiked:\n      check: Did orders get larger, or did a handful of very large orders land?\n      yes: Order value rises while conversion holds; check the largest orders first.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the drop on one device type only, or did mobile take a larger share of sessions?\n      yes: One device falls while the other holds, or each holds and only the mix moved.\n    spiked:\n      check: Is the rise on one device type only?\n      yes: One device rises after a release; confirm it isn't a tracking change before crediting it.\n\ndiagnose_order: [tracking, calendar, traffic-mix, conversion, order-value, device-split]\n\nrelated: [conversion-rate, aov, sessions, net-revenue, cpc]\n\nprose:\n  why_it_matters: >-\n    Revenue per session is what a visit is worth, so it is the number to set beside what a visit\n    costs. At Northwind a session earns about $2.15; at a 53% gross margin, a channel that pays\n    more than about $1.14 per session loses money on the first order. Because it multiplies\n    conversion by order value, it is also the fairest single number for tests that trade one\n    against the other.\n  pitfalls:\n    - Most sessions earn nothing and a few earn a lot, so the weekly figure swings with a handful of large orders. Below about 50,000 sessions a week, a 10% move is often chance.\n    - Revenue per visitor divides by people, not sessions, and reads higher because visitors make several sessions. Don't compare one with the other's benchmark.\n    - Bot sessions lower it without any change in shoppers. When it drops with revenue flat, check sessions by browser and country.\n    - This spec uses order revenue before refunds so it matches what the sessions produced. Subtracting refunds makes it move with returns from earlier weeks.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"revenue-per-session","name":"Revenue per session","aliases":["Revenue per visit","RPS","Session value"],"family":"revenue","kind":"currency","polarity":"up-is-good","definition":{"one_line":"Order revenue earned per session, the one number that combines conversion rate and order value.","formula":"Order revenue after discounts ÷ sessions"},"events":[{"name":"$pageview","description":"A page loaded in the browser. Sessions are the distinct session ids across page views.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"$session_id","description":"The browser session; a new one starts after 30 minutes without activity."}]},{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."}]}],"numerator":{"label":"Order revenue","aggregate":"sum","event":"order_completed","property":"total"},"denominator":{"label":"Sessions","aggregate":"unique_sessions","event":"$pageview"},"noise":{"type":"mean","cv":9,"min_denominator":2000,"volume_unit":"sessions a week","typical":2,"reference_volumes":[2000,10000,50000,250000]},"example":{"business":"store","level":2.15,"volume":600000,"trend":0.1,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did orders stop recording, or did a new tag start splitting visits into extra sessions?","yes":"Orders in the store platform hold while recorded orders fall, or sessions per visitor jump on one day."},"spiked":{"check":"Did page views stop recording on some pages or browsers, or did orders start recording twice?","yes":"Sessions fall with no matching fall in ad clicks, or the same order_id appears twice."}},{"id":"calendar","label":"Shopping calendar","feed":"shopping","dropped":{"check":"Was last week a sale, holiday or payday week?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this a sale, holiday or payday week?","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"traffic-mix","label":"Who arrived","breakdown":"utm_source","dropped":{"check":"Did sessions grow from a low-intent source or from bots?","yes":"Sessions jump from one source that earns a fraction of the rest per visit, while revenue barely moves."},"spiked":{"check":"Did a low-intent source or a bot wave shrink, lifting revenue per session without more revenue?","yes":"Sessions fall while revenue holds. Check total revenue before celebrating."}},{"id":"conversion","label":"Store conversion","metric":"conversion-rate","dropped":{"check":"Did a smaller share of sessions buy?","yes":"Conversion falls by about as much as revenue per session while order value holds."},"spiked":{"check":"Did a larger share of sessions buy?","yes":"Conversion rises by about as much as revenue per session while order value holds."}},{"id":"order-value","label":"Order value","metric":"aov","dropped":{"check":"Did orders get smaller, from discounts, fewer items or cheaper products?","yes":"Order value falls while conversion holds."},"spiked":{"check":"Did orders get larger, or did a handful of very large orders land?","yes":"Order value rises while conversion holds; check the largest orders first."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the drop on one device type only, or did mobile take a larger share of sessions?","yes":"One device falls while the other holds, or each holds and only the mix moved."},"spiked":{"check":"Is the rise on one device type only?","yes":"One device rises after a release; confirm it isn't a tracking change before crediting it."}}],"diagnose_order":["tracking","calendar","traffic-mix","conversion","order-value","device-split"],"related":["conversion-rate","aov","sessions","net-revenue","cpc"],"prose":{"why_it_matters":"Revenue per session is what a visit is worth, so it is the number to set beside what a visit costs. At Northwind a session earns about $2.15; at a 53% gross margin, a channel that pays more than about $1.14 per session loses money on the first order. Because it multiplies conversion by order value, it is also the fairest single number for tests that trade one against the other.","pitfalls":["Most sessions earn nothing and a few earn a lot, so the weekly figure swings with a handful of large orders. Below about 50,000 sessions a week, a 10% move is often chance.","Revenue per visitor divides by people, not sessions, and reads higher because visitors make several sessions. Don't compare one with the other's benchmark.","Bot sessions lower it without any change in shoppers. When it drops with revenue flat, check sessions by browser and country.","This spec uses order revenue before refunds so it matches what the sessions produced. Subtracting refunds makes it move with returns from earlier weeks."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "roas": { yaml: "id: roas\nname: Return on ad spend\naliases:\n  - Ad ROAS\n  - Paid ROAS\n  - Return on advertising spend\nfamily: acquisition\nkind: ratio\npolarity: up-is-good\n\ndefinition:\n  one_line: Revenue from orders placed in visits that arrived through a paid ad, for each dollar of ad spend in the same week.\n  formula: Order revenue from paid-ad sessions ÷ ad spend\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change; the session's first page view decides whether it came from an ad.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: utm_medium\n        description: The campaign medium from the landing URL. Paid when it contains \"cp\", starts with \"paid\", or is ppc, retargeting, display or banner.\n      - name: gclid\n        description: Google Ads click id from auto-tagging. Also gbraid, wbraid, and msclkid for Microsoft Ads.\n  - name: order_completed\n    description: A paid order confirmed by the server, carrying the session id of the visit it was placed in.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n      - name: $session_id\n        description: The visit the order was placed in, passed from the browser to the server event.\n  - name: ad_spend\n    description: One row per channel per day, synced from each ad platform's reporting API.\n    also_called: [Ad Spend, ad_performance, campaign_daily_stats]\n    properties:\n      - name: spend\n        description: Amount spent that day, in the store's reporting currency.\n\nnumerator:\n  label: Revenue from paid-ad sessions\n  aggregate: sum\n  event: order_completed\n  property: total\ndenominator:\n  label: Ad spend\n  aggregate: sum\n  event: ad_spend\n  property: spend\n\nqueries:\n  hogql: |-\n    -- ROAS per week: revenue from orders placed in sessions that arrived through a paid ad (paid utm_medium or ad click id on the first page view) ÷ ad spend, each by the week it happened. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(r.revenue, 0) AS numerator,\n      coalesce(a.spend, 0) AS denominator,\n      if(denominator = 0, NULL, numerator / denominator) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT toMonday(toTimeZone(timestamp, 'UTC')) AS week, sum(toFloat(properties.spend)) AS spend\n      FROM events\n      WHERE event = 'ad_spend'\n        AND timestamp >= now() - toIntervalWeek(27)\n        AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n      GROUP BY week\n    ) AS a ON a.week = w.week\n    LEFT JOIN (\n      SELECT toMonday(o.ts) AS week, sum(o.total) AS revenue\n      FROM (\n        SELECT $session_id AS session_id, toTimeZone(timestamp, 'UTC') AS ts, toFloat(properties.total) AS total\n        FROM events\n        WHERE event = 'order_completed'\n          AND $session_id != ''\n          AND timestamp >= now() - toIntervalWeek(27)\n          AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n      ) AS o\n      INNER JOIN (\n        SELECT\n          $session_id AS session_id,\n          argMin(lower(coalesce(properties.utm_medium, '')), timestamp) AS medium,\n          argMin(coalesce(properties.gclid, properties.gbraid, properties.wbraid, properties.msclkid, '') <> '', timestamp) AS ad_click\n        FROM events\n        WHERE event = '$pageview'\n          AND $session_id != ''\n          AND timestamp >= now() - toIntervalWeek(27)\n          AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n        GROUP BY session_id\n      ) AS e ON e.session_id = o.session_id\n      WHERE (match(e.medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR e.ad_click)\n      GROUP BY week\n    ) AS r ON r.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- ROAS per week: revenue from orders placed in sessions that arrived through a paid ad (paid utm_medium or ad click id on the first page view) ÷ ad spend, each by the week it happened. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    spend AS (\n      SELECT date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week, sum(CASE WHEN properties->>'spend' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'spend')::numeric END) AS spend\n      FROM events\n      WHERE event_name = 'ad_spend'\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n      GROUP BY 1\n    ),\n    entries AS (\n      SELECT DISTINCT ON (session_id)\n        session_id,\n        lower(coalesce(properties->>'utm_medium', '')) AS medium,\n        coalesce(properties->>'gclid', properties->>'gbraid', properties->>'wbraid', properties->>'msclkid', '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id <> ''\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n      ORDER BY session_id, occurred_at\n    ),\n    paid_revenue AS (\n      SELECT date_trunc('week', o.occurred_at AT TIME ZONE 'UTC')::date AS week, sum(CASE WHEN o.properties->>'total' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (o.properties->>'total')::numeric END) AS revenue\n      FROM events AS o\n      JOIN entries AS e ON e.session_id = o.session_id\n      WHERE o.event_name = 'order_completed'\n        AND o.occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n        AND o.occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n        AND (e.medium ~ '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$' OR e.ad_click)\n      GROUP BY 1\n    ),\n    totals AS (\n      SELECT w.week, coalesce(p.revenue, 0) AS numerator, coalesce(s.spend, 0) AS denominator\n      FROM weeks AS w\n      LEFT JOIN spend AS s ON s.week = w.week\n      LEFT JOIN paid_revenue AS p ON p.week = w.week\n    )\n    SELECT week, numerator, denominator, numerator / nullif(denominator, 0) AS value\n    FROM totals\n    ORDER BY week;\n  bigquery: |-\n    -- ROAS per week: revenue from orders placed in sessions that arrived through a paid ad (paid utm_medium or ad click id on the first page view) ÷ ad spend, each by the week it happened. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    spend AS (\n      SELECT DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week, SUM(SAFE_CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64)) AS spend\n      FROM events\n      WHERE event_name = 'ad_spend'\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY week\n    ),\n    entries AS (\n      SELECT\n        session_id,\n        LOWER(COALESCE(JSON_VALUE(properties, '$.utm_medium'), '')) AS medium,\n        COALESCE(JSON_VALUE(properties, '$.gclid'), JSON_VALUE(properties, '$.gbraid'), JSON_VALUE(properties, '$.wbraid'), JSON_VALUE(properties, '$.msclkid'), '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id <> ''\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n    ),\n    paid_revenue AS (\n      SELECT DATE_TRUNC(DATE(o.occurred_at), ISOWEEK) AS week, SUM(SAFE_CAST(JSON_VALUE(o.properties, '$.total') AS FLOAT64)) AS revenue\n      FROM events AS o\n      JOIN entries AS e ON e.session_id = o.session_id\n      WHERE o.event_name = 'order_completed'\n        AND o.occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND o.occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n        AND (REGEXP_CONTAINS(e.medium, r'^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR e.ad_click)\n      GROUP BY week\n    ),\n    totals AS (\n      SELECT w.week, COALESCE(p.revenue, 0) AS numerator, COALESCE(s.spend, 0) AS denominator\n      FROM weeks AS w\n      LEFT JOIN spend AS s ON s.week = w.week\n      LEFT JOIN paid_revenue AS p ON p.week = w.week\n    )\n    SELECT week, numerator, denominator, SAFE_DIVIDE(numerator, denominator) AS value\n    FROM totals\n    ORDER BY week;\n  snowflake: |-\n    -- ROAS per week: revenue from orders placed in sessions that arrived through a paid ad (paid utm_medium or ad click id on the first page view) ÷ ad spend, each by the week it happened. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    spend AS (\n      SELECT DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week, SUM(TRY_TO_DOUBLE(properties:\"spend\"::string)) AS spend\n      FROM events\n      WHERE event_name = 'ad_spend'\n        AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n      GROUP BY 1\n    ),\n    entries AS (\n      SELECT\n        session_id,\n        LOWER(COALESCE(properties:\"utm_medium\"::string, '')) AS medium,\n        COALESCE(properties:\"gclid\"::string, properties:\"gbraid\"::string, properties:\"wbraid\"::string, properties:\"msclkid\"::string, '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id <> ''\n        AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n    ),\n    paid_revenue AS (\n      SELECT DATEADD(day, 1 - DAYOFWEEKISO(o.occurred_at), o.occurred_at::date) AS week, SUM(TRY_TO_DOUBLE(o.properties:\"total\"::string)) AS revenue\n      FROM events AS o\n      JOIN entries AS e ON e.session_id = o.session_id\n      WHERE o.event_name = 'order_completed'\n        AND o.occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND o.occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n        AND (REGEXP_LIKE(e.medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR e.ad_click)\n      GROUP BY 1\n    ),\n    totals AS (\n      SELECT w.week, COALESCE(p.revenue, 0) AS numerator, COALESCE(s.spend, 0) AS denominator\n      FROM weeks AS w\n      LEFT JOIN spend AS s ON s.week = w.week\n      LEFT JOIN paid_revenue AS p ON p.week = w.week\n    )\n    SELECT week, numerator, denominator, numerator / NULLIF(denominator, 0) AS value\n    FROM totals\n    ORDER BY week;\n\nnoise:\n  type: process\n  min_denominator: 50\n  volume_unit: orders from paid sessions a week\n  typical: 2\n\nexample:\n  business: store\n  level: 1.2\n  volume: 3800\n  trend: -0.05\n\ndrivers:\n  - id: attribution\n    label: Tracking and attribution\n    dropped:\n      check: Did orders stop carrying the session id, or did a redirect strip campaign tags, so paid orders look unpaid?\n      yes: Total orders hold while orders matched to paid sessions fall, from the day of a checkout or redirect change.\n    spiked:\n      check: Did untagged traffic start counting as paid, or are orders recorded twice?\n      yes: Paid revenue rises with no rise in paid sessions, or order count exceeds the store admin's.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Did a sale end while budgets stayed high?\n      yes: The same weeks last year show the same fall in return after the event.\n    spiked:\n      check: Is a sale or holiday turning the same clicks into more orders?\n      yes: Paid conversion jumps for the event week and the same week last year shows it too.\n  - id: spend\n    label: Ad spend\n    metric: ad-spend\n    feed: ad-platforms\n    dropped:\n      check: Did spend rise faster than results, from a budget increase or a new prospecting campaign?\n      yes: Spend rises while paid revenue grows less; returns usually fall as budgets scale.\n    spiked:\n      check: Did spend fall, cutting the least efficient campaigns first?\n      yes: Spend falls more than paid revenue does.\n  - id: click-cost\n    label: Cost per click\n    metric: cpc\n    dropped:\n      check: Did each click get more expensive?\n      yes: CPC rises by about as much as ROAS falls, while paid conversion and order value hold.\n    spiked:\n      check: Did clicks get cheaper?\n      yes: CPC falls by about as much as ROAS rises, while paid conversion and order value hold.\n  - id: paid-conversion\n    label: Paid conversion rate\n    metric: paid-conversion-rate\n    dropped:\n      check: Did fewer paid visits order, from a landing page, stock or checkout problem?\n      yes: Paid conversion falls while CPC and order value hold.\n    spiked:\n      check: Did more paid visits order, from a better landing page or offer?\n      yes: Paid conversion rises while CPC and order value hold.\n  - id: order-value\n    label: Order value\n    metric: aov\n    dropped:\n      check: Did paid orders get smaller, from a discount or a cheaper hero product?\n      yes: Order value from paid sessions falls while the number of paid orders holds.\n    spiked:\n      check: Did paid orders get bigger, from a bundle, a price rise or a few large orders?\n      yes: Order value from paid sessions rises while the number of paid orders holds.\n\ndiagnose_order: [attribution, calendar, spend, click-cost, paid-conversion, order-value]\n\nrelated: [mer, ad-spend, paid-conversion-rate, cpc, ncac, aov]\n\nprose:\n  why_it_matters: >-\n    ROAS says whether the ads pay for themselves, and splits into three numbers that each point\n    at a different team: paid conversion rate × order value ÷ spend per paid session, where spend\n    per paid session is cost per click raised by the clicks that never arrive as a session. At\n    Northwind, 2.1% of paid sessions order at about $97 and each costs about $1.67 of spend, so ROAS\n    is about 1.2: $1.20 of session-attributed revenue per ad dollar. Whether that pays depends on\n    margin: break-even ROAS is 1 ÷ gross margin, about 1.9 at Northwind's 53%.\n  pitfalls:\n    - Platform ROAS is not this number. Meta and Google count view-through and modeled conversions and each claim the same order, so the platforms' sum usually runs well above what the store can match to an ad visit.\n    - Session-attributed ROAS undercounts ads that work slowly. A shopper who clicks an ad, leaves, and buys from a bookmark two days later counts as direct here; read MER alongside it.\n    - High ROAS can mean too little spend. Retargeting and branded search show the best returns because they reach people who would have bought anyway.\n    - Orders must carry the browser's session id for this query to match them to a visit. Server-side orders without it count as unpaid.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"roas","name":"Return on ad spend","aliases":["Ad ROAS","Paid ROAS","Return on advertising spend"],"family":"acquisition","kind":"ratio","polarity":"up-is-good","definition":{"one_line":"Revenue from orders placed in visits that arrived through a paid ad, for each dollar of ad spend in the same week.","formula":"Order revenue from paid-ad sessions ÷ ad spend"},"events":[{"name":"$pageview","description":"One page load or client-side route change; the session's first page view decides whether it came from an ad.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"utm_medium","description":"The campaign medium from the landing URL. Paid when it contains \"cp\", starts with \"paid\", or is ppc, retargeting, display or banner."},{"name":"gclid","description":"Google Ads click id from auto-tagging. Also gbraid, wbraid, and msclkid for Microsoft Ads."}]},{"name":"order_completed","description":"A paid order confirmed by the server, carrying the session id of the visit it was placed in.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."},{"name":"$session_id","description":"The visit the order was placed in, passed from the browser to the server event."}]},{"name":"ad_spend","description":"One row per channel per day, synced from each ad platform's reporting API.","also_called":["Ad Spend","ad_performance","campaign_daily_stats"],"properties":[{"name":"spend","description":"Amount spent that day, in the store's reporting currency."}]}],"numerator":{"label":"Revenue from paid-ad sessions","aggregate":"sum","event":"order_completed","property":"total"},"denominator":{"label":"Ad spend","aggregate":"sum","event":"ad_spend","property":"spend"},"queries":{"hogql":"-- ROAS per week: revenue from orders placed in sessions that arrived through a paid ad (paid utm_medium or ad click id on the first page view) ÷ ad spend, each by the week it happened. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(r.revenue, 0) AS numerator,\n  coalesce(a.spend, 0) AS denominator,\n  if(denominator = 0, NULL, numerator / denominator) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT toMonday(toTimeZone(timestamp, 'UTC')) AS week, sum(toFloat(properties.spend)) AS spend\n  FROM events\n  WHERE event = 'ad_spend'\n    AND timestamp >= now() - toIntervalWeek(27)\n    AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n  GROUP BY week\n) AS a ON a.week = w.week\nLEFT JOIN (\n  SELECT toMonday(o.ts) AS week, sum(o.total) AS revenue\n  FROM (\n    SELECT $session_id AS session_id, toTimeZone(timestamp, 'UTC') AS ts, toFloat(properties.total) AS total\n    FROM events\n    WHERE event = 'order_completed'\n      AND $session_id != ''\n      AND timestamp >= now() - toIntervalWeek(27)\n      AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n  ) AS o\n  INNER JOIN (\n    SELECT\n      $session_id AS session_id,\n      argMin(lower(coalesce(properties.utm_medium, '')), timestamp) AS medium,\n      argMin(coalesce(properties.gclid, properties.gbraid, properties.wbraid, properties.msclkid, '') <> '', timestamp) AS ad_click\n    FROM events\n    WHERE event = '$pageview'\n      AND $session_id != ''\n      AND timestamp >= now() - toIntervalWeek(27)\n      AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n    GROUP BY session_id\n  ) AS e ON e.session_id = o.session_id\n  WHERE (match(e.medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR e.ad_click)\n  GROUP BY week\n) AS r ON r.week = w.week\nORDER BY week","postgres":"-- ROAS per week: revenue from orders placed in sessions that arrived through a paid ad (paid utm_medium or ad click id on the first page view) ÷ ad spend, each by the week it happened. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nspend AS (\n  SELECT date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS week, sum(CASE WHEN properties->>'spend' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (properties->>'spend')::numeric END) AS spend\n  FROM events\n  WHERE event_name = 'ad_spend'\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n  GROUP BY 1\n),\nentries AS (\n  SELECT DISTINCT ON (session_id)\n    session_id,\n    lower(coalesce(properties->>'utm_medium', '')) AS medium,\n    coalesce(properties->>'gclid', properties->>'gbraid', properties->>'wbraid', properties->>'msclkid', '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id <> ''\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n  ORDER BY session_id, occurred_at\n),\npaid_revenue AS (\n  SELECT date_trunc('week', o.occurred_at AT TIME ZONE 'UTC')::date AS week, sum(CASE WHEN o.properties->>'total' ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN (o.properties->>'total')::numeric END) AS revenue\n  FROM events AS o\n  JOIN entries AS e ON e.session_id = o.session_id\n  WHERE o.event_name = 'order_completed'\n    AND o.occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n    AND o.occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n    AND (e.medium ~ '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$' OR e.ad_click)\n  GROUP BY 1\n),\ntotals AS (\n  SELECT w.week, coalesce(p.revenue, 0) AS numerator, coalesce(s.spend, 0) AS denominator\n  FROM weeks AS w\n  LEFT JOIN spend AS s ON s.week = w.week\n  LEFT JOIN paid_revenue AS p ON p.week = w.week\n)\nSELECT week, numerator, denominator, numerator / nullif(denominator, 0) AS value\nFROM totals\nORDER BY week;","bigquery":"-- ROAS per week: revenue from orders placed in sessions that arrived through a paid ad (paid utm_medium or ad click id on the first page view) ÷ ad spend, each by the week it happened. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nspend AS (\n  SELECT DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week, SUM(SAFE_CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64)) AS spend\n  FROM events\n  WHERE event_name = 'ad_spend'\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY week\n),\nentries AS (\n  SELECT\n    session_id,\n    LOWER(COALESCE(JSON_VALUE(properties, '$.utm_medium'), '')) AS medium,\n    COALESCE(JSON_VALUE(properties, '$.gclid'), JSON_VALUE(properties, '$.gbraid'), JSON_VALUE(properties, '$.wbraid'), JSON_VALUE(properties, '$.msclkid'), '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id <> ''\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n),\npaid_revenue AS (\n  SELECT DATE_TRUNC(DATE(o.occurred_at), ISOWEEK) AS week, SUM(SAFE_CAST(JSON_VALUE(o.properties, '$.total') AS FLOAT64)) AS revenue\n  FROM events AS o\n  JOIN entries AS e ON e.session_id = o.session_id\n  WHERE o.event_name = 'order_completed'\n    AND o.occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND o.occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    AND (REGEXP_CONTAINS(e.medium, r'^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR e.ad_click)\n  GROUP BY week\n),\ntotals AS (\n  SELECT w.week, COALESCE(p.revenue, 0) AS numerator, COALESCE(s.spend, 0) AS denominator\n  FROM weeks AS w\n  LEFT JOIN spend AS s ON s.week = w.week\n  LEFT JOIN paid_revenue AS p ON p.week = w.week\n)\nSELECT week, numerator, denominator, SAFE_DIVIDE(numerator, denominator) AS value\nFROM totals\nORDER BY week;","snowflake":"-- ROAS per week: revenue from orders placed in sessions that arrived through a paid ad (paid utm_medium or ad click id on the first page view) ÷ ad spend, each by the week it happened. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nspend AS (\n  SELECT DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS week, SUM(TRY_TO_DOUBLE(properties:\"spend\"::string)) AS spend\n  FROM events\n  WHERE event_name = 'ad_spend'\n    AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n  GROUP BY 1\n),\nentries AS (\n  SELECT\n    session_id,\n    LOWER(COALESCE(properties:\"utm_medium\"::string, '')) AS medium,\n    COALESCE(properties:\"gclid\"::string, properties:\"gbraid\"::string, properties:\"wbraid\"::string, properties:\"msclkid\"::string, '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id <> ''\n    AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n),\npaid_revenue AS (\n  SELECT DATEADD(day, 1 - DAYOFWEEKISO(o.occurred_at), o.occurred_at::date) AS week, SUM(TRY_TO_DOUBLE(o.properties:\"total\"::string)) AS revenue\n  FROM events AS o\n  JOIN entries AS e ON e.session_id = o.session_id\n  WHERE o.event_name = 'order_completed'\n    AND o.occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND o.occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n    AND (REGEXP_LIKE(e.medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR e.ad_click)\n  GROUP BY 1\n),\ntotals AS (\n  SELECT w.week, COALESCE(p.revenue, 0) AS numerator, COALESCE(s.spend, 0) AS denominator\n  FROM weeks AS w\n  LEFT JOIN spend AS s ON s.week = w.week\n  LEFT JOIN paid_revenue AS p ON p.week = w.week\n)\nSELECT week, numerator, denominator, numerator / NULLIF(denominator, 0) AS value\nFROM totals\nORDER BY week;"},"noise":{"type":"process","min_denominator":50,"volume_unit":"orders from paid sessions a week","typical":2},"example":{"business":"store","level":1.2,"volume":3800,"trend":-0.05},"drivers":[{"id":"attribution","label":"Tracking and attribution","dropped":{"check":"Did orders stop carrying the session id, or did a redirect strip campaign tags, so paid orders look unpaid?","yes":"Total orders hold while orders matched to paid sessions fall, from the day of a checkout or redirect change."},"spiked":{"check":"Did untagged traffic start counting as paid, or are orders recorded twice?","yes":"Paid revenue rises with no rise in paid sessions, or order count exceeds the store admin's."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Did a sale end while budgets stayed high?","yes":"The same weeks last year show the same fall in return after the event."},"spiked":{"check":"Is a sale or holiday turning the same clicks into more orders?","yes":"Paid conversion jumps for the event week and the same week last year shows it too."}},{"id":"spend","label":"Ad spend","metric":"ad-spend","feed":"ad-platforms","dropped":{"check":"Did spend rise faster than results, from a budget increase or a new prospecting campaign?","yes":"Spend rises while paid revenue grows less; returns usually fall as budgets scale."},"spiked":{"check":"Did spend fall, cutting the least efficient campaigns first?","yes":"Spend falls more than paid revenue does."}},{"id":"click-cost","label":"Cost per click","metric":"cpc","dropped":{"check":"Did each click get more expensive?","yes":"CPC rises by about as much as ROAS falls, while paid conversion and order value hold."},"spiked":{"check":"Did clicks get cheaper?","yes":"CPC falls by about as much as ROAS rises, while paid conversion and order value hold."}},{"id":"paid-conversion","label":"Paid conversion rate","metric":"paid-conversion-rate","dropped":{"check":"Did fewer paid visits order, from a landing page, stock or checkout problem?","yes":"Paid conversion falls while CPC and order value hold."},"spiked":{"check":"Did more paid visits order, from a better landing page or offer?","yes":"Paid conversion rises while CPC and order value hold."}},{"id":"order-value","label":"Order value","metric":"aov","dropped":{"check":"Did paid orders get smaller, from a discount or a cheaper hero product?","yes":"Order value from paid sessions falls while the number of paid orders holds."},"spiked":{"check":"Did paid orders get bigger, from a bundle, a price rise or a few large orders?","yes":"Order value from paid sessions rises while the number of paid orders holds."}}],"diagnose_order":["attribution","calendar","spend","click-cost","paid-conversion","order-value"],"related":["mer","ad-spend","paid-conversion-rate","cpc","ncac","aov"],"prose":{"why_it_matters":"ROAS says whether the ads pay for themselves, and splits into three numbers that each point at a different team: paid conversion rate × order value ÷ spend per paid session, where spend per paid session is cost per click raised by the clicks that never arrive as a session. At Northwind, 2.1% of paid sessions order at about $97 and each costs about $1.67 of spend, so ROAS is about 1.2: $1.20 of session-attributed revenue per ad dollar. Whether that pays depends on margin: break-even ROAS is 1 ÷ gross margin, about 1.9 at Northwind's 53%.","pitfalls":["Platform ROAS is not this number. Meta and Google count view-through and modeled conversions and each claim the same order, so the platforms' sum usually runs well above what the store can match to an ad visit.","Session-attributed ROAS undercounts ads that work slowly. A shopper who clicks an ad, leaves, and buys from a bookmark two days later counts as direct here; read MER alongside it.","High ROAS can mean too little spend. Retargeting and branded search show the best returns because they reach people who would have bought anyway.","Orders must carry the browser's session id for this query to match them to a visit. Server-side orders without it count as unpaid."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "search-conversion-rate": { yaml: "id: search-conversion-rate\nname: Search conversion rate\naliases:\n  - Site search conversion rate\n  - Search to purchase rate\n  - Search conversion\nfamily: conversion\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of sessions that used site search and then placed a paid order in the same session.\n  formula: Sessions that searched, then ordered ÷ sessions that searched\n\nevents:\n  - name: product_searched\n    description: A search submitted in the store's search box, or its results page shown, once per search.\n    also_called: [search, view_search_results, Products Searched, search_submitted]\n    properties:\n      - name: query\n        description: What the shopper typed, as submitted.\n      - name: results_count\n        description: How many products the search returned; 0 is a dead end.\n  - name: order_completed\n    description: A paid order confirmed by the server, carrying the browser's session id.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n\nnumerator:\n  label: Sessions that searched, then ordered\n  aggregate: unique_sessions\n  event: order_completed\ndenominator:\n  label: Sessions that searched\n  aggregate: unique_sessions\n  event: product_searched\n\nqueries:\n  hogql: |-\n    -- Search conversion rate per week: sessions that searched, then placed an order ÷ sessions that searched. Each session counts in the week of its first search. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(s.converted, 0) AS numerator,\n      coalesce(s.sessions, 0) AS denominator,\n      if(coalesce(s.sessions, 0) = 0, NULL, s.converted / s.sessions) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT\n        toMonday(toTimeZone(x.searched_at, 'UTC')) AS week,\n        countIf(x.order_count > 0 AND x.ordered_at >= x.searched_at) AS converted,\n        count() AS sessions\n      FROM (\n        SELECT\n          $session_id AS session_id,\n          minIf(timestamp, event = 'product_searched') AS searched_at,\n          maxIf(timestamp, event = 'order_completed') AS ordered_at,\n          countIf(event = 'order_completed') AS order_count\n        FROM events\n        WHERE event IN ('product_searched', 'order_completed')\n          AND $session_id != ''\n          AND timestamp >= now() - toIntervalWeek(27)\n          AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n        GROUP BY session_id\n        HAVING countIf(event = 'product_searched') > 0\n      ) AS x\n      GROUP BY week\n    ) AS s ON s.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Search conversion rate per week: sessions that searched, then placed an order ÷ sessions that searched. Each session counts in the week of its first search. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    searches AS (\n      SELECT\n        session_id,\n        min(occurred_at) FILTER (WHERE event_name = 'product_searched') AS searched_at,\n        max(occurred_at) FILTER (WHERE event_name = 'order_completed') AS ordered_at\n      FROM events\n      WHERE event_name IN ('product_searched', 'order_completed')\n        AND session_id <> ''\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n      GROUP BY session_id\n    ),\n    weekly AS (\n      SELECT\n        date_trunc('week', searched_at AT TIME ZONE 'UTC')::date AS week,\n        count(*) FILTER (WHERE ordered_at >= searched_at) AS converted,\n        count(*) AS sessions\n      FROM searches\n      WHERE searched_at IS NOT NULL\n      GROUP BY 1\n    )\n    SELECT\n      w.week,\n      coalesce(s.converted, 0) AS numerator,\n      coalesce(s.sessions, 0) AS denominator,\n      s.converted::numeric / nullif(s.sessions, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS s ON s.week = w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Search conversion rate per week: sessions that searched, then placed an order ÷ sessions that searched. Each session counts in the week of its first search. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    searches AS (\n      SELECT\n        session_id,\n        MIN(IF(event_name = 'product_searched', occurred_at, NULL)) AS searched_at,\n        MAX(IF(event_name = 'order_completed', occurred_at, NULL)) AS ordered_at\n      FROM events\n      WHERE event_name IN ('product_searched', 'order_completed')\n        AND session_id <> ''\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY session_id\n    ),\n    weekly AS (\n      SELECT\n        DATE_TRUNC(DATE(searched_at), ISOWEEK) AS week,\n        COUNTIF(ordered_at >= searched_at) AS converted,\n        COUNT(*) AS sessions\n      FROM searches\n      WHERE searched_at IS NOT NULL\n      GROUP BY week\n    )\n    SELECT\n      w.week,\n      COALESCE(s.converted, 0) AS numerator,\n      COALESCE(s.sessions, 0) AS denominator,\n      SAFE_DIVIDE(s.converted, s.sessions) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS s ON s.week = w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Search conversion rate per week: sessions that searched, then placed an order ÷ sessions that searched. Each session counts in the week of its first search. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    searches AS (\n      SELECT\n        session_id,\n        MIN(IFF(event_name = 'product_searched', occurred_at, NULL)) AS searched_at,\n        MAX(IFF(event_name = 'order_completed', occurred_at, NULL)) AS ordered_at\n      FROM events\n      WHERE event_name IN ('product_searched', 'order_completed')\n        AND session_id <> ''\n        AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n      GROUP BY session_id\n    ),\n    weekly AS (\n      SELECT\n        DATEADD(day, 1 - DAYOFWEEKISO(searched_at), searched_at::date) AS week,\n        COUNT_IF(ordered_at >= searched_at) AS converted,\n        COUNT(*) AS sessions\n      FROM searches\n      WHERE searched_at IS NOT NULL\n      GROUP BY 1\n    )\n    SELECT\n      w.week,\n      COALESCE(s.converted, 0) AS numerator,\n      COALESCE(s.sessions, 0) AS denominator,\n      s.converted::float / NULLIF(s.sessions, 0) AS value\n    FROM weeks AS w\n    LEFT JOIN weekly AS s ON s.week = w.week\n    ORDER BY w.week;\n\nnoise:\n  type: binomial\n  min_denominator: 500\n  volume_unit: sessions with a search a week\n  typical: 0.05\n  reference_volumes: [500, 2000, 10000, 50000]\n\nexample:\n  business: store\n  level: 0.052\n  volume: 66000\n  trend: 0.03\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a search app or theme change start firing product_searched on autocomplete keystrokes?\n      yes: Sessions with a search jump on the release day, many with a one- or two-letter query and nothing after it.\n    spiked:\n      check: Did product_searched stop firing on some pages or devices, leaving only the most determined searchers?\n      yes: Sessions with a search fall on one device or template while search orders hold.\n  - id: store-wide\n    label: The whole store\n    metric: conversion-rate\n    dropped:\n      check: Did conversion fall for everyone, not only for searchers?\n      yes: Search conversion and store conversion fall together, so the cause is checkout, price or the calendar, not search.\n    spiked:\n      check: Did conversion rise for everyone, from a sale or a fix elsewhere?\n      yes: Search conversion and store conversion rise together, so search itself didn't change.\n  - id: zero-results\n    label: Searches with no results\n    dropped:\n      check: Did more searches return nothing, from a catalogue change, lost synonyms or a trending term you don't stock?\n      yes: The share of searches with results_count of 0 rises, concentrated in a few queries.\n    spiked:\n      check: Did a synonym, spelling or catalogue fix cut dead-end searches?\n      yes: Zero-result searches fall from the day of the fix, on the queries it covered.\n  - id: stock\n    label: Stock of searched products\n    dropped:\n      check: Are the products people search for most out of stock or missing common sizes?\n      yes: Top queries still return results, but their first results are sold out.\n    spiked:\n      check: Did a much-searched product come back in stock or launch?\n      yes: Orders after searching for that product's name jump from the restock or launch day.\n  - id: relevance\n    label: Ranking and relevance\n    dropped:\n      check: Did a search app update, re-index or merchandising rule push irrelevant or sold-out products to the top?\n      yes: Clicks on the first results fall for the top queries from the day of the change.\n    spiked:\n      check: Did a relevance change or test ship, and is it on for everyone?\n      yes: The rise starts on the release day across devices and queries.\n  - id: who-searches\n    label: Who searches\n    breakdown: $device_type\n    dropped:\n      check: Did the search box become more prominent, so more casual browsers search?\n      yes: Sessions with a search grow faster than orders after searching; search-driven orders still rise.\n    spiked:\n      check: Did the search box move or shrink, leaving fewer but more committed searchers?\n      yes: Sessions with a search fall while orders after searching hold.\n\ndiagnose_order: [tracking, store-wide, zero-results, stock, relevance, who-searches]\n\nrelated: [conversion-rate, product-view-rate, add-to-cart-rate, revenue-per-session]\n\nprose:\n  why_it_matters: >-\n    Shoppers who search say what they want in their own words, and they usually convert well\n    above the store average; at Northwind, 5.2% against 2.1%. A fall here is usually something\n    the team controls, such as a search app update, lost synonyms or empty results for the\n    words people actually type.\n  pitfalls:\n    - Searchers are more committed than average, so a high search conversion doesn't prove search works. Compare search conversion with itself over time, not with the store rate.\n    - Predictive search that fires the event on each keystroke counts sessions that never submitted a search. Fire product_searched on submit or on the results view.\n    - This spec credits search only when the order follows in the same session. A shopper who searches today and buys tomorrow counts as a search that didn't convert.\n    - Zero-result searches are the fastest thing to check. A catalogue, synonym or search app change shows up there on the day it ships, often before orders tell you.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"search-conversion-rate","name":"Search conversion rate","aliases":["Site search conversion rate","Search to purchase rate","Search conversion"],"family":"conversion","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of sessions that used site search and then placed a paid order in the same session.","formula":"Sessions that searched, then ordered ÷ sessions that searched"},"events":[{"name":"product_searched","description":"A search submitted in the store's search box, or its results page shown, once per search.","also_called":["search","view_search_results","Products Searched","search_submitted"],"properties":[{"name":"query","description":"What the shopper typed, as submitted."},{"name":"results_count","description":"How many products the search returned; 0 is a dead end."}]},{"name":"order_completed","description":"A paid order confirmed by the server, carrying the browser's session id.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."}]}],"numerator":{"label":"Sessions that searched, then ordered","aggregate":"unique_sessions","event":"order_completed"},"denominator":{"label":"Sessions that searched","aggregate":"unique_sessions","event":"product_searched"},"queries":{"hogql":"-- Search conversion rate per week: sessions that searched, then placed an order ÷ sessions that searched. Each session counts in the week of its first search. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(s.converted, 0) AS numerator,\n  coalesce(s.sessions, 0) AS denominator,\n  if(coalesce(s.sessions, 0) = 0, NULL, s.converted / s.sessions) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT\n    toMonday(toTimeZone(x.searched_at, 'UTC')) AS week,\n    countIf(x.order_count > 0 AND x.ordered_at >= x.searched_at) AS converted,\n    count() AS sessions\n  FROM (\n    SELECT\n      $session_id AS session_id,\n      minIf(timestamp, event = 'product_searched') AS searched_at,\n      maxIf(timestamp, event = 'order_completed') AS ordered_at,\n      countIf(event = 'order_completed') AS order_count\n    FROM events\n    WHERE event IN ('product_searched', 'order_completed')\n      AND $session_id != ''\n      AND timestamp >= now() - toIntervalWeek(27)\n      AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n    GROUP BY session_id\n    HAVING countIf(event = 'product_searched') > 0\n  ) AS x\n  GROUP BY week\n) AS s ON s.week = w.week\nORDER BY week","postgres":"-- Search conversion rate per week: sessions that searched, then placed an order ÷ sessions that searched. Each session counts in the week of its first search. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nsearches AS (\n  SELECT\n    session_id,\n    min(occurred_at) FILTER (WHERE event_name = 'product_searched') AS searched_at,\n    max(occurred_at) FILTER (WHERE event_name = 'order_completed') AS ordered_at\n  FROM events\n  WHERE event_name IN ('product_searched', 'order_completed')\n    AND session_id <> ''\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n  GROUP BY session_id\n),\nweekly AS (\n  SELECT\n    date_trunc('week', searched_at AT TIME ZONE 'UTC')::date AS week,\n    count(*) FILTER (WHERE ordered_at >= searched_at) AS converted,\n    count(*) AS sessions\n  FROM searches\n  WHERE searched_at IS NOT NULL\n  GROUP BY 1\n)\nSELECT\n  w.week,\n  coalesce(s.converted, 0) AS numerator,\n  coalesce(s.sessions, 0) AS denominator,\n  s.converted::numeric / nullif(s.sessions, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS s ON s.week = w.week\nORDER BY w.week;","bigquery":"-- Search conversion rate per week: sessions that searched, then placed an order ÷ sessions that searched. Each session counts in the week of its first search. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nsearches AS (\n  SELECT\n    session_id,\n    MIN(IF(event_name = 'product_searched', occurred_at, NULL)) AS searched_at,\n    MAX(IF(event_name = 'order_completed', occurred_at, NULL)) AS ordered_at\n  FROM events\n  WHERE event_name IN ('product_searched', 'order_completed')\n    AND session_id <> ''\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY session_id\n),\nweekly AS (\n  SELECT\n    DATE_TRUNC(DATE(searched_at), ISOWEEK) AS week,\n    COUNTIF(ordered_at >= searched_at) AS converted,\n    COUNT(*) AS sessions\n  FROM searches\n  WHERE searched_at IS NOT NULL\n  GROUP BY week\n)\nSELECT\n  w.week,\n  COALESCE(s.converted, 0) AS numerator,\n  COALESCE(s.sessions, 0) AS denominator,\n  SAFE_DIVIDE(s.converted, s.sessions) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS s ON s.week = w.week\nORDER BY w.week;","snowflake":"-- Search conversion rate per week: sessions that searched, then placed an order ÷ sessions that searched. Each session counts in the week of its first search. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nsearches AS (\n  SELECT\n    session_id,\n    MIN(IFF(event_name = 'product_searched', occurred_at, NULL)) AS searched_at,\n    MAX(IFF(event_name = 'order_completed', occurred_at, NULL)) AS ordered_at\n  FROM events\n  WHERE event_name IN ('product_searched', 'order_completed')\n    AND session_id <> ''\n    AND occurred_at >= DATEADD(week, -26, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n  GROUP BY session_id\n),\nweekly AS (\n  SELECT\n    DATEADD(day, 1 - DAYOFWEEKISO(searched_at), searched_at::date) AS week,\n    COUNT_IF(ordered_at >= searched_at) AS converted,\n    COUNT(*) AS sessions\n  FROM searches\n  WHERE searched_at IS NOT NULL\n  GROUP BY 1\n)\nSELECT\n  w.week,\n  COALESCE(s.converted, 0) AS numerator,\n  COALESCE(s.sessions, 0) AS denominator,\n  s.converted::float / NULLIF(s.sessions, 0) AS value\nFROM weeks AS w\nLEFT JOIN weekly AS s ON s.week = w.week\nORDER BY w.week;"},"noise":{"type":"binomial","min_denominator":500,"volume_unit":"sessions with a search a week","typical":0.05,"reference_volumes":[500,2000,10000,50000]},"example":{"business":"store","level":0.052,"volume":66000,"trend":0.03},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a search app or theme change start firing product_searched on autocomplete keystrokes?","yes":"Sessions with a search jump on the release day, many with a one- or two-letter query and nothing after it."},"spiked":{"check":"Did product_searched stop firing on some pages or devices, leaving only the most determined searchers?","yes":"Sessions with a search fall on one device or template while search orders hold."}},{"id":"store-wide","label":"The whole store","metric":"conversion-rate","dropped":{"check":"Did conversion fall for everyone, not only for searchers?","yes":"Search conversion and store conversion fall together, so the cause is checkout, price or the calendar, not search."},"spiked":{"check":"Did conversion rise for everyone, from a sale or a fix elsewhere?","yes":"Search conversion and store conversion rise together, so search itself didn't change."}},{"id":"zero-results","label":"Searches with no results","dropped":{"check":"Did more searches return nothing, from a catalogue change, lost synonyms or a trending term you don't stock?","yes":"The share of searches with results_count of 0 rises, concentrated in a few queries."},"spiked":{"check":"Did a synonym, spelling or catalogue fix cut dead-end searches?","yes":"Zero-result searches fall from the day of the fix, on the queries it covered."}},{"id":"stock","label":"Stock of searched products","dropped":{"check":"Are the products people search for most out of stock or missing common sizes?","yes":"Top queries still return results, but their first results are sold out."},"spiked":{"check":"Did a much-searched product come back in stock or launch?","yes":"Orders after searching for that product's name jump from the restock or launch day."}},{"id":"relevance","label":"Ranking and relevance","dropped":{"check":"Did a search app update, re-index or merchandising rule push irrelevant or sold-out products to the top?","yes":"Clicks on the first results fall for the top queries from the day of the change."},"spiked":{"check":"Did a relevance change or test ship, and is it on for everyone?","yes":"The rise starts on the release day across devices and queries."}},{"id":"who-searches","label":"Who searches","breakdown":"$device_type","dropped":{"check":"Did the search box become more prominent, so more casual browsers search?","yes":"Sessions with a search grow faster than orders after searching; search-driven orders still rise."},"spiked":{"check":"Did the search box move or shrink, leaving fewer but more committed searchers?","yes":"Sessions with a search fall while orders after searching hold."}}],"diagnose_order":["tracking","store-wide","zero-results","stock","relevance","who-searches"],"related":["conversion-rate","product-view-rate","add-to-cart-rate","revenue-per-session"],"prose":{"why_it_matters":"Shoppers who search say what they want in their own words, and they usually convert well above the store average; at Northwind, 5.2% against 2.1%. A fall here is usually something the team controls, such as a search app update, lost synonyms or empty results for the words people actually type.","pitfalls":["Searchers are more committed than average, so a high search conversion doesn't prove search works. Compare search conversion with itself over time, not with the store rate.","Predictive search that fires the event on each keystroke counts sessions that never submitted a search. Fire product_searched on submit or on the results view.","This spec credits search only when the order follows in the same session. A shopper who searches today and buys tomorrow counts as a search that didn't convert.","Zero-result searches are the fastest thing to check. A catalogue, synonym or search app change shows up there on the day it ships, often before orders tell you."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "second-order-rate": { yaml: "id: second-order-rate\nname: Second order rate\naliases:\n  - Second purchase rate\n  - 90-day repeat rate\n  - Second order conversion\nfamily: customers\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of first-time customers who place a second order within 90 days of their first, by the week of the first order.\n  formula: Customers who ordered again within 90 days ÷ customers whose first order fell in the week\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: is_first_order\n        description: True when the store has no earlier order from this customer, from its own customer records.\n      - name: customer_id\n        description: The store's customer id, shared by guest and logged-in orders with the same email.\n      - name: order_id\n        description: Unique per order, so a duplicate of the first order is never taken for a second one.\n      - name: coupon\n        description: The discount code used, if any.\n\nnumerator:\n  label: First-time customers who ordered again within 90 days\n  aggregate: unique_users\n  event: order_completed\n  where:\n    - property: is_first_order\n      op: eq\n      value: false\ndenominator:\n  label: Customers whose first order fell in the week\n  aggregate: unique_users\n  event: order_completed\n  where:\n    - property: is_first_order\n      op: eq\n      value: true\n\nqueries:\n  hogql: |-\n    -- Second order rate: of customers whose first order fell in each week, the share who placed another order (not a repeat of the first order's id) within 90 days of it. First-order weeks 39 to 14 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 90 days close.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(c.reordered_customers, 0) AS numerator,\n      coalesce(c.customers, 0) AS denominator,\n      if(denominator = 0, NULL, numerator / denominator) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(14, 40))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, countIf(reordered) AS reordered_customers, count() AS customers\n      FROM (\n        SELECT\n          toMonday(f.first_at) AS week,\n          f.customer_id AS customer_id,\n          countIf(coalesce(o.order_id != f.first_order_id, 1) AND o.ts > f.first_at AND o.ts <= f.first_at + toIntervalDay(90)) > 0 AS reordered\n        FROM (\n          SELECT\n            customer_id,\n            min(ts) AS first_at,\n            tupleElement(argMin(tuple(order_id), ts), 1) AS first_order_id\n          FROM (\n            SELECT\n              coalesce(properties.customer_id, toString(person_id)) AS customer_id,\n              properties.order_id AS order_id,\n              toTimeZone(timestamp, 'UTC') AS ts\n            FROM events\n            WHERE event = 'order_completed'\n              AND properties.is_first_order = 'true'\n              AND timestamp >= now() - toIntervalWeek(40)\n              AND toMonday(toTimeZone(timestamp, 'UTC')) >= toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(39)\n          )\n          WHERE customer_id IS NOT NULL\n          GROUP BY customer_id\n        ) AS f\n        LEFT JOIN (\n          SELECT\n            coalesce(properties.customer_id, toString(person_id)) AS customer_id,\n            properties.order_id AS order_id,\n            toTimeZone(timestamp, 'UTC') AS ts\n          FROM events\n          WHERE event = 'order_completed'\n            AND timestamp >= now() - toIntervalWeek(40)\n            AND toMonday(toTimeZone(timestamp, 'UTC')) >= toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(39)\n        ) AS o ON o.customer_id = f.customer_id\n        WHERE toMonday(f.first_at) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(39) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(14)\n        GROUP BY week, customer_id\n      )\n      GROUP BY week\n    ) AS c ON c.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Second order rate: of customers whose first order fell in each week, the share who placed another order (not a repeat of the first order's id) within 90 days of it. First-order weeks 39 to 14 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 90 days close.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '39 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '14 weeks',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    orders AS (\n      SELECT\n        coalesce(properties->>'customer_id', user_id) AS customer_id,\n        properties->>'order_id' AS order_id,\n        properties->>'is_first_order' = 'true' AS is_first_order,\n        occurred_at AT TIME ZONE 'UTC' AS ts\n      FROM events\n      WHERE event_name = 'order_completed'\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '39 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n    ),\n    first_orders AS (\n      SELECT DISTINCT ON (customer_id) customer_id, order_id AS first_order_id, ts AS first_at\n      FROM orders\n      WHERE is_first_order\n        AND customer_id IS NOT NULL\n        AND ts < date_trunc('week', now() AT TIME ZONE 'UTC') - interval '13 weeks'\n      ORDER BY customer_id, ts\n    ),\n    cohort AS (\n      SELECT\n        date_trunc('week', f.first_at)::date AS week,\n        f.customer_id,\n        count(o.ts) > 0 AS reordered\n      FROM first_orders AS f\n      LEFT JOIN orders AS o\n        ON o.customer_id = f.customer_id\n       AND coalesce(o.order_id <> f.first_order_id, true)\n       AND o.ts > f.first_at\n       AND o.ts <= f.first_at + interval '90 days'\n      GROUP BY 1, 2\n    )\n    SELECT\n      w.week,\n      count(c.customer_id) FILTER (WHERE c.reordered) AS numerator,\n      count(c.customer_id) AS denominator,\n      (count(c.customer_id) FILTER (WHERE c.reordered))::numeric / nullif(count(c.customer_id), 0) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Second order rate: of customers whose first order fell in each week, the share who placed another order (not a repeat of the first order's id) within 90 days of it. First-order weeks 39 to 14 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 90 days close.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 39 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 14 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    orders AS (\n      SELECT\n        COALESCE(JSON_VALUE(properties, '$.customer_id'), user_id) AS customer_id,\n        JSON_VALUE(properties, '$.order_id') AS order_id,\n        JSON_VALUE(properties, '$.is_first_order') = 'true' AS is_first_order,\n        occurred_at\n      FROM events\n      WHERE event_name = 'order_completed'\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 39 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    ),\n    first_orders AS (\n      SELECT customer_id, order_id AS first_order_id, occurred_at AS first_at\n      FROM orders\n      WHERE is_first_order\n        AND customer_id IS NOT NULL\n        AND occurred_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 13 WEEK))\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY occurred_at) = 1\n    ),\n    cohort AS (\n      SELECT\n        DATE_TRUNC(DATE(f.first_at), ISOWEEK) AS week,\n        f.customer_id,\n        COUNT(o.occurred_at) > 0 AS reordered\n      FROM first_orders AS f\n      LEFT JOIN orders AS o\n        ON o.customer_id = f.customer_id\n       AND COALESCE(o.order_id != f.first_order_id, TRUE)\n       AND o.occurred_at > f.first_at\n       AND o.occurred_at <= TIMESTAMP_ADD(f.first_at, INTERVAL 90 DAY)\n      GROUP BY week, f.customer_id\n    )\n    SELECT\n      w.week,\n      COUNTIF(c.reordered) AS numerator,\n      COUNT(c.customer_id) AS denominator,\n      SAFE_DIVIDE(COUNTIF(c.reordered), COUNT(c.customer_id)) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Second order rate: of customers whose first order fell in each week, the share who placed another order (not a repeat of the first order's id) within 90 days of it. First-order weeks 39 to 14 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 90 days close.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -13 - ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    orders AS (\n      SELECT\n        COALESCE(properties:\"customer_id\"::string, user_id) AS customer_id,\n        properties:\"order_id\"::string AS order_id,\n        properties:\"is_first_order\"::string = 'true' AS is_first_order,\n        occurred_at\n      FROM events\n      WHERE event_name = 'order_completed'\n        AND occurred_at >= DATEADD(week, -39, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n    ),\n    first_orders AS (\n      SELECT customer_id, order_id AS first_order_id, occurred_at AS first_at\n      FROM orders\n      WHERE is_first_order\n        AND customer_id IS NOT NULL\n        AND occurred_at < DATEADD(week, -13, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY occurred_at) = 1\n    ),\n    cohort AS (\n      SELECT\n        DATEADD(day, 1 - DAYOFWEEKISO(f.first_at), f.first_at::date) AS week,\n        f.customer_id,\n        COUNT(o.occurred_at) > 0 AS reordered\n      FROM first_orders AS f\n      LEFT JOIN orders AS o\n        ON o.customer_id = f.customer_id\n       AND COALESCE(o.order_id <> f.first_order_id, TRUE)\n       AND o.occurred_at > f.first_at\n       AND o.occurred_at <= DATEADD(day, 90, f.first_at)\n      GROUP BY 1, 2\n    )\n    SELECT\n      w.week,\n      COUNT_IF(c.reordered) AS numerator,\n      COUNT(c.customer_id) AS denominator,\n      COUNT_IF(c.reordered)::float / NULLIF(COUNT(c.customer_id), 0) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n\nnoise:\n  type: binomial\n  min_denominator: 200\n  volume_unit: first-time customers in the cohort\n  typical: 0.21\n\nexample:\n  business: store\n  level: 0.21\n  volume: 7700\n  trend: 0.02\n\ndrivers:\n  - id: tracking\n    label: Order and customer records\n    dropped:\n      check: Did customer matching break during the cohort's 90 days, so second orders landed under new ids?\n      yes: Second orders fall while new customers rise by a similar number in the same weeks.\n    spiked:\n      check: Are duplicate order events or split shipments being counted as second orders?\n      yes: Many second orders arrive within minutes or hours of the first, often with the same items.\n  - id: calendar\n    label: Holiday cohorts\n    feed: shopping\n    dropped:\n      check: Is this a holiday or Black Friday cohort? Gift buyers and deal hunters reorder far less.\n      yes: The same cohort weeks last year show the same dip.\n    spiked:\n      check: Did the cohort's 90 days include a big sale that pulled second orders forward?\n      yes: An unusual share of second orders landed in one sale week inside the window.\n  - id: cohort-source\n    label: How the cohort was won\n    breakdown: coupon\n    dropped:\n      check: Did the cohort come in on a deep discount, a giveaway or one new paid channel?\n      yes: Customers whose first order used that code or came from that channel reorder far less than the rest.\n    spiked:\n      check: Did the cohort come mostly from referrals, email signups or full-price buyers?\n      yes: The share of first orders without a discount code is higher than in neighbouring cohorts.\n  - id: first-experience\n    label: First-order experience\n    metric: refund-rate\n    dropped:\n      check: Did the cohort's first orders arrive late or damaged, or get refunded more than usual?\n      yes: Refunds or delivery complaints on first orders from the cohort week run above normal.\n    spiked:\n      check: Did delivery get faster or a packaging or product fix land for this cohort?\n      yes: Refunds and complaints on the cohort's first orders run below normal.\n  - id: post-purchase-flows\n    label: Post-purchase emails\n    metric: email-click-rate\n    dropped:\n      check: Did the post-purchase or replenishment flow stop sending during the cohort's 90 days?\n      yes: Flow sends or clicks to the cohort fell, and second orders from email fell with them.\n    spiked:\n      check: Did a new post-purchase offer or replenishment reminder start for this cohort?\n      yes: Second orders from the new flow account for most of the gain.\n\ndiagnose_order: [tracking, calendar, cohort-source, first-experience, post-purchase-flows]\n\nrelated: [repeat-purchase-rate, customer-lifetime-value, new-customers, refund-rate, purchase-frequency]\n\nprose:\n  why_it_matters: >-\n    The second order is the hardest one to win and the best early read on lifetime value: a customer\n    who has ordered twice is far likelier to order a third time than a first-time buyer is to order a\n    second. It judges a cohort in 90 days instead of a year, so it is the first number to show\n    whether a campaign brought buyers or bargain hunters. With 7,700 first-time customers in a\n    cohort, a move of 1.3 points is real.\n  pitfalls:\n    - Only cohorts whose 90 days have closed are reported, so the latest point describes customers who first ordered 14 weeks ago. Showing younger cohorts makes every recent week look like a collapse.\n    - Holiday cohorts reorder less because many first orders are gifts. Compare a cohort with the same weeks last year, not with the cohort before it.\n    - A deep first-order discount wins customers who wait for the next discount. Split by first-order coupon before crediting or blaming the product.\n    - A duplicate order event a few minutes after the first is not a second order. This spec requires a different order id.\n    - Ninety days suits most consumer goods; for products bought once or twice a year, a 180- or 365-day window is the fair one, stated on the chart.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"second-order-rate","name":"Second order rate","aliases":["Second purchase rate","90-day repeat rate","Second order conversion"],"family":"customers","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of first-time customers who place a second order within 90 days of their first, by the week of the first order.","formula":"Customers who ordered again within 90 days ÷ customers whose first order fell in the week"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"is_first_order","description":"True when the store has no earlier order from this customer, from its own customer records."},{"name":"customer_id","description":"The store's customer id, shared by guest and logged-in orders with the same email."},{"name":"order_id","description":"Unique per order, so a duplicate of the first order is never taken for a second one."},{"name":"coupon","description":"The discount code used, if any."}]}],"numerator":{"label":"First-time customers who ordered again within 90 days","aggregate":"unique_users","event":"order_completed","where":[{"property":"is_first_order","op":"eq","value":false}]},"denominator":{"label":"Customers whose first order fell in the week","aggregate":"unique_users","event":"order_completed","where":[{"property":"is_first_order","op":"eq","value":true}]},"queries":{"hogql":"-- Second order rate: of customers whose first order fell in each week, the share who placed another order (not a repeat of the first order's id) within 90 days of it. First-order weeks 39 to 14 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 90 days close.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(c.reordered_customers, 0) AS numerator,\n  coalesce(c.customers, 0) AS denominator,\n  if(denominator = 0, NULL, numerator / denominator) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(14, 40))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, countIf(reordered) AS reordered_customers, count() AS customers\n  FROM (\n    SELECT\n      toMonday(f.first_at) AS week,\n      f.customer_id AS customer_id,\n      countIf(coalesce(o.order_id != f.first_order_id, 1) AND o.ts > f.first_at AND o.ts <= f.first_at + toIntervalDay(90)) > 0 AS reordered\n    FROM (\n      SELECT\n        customer_id,\n        min(ts) AS first_at,\n        tupleElement(argMin(tuple(order_id), ts), 1) AS first_order_id\n      FROM (\n        SELECT\n          coalesce(properties.customer_id, toString(person_id)) AS customer_id,\n          properties.order_id AS order_id,\n          toTimeZone(timestamp, 'UTC') AS ts\n        FROM events\n        WHERE event = 'order_completed'\n          AND properties.is_first_order = 'true'\n          AND timestamp >= now() - toIntervalWeek(40)\n          AND toMonday(toTimeZone(timestamp, 'UTC')) >= toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(39)\n      )\n      WHERE customer_id IS NOT NULL\n      GROUP BY customer_id\n    ) AS f\n    LEFT JOIN (\n      SELECT\n        coalesce(properties.customer_id, toString(person_id)) AS customer_id,\n        properties.order_id AS order_id,\n        toTimeZone(timestamp, 'UTC') AS ts\n      FROM events\n      WHERE event = 'order_completed'\n        AND timestamp >= now() - toIntervalWeek(40)\n        AND toMonday(toTimeZone(timestamp, 'UTC')) >= toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(39)\n    ) AS o ON o.customer_id = f.customer_id\n    WHERE toMonday(f.first_at) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(39) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(14)\n    GROUP BY week, customer_id\n  )\n  GROUP BY week\n) AS c ON c.week = w.week\nORDER BY week","postgres":"-- Second order rate: of customers whose first order fell in each week, the share who placed another order (not a repeat of the first order's id) within 90 days of it. First-order weeks 39 to 14 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 90 days close.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '39 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '14 weeks',\n    interval '1 week'\n  ) AS g(week)\n),\norders AS (\n  SELECT\n    coalesce(properties->>'customer_id', user_id) AS customer_id,\n    properties->>'order_id' AS order_id,\n    properties->>'is_first_order' = 'true' AS is_first_order,\n    occurred_at AT TIME ZONE 'UTC' AS ts\n  FROM events\n  WHERE event_name = 'order_completed'\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '39 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n),\nfirst_orders AS (\n  SELECT DISTINCT ON (customer_id) customer_id, order_id AS first_order_id, ts AS first_at\n  FROM orders\n  WHERE is_first_order\n    AND customer_id IS NOT NULL\n    AND ts < date_trunc('week', now() AT TIME ZONE 'UTC') - interval '13 weeks'\n  ORDER BY customer_id, ts\n),\ncohort AS (\n  SELECT\n    date_trunc('week', f.first_at)::date AS week,\n    f.customer_id,\n    count(o.ts) > 0 AS reordered\n  FROM first_orders AS f\n  LEFT JOIN orders AS o\n    ON o.customer_id = f.customer_id\n   AND coalesce(o.order_id <> f.first_order_id, true)\n   AND o.ts > f.first_at\n   AND o.ts <= f.first_at + interval '90 days'\n  GROUP BY 1, 2\n)\nSELECT\n  w.week,\n  count(c.customer_id) FILTER (WHERE c.reordered) AS numerator,\n  count(c.customer_id) AS denominator,\n  (count(c.customer_id) FILTER (WHERE c.reordered))::numeric / nullif(count(c.customer_id), 0) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;","bigquery":"-- Second order rate: of customers whose first order fell in each week, the share who placed another order (not a repeat of the first order's id) within 90 days of it. First-order weeks 39 to 14 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 90 days close.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 39 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 14 WEEK), INTERVAL 1 WEEK)) AS week\n),\norders AS (\n  SELECT\n    COALESCE(JSON_VALUE(properties, '$.customer_id'), user_id) AS customer_id,\n    JSON_VALUE(properties, '$.order_id') AS order_id,\n    JSON_VALUE(properties, '$.is_first_order') = 'true' AS is_first_order,\n    occurred_at\n  FROM events\n  WHERE event_name = 'order_completed'\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 39 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n),\nfirst_orders AS (\n  SELECT customer_id, order_id AS first_order_id, occurred_at AS first_at\n  FROM orders\n  WHERE is_first_order\n    AND customer_id IS NOT NULL\n    AND occurred_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 13 WEEK))\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY occurred_at) = 1\n),\ncohort AS (\n  SELECT\n    DATE_TRUNC(DATE(f.first_at), ISOWEEK) AS week,\n    f.customer_id,\n    COUNT(o.occurred_at) > 0 AS reordered\n  FROM first_orders AS f\n  LEFT JOIN orders AS o\n    ON o.customer_id = f.customer_id\n   AND COALESCE(o.order_id != f.first_order_id, TRUE)\n   AND o.occurred_at > f.first_at\n   AND o.occurred_at <= TIMESTAMP_ADD(f.first_at, INTERVAL 90 DAY)\n  GROUP BY week, f.customer_id\n)\nSELECT\n  w.week,\n  COUNTIF(c.reordered) AS numerator,\n  COUNT(c.customer_id) AS denominator,\n  SAFE_DIVIDE(COUNTIF(c.reordered), COUNT(c.customer_id)) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;","snowflake":"-- Second order rate: of customers whose first order fell in each week, the share who placed another order (not a repeat of the first order's id) within 90 days of it. First-order weeks 39 to 14 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 90 days close.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -13 - ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\norders AS (\n  SELECT\n    COALESCE(properties:\"customer_id\"::string, user_id) AS customer_id,\n    properties:\"order_id\"::string AS order_id,\n    properties:\"is_first_order\"::string = 'true' AS is_first_order,\n    occurred_at\n  FROM events\n  WHERE event_name = 'order_completed'\n    AND occurred_at >= DATEADD(week, -39, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n),\nfirst_orders AS (\n  SELECT customer_id, order_id AS first_order_id, occurred_at AS first_at\n  FROM orders\n  WHERE is_first_order\n    AND customer_id IS NOT NULL\n    AND occurred_at < DATEADD(week, -13, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY occurred_at) = 1\n),\ncohort AS (\n  SELECT\n    DATEADD(day, 1 - DAYOFWEEKISO(f.first_at), f.first_at::date) AS week,\n    f.customer_id,\n    COUNT(o.occurred_at) > 0 AS reordered\n  FROM first_orders AS f\n  LEFT JOIN orders AS o\n    ON o.customer_id = f.customer_id\n   AND COALESCE(o.order_id <> f.first_order_id, TRUE)\n   AND o.occurred_at > f.first_at\n   AND o.occurred_at <= DATEADD(day, 90, f.first_at)\n  GROUP BY 1, 2\n)\nSELECT\n  w.week,\n  COUNT_IF(c.reordered) AS numerator,\n  COUNT(c.customer_id) AS denominator,\n  COUNT_IF(c.reordered)::float / NULLIF(COUNT(c.customer_id), 0) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;"},"noise":{"type":"binomial","min_denominator":200,"volume_unit":"first-time customers in the cohort","typical":0.21},"example":{"business":"store","level":0.21,"volume":7700,"trend":0.02},"drivers":[{"id":"tracking","label":"Order and customer records","dropped":{"check":"Did customer matching break during the cohort's 90 days, so second orders landed under new ids?","yes":"Second orders fall while new customers rise by a similar number in the same weeks."},"spiked":{"check":"Are duplicate order events or split shipments being counted as second orders?","yes":"Many second orders arrive within minutes or hours of the first, often with the same items."}},{"id":"calendar","label":"Holiday cohorts","feed":"shopping","dropped":{"check":"Is this a holiday or Black Friday cohort? Gift buyers and deal hunters reorder far less.","yes":"The same cohort weeks last year show the same dip."},"spiked":{"check":"Did the cohort's 90 days include a big sale that pulled second orders forward?","yes":"An unusual share of second orders landed in one sale week inside the window."}},{"id":"cohort-source","label":"How the cohort was won","breakdown":"coupon","dropped":{"check":"Did the cohort come in on a deep discount, a giveaway or one new paid channel?","yes":"Customers whose first order used that code or came from that channel reorder far less than the rest."},"spiked":{"check":"Did the cohort come mostly from referrals, email signups or full-price buyers?","yes":"The share of first orders without a discount code is higher than in neighbouring cohorts."}},{"id":"first-experience","label":"First-order experience","metric":"refund-rate","dropped":{"check":"Did the cohort's first orders arrive late or damaged, or get refunded more than usual?","yes":"Refunds or delivery complaints on first orders from the cohort week run above normal."},"spiked":{"check":"Did delivery get faster or a packaging or product fix land for this cohort?","yes":"Refunds and complaints on the cohort's first orders run below normal."}},{"id":"post-purchase-flows","label":"Post-purchase emails","metric":"email-click-rate","dropped":{"check":"Did the post-purchase or replenishment flow stop sending during the cohort's 90 days?","yes":"Flow sends or clicks to the cohort fell, and second orders from email fell with them."},"spiked":{"check":"Did a new post-purchase offer or replenishment reminder start for this cohort?","yes":"Second orders from the new flow account for most of the gain."}}],"diagnose_order":["tracking","calendar","cohort-source","first-experience","post-purchase-flows"],"related":["repeat-purchase-rate","customer-lifetime-value","new-customers","refund-rate","purchase-frequency"],"prose":{"why_it_matters":"The second order is the hardest one to win and the best early read on lifetime value: a customer who has ordered twice is far likelier to order a third time than a first-time buyer is to order a second. It judges a cohort in 90 days instead of a year, so it is the first number to show whether a campaign brought buyers or bargain hunters. With 7,700 first-time customers in a cohort, a move of 1.3 points is real.","pitfalls":["Only cohorts whose 90 days have closed are reported, so the latest point describes customers who first ordered 14 weeks ago. Showing younger cohorts makes every recent week look like a collapse.","Holiday cohorts reorder less because many first orders are gifts. Compare a cohort with the same weeks last year, not with the cohort before it.","A deep first-order discount wins customers who wait for the next discount. Split by first-order coupon before crediting or blaming the product.","A duplicate order event a few minutes after the first is not a second order. This spec requires a different order id.","Ninety days suits most consumer goods; for products bought once or twice a year, a 180- or 365-day window is the fair one, stated on the chart."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "sessions-per-user": { yaml: "id: sessions-per-user\nname: Sessions per user\naliases:\n  - Sessions per active user\n  - Session frequency\n  - Average sessions per user\n  - Weekly sessions per user\nfamily: engagement\nkind: ratio\npolarity: up-is-good\n\ndefinition:\n  one_line: The average number of sessions each active person had this week, Monday to Sunday UTC.\n  formula: Distinct sessions ÷ distinct active people, in the same week\n\nevents:\n  - name: \"*\"\n    description: Any event a person sends; its session id groups events into sessions.\n    also_called: [All events, Any event, Active event]\n    properties:\n      - name: $session_id\n        description: The session the event belongs to. PostHog starts a new one after 30 minutes without events.\n      - name: $os\n        description: The operating system, for splitting by platform.\n\nnumerator:\n  label: Sessions\n  aggregate: unique_sessions\n  event: \"*\"\ndenominator:\n  label: Active people\n  aggregate: unique_users\n  event: \"*\"\n\nnoise:\n  type: mean\n  cv: 1.2\n  min_denominator: 100\n  volume_unit: weekly active users\n  typical: 3.6\n\nexample:\n  business: app\n  level: 3.6\n  volume: 52000\n  trend: 0.02\n\ndrivers:\n  - id: session-definition\n    label: How sessions are counted\n    dropped:\n      check: Did sessions start merging, from a longer timeout or events arriving without a session id on one platform?\n      yes: Events with no session id rise, or the average falls on one platform overnight.\n    spiked:\n      check: Did something start splitting sessions, such as a shorter timeout, an SDK update or backgrounding the app?\n      yes: Sessions jump on one platform or app version from the release date while time in the product holds.\n  - id: calendar\n    label: Calendar\n    feed: holidays\n    dropped:\n      check: Did a holiday break the routines that bring people back several times a week?\n      yes: The same week last year shows the same dip once aligned on the holiday.\n    spiked:\n      check: Is this a seasonal high for the product?\n      yes: The same weeks last year show the same rise.\n  - id: user-mix\n    label: New people in the average\n    metric: signups\n    dropped:\n      check: Did a wave of new people, who have fewer sessions in their first week, join the average?\n      yes: Sessions per returning person hold while new people's share of actives rises.\n    spiked:\n      check: Did new arrivals slow, leaving more heavy users in the average?\n      yes: Sessions per returning person hold and the average rises without anyone using the product more.\n  - id: platform\n    label: Platform and releases\n    breakdown: $os\n    feed: app-stores\n    dropped:\n      check: Is the fall on one platform, after a release or OS update?\n      yes: One platform's average falls from the release date while the others hold.\n    spiked:\n      check: Is the rise on one platform only?\n      yes: One platform rises from a release date; check it isn't the session rule changing.\n  - id: error-retry\n    label: Errors and crashes\n    metric: error-rate\n    dropped:\n      check: Did errors or slow loads make people give up?\n      yes: Error rate rises on the same platform where sessions per user falls.\n    spiked:\n      check: Are people reopening the product because it crashed?\n      yes: Error rate rises too, and the extra sessions are short and close together.\n  - id: notifications\n    label: Notifications\n    dropped:\n      check: Did pushes or reminders that bring people back stop, or lose OS permission?\n      yes: Sessions opened from notifications fall while other sessions hold.\n    spiked:\n      check: Did a new push or reminder go live?\n      yes: Sessions opened from notifications rise; check that they last as long as other sessions.\n\ndiagnose_order: [session-definition, calendar, user-mix, platform, error-retry, notifications]\n\nrelated: [dau, wau, stickiness, error-rate, pages-per-session]\n\nprose:\n  why_it_matters: >-\n    Sessions per user measures frequency: how often active people come back within a week,\n    separate from how many of them there are. A product can hold its weekly actives while\n    frequency falls, which is often the first sign of a fading habit. At 52,000 weekly actives\n    the average moves about 1.5% by chance, so a 5% fall is real.\n  pitfalls:\n    - A session is whatever your tool says it is. PostHog ends one after 30 minutes without events and many mobile SDKs end one on backgrounding, so changing the rule changes the number with no change in behaviour.\n    - Events without a session id drop out of the numerator while their people stay in the denominator. Check the share of events with no session before reading a fall.\n    - New people pull the average down in weeks with strong acquisition. Read returning people on their own.\n    - A crash that makes people reopen the product raises sessions per user. Check error rate before celebrating a rise.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"sessions-per-user","name":"Sessions per user","aliases":["Sessions per active user","Session frequency","Average sessions per user","Weekly sessions per user"],"family":"engagement","kind":"ratio","polarity":"up-is-good","definition":{"one_line":"The average number of sessions each active person had this week, Monday to Sunday UTC.","formula":"Distinct sessions ÷ distinct active people, in the same week"},"events":[{"name":"*","description":"Any event a person sends; its session id groups events into sessions.","also_called":["All events","Any event","Active event"],"properties":[{"name":"$session_id","description":"The session the event belongs to. PostHog starts a new one after 30 minutes without events."},{"name":"$os","description":"The operating system, for splitting by platform."}]}],"numerator":{"label":"Sessions","aggregate":"unique_sessions","event":"*"},"denominator":{"label":"Active people","aggregate":"unique_users","event":"*"},"noise":{"type":"mean","cv":1.2,"min_denominator":100,"volume_unit":"weekly active users","typical":3.6},"example":{"business":"app","level":3.6,"volume":52000,"trend":0.02},"drivers":[{"id":"session-definition","label":"How sessions are counted","dropped":{"check":"Did sessions start merging, from a longer timeout or events arriving without a session id on one platform?","yes":"Events with no session id rise, or the average falls on one platform overnight."},"spiked":{"check":"Did something start splitting sessions, such as a shorter timeout, an SDK update or backgrounding the app?","yes":"Sessions jump on one platform or app version from the release date while time in the product holds."}},{"id":"calendar","label":"Calendar","feed":"holidays","dropped":{"check":"Did a holiday break the routines that bring people back several times a week?","yes":"The same week last year shows the same dip once aligned on the holiday."},"spiked":{"check":"Is this a seasonal high for the product?","yes":"The same weeks last year show the same rise."}},{"id":"user-mix","label":"New people in the average","metric":"signups","dropped":{"check":"Did a wave of new people, who have fewer sessions in their first week, join the average?","yes":"Sessions per returning person hold while new people's share of actives rises."},"spiked":{"check":"Did new arrivals slow, leaving more heavy users in the average?","yes":"Sessions per returning person hold and the average rises without anyone using the product more."}},{"id":"platform","label":"Platform and releases","breakdown":"$os","feed":"app-stores","dropped":{"check":"Is the fall on one platform, after a release or OS update?","yes":"One platform's average falls from the release date while the others hold."},"spiked":{"check":"Is the rise on one platform only?","yes":"One platform rises from a release date; check it isn't the session rule changing."}},{"id":"error-retry","label":"Errors and crashes","metric":"error-rate","dropped":{"check":"Did errors or slow loads make people give up?","yes":"Error rate rises on the same platform where sessions per user falls."},"spiked":{"check":"Are people reopening the product because it crashed?","yes":"Error rate rises too, and the extra sessions are short and close together."}},{"id":"notifications","label":"Notifications","dropped":{"check":"Did pushes or reminders that bring people back stop, or lose OS permission?","yes":"Sessions opened from notifications fall while other sessions hold."},"spiked":{"check":"Did a new push or reminder go live?","yes":"Sessions opened from notifications rise; check that they last as long as other sessions."}}],"diagnose_order":["session-definition","calendar","user-mix","platform","error-retry","notifications"],"related":["dau","wau","stickiness","error-rate","pages-per-session"],"prose":{"why_it_matters":"Sessions per user measures frequency: how often active people come back within a week, separate from how many of them there are. A product can hold its weekly actives while frequency falls, which is often the first sign of a fading habit. At 52,000 weekly actives the average moves about 1.5% by chance, so a 5% fall is real.","pitfalls":["A session is whatever your tool says it is. PostHog ends one after 30 minutes without events and many mobile SDKs end one on backgrounding, so changing the rule changes the number with no change in behaviour.","Events without a session id drop out of the numerator while their people stay in the denominator. Check the share of events with no session before reading a fall.","New people pull the average down in weeks with strong acquisition. Read returning people on their own.","A crash that makes people reopen the product raises sessions per user. Check error rate before celebrating a rise."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "sessions": { yaml: "id: sessions\nname: Sessions\naliases:\n  - Visits\n  - Website sessions\n  - Site visits\nfamily: traffic\ncatalog_id: sessions\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: Visits to the site in the week, where a visit ends after 30 minutes without activity.\n  formula: Distinct session ids with at least one page view\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change, captured in the browser.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: $session_id\n        description: Set by the analytics SDK; a new id after 30 minutes idle or at most 24 hours.\n      - name: $referring_domain\n        description: The domain the visitor came from, or $direct when there was none.\n      - name: utm_medium\n        description: The campaign medium from the landing URL (cpc, email, social).\n\nnumerator:\n  label: Sessions\n  aggregate: unique_sessions\n  event: $pageview\n\nnoise:\n  type: poisson\n  min_denominator: 100\n  volume_unit: sessions a week\n  typical: 40000\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: store\n  level: 600000\n  volume: 600000\n  trend: 0.15\n\ndrivers:\n  - id: tracking\n    label: Tracking and bots\n    breakdown: $browser\n    dropped:\n      check: Did a consent banner, tag manager or SDK change stop page views being recorded?\n      yes: Orders in the store admin hold while recorded sessions fall, starting on the day of the change and often in one browser.\n    spiked:\n      check: Is a bot, crawler or a page view firing twice inflating the count?\n      yes: The extra sessions come from one browser, country or data-centre network, bounce almost every time and never order.\n  - id: site-availability\n    label: Site and CDN availability\n    feed: cloudflare\n    dropped:\n      check: Was the site, its CDN or its DNS down or slow for part of the week?\n      yes: Sessions dip in the hours of a known incident and recover after it.\n    spiked:\n      check: Was last week depressed by an outage, so this week only looks high?\n      yes: Last week has a gap in the hourly chart; this week is back to its usual level.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Was last week a sale, holiday or payday week that this week can't match?\n      yes: The same pair of weeks last year shows the same fall once aligned on the event.\n    spiked:\n      check: Is this week a sale, holiday or gifting week?\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: paid\n    label: Paid traffic\n    metric: paid-sessions\n    feed: ad-platforms\n    dropped:\n      check: Did ad spend fall, a campaign pause or a billing problem stop ads serving?\n      yes: Paid sessions fall by about as many sessions as the total does, while other channels hold.\n    spiked:\n      check: Did a campaign launch or a budget rise bring more ad clicks?\n      yes: Paid sessions rise by about the size of the jump; check that conversion held before celebrating.\n  - id: organic\n    label: Organic search\n    metric: organic-sessions\n    feed: google-search\n    dropped:\n      check: Did search traffic fall after a Google update or lost rankings on key pages?\n      yes: Organic sessions fall from the date of the update, concentrated on a few landing pages.\n    spiked:\n      check: Did a ranking gain, a seasonal search or a brand moment lift search traffic?\n      yes: Organic sessions rise on a handful of landing pages or on branded searches.\n  - id: referral\n    label: Referrals and press\n    metric: referral-sessions\n    dropped:\n      check: Did a partner link, affiliate or a source of steady referrals go away?\n      yes: One referring domain that used to send traffic has stopped.\n    spiked:\n      check: Did a press mention, a newsletter or a viral post link to the site?\n      yes: One referring domain explains most of the rise and fades within days.\n\ndiagnose_order: [tracking, site-availability, calendar, paid, organic, referral]\n\nrelated: [unique-visitors, organic-sessions, paid-sessions, bounce-rate, conversion-rate, revenue-per-session]\n\nprose:\n  why_it_matters: >-\n    Sessions are the top of every store funnel: orders are sessions times conversion, so a\n    traffic move shows up in orders at the same size unless conversion moves too. They are also\n    the number most easily inflated by bots and broken tags. A 600,000-session week that grows 4%\n    from a crawler adds 24,000 sessions and no orders, and drags every rate below it down.\n  pitfalls:\n    - Sessions are not visitors. One person can have several sessions a week, so a change in how often people come back moves sessions while unique visitors hold.\n    - Tools count sessions differently. Universal Analytics also split a visit at midnight and on every campaign change, GA4 estimates its session count, and server logs include bots browser tools never see, so compare a tool only with itself.\n    - Ad blockers and consent banners hide part of every week's visits from browser tracking, and the hidden share changes when the banner or a browser changes, not when traffic does.\n    - Bot traffic rarely looks like bots in the total. Split by country, browser and landing page before trusting a jump.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"sessions","name":"Sessions","aliases":["Visits","Website sessions","Site visits"],"family":"traffic","catalog_id":"sessions","kind":"count","polarity":"up-is-good","definition":{"one_line":"Visits to the site in the week, where a visit ends after 30 minutes without activity.","formula":"Distinct session ids with at least one page view"},"events":[{"name":"$pageview","description":"One page load or client-side route change, captured in the browser.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"$session_id","description":"Set by the analytics SDK; a new id after 30 minutes idle or at most 24 hours."},{"name":"$referring_domain","description":"The domain the visitor came from, or $direct when there was none."},{"name":"utm_medium","description":"The campaign medium from the landing URL (cpc, email, social)."}]}],"numerator":{"label":"Sessions","aggregate":"unique_sessions","event":"$pageview"},"noise":{"type":"poisson","min_denominator":100,"volume_unit":"sessions a week","typical":40000,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"store","level":600000,"volume":600000,"trend":0.15},"drivers":[{"id":"tracking","label":"Tracking and bots","breakdown":"$browser","dropped":{"check":"Did a consent banner, tag manager or SDK change stop page views being recorded?","yes":"Orders in the store admin hold while recorded sessions fall, starting on the day of the change and often in one browser."},"spiked":{"check":"Is a bot, crawler or a page view firing twice inflating the count?","yes":"The extra sessions come from one browser, country or data-centre network, bounce almost every time and never order."}},{"id":"site-availability","label":"Site and CDN availability","feed":"cloudflare","dropped":{"check":"Was the site, its CDN or its DNS down or slow for part of the week?","yes":"Sessions dip in the hours of a known incident and recover after it."},"spiked":{"check":"Was last week depressed by an outage, so this week only looks high?","yes":"Last week has a gap in the hourly chart; this week is back to its usual level."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Was last week a sale, holiday or payday week that this week can't match?","yes":"The same pair of weeks last year shows the same fall once aligned on the event."},"spiked":{"check":"Is this week a sale, holiday or gifting week?","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"paid","label":"Paid traffic","metric":"paid-sessions","feed":"ad-platforms","dropped":{"check":"Did ad spend fall, a campaign pause or a billing problem stop ads serving?","yes":"Paid sessions fall by about as many sessions as the total does, while other channels hold."},"spiked":{"check":"Did a campaign launch or a budget rise bring more ad clicks?","yes":"Paid sessions rise by about the size of the jump; check that conversion held before celebrating."}},{"id":"organic","label":"Organic search","metric":"organic-sessions","feed":"google-search","dropped":{"check":"Did search traffic fall after a Google update or lost rankings on key pages?","yes":"Organic sessions fall from the date of the update, concentrated on a few landing pages."},"spiked":{"check":"Did a ranking gain, a seasonal search or a brand moment lift search traffic?","yes":"Organic sessions rise on a handful of landing pages or on branded searches."}},{"id":"referral","label":"Referrals and press","metric":"referral-sessions","dropped":{"check":"Did a partner link, affiliate or a source of steady referrals go away?","yes":"One referring domain that used to send traffic has stopped."},"spiked":{"check":"Did a press mention, a newsletter or a viral post link to the site?","yes":"One referring domain explains most of the rise and fades within days."}}],"diagnose_order":["tracking","site-availability","calendar","paid","organic","referral"],"related":["unique-visitors","organic-sessions","paid-sessions","bounce-rate","conversion-rate","revenue-per-session"],"prose":{"why_it_matters":"Sessions are the top of every store funnel: orders are sessions times conversion, so a traffic move shows up in orders at the same size unless conversion moves too. They are also the number most easily inflated by bots and broken tags. A 600,000-session week that grows 4% from a crawler adds 24,000 sessions and no orders, and drags every rate below it down.","pitfalls":["Sessions are not visitors. One person can have several sessions a week, so a change in how often people come back moves sessions while unique visitors hold.","Tools count sessions differently. Universal Analytics also split a visit at midnight and on every campaign change, GA4 estimates its session count, and server logs include bots browser tools never see, so compare a tool only with itself.","Ad blockers and consent banners hide part of every week's visits from browser tracking, and the hidden share changes when the banner or a browser changes, not when traffic does.","Bot traffic rarely looks like bots in the total. Split by country, browser and landing page before trusting a jump."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "signup-rate": { yaml: "id: signup-rate\nname: Signup rate\naliases:\n  - Visitor-to-signup rate\n  - Signup conversion rate\n  - Registration rate\nfamily: activation\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of this week's new visitors who signed up, the website's visit-to-account conversion.\n  formula: People who signed up ÷ people whose first ever visit was this week\n\nevents:\n  - name: $pageview\n    description: One per page view; a person's first ever page view marks them as a new visitor.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: utm_source\n        description: The campaign source of the visit, when tagged.\n      - name: $device_type\n        description: Mobile, Desktop or Tablet.\n  - name: signed_up\n    description: An account created, sent by the server when the account exists, not when the form is submitted.\n    also_called: [sign_up, Signed Up, user_signed_up, account_created]\n    properties:\n      - name: method\n        description: How the account was created, such as email, google, sso or invite.\n\nnumerator:\n  label: People who signed up\n  aggregate: unique_users\n  event: signed_up\ndenominator:\n  label: New visitors\n  aggregate: first_time_users\n  event: $pageview\n\nnoise:\n  type: binomial\n  min_denominator: 1000\n  volume_unit: new visitors a week\n  typical: 0.04\n  reference_volumes: [2000, 10000, 50000, 200000]\n\nexample:\n  business: saas\n  level: 0.04\n  volume: 55000\n  trend: 0.05\n\ndrivers:\n  - id: tracking\n    label: Visitor and signup tracking\n    dropped:\n      check: Did a new domain, a tag change or a consent banner fix start counting visitors who were invisible before?\n      yes: New visitors jump on one day with no change in signups or in the server's own traffic logs.\n    spiked:\n      check: Did a consent banner or ad blocker hide visitors while server-side signups kept counting?\n      yes: New visitors fall on one day while signups hold, and the server's traffic logs don't fall.\n  - id: bots\n    label: Bot traffic\n    metric: unique-visitors\n    dropped:\n      check: Is bot or crawler traffic inflating new visitors?\n      yes: New visitors jump from one country, browser or data-centre range with near-zero time on site and no signups.\n    spiked:\n      check: Are bots creating accounts?\n      yes: Signups jump from one country or email domain and almost none of them activate.\n  - id: calendar\n    label: Holidays\n    feed: holidays\n    dropped:\n      check: Is this a holiday week, when business visitors browse but don't commit?\n      yes: The same week last year shows the same dip once aligned on the holiday.\n    spiked:\n      check: Is this the first week back after a holiday?\n      yes: The same week last year shows the same rise.\n  - id: traffic-mix\n    label: Who arrived\n    metric: paid-sessions\n    feed: ad-platforms\n    dropped:\n      check: Did low-intent visitors grow, from a viral post, a broad campaign or a ranking for an unrelated query?\n      yes: New visitors rise from one source whose signup rate is far below the rest.\n    spiked:\n      check: Did a broad campaign end, leaving fewer but more committed visitors?\n      yes: New visitors fall from one source while signups barely move.\n  - id: signup-flow\n    label: Signup page and form\n    breakdown: $device_type\n    dropped:\n      check: Did the signup form, pricing page or required fields change, or break on one device?\n      yes: The drop starts the day a release went out and concentrates on one device or step.\n    spiked:\n      check: Did a shorter form, social sign-in or a free plan ship?\n      yes: The rise starts the day it shipped, on every traffic source.\n\ndiagnose_order: [tracking, bots, calendar, traffic-mix, signup-flow]\n\nrelated: [signups, unique-visitors, activation-rate, demo-request-rate, conversion-rate]\n\nprose:\n  why_it_matters: >-\n    Signup rate separates two different problems: fewer people arriving, and fewer of them deciding\n    to try the product. At Copperline it is about 4% of 55,000 new visitors a week, or 2,200\n    signups. Because the denominator is visitors, it is very\n    sensitive to traffic quality, and a viral post can halve it while adding signups.\n  pitfalls:\n    - Logged-in customers browsing the app are not prospects. Dividing by all visitors buries the rate under existing users, so this spec divides by first-time visitors.\n    - People who first visited in an earlier week and sign up now count in the numerator only, so the rate runs slightly above a strict visitor cohort conversion. It is consistent week to week, which is what a change needs.\n    - Consent banners and ad blockers hide visitors but not server-side signups, which inflates the rate. A banner change can move it a point overnight.\n    - Bot traffic inflates the denominator and drags the rate down with no change in real demand. Filter known bots before reading a drop.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"signup-rate","name":"Signup rate","aliases":["Visitor-to-signup rate","Signup conversion rate","Registration rate"],"family":"activation","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of this week's new visitors who signed up, the website's visit-to-account conversion.","formula":"People who signed up ÷ people whose first ever visit was this week"},"events":[{"name":"$pageview","description":"One per page view; a person's first ever page view marks them as a new visitor.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"utm_source","description":"The campaign source of the visit, when tagged."},{"name":"$device_type","description":"Mobile, Desktop or Tablet."}]},{"name":"signed_up","description":"An account created, sent by the server when the account exists, not when the form is submitted.","also_called":["sign_up","Signed Up","user_signed_up","account_created"],"properties":[{"name":"method","description":"How the account was created, such as email, google, sso or invite."}]}],"numerator":{"label":"People who signed up","aggregate":"unique_users","event":"signed_up"},"denominator":{"label":"New visitors","aggregate":"first_time_users","event":"$pageview"},"noise":{"type":"binomial","min_denominator":1000,"volume_unit":"new visitors a week","typical":0.04,"reference_volumes":[2000,10000,50000,200000]},"example":{"business":"saas","level":0.04,"volume":55000,"trend":0.05},"drivers":[{"id":"tracking","label":"Visitor and signup tracking","dropped":{"check":"Did a new domain, a tag change or a consent banner fix start counting visitors who were invisible before?","yes":"New visitors jump on one day with no change in signups or in the server's own traffic logs."},"spiked":{"check":"Did a consent banner or ad blocker hide visitors while server-side signups kept counting?","yes":"New visitors fall on one day while signups hold, and the server's traffic logs don't fall."}},{"id":"bots","label":"Bot traffic","metric":"unique-visitors","dropped":{"check":"Is bot or crawler traffic inflating new visitors?","yes":"New visitors jump from one country, browser or data-centre range with near-zero time on site and no signups."},"spiked":{"check":"Are bots creating accounts?","yes":"Signups jump from one country or email domain and almost none of them activate."}},{"id":"calendar","label":"Holidays","feed":"holidays","dropped":{"check":"Is this a holiday week, when business visitors browse but don't commit?","yes":"The same week last year shows the same dip once aligned on the holiday."},"spiked":{"check":"Is this the first week back after a holiday?","yes":"The same week last year shows the same rise."}},{"id":"traffic-mix","label":"Who arrived","metric":"paid-sessions","feed":"ad-platforms","dropped":{"check":"Did low-intent visitors grow, from a viral post, a broad campaign or a ranking for an unrelated query?","yes":"New visitors rise from one source whose signup rate is far below the rest."},"spiked":{"check":"Did a broad campaign end, leaving fewer but more committed visitors?","yes":"New visitors fall from one source while signups barely move."}},{"id":"signup-flow","label":"Signup page and form","breakdown":"$device_type","dropped":{"check":"Did the signup form, pricing page or required fields change, or break on one device?","yes":"The drop starts the day a release went out and concentrates on one device or step."},"spiked":{"check":"Did a shorter form, social sign-in or a free plan ship?","yes":"The rise starts the day it shipped, on every traffic source."}}],"diagnose_order":["tracking","bots","calendar","traffic-mix","signup-flow"],"related":["signups","unique-visitors","activation-rate","demo-request-rate","conversion-rate"],"prose":{"why_it_matters":"Signup rate separates two different problems: fewer people arriving, and fewer of them deciding to try the product. At Copperline it is about 4% of 55,000 new visitors a week, or 2,200 signups. Because the denominator is visitors, it is very sensitive to traffic quality, and a viral post can halve it while adding signups.","pitfalls":["Logged-in customers browsing the app are not prospects. Dividing by all visitors buries the rate under existing users, so this spec divides by first-time visitors.","People who first visited in an earlier week and sign up now count in the numerator only, so the rate runs slightly above a strict visitor cohort conversion. It is consistent week to week, which is what a change needs.","Consent banners and ad blockers hide visitors but not server-side signups, which inflates the rate. A banner change can move it a point overnight.","Bot traffic inflates the denominator and drags the rate down with no change in real demand. Filter known bots before reading a drop."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "signups": { yaml: "id: signups\nname: Signups\naliases:\n  - Sign-ups\n  - New signups\n  - Registrations\n  - Account creations\nfamily: activation\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: People who created an account this week, each counted once.\n  formula: Distinct people with a signed_up event, by signup week\n\nevents:\n  - name: signed_up\n    description: An account created, sent by the server when the account exists, not when the form is submitted.\n    also_called: [sign_up, Signed Up, user_signed_up, account_created]\n    properties:\n      - name: method\n        description: How the account was created, such as email, google, sso or invite.\n      - name: plan\n        description: The plan chosen at signup, if any.\n\nnumerator:\n  label: People who signed up\n  aggregate: unique_users\n  event: signed_up\n\nnoise:\n  type: poisson\n  min_denominator: 30\n  volume_unit: signups a week\n  typical: 2200\n\nexample:\n  business: saas\n  level: 2200\n  volume: 2200\n  trend: 0.25\n\ndrivers:\n  - id: tracking\n    label: Signup event\n    breakdown: method\n    dropped:\n      check: Did the signup event stop firing for one method, such as Google sign-in after a release?\n      yes: One signup method falls to near zero while the others hold, and accounts in the database don't fall.\n    spiked:\n      check: Is the event firing twice, from both the client and the server, or on every login?\n      yes: Signups recorded exceed new accounts in the database, or many people have more than one signed_up event.\n  - id: bots\n    label: Bots and spam\n    breakdown: $geoip_country_code\n    dropped:\n      check: Did a new captcha, email verification or bot filter start blocking real people too?\n      yes: Signups fall from the day the filter shipped while visits and form starts hold.\n    spiked:\n      check: Is the spike bots or spam, many signups from one country, email domain or IP range?\n      yes: The extra signups cluster in one country or domain and almost none of them activate.\n  - id: calendar\n    label: Holidays\n    feed: holidays\n    dropped:\n      check: Is this a public holiday week in your main markets, such as the fortnight around Christmas?\n      yes: The same week last year shows the same dip once aligned on the holiday.\n    spiked:\n      check: Is this the first full week back after a holiday?\n      yes: The same week last year shows the same rebound.\n  - id: campaigns\n    label: Campaigns and launches\n    breakdown: utm_source\n    feed: ad-platforms\n    dropped:\n      check: Did a campaign end, a paid channel pause or an ad account get limited?\n      yes: Signups from one source fall to their pre-campaign level while the others hold.\n    spiked:\n      check: Did a launch, a press mention or a campaign bring a wave of signups?\n      yes: The extra signups come from one source; check whether they activate before celebrating.\n  - id: traffic\n    label: Visitors\n    metric: unique-visitors\n    feed: google-search\n    dropped:\n      check: Did fewer people reach the site, and from which channel?\n      yes: Visitors fall in one channel, often organic search after a ranking change, by about as much as signups.\n    spiked:\n      check: Did more people reach the site from one channel?\n      yes: Visitors rise in one channel and signup rate holds.\n  - id: signup-rate\n    label: Signup rate\n    metric: signup-rate\n    dropped:\n      check: Did a smaller share of visitors sign up, after a pricing, form or homepage change?\n      yes: Visitors hold while signup rate falls from the day of the change.\n    spiked:\n      check: Did a shorter form, a free plan or a new call to action lift the share who sign up?\n      yes: Visitors hold while signup rate rises from the day of the change.\n\ndiagnose_order: [tracking, bots, calendar, campaigns, traffic, signup-rate]\n\nrelated: [signup-rate, activation-rate, trial-starts, unique-visitors, sessions]\n\nprose:\n  why_it_matters: >-\n    Signups are the top of a product's funnel and the number most often celebrated too early. At\n    Copperline's 2,200 a week, chance alone moves the count about 6% either way, so a 10% jump is\n    worth a look and a 4% one is not. Count only what becomes a real account: bots, test accounts\n    and double-fired events inflate signups and nothing after them.\n  pitfalls:\n    - Client-side signup events fire twice on a reload or a double submit. Send signed_up from the server when the account is created.\n    - Spam and bot signups can double the count in a week and never activate. Check signups by country and email domain before celebrating a spike.\n    - Teammates who accept an invite are new accounts but not new demand. Split by signup method, or a viral week looks like a marketing win.\n    - A signup is not a customer. Judge a channel by its activation rate, not by its signup count.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"signups","name":"Signups","aliases":["Sign-ups","New signups","Registrations","Account creations"],"family":"activation","kind":"count","polarity":"up-is-good","definition":{"one_line":"People who created an account this week, each counted once.","formula":"Distinct people with a signed_up event, by signup week"},"events":[{"name":"signed_up","description":"An account created, sent by the server when the account exists, not when the form is submitted.","also_called":["sign_up","Signed Up","user_signed_up","account_created"],"properties":[{"name":"method","description":"How the account was created, such as email, google, sso or invite."},{"name":"plan","description":"The plan chosen at signup, if any."}]}],"numerator":{"label":"People who signed up","aggregate":"unique_users","event":"signed_up"},"noise":{"type":"poisson","min_denominator":30,"volume_unit":"signups a week","typical":2200},"example":{"business":"saas","level":2200,"volume":2200,"trend":0.25},"drivers":[{"id":"tracking","label":"Signup event","breakdown":"method","dropped":{"check":"Did the signup event stop firing for one method, such as Google sign-in after a release?","yes":"One signup method falls to near zero while the others hold, and accounts in the database don't fall."},"spiked":{"check":"Is the event firing twice, from both the client and the server, or on every login?","yes":"Signups recorded exceed new accounts in the database, or many people have more than one signed_up event."}},{"id":"bots","label":"Bots and spam","breakdown":"$geoip_country_code","dropped":{"check":"Did a new captcha, email verification or bot filter start blocking real people too?","yes":"Signups fall from the day the filter shipped while visits and form starts hold."},"spiked":{"check":"Is the spike bots or spam, many signups from one country, email domain or IP range?","yes":"The extra signups cluster in one country or domain and almost none of them activate."}},{"id":"calendar","label":"Holidays","feed":"holidays","dropped":{"check":"Is this a public holiday week in your main markets, such as the fortnight around Christmas?","yes":"The same week last year shows the same dip once aligned on the holiday."},"spiked":{"check":"Is this the first full week back after a holiday?","yes":"The same week last year shows the same rebound."}},{"id":"campaigns","label":"Campaigns and launches","breakdown":"utm_source","feed":"ad-platforms","dropped":{"check":"Did a campaign end, a paid channel pause or an ad account get limited?","yes":"Signups from one source fall to their pre-campaign level while the others hold."},"spiked":{"check":"Did a launch, a press mention or a campaign bring a wave of signups?","yes":"The extra signups come from one source; check whether they activate before celebrating."}},{"id":"traffic","label":"Visitors","metric":"unique-visitors","feed":"google-search","dropped":{"check":"Did fewer people reach the site, and from which channel?","yes":"Visitors fall in one channel, often organic search after a ranking change, by about as much as signups."},"spiked":{"check":"Did more people reach the site from one channel?","yes":"Visitors rise in one channel and signup rate holds."}},{"id":"signup-rate","label":"Signup rate","metric":"signup-rate","dropped":{"check":"Did a smaller share of visitors sign up, after a pricing, form or homepage change?","yes":"Visitors hold while signup rate falls from the day of the change."},"spiked":{"check":"Did a shorter form, a free plan or a new call to action lift the share who sign up?","yes":"Visitors hold while signup rate rises from the day of the change."}}],"diagnose_order":["tracking","bots","calendar","campaigns","traffic","signup-rate"],"related":["signup-rate","activation-rate","trial-starts","unique-visitors","sessions"],"prose":{"why_it_matters":"Signups are the top of a product's funnel and the number most often celebrated too early. At Copperline's 2,200 a week, chance alone moves the count about 6% either way, so a 10% jump is worth a look and a 4% one is not. Count only what becomes a real account: bots, test accounts and double-fired events inflate signups and nothing after them.","pitfalls":["Client-side signup events fire twice on a reload or a double submit. Send signed_up from the server when the account is created.","Spam and bot signups can double the count in a week and never activate. Check signups by country and email domain before celebrating a spike.","Teammates who accept an invite are new accounts but not new demand. Split by signup method, or a viral week looks like a marketing win.","A signup is not a customer. Judge a channel by its activation rate, not by its signup count."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "stickiness": { yaml: "id: stickiness\nname: Stickiness\naliases:\n  - DAU/MAU\n  - DAU/MAU ratio\n  - Stickiness ratio\n  - Daily to monthly active ratio\nfamily: engagement\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of a month's users who show up on a typical day, the week's average DAU divided by MAU for the 28 days ending that Sunday.\n  formula: Average daily active users this week ÷ distinct active people in the 28 days ending Sunday 23:59 UTC\n\nevents:\n  - name: \"*\"\n    description: Any event a person sends, counted the same way on both sides of the ratio.\n    also_called: [All events, Any event, Active event]\n    properties:\n      - name: $os\n        description: The operating system, for splitting by platform.\n\nnumerator:\n  label: Average daily active users\n  aggregate: unique_users\n  event: \"*\"\n\nqueries:\n  hogql: |-\n    -- Stickiness per week: the average of the week's seven daily counts of distinct active people (days in UTC) ÷ distinct active people in the four weeks (28 days) ending that Sunday. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(d.person_days, 0) / 7 AS numerator,\n      coalesce(m.people, 0) AS denominator,\n      if(denominator = 0, NULL, numerator / denominator) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT toMonday(day) AS week, count() AS person_days\n      FROM (\n        SELECT DISTINCT person_id, toDate(toTimeZone(timestamp, 'UTC')) AS day\n        FROM events\n        WHERE person_id IS NOT NULL\n          AND timestamp >= now() - toIntervalWeek(27)\n          AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n      )\n      GROUP BY week\n    ) AS d ON d.week = w.week\n    LEFT JOIN (\n      SELECT week, count(DISTINCT person_id) AS people\n      FROM (\n        SELECT person_id, active_week + toIntervalWeek(arrayJoin([0, 1, 2, 3])) AS week\n        FROM (\n          SELECT DISTINCT person_id, toMonday(toTimeZone(timestamp, 'UTC')) AS active_week\n          FROM events\n          WHERE person_id IS NOT NULL\n            AND timestamp >= now() - toIntervalWeek(30)\n            AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(29) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n        )\n      )\n      WHERE week BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n      GROUP BY week\n    ) AS m ON m.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Stickiness per week: the average of the week's seven daily counts of distinct active people (days in UTC) ÷ distinct active people in the four weeks (28 days) ending that Sunday. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    person_days AS (\n      SELECT DISTINCT\n        user_id,\n        (occurred_at AT TIME ZONE 'UTC')::date AS day,\n        date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS active_week\n      FROM events\n      WHERE user_id IS NOT NULL\n        AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '29 weeks') AT TIME ZONE 'UTC'\n        AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n    ),\n    daily AS (\n      SELECT active_week AS week, count(*) / 7.0 AS dau\n      FROM person_days\n      GROUP BY active_week\n    ),\n    monthly AS (\n      SELECT w.week, count(DISTINCT p.user_id) AS mau\n      FROM weeks AS w\n      JOIN person_days AS p ON p.active_week BETWEEN w.week - 21 AND w.week\n      GROUP BY w.week\n    ),\n    totals AS (\n      SELECT w.week, coalesce(d.dau, 0) AS dau, coalesce(m.mau, 0) AS mau\n      FROM weeks AS w\n      LEFT JOIN daily AS d ON d.week = w.week\n      LEFT JOIN monthly AS m ON m.week = w.week\n    )\n    SELECT week, dau AS numerator, mau AS denominator, dau / nullif(mau, 0) AS value\n    FROM totals\n    ORDER BY week;\n  bigquery: |-\n    -- Stickiness per week: the average of the week's seven daily counts of distinct active people (days in UTC) ÷ distinct active people in the four weeks (28 days) ending that Sunday. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    person_days AS (\n      SELECT DISTINCT\n        user_id,\n        DATE(occurred_at) AS day,\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS active_week\n      FROM events\n      WHERE user_id IS NOT NULL\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 29 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    ),\n    daily AS (\n      SELECT active_week AS week, COUNT(*) / 7 AS dau\n      FROM person_days\n      GROUP BY active_week\n    ),\n    monthly AS (\n      SELECT w.week, COUNT(DISTINCT p.user_id) AS mau\n      FROM weeks AS w\n      JOIN person_days AS p ON p.active_week BETWEEN DATE_SUB(w.week, INTERVAL 3 WEEK) AND w.week\n      GROUP BY w.week\n    ),\n    totals AS (\n      SELECT w.week, COALESCE(d.dau, 0) AS dau, COALESCE(m.mau, 0) AS mau\n      FROM weeks AS w\n      LEFT JOIN daily AS d ON d.week = w.week\n      LEFT JOIN monthly AS m ON m.week = w.week\n    )\n    SELECT week, dau AS numerator, mau AS denominator, SAFE_DIVIDE(dau, mau) AS value\n    FROM totals\n    ORDER BY week;\n  snowflake: |-\n    -- Stickiness per week: the average of the week's seven daily counts of distinct active people (days in UTC) ÷ distinct active people in the four weeks (28 days) ending that Sunday. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    person_days AS (\n      SELECT DISTINCT\n        user_id,\n        occurred_at::date AS day,\n        DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS active_week\n      FROM events\n      WHERE user_id IS NOT NULL\n        AND occurred_at >= DATEADD(week, -29, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n    ),\n    daily AS (\n      SELECT active_week AS week, COUNT(*) / 7.0 AS dau\n      FROM person_days\n      GROUP BY active_week\n    ),\n    monthly AS (\n      SELECT w.week, COUNT(DISTINCT p.user_id) AS mau\n      FROM weeks AS w\n      JOIN person_days AS p ON p.active_week BETWEEN DATEADD(week, -3, w.week) AND w.week\n      GROUP BY w.week\n    ),\n    totals AS (\n      SELECT w.week, COALESCE(d.dau, 0) AS dau, COALESCE(m.mau, 0) AS mau\n      FROM weeks AS w\n      LEFT JOIN daily AS d ON d.week = w.week\n      LEFT JOIN monthly AS m ON m.week = w.week\n    )\n    SELECT week, dau AS numerator, mau AS denominator, dau::float / NULLIF(mau, 0) AS value\n    FROM totals\n    ORDER BY week;\n\nnoise:\n  type: process\n  min_denominator: 500\n  volume_unit: monthly active users\n  typical: 0.18\n\nexample:\n  business: app\n  level: 0.183\n  volume: 120000\n  trend: 0\n\ndrivers:\n  - id: tracking\n    label: Same activity on both sides\n    dropped:\n      check: Did a change add people to MAU who rarely come back, such as logged-out pages or a newly tracked web view?\n      yes: MAU jumps on one platform or page with almost no daily return, while DAU barely moves.\n    spiked:\n      check: Did a background event start firing daily for people who didn't open the product?\n      yes: DAU rises on one event or app version while sessions per user don't.\n  - id: calendar\n    label: Calendar\n    feed: holidays\n    dropped:\n      check: Is it a holiday week, when daily routines break?\n      yes: The same week last year shows the same dip once aligned on the holiday.\n    spiked:\n      check: Is it a season when the product becomes a daily habit, such as the new year for a budgeting app?\n      yes: The same weeks last year show the same rise.\n  - id: mau-inflow\n    label: One-time users in MAU\n    metric: mau\n    dropped:\n      check: Did a campaign or launch bring many people who used the product once?\n      yes: MAU rises from new people who visit once and DAU barely moves, so the ratio falls without anyone using it less.\n    spiked:\n      check: Did one-time users from a past campaign just leave the 28-day window?\n      yes: MAU falls four weeks after a spike while DAU holds.\n  - id: dau-change\n    label: Daily use by regulars\n    metric: dau\n    dropped:\n      check: Did regular users come back on fewer days?\n      yes: DAU falls while MAU holds; returning people are active fewer days a week.\n    spiked:\n      check: Did a daily feature, streak or reminder make people come back on more days?\n      yes: DAU rises among existing users from the day it shipped.\n  - id: platform\n    label: Platform and releases\n    breakdown: $os\n    feed: app-stores\n    dropped:\n      check: Is the fall on one platform, after a release or OS update?\n      yes: One platform's daily use falls from the release date while the other holds.\n    spiked:\n      check: Did a release on one platform make daily use easier, for example a widget or faster start?\n      yes: One platform's daily use rises from the release date.\n  - id: notifications\n    label: Notifications\n    dropped:\n      check: Did push or reminder notifications stop, or get throttled by an OS permission change?\n      yes: Daily returns from notification opens fall while other returns hold.\n    spiked:\n      check: Did a new daily notification go live?\n      yes: DAU rises on notification opens; check that sessions per user and retention rise too, not only opens.\n\ndiagnose_order: [tracking, calendar, mau-inflow, dau-change, platform, notifications]\n\nrelated: [dau, mau, wau, sessions-per-user, week-4-retention]\n\nprose:\n  why_it_matters: >-\n    Stickiness is the share of a month's users who show up on a given day: 18% means the average\n    monthly user comes back about 5 days in 28. It separates products people use from products\n    people tried, and unlike DAU it doesn't rise just because marketing brought more people in.\n    Its level depends on how often the product is meant to be used, so compare it with its own\n    history rather than with another kind of product.\n  pitfalls:\n    - DAU and MAU must count the same activity. If MAU includes logged-out web visits and DAU only signed-in app opens, the ratio measures your tracking.\n    - Calendar-month MAU makes stickiness jump every February. Use a fixed 28-day window.\n    - The ratio rises when occasional users leave, so it can improve while the product shrinks. Read it with MAU.\n    - Products meant to be used weekly, such as payroll or reporting tools, should read WAU/MAU instead; a low DAU/MAU is no problem for them.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"stickiness","name":"Stickiness","aliases":["DAU/MAU","DAU/MAU ratio","Stickiness ratio","Daily to monthly active ratio"],"family":"engagement","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of a month's users who show up on a typical day, the week's average DAU divided by MAU for the 28 days ending that Sunday.","formula":"Average daily active users this week ÷ distinct active people in the 28 days ending Sunday 23:59 UTC"},"events":[{"name":"*","description":"Any event a person sends, counted the same way on both sides of the ratio.","also_called":["All events","Any event","Active event"],"properties":[{"name":"$os","description":"The operating system, for splitting by platform."}]}],"numerator":{"label":"Average daily active users","aggregate":"unique_users","event":"*"},"queries":{"hogql":"-- Stickiness per week: the average of the week's seven daily counts of distinct active people (days in UTC) ÷ distinct active people in the four weeks (28 days) ending that Sunday. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(d.person_days, 0) / 7 AS numerator,\n  coalesce(m.people, 0) AS denominator,\n  if(denominator = 0, NULL, numerator / denominator) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(1, 27))) AS week\n) AS w\nLEFT JOIN (\n  SELECT toMonday(day) AS week, count() AS person_days\n  FROM (\n    SELECT DISTINCT person_id, toDate(toTimeZone(timestamp, 'UTC')) AS day\n    FROM events\n    WHERE person_id IS NOT NULL\n      AND timestamp >= now() - toIntervalWeek(27)\n      AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n  )\n  GROUP BY week\n) AS d ON d.week = w.week\nLEFT JOIN (\n  SELECT week, count(DISTINCT person_id) AS people\n  FROM (\n    SELECT person_id, active_week + toIntervalWeek(arrayJoin([0, 1, 2, 3])) AS week\n    FROM (\n      SELECT DISTINCT person_id, toMonday(toTimeZone(timestamp, 'UTC')) AS active_week\n      FROM events\n      WHERE person_id IS NOT NULL\n        AND timestamp >= now() - toIntervalWeek(30)\n        AND toMonday(toTimeZone(timestamp, 'UTC')) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(29) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n    )\n  )\n  WHERE week BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(26) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(1)\n  GROUP BY week\n) AS m ON m.week = w.week\nORDER BY week","postgres":"-- Stickiness per week: the average of the week's seven daily counts of distinct active people (days in UTC) ÷ distinct active people in the four weeks (28 days) ending that Sunday. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '26 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week',\n    interval '1 week'\n  ) AS g(week)\n),\nperson_days AS (\n  SELECT DISTINCT\n    user_id,\n    (occurred_at AT TIME ZONE 'UTC')::date AS day,\n    date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS active_week\n  FROM events\n  WHERE user_id IS NOT NULL\n    AND occurred_at >= (date_trunc('week', now() AT TIME ZONE 'UTC') - interval '29 weeks') AT TIME ZONE 'UTC'\n    AND occurred_at < date_trunc('week', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'\n),\ndaily AS (\n  SELECT active_week AS week, count(*) / 7.0 AS dau\n  FROM person_days\n  GROUP BY active_week\n),\nmonthly AS (\n  SELECT w.week, count(DISTINCT p.user_id) AS mau\n  FROM weeks AS w\n  JOIN person_days AS p ON p.active_week BETWEEN w.week - 21 AND w.week\n  GROUP BY w.week\n),\ntotals AS (\n  SELECT w.week, coalesce(d.dau, 0) AS dau, coalesce(m.mau, 0) AS mau\n  FROM weeks AS w\n  LEFT JOIN daily AS d ON d.week = w.week\n  LEFT JOIN monthly AS m ON m.week = w.week\n)\nSELECT week, dau AS numerator, mau AS denominator, dau / nullif(mau, 0) AS value\nFROM totals\nORDER BY week;","bigquery":"-- Stickiness per week: the average of the week's seven daily counts of distinct active people (days in UTC) ÷ distinct active people in the four weeks (28 days) ending that Sunday. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK), INTERVAL 1 WEEK)) AS week\n),\nperson_days AS (\n  SELECT DISTINCT\n    user_id,\n    DATE(occurred_at) AS day,\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS active_week\n  FROM events\n  WHERE user_id IS NOT NULL\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 29 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n),\ndaily AS (\n  SELECT active_week AS week, COUNT(*) / 7 AS dau\n  FROM person_days\n  GROUP BY active_week\n),\nmonthly AS (\n  SELECT w.week, COUNT(DISTINCT p.user_id) AS mau\n  FROM weeks AS w\n  JOIN person_days AS p ON p.active_week BETWEEN DATE_SUB(w.week, INTERVAL 3 WEEK) AND w.week\n  GROUP BY w.week\n),\ntotals AS (\n  SELECT w.week, COALESCE(d.dau, 0) AS dau, COALESCE(m.mau, 0) AS mau\n  FROM weeks AS w\n  LEFT JOIN daily AS d ON d.week = w.week\n  LEFT JOIN monthly AS m ON m.week = w.week\n)\nSELECT week, dau AS numerator, mau AS denominator, SAFE_DIVIDE(dau, mau) AS value\nFROM totals\nORDER BY week;","snowflake":"-- Stickiness per week: the average of the week's seven daily counts of distinct active people (days in UTC) ÷ distinct active people in the four weeks (28 days) ending that Sunday. Last 26 complete weeks (Monday 00:00 UTC), oldest first.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 * ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nperson_days AS (\n  SELECT DISTINCT\n    user_id,\n    occurred_at::date AS day,\n    DATEADD(day, 1 - DAYOFWEEKISO(occurred_at), occurred_at::date) AS active_week\n  FROM events\n  WHERE user_id IS NOT NULL\n    AND occurred_at >= DATEADD(week, -29, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND occurred_at < DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)\n),\ndaily AS (\n  SELECT active_week AS week, COUNT(*) / 7.0 AS dau\n  FROM person_days\n  GROUP BY active_week\n),\nmonthly AS (\n  SELECT w.week, COUNT(DISTINCT p.user_id) AS mau\n  FROM weeks AS w\n  JOIN person_days AS p ON p.active_week BETWEEN DATEADD(week, -3, w.week) AND w.week\n  GROUP BY w.week\n),\ntotals AS (\n  SELECT w.week, COALESCE(d.dau, 0) AS dau, COALESCE(m.mau, 0) AS mau\n  FROM weeks AS w\n  LEFT JOIN daily AS d ON d.week = w.week\n  LEFT JOIN monthly AS m ON m.week = w.week\n)\nSELECT week, dau AS numerator, mau AS denominator, dau::float / NULLIF(mau, 0) AS value\nFROM totals\nORDER BY week;"},"noise":{"type":"process","min_denominator":500,"volume_unit":"monthly active users","typical":0.18},"example":{"business":"app","level":0.183,"volume":120000,"trend":0},"drivers":[{"id":"tracking","label":"Same activity on both sides","dropped":{"check":"Did a change add people to MAU who rarely come back, such as logged-out pages or a newly tracked web view?","yes":"MAU jumps on one platform or page with almost no daily return, while DAU barely moves."},"spiked":{"check":"Did a background event start firing daily for people who didn't open the product?","yes":"DAU rises on one event or app version while sessions per user don't."}},{"id":"calendar","label":"Calendar","feed":"holidays","dropped":{"check":"Is it a holiday week, when daily routines break?","yes":"The same week last year shows the same dip once aligned on the holiday."},"spiked":{"check":"Is it a season when the product becomes a daily habit, such as the new year for a budgeting app?","yes":"The same weeks last year show the same rise."}},{"id":"mau-inflow","label":"One-time users in MAU","metric":"mau","dropped":{"check":"Did a campaign or launch bring many people who used the product once?","yes":"MAU rises from new people who visit once and DAU barely moves, so the ratio falls without anyone using it less."},"spiked":{"check":"Did one-time users from a past campaign just leave the 28-day window?","yes":"MAU falls four weeks after a spike while DAU holds."}},{"id":"dau-change","label":"Daily use by regulars","metric":"dau","dropped":{"check":"Did regular users come back on fewer days?","yes":"DAU falls while MAU holds; returning people are active fewer days a week."},"spiked":{"check":"Did a daily feature, streak or reminder make people come back on more days?","yes":"DAU rises among existing users from the day it shipped."}},{"id":"platform","label":"Platform and releases","breakdown":"$os","feed":"app-stores","dropped":{"check":"Is the fall on one platform, after a release or OS update?","yes":"One platform's daily use falls from the release date while the other holds."},"spiked":{"check":"Did a release on one platform make daily use easier, for example a widget or faster start?","yes":"One platform's daily use rises from the release date."}},{"id":"notifications","label":"Notifications","dropped":{"check":"Did push or reminder notifications stop, or get throttled by an OS permission change?","yes":"Daily returns from notification opens fall while other returns hold."},"spiked":{"check":"Did a new daily notification go live?","yes":"DAU rises on notification opens; check that sessions per user and retention rise too, not only opens."}}],"diagnose_order":["tracking","calendar","mau-inflow","dau-change","platform","notifications"],"related":["dau","mau","wau","sessions-per-user","week-4-retention"],"prose":{"why_it_matters":"Stickiness is the share of a month's users who show up on a given day: 18% means the average monthly user comes back about 5 days in 28. It separates products people use from products people tried, and unlike DAU it doesn't rise just because marketing brought more people in. Its level depends on how often the product is meant to be used, so compare it with its own history rather than with another kind of product.","pitfalls":["DAU and MAU must count the same activity. If MAU includes logged-out web visits and DAU only signed-in app opens, the ratio measures your tracking.","Calendar-month MAU makes stickiness jump every February. Use a fixed 28-day window.","The ratio rises when occasional users leave, so it can improve while the product shrinks. Read it with MAU.","Products meant to be used weekly, such as payroll or reporting tools, should read WAU/MAU instead; a low DAU/MAU is no problem for them."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "time-to-value": { yaml: "id: time-to-value\nname: Time to value\naliases:\n  - TTV\n  - Time to first value\n  - Time to activation\n  - Time to aha\nfamily: activation\nkind: duration\nduration_unit: hours\npolarity: down-is-good\n\ndefinition:\n  one_line: The median time from signing up to first reaching the activation milestone, among people who got there within 7 days.\n  formula: Median of (first activation − signup) in hours, over signups who activated within 7 days, by signup week\n\nevents:\n  - name: signed_up\n    description: An account created, sent by the server when the account exists, not when the form is submitted.\n    also_called: [sign_up, Signed Up, user_signed_up, account_created]\n    properties:\n      - name: plan\n        description: The plan chosen at signup, if any.\n  - name: activated\n    description: The product's key action, the one that best predicts a user is still active weeks later, such as a first report shared or a first project with data.\n    also_called: [Activated, user_activated, aha_moment]\n    properties:\n      - name: milestone\n        description: Which milestone fired, when a product tracks more than one.\n\nnumerator:\n  label: Signups who activated within 7 days\n  aggregate: unique_users\n  event: activated\n\nqueries:\n  hogql: |-\n    -- Time to value: median hours from a person's first signup to their first activation, among people who activated within 7 days, by signup week. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(m.people, 0) AS activated_users,\n      if(activated_users = 0, NULL, m.median_hours) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(2, 28))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, count() AS people, quantile(0.5)(hours) AS median_hours\n      FROM (\n        SELECT\n          toMonday(s.signup_at) AS week,\n          s.person_id AS person_id,\n          dateDiff('millisecond', s.signup_at, min(a.ts)) / 3600000 AS hours\n        FROM (\n          SELECT person_id, min(toTimeZone(timestamp, 'UTC')) AS signup_at\n          FROM events\n          WHERE event = 'signed_up'\n            AND person_id IS NOT NULL\n          GROUP BY person_id\n        ) AS s\n        INNER JOIN (\n          SELECT person_id, toTimeZone(timestamp, 'UTC') AS ts\n          FROM events\n          WHERE event = 'activated'\n            AND timestamp >= now() - toIntervalWeek(29)\n        ) AS a ON a.person_id = s.person_id\n        WHERE toMonday(s.signup_at) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(27) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(2)\n          AND a.ts >= s.signup_at\n          AND a.ts < s.signup_at + toIntervalDay(7)\n        GROUP BY week, person_id, s.signup_at\n      )\n      GROUP BY week\n    ) AS m ON m.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Time to value: median hours from a person's first signup to their first activation, among people who activated within 7 days, by signup week. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '27 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '2 weeks',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    signups AS (\n      SELECT user_id, min(occurred_at AT TIME ZONE 'UTC') AS signup_at\n      FROM events\n      WHERE event_name = 'signed_up'\n        AND user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    first_value AS (\n      SELECT\n        date_trunc('week', s.signup_at)::date AS week,\n        extract(epoch FROM min(a.occurred_at AT TIME ZONE 'UTC') - s.signup_at) / 3600 AS hours\n      FROM signups AS s\n      JOIN events AS a\n        ON a.user_id = s.user_id\n       AND a.event_name = 'activated'\n       AND a.occurred_at AT TIME ZONE 'UTC' >= s.signup_at\n       AND a.occurred_at AT TIME ZONE 'UTC' < s.signup_at + interval '7 days'\n      WHERE s.signup_at >= date_trunc('week', now() AT TIME ZONE 'UTC') - interval '27 weeks'\n        AND s.signup_at < date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week'\n      GROUP BY s.user_id, s.signup_at\n    ),\n    medians AS (\n      SELECT week, count(*) AS activated_users, percentile_cont(0.5) WITHIN GROUP (ORDER BY hours) AS median_hours\n      FROM first_value\n      GROUP BY week\n    )\n    SELECT w.week, coalesce(m.activated_users, 0) AS activated_users, m.median_hours AS value\n    FROM weeks AS w\n    LEFT JOIN medians AS m ON m.week = w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Time to value: median hours from a person's first signup to their first activation, among people who activated within 7 days, by signup week. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 27 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 2 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    signups AS (\n      SELECT user_id, MIN(occurred_at) AS signup_at\n      FROM events\n      WHERE event_name = 'signed_up'\n        AND user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    first_value AS (\n      SELECT\n        DATE_TRUNC(DATE(s.signup_at), ISOWEEK) AS week,\n        TIMESTAMP_DIFF(MIN(a.occurred_at), s.signup_at, MILLISECOND) / 3600000 AS hours\n      FROM signups AS s\n      JOIN events AS a\n        ON a.user_id = s.user_id\n       AND a.event_name = 'activated'\n       AND a.occurred_at >= s.signup_at\n       AND a.occurred_at < TIMESTAMP_ADD(s.signup_at, INTERVAL 7 DAY)\n      WHERE s.signup_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 27 WEEK))\n        AND s.signup_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK))\n      GROUP BY s.user_id, s.signup_at\n    ),\n    medians AS (\n      SELECT DISTINCT\n        week,\n        COUNT(*) OVER (PARTITION BY week) AS activated_users,\n        PERCENTILE_CONT(hours, 0.5) OVER (PARTITION BY week) AS median_hours\n      FROM first_value\n    )\n    SELECT w.week, COALESCE(m.activated_users, 0) AS activated_users, m.median_hours AS value\n    FROM weeks AS w\n    LEFT JOIN medians AS m ON m.week = w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Time to value: median hours from a person's first signup to their first activation, among people who activated within 7 days, by signup week. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -1 - ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    signups AS (\n      SELECT user_id, MIN(occurred_at) AS signup_at\n      FROM events\n      WHERE event_name = 'signed_up'\n        AND user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    first_value AS (\n      SELECT\n        DATEADD(day, 1 - DAYOFWEEKISO(s.signup_at), s.signup_at::date) AS week,\n        DATEDIFF('millisecond', s.signup_at, MIN(a.occurred_at)) / 3600000 AS hours\n      FROM signups AS s\n      JOIN events AS a\n        ON a.user_id = s.user_id\n       AND a.event_name = 'activated'\n       AND a.occurred_at >= s.signup_at\n       AND a.occurred_at < DATEADD(day, 7, s.signup_at)\n      WHERE s.signup_at >= DATEADD(week, -27, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND s.signup_at < DATEADD(week, -1, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n      GROUP BY s.user_id, s.signup_at\n    ),\n    medians AS (\n      SELECT week, COUNT(*) AS activated_users, MEDIAN(hours) AS median_hours\n      FROM first_value\n      GROUP BY week\n    )\n    SELECT w.week, COALESCE(m.activated_users, 0) AS activated_users, m.median_hours AS value\n    FROM weeks AS w\n    LEFT JOIN medians AS m ON m.week = w.week\n    ORDER BY w.week;\n\nnoise:\n  type: process\n  min_denominator: 30\n  volume_unit: activated signups in the cohort\n  typical: 22\n\nexample:\n  business: saas\n  level: 22\n  volume: 750\n  trend: -0.1\n\ndrivers:\n  - id: tracking\n    label: Activation event\n    dropped:\n      check: Was the milestone redefined to an earlier step, or does the event now fire sooner in the flow?\n      yes: Time to value falls overnight with no product change, and activation rate jumps on the same day.\n    spiked:\n      check: Is the activation event arriving late, from a batch job, a delayed sync or a server queue?\n      yes: Event timestamps lag the action in the product, often by a fixed number of hours.\n  - id: calendar\n    label: Weekends and holidays\n    feed: holidays\n    dropped:\n      check: Did more of the cohort sign up early in the week, or was the previous cohort slowed by a holiday?\n      yes: A larger share of the cohort signed up Monday to Wednesday than usual, or last week's cohort had a holiday in its first days.\n    spiked:\n      check: Did the cohort's first days include a holiday or a long weekend, so people signed up and came back later?\n      yes: The same cohort weeks last year show the same slower time.\n  - id: activation-mix\n    label: Who activated\n    metric: activation-rate\n    dropped:\n      check: Did slow users stop activating at all? The median gets faster when only the quick ones make it.\n      yes: Activation rate fell for the same cohorts while time to value improved.\n    spiked:\n      check: Did more slow-moving users activate late in the window, from a day-5 email or a sales follow-up?\n      yes: Activation rate rose for the same cohorts, and the extra activations land late in the 7 days.\n  - id: onboarding\n    label: Onboarding\n    metric: onboarding-completion-rate\n    dropped:\n      check: Did onboarding get shorter, or a template or sample data let people skip setup?\n      yes: Onboarding completion rose or took less time for the same cohorts.\n    spiked:\n      check: Was a step added to onboarding, or did one start failing and need retries?\n      yes: Time between signup and onboarding completion grew for the same cohorts.\n  - id: setup-dependency\n    label: Waiting on setup\n    dropped:\n      check: Was a slow dependency removed, such as email verification, an approval or a data import?\n      yes: The step that used to wait for an outside event now completes in the first session.\n    spiked:\n      check: Is a dependency slower, such as an integration's approval, an import queue or verification emails?\n      yes: Time between starting and finishing that step grew, while the rest of the path held.\n  - id: segment\n    label: Plan and company size\n    breakdown: plan\n    dropped:\n      check: Did the mix shift toward a plan or company size that sets up faster?\n      yes: Time to value within each plan held while the mix moved.\n    spiked:\n      check: Did the mix shift toward larger teams, which take longer to set up?\n      yes: Time to value within each plan held while the mix moved toward the slower one.\n\ndiagnose_order: [tracking, calendar, activation-mix, onboarding, setup-dependency, segment]\n\nrelated: [activation-rate, onboarding-completion-rate, signups, week-1-retention, trial-conversion-rate]\n\nprose:\n  why_it_matters: >-\n    Every hour between signup and value is an hour in which a new user can leave. Time to value is\n    the speed of activation, as activation rate is its reach. At Copperline the median user who\n    activates gets there in about 22 hours, so a weekend in the middle of setup is enough to move it.\n  pitfalls:\n    - It only counts people who got there. When slow users stop activating at all, the median gets faster while the business gets worse, so always read it next to activation rate.\n    - Use the median, not the mean. A few accounts that take six days pull the average far from what a typical user experiences.\n    - Measured in calendar hours, a Friday signup waits through the weekend. A shift in which weekdays people sign up moves it with no product change.\n    - Only cohorts whose 7 days have closed are reported, so the latest point is the signups of two weeks ago.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"time-to-value","name":"Time to value","aliases":["TTV","Time to first value","Time to activation","Time to aha"],"family":"activation","kind":"duration","duration_unit":"hours","polarity":"down-is-good","definition":{"one_line":"The median time from signing up to first reaching the activation milestone, among people who got there within 7 days.","formula":"Median of (first activation − signup) in hours, over signups who activated within 7 days, by signup week"},"events":[{"name":"signed_up","description":"An account created, sent by the server when the account exists, not when the form is submitted.","also_called":["sign_up","Signed Up","user_signed_up","account_created"],"properties":[{"name":"plan","description":"The plan chosen at signup, if any."}]},{"name":"activated","description":"The product's key action, the one that best predicts a user is still active weeks later, such as a first report shared or a first project with data.","also_called":["Activated","user_activated","aha_moment"],"properties":[{"name":"milestone","description":"Which milestone fired, when a product tracks more than one."}]}],"numerator":{"label":"Signups who activated within 7 days","aggregate":"unique_users","event":"activated"},"queries":{"hogql":"-- Time to value: median hours from a person's first signup to their first activation, among people who activated within 7 days, by signup week. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(m.people, 0) AS activated_users,\n  if(activated_users = 0, NULL, m.median_hours) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(2, 28))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, count() AS people, quantile(0.5)(hours) AS median_hours\n  FROM (\n    SELECT\n      toMonday(s.signup_at) AS week,\n      s.person_id AS person_id,\n      dateDiff('millisecond', s.signup_at, min(a.ts)) / 3600000 AS hours\n    FROM (\n      SELECT person_id, min(toTimeZone(timestamp, 'UTC')) AS signup_at\n      FROM events\n      WHERE event = 'signed_up'\n        AND person_id IS NOT NULL\n      GROUP BY person_id\n    ) AS s\n    INNER JOIN (\n      SELECT person_id, toTimeZone(timestamp, 'UTC') AS ts\n      FROM events\n      WHERE event = 'activated'\n        AND timestamp >= now() - toIntervalWeek(29)\n    ) AS a ON a.person_id = s.person_id\n    WHERE toMonday(s.signup_at) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(27) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(2)\n      AND a.ts >= s.signup_at\n      AND a.ts < s.signup_at + toIntervalDay(7)\n    GROUP BY week, person_id, s.signup_at\n  )\n  GROUP BY week\n) AS m ON m.week = w.week\nORDER BY week","postgres":"-- Time to value: median hours from a person's first signup to their first activation, among people who activated within 7 days, by signup week. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '27 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '2 weeks',\n    interval '1 week'\n  ) AS g(week)\n),\nsignups AS (\n  SELECT user_id, min(occurred_at AT TIME ZONE 'UTC') AS signup_at\n  FROM events\n  WHERE event_name = 'signed_up'\n    AND user_id IS NOT NULL\n  GROUP BY user_id\n),\nfirst_value AS (\n  SELECT\n    date_trunc('week', s.signup_at)::date AS week,\n    extract(epoch FROM min(a.occurred_at AT TIME ZONE 'UTC') - s.signup_at) / 3600 AS hours\n  FROM signups AS s\n  JOIN events AS a\n    ON a.user_id = s.user_id\n   AND a.event_name = 'activated'\n   AND a.occurred_at AT TIME ZONE 'UTC' >= s.signup_at\n   AND a.occurred_at AT TIME ZONE 'UTC' < s.signup_at + interval '7 days'\n  WHERE s.signup_at >= date_trunc('week', now() AT TIME ZONE 'UTC') - interval '27 weeks'\n    AND s.signup_at < date_trunc('week', now() AT TIME ZONE 'UTC') - interval '1 week'\n  GROUP BY s.user_id, s.signup_at\n),\nmedians AS (\n  SELECT week, count(*) AS activated_users, percentile_cont(0.5) WITHIN GROUP (ORDER BY hours) AS median_hours\n  FROM first_value\n  GROUP BY week\n)\nSELECT w.week, coalesce(m.activated_users, 0) AS activated_users, m.median_hours AS value\nFROM weeks AS w\nLEFT JOIN medians AS m ON m.week = w.week\nORDER BY w.week;","bigquery":"-- Time to value: median hours from a person's first signup to their first activation, among people who activated within 7 days, by signup week. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 27 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 2 WEEK), INTERVAL 1 WEEK)) AS week\n),\nsignups AS (\n  SELECT user_id, MIN(occurred_at) AS signup_at\n  FROM events\n  WHERE event_name = 'signed_up'\n    AND user_id IS NOT NULL\n  GROUP BY user_id\n),\nfirst_value AS (\n  SELECT\n    DATE_TRUNC(DATE(s.signup_at), ISOWEEK) AS week,\n    TIMESTAMP_DIFF(MIN(a.occurred_at), s.signup_at, MILLISECOND) / 3600000 AS hours\n  FROM signups AS s\n  JOIN events AS a\n    ON a.user_id = s.user_id\n   AND a.event_name = 'activated'\n   AND a.occurred_at >= s.signup_at\n   AND a.occurred_at < TIMESTAMP_ADD(s.signup_at, INTERVAL 7 DAY)\n  WHERE s.signup_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 27 WEEK))\n    AND s.signup_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK))\n  GROUP BY s.user_id, s.signup_at\n),\nmedians AS (\n  SELECT DISTINCT\n    week,\n    COUNT(*) OVER (PARTITION BY week) AS activated_users,\n    PERCENTILE_CONT(hours, 0.5) OVER (PARTITION BY week) AS median_hours\n  FROM first_value\n)\nSELECT w.week, COALESCE(m.activated_users, 0) AS activated_users, m.median_hours AS value\nFROM weeks AS w\nLEFT JOIN medians AS m ON m.week = w.week\nORDER BY w.week;","snowflake":"-- Time to value: median hours from a person's first signup to their first activation, among people who activated within 7 days, by signup week. Signup weeks 27 to 2 weeks before this one (Monday 00:00 UTC), oldest first; last week's signups are left out until their 7 days close.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -1 - ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nsignups AS (\n  SELECT user_id, MIN(occurred_at) AS signup_at\n  FROM events\n  WHERE event_name = 'signed_up'\n    AND user_id IS NOT NULL\n  GROUP BY user_id\n),\nfirst_value AS (\n  SELECT\n    DATEADD(day, 1 - DAYOFWEEKISO(s.signup_at), s.signup_at::date) AS week,\n    DATEDIFF('millisecond', s.signup_at, MIN(a.occurred_at)) / 3600000 AS hours\n  FROM signups AS s\n  JOIN events AS a\n    ON a.user_id = s.user_id\n   AND a.event_name = 'activated'\n   AND a.occurred_at >= s.signup_at\n   AND a.occurred_at < DATEADD(day, 7, s.signup_at)\n  WHERE s.signup_at >= DATEADD(week, -27, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND s.signup_at < DATEADD(week, -1, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n  GROUP BY s.user_id, s.signup_at\n),\nmedians AS (\n  SELECT week, COUNT(*) AS activated_users, MEDIAN(hours) AS median_hours\n  FROM first_value\n  GROUP BY week\n)\nSELECT w.week, COALESCE(m.activated_users, 0) AS activated_users, m.median_hours AS value\nFROM weeks AS w\nLEFT JOIN medians AS m ON m.week = w.week\nORDER BY w.week;"},"noise":{"type":"process","min_denominator":30,"volume_unit":"activated signups in the cohort","typical":22},"example":{"business":"saas","level":22,"volume":750,"trend":-0.1},"drivers":[{"id":"tracking","label":"Activation event","dropped":{"check":"Was the milestone redefined to an earlier step, or does the event now fire sooner in the flow?","yes":"Time to value falls overnight with no product change, and activation rate jumps on the same day."},"spiked":{"check":"Is the activation event arriving late, from a batch job, a delayed sync or a server queue?","yes":"Event timestamps lag the action in the product, often by a fixed number of hours."}},{"id":"calendar","label":"Weekends and holidays","feed":"holidays","dropped":{"check":"Did more of the cohort sign up early in the week, or was the previous cohort slowed by a holiday?","yes":"A larger share of the cohort signed up Monday to Wednesday than usual, or last week's cohort had a holiday in its first days."},"spiked":{"check":"Did the cohort's first days include a holiday or a long weekend, so people signed up and came back later?","yes":"The same cohort weeks last year show the same slower time."}},{"id":"activation-mix","label":"Who activated","metric":"activation-rate","dropped":{"check":"Did slow users stop activating at all? The median gets faster when only the quick ones make it.","yes":"Activation rate fell for the same cohorts while time to value improved."},"spiked":{"check":"Did more slow-moving users activate late in the window, from a day-5 email or a sales follow-up?","yes":"Activation rate rose for the same cohorts, and the extra activations land late in the 7 days."}},{"id":"onboarding","label":"Onboarding","metric":"onboarding-completion-rate","dropped":{"check":"Did onboarding get shorter, or a template or sample data let people skip setup?","yes":"Onboarding completion rose or took less time for the same cohorts."},"spiked":{"check":"Was a step added to onboarding, or did one start failing and need retries?","yes":"Time between signup and onboarding completion grew for the same cohorts."}},{"id":"setup-dependency","label":"Waiting on setup","dropped":{"check":"Was a slow dependency removed, such as email verification, an approval or a data import?","yes":"The step that used to wait for an outside event now completes in the first session."},"spiked":{"check":"Is a dependency slower, such as an integration's approval, an import queue or verification emails?","yes":"Time between starting and finishing that step grew, while the rest of the path held."}},{"id":"segment","label":"Plan and company size","breakdown":"plan","dropped":{"check":"Did the mix shift toward a plan or company size that sets up faster?","yes":"Time to value within each plan held while the mix moved."},"spiked":{"check":"Did the mix shift toward larger teams, which take longer to set up?","yes":"Time to value within each plan held while the mix moved toward the slower one."}}],"diagnose_order":["tracking","calendar","activation-mix","onboarding","setup-dependency","segment"],"related":["activation-rate","onboarding-completion-rate","signups","week-1-retention","trial-conversion-rate"],"prose":{"why_it_matters":"Every hour between signup and value is an hour in which a new user can leave. Time to value is the speed of activation, as activation rate is its reach. At Copperline the median user who activates gets there in about 22 hours, so a weekend in the middle of setup is enough to move it.","pitfalls":["It only counts people who got there. When slow users stop activating at all, the median gets faster while the business gets worse, so always read it next to activation rate.","Use the median, not the mean. A few accounts that take six days pull the average far from what a typical user experiences.","Measured in calendar hours, a Friday signup waits through the weekend. A shift in which weekdays people sign up moves it with no product change.","Only cohorts whose 7 days have closed are reported, so the latest point is the signups of two weeks ago."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "trial-conversion-rate": { yaml: "id: trial-conversion-rate\nname: Trial conversion rate\naliases:\n  - Trial-to-paid conversion\n  - Trial to paid rate\n  - Free trial conversion rate\nfamily: activation\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of trials started in a week that became a paid subscription within 30 days of the trial start.\n  formula: Trials that started a paid subscription within 30 days ÷ trials started, by trial start week\n\nevents:\n  - name: trial_started\n    description: A free trial of a paid plan began, sent by the billing system or the server.\n    also_called: [Trial Started, start_trial, customer.subscription.created (status trialing)]\n    properties:\n      - name: plan\n        description: The plan being trialled.\n  - name: subscription_started\n    description: The first paid period of a subscription, sent by the billing system when the first payment succeeds.\n    also_called: [Subscription Started, customer.subscription.updated (trialing to active), invoice.paid (first)]\n    properties:\n      - name: subscription_id\n        description: The billing system's subscription id.\n      - name: plan\n        description: The plan subscribed to.\n\nnumerator:\n  label: Trials that converted within 30 days\n  aggregate: unique_users\n  event: subscription_started\ndenominator:\n  label: People who started a trial\n  aggregate: unique_users\n  event: trial_started\n\nqueries:\n  hogql: |-\n    -- Trial conversion rate: of people whose first trial started in each week, the share who started a paid subscription within 30 days of the trial start. Trial weeks 31 to 6 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 30 days close.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(c.converted_people, 0) AS numerator,\n      coalesce(c.people, 0) AS denominator,\n      if(denominator = 0, NULL, numerator / denominator) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(6, 32))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, countIf(converted) AS converted_people, count() AS people\n      FROM (\n        SELECT\n          toMonday(s.start_at) AS week,\n          s.person_id AS person_id,\n          countIf(x.ts >= s.start_at AND x.ts < s.start_at + toIntervalDay(30)) > 0 AS converted\n        FROM (\n          SELECT person_id, min(toTimeZone(timestamp, 'UTC')) AS start_at\n          FROM events\n          WHERE event = 'trial_started'\n            AND person_id IS NOT NULL\n          GROUP BY person_id\n        ) AS s\n        LEFT JOIN (\n          SELECT person_id, toTimeZone(timestamp, 'UTC') AS ts\n          FROM events\n          WHERE event = 'subscription_started'\n            AND timestamp >= now() - toIntervalWeek(33)\n        ) AS x ON x.person_id = s.person_id\n        WHERE toMonday(s.start_at) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(31) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(6)\n        GROUP BY week, person_id\n      )\n      GROUP BY week\n    ) AS c ON c.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Trial conversion rate: of people whose first trial started in each week, the share who started a paid subscription within 30 days of the trial start. Trial weeks 31 to 6 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 30 days close.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '31 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '6 weeks',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    starts AS (\n      SELECT user_id, min(occurred_at AT TIME ZONE 'UTC') AS start_at\n      FROM events\n      WHERE event_name = 'trial_started'\n        AND user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    cohort AS (\n      SELECT\n        date_trunc('week', s.start_at)::date AS week,\n        s.user_id,\n        count(x.occurred_at) > 0 AS converted\n      FROM starts AS s\n      LEFT JOIN events AS x\n        ON x.user_id = s.user_id\n       AND x.event_name = 'subscription_started'\n       AND x.occurred_at AT TIME ZONE 'UTC' >= s.start_at\n       AND x.occurred_at AT TIME ZONE 'UTC' < s.start_at + interval '30 days'\n      WHERE s.start_at >= date_trunc('week', now() AT TIME ZONE 'UTC') - interval '31 weeks'\n        AND s.start_at < date_trunc('week', now() AT TIME ZONE 'UTC') - interval '5 weeks'\n      GROUP BY 1, 2\n    )\n    SELECT\n      w.week,\n      count(c.user_id) FILTER (WHERE c.converted) AS numerator,\n      count(c.user_id) AS denominator,\n      (count(c.user_id) FILTER (WHERE c.converted))::numeric / nullif(count(c.user_id), 0) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Trial conversion rate: of people whose first trial started in each week, the share who started a paid subscription within 30 days of the trial start. Trial weeks 31 to 6 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 30 days close.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 31 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 6 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    starts AS (\n      SELECT user_id, MIN(occurred_at) AS start_at\n      FROM events\n      WHERE event_name = 'trial_started'\n        AND user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    cohort AS (\n      SELECT\n        DATE_TRUNC(DATE(s.start_at), ISOWEEK) AS week,\n        s.user_id,\n        COUNT(x.occurred_at) > 0 AS converted\n      FROM starts AS s\n      LEFT JOIN events AS x\n        ON x.user_id = s.user_id\n       AND x.event_name = 'subscription_started'\n       AND x.occurred_at >= s.start_at\n       AND x.occurred_at < TIMESTAMP_ADD(s.start_at, INTERVAL 30 DAY)\n      WHERE s.start_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 31 WEEK))\n        AND s.start_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 5 WEEK))\n      GROUP BY week, s.user_id\n    )\n    SELECT\n      w.week,\n      COUNTIF(c.converted) AS numerator,\n      COUNT(c.user_id) AS denominator,\n      SAFE_DIVIDE(COUNTIF(c.converted), COUNT(c.user_id)) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Trial conversion rate: of people whose first trial started in each week, the share who started a paid subscription within 30 days of the trial start. Trial weeks 31 to 6 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 30 days close.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -5 - ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    starts AS (\n      SELECT user_id, MIN(occurred_at) AS start_at\n      FROM events\n      WHERE event_name = 'trial_started'\n        AND user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    cohort AS (\n      SELECT\n        DATEADD(day, 1 - DAYOFWEEKISO(s.start_at), s.start_at::date) AS week,\n        s.user_id,\n        COUNT(x.occurred_at) > 0 AS converted\n      FROM starts AS s\n      LEFT JOIN events AS x\n        ON x.user_id = s.user_id\n       AND x.event_name = 'subscription_started'\n       AND x.occurred_at >= s.start_at\n       AND x.occurred_at < DATEADD(day, 30, s.start_at)\n      WHERE s.start_at >= DATEADD(week, -31, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND s.start_at < DATEADD(week, -5, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n      GROUP BY 1, 2\n    )\n    SELECT\n      w.week,\n      COUNT_IF(c.converted) AS numerator,\n      COUNT(c.user_id) AS denominator,\n      COUNT_IF(c.converted)::float / NULLIF(COUNT(c.user_id), 0) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n\nnoise:\n  type: binomial\n  min_denominator: 50\n  volume_unit: trials in the cohort\n  typical: 0.18\n  reference_volumes: [50, 150, 500, 2000]\n\nexample:\n  business: saas\n  level: 0.18\n  volume: 160\n  trend: 0.04\n\ndrivers:\n  - id: billing\n    label: Billing and first charges\n    feed: stripe\n    dropped:\n      check: Did first charges at trial end start failing, or did subscription events stop syncing?\n      yes: Failed first payments rise, or paid subscriptions in the billing dashboard exceed those recorded.\n    spiked:\n      check: Is a billing migration or plan change firing subscription_started for people who were already paying?\n      yes: Many converters had an earlier paid subscription under another id.\n  - id: calendar\n    label: Holidays at trial end\n    feed: holidays\n    dropped:\n      check: Did the cohort's trials end over a holiday, when nobody was there to approve the purchase?\n      yes: The same cohort weeks last year show the same dip.\n    spiked:\n      check: Did the cohort's trials end at a quarter or budget-year start?\n      yes: The same cohort weeks last year show the same rise.\n  - id: trial-terms\n    label: Trial terms\n    dropped:\n      check: Did the cohort get easier terms, such as no card required or a longer trial that doesn't fit the 30 days?\n      yes: Trial starts jumped for the cohort and the conversion drop starts with the first cohort on the new terms.\n    spiked:\n      check: Did the cohort get stricter terms, such as a card required up front?\n      yes: Trial starts fell for the cohort and conversion rose from the first cohort on the new terms.\n  - id: trial-quality\n    label: Who started a trial\n    metric: trial-starts\n    breakdown: plan\n    dropped:\n      check: Did a promotion or a campaign fill the cohort with low-intent trials?\n      yes: Trial starts rose that week from one source or plan that converts far below the rest.\n    spiked:\n      check: Did a low-intent source stop, leaving a smaller, more committed cohort?\n      yes: Trial starts fell that week while conversion from the other sources held.\n  - id: activation\n    label: Activation during the trial\n    metric: activation-rate\n    dropped:\n      check: Did fewer trialists reach the activation milestone during the trial?\n      yes: Activation fell for the same people, and conversion fell mostly among those who never activated.\n    spiked:\n      check: Did more trialists reach the milestone, after an onboarding or product change?\n      yes: Activation rose for the same people by a similar share.\n  - id: pricing\n    label: Pricing and follow-up\n    dropped:\n      check: Did prices rise, a discount end, or sales follow-up on trials slow down?\n      yes: Conversion fell from the first cohort to see the new price or the change in follow-up.\n    spiked:\n      check: Did a trial-end discount or a cheaper plan launch, or did sales start calling every trialist?\n      yes: Conversion rose from the first cohort to get the offer, often concentrated on one plan.\n\ndiagnose_order: [billing, calendar, trial-terms, trial-quality, activation, pricing]\n\nrelated: [trial-starts, new-paid-accounts, activation-rate, time-to-value, logo-churn-rate]\n\nprose:\n  why_it_matters: >-\n    Trial conversion is where a product proves it is worth paying for. Its level depends on the\n    trial terms: requiring a card up front means fewer trials and a much higher share of them\n    converting, so compare only within one policy. Read by trial-start cohort, each week's number\n    answers a question about the trials that began then, not about whoever happened to pay this week.\n  pitfalls:\n    - Conversions this week ÷ trials started this week mixes cohorts and swings with last month's trial volume. This spec follows each trial cohort for 30 days.\n    - Thirty days covers trials of up to about three weeks plus a grace period. For a 30-day trial use a window of at least 37 days, or every cohort looks low.\n    - Only cohorts whose 30 days have closed are reported, so the latest point is trials that started 6 weeks ago.\n    - Failed card charges at trial end are lost conversions, not lost interest. Check failed first payments before changing the product.\n    - At 160 trials a week a move of 8 points is still chance. Small products should judge trial conversion over four-week groups.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"trial-conversion-rate","name":"Trial conversion rate","aliases":["Trial-to-paid conversion","Trial to paid rate","Free trial conversion rate"],"family":"activation","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of trials started in a week that became a paid subscription within 30 days of the trial start.","formula":"Trials that started a paid subscription within 30 days ÷ trials started, by trial start week"},"events":[{"name":"trial_started","description":"A free trial of a paid plan began, sent by the billing system or the server.","also_called":["Trial Started","start_trial","customer.subscription.created (status trialing)"],"properties":[{"name":"plan","description":"The plan being trialled."}]},{"name":"subscription_started","description":"The first paid period of a subscription, sent by the billing system when the first payment succeeds.","also_called":["Subscription Started","customer.subscription.updated (trialing to active)","invoice.paid (first)"],"properties":[{"name":"subscription_id","description":"The billing system's subscription id."},{"name":"plan","description":"The plan subscribed to."}]}],"numerator":{"label":"Trials that converted within 30 days","aggregate":"unique_users","event":"subscription_started"},"denominator":{"label":"People who started a trial","aggregate":"unique_users","event":"trial_started"},"queries":{"hogql":"-- Trial conversion rate: of people whose first trial started in each week, the share who started a paid subscription within 30 days of the trial start. Trial weeks 31 to 6 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 30 days close.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(c.converted_people, 0) AS numerator,\n  coalesce(c.people, 0) AS denominator,\n  if(denominator = 0, NULL, numerator / denominator) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(6, 32))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, countIf(converted) AS converted_people, count() AS people\n  FROM (\n    SELECT\n      toMonday(s.start_at) AS week,\n      s.person_id AS person_id,\n      countIf(x.ts >= s.start_at AND x.ts < s.start_at + toIntervalDay(30)) > 0 AS converted\n    FROM (\n      SELECT person_id, min(toTimeZone(timestamp, 'UTC')) AS start_at\n      FROM events\n      WHERE event = 'trial_started'\n        AND person_id IS NOT NULL\n      GROUP BY person_id\n    ) AS s\n    LEFT JOIN (\n      SELECT person_id, toTimeZone(timestamp, 'UTC') AS ts\n      FROM events\n      WHERE event = 'subscription_started'\n        AND timestamp >= now() - toIntervalWeek(33)\n    ) AS x ON x.person_id = s.person_id\n    WHERE toMonday(s.start_at) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(31) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(6)\n    GROUP BY week, person_id\n  )\n  GROUP BY week\n) AS c ON c.week = w.week\nORDER BY week","postgres":"-- Trial conversion rate: of people whose first trial started in each week, the share who started a paid subscription within 30 days of the trial start. Trial weeks 31 to 6 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 30 days close.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '31 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '6 weeks',\n    interval '1 week'\n  ) AS g(week)\n),\nstarts AS (\n  SELECT user_id, min(occurred_at AT TIME ZONE 'UTC') AS start_at\n  FROM events\n  WHERE event_name = 'trial_started'\n    AND user_id IS NOT NULL\n  GROUP BY user_id\n),\ncohort AS (\n  SELECT\n    date_trunc('week', s.start_at)::date AS week,\n    s.user_id,\n    count(x.occurred_at) > 0 AS converted\n  FROM starts AS s\n  LEFT JOIN events AS x\n    ON x.user_id = s.user_id\n   AND x.event_name = 'subscription_started'\n   AND x.occurred_at AT TIME ZONE 'UTC' >= s.start_at\n   AND x.occurred_at AT TIME ZONE 'UTC' < s.start_at + interval '30 days'\n  WHERE s.start_at >= date_trunc('week', now() AT TIME ZONE 'UTC') - interval '31 weeks'\n    AND s.start_at < date_trunc('week', now() AT TIME ZONE 'UTC') - interval '5 weeks'\n  GROUP BY 1, 2\n)\nSELECT\n  w.week,\n  count(c.user_id) FILTER (WHERE c.converted) AS numerator,\n  count(c.user_id) AS denominator,\n  (count(c.user_id) FILTER (WHERE c.converted))::numeric / nullif(count(c.user_id), 0) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;","bigquery":"-- Trial conversion rate: of people whose first trial started in each week, the share who started a paid subscription within 30 days of the trial start. Trial weeks 31 to 6 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 30 days close.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 31 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 6 WEEK), INTERVAL 1 WEEK)) AS week\n),\nstarts AS (\n  SELECT user_id, MIN(occurred_at) AS start_at\n  FROM events\n  WHERE event_name = 'trial_started'\n    AND user_id IS NOT NULL\n  GROUP BY user_id\n),\ncohort AS (\n  SELECT\n    DATE_TRUNC(DATE(s.start_at), ISOWEEK) AS week,\n    s.user_id,\n    COUNT(x.occurred_at) > 0 AS converted\n  FROM starts AS s\n  LEFT JOIN events AS x\n    ON x.user_id = s.user_id\n   AND x.event_name = 'subscription_started'\n   AND x.occurred_at >= s.start_at\n   AND x.occurred_at < TIMESTAMP_ADD(s.start_at, INTERVAL 30 DAY)\n  WHERE s.start_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 31 WEEK))\n    AND s.start_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 5 WEEK))\n  GROUP BY week, s.user_id\n)\nSELECT\n  w.week,\n  COUNTIF(c.converted) AS numerator,\n  COUNT(c.user_id) AS denominator,\n  SAFE_DIVIDE(COUNTIF(c.converted), COUNT(c.user_id)) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;","snowflake":"-- Trial conversion rate: of people whose first trial started in each week, the share who started a paid subscription within 30 days of the trial start. Trial weeks 31 to 6 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their 30 days close.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -5 - ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nstarts AS (\n  SELECT user_id, MIN(occurred_at) AS start_at\n  FROM events\n  WHERE event_name = 'trial_started'\n    AND user_id IS NOT NULL\n  GROUP BY user_id\n),\ncohort AS (\n  SELECT\n    DATEADD(day, 1 - DAYOFWEEKISO(s.start_at), s.start_at::date) AS week,\n    s.user_id,\n    COUNT(x.occurred_at) > 0 AS converted\n  FROM starts AS s\n  LEFT JOIN events AS x\n    ON x.user_id = s.user_id\n   AND x.event_name = 'subscription_started'\n   AND x.occurred_at >= s.start_at\n   AND x.occurred_at < DATEADD(day, 30, s.start_at)\n  WHERE s.start_at >= DATEADD(week, -31, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND s.start_at < DATEADD(week, -5, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n  GROUP BY 1, 2\n)\nSELECT\n  w.week,\n  COUNT_IF(c.converted) AS numerator,\n  COUNT(c.user_id) AS denominator,\n  COUNT_IF(c.converted)::float / NULLIF(COUNT(c.user_id), 0) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;"},"noise":{"type":"binomial","min_denominator":50,"volume_unit":"trials in the cohort","typical":0.18,"reference_volumes":[50,150,500,2000]},"example":{"business":"saas","level":0.18,"volume":160,"trend":0.04},"drivers":[{"id":"billing","label":"Billing and first charges","feed":"stripe","dropped":{"check":"Did first charges at trial end start failing, or did subscription events stop syncing?","yes":"Failed first payments rise, or paid subscriptions in the billing dashboard exceed those recorded."},"spiked":{"check":"Is a billing migration or plan change firing subscription_started for people who were already paying?","yes":"Many converters had an earlier paid subscription under another id."}},{"id":"calendar","label":"Holidays at trial end","feed":"holidays","dropped":{"check":"Did the cohort's trials end over a holiday, when nobody was there to approve the purchase?","yes":"The same cohort weeks last year show the same dip."},"spiked":{"check":"Did the cohort's trials end at a quarter or budget-year start?","yes":"The same cohort weeks last year show the same rise."}},{"id":"trial-terms","label":"Trial terms","dropped":{"check":"Did the cohort get easier terms, such as no card required or a longer trial that doesn't fit the 30 days?","yes":"Trial starts jumped for the cohort and the conversion drop starts with the first cohort on the new terms."},"spiked":{"check":"Did the cohort get stricter terms, such as a card required up front?","yes":"Trial starts fell for the cohort and conversion rose from the first cohort on the new terms."}},{"id":"trial-quality","label":"Who started a trial","metric":"trial-starts","breakdown":"plan","dropped":{"check":"Did a promotion or a campaign fill the cohort with low-intent trials?","yes":"Trial starts rose that week from one source or plan that converts far below the rest."},"spiked":{"check":"Did a low-intent source stop, leaving a smaller, more committed cohort?","yes":"Trial starts fell that week while conversion from the other sources held."}},{"id":"activation","label":"Activation during the trial","metric":"activation-rate","dropped":{"check":"Did fewer trialists reach the activation milestone during the trial?","yes":"Activation fell for the same people, and conversion fell mostly among those who never activated."},"spiked":{"check":"Did more trialists reach the milestone, after an onboarding or product change?","yes":"Activation rose for the same people by a similar share."}},{"id":"pricing","label":"Pricing and follow-up","dropped":{"check":"Did prices rise, a discount end, or sales follow-up on trials slow down?","yes":"Conversion fell from the first cohort to see the new price or the change in follow-up."},"spiked":{"check":"Did a trial-end discount or a cheaper plan launch, or did sales start calling every trialist?","yes":"Conversion rose from the first cohort to get the offer, often concentrated on one plan."}}],"diagnose_order":["billing","calendar","trial-terms","trial-quality","activation","pricing"],"related":["trial-starts","new-paid-accounts","activation-rate","time-to-value","logo-churn-rate"],"prose":{"why_it_matters":"Trial conversion is where a product proves it is worth paying for. Its level depends on the trial terms: requiring a card up front means fewer trials and a much higher share of them converting, so compare only within one policy. Read by trial-start cohort, each week's number answers a question about the trials that began then, not about whoever happened to pay this week.","pitfalls":["Conversions this week ÷ trials started this week mixes cohorts and swings with last month's trial volume. This spec follows each trial cohort for 30 days.","Thirty days covers trials of up to about three weeks plus a grace period. For a 30-day trial use a window of at least 37 days, or every cohort looks low.","Only cohorts whose 30 days have closed are reported, so the latest point is trials that started 6 weeks ago.","Failed card charges at trial end are lost conversions, not lost interest. Check failed first payments before changing the product.","At 160 trials a week a move of 8 points is still chance. Small products should judge trial conversion over four-week groups."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "trial-starts": { yaml: "id: trial-starts\nname: Trial starts\naliases:\n  - Free trial starts\n  - New trials\n  - Trials started\nfamily: activation\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: People who started a free trial of a paid plan this week, each counted once.\n  formula: Distinct people with a trial_started event, by week\n\nevents:\n  - name: trial_started\n    description: A free trial of a paid plan began, sent by the billing system or the server.\n    also_called: [Trial Started, start_trial, customer.subscription.created (status trialing)]\n    properties:\n      - name: plan\n        description: The plan being trialled.\n\nnumerator:\n  label: People who started a trial\n  aggregate: unique_users\n  event: trial_started\n\nnoise:\n  type: poisson\n  min_denominator: 20\n  volume_unit: trials a week\n  typical: 160\n  reference_volumes: [50, 150, 500, 2000]\n\nexample:\n  business: saas\n  level: 160\n  volume: 160\n  trend: 0.2\n\ndrivers:\n  - id: tracking\n    label: Trial event\n    breakdown: plan\n    dropped:\n      check: Did the trial event stop arriving from billing for one plan or one signup path?\n      yes: One plan falls to near zero while trials in the billing system hold.\n    spiked:\n      check: Is the event firing twice, or did a migration create trials for existing accounts?\n      yes: Trials recorded exceed trials in the billing system, or many trialists already pay.\n  - id: calendar\n    label: Holidays\n    feed: holidays\n    dropped:\n      check: Is this a holiday week in your main markets?\n      yes: The same week last year shows the same dip once aligned on the holiday.\n    spiked:\n      check: Is this the first full week back after a holiday, or a quarter start when budgets reset?\n      yes: The same week last year shows the same rise.\n  - id: trial-offer\n    label: Trial terms\n    dropped:\n      check: Did the offer get stricter, such as a card now required, a shorter trial or fewer plans with a trial?\n      yes: Trials fall from the day the terms changed, on every channel at once.\n    spiked:\n      check: Did the offer get easier, such as no card required or a longer trial?\n      yes: Trials jump from the day the terms changed; expect trial conversion to fall weeks later.\n  - id: signups\n    label: Signups\n    metric: signups\n    dropped:\n      check: Did fewer people sign up in the first place?\n      yes: Signups fall by about as much as trials, and the share of signups starting a trial holds.\n    spiked:\n      check: Did a wave of signups arrive, and are they real?\n      yes: Signups rise by about as much as trials; check activation before celebrating.\n  - id: activation\n    label: Reaching the paywall\n    metric: activation-rate\n    dropped:\n      check: Did fewer free users reach the point where a paid feature or a limit prompts a trial?\n      yes: Activation or usage of the gated feature falls while signups hold.\n    spiked:\n      check: Did a new limit or paid feature push more free users to try a paid plan?\n      yes: Trials started from in-app prompts jump from the day the change shipped.\n  - id: campaigns\n    label: Campaigns\n    feed: ad-platforms\n    dropped:\n      check: Did a campaign that sends people straight to a trial end?\n      yes: Trials from one source fall to their pre-campaign level.\n    spiked:\n      check: Did a promotion or a campaign drive people straight to a trial?\n      yes: Most of the extra trials come from one source in the days after launch.\n\ndiagnose_order: [tracking, calendar, trial-offer, signups, activation, campaigns]\n\nrelated: [trial-conversion-rate, signups, new-paid-accounts, activation-rate, demo-request-rate]\n\nprose:\n  why_it_matters: >-\n    Trial starts are the bridge between interest and revenue: in a trial-led product, every new paid\n    account began here a few weeks earlier. At Copperline's 160 a week, chance moves the count by\n    about 22% either way, so one quiet week means little and three in a row is a pipeline problem.\n  pitfalls:\n    - Whether a card is required changes everything. Dropping the card requirement usually multiplies trial starts and divides conversion, so compare trials only within one policy.\n    - Trials that start automatically at signup are signups under another name. Read signups for demand and this for the share who choose a paid plan.\n    - A person who restarts a trial, or a teammate who starts one on the same account, is not new demand. Count first trials per account where accounts exist.\n    - Trials pulled forward by a discount or a deadline are followed by a quiet week. Read two-week sums around promotions.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"trial-starts","name":"Trial starts","aliases":["Free trial starts","New trials","Trials started"],"family":"activation","kind":"count","polarity":"up-is-good","definition":{"one_line":"People who started a free trial of a paid plan this week, each counted once.","formula":"Distinct people with a trial_started event, by week"},"events":[{"name":"trial_started","description":"A free trial of a paid plan began, sent by the billing system or the server.","also_called":["Trial Started","start_trial","customer.subscription.created (status trialing)"],"properties":[{"name":"plan","description":"The plan being trialled."}]}],"numerator":{"label":"People who started a trial","aggregate":"unique_users","event":"trial_started"},"noise":{"type":"poisson","min_denominator":20,"volume_unit":"trials a week","typical":160,"reference_volumes":[50,150,500,2000]},"example":{"business":"saas","level":160,"volume":160,"trend":0.2},"drivers":[{"id":"tracking","label":"Trial event","breakdown":"plan","dropped":{"check":"Did the trial event stop arriving from billing for one plan or one signup path?","yes":"One plan falls to near zero while trials in the billing system hold."},"spiked":{"check":"Is the event firing twice, or did a migration create trials for existing accounts?","yes":"Trials recorded exceed trials in the billing system, or many trialists already pay."}},{"id":"calendar","label":"Holidays","feed":"holidays","dropped":{"check":"Is this a holiday week in your main markets?","yes":"The same week last year shows the same dip once aligned on the holiday."},"spiked":{"check":"Is this the first full week back after a holiday, or a quarter start when budgets reset?","yes":"The same week last year shows the same rise."}},{"id":"trial-offer","label":"Trial terms","dropped":{"check":"Did the offer get stricter, such as a card now required, a shorter trial or fewer plans with a trial?","yes":"Trials fall from the day the terms changed, on every channel at once."},"spiked":{"check":"Did the offer get easier, such as no card required or a longer trial?","yes":"Trials jump from the day the terms changed; expect trial conversion to fall weeks later."}},{"id":"signups","label":"Signups","metric":"signups","dropped":{"check":"Did fewer people sign up in the first place?","yes":"Signups fall by about as much as trials, and the share of signups starting a trial holds."},"spiked":{"check":"Did a wave of signups arrive, and are they real?","yes":"Signups rise by about as much as trials; check activation before celebrating."}},{"id":"activation","label":"Reaching the paywall","metric":"activation-rate","dropped":{"check":"Did fewer free users reach the point where a paid feature or a limit prompts a trial?","yes":"Activation or usage of the gated feature falls while signups hold."},"spiked":{"check":"Did a new limit or paid feature push more free users to try a paid plan?","yes":"Trials started from in-app prompts jump from the day the change shipped."}},{"id":"campaigns","label":"Campaigns","feed":"ad-platforms","dropped":{"check":"Did a campaign that sends people straight to a trial end?","yes":"Trials from one source fall to their pre-campaign level."},"spiked":{"check":"Did a promotion or a campaign drive people straight to a trial?","yes":"Most of the extra trials come from one source in the days after launch."}}],"diagnose_order":["tracking","calendar","trial-offer","signups","activation","campaigns"],"related":["trial-conversion-rate","signups","new-paid-accounts","activation-rate","demo-request-rate"],"prose":{"why_it_matters":"Trial starts are the bridge between interest and revenue: in a trial-led product, every new paid account began here a few weeks earlier. At Copperline's 160 a week, chance moves the count by about 22% either way, so one quiet week means little and three in a row is a pipeline problem.","pitfalls":["Whether a card is required changes everything. Dropping the card requirement usually multiplies trial starts and divides conversion, so compare trials only within one policy.","Trials that start automatically at signup are signups under another name. Read signups for demand and this for the share who choose a paid plan.","A person who restarts a trial, or a teammate who starts one on the same account, is not new demand. Count first trials per account where accounts exist.","Trials pulled forward by a discount or a deadline are followed by a quiet week. Read two-week sums around promotions."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "unique-visitors": { yaml: "id: unique-visitors\nname: Unique visitors\naliases:\n  - Visitors\n  - Website visitors\n  - Weekly unique visitors\nfamily: traffic\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: The number of different people, counted by browser or login, who viewed at least one page in the week.\n  formula: Distinct visitor ids with at least one page view\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change, captured in the browser.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: $session_id\n        description: Set by the analytics SDK; ties the page view to a visit.\n      - name: $device_type\n        description: Mobile, Desktop or Tablet.\n\nnumerator:\n  label: Unique visitors\n  aggregate: unique_users\n  event: $pageview\n\nnoise:\n  type: poisson\n  min_denominator: 100\n  volume_unit: visitors a week\n  typical: 30000\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: store\n  level: 390000\n  volume: 390000\n  trend: 0.12\n\ndrivers:\n  - id: identity\n    label: Cookies and identity\n    breakdown: $browser\n    dropped:\n      check: Did a consent banner, a cookie change or a merge of anonymous and logged-in people cut the count?\n      yes: Visitors fall while sessions hold, from the day of the change, often in one browser.\n    spiked:\n      check: Did cookies start resetting, so the same people now count as new visitors?\n      yes: Visitors and new-visitor share jump together while sessions per visitor fall, often on Safari or after a domain change.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Was last week a sale, holiday or gifting week that this week can't match?\n      yes: The same pair of weeks last year shows the same fall once aligned on the event.\n    spiked:\n      check: Is this a sale, holiday or gifting week that brings people who don't usually visit?\n      yes: The same week last year shows the same jump, mostly in new visitors.\n  - id: new-visitors\n    label: New visitors\n    metric: new-visitor-share\n    dropped:\n      check: Did fewer first-time visitors arrive while returning visitors held?\n      yes: New-visitor share falls and the drop sits in prospecting channels.\n    spiked:\n      check: Is the rise all first-time visitors from one source?\n      yes: New-visitor share jumps with one campaign, post or press mention.\n  - id: paid\n    label: Paid traffic\n    metric: paid-sessions\n    feed: ad-platforms\n    dropped:\n      check: Did prospecting spend fall or a campaign stop serving?\n      yes: Paid sessions fall in the same days, and visitors from paid sources account for most of the drop.\n    spiked:\n      check: Did a prospecting campaign or a budget increase start?\n      yes: Paid sessions rise and the new people come from one platform.\n  - id: organic\n    label: Organic search\n    metric: organic-sessions\n    feed: google-search\n    dropped:\n      check: Did search traffic fall after a Google update or lost rankings?\n      yes: Organic sessions fall from the date of the update.\n    spiked:\n      check: Did a ranking gain or a seasonal search term bring new people?\n      yes: Organic sessions rise on a few landing pages.\n\ndiagnose_order: [identity, calendar, new-visitors, paid, organic]\n\nrelated: [sessions, new-visitor-share, sessions-per-user, wau, organic-sessions]\n\nprose:\n  why_it_matters: >-\n    Unique visitors tell you how many people the store reached, which sessions can't: a loyal\n    visitor coming back five times is five sessions and one person. When sessions grow and\n    visitors don't, the same people are visiting more; when visitors grow, reach is growing.\n    A store with 390,000 visitors a week can lose 3% of them to a cookie change without a\n    single real person leaving.\n  pitfalls:\n    - A visitor is a browser, not a person. Phone and laptop count twice, and Safari's seven-day limit on script-set cookies makes anyone who returns after more than a week look new.\n    - Weekly unique visitors don't add up to monthly unique visitors. Never sum weeks; count distinct people over the longer window.\n    - In a warehouse, count the anonymous id for visitors who never log in. Counting only user_id drops most of a store's traffic.\n    - Merging anonymous and identified people, as PostHog does on login, can lower past weeks' counts after the fact. Freeze last week's number when you report it.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"unique-visitors","name":"Unique visitors","aliases":["Visitors","Website visitors","Weekly unique visitors"],"family":"traffic","kind":"count","polarity":"up-is-good","definition":{"one_line":"The number of different people, counted by browser or login, who viewed at least one page in the week.","formula":"Distinct visitor ids with at least one page view"},"events":[{"name":"$pageview","description":"One page load or client-side route change, captured in the browser.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"$session_id","description":"Set by the analytics SDK; ties the page view to a visit."},{"name":"$device_type","description":"Mobile, Desktop or Tablet."}]}],"numerator":{"label":"Unique visitors","aggregate":"unique_users","event":"$pageview"},"noise":{"type":"poisson","min_denominator":100,"volume_unit":"visitors a week","typical":30000,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"store","level":390000,"volume":390000,"trend":0.12},"drivers":[{"id":"identity","label":"Cookies and identity","breakdown":"$browser","dropped":{"check":"Did a consent banner, a cookie change or a merge of anonymous and logged-in people cut the count?","yes":"Visitors fall while sessions hold, from the day of the change, often in one browser."},"spiked":{"check":"Did cookies start resetting, so the same people now count as new visitors?","yes":"Visitors and new-visitor share jump together while sessions per visitor fall, often on Safari or after a domain change."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Was last week a sale, holiday or gifting week that this week can't match?","yes":"The same pair of weeks last year shows the same fall once aligned on the event."},"spiked":{"check":"Is this a sale, holiday or gifting week that brings people who don't usually visit?","yes":"The same week last year shows the same jump, mostly in new visitors."}},{"id":"new-visitors","label":"New visitors","metric":"new-visitor-share","dropped":{"check":"Did fewer first-time visitors arrive while returning visitors held?","yes":"New-visitor share falls and the drop sits in prospecting channels."},"spiked":{"check":"Is the rise all first-time visitors from one source?","yes":"New-visitor share jumps with one campaign, post or press mention."}},{"id":"paid","label":"Paid traffic","metric":"paid-sessions","feed":"ad-platforms","dropped":{"check":"Did prospecting spend fall or a campaign stop serving?","yes":"Paid sessions fall in the same days, and visitors from paid sources account for most of the drop."},"spiked":{"check":"Did a prospecting campaign or a budget increase start?","yes":"Paid sessions rise and the new people come from one platform."}},{"id":"organic","label":"Organic search","metric":"organic-sessions","feed":"google-search","dropped":{"check":"Did search traffic fall after a Google update or lost rankings?","yes":"Organic sessions fall from the date of the update."},"spiked":{"check":"Did a ranking gain or a seasonal search term bring new people?","yes":"Organic sessions rise on a few landing pages."}}],"diagnose_order":["identity","calendar","new-visitors","paid","organic"],"related":["sessions","new-visitor-share","sessions-per-user","wau","organic-sessions"],"prose":{"why_it_matters":"Unique visitors tell you how many people the store reached, which sessions can't: a loyal visitor coming back five times is five sessions and one person. When sessions grow and visitors don't, the same people are visiting more; when visitors grow, reach is growing. A store with 390,000 visitors a week can lose 3% of them to a cookie change without a single real person leaving.","pitfalls":["A visitor is a browser, not a person. Phone and laptop count twice, and Safari's seven-day limit on script-set cookies makes anyone who returns after more than a week look new.","Weekly unique visitors don't add up to monthly unique visitors. Never sum weeks; count distinct people over the longer window.","In a warehouse, count the anonymous id for visitors who never log in. Counting only user_id drops most of a store's traffic.","Merging anonymous and identified people, as PostHog does on login, can lower past weeks' counts after the fact. Freeze last week's number when you report it."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "units-per-order": { yaml: "id: units-per-order\nname: Units per order\naliases:\n  - Units per transaction\n  - UPT\n  - Items per order\n  - Average basket size\n  - Basket size\nfamily: revenue\nkind: ratio\npolarity: up-is-good\n\ndefinition:\n  one_line: The average number of items in a paid order, the basket half of average order value.\n  formula: Items sold ÷ paid orders\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: item_count\n        description: Total units in the order, summing each line's quantity.\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n      - name: is_first_order\n        description: True when the store has no earlier order from this customer, from its own customer records.\n\nnumerator:\n  label: Items sold\n  aggregate: sum\n  event: order_completed\n  property: item_count\ndenominator:\n  label: Paid orders\n  aggregate: count\n  event: order_completed\n\nnoise:\n  type: mean\n  cv: 0.75\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 1.8\n\nexample:\n  business: store\n  level: 1.86\n  volume: 13300\n  trend: 0.05\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did item_count switch from units to line items, or stop counting bundle components?\n      yes: Units per order step down on one release day while order value holds.\n    spiked:\n      check: Did item_count start counting free gifts, samples or shipping protection as items?\n      yes: Units step up on one day, and orders carry $0 lines they didn't before.\n  - id: calendar\n    label: Shopping calendar\n    feed: shopping\n    dropped:\n      check: Was last week a gifting or stock-up week, when baskets run larger?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this a gifting or stock-up week?\n      yes: The same week last year shows the same rise once aligned on the event.\n  - id: offers\n    label: Bundles and thresholds\n    dropped:\n      check: Did a bundle, a multi-buy offer or a free-shipping threshold end or fall?\n      yes: The share of one-item orders rises from the day the offer changed.\n    spiked:\n      check: Did a buy-two offer, a bundle or a higher free-shipping threshold go live?\n      yes: The share of one-item orders falls from the launch day.\n  - id: cross-sell\n    label: Cart recommendations\n    dropped:\n      check: Did a cart upsell, recommendations widget or frequently-bought-together block break or get removed?\n      yes: Adds from recommendations fall to near zero from one day.\n    spiked:\n      check: Did a new cross-sell launch, and are its adds paid items rather than free gifts?\n      yes: Adds from recommendations rise and the extra items carry a price.\n  - id: product-mix\n    label: Product mix\n    dropped:\n      check: Did a single-item product, such as a high-priced hero or a new launch, take a larger share of orders?\n      yes: Orders for that product grow while other baskets hold their size.\n    spiked:\n      check: Did consumables, refills or small accessories that people buy several of gain share?\n      yes: Orders containing those products grow while other baskets hold their size.\n  - id: first-orders\n    label: First vs repeat orders\n    breakdown: is_first_order\n    dropped:\n      check: Did first orders take a larger share of orders, and do they hold fewer items than repeat orders?\n      yes: First orders average fewer items, each group's average holds, and only the mix moved.\n    spiked:\n      check: Did repeat customers, who know what they want, take a larger share?\n      yes: The mix moved toward repeat orders while each group's average held.\n\ndiagnose_order: [tracking, calendar, offers, cross-sell, product-mix, first-orders]\n\nrelated: [aov, gross-sales, orders, discount-rate, add-to-cart-rate]\n\nprose:\n  why_it_matters: >-\n    Units per order is the basket half of average order value; AOV is units per order × the\n    average price per unit. Bundles, free-shipping thresholds and cross-sells act on it\n    directly. Going from 1.8 to 1.9 at Northwind is about 1,330 more items a week with no new\n    customers.\n  pitfalls:\n    - Decide whether item_count counts units or line items and keep it; switching changes every multi-quantity order.\n    - Free gifts, samples and shipping protection count as items unless excluded, so a gift-with-purchase lifts units with no extra sales.\n    - A bundle sold as one product counts as one item. Splitting a bundle into its parts in the catalogue changes units per order without changing what shoppers bought.\n    - Basket size means units in some reports and order value in others. This page uses units; AOV is the value.\n    - An average hides the shape. A move from 1.8 to 1.9 usually means fewer one-item orders, not bigger baskets everywhere; check the share of one-item orders.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"units-per-order","name":"Units per order","aliases":["Units per transaction","UPT","Items per order","Average basket size","Basket size"],"family":"revenue","kind":"ratio","polarity":"up-is-good","definition":{"one_line":"The average number of items in a paid order, the basket half of average order value.","formula":"Items sold ÷ paid orders"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"item_count","description":"Total units in the order, summing each line's quantity."},{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."},{"name":"is_first_order","description":"True when the store has no earlier order from this customer, from its own customer records."}]}],"numerator":{"label":"Items sold","aggregate":"sum","event":"order_completed","property":"item_count"},"denominator":{"label":"Paid orders","aggregate":"count","event":"order_completed"},"noise":{"type":"mean","cv":0.75,"min_denominator":50,"volume_unit":"orders a week","typical":1.8},"example":{"business":"store","level":1.86,"volume":13300,"trend":0.05},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did item_count switch from units to line items, or stop counting bundle components?","yes":"Units per order step down on one release day while order value holds."},"spiked":{"check":"Did item_count start counting free gifts, samples or shipping protection as items?","yes":"Units step up on one day, and orders carry $0 lines they didn't before."}},{"id":"calendar","label":"Shopping calendar","feed":"shopping","dropped":{"check":"Was last week a gifting or stock-up week, when baskets run larger?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this a gifting or stock-up week?","yes":"The same week last year shows the same rise once aligned on the event."}},{"id":"offers","label":"Bundles and thresholds","dropped":{"check":"Did a bundle, a multi-buy offer or a free-shipping threshold end or fall?","yes":"The share of one-item orders rises from the day the offer changed."},"spiked":{"check":"Did a buy-two offer, a bundle or a higher free-shipping threshold go live?","yes":"The share of one-item orders falls from the launch day."}},{"id":"cross-sell","label":"Cart recommendations","dropped":{"check":"Did a cart upsell, recommendations widget or frequently-bought-together block break or get removed?","yes":"Adds from recommendations fall to near zero from one day."},"spiked":{"check":"Did a new cross-sell launch, and are its adds paid items rather than free gifts?","yes":"Adds from recommendations rise and the extra items carry a price."}},{"id":"product-mix","label":"Product mix","dropped":{"check":"Did a single-item product, such as a high-priced hero or a new launch, take a larger share of orders?","yes":"Orders for that product grow while other baskets hold their size."},"spiked":{"check":"Did consumables, refills or small accessories that people buy several of gain share?","yes":"Orders containing those products grow while other baskets hold their size."}},{"id":"first-orders","label":"First vs repeat orders","breakdown":"is_first_order","dropped":{"check":"Did first orders take a larger share of orders, and do they hold fewer items than repeat orders?","yes":"First orders average fewer items, each group's average holds, and only the mix moved."},"spiked":{"check":"Did repeat customers, who know what they want, take a larger share?","yes":"The mix moved toward repeat orders while each group's average held."}}],"diagnose_order":["tracking","calendar","offers","cross-sell","product-mix","first-orders"],"related":["aov","gross-sales","orders","discount-rate","add-to-cart-rate"],"prose":{"why_it_matters":"Units per order is the basket half of average order value; AOV is units per order × the average price per unit. Bundles, free-shipping thresholds and cross-sells act on it directly. Going from 1.8 to 1.9 at Northwind is about 1,330 more items a week with no new customers.","pitfalls":["Decide whether item_count counts units or line items and keep it; switching changes every multi-quantity order.","Free gifts, samples and shipping protection count as items unless excluded, so a gift-with-purchase lifts units with no extra sales.","A bundle sold as one product counts as one item. Splitting a bundle into its parts in the catalogue changes units per order without changing what shoppers bought.","Basket size means units in some reports and order value in others. This page uses units; AOV is the value.","An average hides the shape. A move from 1.8 to 1.9 usually means fewer one-item orders, not bigger baskets everywhere; check the share of one-item orders."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "wau": { yaml: "id: wau\nname: Weekly active users\naliases:\n  - WAU\n  - Weekly active users (WAU)\n  - Weekly actives\nfamily: engagement\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: The number of distinct people active at least once in the week, Monday to Sunday UTC.\n  formula: Distinct people with any event in the week\n\nevents:\n  - name: \"*\"\n    description: Any event a person sends. Activity, not one specific action; the same definition as DAU and MAU.\n    also_called: [All events, Any event, Active event]\n    properties:\n      - name: $os\n        description: The operating system, for splitting by platform.\n\nnumerator:\n  label: Weekly active users\n  aggregate: unique_users\n  event: \"*\"\n\nnoise:\n  type: poisson\n  min_denominator: 100\n  volume_unit: weekly active users\n  typical: 52000\n\nexample:\n  business: app\n  level: 52000\n  volume: 52000\n  trend: 0.15\n\ndrivers:\n  - id: tracking\n    label: Tracking and bots\n    dropped:\n      check: Did an SDK update, consent banner or ad blocker stop events from one platform or app version?\n      yes: One platform or version goes quiet from the day of a release while the others hold.\n    spiked:\n      check: Is the rise real people, or bots, duplicated ids, or a background event now counting as activity?\n      yes: Events per active person fall sharply, or one event, app version or user agent accounts for the new actives.\n  - id: calendar\n    label: Calendar\n    feed: holidays\n    dropped:\n      check: Is this a holiday week, when routines break?\n      yes: The same week last year shows the same dip once aligned on the holiday.\n    spiked:\n      check: Is this a seasonal high for the product?\n      yes: The same weeks last year show the same rise.\n  - id: platform\n    label: Platform and releases\n    breakdown: $os\n    feed: app-stores\n    dropped:\n      check: Is the drop on one platform only, after a release, a store rejection or an OS update?\n      yes: One platform falls from the release date while the others hold.\n    spiked:\n      check: Did a release or a store feature lift one platform?\n      yes: One platform rises from the day the release or feature went live.\n  - id: retained\n    label: Retained from last week\n    dropped:\n      check: Did fewer of last week's active people come back this week?\n      yes: People active in both weeks fall while new and resurrected people hold.\n    spiked:\n      check: Did more of last week's active people come back?\n      yes: People active in both weeks rise while new and resurrected people hold.\n  - id: new-users\n    label: New users\n    metric: signups\n    dropped:\n      check: Did fewer new people arrive?\n      yes: New people fall by about as many as WAU did.\n    spiked:\n      check: Did a launch, a press mention or a paid campaign bring a wave of new people?\n      yes: New people explain the rise; whether they stay shows in week 1 retention.\n  - id: resurrected\n    label: Resurrected users\n    metric: resurrected-users\n    dropped:\n      check: Did fewer lapsed people come back this week?\n      yes: Resurrected users fall below their usual range, often because a win-back campaign skipped a week.\n    spiked:\n      check: Did a win-back campaign, or a quiet week before, bring lapsed people back?\n      yes: Resurrected users explain the rise; most return on the campaign's send days.\n\ndiagnose_order: [tracking, calendar, platform, retained, new-users, resurrected]\n\nrelated: [dau, mau, stickiness, resurrected-users, signups]\n\nprose:\n  why_it_matters: >-\n    WAU counts everyone who showed up at least once in the week, which suits products people use\n    a few times a week rather than every day. It is the sum of three groups, people retained from\n    last week, new people and people back after a gap, and every real move in WAU is a move in\n    one of them. At 52,000, chance alone moves it by about 1.2%.\n  pitfalls:\n    - WAU is not seven times DAU, because the same people show up on several days. Never add daily counts to get a weekly one.\n    - Passive events such as push notifications received and background syncs count devices that did nothing. Use the same activity definition as DAU and MAU.\n    - A holiday week lowers WAU for work tools and can lift it for consumer apps. Compare with the same week last year.\n    - A campaign can lift WAU with new people while retention falls underneath. Split WAU into retained, new and resurrected before calling it growth.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"wau","name":"Weekly active users","aliases":["WAU","Weekly active users (WAU)","Weekly actives"],"family":"engagement","kind":"count","polarity":"up-is-good","definition":{"one_line":"The number of distinct people active at least once in the week, Monday to Sunday UTC.","formula":"Distinct people with any event in the week"},"events":[{"name":"*","description":"Any event a person sends. Activity, not one specific action; the same definition as DAU and MAU.","also_called":["All events","Any event","Active event"],"properties":[{"name":"$os","description":"The operating system, for splitting by platform."}]}],"numerator":{"label":"Weekly active users","aggregate":"unique_users","event":"*"},"noise":{"type":"poisson","min_denominator":100,"volume_unit":"weekly active users","typical":52000},"example":{"business":"app","level":52000,"volume":52000,"trend":0.15},"drivers":[{"id":"tracking","label":"Tracking and bots","dropped":{"check":"Did an SDK update, consent banner or ad blocker stop events from one platform or app version?","yes":"One platform or version goes quiet from the day of a release while the others hold."},"spiked":{"check":"Is the rise real people, or bots, duplicated ids, or a background event now counting as activity?","yes":"Events per active person fall sharply, or one event, app version or user agent accounts for the new actives."}},{"id":"calendar","label":"Calendar","feed":"holidays","dropped":{"check":"Is this a holiday week, when routines break?","yes":"The same week last year shows the same dip once aligned on the holiday."},"spiked":{"check":"Is this a seasonal high for the product?","yes":"The same weeks last year show the same rise."}},{"id":"platform","label":"Platform and releases","breakdown":"$os","feed":"app-stores","dropped":{"check":"Is the drop on one platform only, after a release, a store rejection or an OS update?","yes":"One platform falls from the release date while the others hold."},"spiked":{"check":"Did a release or a store feature lift one platform?","yes":"One platform rises from the day the release or feature went live."}},{"id":"retained","label":"Retained from last week","dropped":{"check":"Did fewer of last week's active people come back this week?","yes":"People active in both weeks fall while new and resurrected people hold."},"spiked":{"check":"Did more of last week's active people come back?","yes":"People active in both weeks rise while new and resurrected people hold."}},{"id":"new-users","label":"New users","metric":"signups","dropped":{"check":"Did fewer new people arrive?","yes":"New people fall by about as many as WAU did."},"spiked":{"check":"Did a launch, a press mention or a paid campaign bring a wave of new people?","yes":"New people explain the rise; whether they stay shows in week 1 retention."}},{"id":"resurrected","label":"Resurrected users","metric":"resurrected-users","dropped":{"check":"Did fewer lapsed people come back this week?","yes":"Resurrected users fall below their usual range, often because a win-back campaign skipped a week."},"spiked":{"check":"Did a win-back campaign, or a quiet week before, bring lapsed people back?","yes":"Resurrected users explain the rise; most return on the campaign's send days."}}],"diagnose_order":["tracking","calendar","platform","retained","new-users","resurrected"],"related":["dau","mau","stickiness","resurrected-users","signups"],"prose":{"why_it_matters":"WAU counts everyone who showed up at least once in the week, which suits products people use a few times a week rather than every day. It is the sum of three groups, people retained from last week, new people and people back after a gap, and every real move in WAU is a move in one of them. At 52,000, chance alone moves it by about 1.2%.","pitfalls":["WAU is not seven times DAU, because the same people show up on several days. Never add daily counts to get a weekly one.","Passive events such as push notifications received and background syncs count devices that did nothing. Use the same activity definition as DAU and MAU.","A holiday week lowers WAU for work tools and can lift it for consumer apps. Compare with the same week last year.","A campaign can lift WAU with new people while retention falls underneath. Split WAU into retained, new and resurrected before calling it growth."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "week-1-retention": { yaml: "id: week-1-retention\nname: Week 1 retention\naliases:\n  - W1 retention\n  - First-week retention\n  - Week one retention\nfamily: engagement\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of new people who are active again in their second week, between 7 and 14 days after their first event, by the week they arrived.\n  formula: People with any event from 7 to 14 days after their first event (days 7–13, hours 168 to 336) ÷ people whose first event fell in the cohort week\n\nevents:\n  - name: \"*\"\n    description: Any event a person sends. A person's first ever event places them in a cohort; any later event counts as a return.\n    also_called: [All events, Any event, Active event]\n    properties:\n      - name: $os\n        description: The operating system, for splitting by platform.\n      - name: utm_source\n        description: The campaign source a person arrived from, for splitting by acquisition channel.\n\nnumerator:\n  label: New people active again 7 to 14 days later\n  aggregate: returning_users\n  event: \"*\"\n\nqueries:\n  hogql: |-\n    -- Week 1 retention: of the people whose first event fell in each week, the share with any event 7 to 14 days after it. Cohort weeks 28 to 3 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their window has closed.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(c.retained_people, 0) AS numerator,\n      coalesce(c.people, 0) AS denominator,\n      if(denominator = 0, NULL, numerator / denominator) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(3, 29))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, countIf(retained) AS retained_people, count() AS people\n      FROM (\n        SELECT\n          toMonday(f.first_at) AS week,\n          f.person_id AS person_id,\n          countIf(e.ts >= f.first_at + toIntervalDay(7) AND e.ts < f.first_at + toIntervalDay(14)) > 0 AS retained\n        FROM (\n          SELECT person_id, min(toTimeZone(timestamp, 'UTC')) AS first_at\n          FROM events\n          WHERE person_id IS NOT NULL\n          GROUP BY person_id\n        ) AS f\n        LEFT JOIN (\n          SELECT person_id, toTimeZone(timestamp, 'UTC') AS ts\n          FROM events\n          WHERE person_id IS NOT NULL\n            AND timestamp >= now() - toIntervalWeek(29)\n        ) AS e ON e.person_id = f.person_id\n        WHERE toMonday(f.first_at) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(28) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(3)\n        GROUP BY week, person_id\n      )\n      GROUP BY week\n    ) AS c ON c.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Week 1 retention: of the people whose first event fell in each week, the share with any event 7 to 14 days after it. Cohort weeks 28 to 3 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their window has closed.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '28 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '3 weeks',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    firsts AS (\n      SELECT user_id, min(occurred_at AT TIME ZONE 'UTC') AS first_at\n      FROM events\n      WHERE user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    cohort AS (\n      SELECT\n        date_trunc('week', f.first_at)::date AS week,\n        f.user_id,\n        count(e.occurred_at) > 0 AS retained\n      FROM firsts AS f\n      LEFT JOIN events AS e\n        ON e.user_id = f.user_id\n       AND e.occurred_at AT TIME ZONE 'UTC' >= f.first_at + interval '7 days'\n       AND e.occurred_at AT TIME ZONE 'UTC' < f.first_at + interval '14 days'\n      WHERE f.first_at >= date_trunc('week', now() AT TIME ZONE 'UTC') - interval '28 weeks'\n        AND f.first_at < date_trunc('week', now() AT TIME ZONE 'UTC') - interval '2 weeks'\n      GROUP BY 1, 2\n    )\n    SELECT\n      w.week,\n      count(c.user_id) FILTER (WHERE c.retained) AS numerator,\n      count(c.user_id) AS denominator,\n      (count(c.user_id) FILTER (WHERE c.retained))::numeric / nullif(count(c.user_id), 0) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Week 1 retention: of the people whose first event fell in each week, the share with any event 7 to 14 days after it. Cohort weeks 28 to 3 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their window has closed.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 28 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 3 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    firsts AS (\n      SELECT user_id, MIN(occurred_at) AS first_at\n      FROM events\n      WHERE user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    cohort AS (\n      SELECT\n        DATE_TRUNC(DATE(f.first_at), ISOWEEK) AS week,\n        f.user_id,\n        COUNT(e.occurred_at) > 0 AS retained\n      FROM firsts AS f\n      LEFT JOIN events AS e\n        ON e.user_id = f.user_id\n       AND e.occurred_at >= TIMESTAMP_ADD(f.first_at, INTERVAL 7 DAY)\n       AND e.occurred_at < TIMESTAMP_ADD(f.first_at, INTERVAL 14 DAY)\n      WHERE f.first_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 28 WEEK))\n        AND f.first_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 2 WEEK))\n      GROUP BY week, f.user_id\n    )\n    SELECT\n      w.week,\n      COUNTIF(c.retained) AS numerator,\n      COUNT(c.user_id) AS denominator,\n      SAFE_DIVIDE(COUNTIF(c.retained), COUNT(c.user_id)) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Week 1 retention: of the people whose first event fell in each week, the share with any event 7 to 14 days after it. Cohort weeks 28 to 3 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their window has closed.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -2 - ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    firsts AS (\n      SELECT user_id, MIN(occurred_at) AS first_at\n      FROM events\n      WHERE user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    cohort AS (\n      SELECT\n        DATEADD(day, 1 - DAYOFWEEKISO(f.first_at), f.first_at::date) AS week,\n        f.user_id,\n        COUNT(e.occurred_at) > 0 AS retained\n      FROM firsts AS f\n      LEFT JOIN events AS e\n        ON e.user_id = f.user_id\n       AND e.occurred_at >= DATEADD(day, 7, f.first_at)\n       AND e.occurred_at < DATEADD(day, 14, f.first_at)\n      WHERE f.first_at >= DATEADD(week, -28, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND f.first_at < DATEADD(week, -2, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n      GROUP BY 1, 2\n    )\n    SELECT\n      w.week,\n      COUNT_IF(c.retained) AS numerator,\n      COUNT(c.user_id) AS denominator,\n      COUNT_IF(c.retained)::float / NULLIF(COUNT(c.user_id), 0) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: new people in the cohort\n  typical: 0.3\n\nexample:\n  business: app\n  level: 0.31\n  volume: 8500\n  trend: 0.03\n\ndrivers:\n  - id: identity\n    label: Identity and tracking\n    dropped:\n      check: Did returning people start appearing as new, for example after an SDK, login or identity change?\n      yes: New people jump and their retention falls from the same date, with no change in sign-ups.\n    spiked:\n      check: Did a tracking change stop counting one-time visitors as new people?\n      yes: Cohorts shrink from one date, mostly people with a single event, and retention rises with no product change.\n  - id: calendar\n    label: Calendar\n    feed: holidays\n    dropped:\n      check: Did the cohort's second week fall over a holiday?\n      yes: Cohorts whose days 7 to 14 overlap a holiday retain less, and the next cohort recovers.\n    spiked:\n      check: Did the cohort arrive in a high-intent season, such as the new year for a budgeting app?\n      yes: The same cohorts last year retained better too.\n  - id: platform\n    label: Platform and releases\n    breakdown: $os\n    feed: app-stores\n    dropped:\n      check: Did a release break something new people hit in their first days, on one platform?\n      yes: Retention falls for cohorts on one platform or app version only.\n    spiked:\n      check: Did a release fix a first-week problem on one platform?\n      yes: Retention rises for cohorts on that platform from the release date.\n  - id: acquisition-mix\n    label: Where new people came from\n    breakdown: utm_source\n    dropped:\n      check: Did more of the cohort come from a broad or low-intent source, such as a new paid campaign?\n      yes: One source grew its share of new people and retains far below the others.\n    spiked:\n      check: Did a low-retention source shrink, or a high-intent one such as referrals grow?\n      yes: The mix shifted toward sources that always retain better; each source's own rate is flat.\n  - id: onboarding\n    label: Onboarding and activation\n    metric: activation-rate\n    dropped:\n      check: Did fewer new people reach the first key action in their first days?\n      yes: Activation for the same cohorts falls, starting with a release or an onboarding test.\n    spiked:\n      check: Did an onboarding change get more people to the key action?\n      yes: Activation rose for the same cohorts and retention rose with it.\n  - id: reminders\n    label: First-week reminders\n    dropped:\n      check: Did the emails or pushes that bring new people back in their second week stop or get throttled?\n      yes: Returns from reminder opens in days 7 to 14 fall while other returns hold.\n    spiked:\n      check: Did a new reminder for the second week go live?\n      yes: Returns from reminder opens rise; check week 4 retention to see whether they stay.\n\ndiagnose_order: [identity, calendar, platform, acquisition-mix, onboarding, reminders]\n\nrelated: [week-4-retention, activation-rate, onboarding-completion-rate, signups, resurrected-users]\n\nprose:\n  why_it_matters: >-\n    Week 1 retention is the first honest read of whether new people found what they came for, and\n    later weeks usually follow it: a cohort that keeps fewer people in its second week tends to\n    keep fewer for good. Because it is read per arrival cohort, it shows an onboarding or acquisition change within\n    three weeks. A drop from 31% to 27% on 8,500 new people a week is 340 people a week who would\n    otherwise have stayed.\n  pitfalls:\n    - Calendar-week retention, active in the week after the arrival week, gives a Sunday arrival a one-day gap and a Monday arrival seven. This spec measures from each person's own first event.\n    - Cohorts younger than three weeks haven't had their full window yet, and including them shows a false drop. Only mature cohorts are reported.\n    - Counting every first event as a new person includes bots and returning people whose old id wasn't recognised. Fix identity before reading retention.\n    - A low-intent campaign lowers the cohort's retention with no change in the product. Split by source before blaming onboarding.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"week-1-retention","name":"Week 1 retention","aliases":["W1 retention","First-week retention","Week one retention"],"family":"engagement","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of new people who are active again in their second week, between 7 and 14 days after their first event, by the week they arrived.","formula":"People with any event from 7 to 14 days after their first event (days 7–13, hours 168 to 336) ÷ people whose first event fell in the cohort week"},"events":[{"name":"*","description":"Any event a person sends. A person's first ever event places them in a cohort; any later event counts as a return.","also_called":["All events","Any event","Active event"],"properties":[{"name":"$os","description":"The operating system, for splitting by platform."},{"name":"utm_source","description":"The campaign source a person arrived from, for splitting by acquisition channel."}]}],"numerator":{"label":"New people active again 7 to 14 days later","aggregate":"returning_users","event":"*"},"queries":{"hogql":"-- Week 1 retention: of the people whose first event fell in each week, the share with any event 7 to 14 days after it. Cohort weeks 28 to 3 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their window has closed.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(c.retained_people, 0) AS numerator,\n  coalesce(c.people, 0) AS denominator,\n  if(denominator = 0, NULL, numerator / denominator) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(3, 29))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, countIf(retained) AS retained_people, count() AS people\n  FROM (\n    SELECT\n      toMonday(f.first_at) AS week,\n      f.person_id AS person_id,\n      countIf(e.ts >= f.first_at + toIntervalDay(7) AND e.ts < f.first_at + toIntervalDay(14)) > 0 AS retained\n    FROM (\n      SELECT person_id, min(toTimeZone(timestamp, 'UTC')) AS first_at\n      FROM events\n      WHERE person_id IS NOT NULL\n      GROUP BY person_id\n    ) AS f\n    LEFT JOIN (\n      SELECT person_id, toTimeZone(timestamp, 'UTC') AS ts\n      FROM events\n      WHERE person_id IS NOT NULL\n        AND timestamp >= now() - toIntervalWeek(29)\n    ) AS e ON e.person_id = f.person_id\n    WHERE toMonday(f.first_at) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(28) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(3)\n    GROUP BY week, person_id\n  )\n  GROUP BY week\n) AS c ON c.week = w.week\nORDER BY week","postgres":"-- Week 1 retention: of the people whose first event fell in each week, the share with any event 7 to 14 days after it. Cohort weeks 28 to 3 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their window has closed.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '28 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '3 weeks',\n    interval '1 week'\n  ) AS g(week)\n),\nfirsts AS (\n  SELECT user_id, min(occurred_at AT TIME ZONE 'UTC') AS first_at\n  FROM events\n  WHERE user_id IS NOT NULL\n  GROUP BY user_id\n),\ncohort AS (\n  SELECT\n    date_trunc('week', f.first_at)::date AS week,\n    f.user_id,\n    count(e.occurred_at) > 0 AS retained\n  FROM firsts AS f\n  LEFT JOIN events AS e\n    ON e.user_id = f.user_id\n   AND e.occurred_at AT TIME ZONE 'UTC' >= f.first_at + interval '7 days'\n   AND e.occurred_at AT TIME ZONE 'UTC' < f.first_at + interval '14 days'\n  WHERE f.first_at >= date_trunc('week', now() AT TIME ZONE 'UTC') - interval '28 weeks'\n    AND f.first_at < date_trunc('week', now() AT TIME ZONE 'UTC') - interval '2 weeks'\n  GROUP BY 1, 2\n)\nSELECT\n  w.week,\n  count(c.user_id) FILTER (WHERE c.retained) AS numerator,\n  count(c.user_id) AS denominator,\n  (count(c.user_id) FILTER (WHERE c.retained))::numeric / nullif(count(c.user_id), 0) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;","bigquery":"-- Week 1 retention: of the people whose first event fell in each week, the share with any event 7 to 14 days after it. Cohort weeks 28 to 3 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their window has closed.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 28 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 3 WEEK), INTERVAL 1 WEEK)) AS week\n),\nfirsts AS (\n  SELECT user_id, MIN(occurred_at) AS first_at\n  FROM events\n  WHERE user_id IS NOT NULL\n  GROUP BY user_id\n),\ncohort AS (\n  SELECT\n    DATE_TRUNC(DATE(f.first_at), ISOWEEK) AS week,\n    f.user_id,\n    COUNT(e.occurred_at) > 0 AS retained\n  FROM firsts AS f\n  LEFT JOIN events AS e\n    ON e.user_id = f.user_id\n   AND e.occurred_at >= TIMESTAMP_ADD(f.first_at, INTERVAL 7 DAY)\n   AND e.occurred_at < TIMESTAMP_ADD(f.first_at, INTERVAL 14 DAY)\n  WHERE f.first_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 28 WEEK))\n    AND f.first_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 2 WEEK))\n  GROUP BY week, f.user_id\n)\nSELECT\n  w.week,\n  COUNTIF(c.retained) AS numerator,\n  COUNT(c.user_id) AS denominator,\n  SAFE_DIVIDE(COUNTIF(c.retained), COUNT(c.user_id)) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;","snowflake":"-- Week 1 retention: of the people whose first event fell in each week, the share with any event 7 to 14 days after it. Cohort weeks 28 to 3 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their window has closed.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -2 - ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nfirsts AS (\n  SELECT user_id, MIN(occurred_at) AS first_at\n  FROM events\n  WHERE user_id IS NOT NULL\n  GROUP BY user_id\n),\ncohort AS (\n  SELECT\n    DATEADD(day, 1 - DAYOFWEEKISO(f.first_at), f.first_at::date) AS week,\n    f.user_id,\n    COUNT(e.occurred_at) > 0 AS retained\n  FROM firsts AS f\n  LEFT JOIN events AS e\n    ON e.user_id = f.user_id\n   AND e.occurred_at >= DATEADD(day, 7, f.first_at)\n   AND e.occurred_at < DATEADD(day, 14, f.first_at)\n  WHERE f.first_at >= DATEADD(week, -28, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND f.first_at < DATEADD(week, -2, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n  GROUP BY 1, 2\n)\nSELECT\n  w.week,\n  COUNT_IF(c.retained) AS numerator,\n  COUNT(c.user_id) AS denominator,\n  COUNT_IF(c.retained)::float / NULLIF(COUNT(c.user_id), 0) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"new people in the cohort","typical":0.3},"example":{"business":"app","level":0.31,"volume":8500,"trend":0.03},"drivers":[{"id":"identity","label":"Identity and tracking","dropped":{"check":"Did returning people start appearing as new, for example after an SDK, login or identity change?","yes":"New people jump and their retention falls from the same date, with no change in sign-ups."},"spiked":{"check":"Did a tracking change stop counting one-time visitors as new people?","yes":"Cohorts shrink from one date, mostly people with a single event, and retention rises with no product change."}},{"id":"calendar","label":"Calendar","feed":"holidays","dropped":{"check":"Did the cohort's second week fall over a holiday?","yes":"Cohorts whose days 7 to 14 overlap a holiday retain less, and the next cohort recovers."},"spiked":{"check":"Did the cohort arrive in a high-intent season, such as the new year for a budgeting app?","yes":"The same cohorts last year retained better too."}},{"id":"platform","label":"Platform and releases","breakdown":"$os","feed":"app-stores","dropped":{"check":"Did a release break something new people hit in their first days, on one platform?","yes":"Retention falls for cohorts on one platform or app version only."},"spiked":{"check":"Did a release fix a first-week problem on one platform?","yes":"Retention rises for cohorts on that platform from the release date."}},{"id":"acquisition-mix","label":"Where new people came from","breakdown":"utm_source","dropped":{"check":"Did more of the cohort come from a broad or low-intent source, such as a new paid campaign?","yes":"One source grew its share of new people and retains far below the others."},"spiked":{"check":"Did a low-retention source shrink, or a high-intent one such as referrals grow?","yes":"The mix shifted toward sources that always retain better; each source's own rate is flat."}},{"id":"onboarding","label":"Onboarding and activation","metric":"activation-rate","dropped":{"check":"Did fewer new people reach the first key action in their first days?","yes":"Activation for the same cohorts falls, starting with a release or an onboarding test."},"spiked":{"check":"Did an onboarding change get more people to the key action?","yes":"Activation rose for the same cohorts and retention rose with it."}},{"id":"reminders","label":"First-week reminders","dropped":{"check":"Did the emails or pushes that bring new people back in their second week stop or get throttled?","yes":"Returns from reminder opens in days 7 to 14 fall while other returns hold."},"spiked":{"check":"Did a new reminder for the second week go live?","yes":"Returns from reminder opens rise; check week 4 retention to see whether they stay."}}],"diagnose_order":["identity","calendar","platform","acquisition-mix","onboarding","reminders"],"related":["week-4-retention","activation-rate","onboarding-completion-rate","signups","resurrected-users"],"prose":{"why_it_matters":"Week 1 retention is the first honest read of whether new people found what they came for, and later weeks usually follow it: a cohort that keeps fewer people in its second week tends to keep fewer for good. Because it is read per arrival cohort, it shows an onboarding or acquisition change within three weeks. A drop from 31% to 27% on 8,500 new people a week is 340 people a week who would otherwise have stayed.","pitfalls":["Calendar-week retention, active in the week after the arrival week, gives a Sunday arrival a one-day gap and a Monday arrival seven. This spec measures from each person's own first event.","Cohorts younger than three weeks haven't had their full window yet, and including them shows a false drop. Only mature cohorts are reported.","Counting every first event as a new person includes bots and returning people whose old id wasn't recognised. Fix identity before reading retention.","A low-intent campaign lowers the cohort's retention with no change in the product. Split by source before blaming onboarding."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "week-4-retention": { yaml: "id: week-4-retention\nname: Week 4 retention\naliases:\n  - W4 retention\n  - Week four retention\n  - Fourth-week retention\nfamily: engagement\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of new people still active in their fifth week, between 28 and 35 days after their first event, by the week they arrived.\n  formula: People with any event from 28 to 35 days after their first event (days 28–34, hours 672 to 840) ÷ people whose first event fell in the cohort week\n\nevents:\n  - name: \"*\"\n    description: Any event a person sends. A person's first ever event places them in a cohort; any later event counts as a return.\n    also_called: [All events, Any event, Active event]\n    properties:\n      - name: $os\n        description: The operating system, for splitting by platform.\n      - name: utm_source\n        description: The campaign source a person arrived from, for splitting by acquisition channel.\n\nnumerator:\n  label: New people active again 28 to 35 days later\n  aggregate: returning_users\n  event: \"*\"\n\nqueries:\n  hogql: |-\n    -- Week 4 retention: of the people whose first event fell in each week, the share with any event 28 to 35 days after it. Cohort weeks 31 to 6 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their window has closed.\n    -- HogQL: paste into a PostHog SQL insight.\n    SELECT\n      w.week AS week,\n      coalesce(c.retained_people, 0) AS numerator,\n      coalesce(c.people, 0) AS denominator,\n      if(denominator = 0, NULL, numerator / denominator) AS value\n    FROM (\n      SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(6, 32))) AS week\n    ) AS w\n    LEFT JOIN (\n      SELECT week, countIf(retained) AS retained_people, count() AS people\n      FROM (\n        SELECT\n          toMonday(f.first_at) AS week,\n          f.person_id AS person_id,\n          countIf(e.ts >= f.first_at + toIntervalDay(28) AND e.ts < f.first_at + toIntervalDay(35)) > 0 AS retained\n        FROM (\n          SELECT person_id, min(toTimeZone(timestamp, 'UTC')) AS first_at\n          FROM events\n          WHERE person_id IS NOT NULL\n          GROUP BY person_id\n        ) AS f\n        LEFT JOIN (\n          SELECT person_id, toTimeZone(timestamp, 'UTC') AS ts\n          FROM events\n          WHERE person_id IS NOT NULL\n            AND timestamp >= now() - toIntervalWeek(32)\n        ) AS e ON e.person_id = f.person_id\n        WHERE toMonday(f.first_at) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(31) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(6)\n        GROUP BY week, person_id\n      )\n      GROUP BY week\n    ) AS c ON c.week = w.week\n    ORDER BY week\n  postgres: |-\n    -- Week 4 retention: of the people whose first event fell in each week, the share with any event 28 to 35 days after it. Cohort weeks 31 to 6 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their window has closed.\n    -- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\n    WITH weeks AS (\n      SELECT g.week::date AS week\n      FROM generate_series(\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '31 weeks',\n        date_trunc('week', now() AT TIME ZONE 'UTC') - interval '6 weeks',\n        interval '1 week'\n      ) AS g(week)\n    ),\n    firsts AS (\n      SELECT user_id, min(occurred_at AT TIME ZONE 'UTC') AS first_at\n      FROM events\n      WHERE user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    cohort AS (\n      SELECT\n        date_trunc('week', f.first_at)::date AS week,\n        f.user_id,\n        count(e.occurred_at) > 0 AS retained\n      FROM firsts AS f\n      LEFT JOIN events AS e\n        ON e.user_id = f.user_id\n       AND e.occurred_at AT TIME ZONE 'UTC' >= f.first_at + interval '28 days'\n       AND e.occurred_at AT TIME ZONE 'UTC' < f.first_at + interval '35 days'\n      WHERE f.first_at >= date_trunc('week', now() AT TIME ZONE 'UTC') - interval '31 weeks'\n        AND f.first_at < date_trunc('week', now() AT TIME ZONE 'UTC') - interval '5 weeks'\n      GROUP BY 1, 2\n    )\n    SELECT\n      w.week,\n      count(c.user_id) FILTER (WHERE c.retained) AS numerator,\n      count(c.user_id) AS denominator,\n      (count(c.user_id) FILTER (WHERE c.retained))::numeric / nullif(count(c.user_id), 0) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n  bigquery: |-\n    -- Week 4 retention: of the people whose first event fell in each week, the share with any event 28 to 35 days after it. Cohort weeks 31 to 6 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their window has closed.\n    -- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 31 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 6 WEEK), INTERVAL 1 WEEK)) AS week\n    ),\n    firsts AS (\n      SELECT user_id, MIN(occurred_at) AS first_at\n      FROM events\n      WHERE user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    cohort AS (\n      SELECT\n        DATE_TRUNC(DATE(f.first_at), ISOWEEK) AS week,\n        f.user_id,\n        COUNT(e.occurred_at) > 0 AS retained\n      FROM firsts AS f\n      LEFT JOIN events AS e\n        ON e.user_id = f.user_id\n       AND e.occurred_at >= TIMESTAMP_ADD(f.first_at, INTERVAL 28 DAY)\n       AND e.occurred_at < TIMESTAMP_ADD(f.first_at, INTERVAL 35 DAY)\n      WHERE f.first_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 31 WEEK))\n        AND f.first_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 5 WEEK))\n      GROUP BY week, f.user_id\n    )\n    SELECT\n      w.week,\n      COUNTIF(c.retained) AS numerator,\n      COUNT(c.user_id) AS denominator,\n      SAFE_DIVIDE(COUNTIF(c.retained), COUNT(c.user_id)) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n  snowflake: |-\n    -- Week 4 retention: of the people whose first event fell in each week, the share with any event 28 to 35 days after it. Cohort weeks 31 to 6 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their window has closed.\n    -- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\n    WITH weeks AS (\n      SELECT DATEADD(week, -5 - ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    firsts AS (\n      SELECT user_id, MIN(occurred_at) AS first_at\n      FROM events\n      WHERE user_id IS NOT NULL\n      GROUP BY user_id\n    ),\n    cohort AS (\n      SELECT\n        DATEADD(day, 1 - DAYOFWEEKISO(f.first_at), f.first_at::date) AS week,\n        f.user_id,\n        COUNT(e.occurred_at) > 0 AS retained\n      FROM firsts AS f\n      LEFT JOIN events AS e\n        ON e.user_id = f.user_id\n       AND e.occurred_at >= DATEADD(day, 28, f.first_at)\n       AND e.occurred_at < DATEADD(day, 35, f.first_at)\n      WHERE f.first_at >= DATEADD(week, -31, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n        AND f.first_at < DATEADD(week, -5, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n      GROUP BY 1, 2\n    )\n    SELECT\n      w.week,\n      COUNT_IF(c.retained) AS numerator,\n      COUNT(c.user_id) AS denominator,\n      COUNT_IF(c.retained)::float / NULLIF(COUNT(c.user_id), 0) AS value\n    FROM weeks AS w\n    LEFT JOIN cohort AS c ON c.week = w.week\n    GROUP BY w.week\n    ORDER BY w.week;\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: new people in the cohort\n  typical: 0.16\n\nexample:\n  business: app\n  level: 0.16\n  volume: 8200\n  trend: 0.03\n\ndrivers:\n  - id: identity\n    label: Identity and tracking\n    dropped:\n      check: Did returning people start appearing as new, for example after an SDK, login or identity change?\n      yes: New people jump and their retention falls from the same date, with no change in sign-ups.\n    spiked:\n      check: Did a tracking change stop counting one-time visitors as new people?\n      yes: Cohorts shrink from one date, mostly people with a single event, and retention rises with no product change.\n  - id: calendar\n    label: Calendar\n    feed: holidays\n    dropped:\n      check: Did the cohort's fifth week fall over a holiday?\n      yes: Cohorts whose days 28 to 35 overlap a holiday retain less, and the next cohort recovers.\n    spiked:\n      check: Did the cohort arrive in a high-intent season, such as the new year for a budgeting app?\n      yes: The same cohorts last year retained better too.\n  - id: week-1\n    label: Week 1 retention of the same cohorts\n    metric: week-1-retention\n    dropped:\n      check: Did the same cohorts already retain worse in their second week?\n      yes: Week 1 retention fell for the same cohorts by a similar share, so the cause is in the first days.\n    spiked:\n      check: Did the same cohorts already retain better in their second week?\n      yes: Week 1 retention rose for the same cohorts, and the gain carried through.\n  - id: acquisition-mix\n    label: Where new people came from\n    breakdown: utm_source\n    dropped:\n      check: Did more of the cohort come from a broad or low-intent source?\n      yes: One source grew its share of new people and retains far below the others by week 4.\n    spiked:\n      check: Did a high-intent source such as referrals grow its share?\n      yes: The mix shifted toward sources that always retain better; each source's own rate is flat.\n  - id: platform\n    label: Platform and releases\n    breakdown: $os\n    feed: app-stores\n    dropped:\n      check: Did a release in the cohort's first month break something on one platform?\n      yes: Retention falls for cohorts on one platform or app version only.\n    spiked:\n      check: Did a release improve the product on one platform during the cohort's first month?\n      yes: Retention rises for cohorts on that platform from the release date.\n  - id: habit-feature\n    label: The feature that keeps people\n    metric: feature-adoption-rate\n    dropped:\n      check: Did fewer of the cohort adopt the feature that long-term users rely on?\n      yes: Adoption of that feature in the cohort's first weeks fell before week 4 retention did.\n    spiked:\n      check: Did more of the cohort adopt that feature early, for example after it moved into onboarding?\n      yes: Early adoption rose for the same cohorts and week 4 retention followed.\n\ndiagnose_order: [identity, calendar, week-1, acquisition-mix, platform, habit-feature]\n\nrelated: [week-1-retention, stickiness, activation-rate, mau, customer-lifetime-value]\n\nprose:\n  why_it_matters: >-\n    Week 4 retention shows who is left once the novelty wears off: people still active a month\n    after arriving are the ones a product tends to keep for months. If a product's retention curve\n    flattens, it has usually started to by now, so this is a first estimate of the share it keeps.\n    It is slow by nature, because a cohort's week 4 is known only six weeks after it starts arriving.\n  pitfalls:\n    - Week 4 here means 28 to 35 days after each person's own first event. Tools that use calendar weeks or day 30 report different numbers, so compare like with like.\n    - Cohorts younger than six weeks haven't had their full window yet, and reading them early shows a drop that isn't there. Only mature cohorts are reported.\n    - Any event counts as active, so a push notification received in week 4 can count as retained. Count only events a person chooses to send.\n    - A strong acquisition month can lower the rate by adding casual users while the number of people retained rises. Read the retained count beside the rate.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"week-4-retention","name":"Week 4 retention","aliases":["W4 retention","Week four retention","Fourth-week retention"],"family":"engagement","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of new people still active in their fifth week, between 28 and 35 days after their first event, by the week they arrived.","formula":"People with any event from 28 to 35 days after their first event (days 28–34, hours 672 to 840) ÷ people whose first event fell in the cohort week"},"events":[{"name":"*","description":"Any event a person sends. A person's first ever event places them in a cohort; any later event counts as a return.","also_called":["All events","Any event","Active event"],"properties":[{"name":"$os","description":"The operating system, for splitting by platform."},{"name":"utm_source","description":"The campaign source a person arrived from, for splitting by acquisition channel."}]}],"numerator":{"label":"New people active again 28 to 35 days later","aggregate":"returning_users","event":"*"},"queries":{"hogql":"-- Week 4 retention: of the people whose first event fell in each week, the share with any event 28 to 35 days after it. Cohort weeks 31 to 6 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their window has closed.\n-- HogQL: paste into a PostHog SQL insight.\nSELECT\n  w.week AS week,\n  coalesce(c.retained_people, 0) AS numerator,\n  coalesce(c.people, 0) AS denominator,\n  if(denominator = 0, NULL, numerator / denominator) AS value\nFROM (\n  SELECT toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(arrayJoin(range(6, 32))) AS week\n) AS w\nLEFT JOIN (\n  SELECT week, countIf(retained) AS retained_people, count() AS people\n  FROM (\n    SELECT\n      toMonday(f.first_at) AS week,\n      f.person_id AS person_id,\n      countIf(e.ts >= f.first_at + toIntervalDay(28) AND e.ts < f.first_at + toIntervalDay(35)) > 0 AS retained\n    FROM (\n      SELECT person_id, min(toTimeZone(timestamp, 'UTC')) AS first_at\n      FROM events\n      WHERE person_id IS NOT NULL\n      GROUP BY person_id\n    ) AS f\n    LEFT JOIN (\n      SELECT person_id, toTimeZone(timestamp, 'UTC') AS ts\n      FROM events\n      WHERE person_id IS NOT NULL\n        AND timestamp >= now() - toIntervalWeek(32)\n    ) AS e ON e.person_id = f.person_id\n    WHERE toMonday(f.first_at) BETWEEN toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(31) AND toMonday(toTimeZone(now(), 'UTC')) - toIntervalWeek(6)\n    GROUP BY week, person_id\n  )\n  GROUP BY week\n) AS c ON c.week = w.week\nORDER BY week","postgres":"-- Week 4 retention: of the people whose first event fell in each week, the share with any event 28 to 35 days after it. Cohort weeks 31 to 6 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their window has closed.\n-- Postgres. Reads events(event_name text, occurred_at timestamptz, user_id text, session_id text, properties jsonb). Weeks are cut in UTC whatever the session time zone.\nWITH weeks AS (\n  SELECT g.week::date AS week\n  FROM generate_series(\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '31 weeks',\n    date_trunc('week', now() AT TIME ZONE 'UTC') - interval '6 weeks',\n    interval '1 week'\n  ) AS g(week)\n),\nfirsts AS (\n  SELECT user_id, min(occurred_at AT TIME ZONE 'UTC') AS first_at\n  FROM events\n  WHERE user_id IS NOT NULL\n  GROUP BY user_id\n),\ncohort AS (\n  SELECT\n    date_trunc('week', f.first_at)::date AS week,\n    f.user_id,\n    count(e.occurred_at) > 0 AS retained\n  FROM firsts AS f\n  LEFT JOIN events AS e\n    ON e.user_id = f.user_id\n   AND e.occurred_at AT TIME ZONE 'UTC' >= f.first_at + interval '28 days'\n   AND e.occurred_at AT TIME ZONE 'UTC' < f.first_at + interval '35 days'\n  WHERE f.first_at >= date_trunc('week', now() AT TIME ZONE 'UTC') - interval '31 weeks'\n    AND f.first_at < date_trunc('week', now() AT TIME ZONE 'UTC') - interval '5 weeks'\n  GROUP BY 1, 2\n)\nSELECT\n  w.week,\n  count(c.user_id) FILTER (WHERE c.retained) AS numerator,\n  count(c.user_id) AS denominator,\n  (count(c.user_id) FILTER (WHERE c.retained))::numeric / nullif(count(c.user_id), 0) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;","bigquery":"-- Week 4 retention: of the people whose first event fell in each week, the share with any event 28 to 35 days after it. Cohort weeks 31 to 6 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their window has closed.\n-- BigQuery. Reads events(event_name STRING, occurred_at TIMESTAMP, user_id STRING, session_id STRING, properties JSON). Weeks are cut in UTC.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 31 WEEK), DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 6 WEEK), INTERVAL 1 WEEK)) AS week\n),\nfirsts AS (\n  SELECT user_id, MIN(occurred_at) AS first_at\n  FROM events\n  WHERE user_id IS NOT NULL\n  GROUP BY user_id\n),\ncohort AS (\n  SELECT\n    DATE_TRUNC(DATE(f.first_at), ISOWEEK) AS week,\n    f.user_id,\n    COUNT(e.occurred_at) > 0 AS retained\n  FROM firsts AS f\n  LEFT JOIN events AS e\n    ON e.user_id = f.user_id\n   AND e.occurred_at >= TIMESTAMP_ADD(f.first_at, INTERVAL 28 DAY)\n   AND e.occurred_at < TIMESTAMP_ADD(f.first_at, INTERVAL 35 DAY)\n  WHERE f.first_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 31 WEEK))\n    AND f.first_at < TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 5 WEEK))\n  GROUP BY week, f.user_id\n)\nSELECT\n  w.week,\n  COUNTIF(c.retained) AS numerator,\n  COUNT(c.user_id) AS denominator,\n  SAFE_DIVIDE(COUNTIF(c.retained), COUNT(c.user_id)) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;","snowflake":"-- Week 4 retention: of the people whose first event fell in each week, the share with any event 28 to 35 days after it. Cohort weeks 31 to 6 weeks before this one (Monday 00:00 UTC), oldest first; younger cohorts are left out until their window has closed.\n-- Snowflake. Reads events(event_name VARCHAR, occurred_at TIMESTAMP_NTZ in UTC, user_id VARCHAR, session_id VARCHAR, properties VARIANT). Weeks start Monday whatever WEEK_START is set to.\nWITH weeks AS (\n  SELECT DATEADD(week, -5 - ROW_NUMBER() OVER (ORDER BY SEQ4()), DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date)) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nfirsts AS (\n  SELECT user_id, MIN(occurred_at) AS first_at\n  FROM events\n  WHERE user_id IS NOT NULL\n  GROUP BY user_id\n),\ncohort AS (\n  SELECT\n    DATEADD(day, 1 - DAYOFWEEKISO(f.first_at), f.first_at::date) AS week,\n    f.user_id,\n    COUNT(e.occurred_at) > 0 AS retained\n  FROM firsts AS f\n  LEFT JOIN events AS e\n    ON e.user_id = f.user_id\n   AND e.occurred_at >= DATEADD(day, 28, f.first_at)\n   AND e.occurred_at < DATEADD(day, 35, f.first_at)\n  WHERE f.first_at >= DATEADD(week, -31, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n    AND f.first_at < DATEADD(week, -5, DATEADD(day, 1 - DAYOFWEEKISO(SYSDATE()), SYSDATE()::date))\n  GROUP BY 1, 2\n)\nSELECT\n  w.week,\n  COUNT_IF(c.retained) AS numerator,\n  COUNT(c.user_id) AS denominator,\n  COUNT_IF(c.retained)::float / NULLIF(COUNT(c.user_id), 0) AS value\nFROM weeks AS w\nLEFT JOIN cohort AS c ON c.week = w.week\nGROUP BY w.week\nORDER BY w.week;"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"new people in the cohort","typical":0.16},"example":{"business":"app","level":0.16,"volume":8200,"trend":0.03},"drivers":[{"id":"identity","label":"Identity and tracking","dropped":{"check":"Did returning people start appearing as new, for example after an SDK, login or identity change?","yes":"New people jump and their retention falls from the same date, with no change in sign-ups."},"spiked":{"check":"Did a tracking change stop counting one-time visitors as new people?","yes":"Cohorts shrink from one date, mostly people with a single event, and retention rises with no product change."}},{"id":"calendar","label":"Calendar","feed":"holidays","dropped":{"check":"Did the cohort's fifth week fall over a holiday?","yes":"Cohorts whose days 28 to 35 overlap a holiday retain less, and the next cohort recovers."},"spiked":{"check":"Did the cohort arrive in a high-intent season, such as the new year for a budgeting app?","yes":"The same cohorts last year retained better too."}},{"id":"week-1","label":"Week 1 retention of the same cohorts","metric":"week-1-retention","dropped":{"check":"Did the same cohorts already retain worse in their second week?","yes":"Week 1 retention fell for the same cohorts by a similar share, so the cause is in the first days."},"spiked":{"check":"Did the same cohorts already retain better in their second week?","yes":"Week 1 retention rose for the same cohorts, and the gain carried through."}},{"id":"acquisition-mix","label":"Where new people came from","breakdown":"utm_source","dropped":{"check":"Did more of the cohort come from a broad or low-intent source?","yes":"One source grew its share of new people and retains far below the others by week 4."},"spiked":{"check":"Did a high-intent source such as referrals grow its share?","yes":"The mix shifted toward sources that always retain better; each source's own rate is flat."}},{"id":"platform","label":"Platform and releases","breakdown":"$os","feed":"app-stores","dropped":{"check":"Did a release in the cohort's first month break something on one platform?","yes":"Retention falls for cohorts on one platform or app version only."},"spiked":{"check":"Did a release improve the product on one platform during the cohort's first month?","yes":"Retention rises for cohorts on that platform from the release date."}},{"id":"habit-feature","label":"The feature that keeps people","metric":"feature-adoption-rate","dropped":{"check":"Did fewer of the cohort adopt the feature that long-term users rely on?","yes":"Adoption of that feature in the cohort's first weeks fell before week 4 retention did."},"spiked":{"check":"Did more of the cohort adopt that feature early, for example after it moved into onboarding?","yes":"Early adoption rose for the same cohorts and week 4 retention followed."}}],"diagnose_order":["identity","calendar","week-1","acquisition-mix","platform","habit-feature"],"related":["week-1-retention","stickiness","activation-rate","mau","customer-lifetime-value"],"prose":{"why_it_matters":"Week 4 retention shows who is left once the novelty wears off: people still active a month after arriving are the ones a product tends to keep for months. If a product's retention curve flattens, it has usually started to by now, so this is a first estimate of the share it keeps. It is slow by nature, because a cohort's week 4 is known only six weeks after it starts arriving.","pitfalls":["Week 4 here means 28 to 35 days after each person's own first event. Tools that use calendar weeks or day 30 report different numbers, so compare like with like.","Cohorts younger than six weeks haven't had their full window yet, and reading them early shows a drop that isn't there. Only mature cohorts are reported.","Any event counts as active, so a push notification received in week 4 can count as retained. Count only events a person chooses to send.","A strong acquisition month can lower the rate by adding casual users while the number of people retained rises. Read the retained count beside the rate."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
}
